  // =========================
  // Build Queue live state
  // =========================
  const BUILDQ = {
    active: {
      finishTime: 0,
      totalSeconds: 0,
    },
  };

  const RESEARCHQ = {
    active: {
      finishTime: 0,
      totalSeconds: 0,
    },
  };

  const SHIPYARDQ = {
    active: {
      finishTime: 0,
      totalSeconds: 0,
    },
  };

  const DEFENSEQ = {
    active: {
      finishTime: 0,
      totalSeconds: 0,
    },
  };

  function _hasLiveCountdownAt() {
    const now = getTimerServerNow();
    for (const el of queryTimerElements()) {
      syncTimerElement(el);
      if (timerRemainingSeconds(el, now) > 0) return true;
    }
    const previewArrival = document.querySelector("[data-preview-arrival][data-countdown-at]");
    if (previewArrival) {
      syncTimerElement(previewArrival);
      if (timerRemainingSeconds(previewArrival, now) > 0) return true;
    }
    return false;
  }

  function _hasStaleMovementCountdown() {
    const now = getTimerServerNow();
    for (const el of queryTimerElements()) {
      syncTimerElement(el);
      const scope = el.dataset.countdownScope || "";
      const kind = el.dataset.timerKind || inferTimerKind(el);
      if (scope !== "fleet" && scope !== "overview" && kind !== "fleet") continue;
      if (Number(el.dataset.timerTarget || el.dataset.countdownAt || 0) && timerRemainingSeconds(el, now) <= 0) {
        return true;
      }
    }
    return false;
  }

  function _hasVisibleOverviewResearchTimer() {
    const box = document.getElementById("overview-research-active");
    if (!box || box.hidden || box.style.display === "none") return false;
    const finishAt = parseTimerTarget(box.dataset.finishAt || 0);
    if (!finishAt) return false;
    const srvRem = box.dataset.serverRemaining;
    return queueJobRemainingSeconds(
      finishAt,
      getTimerServerNow(),
      srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
    ) > 0;
  }

  function _hasSafetyCountdownTimers() {
    const now = Math.floor(getTimerServerNow());
    const safety = GC.lastState?.account_safety;
    if (safety && typeof safety === "object") {
      if (safety.vacation_active && Number(safety.vacation_locked_until || 0) > now) return true;
      if (safety.deletion_pending && Number(safety.deletion_due_at || 0) > now) return true;
    }
    const fleetVacTimer = document.querySelector("[data-fleet-vacation-timer]");
    if (fleetVacTimer && !fleetVacTimer.hidden && Number(fleetVacTimer.getAttribute("data-until") || 0) > now) {
      return true;
    }
    const vacTimer = document.getElementById("options-vacation-timer");
    if (vacTimer && !vacTimer.hidden && Number(vacTimer.getAttribute("data-until") || 0) > now) return true;
    const delTimer = document.getElementById("options-deletion-timer");
    if (delTimer && !delTimer.hidden && Number(delTimer.getAttribute("data-until") || 0) > now) return true;
    return false;
  }

  function updateSafetyCountdownTimers() {
    const safety = GC.lastState?.account_safety;
    syncFleetVacationNotice(safety || {});
    syncHeaderVacationBanner(safety || {});
    if (typeof GC.syncSafetyCountdownTimers === "function") {
      GC.syncSafetyCountdownTimers(safety || {});
    }
  }

  function _hasStaleActiveCardQueue() {
    const now = getTimerServerNow();
    let stale = false;
    document.querySelectorAll("[data-gc-card-queue][data-queue-active='1']").forEach((block) => {
      const finish = parseTimerTarget(block.dataset.finishAt || 0);
      if (finish > 0 && finish <= now) stale = true;
    });
    document.querySelectorAll(".build-job.build-job-active[data-finish-time]").forEach((job) => {
      const finish = parseTimerTarget(job.getAttribute("data-finish-time") || 0);
      if (finish > 0 && finish <= now) stale = true;
    });
    document.querySelectorAll(".research-job.research-job-active[data-finish-time]").forEach((job) => {
      const finish = parseTimerTarget(job.getAttribute("data-finish-time") || 0);
      if (finish > 0 && finish <= now) stale = true;
    });
    return stale;
  }

  function _hasActiveProgressJobs() {
    const now = getTimerServerNow();
    const buildFinish = BUILDQ.active.finishTime > now;
    const researchFinish = RESEARCHQ.active.finishTime > now;
    const shipyardFinish = SHIPYARDQ.active.finishTime > now;
    const defenseFinish = DEFENSEQ.active.finishTime > now;
    const activeFleetCount = normalizeActiveFleetsPayload(GC.lastState?.active_fleets).count;
    return (
      buildFinish ||
      researchFinish ||
      shipyardFinish ||
      defenseFinish ||
      activeFleetCount > 0 ||
      (GC.lastState?.fleet_alerts?.has_incoming_attack === true) ||
      _hasSafetyCountdownTimers() ||
      !!document.querySelector(".build-job.build-job-active") ||
      !!document.querySelector(".research-job.research-job-active") ||
      !!document.querySelector(".shipyard-job.shipyard-job-active") ||
      !!document.querySelector("[data-fleet-drawer-row]") ||
      _hasVisibleOverviewResearchTimer() ||
      !!document.querySelector(".planet-evolution-page .gc-card-queue-block[data-gc-card-queue='1']") ||
      !!document.querySelector(".gc-mini-queue-card--active[data-finish-at]") ||
      _hasLiveCountdownAt() ||
      _hasStaleActiveCardQueue()
    );
  }

  function _maybeRefreshStaleMovementCountdowns() {
    if (!shouldRunGameLoop() || _authLoopAborted) return;
    if (!_anyStaleMovementCountdownDom()) return;
    if (_movementCountdownRefreshPending.fleet) requestMovementCountdownRefresh("fleet");
    else requestMovementCountdownRefresh("overview");
  }

  // progress ticker: GC.startProgressTicker / GC.stopProgressTicker

  // =========================
  // Build-Queue panel render
  // - minimal re-render via signature
  // - BUT live progress runs independently
  // =========================
  let _lastQueueSignature = "";

  function _queueSignature(queueList, summary, planetId) {
    try {
      const pid = Number(planetId || 0);
      const count = summary?.count ?? (queueList?.length ?? 0);
      const items = (queueList || [])
        .map((j) => `${j.id || j.building_type}:${j.target_level}:${j.finish_time || 0}`)
        .join("|");
      return `${pid}|${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _collectBuildQueueCardJobs(buildQueueRaw) {
    const byOwner = buildQueueRaw?.card_jobs_by_owner;
    if (byOwner && typeof byOwner === "object") {
      const jobs = [];
      Object.values(byOwner).forEach((rows) => {
        if (Array.isArray(rows)) rows.forEach((j) => jobs.push(j));
      });
      jobs.sort((a, b) => (Number(a.queue_position) || 0) - (Number(b.queue_position) || 0));
      if (jobs.length) return jobs;
    }
    const queueList = Array.isArray(buildQueueRaw?.queue)
      ? buildQueueRaw.queue
      : Array.isArray(buildQueueRaw)
        ? buildQueueRaw
        : [];
    return queueList.map((raw, idx) => {
      const finishAt = resolveQueueJobFinishTime(raw);
      const total = Math.max(1, Math.floor(Number(raw.total || raw.total_seconds || 1)));
      const remainingRaw = resolveQueueJobRemaining(raw);
      const remaining = Number.isFinite(remainingRaw)
        ? Math.max(0, Math.floor(remainingRaw))
        : Math.max(0, Math.floor(Number(raw.remaining_seconds ?? raw.remaining ?? 0)));
      const isActive = idx === 0;
      const elapsed = isActive ? Math.max(0, total - remaining) : 0;
      const progressPct = isActive ? Math.max(0, Math.min(100, Math.round((100 * elapsed) / total))) : 0;
      const ownerKey = String(raw.building_type || "");
      return {
        owner_type: "building",
        owner_key: ownerKey,
        job_id: Math.floor(Number(raw.id || 0)),
        status: isActive ? "active" : "queued",
        queue_position: idx + 1,
        finish_at: finishAt,
        duration_seconds: total,
        remaining_seconds: remaining,
        target_level: Math.floor(Number(raw.target_level || 0)),
        label_key: String(raw.label_key || raw.label || `building_${ownerKey}`),
        progress_pct: progressPct,
      };
    });
  }

  function _buildQueueCompactSignature(buildQueueRaw) {
    try {
      const jobs = _collectBuildQueueCardJobs(buildQueueRaw);
      const count = buildQueueRaw?.summary?.count ?? jobs.length;
      const pid = Number(buildQueueRaw?.planet_id || 0);
      const items = jobs
        .map((j) => cardQueueJobSignature(j))
        .join("|");
      return `${pid}|${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _globalQueueHudDomain(job) {
    return _cardQueueDomain(job);
  }

  function _globalQueueHudNavPath(job) {
    const domain = _globalQueueHudDomain(job);
    if (domain === "research") return "/research";
    if (domain === "shipyard") return "/shipyard";
    if (domain === "defense") return "/defense";
    return "/buildings";
  }

  function _globalQueueHudGlyph(job) {
    const domain = _globalQueueHudDomain(job);
    if (domain === "research") return "🔬";
    if (domain === "shipyard") return "🚀";
    if (domain === "defense") return "🛡";
    return "🏗";
  }

  function _globalQueueHudLabel(job) {
    const domain = _globalQueueHudDomain(job);
    const ownerKey = String(job.owner_key || "");
    if (domain === "shipyard" || domain === "defense") {
      const amount = Math.floor(Number(job.target_amount || 0));
      const itemLabel =
        domain === "defense"
          ? t(job.defense_label_key || `defense_${ownerKey}`, defenseDisplayName(ownerKey))
          : t(job.ship_label_key || `fleet_ship_${ownerKey}`, shipDisplayName(ownerKey));
      return amount > 1 ? `${itemLabel} ×${fmtNumber(amount)}` : itemLabel;
    }
    return _resolveQueueJobDisplayName(job, domain);
  }

  function _globalQueueHudSignature(payload) {
    try {
      const jobs = Array.isArray(payload?.jobs) ? payload.jobs : [];
      const pid = Number(payload?.planet_id || 0);
      return `${pid}|${jobs.map((j) => cardQueueJobSignature(j)).join("|")}`;
    } catch (_) {
      return "";
    }
  }

  function _globalQueueHudPayloadFromState(data) {
    if (data?.global_queue_hud && typeof data.global_queue_hud === "object") {
      return data.global_queue_hud;
    }
    const jobs = [];
    const buildJobs = _collectBuildQueueCardJobs(data?.build_queue);
    buildJobs.forEach((j) => {
      const pos = Number(j.queue_position || 0);
      if (pos === 1 || pos === 2) jobs.push(j);
    });
    const researchJobs = _collectResearchQueueCardJobs(data?.research);
    const activeResearch = researchJobs.find((j) => String(j.status || "") === "active");
    if (activeResearch) jobs.push(activeResearch);
    return {
      jobs,
      planet_id: Number(data?.active_planet_id || data?.build_queue?.planet_id || 0),
      planet_name: String(data?.active_planet_name || ""),
    };
  }

  function _researchQueueIconByKey(researchRaw) {
    const iconByKey = new Map();
    const queueList = Array.isArray(researchRaw?.queue) ? researchRaw.queue : [];
    queueList.forEach((raw) => {
      const k = String(raw?.tech_key || raw?.key || "").trim();
      const icon = String(raw?.icon || "").trim();
      if (k && icon) iconByKey.set(k, icon);
    });
    const techs = Array.isArray(researchRaw?.techs) ? researchRaw.techs : [];
    techs.forEach((row) => {
      const k = String(row?.key || row?.tech_key || "").trim();
      const icon = String(row?.icon || "").trim();
      if (k && icon && !iconByKey.has(k)) iconByKey.set(k, icon);
    });
    return iconByKey;
  }

  function _collectResearchQueueCardJobs(researchRaw) {
    const iconByKey = _researchQueueIconByKey(researchRaw);
    const attachIcon = (job) => {
      if (!job || typeof job !== "object") return job;
      if (job.icon) return job;
      const k = String(job.owner_key || "");
      const icon = iconByKey.get(k);
      return icon ? { ...job, icon } : job;
    };
    const byOwner = researchRaw?.card_jobs_by_owner;
    if (byOwner && typeof byOwner === "object") {
      const jobs = [];
      Object.values(byOwner).forEach((rows) => {
        if (Array.isArray(rows)) rows.forEach((j) => jobs.push(attachIcon(j)));
      });
      jobs.sort((a, b) => (Number(a.queue_position) || 0) - (Number(b.queue_position) || 0));
      return jobs;
    }
    const queueList = Array.isArray(researchRaw?.queue) ? researchRaw.queue : [];
    return queueList.map((raw, idx) => {
      const ownerKey = String(raw.tech_key || raw.key || "");
      return {
        owner_type: "research",
        owner_key: ownerKey,
        job_id: raw.id,
        status: idx === 0 ? "active" : "queued",
        queue_position: idx + 1,
        finish_at: resolveQueueJobFinishTime(raw),
        remaining_seconds: resolveQueueJobRemaining(raw),
        target_level: raw.target_level,
        label_key: raw.label_key || ownerKey,
        label: raw.label,
        icon: raw.icon || iconByKey.get(ownerKey),
      };
    });
  }

  function _globalQueueHudDomainTitle(job) {
    const domain = _globalQueueHudDomain(job);
    if (domain === "research") return t("nav_research", "Forschung");
    if (domain === "shipyard") return t("location_action_shipyard", "Orbitalwerft");
    if (domain === "defense") return t("nav_defense", "Verteidigung");
    return t("nav_buildings", "Gebäude");
  }

  function _globalQueueHudSubtitle(job) {
    const domain = _globalQueueHudDomain(job);
    const isActive = String(job.status || "") === "active";
    const targetLevel = Math.floor(Number(job.target_level || 0));
    const position = Math.max(1, Math.floor(Number(job.queue_position || 1)));

    if (domain === "shipyard" || domain === "defense") {
      const prefix = tf("global_queue_hud_next_job", {}, "Nächster Auftrag:");
      return `${prefix} ${_globalQueueHudLabel(job)}`;
    }
    if (targetLevel > 0) {
      return tf("build_queue_compact_level", { level: targetLevel }, `Level ${targetLevel}`);
    }
    if (!isActive && domain === "building") {
      return tf("queue_card_status_queued", { n: position }, `Queue #${position}`);
    }
    return _globalQueueHudLabel(job);
  }

  function _syncGlobalQueueHudRowVisibility() {
    const row = document.getElementById("gc-header-row-queues");
    if (!row) return;
    const hud = document.querySelector("[data-global-queue-hud]");
    const fleet = document.querySelector("[data-fleet-global-hud]");
    const queueVisible = hud && !hud.hidden && !hud.classList.contains("is-empty");
    const fleetVisible = fleet && !fleet.hidden && !fleet.classList.contains("is-empty");
    row.hidden = !queueVisible && !fleetVisible;
  }

  function _createGlobalQueueHudRow(job) {
    if (!job || typeof job !== "object") return null;
    const domain = _globalQueueHudDomain(job);
    const isActive = String(job.status || "") === "active";
    const jobId = Math.floor(Number(job.job_id || 0));
    const finishAt = Math.floor(Number(job.finish_at || 0));
    const totalSeconds = Math.max(1, Math.floor(Number(job.duration_seconds || 1)));
    const remaining = Math.max(0, Math.floor(Number(job.remaining_seconds || 0)));
    const progressPct = Math.max(0, Math.min(100, Math.floor(Number(job.progress_pct || 0))));

    const chip = document.createElement("article");
    chip.className = `gc-global-queue-hud-chip gc-global-queue-hud-chip--${domain}${isActive ? " is-active" : " is-queued"}`;
    chip.dataset.globalQueueHudChip = "1";
    chip.dataset.globalQueueHudRow = "1";
    chip.dataset.navPath = _globalQueueHudNavPath(job);

    const wrap = document.createElement("div");
    wrap.className = "gc-global-queue-hud-item";
    wrap.dataset.gcCardQueue = "1";
    wrap.dataset.queueActive = isActive ? "1" : "0";
    wrap.dataset.timerDomain = domain;
    wrap.dataset.queuePosition = String(Math.max(1, Math.floor(Number(job.queue_position || 1))));
    wrap.dataset.queueSig = cardQueueJobSignature(job);
    if (jobId > 0) wrap.dataset.jobId = String(jobId);
    if (finishAt > 0) wrap.dataset.finishAt = String(finishAt);
    wrap.dataset.totalSeconds = String(totalSeconds);
    if (Number.isFinite(remaining)) {
      assignMonotonicServerRemaining(wrap, remaining, finishAt);
    }
    wrap.appendChild(chip);

    const head = document.createElement("div");
    head.className = "gc-global-queue-hud-chip-head";
    const glyph = document.createElement("span");
    glyph.className = "gc-global-queue-hud-glyph";
    glyph.setAttribute("aria-hidden", "true");
    glyph.textContent = _globalQueueHudGlyph(job);
    head.appendChild(glyph);
    const domainEl = document.createElement("span");
    domainEl.className = "gc-global-queue-hud-chip-domain";
    domainEl.textContent = _globalQueueHudDomainTitle(job);
    head.appendChild(domainEl);
    chip.appendChild(head);

    const titleEl = document.createElement("div");
    titleEl.className = "gc-global-queue-hud-chip-title";
    if (domain === "shipyard" || domain === "defense") {
      titleEl.textContent = _globalQueueHudDomainTitle(job);
    } else {
      titleEl.textContent = _globalQueueHudLabel(job);
    }
    chip.appendChild(titleEl);

    if (isActive) {
      const bar = document.createElement("div");
      bar.className = "gc-card-queue-bar gc-global-queue-hud-bar";
      bar.setAttribute("role", "progressbar");
      bar.setAttribute("aria-valuemin", "0");
      bar.setAttribute("aria-valuemax", "100");
      bar.setAttribute("aria-valuenow", String(progressPct));
      const fill = document.createElement("div");
      fill.className = "gc-card-queue-bar-fill gc-progress-smooth";
      fill.style.width = `${progressPct}%`;
      bar.appendChild(fill);
      chip.appendChild(bar);
    }

    const subtitleEl = document.createElement("div");
    subtitleEl.className = "gc-global-queue-hud-chip-subtitle";
    subtitleEl.textContent = _globalQueueHudSubtitle(job);
    chip.appendChild(subtitleEl);

    const foot = document.createElement("div");
    foot.className = "gc-global-queue-hud-chip-foot";

    const timerEl = document.createElement("span");
    timerEl.className = "gc-card-queue-timer gc-global-queue-hud-timer gc-mono";
    const waitTarget = cardQueueTimerTarget(job, isActive);
    const timerKind =
      domain === "research"
        ? "research"
        : domain === "shipyard"
          ? "shipyard"
          : domain === "defense"
            ? "defense"
            : "build";
    if (waitTarget > 0) {
      const displayRemaining = queueJobRemainingSeconds(
        waitTarget,
        getTimerServerNow(),
        resolveQueueJobRemaining(job)
      );
      applyQueueJobTimerAttrs(timerEl, waitTarget, timerKind, "game-state", displayRemaining);
      timerEl.textContent = formatEta(queueTimerDisplaySeconds(displayRemaining));
    } else if (!isActive) {
      timerEl.textContent = formatEta(Math.max(0, Math.floor(Number(job.remaining_seconds || 0))));
    }
    foot.appendChild(timerEl);

    if (jobId > 0) {
      const cancelBtn = document.createElement("button");
      cancelBtn.type = "button";
      cancelBtn.className = "gc-global-queue-hud-cancel gc-btn gc-btn-ghost gc-btn-xs";
      cancelBtn.setAttribute("aria-label", t("action_cancel", "Abbrechen"));
      cancelBtn.title = t("action_cancel", "Abbrechen");
      cancelBtn.textContent = "✕";
      if (domain === "research") cancelBtn.dataset.researchCancelId = String(jobId);
      else if (domain === "shipyard") cancelBtn.dataset.shipyardQueueCancel = String(jobId);
      else if (domain === "defense") cancelBtn.dataset.defenseQueueCancel = String(jobId);
      else cancelBtn.dataset.buildCancelId = String(jobId);
      foot.appendChild(cancelBtn);
    }
    chip.appendChild(foot);

    return wrap;
  }

  function _syncGlobalQueueHudLiveState(jobs) {
    const buildJobs = (jobs || []).filter((j) => _globalQueueHudDomain(j) === "building");
    _syncBuildQueueLiveState(
      buildJobs.map((j) => ({
        id: j.job_id,
        building_type: j.owner_key,
        finish_time: j.finish_at,
        total: j.duration_seconds,
        remaining: j.remaining_seconds,
        remaining_seconds: j.remaining_seconds,
      }))
    );
    const researchJobs = (jobs || []).filter((j) => _globalQueueHudDomain(j) === "research");
    if (researchJobs.length) _syncResearchQueueLiveState(researchJobs);
    const shipJobs = (jobs || []).filter((j) => _globalQueueHudDomain(j) === "shipyard");
    if (shipJobs.length) _syncShipyardQueueLiveState(shipJobs);
    const defJobs = (jobs || []).filter((j) => _globalQueueHudDomain(j) === "defense");
    if (defJobs.length) _syncDefenseQueueLiveState(defJobs);
  }

  function _renderGlobalQueueHud(payload) {
    const hud = document.querySelector("[data-global-queue-hud]");
    if (!hud) return;

    const bodyEl = hud.querySelector("[data-global-queue-hud-body]");
    if (!bodyEl) return;

    const allJobs = Array.isArray(payload?.jobs) ? payload.jobs : [];
    const jobs = allJobs;
    const planetId = Number(payload?.planet_id || 0);
    if (planetId > 0) hud.dataset.planetId = String(planetId);

    _syncGlobalQueueHudLiveState(allJobs);

    if (!jobs.length) {
      hud.classList.add("is-empty");
      hud.hidden = true;
      delete bodyEl.dataset.hudSig;
      bodyEl.replaceChildren();
      _syncGlobalQueueHudRowVisibility();
      return;
    }

    hud.classList.remove("is-empty");
    hud.hidden = false;

    const sig = _globalQueueHudSignature({ ...payload, jobs });
    if (sig === bodyEl.dataset.hudSig) {
      _syncGlobalQueueHudRowVisibility();
      return;
    }
    bodyEl.dataset.hudSig = sig;
    bodyEl.replaceChildren();

    jobs.forEach((job) => {
      const item = _createGlobalQueueHudRow(job);
      if (item) bodyEl.appendChild(item);
    });

    _syncGlobalQueueHudRowVisibility();
  }

  function renderGlobalQueueHud(payloadOrState) {
    const payload =
      payloadOrState?.jobs !== undefined
        ? payloadOrState
        : _globalQueueHudPayloadFromState(payloadOrState || GC.lastState || {});
    _renderGlobalQueueHud(payload);
    GC.startProgressTicker();
  }
  GC.renderGlobalQueueHud = renderGlobalQueueHud;
  GC.renderGlobalBuildQueueHud = renderGlobalQueueHud;

  function shipyardActionReasonText(reason) {
    const key = String(reason || "generic").trim() || "generic";
    const shipyard = t(`shipyard_error_${key}`, "");
    if (shipyard && shipyard !== `shipyard_error_${key}`) return shipyard;
    if (key === "generic" || key === "cancel_failed") {
      return t("shipyard_error_cancel_failed", "Werftauftrag konnte nicht abgebrochen werden.");
    }
    const fleet = t(`fleet_error_${key}`, "");
    if (fleet && fleet !== `fleet_error_${key}`) return fleet;
    return t("shipyard_error_cancel_failed", "Werftauftrag konnte nicht abgebrochen werden.");
  }

  async function _handleGlobalQueueHudCancel(btn) {
    if (!btn || btn.dataset.busy === "1") return;
    const planetId = Number(
      btn.closest("[data-global-queue-hud]")?.dataset.planetId
      || GC.lastState?.global_queue_hud?.planet_id
      || GC.lastState?.active_planet_id
      || 0
    );

    if (btn.dataset.buildCancelId) {
      if (btn.dataset.busy === "1") return;
      setProgressionActionBusy(btn, true);
      try {
        const json = await GC.fetchGameAction("/api/buildings/cancel", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ job_id: Number(btn.dataset.buildCancelId || 0) }),
        });
        applyActionState(json, json.ok ? "build_cancel_success" : "build_cancel_error");
        if (!json.ok) showNotify(mapActionError(json.reason, json.payload), "error");
      } catch (err) {
        console.error("Global build cancel failed:", err);
        showNotify(t("msg_action_failed", "Aktion fehlgeschlagen. Bitte erneut versuchen."), "error");
      } finally {
        setProgressionActionBusy(btn, false);
      }
      return;
    }

    if (btn.dataset.researchCancelId) {
      if (btn.dataset.busy === "1") return;
      setProgressionActionBusy(btn, true);
      try {
        const json = await GC.fetchGameAction("/api/research/cancel", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ job_id: Number(btn.dataset.researchCancelId || 0) }),
        });
        applyActionState(json, json.ok ? "research_cancel_success" : "research_cancel_error");
        if (!json.ok) showNotify(mapActionError(json.reason, json.payload), "error");
      } catch (err) {
        console.error("Global research cancel failed:", err);
        showNotify(t("msg_action_failed", "Aktion fehlgeschlagen. Bitte erneut versuchen."), "error");
      } finally {
        setProgressionActionBusy(btn, false);
      }
      return;
    }

    if (btn.dataset.planetResearchCancelId) {
      if (btn.dataset.busy === "1") return;
      setProgressionActionBusy(btn, true);
      try {
        const planetId = Math.floor(
          Number(
            GC.lastState?.active_planet_id
              || (typeof GC.getDomPlanetId === "function" ? GC.getDomPlanetId() : 0)
              || document.querySelector(".planet-evolution-page")?.dataset?.planetId
              || 0
          )
        );
        const json = await GC.fetchGameAction(`/api/planets/${planetId}/research/cancel`, {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ job_id: Number(btn.dataset.planetResearchCancelId || 0) }),
        });
        applyActionState(json, json.ok ? "planet_research_cancel_success" : "planet_research_cancel_error");
        if (!json.ok) showNotify(mapActionError(json.reason, json.payload), "error");
      } catch (err) {
        console.error("Global planet research cancel failed:", err);
        showNotify(t("msg_action_failed", "Aktion fehlgeschlagen. Bitte erneut versuchen."), "error");
      } finally {
        setProgressionActionBusy(btn, false);
      }
      return;
    }

    if (btn.dataset.shipyardQueueCancel) {
      btn.dataset.busy = "1";
      try {
        const res = await GC.fetchGameAction("/api/shipyard/queue/cancel", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            job_id: Number(btn.dataset.shipyardQueueCancel || 0),
            planet_id: planetId || undefined,
          }),
        });
        if (res?.ok) {
          // GC-512D — state-first; optional data for page-local stocks/labels
          if (res.state) applyActionState(res, "shipyard_cancel");
          const syPage = document.getElementById("shipyard-page");
          if (syPage?.dataset.ready === "1" && res.data) {
            applyShipyardState(syPage, res.data);
          } else if (!res.state && typeof GC.refreshGameState === "function") {
            await GC.refreshGameState("shipyard_cancel");
          }
        } else {
          showNotify(shipyardActionReasonText(res?.error || res?.reason || "cancel_failed"), "error");
        }
      } catch (_) {
        showNotify(shipyardActionReasonText("cancel_failed"), "error");
      } finally {
        btn.dataset.busy = "0";
      }
      return;
    }

    if (btn.dataset.defenseQueueCancel) {
      btn.dataset.busy = "1";
      try {
        const res = await GC.fetchGameAction("/api/defense/cancel", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            job_id: Number(btn.dataset.defenseQueueCancel || 0),
            planet_id: planetId || undefined,
          }),
        });
        if (res?.ok) {
          applyActionState(res, "defense_cancel");
        } else {
          showNotify(reasonText(res?.error || apiError(res)), "error");
        }
      } catch (_) {
        showNotify(reasonText("generic"), "error");
      } finally {
        btn.dataset.busy = "0";
      }
    }
  }

  function initGlobalQueueHud() {
    const hud = document.querySelector("[data-global-queue-hud]");
    if (!hud || hud.dataset.bound === "1") return;
    hud.dataset.bound = "1";

    hud.addEventListener("click", async (e) => {
      const cancelBtn = e.target.closest(
        ".gc-global-queue-hud-cancel, [data-build-cancel-id], [data-research-cancel-id], [data-shipyard-queue-cancel], [data-defense-queue-cancel]"
      );
      if (cancelBtn && hud.contains(cancelBtn)) {
        e.preventDefault();
        e.stopPropagation();
        await _handleGlobalQueueHudCancel(cancelBtn);
        return;
      }
      const row = e.target.closest("[data-global-queue-hud-chip], [data-global-queue-hud-row]");
      if (!row || !hud.contains(row)) return;
      const path = String(row.dataset.navPath || "").trim();
      if (path && typeof GC.navigateTo === "function") {
        e.preventDefault();
        GC.navigateTo(path, { push: true });
      }
    });
  }
  GC.initGlobalQueueHud = initGlobalQueueHud;

  function buildingSubnavRoots() {
    return document.querySelectorAll('[id$="nav-buildings-sub"]');
  }

  function resolveBuildingsActiveTab(preferred) {
    const pageRoot = document.querySelector("[data-buildings-page]");
    if (!pageRoot) return String(preferred || "resources");
    try {
      const urlTab = new URL(window.location.href).searchParams.get("tab");
      if (urlTab) return urlTab;
    } catch (_) {}
    if (pageRoot.dataset.activeBuildingTab) return pageRoot.dataset.activeBuildingTab;
    const panel = pageRoot.querySelector(".tab-content[data-tab]");
    if (panel?.dataset?.tab) return panel.dataset.tab;
    for (const sub of buildingSubnavRoots()) {
      const active = sub.querySelector("[data-building-tab].active");
      if (active?.dataset?.buildingTab) return active.dataset.buildingTab;
    }
    return String(preferred || "resources");
  }

  function _getActiveBuildingTab() {
    return resolveBuildingsActiveTab("resources");
  }

  function _setSubnavGroupExpanded(groupEl, parentEl, expanded) {
    if (groupEl) groupEl.classList.toggle("is-expanded", expanded);
    if (parentEl) parentEl.setAttribute("aria-expanded", expanded ? "true" : "false");
  }

  function syncBuildingsSubnavFromState() {
    GC.restoreLeftmenuState(window.location.href);
  }

  function hideBuildingsSubnav() {
    syncBuildingsSubnavFromState();
  }

  function showBuildingsSubnav() {
    syncBuildingsSubnavFromState();
  }

  function syncBuildingSidebarTab(tab) {
    const target = tab == null || tab === "" ? null : String(tab || "resources");
    buildingSubnavRoots().forEach((sub) => {
      if (!target) {
        sub.querySelectorAll("[data-building-tab]").forEach((el) => el.classList.remove("active"));
        return;
      }
      sub.querySelectorAll("[data-building-tab]").forEach((el) => {
        el.classList.toggle("active", el.dataset.buildingTab === target);
      });
    });
  }

  function activateBuildingTabByName(targetTab, focusEl) {
    const pageRoot = document.querySelector("[data-buildings-page]");
    if (!pageRoot) return;
    const tab = resolveBuildingsActiveTab(targetTab);
    const panels = pageRoot.querySelectorAll(".tab-content[data-tab]");
    if (panels.length === 1) {
      const panel = panels[0];
      panel.classList.add("active");
      if (panel.getAttribute("role") === "tabpanel") panel.hidden = false;
      syncBuildingSidebarTab(panel.dataset.tab || tab);
      pageRoot.dataset.activeBuildingTab = panel.dataset.tab || tab;
    } else {
      panels.forEach((c) => {
        const isActive = c.dataset.tab === tab;
        c.classList.toggle("active", isActive);
        if (c.getAttribute("role") === "tabpanel") c.hidden = !isActive;
      });
      syncBuildingSidebarTab(tab);
      pageRoot.dataset.activeBuildingTab = tab;
    }
    if (focusEl && typeof focusEl.focus === "function") focusEl.focus();
    if (GC.lastState && GC.lastState.ok !== false) {
      _finalizeTimekeeperQueueButtons(GC.lastState);
    }
  }

  function bindBuildingTabsOnce() {
    if (GC._tabsBound) return;
    GC._tabsBound = true;

    document.addEventListener("click", (e) => {
      const subBtn = e.target.closest(
        '[id$="nav-buildings-sub"] [data-building-tab], #gc-bottom-buildings-menu [data-building-tab]'
      );
      if (subBtn) {
        e.preventDefault();
        const tab = subBtn.dataset.buildingTab || "resources";
        if (typeof GC.closeBottomBuildingsMenu === "function") {
          GC.closeBottomBuildingsMenu();
        }
        if (GC.detectPage() === "buildings" && _getActiveBuildingTab() === tab) {
          return;
        }
        GC.navigateTo(`/buildings?tab=${encodeURIComponent(tab)}`);
        return;
      }

      const btn = e.target.closest(".building-tabs .tab-btn");
      if (!btn || btn.closest("#messages-tabs") || btn.closest("#hall-of-fame-page") || btn.closest("#chronicles-page")) return;
      if (btn.tagName === "A") e.preventDefault();
      const tabBtn = btn.dataset.tab;
      if (GC.detectPage() === "buildings" && tabBtn) {
        if (_getActiveBuildingTab() !== tabBtn) {
          GC.navigateTo(`/buildings?tab=${encodeURIComponent(tabBtn)}`);
        }
        return;
      }
      activateBuildingTabByName(tabBtn, btn);
    });
  }

  function initBuildings() {
    bindBuildingTabsOnce();
    initBuildingTechnicalData();
    const pageRoot = document.querySelector("[data-buildings-page]");
    if (!pageRoot) return;
    const initialTab = pageRoot.dataset.activeBuildingTab || "resources";
    activateBuildingTabByName(initialTab, null);
    GC.startProgressTicker();
  }

  const BUILDING_TECH = {
    root: null,
    titleEl: null,
    descEl: null,
    tableWrap: null,
    tableEl: null,
    theadEl: null,
    tbodyEl: null,
    detailEl: null,
    loadingEl: null,
    errorEl: null,
    abort: null,
    open: false,
    reqId: 0,
    activeKey: "",
    activeKind: "building",
  };

  function cacheBuildingTechElements() {
    if (BUILDING_TECH.root && BUILDING_TECH.tbodyEl) return BUILDING_TECH.root;
    BUILDING_TECH.root = document.getElementById("gc-building-tech-root");
    if (!BUILDING_TECH.root) return null;
    BUILDING_TECH.titleEl = document.getElementById("gc-building-tech-title");
    BUILDING_TECH.descEl = BUILDING_TECH.root.querySelector("[data-bt-desc]");
    BUILDING_TECH.tableWrap = BUILDING_TECH.root.querySelector("[data-bt-table-wrap]");
    BUILDING_TECH.tableEl = BUILDING_TECH.root.querySelector("[data-bt-table]");
    BUILDING_TECH.theadEl = BUILDING_TECH.root.querySelector("[data-bt-thead]");
    BUILDING_TECH.tbodyEl = BUILDING_TECH.root.querySelector("[data-bt-tbody]");
    BUILDING_TECH.detailEl = BUILDING_TECH.root.querySelector("[data-bt-detail]");
    BUILDING_TECH.loadingEl = BUILDING_TECH.root.querySelector("[data-bt-loading]");
    BUILDING_TECH.errorEl = BUILDING_TECH.root.querySelector("[data-bt-error]");
    return BUILDING_TECH.root;
  }

  function renderPlayerCardStat(label, valueHtml, { highlight = false, sub = "" } = {}) {
    const subHtml = sub
      ? `<span class="gc-player-card-stat-sub gc-mono">${sub}</span>`
      : "";
    return (
      `<div class="gc-player-card-stat${highlight ? " gc-player-card-stat--highlight" : ""}">` +
      `<span class="gc-player-card-stat-label">${escapeHtml(label)}</span>` +
      `<span class="gc-player-card-stat-value gc-mono">${valueHtml}</span>` +
      subHtml +
      `</div>`
    );
  }

  function renderTechnicalCostChips(metal, crystal) {
    return (
      `<div class="gc-ship-detail-cost gc-mono">` +
      `<span class="gc-cost-chip gc-cost-metal"><span class="gc-res-icon gc-res-metal" aria-hidden="true"></span>` +
      `${renderCostVal(metal)}</span>` +
      `<span class="gc-cost-chip gc-cost-crystal"><span class="gc-res-icon gc-res-crystal" aria-hidden="true"></span>` +
      `${renderCostVal(crystal)}</span>` +
      `</div>`
    );
  }

  function formatTechnicalOutputPart(row) {
    if (!row || typeof row !== "object") return "";
    const kind = String(row.effect_kind || "level");
    const val = row.effect_value;
    if (val == null || val === "") return "";
    const unit = row.effect_unit || "";
    const metricKey = row.effect_metric_key ? t(row.effect_metric_key, "") : "";
    const metricPrefix = metricKey ? `${metricKey}: ` : "";
    if (kind === "production") {
      const res = row.effect_resource ? t("resource_" + row.effect_resource, row.effect_resource) : "";
      const base = `${fmtNumber(val)}${unit}${res ? " " + res : ""}`;
      const delta = row.production_delta_per_hour;
      if (delta != null && Number(delta) > 0) {
        const d = Math.floor(Number(delta));
        return `${metricPrefix}${base} (+${formatNumberCompact(d)}${unit})`;
      }
      return `${metricPrefix}${base}`;
    }
    if (kind === "energy") {
      return `${metricPrefix}${fmtNumber(val)} ${t("energy", "Energie")}`;
    }
    if (kind === "energy_use") {
      return `${metricPrefix}-${fmtNumber(val)} ${t("buildings_technical_energy_use", "Verbrauch")}`;
    }
    if (kind === "storage") {
      const res = row.effect_resource ? t("resource_" + row.effect_resource, row.effect_resource) : "";
      return `${metricPrefix}${fmtNumber(val)}${res ? " " + res : ""}`;
    }
    if (kind === "bonus_percent") {
      return `${metricPrefix}${fmtNumber(val)}${unit || "%"}`;
    }
    if (kind === "reduction_percent") {
      return `${metricPrefix}-${fmtNumber(val)}${unit || "%"}`;
    }
    if (kind === "max_level" || kind === "scan" || kind === "level") {
      return `${metricPrefix}${fmtNumber(val)}`;
    }
    if (kind === "yard_production") {
      const capCompact = formatNumberCompact(val);
      const reduction = Number(row.build_time_reduction_percent || 0);
      if (reduction > 0) {
        return tf(
          "buildings_technical_yard_compact_with_reduction",
          { capacity: capCompact, percent: fmtNumber(reduction) },
          `${capCompact} · -${fmtNumber(reduction)}%`
        );
      }
      return tf(
        "buildings_technical_yard_capacity_compact",
        { capacity: capCompact },
        capCompact
      );
    }
    if (kind === "defense_unlock") {
      return "";
    }
    if (kind === "yard_reference") {
      return tf(
        "buildings_technical_yard_ref_compact",
        { capacity: formatNumberCompact(val) },
        formatNumberCompact(val)
      );
    }
    return `${metricPrefix}${fmtNumber(val)}`;
  }

  function formatTechnicalOutputTitle(row) {
    if (!row || typeof row !== "object") return "";
    const kind = String(row.effect_kind || "");
    if (kind === "reduction_percent") {
      const pct = fmtNumber(row.effect_value ?? row.build_time_reduction_percent ?? 0);
      const factor = row.build_time_factor;
      const parts = [
        tf(
          "buildings_technical_build_time_reduction_building",
          { percent: pct },
          `-${pct}% Bauzeit`
        ),
      ];
      if (factor != null && factor !== "") {
        parts.push(
          tf(
            "buildings_technical_build_time_factor",
            { factor: String(factor) },
            `Faktor ${factor}`
          )
        );
      }
      return parts.join(" · ");
    }
    if (kind === "bonus_percent" && row.effect_resource === "build") {
      const preview = row.nano_time_preview || row.display?.nano_time_preview;
      if (preview && typeof preview === "object") {
        const speed = preview.speed_current != null ? String(preview.speed_current) : "";
        const saved = Math.max(0, Math.floor(Number(preview.saved_marginal_seconds) || 0));
        const parts = [];
        if (speed) {
          parts.push(
            tf(
              "buildings_technical_nano_speed",
              { factor: speed },
              `×${speed}`
            )
          );
        }
        if (saved > 0) {
          parts.push(
            tf(
              "buildings_technical_nano_marginal_save",
              { time: formatDuration(saved) },
              `−${formatDuration(saved)}`
            )
          );
        }
        if (parts.length) return parts.join(" · ");
      }
      const pct = fmtNumber(row.effect_value ?? row.build_time_speed_bonus_percent ?? 0);
      const factor = row.build_time_factor;
      const parts = [
        tf(
          "buildings_technical_build_speed_bonus",
          { percent: pct },
          `+${pct}% Baugeschwindigkeit`
        ),
      ];
      if (factor != null && factor !== "") {
        parts.push(
          tf(
            "buildings_technical_build_time_factor",
            { factor: String(factor) },
            `Faktor ${factor}`
          )
        );
      }
      return parts.join(" · ");
    }
    if (kind === "yard_production") {
      const capFull = fmtNumber(row.effect_value ?? row.yard_batch_capacity ?? 0);
      const parts = [
        tf("buildings_technical_yard_capacity_row", { capacity: capFull }, `Werftkapazität ${capFull}`),
      ];
      const reduction = Number(row.build_time_reduction_percent || 0);
      if (reduction > 0) {
        parts.push(
          tf(
            "buildings_technical_build_time_reduction",
            { percent: fmtNumber(reduction) },
            `-${fmtNumber(reduction)}% Zyklus`
          )
        );
      }
      const light = row.parallel_light;
      const medium = row.parallel_medium;
      const heavy = row.parallel_heavy;
      if (light != null && medium != null && heavy != null) {
        parts.push(
          tf(
            "buildings_technical_parallel_examples",
            {
              light: fmtNumber(light),
              medium: fmtNumber(medium),
              heavy: fmtNumber(heavy),
            },
            `Parallel z. B. ${fmtNumber(light)} / ${fmtNumber(medium)} / ${fmtNumber(heavy)}`
          )
        );
      }
      return parts.join(" · ");
    }
    if (kind === "defense_unlock") {
      const parts = [
        tf(
          "buildings_technical_defense_unlock_row",
          { level: fmtNumber(row.effect_value ?? 0) },
          `Freischaltung Stufe ${fmtNumber(row.effect_value ?? 0)}`
        ),
      ];
      if (row.secondary_effect) {
        const secTitle = formatTechnicalOutputTitle(row.secondary_effect);
        if (secTitle) parts.push(secTitle);
      }
      return parts.join(" · ");
    }
    if (kind === "yard_reference") {
      const yardLevel = row.yard_level != null ? fmtNumber(row.yard_level) : "";
      const capFull = fmtNumber(row.effect_value ?? 0);
      if (yardLevel) {
        return tf(
          "buildings_technical_yard_reference",
          { level: yardLevel, capacity: capFull },
          `Orbitalwerft Stufe ${yardLevel}: Kapazität ${capFull}`
        );
      }
      return tf(
        "buildings_technical_yard_capacity_row",
        { capacity: capFull },
        `Werftkapazität ${capFull}`
      );
    }
    return "";
  }

  function formatTechnicalOutput(row) {
    const primary = formatTechnicalOutputPart(row);
    const sec = row?.secondary_effect;
    const secondary = sec ? formatTechnicalOutputPart(sec) : "";
    if (primary && secondary) return `${primary} · ${secondary}`;
    return primary || secondary || "—";
  }

  function formatTechnicalEnergy(row) {
    if (row?.energy_use != null) return `-${fmtNumber(row.energy_use)}`;
    if (row?.energy_total != null) return fmtNumber(row.energy_total);
    return "—";
  }

