  function updateResearchQueueActions(researchRaw) {
    const list = document.querySelector(".research-prog-list");
    if (!list) return;

    const summary = researchRaw?.summary || null;
    const count = summary?.count ?? (Array.isArray(researchRaw?.queue) ? researchRaw.queue.length : 0);
    const limit = summary?.limit ?? 3;
    const queueFull = count >= limit;

    list.querySelectorAll(".gc-bld-card-head-action[data-tech-key], .tech-status-cell[data-tech-key]").forEach((cell) => {
      if (cell.querySelector(".gc-bld-head-action-btn--warn[disabled]")) return;
      if (cell.querySelector(".gc-bld-head-action-btn--afford[disabled]")) return;

      const techKey = cell.dataset.techKey;
      if (!techKey) return;

      if (queueFull) {
        const fullLabel = t("research_btn_queue_full", "Forschungsliste voll");
        const queueBtn = cell.querySelector(".gc-bld-head-action-btn--locked");
        if (!queueBtn) {
          cell.innerHTML =
            `<button class="gc-bld-head-action-btn gc-bld-head-action-btn--locked btn-research" type="button" disabled` +
            ` aria-disabled="true" title="${fullLabel}" aria-label="${fullLabel}"><span class="gc-bld-head-action-icon">🔒</span></button>`;
        }
        return;
      }

      if (cell.querySelector(".gc-bld-head-action-btn--locked")) {
        const queueActive = count > 0;
        const actionLabel = queueActive
          ? t("research_btn_queue", "Anreihen")
          : t("research_btn_start", "Forschung starten");
        const href = `/research_start/${encodeURIComponent(techKey)}`;
        cell.innerHTML =
          `<a href="${href}" class="gc-bld-head-action-btn gc-bld-head-action-btn--go btn-research"` +
          ` title="${actionLabel}" aria-label="${actionLabel}"><span class="gc-bld-head-action-icon">+</span></a>`;
      }
    });
  }

  function updateBuildQueueActions(buildQueueRaw) {
    if (!document.querySelector(".buildings-prog-list")) return;

    const summary = buildQueueRaw?.summary || null;
    const count = summary?.count ?? (Array.isArray(buildQueueRaw?.queue) ? buildQueueRaw.queue.length : 0);
    const limit = summary?.limit ?? 3;
    const queueFull = count >= limit;
    const fullLabel = t("buildings_btn_queue_full", "Warteschlange voll");
    const queueActive = count > 0;
    const actionLabel = queueActive
      ? t("research_btn_queue", "Anreihen")
      : t("buildings_btn_upgrade", "Ausbau starten");
    const tab = _getActiveBuildingTab();

    document.querySelectorAll(".buildings-prog-list .gc-bld-card-head-action[data-building], .buildings-prog-list .bcell-action[data-building]").forEach((cell) => {
      if (cell.querySelector(".gc-bld-head-action-btn--warn[disabled]")) return;
      if (cell.querySelector(".gc-bld-head-action-btn--afford[disabled]")) return;
      if (cell.querySelector(".gc-bld-head-action-btn--max")) return;

      const bType = cell.dataset.building;
      if (!bType) return;
      const btn = cell.querySelector(".gc-bld-head-action-btn");
      const state = btn?.dataset?.actionState || "";

      if (queueFull && state === "go") {
        cell.innerHTML =
          `<button class="gc-bld-head-action-btn gc-bld-head-action-btn--locked btn-upgrade" type="button" disabled` +
          ` data-action-state="locked" aria-disabled="true" title="${fullLabel}" aria-label="${fullLabel}"><span class="gc-bld-head-action-icon">🔒</span></button>`;
        return;
      }
    });
  }

  function _stripCardQueueOwnerClasses(cardEl) {
    if (!cardEl) return;
    cardEl.classList.remove(
      "gc-building-card--in-queue",
      "gc-building-card--queue-active",
      "gc-building-card--queue-pending",
      "gc-research-card--in-queue",
      "gc-research-card--queue-active",
      "gc-research-card--queue-pending",
      "gc-ship-card--in-queue",
      "gc-ship-card--queue-active",
      "gc-ship-card--queue-pending",
      "gc-planet-tech-card--in-queue",
      "gc-planet-tech-card--queue-active",
      "gc-planet-tech-card--queue-pending",
      "gc-ascension-card--in-queue",
      "gc-ascension-card--queue-active",
      "gc-ascension-card--queue-pending"
    );
  }

  GC.clearCardQueueBlock = function clearCardQueueBlock(cardEl) {
    if (!cardEl) return;
    cardEl.querySelectorAll("[data-gc-card-queue], [data-hero-queue]").forEach((block) => block.remove());
    _clearCardQueueTimekeeperBtn(cardEl);
    stripHeroTimeChipQueueTimer(cardEl);
    resetHeroImageProgress(cardEl);
    _stripCardQueueOwnerClasses(cardEl);
    delete cardEl.dataset.queueHeadJobId;
    delete cardEl.dataset.queuePending;
    delete cardEl.dataset.queueZeroFiredFor;
    delete cardEl.dataset.queueZeroFiredAt;
  };

  /** GC-833: drop completed timer UI immediately — do not wait for poll/PJAX. */
  function dismissCompletedCardQueueBlock(block) {
    if (!block) return;
    const cardEl = block.closest("[data-building-row], [data-research-card], [data-building-card]");
    block.remove();
    if (cardEl && !cardEl.querySelector("[data-gc-card-queue], [data-hero-queue]")) {
      _clearCardQueueTimekeeperBtn(cardEl);
      stripHeroTimeChipQueueTimer(cardEl);
      resetHeroImageProgress(cardEl);
      _stripCardQueueOwnerClasses(cardEl);
      delete cardEl.dataset.queueHeadJobId;
      delete cardEl.dataset.queuePending;
    }
  }

  /** GC-838 — optimistic overlay removal at timer 0 before server confirm. */
  function optimisticDismissDueCardQueueBlock(block) {
    if (!block) return;
    dismissCompletedCardQueueBlock(block);
  }

  function findCardQueueBlockByJobId(cardEl, jobId) {
    if (!cardEl) return null;
    const id = Math.floor(Number(jobId || 0));
    if (id <= 0) return null;
    return cardEl.querySelector(`[data-gc-card-queue][data-job-id="${id}"]`);
  }

  function syncCardQueueOwnerClassesFromBlocks(cardEl, fallbackDomain) {
    if (!cardEl) return;
    const blocks = Array.from(cardEl.querySelectorAll("[data-gc-card-queue]")).filter(
      (block) => block.dataset.heroQueue === "1" || block.classList.contains("gc-card-queue-block")
    );
    if (!blocks.length) {
      _stripCardQueueOwnerClasses(cardEl);
      return;
    }
    const domain =
      fallbackDomain || String(blocks[0].dataset.timerDomain || "building");
    const cardPrefix = _cardQueueClassPrefix(domain);
    const hasActive = Array.from(blocks).some((b) => b.dataset.queueActive === "1");
    cardEl.classList.add(`${cardPrefix}--in-queue`);
    cardEl.classList.toggle(`${cardPrefix}--queue-active`, hasActive);
    cardEl.classList.toggle(`${cardPrefix}--queue-pending`, !hasActive);
  }

  function _cardQueueDomain(queueJob, opts) {
    const fromOpts = opts && opts.domain ? String(opts.domain) : "";
    if (fromOpts) return fromOpts;
    const ownerType = String(queueJob.owner_type || "");
    if (ownerType === "research") return "research";
    if (ownerType === "shipyard") return "shipyard";
    if (ownerType === "planet_research") return "planet_research";
    if (ownerType === "ascension") return "ascension";
    if (ownerType === "defense") return "defense";
    return "building";
  }

  function _cardQueueClassPrefix(domain) {
    if (domain === "research") return "gc-research-card";
    if (domain === "shipyard" || domain === "defense") return "gc-ship-card";
    if (domain === "planet_research") return "gc-planet-tech-card";
    if (domain === "ascension") return "gc-ascension-card";
    return "gc-building-card";
  }

  /**
   * GC-536B/C — queue status inside building/research cards.
   * Safe DOM: createElement + textContent (+ progress width style only).
   */
  function cardQueueJobSignature(queueJob) {
    if (!queueJob || typeof queueJob !== "object") return "";
    return [
      queueJob.owner_type || "",
      queueJob.owner_key || "",
      queueJob.job_id || 0,
      queueJob.status || "",
      queueJob.queue_position || 0,
      Math.floor(Number(queueJob.finish_at || 0)),
      Math.floor(Number(queueJob.start_at || 0)),
      Math.floor(Number(queueJob.target_amount || 0)),
      Math.floor(Number(queueJob.target_level || 0)),
      Math.floor(Number(queueJob.target_phase || 0)),
    ].join(":");
  }

  /** In-place timer patch only when the same live job is still active/queued with stable targets. */
  function canPatchCardQueueInPlace(existing, queueJob) {
    if (!existing || !queueJob || typeof queueJob !== "object") return false;
    const jobId = Math.floor(Number(queueJob.job_id || 0));
    const prevJobId = Math.floor(Number(existing.dataset.jobId || 0));
    if (jobId <= 0 || jobId !== prevJobId) return false;

    const status = String(queueJob.status || "");
    const wasActive = existing.dataset.queueActive === "1";
    const isActive = status === "active";
    if (wasActive !== isActive) return false;

    return true;
  }

  function _patchCardQueueTimingDatasets(block, queueJob) {
    if (!block || !queueJob) return;
    const finishAt = Math.floor(Number(queueJob.finish_at || queueJob.finish_time || 0));
    const startAt = Math.floor(Number(queueJob.start_at || 0));
    if (finishAt > 0) block.dataset.finishAt = String(finishAt);
    else delete block.dataset.finishAt;
    if (startAt > 0) block.dataset.startAt = String(startAt);
    else delete block.dataset.startAt;
  }

  function syncCardQueueOwnerClasses(cardEl, queueJob, domain) {
    if (!cardEl || !queueJob) return;
    const cardPrefix = _cardQueueClassPrefix(domain);
    const isActive = String(queueJob.status || "") === "active";
    cardEl.classList.add(`${cardPrefix}--in-queue`);
    cardEl.classList.toggle(`${cardPrefix}--queue-active`, isActive);
    cardEl.classList.toggle(`${cardPrefix}--queue-pending`, !isActive);
  }

  function findHeroQueue(cardEl) {
    return cardEl?.querySelector("[data-hero-queue]");
  }

  function findHeroImgStack(cardEl) {
    return cardEl?.querySelector(".gc-bld-hero-img-stack");
  }

  function ensureHeroDualImageStack(stack) {
    if (!stack || stack.querySelector(".gc-bld-card-hero-img--color")) return;
    const single = stack.querySelector(":scope > .gc-bld-card-hero-img:not(.gc-bld-card-hero-img--muted):not(.gc-bld-card-hero-img--color)");
    if (!single) return;
    const muted = single.cloneNode(true);
    muted.classList.add("gc-bld-card-hero-img--muted");
    const color = single.cloneNode(true);
    color.classList.add("gc-bld-card-hero-img--color");
    color.setAttribute("aria-hidden", "true");
    single.replaceWith(muted, color);
  }

  function resetHeroSingleImage(stack) {
    if (!stack) return;
    const muted = stack.querySelector(".gc-bld-card-hero-img--muted");
    if (!muted) return;
    const single = muted.cloneNode(true);
    single.classList.remove("gc-bld-card-hero-img--muted", "gc-bld-card-hero-img--color");
    single.removeAttribute("aria-hidden");
    single.style.clipPath = "";
    stack.querySelector(".gc-bld-card-hero-img--color")?.remove();
    muted.replaceWith(single);
  }

  function applyHeroImageProgress(cardEl, pct) {
    const stack = findHeroImgStack(cardEl);
    if (!stack) return;
    const progress = Math.max(0, Math.min(100, Math.round(Number(pct) || 0)));
    stack.classList.add("gc-bld-hero-img-stack--progress");
    stack.style.setProperty("--hero-progress-pct", `${progress}%`);
    ensureHeroDualImageStack(stack);
    const color = stack.querySelector(".gc-bld-card-hero-img--color");
    if (color) color.style.clipPath = `inset(${100 - progress}% 0 0 0)`;
  }

  function applyHeroQueuedMark(cardEl) {
    resetHeroImageProgress(cardEl);
  }

  function resetHeroImageProgress(cardEl) {
    const stack = findHeroImgStack(cardEl);
    if (!stack) return;
    stack.classList.remove("gc-bld-hero-img-stack--progress");
    stack.style.removeProperty("--hero-progress-pct");
    resetHeroSingleImage(stack);
  }

  function stripHeroTimeChipQueueTimer(cardEl) {
    const chip = cardEl?.querySelector("[data-hero-time-chip]");
    if (!chip) return;
    chip.querySelectorAll(".gc-card-queue-timer").forEach((timerEl) => {
      delete timerEl.dataset.timerTarget;
      delete timerEl.dataset.countdownAt;
      delete timerEl.dataset.serverRemaining;
      delete timerEl.dataset.timerKind;
      delete timerEl.dataset.refreshOnZero;
      delete timerEl.dataset.refreshFiredAt;
      timerEl.remove();
    });
  }

  function setHeroTimeChipIdle(cardEl, seconds, title) {
    if (!cardEl || cardEl.classList.contains("gc-building-card--in-queue") || cardEl.classList.contains("gc-research-card--in-queue")) {
      return;
    }
    stripHeroTimeChipQueueTimer(cardEl);
    const chip = cardEl.querySelector("[data-hero-time-chip]");
    if (!chip) return;
    const label = formatDuration(seconds);
    chip.title = title || chip.title || "";
    let textEl = chip.querySelector(".gc-hero-time-text");
    if (!textEl) {
      chip.innerHTML = `<span class="gc-hero-time-text">${label}</span>`;
      return;
    }
    _setIfChanged(textEl, label);
  }

  function ensureHeroTimeChipTimer(cardEl, queueJob, timerKind, refreshOnZero) {
    const chip = cardEl?.querySelector("[data-hero-time-chip]");
    if (!chip || !queueJob) return null;
    if (String(queueJob.status || "") !== "active") return null;
    let timerEl = chip.querySelector(".gc-card-queue-timer");
    const timerTarget = cardQueueTimerTarget(queueJob, true);
    if (!timerEl) {
      timerEl = document.createElement("div");
      timerEl.className = "gc-card-queue-timer gc-mono";
      chip.innerHTML = "";
      chip.appendChild(timerEl);
    }
    if (timerTarget > 0) {
      const remaining = queueJobRemainingSeconds(
        timerTarget,
        getTimerServerNow(),
        resolveQueueJobRemaining(queueJob)
      );
      applyQueueJobTimerAttrs(timerEl, timerTarget, timerKind, refreshOnZero, remaining);
      timerEl.textContent = formatEta(queueTimerDisplaySeconds(remaining));
    }
    return timerEl;
  }

  function ensureHeroQueuedBadgeTimer(block, queueJob, timerKind, refreshOnZero) {
    if (!block || !queueJob) return null;
    const position = Math.max(1, Math.floor(Number(queueJob.queue_position || block.dataset.queuePosition || 1)));
    let badge = block.querySelector(".gc-bld-hero-queue-badge");
    if (!badge) {
      badge = document.createElement("div");
      badge.className = "gc-bld-hero-queue-badge gc-mono";
      block.innerHTML = "";
      block.appendChild(badge);
    }
    let lineEl = badge.querySelector(".gc-bld-hero-queue-badge-line");
    let subEl = badge.querySelector(".gc-bld-hero-queue-badge-sub");
    if (!lineEl || !subEl) {
      badge.innerHTML =
        '<span class="gc-bld-hero-queue-badge-line"></span>' +
        '<span class="gc-bld-hero-queue-badge-sub">' +
        `<span class="gc-bld-hero-queue-starts-label">${t("queue_starts_in", "Startet in")}</span> ` +
        "</span>";
      lineEl = badge.querySelector(".gc-bld-hero-queue-badge-line");
      subEl = badge.querySelector(".gc-bld-hero-queue-badge-sub");
    }
    const queuedLabel = tf("queue_card_status_queued", { n: position }, `QUEUE #${position}`);
    _setIfChanged(lineEl, queuedLabel);
    let timerEl = subEl?.querySelector(".gc-card-queue-timer");
    if (!timerEl && subEl) {
      timerEl = document.createElement("div");
      timerEl.className = "gc-card-queue-timer gc-mono";
      subEl.appendChild(timerEl);
    }
    const timerTarget = cardQueueTimerTarget(queueJob, false);
    if (timerEl && timerTarget > 0) {
      const remaining = queueJobRemainingSeconds(
        timerTarget,
        getTimerServerNow(),
        resolveQueueJobRemaining(queueJob)
      );
      applyQueueJobTimerAttrs(timerEl, timerTarget, timerKind, refreshOnZero, remaining);
      timerEl.textContent = formatEta(queueTimerDisplaySeconds(remaining));
    }
    return timerEl;
  }

  function applyHeroQueueVisual(cardEl, block, queueJob, pct, remaining, timerKind, refreshOnZero) {
    if (!cardEl || !block || !queueJob) return;
    const isActive = String(queueJob.status || "") === "active";
    const progress = Math.max(0, Math.min(100, Math.round(Number(pct) || 0)));
    const pctEl = block.querySelector(".gc-bld-hero-queue-pct");
    const centerEl = block.querySelector(".gc-bld-hero-queue-center");
    block.classList.toggle("gc-bld-hero-queue--active", isActive);
    block.classList.toggle("gc-bld-hero-queue--queued", !isActive);
    if (isActive) {
      applyHeroImageProgress(cardEl, progress);
      if (pctEl) _setIfChanged(pctEl, `${progress}%`);
      if (centerEl) {
        centerEl.setAttribute("role", "progressbar");
        centerEl.setAttribute("aria-valuemin", "0");
        centerEl.setAttribute("aria-valuemax", "100");
        centerEl.setAttribute("aria-valuenow", String(progress));
      }
      const timerEl = cardEl.querySelector("[data-hero-time-chip] .gc-card-queue-timer");
      if (timerEl && Number.isFinite(remaining)) {
        const eta = formatEta(queueTimerDisplaySeconds(remaining));
        _setIfChanged(timerEl, eta);
        block.title = eta;
      }
    } else {
      applyHeroQueuedMark(cardEl);
      if (timerKind) ensureHeroQueuedBadgeTimer(block, queueJob, timerKind, refreshOnZero || "game-state");
      centerEl?.removeAttribute("role");
      centerEl?.removeAttribute("aria-valuemin");
      centerEl?.removeAttribute("aria-valuemax");
      centerEl?.removeAttribute("aria-valuenow");
      const position = Math.max(1, Math.floor(Number(queueJob.queue_position || 1)));
      const queuedLabel = tf("queue_card_status_queued", { n: position }, `QUEUE #${position}`);
      block.title = queuedLabel;
    }
  }

  function patchHeroQueueInPlace(block, queueJob, opts) {
    const cardEl = block.closest("[data-building-row], [data-research-card], [data-building-card]");
    const { timerKind, refreshOnZero } = _cardQueueTimerMeta(queueJob, opts);
    const isActive = String(queueJob.status || "") === "active";
    const finishAt = Math.floor(Number(queueJob.finish_at || 0));
    const totalSeconds = Math.max(1, Math.floor(Number(queueJob.duration_seconds || block.dataset.totalSeconds || 1)));
    const now = getTimerServerNow();
    const timerTarget = cardQueueTimerTarget(queueJob, isActive);
    const remaining = timerTarget > 0
      ? queueJobRemainingSeconds(timerTarget, now, resolveQueueJobRemaining(queueJob))
      : Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)));
    const progressPct = Math.max(0, Math.min(100, Math.floor(Number(queueJob.progress_pct || 0))));
    const pct = isActive
      ? (totalSeconds > 0 ? 100 * (1 - remaining / totalSeconds) : progressPct)
      : 0;

    if (isActive) {
      ensureHeroTimeChipTimer(cardEl, queueJob, timerKind, refreshOnZero);
    } else {
      ensureHeroQueuedBadgeTimer(block, queueJob, timerKind, refreshOnZero);
    }

    _patchCardQueueTimingDatasets(block, queueJob);
    if (isActive && finishAt > 0) assignMonotonicServerRemaining(block, remaining, finishAt);
    applyHeroQueueVisual(cardEl, block, queueJob, pct, remaining, timerKind, refreshOnZero);
    _syncTimekeeperApplyBtn(block, _cardQueueDomain(queueJob, opts), queueJob);
    return block;
  }

  function renderHeroQueueOverlay(cardEl, queueJob, opts) {
    const hero = cardEl.querySelector(".gc-bld-card-hero");
    if (!hero || !queueJob) return null;

    const options = opts && typeof opts === "object" ? opts : {};
    const domain = _cardQueueDomain(queueJob, options);
    if (domain !== "building" && domain !== "research") return null;

    const sig = cardQueueJobSignature(queueJob);
    const jobId = Math.floor(Number(queueJob.job_id || 0));
    let block = findHeroQueue(cardEl);
    if (!block) {
      block = document.createElement("div");
      block.className = "gc-bld-hero-queue gc-card-queue-block gc-card-queue-block--hero";
      block.dataset.heroQueue = "1";
      const levelBadge = hero.querySelector(".gc-bld-card-level");
      if (levelBadge) hero.insertBefore(block, levelBadge);
      else hero.appendChild(block);
    }

    cardEl.querySelectorAll("[data-hero-queue]").forEach((existing) => {
      if (existing !== block) existing.remove();
    });

    if (block && canPatchCardQueueInPlace(block, queueJob)) {
      block.dataset.queueSig = sig;
      patchHeroQueueInPlace(block, queueJob, options);
      syncCardQueueOwnerClassesFromBlocks(cardEl, domain);
      return block;
    }

    const { timerKind, refreshOnZero } = _cardQueueTimerMeta(queueJob, options);
    const status = String(queueJob.status || "");
    const position = Math.max(1, Math.floor(Number(queueJob.queue_position || 1)));
    const finishAt = Math.floor(Number(queueJob.finish_at || 0));
    const startAt = Math.floor(Number(queueJob.start_at || 0));
    const totalSeconds = Math.max(1, Math.floor(Number(queueJob.duration_seconds || 1)));
    const isActive = status === "active";
    const remaining = Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)));
    const progressPct = Math.max(0, Math.min(100, Math.floor(Number(queueJob.progress_pct || 0))));

    block.className = `gc-bld-hero-queue gc-card-queue-block gc-card-queue-block--hero gc-card-queue-block--${isActive ? "active" : "queued"} gc-bld-hero-queue--${isActive ? "active" : "queued"}`;
    block.dataset.heroQueue = "1";
    block.dataset.gcCardQueue = "1";
    block.dataset.queueSig = sig;
    block.dataset.queueActive = isActive ? "1" : "0";
    block.dataset.timerDomain = domain;
    block.dataset.queuePosition = String(position);
    if (jobId > 0) block.dataset.jobId = String(jobId);
    if (startAt > 0) block.dataset.startAt = String(startAt);
    if (finishAt > 0) block.dataset.finishAt = String(finishAt);
    block.dataset.totalSeconds = String(totalSeconds);
    if (isActive && Number.isFinite(remaining)) assignMonotonicServerRemaining(block, remaining, finishAt);

    if (isActive) {
      block.innerHTML =
        '<div class="gc-bld-hero-queue-center"><span class="gc-bld-hero-queue-pct gc-mono"></span></div>';
    } else {
      block.innerHTML =
        '<div class="gc-bld-hero-queue-badge gc-mono">' +
        '<span class="gc-bld-hero-queue-badge-line"></span>' +
        '<span class="gc-bld-hero-queue-badge-sub">' +
        `<span class="gc-bld-hero-queue-starts-label">${t("queue_starts_in", "Startet in")}</span> ` +
        "</span></div>";
    }

    if (isActive) {
      ensureHeroTimeChipTimer(cardEl, queueJob, timerKind, refreshOnZero);
    } else {
      ensureHeroQueuedBadgeTimer(block, queueJob, timerKind, refreshOnZero);
    }

    let cancelBtn = block.querySelector(".gc-bld-hero-queue-cancel");
    if (jobId > 0) {
      if (!cancelBtn) {
        cancelBtn = document.createElement("button");
        cancelBtn.type = "button";
        cancelBtn.className = "gc-bld-hero-queue-cancel";
        cancelBtn.innerHTML = '<span class="gc-bld-head-action-icon">×</span>';
        block.appendChild(cancelBtn);
      }
      if (domain === "research") {
        cancelBtn.dataset.researchCancelId = String(jobId);
        delete cancelBtn.dataset.buildCancelId;
      } else {
        cancelBtn.dataset.buildCancelId = String(jobId);
        delete cancelBtn.dataset.researchCancelId;
      }
      cancelBtn.title = t("action_cancel", "Abbrechen");
      cancelBtn.setAttribute("aria-label", t("action_cancel", "Abbrechen"));
    } else if (cancelBtn) {
      cancelBtn.remove();
    }

    const pct = isActive
      ? (totalSeconds > 0 ? 100 * (1 - remaining / totalSeconds) : progressPct)
      : 0;
    applyHeroQueueVisual(cardEl, block, queueJob, pct, remaining, timerKind, refreshOnZero);
    _syncTimekeeperApplyBtn(block, domain, queueJob);
    syncCardQueueOwnerClassesFromBlocks(cardEl, domain);
    return block;
  }

  function _cardQueueTimerMeta(queueJob, opts) {
    const options = opts && typeof opts === "object" ? opts : {};
    const domain = _cardQueueDomain(queueJob, options);
    const timerKind = String(
      options.timerKind ||
        (domain === "research"
          ? "research"
          : domain === "shipyard"
            ? "shipyard"
            : domain === "planet_research"
              ? "planet_research"
              : domain === "ascension"
                ? "ascension"
              : domain === "defense"
                ? "defense"
                : "build")
    );
    const refreshOnZero = String(
      options.refreshOnZero ||
        (domain === "shipyard"
          ? "shipyard"
          : domain === "defense"
            ? "defense"
          : domain === "planet_research" || domain === "ascension"
            ? "planet_evolution"
            : "game-state")
    );
    return { domain, timerKind, refreshOnZero };
  }

  function patchCardQueueBlockInPlace(block, cardEl, queueJob, opts) {
    if (block?.dataset?.heroQueue === "1" || block?.classList?.contains("gc-bld-hero-queue")) {
      return patchHeroQueueInPlace(block, queueJob, opts);
    }
    const { domain, timerKind, refreshOnZero } = _cardQueueTimerMeta(queueJob, opts);
    const status = String(queueJob.status || "");
    const isActive = status === "active";
    const finishAt = Math.floor(Number(queueJob.finish_at || 0));
    const startAt = Math.floor(Number(queueJob.start_at || 0));
    const totalSeconds = Math.max(1, Math.floor(Number(queueJob.duration_seconds || block.dataset.totalSeconds || 1)));
    const now = getTimerServerNow();
    const timerTarget = cardQueueTimerTarget(queueJob, isActive);
    const remaining = timerTarget > 0
      ? queueJobRemainingSeconds(timerTarget, now, resolveQueueJobRemaining(queueJob))
      : Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)));
    const progressPct = Math.max(0, Math.min(100, Math.floor(Number(queueJob.progress_pct || 0))));

    const timerEl = block.querySelector(".gc-card-queue-timer");
    if (timerEl && timerTarget > 0) {
      applyQueueJobTimerAttrs(timerEl, timerTarget, timerKind, refreshOnZero, remaining);
      const label = formatEta(queueTimerDisplaySeconds(remaining));
      _setIfChanged(timerEl, label);
    }

    const statusEl = block.querySelector(".gc-card-queue-status");
    if (statusEl) {
      const position = Math.max(1, Math.floor(Number(queueJob.queue_position || 1)));
      const statusLabel = isActive
        ? t("queue_card_status_active", "AKTIV")
        : tf("queue_card_status_queued", { n: position }, `QUEUE #${position}`);
      _setIfChanged(statusEl, statusLabel);
    }

    _patchCardQueueTimingDatasets(block, queueJob);
    if (isActive) {
      assignMonotonicServerRemaining(block, remaining, finishAt);
      const pct = totalSeconds > 0 ? 100 * (1 - remaining / totalSeconds) : progressPct;
      const fillEl = block.querySelector(".gc-card-queue-bar-fill");
      const barEl = block.querySelector(".gc-card-queue-bar");
      _applyProgressFill(fillEl, pct);
      if (barEl) barEl.setAttribute("aria-valuenow", String(Math.max(0, Math.min(100, Math.round(pct)))));
    } else if (finishAt > 0) {
      assignMonotonicServerRemaining(block, remaining, finishAt);
    }

    _syncTimekeeperApplyBtn(block, domain, queueJob);
    return block;
  }

  /** Sync card queue blocks from owner map — one visible job per card (head only; rest hidden). */
  function patchCardQueuesFromOwnerMap(page, byOwner, listCards, ownerKeyFromCard, findCard) {
    if (!page) return;
    const ownerMap = byOwner && typeof byOwner === "object" ? byOwner : {};
    const activeKeys = new Set(Object.keys(ownerMap));
    listCards(page).forEach((card) => {
      const key = ownerKeyFromCard(card);
      if (key && !activeKeys.has(key)) {
        delete card.dataset.queueHeadJobId;
        delete card.dataset.queuePending;
        GC.clearCardQueueBlock(card);
      }
    });
    Object.entries(ownerMap).forEach(([ownerKey, jobs]) => {
      const card = findCard(page, ownerKey);
      if (!card) return;
      const list = (Array.isArray(jobs) ? jobs : [])
        .filter((job) => job && typeof job === "object")
        .slice()
        .sort((a, b) => {
          const pa = Math.floor(Number(a.queue_position || 0));
          const pb = Math.floor(Number(b.queue_position || 0));
          if (pa !== pb) return pa - pb;
          return Math.floor(Number(a.job_id || 0)) - Math.floor(Number(b.job_id || 0));
        });
      if (!list.length) {
        delete card.dataset.queueHeadJobId;
        delete card.dataset.queuePending;
        GC.clearCardQueueBlock(card);
        return;
      }
      const headJob = list.find((j) => String(j.status || "") === "active") || list[0];
      const headId = Math.floor(Number(headJob.job_id || 0));
      const prevHead = card.dataset.queueHeadJobId || "";
      const advanced = prevHead && headId > 0 && prevHead !== String(headId);

      card.querySelectorAll("[data-gc-card-queue]").forEach((block) => {
        const blockJobId = Math.floor(Number(block.dataset.jobId || 0));
        if (blockJobId !== headId) block.remove();
      });

      if (headId > 0) card.dataset.queueHeadJobId = String(headId);
      else delete card.dataset.queueHeadJobId;
      if (list.length > 1) card.dataset.queuePending = String(list.length - 1);
      else delete card.dataset.queuePending;

      const block = GC.renderCardQueueBlock(card, headJob);
      if (advanced && block) {
        block.classList.add("gc-card-queue-block--advance");
        block.addEventListener(
          "animationend",
          () => block.classList.remove("gc-card-queue-block--advance"),
          { once: true }
        );
      }
      syncCardQueueOwnerClassesFromBlocks(card, _cardQueueDomain(headJob));
    });
    if (GC.lastState && GC.lastState.ok !== false) {
      _refreshDomTimekeeperApplyBtns(getTimerServerNow());
    }
  }

  GC.renderCardQueueBlock = function renderCardQueueBlock(cardEl, queueJob, opts) {
    if (!cardEl || !queueJob || typeof queueJob !== "object") return null;

    const options = opts && typeof opts === "object" ? opts : {};
    const domain = _cardQueueDomain(queueJob, options);
    if (domain === "building" || domain === "research") {
      return renderHeroQueueOverlay(cardEl, queueJob, options);
    }
    // GC-UNIT-QUEUE-DEDUP-001: shipyard/defense only in central mini-queue strip.
    if (domain === "shipyard" || domain === "defense") {
      return null;
    }

    const sig = cardQueueJobSignature(queueJob);
    const jobId = Math.floor(Number(queueJob.job_id || 0));
    const existing =
      jobId > 0 ? findCardQueueBlockByJobId(cardEl, jobId) : cardEl.querySelector("[data-gc-card-queue]");
    if (existing && canPatchCardQueueInPlace(existing, queueJob)) {
      existing.dataset.queueSig = sig;
      if (String(existing.dataset.queueZeroFiredFor || "").split(":")[0] !== String(jobId)) {
        delete existing.dataset.queueZeroFiredFor;
      }
      patchCardQueueBlockInPlace(existing, cardEl, queueJob, options);
      syncCardQueueOwnerClassesFromBlocks(cardEl, domain);
      return existing;
    }

    const { timerKind, refreshOnZero } = _cardQueueTimerMeta(queueJob, options);

    if (existing) existing.remove();

    const status = String(queueJob.status || "");
    const position = Math.max(1, Math.floor(Number(queueJob.queue_position || 1)));
    const remaining = Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)));
    const progressPct = Math.max(0, Math.min(100, Math.floor(Number(queueJob.progress_pct || 0))));
    const finishAt = Math.floor(Number(queueJob.finish_at || 0));
    const startAt = Math.floor(Number(queueJob.start_at || 0));
    const totalSeconds = Math.max(1, Math.floor(Number(queueJob.duration_seconds || 1)));
    const isActive = status === "active";
    const targetLevel = Math.floor(Number(queueJob.target_level || 0));
    const currentLevel = Math.max(
      0,
      Math.floor(Number(queueJob.current_level ?? (targetLevel > 0 ? targetLevel - 1 : 0)))
    );

    const block = document.createElement("div");
    block.className = `gc-card-queue-block gc-card-queue-block--${domain} gc-card-queue-block--${isActive ? "active" : "queued"}`;
    block.dataset.gcCardQueue = "1";
    block.dataset.queueSig = sig;
    block.dataset.queueActive = isActive ? "1" : "0";
    block.dataset.timerDomain = domain;
    block.dataset.queuePosition = String(position);
    if (jobId > 0) block.dataset.jobId = String(jobId);
    delete block.dataset.queueZeroFiredFor;
    delete block.dataset.queueZeroFiredAt;
    if (startAt > 0) block.dataset.startAt = String(startAt);
    if (finishAt > 0) block.dataset.finishAt = String(finishAt);
    block.dataset.totalSeconds = String(totalSeconds);
    if (isActive && Number.isFinite(remaining)) {
      assignMonotonicServerRemaining(block, remaining, finishAt);
    }

    const head = document.createElement("div");
    head.className = "gc-card-queue-head";

    const glyph = document.createElement("span");
    glyph.className = "gc-card-queue-glyph";
    if (domain === "research") glyph.classList.add("gc-card-queue-glyph--research");
    else if (domain === "shipyard") glyph.classList.add("gc-card-queue-glyph--shipyard");
    else if (domain === "planet_research") glyph.classList.add("gc-card-queue-glyph--planet-research");
    else if (domain === "ascension") glyph.classList.add("gc-card-queue-glyph--ascension");
    else if (domain === "defense") glyph.classList.add("gc-card-queue-glyph--defense");
    glyph.setAttribute("aria-hidden", "true");
    head.appendChild(glyph);

    const statusEl = document.createElement("span");
    statusEl.className = "gc-card-queue-status";
    if (isActive) {
      statusEl.textContent = t("queue_card_status_active", "AKTIV");
    } else {
      statusEl.textContent = tf("queue_card_status_queued", { n: position }, `QUEUE #${position}`);
    }
    head.appendChild(statusEl);
    block.appendChild(head);

    const labelKey = String(queueJob.label_key || queueJob.label || "");
    if (labelKey && (domain === "planet_research" || domain === "ascension")) {
      const titleEl = document.createElement("div");
      titleEl.className = "gc-card-queue-target gc-mono";
      titleEl.textContent = t(labelKey, String(queueJob.owner_key || ""));
      block.appendChild(titleEl);
    }

    const targetAmount = Math.floor(Number(queueJob.target_amount || 0));
    const shipKey = String(queueJob.owner_key || "");
    if ((domain === "shipyard" || domain === "defense") && targetAmount > 1 && shipKey) {
      const qtyEl = document.createElement("div");
      qtyEl.className = "gc-card-queue-quantity gc-mono";
      const itemLabel =
        domain === "defense"
          ? t(queueJob.defense_label_key || `defense_${shipKey}`, defenseDisplayName(shipKey))
          : t(queueJob.ship_label_key || `fleet_ship_${shipKey}`, shipDisplayName(shipKey));
      qtyEl.textContent = `${fmtNumber(targetAmount)}× ${itemLabel}`;
      block.appendChild(qtyEl);
    } else if (targetLevel > 0) {
      const levelEl = document.createElement("div");
      levelEl.className = "gc-card-queue-level gc-mono";
      const lvlShort = t("label_level_short", "L");
      levelEl.textContent = `${lvlShort}${currentLevel} → ${lvlShort}${targetLevel}`;
      block.appendChild(levelEl);
    } else if (domain === "ascension") {
      const targetPhase = Math.floor(Number(queueJob.target_phase || 0));
      if (targetPhase > 0) {
        const phaseEl = document.createElement("div");
        phaseEl.className = "gc-card-queue-phase gc-mono";
        phaseEl.textContent = tf("pe_ascension_phase", { n: targetPhase }, `Phase ${targetPhase}`);
        block.appendChild(phaseEl);
      } else if (queueJob.label_key || queueJob.label) {
        const labelEl = document.createElement("div");
        labelEl.className = "gc-card-queue-target gc-mono";
        labelEl.textContent = t(queueJob.label_key || queueJob.label, String(queueJob.owner_key || ""));
        block.appendChild(labelEl);
      }
    }

    const timerEl = document.createElement("div");
    timerEl.className = "gc-card-queue-timer gc-mono";
    const waitTarget = cardQueueTimerTarget(queueJob, isActive);
    if (waitTarget > 0) {
      const displayRemaining = queueJobRemainingSeconds(
        waitTarget,
        getTimerServerNow(),
        resolveQueueJobRemaining(queueJob)
      );
      applyQueueJobTimerAttrs(timerEl, waitTarget, timerKind, refreshOnZero, displayRemaining);
      timerEl.textContent = formatEta(queueTimerDisplaySeconds(displayRemaining));
    } else if (!isActive) {
      timerEl.textContent = formatEta(Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0))));
    }
    const timeRow = document.createElement("div");
    timeRow.className = "gc-card-queue-time-row";
    timeRow.appendChild(timerEl);
    block.appendChild(timeRow);

    if (isActive) {
      const bar = document.createElement("div");
      bar.className = "gc-card-queue-bar";
      bar.setAttribute("role", "progressbar");
      bar.setAttribute("aria-valuemin", "0");
      bar.setAttribute("aria-valuemax", "100");
      bar.setAttribute("aria-valuenow", String(progressPct));

      const fill = document.createElement("div");
      fill.className = "gc-card-queue-bar-fill gc-progress-smooth";
      fill.style.width = `${progressPct}%`;
      bar.appendChild(fill);

      const scanline = document.createElement("div");
      scanline.className = "gc-card-queue-scanline";
      if (domain === "research") scanline.classList.add("gc-card-queue-scanline--research");
      else if (domain === "shipyard") scanline.classList.add("gc-card-queue-scanline--shipyard");
      else if (domain === "planet_research") scanline.classList.add("gc-card-queue-scanline--planet-research");
      else if (domain === "ascension") scanline.classList.add("gc-card-queue-scanline--ascension");
      else if (domain === "defense") scanline.classList.add("gc-card-queue-scanline--defense");
      scanline.setAttribute("aria-hidden", "true");
      bar.appendChild(scanline);

      block.appendChild(bar);
    }

    if (jobId > 0 && domain !== "ascension") {
      const cancelBtn = document.createElement("button");
      cancelBtn.type = "button";
      cancelBtn.className = "gc-btn gc-btn-ghost gc-btn-xs gc-card-queue-cancel";
      if (domain === "research") cancelBtn.dataset.researchCancelId = String(jobId);
      else if (domain === "shipyard") cancelBtn.dataset.shipyardQueueCancel = String(jobId);
      else if (domain === "defense") cancelBtn.dataset.defenseQueueCancel = String(jobId);
      else if (domain === "planet_research") cancelBtn.dataset.planetResearchCancelId = String(jobId);
      else cancelBtn.dataset.buildCancelId = String(jobId);
      cancelBtn.textContent =
        domain === "shipyard" || domain === "defense"
          ? t("shipyard_queue_cancel_btn", "Abbrechen")
          : t("action_cancel", "Abbrechen");
      block.appendChild(cancelBtn);
    }

    _syncTimekeeperApplyBtn(block, domain, queueJob);

    const slot = cardEl.querySelector(".gc-bld-card-queue-slot");
    const isQueueListHost =
      cardEl.classList.contains("gc-card-queue-list") || cardEl.dataset.peQueueList !== undefined;
    if (isQueueListHost) {
      cardEl.appendChild(block);
    } else if (slot) {
      slot.appendChild(block);
    } else {
      const anchor = cardEl.querySelector(".gc-bld-card-meta, .gc-prog-main");
      if (anchor) cardEl.insertBefore(block, anchor);
      else cardEl.appendChild(block);
    }

    if (!isQueueListHost) {
      syncCardQueueOwnerClassesFromBlocks(cardEl, domain);
    }
    return block;
  };

  function _syncBuildQueueLiveState(queueList) {
    const first = queueList && queueList.length ? queueList[0] : null;
    if (first) {
      const finishTime = resolveQueueJobFinishTime(first);
      if (finishTime) {
        const now = getTimerServerNow();
        const remaining = queueJobRemainingSeconds(finishTime, now, resolveQueueJobRemaining(first));
        const totalRaw = Number(first.total || first.total_seconds || 0);
        const total = totalRaw > 0 ? Math.floor(totalRaw) : Math.max(1, remaining + 1);
        BUILDQ.active.finishTime = finishTime;
        BUILDQ.active.totalSeconds = total;
      } else {
        BUILDQ.active.finishTime = 0;
        BUILDQ.active.totalSeconds = 0;
      }
    } else {
      BUILDQ.active.finishTime = 0;
      BUILDQ.active.totalSeconds = 0;
    }
  }

  function _collectCardJobsFromOwnerMap(queueRaw, mapRawFn) {
    const byOwner = queueRaw?.card_jobs_by_owner;
    if (byOwner && typeof byOwner === "object") {
      const jobs = [];
      Object.values(byOwner).forEach((rows) => {
        if (Array.isArray(rows)) rows.forEach((j) => jobs.push(j));
      });
      jobs.sort((a, b) => (Number(a.queue_position) || 0) - (Number(b.queue_position) || 0));
      return jobs;
    }
    return typeof mapRawFn === "function" ? mapRawFn(queueRaw) : [];
  }

  function _collectShipyardQueueCardJobs(queueRaw) {
    return _collectCardJobsFromOwnerMap(queueRaw, (raw) => {
      const list = Array.isArray(raw?.queue) ? raw.queue : [];
      return list.map((job, idx) => ({
        owner_type: "shipyard",
        owner_key: job.ship_key,
        job_id: job.id,
        status: idx === 0 ? "active" : "queued",
        queue_position: idx + 1,
        finish_at: resolveQueueJobFinishTime(job),
        remaining_seconds: resolveQueueJobRemaining(job),
        target_amount: job.amount || job.amount_total,
        ship_label_key: `fleet_ship_${job.ship_key}`,
      }));
    });
  }

  function _collectDefenseQueueCardJobs(queueRaw) {
    return _collectCardJobsFromOwnerMap(queueRaw, (raw) => {
      const list = Array.isArray(raw?.queue) ? raw.queue : [];
      return list.map((job, idx) => ({
        owner_type: "defense",
        owner_key: job.defense_key,
        job_id: job.id,
        status: idx === 0 ? "active" : "queued",
        queue_position: idx + 1,
        finish_at: resolveQueueJobFinishTime(job),
        remaining_seconds: resolveQueueJobRemaining(job),
        target_amount: job.amount || job.amount_total,
        defense_label_key: `defense_${job.defense_key}`,
      }));
    });
  }

  function miniQueueJobSignature(job) {
    if (!job || typeof job !== "object") return "";
    return [
      job.job_id,
      job.owner_key,
      job.image_url,
      job.position || job.queue_position,
      job.amount || job.target_amount,
      job.is_active ? 1 : 0,
      job.finish_at,
      job.start_at,
      job.duration_seconds,
    ].join(":");
  }

  function researchIconUrl(techKey, iconFile) {
    const key = String(techKey || "").trim();
    let file = String(iconFile || "").trim();
    if (!file && key) {
      const techs = GC.lastState?.research?.techs;
      if (Array.isArray(techs)) {
        const row = techs.find((t) => String(t.key || t.tech_key || "") === key);
        if (row?.icon) file = String(row.icon).trim();
      }
      const queue = GC.lastState?.research?.queue;
      if (!file && Array.isArray(queue)) {
        const row = queue.find((t) => String(t.tech_key || t.key || "") === key);
        if (row?.icon) file = String(row.icon).trim();
      }
    }
    if (!file && key) file = `${key}.png`;
    if (!file) return GC.preferWebpStaticUrl("/static/img/research/energieeffizienz.png");
    if (file.startsWith("/static/")) return GC.preferWebpStaticUrl(file);
    if (file.startsWith("img/")) return GC.preferWebpStaticUrl(`/static/${file}`);
    return GC.preferWebpStaticUrl(`/static/img/research/${file}`);
  }

  function _miniQueueIconUrl(job, domain) {
    const dom = String(domain || "").toLowerCase();
    const ownerKey = String(job.owner_key || "");
    const preset = String(job.image_url || "");
    if (preset) return preset;
    if (dom === "defense") return defenseIconUrl(ownerKey);
    if (dom === "shipyard") return shipyardIconUrl(ownerKey);
    if (dom === "building" || dom === "build") return buildingIconUrl(ownerKey);
    if (dom === "research") return researchIconUrl(ownerKey, job.icon);
    return "";
  }

  function _collectMiniQueueJobs(queueRaw, domain) {
    if (Array.isArray(queueRaw?.mini_queue_jobs)) return queueRaw.mini_queue_jobs;
    const dom = String(domain || "").toLowerCase();
    let cardJobs;
    if (dom === "defense") cardJobs = _collectDefenseQueueCardJobs(queueRaw);
    else if (dom === "shipyard") cardJobs = _collectShipyardQueueCardJobs(queueRaw);
    else if (dom === "building" || dom === "build") cardJobs = _collectBuildQueueCardJobs(queueRaw);
    else if (dom === "research") cardJobs = _collectResearchQueueCardJobs(queueRaw);
    else cardJobs = _collectShipyardQueueCardJobs(queueRaw);
    const isLevelQueue = dom === "building" || dom === "build" || dom === "research";
    return cardJobs.map((job) => ({
      job_id: Math.floor(Number(job.job_id || 0)),
      domain: dom,
      owner_key: String(job.owner_key || ""),
      label: String(
        job.ship_label_key || job.defense_label_key || job.label_key || job.label || job.owner_key || ""
      ),
      amount: isLevelQueue ? 0 : Math.floor(Number(job.target_amount || 0)),
      target_level: Math.floor(Number(job.target_level || 0)) || null,
      position: Math.floor(Number(job.queue_position || 1)),
      is_active: String(job.status || "") === "active",
      remaining_seconds: Math.max(0, Math.floor(Number(job.remaining_seconds || 0))),
      start_at: Math.floor(Number(job.start_at || 0)),
      finish_at: Math.floor(Number(job.finish_at || 0)),
      progress_pct: Math.max(0, Math.min(100, Math.floor(Number(job.progress_pct || 0)))),
      duration_seconds: Math.max(1, Math.floor(Number(job.duration_seconds || 1))),
      image_url: _miniQueueIconUrl(job, dom),
      icon: job.icon,
      cancelable: true,
    }));
  }

  function _resolveMiniQueueLabel(job, domain) {
    return _resolveQueueJobDisplayName(job, domain);
  }

  function _timekeeperApplyBalance(fromState) {
    const src = fromState && typeof fromState === "object" ? fromState : GC.lastState;
    const tk = (src && src.timekeeper) || {};
    return Math.max(0, parseInt(tk.balance_sec, 10) || 0);
  }

  function _primeActionStateTimekeeper(state) {
    if (!state || !state.timekeeper) return;
    const base = GC.lastState && GC.lastState.ok === true ? GC.lastState : { ok: true };
    GC.lastState = { ...base, timekeeper: state.timekeeper };
  }

  function _clearCardQueueTimekeeperBtn(cardEl) {
    if (!cardEl) return;
    cardEl.querySelectorAll(
      ".gc-bld-hero-action-slot--timekeeper [data-gc-timekeeper-apply], .gc-card-queue-time-row [data-gc-timekeeper-apply]"
    ).forEach((btn) => btn.remove());
  }

  function _pruneInactiveTimekeeperApplyBtns() {
    // Hero cards never host ⚡ — strip any leftover SSR/JS injects.
    document.querySelectorAll(
      ".gc-bld-hero-action-slot--timekeeper [data-gc-timekeeper-apply], [data-building-row] .gc-bld-hero-action-row [data-gc-timekeeper-apply], [data-research-card] .gc-bld-hero-action-row [data-gc-timekeeper-apply]"
    ).forEach((btn) => btn.remove());
    // PE tech cards must not host ⚡ (list-only).
    document.querySelectorAll(
      "[data-planet-tech-card] [data-gc-timekeeper-apply]"
    ).forEach((btn) => {
      if (!btn.closest("[data-pe-queue-list], .gc-card-queue-list, #pe-planet-tech-queue-list, #pe-ascension-queue-list")) {
        btn.remove();
      }
    });
    document.querySelectorAll("[data-gc-timekeeper-apply]").forEach((btn) => {
      if (_timekeeperApplying) return;
      const miniCard = btn.closest("[data-mini-queue-card]");
      if (miniCard) {
        if (miniCard.dataset.queueActive !== "1") btn.remove();
        return;
      }
      const peList = btn.closest("#pe-planet-tech-queue-list, #pe-ascension-queue-list, [data-pe-queue-list]");
      if (peList) {
        const block = btn.closest("[data-gc-card-queue]");
        if (block && block.dataset.queueActive !== "1") btn.remove();
        return;
      }
      // Build/research/shipyard/defense: TK only on mini strip — remove stray card buttons.
      const block = btn.closest("[data-gc-card-queue], [data-hero-queue]");
      if (block) btn.remove();
    });
  }

  function _syncTimekeeperButtonsFromState(state) {
    if (!state || state.ok === false) return;
    // Build/research/shipyard/defense: ⚡ only via mini strip (_syncMiniQueueTimekeeperFromState).
    // PE: ⚡ only on queue lists — never inject onto tech cards.
    if (document.querySelector(".planet-evolution-page")) {
      _syncPeQueueListTimekeeperFromDom("pe-planet-tech-queue-list", "planet_research");
      _syncPeQueueListTimekeeperFromDom("pe-ascension-queue-list", "ascension");
    }
    _syncMiniQueueTimekeeperFromState(state);
  }

  function _refreshDomTimekeeperApplyBtns(serverNowTs) {
    const state = GC.lastState;
    if (state && state.ok !== false) {
      _syncTimekeeperButtonsFromState(state);
    }
    const now = Number.isFinite(serverNowTs) ? serverNowTs : getTimerServerNow();
    document.querySelectorAll("[data-gc-timekeeper-apply]").forEach((btn) => {
      const miniCard = btn.closest("[data-mini-queue-card]");
      const block = btn.closest("[data-gc-card-queue], [data-hero-queue]");
      const host = miniCard || block;
      if (!host) return;
      const finishAt = Math.floor(Number(host.dataset.finishAt || 0));
      let rem = parseInt(btn.dataset.timekeeperRemaining, 10) || 0;
      if (finishAt > 0) {
        const srvRemRaw = host.dataset.serverRemaining;
        rem = Math.max(
          0,
          Math.floor(
            queueJobRemainingSeconds(
              finishAt,
              now,
              srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
            )
          )
        );
      }
      _applyTimekeeperBtnState(btn, rem, state);
    });
  }

  function _findResearchCard(ownerKey) {
    const key = String(ownerKey || "").trim();
    if (!key) return null;
    return document.querySelector(`[data-research-card][data-tech-key="${key}"]`);
  }

  function _listResearchCards(root) {
    const scope = root && root.querySelectorAll ? root : document;
    return scope.querySelectorAll("[data-research-card][data-tech-key]");
  }

  function _syncMiniQueueTimekeeperFromState(state) {
    if (!state || typeof state !== "object") return;
    const specs = [
      { hostId: "build-mini-queue", raw: state.build_queue, domain: "building" },
      { hostId: "research-mini-queue", raw: state.research, domain: "research" },
      { hostId: "shipyard-mini-queue", raw: state.shipyard?.queue || state.shipyard_queue, domain: "shipyard" },
      { hostId: "defense-mini-queue", raw: state.defense?.queue || state.defense?.defense_queue, domain: "defense" },
    ];
    specs.forEach(({ hostId, raw, domain }) => {
      if (!raw || !document.getElementById(hostId)) return;
      _collectMiniQueueJobs(raw, domain)
        .filter((job) => Boolean(job.is_active) || String(job.status || "") === "active")
        .forEach((job) => {
          const jobId = Math.floor(Number(job.job_id || 0));
          if (jobId <= 0) return;
          let card = document.querySelector(`[data-mini-queue-card][data-job-id="${jobId}"]`);
          if (!card) return;
          const finishAt = Math.floor(Number(job.finish_at || 0));
          if (finishAt > 0) card.dataset.finishAt = String(finishAt);
          if (job.duration_seconds) card.dataset.totalSeconds = String(Math.max(1, Math.floor(Number(job.duration_seconds))));
          card.dataset.queueActive = "1";
          _syncTimekeeperApplyBtn(card, domain, {
            is_active: true,
            status: "active",
            job_id: jobId,
            finish_at: finishAt,
            remaining_seconds: Math.max(0, Math.floor(Number(job.remaining_seconds || 0))),
            duration_seconds: Math.max(1, Math.floor(Number(job.duration_seconds || card.dataset.totalSeconds || 1))),
          });
        });
    });
  }

  function _syncActiveMiniQueueTimekeeperButtons() {
    document.querySelectorAll("[data-mini-queue-card][data-queue-active='1']").forEach((card) => {
      const domain = String(card.dataset.timerDomain || "build");
      const finishAt = Math.floor(Number(card.dataset.finishAt || 0));
      const total = Math.max(1, Math.floor(Number(card.dataset.totalSeconds || 1)));
      const now = getTimerServerNow();
      const rem = finishAt > 0
        ? Math.max(0, Math.floor(queueJobRemainingSeconds(finishAt, now, NaN)))
        : 0;
      if (rem <= 0) return;
      _syncTimekeeperApplyBtn(card, domain, {
        is_active: true,
        status: "active",
        job_id: Math.floor(Number(card.dataset.jobId || 0)),
        finish_at: finishAt,
        remaining_seconds: rem,
        duration_seconds: total,
      });
    });
  }

  function _finalizeTimekeeperQueueButtons(state) {
    if (!state) return;
    _primeActionStateTimekeeper(state);
    _syncTimekeeperButtonsFromState(state);
    _syncActiveMiniQueueTimekeeperButtons();
    _pruneInactiveTimekeeperApplyBtns();
    _refreshDomTimekeeperApplyBtns(getTimerServerNow());
    patchShellHudTimekeeper(state);
  }

  function _queueJobTimekeeperRemaining(queueJob) {
    if (!queueJob || typeof queueJob !== "object") return 0;
    const isActive = Boolean(queueJob.is_active) || String(queueJob.status || "") === "active";
    if (!isActive) return 0;
    const finishAt = Math.floor(Number(queueJob.finish_at || queueJob.finish_time || 0));
    const now = getTimerServerNow();
    if (finishAt > 0) {
      return Math.max(
        0,
        Math.floor(
          queueJobRemainingSeconds(
            finishAt,
            now,
            Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)))
          )
        )
      );
    }
    return Math.max(0, Math.floor(Number(queueJob.remaining_seconds || 0)));
  }

  function _applyTimekeeperBtnState(btn, remaining, stateForBalance) {
    if (!btn) return;
    const rem = Math.max(0, Math.floor(Number(remaining) || 0));
    const bal = _timekeeperApplyBalance(stateForBalance);
    btn.dataset.timekeeperRemaining = String(rem);
    btn.hidden = bal <= 0 || rem <= 0;
    btn.disabled = bal <= 0 || rem <= 0;
  }

  function _ensureCardQueueTimeRow(block) {
    if (!block) return null;
    let row = block.querySelector(".gc-card-queue-time-row");
    if (row) return row;
    const timerEl = block.querySelector(":scope > .gc-card-queue-timer");
    row = document.createElement("div");
    row.className = "gc-card-queue-time-row";
    if (timerEl) {
      timerEl.replaceWith(row);
      row.appendChild(timerEl);
    } else {
      block.appendChild(row);
    }
    return row;
  }

  function _resolveTimekeeperBtnHost(parent, queueJob) {
    if (!parent) return null;
    // Build/research hero overlays never host ⚡ — mini strip only.
    if (parent.dataset?.heroQueue === "1" || parent.classList?.contains("gc-bld-hero-queue")) {
      return null;
    }
    if (parent.dataset?.miniQueueCard !== undefined || parent.hasAttribute("data-mini-queue-card")) {
      return parent;
    }
    if (parent.dataset?.gcCardQueue === "1" || parent.classList?.contains("gc-card-queue-block")) {
      const onPeList = Boolean(
        parent.closest("#pe-planet-tech-queue-list, #pe-ascension-queue-list, [data-pe-queue-list]")
      );
      if (!onPeList) return null;
      return _ensureCardQueueTimeRow(parent);
    }
    if (parent.classList?.contains("gc-card-queue-time-row")) {
      const onPeList = Boolean(
        parent.closest("#pe-planet-tech-queue-list, #pe-ascension-queue-list, [data-pe-queue-list]")
      );
      return onPeList ? parent : null;
    }
    if (parent.classList?.contains("gc-bld-hero-action-slot--timekeeper")) return null;
    return parent;
  }

  function _insertTimekeeperBtn(host, btn) {
    if (!host || !btn) return;
    if (host.dataset?.miniQueueCard !== undefined || host.hasAttribute("data-mini-queue-card")) {
      const cancel = host.querySelector(".gc-mini-queue-card__cancel");
      if (cancel) host.insertBefore(btn, cancel);
      else host.appendChild(btn);
      return;
    }
    if (host.classList?.contains("gc-card-queue-time-row")) {
      host.insertBefore(btn, host.firstChild);
      return;
    }
    host.appendChild(btn);
  }

  function _createTimekeeperApplyBtn(domain, remaining) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "gc-queue-timekeeper-btn";
    btn.setAttribute("data-gc-timekeeper-apply", "");
    btn.setAttribute("data-timekeeper-domain", String(domain || "build"));
    const tip = _timekeeperApplyTooltip();
    btn.title = tip;
    btn.setAttribute("aria-label", tip);
    btn.innerHTML = '<span aria-hidden="true">⚡</span>';
    _applyTimekeeperBtnState(btn, remaining);
    return btn;
  }

  function _syncTimekeeperApplyBtn(parent, domain, queueJob) {
    if (!parent || !queueJob) return null;
    const isActive = Boolean(queueJob.is_active) || String(queueJob.status || "") === "active";
    if (!isActive) {
      const cardEl = parent.closest("[data-building-row], [data-research-card], [data-building-card]");
      if (cardEl) _clearCardQueueTimekeeperBtn(cardEl);
      return null;
    }
    const host = _resolveTimekeeperBtnHost(parent, queueJob);
    if (!host) return null;
    const rem = _queueJobTimekeeperRemaining(queueJob);
    const show = rem > 0;
    let btn = host.querySelector("[data-gc-timekeeper-apply]");
    if (!show) {
      if (btn) btn.remove();
      return null;
    }
    const dom = String(domain || parent.dataset.timerDomain || host.dataset.timerDomain || "build");
    if (!btn) {
      btn = _createTimekeeperApplyBtn(dom, rem);
      _insertTimekeeperBtn(host, btn);
    } else {
      btn.setAttribute("data-timekeeper-domain", dom);
      _applyTimekeeperBtnState(btn, rem);
    }
    const jobId = Math.floor(
      Number(host?.dataset?.jobId || parent?.dataset?.jobId || queueJob?.job_id || 0)
    );
    if (jobId > 0) btn.setAttribute("data-timekeeper-job-id", String(jobId));
    else btn.removeAttribute("data-timekeeper-job-id");
    return btn;
  }

  GC.renderMiniQueueStrip = function renderMiniQueueStrip(rootEl, jobs, options) {
    if (!rootEl) return;
    const opts = options && typeof options === "object" ? options : {};
    const domain = String(opts.domain || rootEl.dataset.miniQueueHost || "shipyard");
    const cancelDataset =
      domain === "defense"
        ? "defenseQueueCancel"
        : domain === "shipyard"
          ? "shipyardQueueCancel"
          : domain === "research"
            ? "researchCancelId"
            : domain === "building" || domain === "build"
              ? "buildCancelId"
              : "";
    const isLevelQueue = domain === "building" || domain === "build" || domain === "research";
    const strip = rootEl.querySelector("[data-mini-queue-strip]") || rootEl;
    const now = getTimerServerNow();
    const visibleJobs = (Array.isArray(jobs) ? jobs : [])
      .filter((job) => {
        if (!job || typeof job !== "object") return false;
        const rem = Math.max(0, Math.floor(Number(job.remaining_seconds || 0)));
        const finish = Math.floor(Number(job.finish_at || 0));
        if (rem <= 0 && finish > 0 && finish <= now) return false;
        return Math.floor(Number(job.job_id || 0)) > 0;
      })
      .slice()
      .sort(
        (a, b) =>
          Math.floor(Number(a.position || a.queue_position || 0)) -
          Math.floor(Number(b.position || b.queue_position || 0))
      );

    const sig = visibleJobs.map((j) => miniQueueJobSignature(j)).join("|");
    if (sig === strip.dataset.miniQueueSig) {
      visibleJobs.forEach((job) => {
        const card = strip.querySelector(`[data-mini-queue-card][data-job-id="${Math.floor(Number(job.job_id))}"]`);
        if (!card) return;
        const isActive = Boolean(job.is_active);
        const imageUrl = _miniQueueIconUrl(job, domain);
        const imgEl = card.querySelector(".gc-mini-queue-card__image");
        if (imgEl && imageUrl && imgEl.getAttribute("src") !== imageUrl) {
          imgEl.setAttribute("src", imageUrl);
        }
        const timerEl = card.querySelector(".gc-mini-queue-card__timer");
        const finishAt = Math.floor(Number(job.finish_at || 0));
        const titleEl = card.querySelector(".gc-mini-queue-card__title");
        if (titleEl) {
          const label = _resolveMiniQueueLabel(job, domain);
          if (titleEl.textContent !== label) titleEl.textContent = label;
          if (card.title !== label) card.title = label;
        }
        if (timerEl && finishAt > 0) {
          const displayRemaining = queueJobRemainingSeconds(
            finishAt,
            now,
            Math.max(0, Math.floor(Number(job.remaining_seconds || 0)))
          );
          applyQueueJobTimerAttrs(timerEl, finishAt, domain, "game-state", displayRemaining);
          timerEl.textContent = formatEta(queueTimerDisplaySeconds(displayRemaining));
        }
        if (isActive) {
          const total = Math.max(1, Math.floor(Number(job.duration_seconds || card.dataset.totalSeconds || 1)));
          const displayRemaining = finishAt > 0
            ? queueJobRemainingSeconds(
              finishAt,
              now,
              Math.max(0, Math.floor(Number(job.remaining_seconds || 0)))
            )
            : Math.max(0, Math.floor(Number(job.remaining_seconds || 0)));
          const pct = Math.max(0, Math.min(100, Math.round(100 * (1 - displayRemaining / total))));
          const bar = card.querySelector(".gc-mini-queue-card__progress");
          const fill = card.querySelector(".gc-mini-queue-card__progress-fill");
          if (bar) bar.setAttribute("aria-valuenow", String(pct));
          _applyProgressFill(fill, pct);
        }
        if (isActive) _syncTimekeeperApplyBtn(card, domain, job);
        else card.querySelector("[data-gc-timekeeper-apply]")?.remove();
      });
      return;
    }
    strip.dataset.miniQueueSig = sig;
    strip.replaceChildren();

    if (!visibleJobs.length) {
      const emptyEl = document.createElement("span");
      emptyEl.className = "gc-mini-queue-empty";
      emptyEl.dataset.miniQueueEmpty = "1";
      emptyEl.setAttribute("aria-hidden", "true");
      strip.appendChild(emptyEl);
      return;
    }

    visibleJobs.forEach((job, idx) => {
      const jobId = Math.floor(Number(job.job_id || 0));
      const isActive = Boolean(job.is_active);
      const position = Math.max(1, Math.floor(Number(job.position || job.queue_position || idx + 1)));
      const amount = Math.floor(Number(job.amount || job.target_amount || 0));
      const ownerKey = String(job.owner_key || "");
      const finishAt = Math.floor(Number(job.finish_at || 0));
      const startAt = Math.floor(Number(job.start_at || 0));
      const duration = Math.max(1, Math.floor(Number(job.duration_seconds || 1)));
      const progressPct = Math.max(0, Math.min(100, Math.floor(Number(job.progress_pct || 0))));
      const imageUrl = _miniQueueIconUrl(job, domain);
      const label = _resolveMiniQueueLabel(job, domain);

      const card = document.createElement("article");
      card.className = `gc-mini-queue-card${isActive ? " gc-mini-queue-card--active" : " gc-mini-queue-card--waiting"}${isLevelQueue ? " gc-mini-queue-card--level-queue" : " gc-mini-queue-card--production"}`;
      card.dataset.miniQueueCard = "1";
      card.dataset.jobId = String(jobId);
      card.dataset.queueActive = isActive ? "1" : "0";
      card.dataset.timerDomain = domain;
      card.title = amount > 0 ? `${label} ×${fmtNumber(amount)}` : label;
      if (startAt > 0) card.dataset.startAt = String(startAt);
      if (finishAt > 0) card.dataset.finishAt = String(finishAt);
      card.dataset.totalSeconds = String(duration);
      const posLabel = tf("queue_position_label", { n: position }, `Position ${position}`);
      card.setAttribute("aria-label", amount > 0 ? `${posLabel} · ${label} ×${fmtNumber(amount)}` : `${posLabel} · ${label}`);

      const img = document.createElement("img");
      img.className = "gc-mini-queue-card__image";
      img.src = imageUrl;
      img.alt = label;
      img.title = label;
      img.loading = "lazy";
      card.appendChild(img);

      const body = document.createElement("div");
      body.className = "gc-mini-queue-card__body";

      const titleEl = document.createElement("span");
      titleEl.className = "gc-mini-queue-card__title";
      titleEl.textContent = label;
      body.appendChild(titleEl);

      if (isLevelQueue) {
        const targetLevel = Math.floor(Number(job.target_level || 0));
        if (targetLevel > 0) {
          const lvlEl = document.createElement("span");
          lvlEl.className = "gc-mini-queue-card__level gc-mono";
          lvlEl.textContent = tf("build_queue_compact_level", { level: targetLevel }, `Lv.${targetLevel}`);
          body.appendChild(lvlEl);
        }
      } else if (amount > 0) {
        const amtEl = document.createElement("span");
        amtEl.className = "gc-mini-queue-card__amount gc-mono";
        const amtText = `×${fmtNumber(amount)}`;
        amtEl.textContent = amtText;
        amtEl.title = fmtNumber(amount);
        body.appendChild(amtEl);
      }

      const timerEl = document.createElement("span");
      timerEl.className = "gc-mini-queue-card__timer gc-mono";
      if (finishAt > 0) {
        const displayRemaining = queueJobRemainingSeconds(
          finishAt,
          now,
          Math.max(0, Math.floor(Number(job.remaining_seconds || 0)))
        );
        applyQueueJobTimerAttrs(timerEl, finishAt, domain, "game-state", displayRemaining);
        timerEl.textContent = formatEta(queueTimerDisplaySeconds(displayRemaining));
      } else {
        timerEl.textContent = formatEta(Math.max(0, Math.floor(Number(job.remaining_seconds || 0))));
      }
      body.appendChild(timerEl);
      card.appendChild(body);

      if (isActive) _syncTimekeeperApplyBtn(card, domain, job);

      if (job.cancelable !== false && jobId > 0 && cancelDataset) {
        const cancelBtn = document.createElement("button");
        cancelBtn.type = "button";
        cancelBtn.className = "gc-mini-queue-card__cancel";
        cancelBtn.dataset[cancelDataset] = String(jobId);
        cancelBtn.title = t("queue_cancel_tooltip", "Auftrag abbrechen");
        cancelBtn.setAttribute("aria-label", t("queue_cancel_tooltip", "Auftrag abbrechen"));
        cancelBtn.innerHTML = '<span aria-hidden="true">×</span>';
        card.appendChild(cancelBtn);
      }

      if (isActive) {
        const bar = document.createElement("div");
        bar.className = "gc-mini-queue-card__progress";
        bar.setAttribute("role", "progressbar");
        bar.setAttribute("aria-valuemin", "0");
        bar.setAttribute("aria-valuemax", "100");
        bar.setAttribute("aria-valuenow", String(progressPct));
        const fill = document.createElement("div");
        fill.className = "gc-mini-queue-card__progress-fill gc-progress-smooth";
        fill.style.width = `${progressPct}%`;
        bar.appendChild(fill);
        card.appendChild(bar);
      }

      strip.appendChild(card);
    });
  };

  function _renderProductionMiniQueue(hostId, queueRaw, options) {
    const host = document.getElementById(hostId);
    if (!host) return;
    const opts = options && typeof options === "object" ? options : {};
    const domain = String(opts.domain || host.dataset.miniQueueHost || "shipyard");
    const jobs = _collectMiniQueueJobs(queueRaw, domain);
    GC.renderMiniQueueStrip(host, jobs, {
      domain,
      idleText: opts.idleText,
      planetId: opts.planetId,
      limit: Math.floor(Number(queueRaw?.summary?.limit || opts.limit || 0)),
    });
  }

  function _resolveQueueJobDisplayName(job, domain) {
    const ownerKey = String(
      job?.owner_key || job?.tech_key || job?.key || job?.building_type
      || job?.ship_key || job?.defense_key || ""
    );
    if (domain === "shipyard") {
      return t(job.ship_label_key || `fleet_ship_${ownerKey}`, shipDisplayName(ownerKey));
    }
    if (domain === "defense") {
      return t(job.defense_label_key || `defense_${ownerKey}`, defenseDisplayName(ownerKey));
    }
    const candidates = [];
    if (job?.label_key) candidates.push(job.label_key);
    if (job?.label && job.label !== job.label_key) candidates.push(job.label);
    if (domain === "research") {
      candidates.push(ownerKey);
    } else {
      candidates.push(`building_${ownerKey}`, ownerKey);
    }
    for (const key of candidates) {
      const k = String(key || "").trim();
      if (!k) continue;
      const val = t(k, "");
      if (val && val !== k) return val;
    }
    return ownerKey;
  }

  function _bootstrapPageQueueCompactLiveFromDom() {
    const boots = [
      { compactId: "build-mini-queue", live: BUILDQ },
      { compactId: "research-mini-queue", live: RESEARCHQ },
      { compactId: "shipyard-mini-queue", live: SHIPYARDQ },
      { compactId: "defense-mini-queue", live: DEFENSEQ },
    ];
    const now = getTimerServerNow();
    boots.forEach(({ compactId, live }) => {
      const root = document.getElementById(compactId);
      if (!root) return;
      const timerEl = root.querySelector(
        ".gc-mini-queue-card--active .gc-mini-queue-card__timer[data-countdown-at], .gc-mini-queue-card__timer[data-countdown-at]"
      );
      if (!timerEl) return;
      syncTimerElement(timerEl);
      const finish = parseTimerTarget(timerEl.dataset.timerTarget || timerEl.dataset.countdownAt || 0);
      if (!finish || finish <= now) return;
      const srvRem = timerRemainingSeconds(timerEl, now);
      live.active.finishTime = finish;
      live.active.totalSeconds = Math.max(1, srvRem + 1);
    });
  }

  function _hydratePageQueueCompactsFromState() {
    const state = GC.lastState;
    if (!state || state.ok !== true) {
      _bootstrapPageQueueCompactLiveFromDom();
      GC.startProgressTicker();
      return;
    }
    const updaters = [
      ["build-mini-queue", () => _renderProductionMiniQueue("build-mini-queue", state.build_queue, { domain: "building" })],
      ["research-mini-queue", () => _renderProductionMiniQueue("research-mini-queue", state.research, { domain: "research" })],
      ["shipyard-mini-queue", () => {
        const sy = state.shipyard?.queue || state.shipyard_queue;
        const page = document.getElementById("shipyard-page");
        if (sy && page) renderShipyardQueue(page, sy);
      }],
      ["defense-mini-queue", () => {
        const df = state.defense?.defense_queue || state.defense?.queue || state.defense_queue;
        const page = document.getElementById("defense-page");
        if (df && page) renderDefenseQueue(page, df);
      }],
    ];
    updaters.forEach(([id, fn]) => {
      const el = document.getElementById(id);
      if (!el) return;
      delete el.dataset.compactSig;
      fn();
    });
    _bootstrapPageQueueCompactLiveFromDom();
    GC.startProgressTicker();
  }

  function renderBuildQueue(buildQueueRaw) {
    let queueList = [];
    if (!buildQueueRaw) {
      queueList = [];
    } else if (Array.isArray(buildQueueRaw)) {
      queueList = buildQueueRaw;
    } else if (Array.isArray(buildQueueRaw.queue)) {
      queueList = buildQueueRaw.queue;
    }

    const sig = _queueSignature(queueList, buildQueueRaw?.summary || null, buildQueueRaw?.planet_id || 0);
    const count = buildQueueRaw?.summary?.count ?? queueList.length;

    if (sig === _lastQueueSignature) {
      const first = queueList[0];
      const overdue =
        first &&
        resolveQueueJobFinishTime(first) &&
        resolveQueueJobFinishTime(first) <= getTimerServerNow();
      if (!overdue) {
        _syncBuildQueueLiveState(queueList);
        _renderProductionMiniQueue("build-mini-queue", buildQueueRaw, { domain: "building" });
        GC.startProgressTicker();
        return;
      }
    }
    _lastQueueSignature = sig;
    _buildZeroHandled = "";

    if (!queueList.length) _finishRefreshArmed.buildings = false;
    else clearFinishRefreshArmed("buildings", queueList);

    _syncBuildQueueLiveState(queueList);
    _renderProductionMiniQueue("build-mini-queue", buildQueueRaw, { domain: "building" });

    GC.startProgressTicker();
  }

  // =========================
  // Research Queue panel render
  // =========================
  let _lastResearchQueueSignature = "";

  function _researchQueueSignature(queueList, summary) {
    try {
      const count = summary?.count ?? (queueList?.length ?? 0);
      const items = (queueList || [])
        .map((j) => `${j.id || j.tech_key}:${j.target_level}:${j.finish_at || j.finish_time || 0}`)
        .join("|");
      return `${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _syncResearchQueueLiveState(queueList) {
    const first = queueList && queueList.length ? queueList[0] : null;
    if (first) {
      const finishTime = resolveQueueJobFinishTime(first);
      if (finishTime) {
        const now = getTimerServerNow();
        const remaining = queueJobRemainingSeconds(finishTime, now, resolveQueueJobRemaining(first));
        const totalRaw = Number(first.total || first.total_seconds || 0);
        const total = totalRaw > 0 ? Math.floor(totalRaw) : Math.max(1, remaining + 1);
        RESEARCHQ.active.finishTime = finishTime;
        RESEARCHQ.active.totalSeconds = total;
      } else {
        RESEARCHQ.active.finishTime = 0;
        RESEARCHQ.active.totalSeconds = 0;
      }
    } else {
      RESEARCHQ.active.finishTime = 0;
      RESEARCHQ.active.totalSeconds = 0;
    }
  }

  function renderResearchQueue(researchRaw) {
    const host = document.getElementById("research-mini-queue");
    if (!host) return;

    let queueList = [];
    let summary = null;

    if (!researchRaw) {
      queueList = [];
    } else if (Array.isArray(researchRaw.queue)) {
      queueList = researchRaw.queue;
      summary = researchRaw.summary || null;
    } else if (researchRaw.active) {
      queueList = [researchRaw.active];
      summary = { count: 1, limit: 3, first_finish_in: researchRaw.active.remaining || 0 };
    }

    _syncResearchQueueLiveState(queueList);

    const sig = _researchQueueSignature(queueList, summary);
    const count = summary?.count ?? queueList.length;

    if (sig === _lastResearchQueueSignature) {
      const first = queueList[0];
      const finishTime = first ? resolveQueueJobFinishTime(first) : 0;
      const overdue = finishTime > 0 && finishTime <= getTimerServerNow();
      if (!overdue) {
        _renderProductionMiniQueue("research-mini-queue", researchRaw, { domain: "research" });
        GC.startProgressTicker();
        return;
      }
    }
    _lastResearchQueueSignature = sig;

    _renderProductionMiniQueue("research-mini-queue", researchRaw, { domain: "research" });
    if (!queueList.length) _finishRefreshArmed.research = false;
    else clearFinishRefreshArmed("research", queueList);

    GC.startProgressTicker();
  }

  function _applyProgressFill(fillEl, pct) {
    if (!fillEl) return;
    const clamped = Math.max(0, Math.min(100, pct));
    fillEl.style.width = `${clamped}%`;
    fillEl.setAttribute("aria-valuenow", String(Math.round(clamped)));
  }

  let _lastPePlanetTechQueueSignature = "";
  let _lastPeAscensionQueueSignature = "";

  function _resolveActivePePlanetId() {
    const page = document.querySelector(".planet-evolution-page");
    const fromPage = Math.floor(Number(page?.dataset?.planetId || 0));
    if (fromPage > 0) return fromPage;
    return Math.floor(Number(GC.lastState?.active_planet_id || GC.getDomPlanetId?.() || 0));
  }

  function _normalizePePlanetTechQueueRaw(raw) {
    if (!raw || typeof raw !== "object") return null;
    if (raw.card_jobs_by_owner && (raw.queue_count != null || raw.summary)) {
      return {
        ...raw,
        queue_count: raw.queue_count ?? raw.summary?.count ?? 0,
        queue_limit: raw.queue_limit ?? raw.summary?.limit ?? 2,
        card_jobs_by_owner: resolveCardJobsByOwner(raw),
      };
    }
    const byOwner = resolveCardJobsByOwner(raw);
    if (!Object.keys(byOwner).length && !Array.isArray(raw.queue)) return null;
    return {
      ...raw,
      queue_count: raw.summary?.count ?? (Array.isArray(raw.queue) ? raw.queue.length : 0),
      queue_limit: raw.queue_limit ?? raw.summary?.limit ?? 2,
      card_jobs_by_owner: byOwner,
    };
  }

  function _shouldRefreshPlanetEvolutionAfterAction(reasonStr) {
    if (!document.querySelector(".planet-evolution-page")) return false;
    const r = String(reasonStr || "");
    if (r === "timekeeper_apply") return true;
    if (r === "queue_timer_zero" || r === "timer_done" || r.endsWith("_finished")) return true;
    if (r === "planet_research_start" || r === "planet_research_cancel" || r === "planet_research_cancel_success") return true;
    if (r.startsWith("planet_research")) return true;
    if (r === "pe_spec_pick" || r === "pe_spec_upgrade") return true;
    if (r === "pe_policy_activate" || r === "pe_event_resolve" || r === "pe_research_choose") return true;
    return false;
  }

  /** Soft PE content swap after structural mutations (spec/policy/events/choice). HUD already patched via applyActionState. */
  async function _softReloadPlanetEvolutionContent() {
    if (!document.querySelector(".planet-evolution-page")) return;
    if (typeof GC.reloadCurrentPage !== "function") return;
    const anyActive = typeof hasBusyLiveActivity === "function" ? hasBusyLiveActivity() : false;
    await GC.reloadCurrentPage({
      force: true,
      skipGameState: true,
      skipHydrate: true,
      skipPolling: true,
    });
    ensurePlanetLandscapeAfterSoftNav();
    if (typeof GC.startPolling === "function") {
      GC.startPolling(anyActive || (typeof hasBusyLiveActivity === "function" && hasBusyLiveActivity()));
    }
    if (typeof GC.startProgressTicker === "function") GC.startProgressTicker();
  }

  function _schedulePlanetEvolutionRefreshAfterAction(reasonStr) {
    if (!_shouldRefreshPlanetEvolutionAfterAction(reasonStr)) return;
    const pid = _resolveActivePePlanetId();
    if (!pid) return;
    void refreshPlanetEvolutionState(pid).then(() => {
      if (GC.lastState && GC.lastState.ok !== false) {
        _finalizeTimekeeperQueueButtons(GC.lastState);
      }
      GC.startProgressTicker();
    });
  }

  function _syncPeQueueListTimekeeperFromDom(listId, domain) {
    const listEl = document.getElementById(listId);
    if (!listEl) return;
    const now = getTimerServerNow();
    listEl.querySelectorAll("[data-gc-card-queue][data-queue-active='1']").forEach((block) => {
      const jobId = Math.floor(Number(block.dataset.jobId || 0));
      if (jobId <= 0) return;
      const finishAt = Math.floor(Number(block.dataset.finishAt || 0));
      const total = Math.max(1, Math.floor(Number(block.dataset.totalSeconds || 1)));
      const srvRemRaw = block.dataset.serverRemaining;
      const rem = finishAt > 0
        ? Math.max(
          0,
          Math.floor(
            queueJobRemainingSeconds(
              finishAt,
              now,
              srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
            )
          )
        )
        : 0;
      if (rem <= 0) return;
      _syncTimekeeperApplyBtn(block, domain, {
        is_active: true,
        status: "active",
        job_id: jobId,
        finish_at: finishAt,
        remaining_seconds: rem,
        duration_seconds: total,
      });
    });
  }

  function _pePlanetTechQueueSignature(rdx) {
    try {
      const count = rdx?.queue_count ?? 0;
      const byOwner = rdx?.card_jobs_by_owner || {};
      const items = Object.entries(byOwner)
        .map(([k, jobs]) => `${k}:${(jobs[0] || {}).job_id}:${(jobs[0] || {}).finish_at || 0}`)
        .join("|");
      return `${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _peAscensionQueueSignature(asc) {
    try {
      const count = asc?.summary?.count ?? asc?.queue?.length ?? 0;
      const byOwner = asc?.card_jobs_by_owner || {};
      const items = Object.entries(byOwner)
        .map(([k, jobs]) => `${k}:${(jobs[0] || {}).job_id}:${(jobs[0] || {}).finish_at || 0}`)
        .join("|");
      return `${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _updatePePlanetTechQueueCompact(count, limit) {
    const labelEl = document.getElementById("pe-planet-tech-queue-compact-label");
    const countEl = document.getElementById("pe-planet-tech-queue-compact-count");
    const n = Math.max(0, Math.floor(Number(count || 0)));
    const lim = Math.max(1, Math.floor(Number(limit || 2)));
    if (countEl) {
      _setIfChanged(
        countEl,
        `${n}/${lim} ${t("research_queue_jobs", "Aufträge")}`
      );
    }
    if (!labelEl) return;
    if (!n) {
      _setIfChanged(labelEl, t("pe_planet_tech_queue_compact_idle", "Keine Planet-Tech-Aufträge"));
      return;
    }
    _setIfChanged(
      labelEl,
      tf("pe_planet_tech_queue_compact_active", { count: n }, `${n} Planet-Tech-Aufträge`)
    );
  }

  function _updatePeAscensionQueueCompact(count) {
    const labelEl = document.getElementById("pe-ascension-queue-compact-label");
    if (!labelEl) return;
    const n = Math.max(0, Math.floor(Number(count || 0)));
    if (!n) {
      _setIfChanged(labelEl, t("pe_ascension_queue_compact_idle", "Keine Ascension-Aufträge"));
      return;
    }
    _setIfChanged(
      labelEl,
      tf("pe_ascension_queue_compact_active", { count: n }, `${n} Ascension-Aufträge`)
    );
  }

  function _collectPeQueueJobsFromOwnerMap(rdx) {
    const byOwner = resolveCardJobsByOwner(rdx) || {};
    const jobs = [];
    Object.values(byOwner).forEach((rows) => {
      if (!Array.isArray(rows)) return;
      rows.forEach((job) => {
        if (job && typeof job === "object") jobs.push(job);
      });
    });
    jobs.sort((a, b) => {
      const pa = Math.floor(Number(a.queue_position || 0));
      const pb = Math.floor(Number(b.queue_position || 0));
      if (pa !== pb) return pa - pb;
      return Math.floor(Number(a.job_id || 0)) - Math.floor(Number(b.job_id || 0));
    });
    return jobs;
  }

  function _renderPeQueueList(listEl, rdx) {
    if (!listEl) return;
    const jobs = _collectPeQueueJobsFromOwnerMap(rdx);
    const activeIds = new Set(
      jobs.map((job) => String(Math.floor(Number(job.job_id || 0)))).filter((id) => id !== "0")
    );
    listEl.querySelectorAll("[data-gc-card-queue]").forEach((block) => {
      const blockId = block.dataset.jobId || "";
      if (!activeIds.has(blockId)) block.remove();
    });
    if (!jobs.length) {
      listEl.hidden = true;
      return;
    }
    listEl.hidden = false;
    jobs.forEach((job) => {
      const jobId = Math.floor(Number(job.job_id || 0));
      const sig = cardQueueJobSignature(job);
      let block =
        jobId > 0 ? listEl.querySelector(`[data-gc-card-queue][data-job-id="${jobId}"]`) : null;
      if (block && canPatchCardQueueInPlace(block, job)) {
        block.dataset.queueSig = sig;
        if (String(block.dataset.queueZeroFiredFor || "").split(":")[0] !== String(jobId)) {
          delete block.dataset.queueZeroFiredFor;
        }
        patchCardQueueBlockInPlace(block, listEl, job);
        return;
      }
      if (block) block.remove();
      GC.renderCardQueueBlock(listEl, job);
    });
  }

  function patchPePlanetTechCardQueues(rdx) {
    const page = document.querySelector(".planet-evolution-page");
    if (!page) return;
    const byOwner = resolveCardJobsByOwner(rdx);
    _renderPeQueueList(document.getElementById("pe-planet-tech-queue-list"), {
      ...(rdx && typeof rdx === "object" ? rdx : {}),
      card_jobs_by_owner: byOwner,
    });
    page.querySelectorAll("[data-planet-tech-card] [data-gc-card-queue]").forEach((block) => block.remove());
  }

  function patchPeAscensionCardQueues(asc) {
    const page = document.querySelector(".planet-evolution-page");
    if (!page) return;
    _renderPeQueueList(document.getElementById("pe-ascension-queue-list"), asc);
    page.querySelectorAll("[data-ascension-card] [data-gc-card-queue]").forEach((block) => block.remove());
  }

  function applyPeResearchCardQueueJobs(cards) {
    const listEl = document.getElementById("pe-planet-tech-queue-list");
    if (!listEl) return;
    listEl.querySelectorAll("[data-gc-card-queue]").forEach((block) => block.remove());
    const queued = (cards || []).filter((row) => row && row.queue_job);
    if (!queued.length) {
      listEl.hidden = true;
      return;
    }
    listEl.hidden = false;
    queued.forEach((row) => GC.renderCardQueueBlock(listEl, row.queue_job));
  }

  function applyPeAscensionCardQueueJobs(cards) {
    const listEl = document.getElementById("pe-ascension-queue-list");
    if (!listEl) return;
    listEl.querySelectorAll("[data-gc-card-queue]").forEach((block) => block.remove());
    const queued = (cards || []).filter((row) => row && row.queue_job);
    if (!queued.length) {
      listEl.hidden = true;
      return;
    }
    listEl.hidden = false;
    queued.forEach((row) => GC.renderCardQueueBlock(listEl, row.queue_job));
  }

  function renderPePlanetTechQueue(rdx) {
    if (!document.getElementById("pe-planet-tech-queue-compact-count")) return;
    const data = rdx || { queue_count: 0, card_jobs_by_owner: {}, queue_limit: 2 };
    const count = data.queue_count ?? 0;
    const limit = data.queue_limit ?? 2;
    const sig = _pePlanetTechQueueSignature(data);
    if (sig === _lastPePlanetTechQueueSignature) {
      _updatePePlanetTechQueueCompact(count, limit);
      patchPePlanetTechCardQueues(data);
      return;
    }
    _lastPePlanetTechQueueSignature = sig;
    _updatePePlanetTechQueueCompact(count, limit);
    patchPePlanetTechCardQueues(data);
    applyPeResearchCardQueueJobs(data.queue_cards || []);
  }

  function renderPeAscensionQueue(asc) {
    if (!document.getElementById("pe-ascension-queue-compact-label")) return;
    const data = asc || { summary: { count: 0 }, card_jobs_by_owner: {}, ascensions: [] };
    const count = data.summary?.count ?? data.queue?.length ?? 0;
    const sig = _peAscensionQueueSignature(data);
    if (sig === _lastPeAscensionQueueSignature) {
      _updatePeAscensionQueueCompact(count);
      patchPeAscensionCardQueues(data);
      return;
    }
    _lastPeAscensionQueueSignature = sig;
    _updatePeAscensionQueueCompact(count);
    patchPeAscensionCardQueues(data);
    applyPeAscensionCardQueueJobs(data.ascensions || []);
  }

  function applyPlanetEvolutionState(res) {
    const payload = res?.planet || res;
    if (!payload || payload.ok === false) return;
    const dash = payload.dashboard || {};
    if (dash.research_ux) renderPePlanetTechQueue(dash.research_ux);
    if (dash.ascension_ux) renderPeAscensionQueue(dash.ascension_ux);
    if (GC.lastState && GC.lastState.ok !== false) {
      _finalizeTimekeeperQueueButtons(GC.lastState);
    }
    GC.startProgressTicker();
  }

  async function refreshPlanetEvolutionState(planetId) {
    const pid = Math.floor(Number(planetId || 0));
    if (!pid) return null;
    const res = await GC.fetchGameAction(`/api/planets/${pid}/state`);
    if (res?.ok && res.planet) {
      applyPlanetEvolutionState(res);
      return res.planet;
    }
    return null;
  }

  // =========================
  // GC-540 — unified page timers (single tick via startProgressTicker)
  // =========================
  let _pageTimerLoopRunning = false;

  function getTimerServerNow() {
    // Only adopt lastState clock when it is ahead of the local estimate.
    // Never pull the timer clock backward on every tick (causes 1s↔0s / Ankunft flicker).
    const st = Number(GC.lastState?.server_now ?? GC.lastState?.server_time ?? 0);
    if (st > 0) {
      const approx = serverNow();
      if (!TIME.serverNow || st > approx + 0.05) setServerTime(st);
    }
    return serverNow();
  }

  function queryTimerElements(root) {
    const base = root || document;
    const seen = new Set();
    const out = [];
    const add = (el) => {
      if (el && el.nodeType === 1 && !seen.has(el)) {
        seen.add(el);
        out.push(el);
      }
    };
    base.querySelectorAll("[data-timer-target], [data-countdown-at]").forEach(add);
    [
      "#build-eta-live",
      "#research-eta-live",
      "#shipyard-eta-live",
      "#build-queue-subtitle-eta",
      "#research-queue-subtitle-eta",
      "#shipyard-queue-subtitle-eta",
    ].forEach((sel) => {
      const el = base.querySelector(sel);
      if (el) add(el);
    });
    base.querySelectorAll(
      ".build-job-active[data-finish-time], .research-job-active[data-finish-time], .shipyard-job-active[data-finish-time]"
    ).forEach((job) => {
      const eta = job.querySelector("[data-timer-target], [data-countdown-at], .job-time, [data-activity-eta]");
      add(eta || job);
    });
    return out;
  }

  function inferTimerKind(el) {
    if (el.dataset.timerKind) return el.dataset.timerKind;
    if (el.dataset.countdownFormat === "fleet" || el.classList.contains("fleet-active-countdown")) return "fleet";
    if (el.dataset.activityEta) {
      return el.dataset.countdownFormat === "fleet" ? "fleet" : "queue";
    }
    if (el.closest(".shipyard-job-active")) return "shipyard";
    if (el.closest(".build-job-active")) return "build";
    if (el.closest(".research-job-active")) return "research";
    return el.dataset.countdownFormat || "eta";
  }

  function inferRefreshOnZero(el, kind) {
    if (el.dataset.refreshOnZero) return el.dataset.refreshOnZero;
    const scope = el.dataset.countdownScope || "";
    if (scope === "fleet" || kind === "fleet") return "fleet";
    if (kind === "shipyard") return "shipyard";
    if (kind === "defense") return "defense";
    if (scope === "overview" || kind === "build" || kind === "research" || kind === "queue") return "game-state";
    return "";
  }

  function syncTimerElement(el) {
    if (!el) return;
    let target = parseTimerTarget(el.dataset.timerTarget);
    if (!target) target = parseTimerTarget(el.dataset.countdownAt);
    if (!target) {
      const parent = el.closest("[data-finish-time], [data-finish-at]");
      if (parent) {
        target = parseTimerTarget(parent.dataset.finishTime || parent.dataset.finishAt || parent.getAttribute("data-finish-time"));
      }
    }
    if (!target) target = parseTimerTarget(el.getAttribute("data-finish-time"));
    if (target > 0) {
      if (!el.dataset.timerTarget) el.dataset.timerTarget = String(target);
      if (!el.dataset.countdownAt) el.dataset.countdownAt = String(target);
      if (el.dataset.refreshFiredAt && el.dataset.refreshFiredAt !== String(target)) {
        delete el.dataset.refreshFiredAt;
      }
    }
    const kind = inferTimerKind(el);
    if (!el.dataset.timerKind) el.dataset.timerKind = kind;
    const refresh = inferRefreshOnZero(el, kind);
    if (refresh && !el.dataset.refreshOnZero) el.dataset.refreshOnZero = refresh;
  }

  function timerRemainingSeconds(el, serverNow) {
    syncTimerElement(el);
    const target = parseTimerTarget(el.dataset.timerTarget || el.dataset.countdownAt || 0);
    if (!target) return 0;
    const srvRem = el.dataset.serverRemaining;
    const kind = el.dataset.timerKind || inferTimerKind(el);
    const scope = el.dataset.countdownScope || "";
    const useMovement =
      kind === "fleet"
      || scope === "fleet"
      || (scope === "overview" && kind === "fleet");
    if (useMovement) {
      return movementRemainingSeconds(
        target,
        serverNow,
        srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
      );
    }
    return queueJobRemainingSeconds(
      target,
      serverNow,
      srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
    );
  }

  function formatTimerDisplay(remaining, kind) {
    if (kind === "fleet") return formatCountdownRemain(remaining);
    return formatEta(Math.max(0, Math.ceil(remaining)));
  }

  // GC-546D — production completion refresh: canonical include_panel state at timer zero.
  let _queuePanelRefreshInFlight = null;
  let _shipyardApiInFlight = null;
  let _defenseApiInFlight = null;
  const _productionZeroHandled = { shipyard: "", defense: "" };

  function _timerZeroAlreadyFired(el, target) {
    return !!(el && target > 0 && el.dataset.refreshFiredAt === String(target));
  }

  function _markTimerZeroFired(el, target) {
    if (el && target > 0) el.dataset.refreshFiredAt = String(target);
  }

  function requestProductionCompletionSync(opts) {
    if (!shouldRunGameLoop() || _authLoopAborted) return;
    const o = opts && typeof opts === "object" ? opts : {};
    if (o.gameState !== false) {
      requestQueueTimerZeroRefresh({ domain: o.shipyard ? "shipyard" : o.defense ? "defense" : "production" });
    }
  }

  function requestQueueTimerZeroRefresh(meta) {
    if (!shouldRunGameLoop() || _authLoopAborted) return;
    if (GC.pjaxInFlight) return;
    const o = meta && typeof meta === "object" ? meta : {};
    const domain = String(o.domain || "");
    const jobId = Math.floor(Number(o.jobId || 0));
    const finishAt = Math.floor(Number(o.finishAt || 0));
    const key = jobId > 0 ? `${domain}:${jobId}:${finishAt}` : `${domain}:panel:${finishAt || 0}`;
    if (_queueTimerZeroRefreshKeys.has(key)) return;
    _queueTimerZeroRefreshKeys.add(key);
    if (_queueTimerZeroPendingDomains && domain) _queueTimerZeroPendingDomains.add(domain);
    if (_queueTimerZeroRefreshTimer != null) return;
    _queueTimerZeroRefreshTimer = GC.setSafeTimeout(() => {
      _queueTimerZeroRefreshTimer = null;
      const domains = _queueTimerZeroPendingDomains
        ? new Set(_queueTimerZeroPendingDomains)
        : new Set();
      _queueTimerZeroPendingDomains = new Set();
      const keysSnapshot = Array.from(_queueTimerZeroRefreshKeys);
      if (typeof GC.refreshGameState !== "function") {
        keysSnapshot.forEach((k) => _queueTimerZeroRefreshKeys.delete(k));
        return;
      }
      Promise.resolve(forceCanonicalGameStateRefresh("queue_timer_zero")).finally(() => {
          GC.setSafeTimeout(() => {
            keysSnapshot.forEach((k) => _queueTimerZeroRefreshKeys.delete(k));
          }, 1500);
        });
    }, QUEUE_TIMER_ZERO_DEBOUNCE_MS);
  }

  function markCardQueueZeroRefresh(block, jobId, finishAt) {
    if (!block) return false;
    const fireKey = `${Math.floor(Number(jobId || 0))}:${Math.floor(Number(finishAt || 0))}`;
    const prev = block.dataset.queueZeroFiredFor || "";
    const prevAt = Number(block.dataset.queueZeroFiredAt || 0);
    if (prev === fireKey && Date.now() - prevAt < 2500) return false;
    block.dataset.queueZeroFiredFor = fireKey;
    block.dataset.queueZeroFiredAt = String(Date.now());
    return true;
  }

  function requestTimerZeroRefresh(refreshKind, timerKind, opts) {
    const kind = String(refreshKind || "game-state");
    const o = opts && typeof opts === "object" ? opts : {};
    if (kind === "fleet") {
      requestMovementCountdownRefresh("fleet");
      return;
    }
    if (kind === "galaxy") {
      if (typeof GC.reloadCurrentPage === "function") {
        GC.reloadCurrentPage({ force: true });
      }
      return;
    }
    if (kind === "shipyard" || kind === "defense") {
      if (o.jobId != null || o.finishAt != null || o.domain) {
        requestQueueTimerZeroRefresh({
          domain: o.domain || kind,
          jobId: o.jobId,
          finishAt: o.finishAt,
        });
        return;
      }
      requestQueueTimerZeroRefresh({ domain: kind, jobId: 0, finishAt: 0 });
      return;
    }
    const actKey = timerKind === "research" ? "research" : "buildings";
    requestFinishRefresh(actKey);
  }

  const _movementCountdownRefreshPending = { fleet: false, overview: false };
  const _movementCountdownExpiryState = new Map();
  let _movementCountdownRefreshTimer = null;
  let _lastGlobalMovementExpiryRefreshMs = 0;
  let _queuedChainRefreshReason = null;
  const _timerZeroRefreshLastAt = new Map();
  const TIMER_ZERO_REFRESH_MIN_MS = 250;
  const _queueTimerZeroRefreshKeys = new Set();
  let _queueTimerZeroRefreshTimer = null;
  let _queueTimerZeroPendingDomains = new Set();
  const QUEUE_TIMER_ZERO_DEBOUNCE_MS = 150;

  const MOVEMENT_EXPIRY_REFRESH_MS = 900;
  const MOVEMENT_EXPIRY_REFRESH_MS_SHORT = 200;

  function _movementCountdownKey(el) {
    return String(el.dataset.countdownKey || `${el.dataset.countdownScope || ""}:${el.dataset.countdownAt || ""}`);
  }

  function _clearMovementCountdownExpiryState() {
    _movementCountdownExpiryState.clear();
    _lastGlobalMovementExpiryRefreshMs = 0;
  }

  function _movementExpiryCooldownMs(key, urgent) {
    if (urgent) return MOVEMENT_EXPIRY_REFRESH_MS_SHORT;
    const staleHits = _movementCountdownExpiryState.get(`${key}:stale`) || 0;
    if (staleHits >= 3) return MOVEMENT_EXPIRY_REFRESH_MS * 4;
    if (staleHits >= 1) return MOVEMENT_EXPIRY_REFRESH_MS * 2;
    return MOVEMENT_EXPIRY_REFRESH_MS;
  }

  function _shouldRefreshExpiredCountdown(key, urgent) {
    const nowMs = Date.now();
    const globalCooldown = urgent ? MOVEMENT_EXPIRY_REFRESH_MS_SHORT : MOVEMENT_EXPIRY_REFRESH_MS;
    if (nowMs - _lastGlobalMovementExpiryRefreshMs < globalCooldown) return false;
    if (urgent) {
      _movementCountdownExpiryState.set(key, nowMs);
      return true;
    }
    const last = _movementCountdownExpiryState.get(key) || 0;
    const cooldown = _movementExpiryCooldownMs(key, false);
    if (nowMs - last < cooldown) return false;
    _movementCountdownExpiryState.set(key, nowMs);
    return true;
  }

  function _movementExpiryRefreshDebounceMs() {
    let maxStale = 0;
    _movementCountdownExpiryState.forEach((val, k) => {
      if (!String(k).endsWith(":stale")) return;
      maxStale = Math.max(maxStale, Number(val) || 0);
    });
    if (maxStale >= 8) return 400;
    if (maxStale >= 4) return 200;
    return 60;
  }

  function _anyStaleMovementCountdownDom() {
    const now = getTimerServerNow();
    for (const el of document.querySelectorAll("[data-countdown-at]")) {
      const scope = el.dataset.countdownScope || "";
      if (scope !== "fleet" && scope !== "overview") continue;
      const at = Number(el.dataset.countdownAt || 0);
      if (at && Math.ceil(at - now) <= 0) return true;
    }
    if (typeof hasExpiredFleetDrawerMovement === "function" && hasExpiredFleetDrawerMovement(now)) {
      return true;
    }
    return false;
  }

  function _noteMovementCountdownStillStale(key) {
    const hits = (_movementCountdownExpiryState.get(`${key}:stale`) || 0) + 1;
    _movementCountdownExpiryState.set(`${key}:stale`, hits);
  }

  function _clearMovementCountdownStale(key) {
    _movementCountdownExpiryState.delete(`${key}:stale`);
  }

  function requestMovementCountdownRefresh(scope) {
    if (!shouldRunGameLoop() || _authLoopAborted) return;
    const pendingKey = scope === "fleet" ? "fleet" : "overview";
    if (_movementCountdownRefreshPending[pendingKey]) return;

    if (_movementCountdownRefreshTimer) {
      clearTimeout(_movementCountdownRefreshTimer);
      _movementCountdownRefreshTimer = null;
    }

    // GC-FLEET-NOTIFICATION-BATCH-001: coalesce multi-row zeros (150–300ms).
    const debounceMs = Math.max(150, Math.min(300, _movementExpiryRefreshDebounceMs() * 2));
    _movementCountdownRefreshTimer = GC.setSafeTimeout(() => {
      _movementCountdownRefreshTimer = null;
      if (_movementCountdownRefreshPending[pendingKey]) return;
      _movementCountdownRefreshPending[pendingKey] = true;
      _lastGlobalMovementExpiryRefreshMs = Date.now();

      const staleKeys = [];
      document.querySelectorAll("[data-countdown-at]").forEach((el) => {
        const countdownAt = Number(el.dataset.countdownAt || 0);
        if (!countdownAt) return;
        const srvRem = el.dataset.serverRemaining;
        const remaining = movementRemainingSeconds(
          countdownAt,
          getTimerServerNow(),
          srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
        );
        if (remaining <= 0) staleKeys.push(_movementCountdownKey(el));
      });

      if (typeof GC._debugFleetBatch === "object") {
        GC._debugFleetBatch.staleCountdowns = staleKeys.length;
        GC._debugFleetBatch.fleetStateRequests =
          (GC._debugFleetBatch.fleetStateRequests || 0) + 1;
      }

      let refreshPromise = Promise.resolve();
      if (typeof GC.scheduleFleetStateRefresh === "function") {
        refreshPromise = GC.scheduleFleetStateRefresh(`countdown_${pendingKey}`, { immediate: true });
      }
      if (typeof GC.refreshGameState === "function") {
        refreshPromise = refreshPromise.then(() =>
          GC.refreshGameState("fleet_countdown_expired")
        );
      }

      Promise.resolve(refreshPromise).finally(() => {
        _movementCountdownRefreshPending[pendingKey] = false;
        staleKeys.forEach((key) => {
          let stillStale = false;
          document.querySelectorAll("[data-countdown-at]").forEach((el) => {
            if (_movementCountdownKey(el) !== key) return;
            const countdownAt = Number(el.dataset.countdownAt || 0);
            if (!countdownAt) return;
            const srvRem = el.dataset.serverRemaining;
            if (movementRemainingSeconds(
              countdownAt,
              getApproxServerNow(),
              srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
            ) <= 0) stillStale = true;
          });
          if (stillStale) _noteMovementCountdownStillStale(key);
          else _clearMovementCountdownStale(key);
        });
        if (_anyStaleMovementCountdownDom()) {
          requestMovementCountdownRefresh(pendingKey);
        } else {
          GC.startProgressTicker();
        }
      });
    }, debounceMs);
  }

  function updatePageTimers(serverNow) {
    const now = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();
    let fleetExpired = false;
    let overviewExpired = false;

    queryTimerElements().forEach((el) => {
      syncTimerElement(el);
      if (el.closest("[data-fleet-drawer-row]") && el.hasAttribute("data-fleet-drawer-countdown")) {
        return;
      }
      const target = parseTimerTarget(el.dataset.timerTarget || el.dataset.countdownAt || 0);
      if (!target) return;
      const kind = el.dataset.timerKind || inferTimerKind(el);
      const remaining = timerRemainingSeconds(el, now);
      const cardBlock = el.closest("[data-gc-card-queue]");
      const cardDomain = cardBlock ? String(cardBlock.dataset.timerDomain || "") : "";
      const isProductionCardTimer =
        cardBlock && (kind === "shipyard" || kind === "defense" || cardDomain === "shipyard" || cardDomain === "defense");
      if (isProductionCardTimer) {
        _setIfChanged(el, formatEta(queueTimerDisplaySeconds(remaining)));
      } else {
        _setIfChanged(el, formatTimerDisplay(remaining, kind));
      }
      const scope = el.dataset.countdownScope || "";
      const key = _movementCountdownKey(el);
      const isFleetTimer = scope === "fleet" || kind === "fleet";
      const isOverviewFleet = scope === "overview" && kind === "fleet";
      const cardFinish = cardBlock ? parseTimerTarget(cardBlock.dataset.finishAt || target) : 0;
      const refreshKind = el.dataset.refreshOnZero || inferRefreshOnZero(el, kind);
      const queueTimerDone =
        isProductionCardTimer && isQueueTimerComplete(remaining, cardFinish, now);
      if (remaining <= 0 || queueTimerDone) {
        if (isFleetTimer) {
          fleetExpired = true;
        } else if (isOverviewFleet) {
          overviewExpired = true;
        } else if (scope === "overview" && kind === "queue") {
          const actRow = el.closest("[data-activity-key]");
          const actKey = actRow?.dataset?.activityKey || "";
          const zeroKey = `${refreshKind}:${actKey}:${key}`;
          const lastAt = _timerZeroRefreshLastAt.get(zeroKey) || 0;
          if (Date.now() - lastAt >= TIMER_ZERO_REFRESH_MIN_MS) {
            _timerZeroRefreshLastAt.set(zeroKey, Date.now());
            if (actKey === "shipyard") requestFinishRefresh("shipyard");
            else if (actKey === "research") requestFinishRefresh("research");
            else if (actKey === "build") requestFinishRefresh("buildings");
            else if (typeof GC.refreshGameState === "function") GC.refreshGameState("timer_done");
          }
        } else if (queueTimerDone && cardBlock) {
          const jobId = Math.floor(Number(cardBlock.dataset.jobId || 0));
          const finishAt = cardFinish || target;
          if (markCardQueueZeroRefresh(cardBlock, jobId, finishAt)) {
            requestQueueTimerZeroRefresh({
              domain: cardDomain || refreshKind || kind,
              jobId,
              finishAt,
            });
          }
        } else if (remaining <= 0 && refreshKind && !_timerZeroAlreadyFired(el, target)) {
          const zeroKey = `${refreshKind}:${key}`;
          const lastAt = _timerZeroRefreshLastAt.get(zeroKey) || 0;
          if (Date.now() - lastAt >= TIMER_ZERO_REFRESH_MIN_MS) {
            _timerZeroRefreshLastAt.set(zeroKey, Date.now());
            _markTimerZeroFired(el, target);
            requestTimerZeroRefresh(refreshKind, kind);
          }
        }
      } else {
        _movementCountdownExpiryState.delete(key);
        _clearMovementCountdownStale(key);
      }
    });

    document.querySelectorAll("[data-preview-arrival][data-countdown-at]").forEach((el) => {
      syncTimerElement(el);
      const remaining = timerRemainingSeconds(el, now);
      _setIfChanged(el, formatCountdownRemain(remaining));
    });

    if (fleetExpired) requestMovementCountdownRefresh("fleet");
    if (overviewExpired) requestMovementCountdownRefresh("overview");
    updateFleetDrawerRowTimers(now);
    _maybeRefreshStaleMovementCountdowns();
  }

  function updateMovementCountdowns(serverNow) {
    updatePageTimers(serverNow);
  }

  let _buildZeroHandled = "";

  /** GC-557 — drop cached queue timer state (planet switch / PJAX cleanup). */
  function _resetQueueLiveStates() {
    BUILDQ.active.finishTime = 0;
    BUILDQ.active.totalSeconds = 0;
    RESEARCHQ.active.finishTime = 0;
    RESEARCHQ.active.totalSeconds = 0;
    SHIPYARDQ.active.finishTime = 0;
    SHIPYARDQ.active.totalSeconds = 0;
    DEFENSEQ.active.finishTime = 0;
    DEFENSEQ.active.totalSeconds = 0;
    _buildZeroHandled = "";
    _productionZeroHandled.shipyard = "";
    _productionZeroHandled.defense = "";
  }

  function updateAllProgressBars(serverNow) {
    const serverNowTs = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();

    const path = window.location.pathname || "";
    const isResearchPage = path.endsWith("/research");
    const isOverviewPage = path.endsWith("/overview") || path === "/" || path === "";

    const buildActive = document.querySelector(".build-job.build-job-active");
    const buildFinishFromDom = buildActive ? parseTimerTarget(buildActive.getAttribute("data-finish-time")) : 0;
    const buildTotalFromDom = buildActive ? Math.max(1, Number(buildActive.getAttribute("data-total") || 1)) : 1;
    const buildFinishFromState = parseTimerTarget(BUILDQ.active.finishTime || 0);
    const buildTotalFromState = Math.max(1, Number(BUILDQ.active.totalSeconds || 1));
    const buildFinish = buildFinishFromDom || buildFinishFromState;
    const buildTotal = buildFinishFromDom ? buildTotalFromDom : buildTotalFromState;
    if (buildFinish) {
      const srvRemRaw = buildActive?.dataset?.serverRemaining;
      const remaining = queueJobRemainingSeconds(
        buildFinish,
        serverNowTs,
        srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
      );
      if (buildActive) assignMonotonicServerRemaining(buildActive, remaining, buildFinish);
      const pct = 100 * (1 - remaining / buildTotal);
      const etaEl = document.getElementById("build-eta-live");
      const fillEl = document.getElementById("build-bar-fill-live");
      if (etaEl) {
        applyQueueJobTimerAttrs(etaEl, buildFinish, "build", "game-state", remaining);
        _setIfChanged(etaEl, formatEta(Math.ceil(remaining)));
      }
      _applyProgressFill(fillEl, pct);
      if (remaining <= 0) {
        _applyProgressFill(fillEl, 100);
        const zeroKey = `build:${buildFinish}`;
        if (_buildZeroHandled !== zeroKey) {
          _buildZeroHandled = zeroKey;
          requestFinishRefresh("buildings");
        }
      }
    }

    document.querySelectorAll("[data-gc-card-queue][data-queue-active='1']").forEach((block) => {
      const finish = parseTimerTarget(block.dataset.finishAt || 0);
      if (!finish) return;
      const total = Math.max(1, Number(block.dataset.totalSeconds || 1));
      const domain = String(block.dataset.timerDomain || "building");
      const timerKind =
        domain === "research"
          ? "research"
          : domain === "shipyard"
            ? "shipyard"
            : domain === "defense"
              ? "defense"
            : domain === "planet_research"
              ? "planet_research"
              : domain === "ascension"
                ? "ascension"
                : "build";
      const refreshOnZero =
        domain === "shipyard"
          ? "shipyard"
          : domain === "defense"
            ? "defense"
          : domain === "planet_research" || domain === "ascension"
            ? "planet_evolution"
            : "game-state";
      const srvRemRaw = block.dataset.serverRemaining;
      const remaining = queueJobRemainingSeconds(
        finish,
        serverNowTs,
        srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
      );
      assignMonotonicServerRemaining(block, remaining, finish);
      const pct = 100 * (1 - remaining / total);
      const cardEl = block.closest("[data-building-row], [data-research-card], [data-building-card]");
      const timerEl = block.dataset.heroQueue === "1"
        ? cardEl?.querySelector("[data-hero-time-chip] .gc-card-queue-timer")
        : block.querySelector(".gc-card-queue-timer");
      const fillEl = block.querySelector(".gc-card-queue-bar-fill");
      const barEl = block.querySelector(".gc-card-queue-bar");
      if (block.dataset.heroQueue === "1" && cardEl) {
        const rounded = Math.max(0, Math.min(100, Math.round(pct)));
        applyHeroImageProgress(cardEl, rounded);
        const heroPctEl = block.querySelector(".gc-bld-hero-queue-pct");
        const centerEl = block.querySelector(".gc-bld-hero-queue-center");
        if (heroPctEl) _setIfChanged(heroPctEl, `${rounded}%`);
        if (centerEl) centerEl.setAttribute("aria-valuenow", String(rounded));
        if (timerEl) {
          applyQueueJobTimerAttrs(timerEl, finish, timerKind, refreshOnZero, remaining);
          const eta = formatEta(queueTimerDisplaySeconds(remaining));
          _setIfChanged(timerEl, eta);
          block.title = eta;
        }
      } else {
        if (timerEl) {
          applyQueueJobTimerAttrs(timerEl, finish, timerKind, refreshOnZero, remaining);
          _setIfChanged(timerEl, formatEta(queueTimerDisplaySeconds(remaining)));
        }
        _applyProgressFill(fillEl, pct);
        if (barEl) barEl.setAttribute("aria-valuenow", String(Math.max(0, Math.min(100, Math.round(pct)))));
      }
      if (isQueueTimerComplete(remaining, finish, serverNowTs)) {
        const jobId = Math.floor(Number(block.dataset.jobId || 0));
        optimisticDismissDueCardQueueBlock(block);
        if (domain === "research") {
          const zeroKey = `research-card:${finish}:${jobId}`;
          if (_buildZeroHandled !== zeroKey) {
            _buildZeroHandled = zeroKey;
            requestFinishRefresh("research");
          }
        } else if (domain === "shipyard" || domain === "defense") {
          if (markCardQueueZeroRefresh(block, jobId, finish)) {
            requestQueueTimerZeroRefresh({ domain, jobId, finishAt: finish });
          }
        } else if (domain === "planet_research" || domain === "ascension") {
          const zeroKey = `${domain}-card:${finish}:${jobId}`;
          if (_buildZeroHandled !== zeroKey) {
            _buildZeroHandled = zeroKey;
            requestFinishRefresh("planet_evolution");
          }
        } else {
          const zeroKey = `build-card:${finish}:${jobId}`;
          const cardEl = block.closest("[data-building-row]");
          const buildingKey = cardEl?.getAttribute("data-building-row") || "";
          if (_buildZeroHandled !== zeroKey) {
            _buildZeroHandled = zeroKey;
            requestBuildingsFinishRefresh({ buildingKey, jobId, finishAt: finish });
          }
        }
      }
    });

    document.querySelectorAll("[data-gc-card-queue][data-queue-active='0']").forEach((block) => {
      const finishAt = parseTimerTarget(block.dataset.finishAt || 0);
      const startAt = parseTimerTarget(block.dataset.startAt || 0);
      const target = finishAt > 0 ? finishAt : startAt;
      if (!target) return;
      const cardEl = block.closest("[data-building-row], [data-research-card], [data-building-card]");
      const timerEl = block.dataset.heroQueue === "1"
        ? block.querySelector(".gc-bld-hero-queue-badge .gc-card-queue-timer")
        : block.querySelector(".gc-card-queue-timer");
      if (!timerEl) return;
      const domain = String(block.dataset.timerDomain || "building");
      const timerKind =
        domain === "research"
          ? "research"
          : domain === "shipyard"
            ? "shipyard"
            : domain === "defense"
              ? "defense"
            : domain === "planet_research"
              ? "planet_research"
              : domain === "ascension"
                ? "ascension"
                : "build";
      const refreshOnZero =
        domain === "shipyard"
          ? "shipyard"
          : domain === "defense"
            ? "defense"
          : domain === "planet_research" || domain === "ascension"
            ? "planet_evolution"
            : "game-state";
      const srvRemRaw = block.dataset.serverRemaining;
      const remaining = queueJobRemainingSeconds(
        target,
        serverNowTs,
        srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
      );
      assignMonotonicServerRemaining(block, remaining, target);
      applyQueueJobTimerAttrs(timerEl, target, timerKind, refreshOnZero, remaining);
      _setIfChanged(timerEl, formatEta(queueTimerDisplaySeconds(remaining)));
    });

    const researchActive = document.querySelector(".research-job.research-job-active");
    if (researchActive) {
      const finishTimeFromDom = parseTimerTarget(researchActive.getAttribute("data-finish-time"));
      const finishTimeFromState = parseTimerTarget(RESEARCHQ.active.finishTime || 0);
      const finishTime = finishTimeFromDom || finishTimeFromState;
      const totalFromDom = Math.max(1, Number(researchActive.getAttribute("data-total") || 1));
      const totalFromState = Math.max(1, Number(RESEARCHQ.active.totalSeconds || 1));
      const total = finishTimeFromDom ? totalFromDom : totalFromState;
      if (finishTime) {
        const srvRemRaw = researchActive.dataset.serverRemaining;
        const remaining = queueJobRemainingSeconds(
          finishTime,
          serverNowTs,
          srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
        );
        const pct = 100 * (1 - remaining / total);
        const etaEl = document.getElementById("research-eta-live");
        const fillEl = document.getElementById("research-bar-fill-live");
        if (etaEl) {
          applyQueueJobTimerAttrs(etaEl, finishTime, "research", "game-state", remaining);
          _setIfChanged(etaEl, formatEta(remaining));
        }
        _applyProgressFill(fillEl, pct);
        const subEta = document.getElementById("research-queue-subtitle-eta");
        if (subEta) _setIfChanged(subEta, formatEta(remaining));
        if (remaining <= 0) {
          _applyProgressFill(fillEl, 100);
          requestFinishRefresh("research");
        }
      }
    }

    const shipyardActive = document.getElementById("shipyard-page")?.querySelector(".shipyard-job.shipyard-job-active");
    if (shipyardActive) {
      const orderFinishFromDom = parseTimerTarget(shipyardActive.getAttribute("data-finish-time"));
      const orderFinishFromState = parseTimerTarget(SHIPYARDQ.active.finishTime || 0);
      const orderFinish = orderFinishFromDom || orderFinishFromState;
      const nextUnitFinish = parseTimerTarget(shipyardActive.getAttribute("data-next-finish-time"));
      const totalFromDom = Math.max(1, Number(shipyardActive.getAttribute("data-total") || 1));
      const totalFromState = Math.max(1, Number(SHIPYARDQ.active.totalSeconds || 1));
      const total = orderFinishFromDom ? totalFromDom : totalFromState;
      if (orderFinish) {
        const srvRemRaw = shipyardActive.dataset.serverRemaining;
        const orderRemaining = queueJobRemainingSeconds(
          orderFinish,
          serverNowTs,
          srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
        );
        assignMonotonicServerRemaining(shipyardActive, orderRemaining, orderFinish);
        const pct = 100 * (1 - orderRemaining / total);
        const etaEl = document.getElementById("shipyard-eta-live");
        const fillEl = document.getElementById("shipyard-bar-fill-live");
        if (etaEl) {
          applyQueueJobTimerAttrs(etaEl, orderFinish, "shipyard", "shipyard", orderRemaining);
          _setIfChanged(etaEl, formatEta(queueTimerDisplaySeconds(orderRemaining)));
        }
        _applyProgressFill(fillEl, pct);
        const subEta = document.getElementById("shipyard-queue-subtitle-eta");
        if (subEta) _setIfChanged(subEta, formatEta(queueTimerDisplaySeconds(orderRemaining)));
        if (nextUnitFinish > 0 && nextUnitFinish <= serverNowTs) {
          const unitKey = `${shipyardActive.dataset.queueJobId || ""}:${nextUnitFinish}`;
          if (_shipyardUnitFinishKey !== unitKey) {
            _shipyardUnitFinishKey = unitKey;
            requestProductionCompletionSync({ gameState: true, shipyard: true });
          }
        } else if (isQueueTimerComplete(orderRemaining, orderFinish, serverNowTs)) {
          const jobId = Math.floor(Number(shipyardActive.dataset.queueJobId || 0));
          if (markCardQueueZeroRefresh(shipyardActive, jobId, orderFinish)) {
            requestQueueTimerZeroRefresh({
              domain: "shipyard",
              jobId,
              finishAt: orderFinish,
            });
          }
        }
      }
    }

    const defenseActive = document.getElementById("defense-page")?.querySelector(".shipyard-job.shipyard-job-active");
    if (defenseActive) {
      const orderFinishFromDom = parseTimerTarget(defenseActive.getAttribute("data-finish-time"));
      const orderFinishFromState = parseTimerTarget(DEFENSEQ.active.finishTime || 0);
      const orderFinish = orderFinishFromDom || orderFinishFromState;
      const nextUnitFinish = parseTimerTarget(defenseActive.getAttribute("data-next-finish-time"));
      const totalFromDom = Math.max(1, Number(defenseActive.getAttribute("data-total") || 1));
      const totalFromState = Math.max(1, Number(DEFENSEQ.active.totalSeconds || 1));
      const total = orderFinishFromDom ? totalFromDom : totalFromState;
      if (orderFinish) {
        const srvRemRaw = defenseActive.dataset.serverRemaining;
        const orderRemaining = queueJobRemainingSeconds(
          orderFinish,
          serverNowTs,
          srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
        );
        assignMonotonicServerRemaining(defenseActive, orderRemaining, orderFinish);
        const pct = 100 * (1 - orderRemaining / total);
        const etaEl = document.getElementById("defense-eta-live");
        const fillEl = document.getElementById("defense-bar-fill-live");
        if (etaEl) {
          applyQueueJobTimerAttrs(etaEl, orderFinish, "defense", "defense", orderRemaining);
          _setIfChanged(etaEl, formatEta(queueTimerDisplaySeconds(orderRemaining)));
        }
        _applyProgressFill(fillEl, pct);
        const subEta = document.getElementById("defense-queue-subtitle-eta");
        if (subEta) _setIfChanged(subEta, formatEta(queueTimerDisplaySeconds(orderRemaining)));
        if (nextUnitFinish > 0 && nextUnitFinish <= serverNowTs) {
          const unitKey = `${defenseActive.dataset.queueJobId || ""}:${nextUnitFinish}`;
          if (_defenseUnitFinishKey !== unitKey) {
            _defenseUnitFinishKey = unitKey;
            requestProductionCompletionSync({ gameState: true, defense: true });
          }
        } else if (isQueueTimerComplete(orderRemaining, orderFinish, serverNowTs)) {
          const jobId = Math.floor(Number(defenseActive.dataset.queueJobId || 0));
          if (markCardQueueZeroRefresh(defenseActive, jobId, orderFinish)) {
            requestQueueTimerZeroRefresh({
              domain: "defense",
              jobId,
              finishAt: orderFinish,
            });
          }
        }
      }
    }

    const ovBox = document.getElementById("overview-research-active");
    if (ovBox) {
      const finishAt = Number(ovBox.dataset.finishAt || 0);
      const total = Math.max(1, Number(ovBox.dataset.total || 1));
      if (finishAt) {
        const srvRemRaw = ovBox.dataset.serverRemaining;
        const remaining = queueJobRemainingSeconds(
          finishAt,
          serverNowTs,
          srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
        );
        const pct = 100 * (1 - remaining / total);
        const cdEl = document.getElementById("research-remaining");
        const barEl = document.getElementById("research-bar-fill");
        if (cdEl) _setIfChanged(cdEl, formatEta(remaining));
        _applyProgressFill(barEl, pct);
        if (remaining <= 0) {
          _applyProgressFill(barEl, 100);
          requestFinishRefresh("research");
        }
      }
    }

    updateMovementCountdowns(serverNowTs);

    if (isOverviewPage) {
      document.querySelectorAll("#overview-activities .overview-activity-row[data-finish-at]").forEach((row) => {
        const etaEl = row.querySelector("[data-activity-eta]");
        if (!etaEl) return;
        syncTimerElement(etaEl);
        const finishAt = parseTimerTarget(row.dataset.finishAt || etaEl.dataset.timerTarget || etaEl.dataset.countdownAt);
        if (!finishAt) return;
        const srvRemRaw = etaEl.dataset.serverRemaining;
        const remaining = queueJobRemainingSeconds(
          finishAt,
          serverNowTs,
          srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
        );
        _setIfChanged(etaEl, formatTimerDisplay(remaining, etaEl.dataset.timerKind || inferTimerKind(etaEl)));
        if (remaining <= 0) {
          const actKey = String(row.dataset.activityKey || "");
          if (actKey === "build") requestFinishRefresh("buildings");
          else if (actKey === "research") requestFinishRefresh("research");
          else if (actKey === "shipyard") requestFinishRefresh("shipyard");
          else if (!actKey.startsWith("fleet")) requestFinishRefresh("planet_evolution");
        }
      });
    }

    updateMiniQueueProgressBars(serverNowTs);
    updateSafetyCountdownTimers();
    if (_timekeeperApplyBalance() > 0 && !_timekeeperApplying) {
      _refreshDomTimekeeperApplyBtns(serverNowTs);
    }
  }

  function updateMiniQueueProgressBars(serverNowTs) {
    document.querySelectorAll(".gc-mini-queue-card--active[data-finish-at]").forEach((card) => {
      const finish = parseTimerTarget(card.dataset.finishAt || 0);
      if (!finish) return;
      const total = Math.max(1, Number(card.dataset.totalSeconds || 1));
      const domain = String(card.dataset.timerDomain || "building");
      const srvRemRaw = card.dataset.serverRemaining;
      const remaining = queueJobRemainingSeconds(
        finish,
        serverNowTs,
        srvRemRaw === undefined || srvRemRaw === "" ? NaN : Number(srvRemRaw)
      );
      assignMonotonicServerRemaining(card, remaining, finish);
      const timerEl = card.querySelector(".gc-mini-queue-card__timer");
      if (timerEl) {
        applyQueueJobTimerAttrs(timerEl, finish, domain, "game-state", remaining);
        _setIfChanged(timerEl, formatEta(queueTimerDisplaySeconds(remaining)));
      }
      const pct = Math.max(0, Math.min(100, 100 * (1 - remaining / total)));
      const bar = card.querySelector(".gc-mini-queue-card__progress");
      const fill = card.querySelector(".gc-mini-queue-card__progress-fill");
      if (bar) bar.setAttribute("aria-valuenow", String(Math.round(pct)));
      _applyProgressFill(fill, pct);
    });
  }

  // =========================
  // Polling state (singleton via GC.polling)
  // =========================

  let lastHadActiveJob = false;
  let lastHadActiveResearch = false;
  let lastHadActiveShipyard = false;
  let lastHadActiveDefense = false;
  let lastHadActiveFleet = false;
  let _lastPollVersion = 0;
  let lastBuildQueueCount = null;
  let lastBuildQueueFull = null;
  let lastResearchQueueCount = null;
  let lastResearchQueueFull = null;

  function hasBusyLiveActivity() {
    return (
      lastHadActiveJob
      || lastHadActiveResearch
      || lastHadActiveShipyard
      || lastHadActiveDefense
      || lastHadActiveFleet
    );
  }

  function rememberPollVersion(data) {
    const ver = Number(data?.poll_version || data?.version || 0);
    if (Number.isFinite(ver) && ver > 0) _lastPollVersion = ver;
  }

  function syncActiveFleetBusyFromState(data) {
    const now = getTimerServerNow();
    const fleets = normalizeActiveFleetsPayload(data?.active_fleets);
    let busy = Number(fleets.count || 0) > 0;
    if (!busy && Array.isArray(fleets.items)) {
      busy = fleets.items.some((it) => {
        if (!it || typeof it !== "object") return false;
        const arr = Number(it.arrival_at || 0);
        const ret = Number(it.return_at || 0);
        return (arr > now) || (ret > now);
      });
    }
    lastHadActiveFleet = Boolean(busy);
  }

  /** Client-side resource projection for the active planet (synced on each game-state). */
  const _resourceLive = {
    planetId: 0,
    syncedAt: 0,
    metal: 0,
    crystal: 0,
    fuelCells: 0,
    prodMetal: 0,
    prodCrystal: 0,
    prodFuelCells: 0,
    capMetal: 0,
    capCrystal: 0,
    capFuelCells: 0,
    energyUsed: 0,
    energyTotal: 0,
  };
  let _resourceTickerId = null;
  let _resourceTickerPaused = false;
  const RESOURCE_TICKER_MS_ACTIVE = 1000;
  const RESOURCE_TICKER_MS_IDLE = 5000;
  let _resourceTickerCurrentInterval = RESOURCE_TICKER_MS_IDLE;
  let _resourceDisplay = { metal: null, crystal: null, fuelCells: null };

  /** Shell HUD resource values only (#resource-bar) — never fleet/page [data-res] nodes. */
  function patchShellHudLiveResources(metal, crystal, fuelCells) {
    const bar = document.getElementById("resource-bar");
    if (!bar) return;
    const m = Math.max(0, Math.floor(Number(metal) || 0));
    const c = Math.max(0, Math.floor(Number(crystal) || 0));
    const f = Math.max(0, Math.floor(Number(fuelCells) || 0));
    if (_resourceDisplay.metal !== m) {
      bar.querySelectorAll(".res-value.metal").forEach((el) => {
        _setIfChanged(el, fmtNumber(m));
      });
      _resourceDisplay.metal = m;
    }
    if (_resourceDisplay.crystal !== c) {
      bar.querySelectorAll(".res-value.crystal").forEach((el) => {
        _setIfChanged(el, fmtNumber(c));
      });
      _resourceDisplay.crystal = c;
    }
    if (_resourceDisplay.fuelCells !== f) {
      bar.querySelectorAll(".res-value.fuel_cells").forEach((el) => {
        _setIfChanged(el, fmtNumber(f));
      });
      _resourceDisplay.fuelCells = f;
    }
    patchHudCapacityBars(
      m,
      c,
      f,
      _resourceLive.capMetal,
      _resourceLive.capCrystal,
      _resourceLive.capFuelCells,
      _resourceLive.energyUsed,
      _resourceLive.energyTotal,
      { animate: false }
    );
    patchResourceBarEnergyWarning(_resourceLive.energyUsed, _resourceLive.energyTotal);
  }

  function monotonicResourceBaseline(incoming, current, projected, allowRegression) {
    const inc = Math.max(0, Math.floor(Number(incoming) || 0));
    if (allowRegression) return inc;
    const cur = Math.max(0, Math.floor(Number(current) || 0));
    const proj = Math.max(0, Math.floor(Number(projected) || 0));
    return Math.max(inc, cur, proj);
  }

  function syncResourceLiveBaseline(snapshot, opts) {
    if (!snapshot || !snapshot.planetId) return;
    const planetId = Number(snapshot.planetId);
    if (!Number.isFinite(planetId) || planetId <= 0) return;
    const allowRegression = Boolean(opts && opts.allowResourceRegression);
    const samePlanet = planetId === _resourceLive.planetId;
    const projected = allowRegression ? null : projectLiveResourceAmounts(getApproxServerNow());
    _resourceLive.planetId = planetId;
    _resourceLive.syncedAt = getApproxServerNow();
    _resourceLive.metal = monotonicResourceBaseline(
      snapshot.metal,
      samePlanet ? _resourceLive.metal : 0,
      projected ? projected.metal : 0,
      allowRegression
    );
    _resourceLive.crystal = monotonicResourceBaseline(
      snapshot.crystal,
      samePlanet ? _resourceLive.crystal : 0,
      projected ? projected.crystal : 0,
      allowRegression
    );
    _resourceLive.fuelCells = monotonicResourceBaseline(
      snapshot.fuelCells,
      samePlanet ? _resourceLive.fuelCells : 0,
      projected ? projected.fuelCells : 0,
      allowRegression
    );
    _resourceLive.prodMetal = Math.max(0, Math.floor(Number(snapshot.prodMetal) || 0));
    _resourceLive.prodCrystal = Math.max(0, Math.floor(Number(snapshot.prodCrystal) || 0));
    _resourceLive.prodFuelCells = Math.max(0, Math.floor(Number(snapshot.prodFuelCells) || 0));
    _resourceLive.capMetal = Math.max(0, Math.floor(Number(snapshot.storageMetal) || 0));
    _resourceLive.capCrystal = Math.max(0, Math.floor(Number(snapshot.storageCrystal) || 0));
    _resourceLive.capFuelCells = Math.max(0, Math.floor(Number(snapshot.storageFuelCells) || 0));
    _resourceLive.energyUsed = Math.max(0, Math.floor(Number(snapshot.energyUsed) || 0));
    _resourceLive.energyTotal = Math.max(0, Math.floor(Number(snapshot.energyTotal) || 0));
    _resourceDisplay = { metal: null, crystal: null, fuelCells: null };
    startResourceTicker();
  }

  let _resourceRatesMissingForceAt = 0;
  const RESOURCE_RATES_MISSING_FORCE_COOLDOWN_MS = 15000;

  function resourceLiveRatesAreZero() {
    return !(
      _resourceLive.prodMetal
      || _resourceLive.prodCrystal
      || _resourceLive.prodFuelCells
    );
  }

  /** After diet `{unchanged:true}`, restore ticker rates or force one full diet. */
  function maybeRestoreResourceRatesAfterUnchangedPoll() {
    if (!resourceLiveRatesAreZero()) return;
    const fromState = productionRatesFromState(GC.lastState);
    if (fromState.prodMetal || fromState.prodCrystal || fromState.prodFuelCells) {
      const planetId = Number(_resourceLive.planetId || getDomPlanetId() || 0);
      if (!planetId) return;
      syncResourceLiveBaseline({
        planetId,
        metal: _resourceLive.metal,
        crystal: _resourceLive.crystal,
        fuelCells: _resourceLive.fuelCells,
        storageMetal: _resourceLive.capMetal,
        storageCrystal: _resourceLive.capCrystal,
        storageFuelCells: _resourceLive.capFuelCells,
        energyUsed: _resourceLive.energyUsed,
        energyTotal: _resourceLive.energyTotal,
        prodMetal: fromState.prodMetal,
        prodCrystal: fromState.prodCrystal,
        prodFuelCells: fromState.prodFuelCells,
      });
      return;
    }
    const now = Date.now();
    if (now - _resourceRatesMissingForceAt < RESOURCE_RATES_MISSING_FORCE_COOLDOWN_MS) return;
    _resourceRatesMissingForceAt = now;
    _lastPollVersion = 0;
    queueMicrotask(() => {
      if (!shouldRunGameLoop() || _authLoopAborted) return;
      if (!resourceLiveRatesAreZero()) return;
      refreshGameState("resource_rates_missing");
    });
  }

  function projectLiveResourceAmount(current, prodPerHour, cap, hours) {
    const cur = Math.max(0, Math.floor(Number(current) || 0));
    const prod = Math.max(0, Math.floor(Number(prodPerHour) || 0));
    const h = Math.max(0, Number(hours) || 0);
    const capN = Math.floor(Number(cap) || 0);
    if (capN <= 0) return Math.floor(cur + prod * h);
    // Overflow (trader/scrapyard/rewards): never clamp existing stock; production only fills to cap.
    if (cur >= capN) return cur;
    return Math.min(capN, Math.floor(cur + prod * h));
  }

  function projectLiveResourceAmounts(nowSec) {
    if (!_resourceLive.planetId || !_resourceLive.syncedAt) return null;
    const elapsed = Math.max(0, Number(nowSec) - _resourceLive.syncedAt);
    if (elapsed <= 0) {
      return {
        metal: _resourceLive.metal,
        crystal: _resourceLive.crystal,
        fuelCells: _resourceLive.fuelCells,
      };
    }
    const hours = elapsed / 3600;
    return {
      metal: projectLiveResourceAmount(_resourceLive.metal, _resourceLive.prodMetal, _resourceLive.capMetal, hours),
      crystal: projectLiveResourceAmount(_resourceLive.crystal, _resourceLive.prodCrystal, _resourceLive.capCrystal, hours),
      fuelCells: projectLiveResourceAmount(_resourceLive.fuelCells, _resourceLive.prodFuelCells, _resourceLive.capFuelCells, hours),
    };
  }

  function tickLiveResourceBar() {
    if (!shouldRunVisualLoops() || _authLoopAborted || !_resourceLive.planetId) return;
    const projected = projectLiveResourceAmounts(getApproxServerNow());
    if (!projected) return;
    patchShellHudLiveResources(projected.metal, projected.crystal, projected.fuelCells);
    tickBoostHudCountdown();
  }

  function _resourceTickerIntervalMs() {
    if (_hasActiveProgressJobs()) return RESOURCE_TICKER_MS_ACTIVE;
    return RESOURCE_TICKER_MS_IDLE;
  }

  function pauseResourceTicker() {
    _resourceTickerPaused = true;
    if (_resourceTickerId != null) {
      clearInterval(_resourceTickerId);
      _resourceTickerId = null;
    }
  }

  function startResourceTicker() {
    if (!shouldRunVisualLoops() || _authLoopAborted || !_resourceLive.planetId) return;
    _resourceTickerPaused = false;
    const intervalMs = _resourceTickerIntervalMs();
    if (_resourceTickerId != null && _resourceTickerCurrentInterval === intervalMs) return;
    if (_resourceTickerId != null) {
      clearInterval(_resourceTickerId);
      _resourceTickerId = null;
    }
    _resourceTickerCurrentInterval = intervalMs;
    tickLiveResourceBar();
    _resourceTickerId = setInterval(tickLiveResourceBar, intervalMs);
  }

  function stopResourceTicker() {
    pauseResourceTicker();
    _resourceTickerPaused = false;
    _resourceLive.planetId = 0;
    _resourceLive.syncedAt = 0;
    _resourceDisplay = { metal: null, crystal: null, fuelCells: null };
  }

  GC.syncResourceLiveBaseline = syncResourceLiveBaseline;
  GC.tickLiveResourceBar = tickLiveResourceBar;

  // Keep last values to avoid DOM churn
  const _last = {
    metal: null,
    crystal: null,
    fuelCells: null,
    energyUsed: null,
    energyTotal: null,
    storageMetal: null,
    storageCrystal: null,
    storageFuelCells: null,
    prodMetal: null,
    prodCrystal: null,
    prodFuelCells: null,
    activePlanetId: null,
    planetLimitCurrent: null,
    planetLimitMax: null,
  };

  function patchHeaderPlanetLimitFromState(data, force) {
    const block = data && data.planet_limit;
    const planets = data && data.planets;
    let owned = Number(block && block.owned_worlds);
    if (!Number.isFinite(owned) && Array.isArray(planets)) {
      owned = planets.length;
    }
    if (!Number.isFinite(owned) && Number.isFinite(Number(block && block.current))) {
      owned = Number(block.current) + 1;
    }
    if (!Number.isFinite(owned) || owned < 0) {
      if (!force) return;
      owned = 0;
    }
    owned = Math.floor(owned);
    const maxRaw = block && block.max;
    const hasLegacyMax = Number.isFinite(Number(maxRaw)) && Number(maxRaw) >= 1;
    const max = hasLegacyMax ? Math.floor(Number(maxRaw)) : null;
    const displayText = hasLegacyMax ? `${fmtNumber(owned)} / ${fmtNumber(max)}` : fmtNumber(owned);
    let title = tf("header_planet_limit", "Planets");
    if (block && block.gate_reason && block.can_expand === false) {
      title = `${title} — ${tf(block.gate_reason, block.gate_reason)}`;
    } else if (block && block.can_expand) {
      title = `${title} — ${tf(
        "expansion_checklist_ready",
        "Your empire is ready — choose a world on the Command Map."
      )}`;
    }
    if (
      !force
      && _last.planetLimitCurrent === owned
      && _last.planetLimitMax === (hasLegacyMax ? max : null)
    ) {
      return;
    }
    _last.planetLimitCurrent = owned;
    _last.planetLimitMax = hasLegacyMax ? max : null;
    document.querySelectorAll("[data-planet-limit-value]").forEach((el) => {
      _setIfChanged(el, displayText);
      if (title) el.setAttribute("title", title);
    });
  }
  GC.patchHeaderPlanetLimitFromState = patchHeaderPlanetLimitFromState;

  function resetResourceDisplayCache() {
    _last.metal = null;
    _last.crystal = null;
    _last.fuelCells = null;
    _last.energyUsed = null;
    _last.energyTotal = null;
    _last.storageMetal = null;
    _last.storageCrystal = null;
    _last.storageFuelCells = null;
    _last.prodMetal = null;
    _last.prodCrystal = null;
    _last.prodFuelCells = null;
    _resourceDisplay = { metal: null, crystal: null, fuelCells: null };
  }

  const BUILDING_ICON_FILE = {
    orbital_shipyard: "shipyard",
    fuel_storage: "fuel_cell_storage",
  };

  function buildingIconUrl(buildingType) {
    const key = String(buildingType || "").trim();
    const file = BUILDING_ICON_FILE[key] || key;
    return GC.preferWebpStaticUrl(`/static/img/buildings/${file}.png`);
  }
  GC.buildingIconUrl = buildingIconUrl;

  // =========================
  // Messages unread badges (game-state polling)
  // =========================
  let _lastMessagesUnreadPoll = null;
  let _lastToastedMessageId = 0;
  let _pendingMessageNotifyItems = [];
  let _messageNotifyBatchTimer = null;
  let _messagesUnreadLocalAt = 0;
  const MESSAGES_UNREAD_LOCAL_GUARD_MS = 30000;
  const MESSAGE_NOTIFY_BATCH_MS = 250;
  const MESSAGE_NOTIFY_GROUP_ORDER = [
    "combat",
    "espionage",
    "expedition",
    "logistics",
    "player",
    "system",
  ];

  function coercePollUnreadForHud(data, reason) {
    if (!data || typeof data.unread_messages_count !== "number") return data;
    const r = String(reason || "");
    if (
      r === "poll"
      || r === "notification_poll"
      || r === "queue_timer_zero"
      || r === "timer_done"
      || r.endsWith("_finished")
      || r.endsWith("_success")
      || r === "messages_sync"
    ) {
      return data;
    }
    const localUnread = GC.lastState?.unread_messages_count;
    if (typeof localUnread !== "number") return data;
    const incomingUnread = data.unread_messages_count;
    if (incomingUnread <= localUnread) return data;
    if (
      _lastMessagesUnreadPoll !== null
      && incomingUnread > _lastMessagesUnreadPoll
    ) {
      return data;
    }
    if (_messagesUnreadLocalAt && Date.now() - _messagesUnreadLocalAt < MESSAGES_UNREAD_LOCAL_GUARD_MS) {
      return { ...data, unread_messages_count: localUnread };
    }
    return data;
  }

  function updateMessagesUnreadBadges(count) {
    const n = Math.max(0, Number(count) || 0);
    const label = n > 99 ? "99+" : String(n);
    document.querySelectorAll("[data-messages-unread-badge]").forEach((el) => {
      if (n > 0) {
        el.textContent = label;
        el.hidden = false;
        el.classList.remove("hidden");
        el.setAttribute("aria-hidden", "false");
      } else {
        el.textContent = "";
        el.hidden = true;
        el.classList.add("hidden");
        el.setAttribute("aria-hidden", "true");
      }
    });
  }
  GC.updateMessagesUnreadBadges = updateMessagesUnreadBadges;
  GC.setMessagesUnreadPollBaseline = function setMessagesUnreadPollBaseline(count) {
    _lastMessagesUnreadPoll = Math.max(0, Number(count) || 0);
  };

  function _messageNotifyGroupKey(item) {
    const cat = String(item?.category || "system").toLowerCase();
    if (cat === "combat" || cat === "espionage" || cat === "expedition" || cat === "player") {
      return cat;
    }
    const mission = String(item?.mission_type || "").toLowerCase();
    const phase = String(item?.report_phase || "").trim();
    if (
      phase
      || mission === "transport"
      || mission === "collect"
      || mission === "deploy"
      || mission === "recycle"
    ) {
      return "logistics";
    }
    return "system";
  }

  function _messageNotifyGroupCopy(groupKey, count) {
    const n = Math.max(1, Math.floor(Number(count) || 1));
    const titleKey = (base) => (n === 1 ? `${base}_one` : base);
    if (groupKey === "expedition") {
      return {
        title: tf(
          titleKey("messages.notify_batch_expedition_title"),
          { count: n },
          n === 1 ? "1 Expedition abgeschlossen" : `${n} Expeditionen abgeschlossen`
        ),
        body: t(
          "messages.notify_batch_expedition_body",
          "Neue Expeditionsberichte sind eingetroffen."
        ),
        filter: "expedition",
      };
    }
    if (groupKey === "combat") {
      return {
        title: tf(
          titleKey("messages.notify_batch_combat_title"),
          { count: n },
          n === 1 ? "1 Kampfbericht" : `${n} Kampfberichte`
        ),
        body: t("messages.notify_batch_combat_body", "Neue Kampfberichte sind eingetroffen."),
        filter: "combat",
      };
    }
    if (groupKey === "espionage") {
      return {
        title: tf(
          titleKey("messages.notify_batch_espionage_title"),
          { count: n },
          n === 1 ? "1 Spionagebericht" : `${n} Spionageberichte`
        ),
        body: t("messages.notify_batch_espionage_body", "Neue Spionageberichte sind eingetroffen."),
        filter: "espionage",
      };
    }
    if (groupKey === "logistics") {
      return {
        title: tf(
          titleKey("messages.notify_batch_logistics_title"),
          { count: n },
          n === 1 ? "1 Logistikbericht" : `${n} Logistikberichte`
        ),
        body: t("messages.notify_batch_logistics_body", "Neue Logistikberichte sind eingetroffen."),
        filter: "system",
      };
    }
    if (groupKey === "player") {
      return {
        title: tf(
          titleKey("messages.notify_batch_player_title"),
          { count: n },
          n === 1 ? "1 Spielernachricht" : `${n} Spielernachrichten`
        ),
        body: t("messages.notify_batch_player_body", "Neue Nachrichten von Spielern."),
        filter: "player",
      };
    }
    if (n > 1) {
      return {
        title: tf("messages.notify_new_count", { count: n }, `Du hast ${n} ungelesene Nachrichten.`),
        body: t("messages.notify_batch_system_body", "Neue Systemmeldungen sind eingetroffen."),
        filter: "system",
      };
    }
    return {
      title: t("messages.notify_new", "Neue Nachricht im Posteingang."),
      body: t("messages.notify_batch_system_body", "Neue Systemmeldungen sind eingetroffen."),
      filter: "all",
    };
  }

  function _openMessagesFilterFromToast(filter) {
    const cat = String(filter || "all");
    try {
      sessionStorage.setItem("gc_messages_prefer_filter", cat);
    } catch (_) {}
    if (typeof GC.navigateTo === "function") {
      GC.navigateTo("/messages");
    }
  }

  function _flushMessageNotifyBatch() {
    _messageNotifyBatchTimer = null;
    const items = _pendingMessageNotifyItems;
    _pendingMessageNotifyItems = [];
    if (!items.length) return;
    if (GC.detectPage() === "messages") return;

    const byGroup = new Map();
    let maxId = _lastToastedMessageId;
    items.forEach((item) => {
      const id = Math.floor(Number(item?.id) || 0);
      if (id > 0) maxId = Math.max(maxId, id);
      const key = _messageNotifyGroupKey(item);
      byGroup.set(key, (byGroup.get(key) || 0) + 1);
    });

    const ordered = MESSAGE_NOTIFY_GROUP_ORDER.filter((k) => byGroup.has(k));
    Object.keys(Object.fromEntries(byGroup)).forEach((k) => {
      if (!ordered.includes(k)) ordered.push(k);
    });

    let toastCount = 0;
    ordered.forEach((groupKey) => {
      const count = byGroup.get(groupKey) || 0;
      if (count <= 0) return;
      const copy = _messageNotifyGroupCopy(groupKey, count);
      const toastEl = typeof GC.showToast === "function"
        ? GC.showToast(copy.body, "info", { title: copy.title })
        : (typeof GC.showNotify === "function" ? GC.showNotify(copy.title, "info") : null);
      toastCount += 1;
      if (toastEl && toastEl.addEventListener) {
        toastEl.style.cursor = "pointer";
        toastEl.addEventListener("click", (ev) => {
          if (ev.target && ev.target.closest && ev.target.closest("[data-gc-toast-dismiss]")) return;
          _openMessagesFilterFromToast(copy.filter);
        });
      }
    });

    if (maxId > _lastToastedMessageId) _lastToastedMessageId = maxId;
    if (typeof GC._debugFleetBatch === "object") {
      GC._debugFleetBatch.visibleToasts = (GC._debugFleetBatch.visibleToasts || 0) + toastCount;
      GC._debugFleetBatch.batchedMessageItems = items.length;
    }
  }

  function _queueMessageNotifyItems(items) {
    const list = Array.isArray(items) ? items : [];
    if (!list.length) return;
    const fresh = [];
    list.forEach((item) => {
      const id = Math.floor(Number(item?.id) || 0);
      if (id > 0 && id <= _lastToastedMessageId) return;
      fresh.push(item);
    });
    if (!fresh.length) return;
    _pendingMessageNotifyItems.push(...fresh);
    if (_messageNotifyBatchTimer) clearTimeout(_messageNotifyBatchTimer);
    _messageNotifyBatchTimer = setTimeout(_flushMessageNotifyBatch, MESSAGE_NOTIFY_BATCH_MS);
  }

  function _extractNotificationToastItems(data, unreadDelta) {
    const fromSlice = data?.notifications?.new_items;
    if (Array.isArray(fromSlice) && fromSlice.length) {
      return fromSlice.filter((item) => {
        const id = Math.floor(Number(item?.id) || 0);
        return id > _lastToastedMessageId;
      });
    }
    const delta = Math.max(0, Math.floor(Number(unreadDelta) || 0));
    if (delta <= 0) return [];
    const latest = Math.floor(Number(data?.latest_message_id) || 0);
    if (latest <= _lastToastedMessageId) return [];
    // Fallback without category slice: synthetic ids so batch count matches unread delta.
    const items = [];
    for (let i = 0; i < delta; i += 1) {
      const id = Math.max(_lastToastedMessageId + 1, latest - (delta - 1 - i));
      items.push({ id, category: "system", mission_type: null });
    }
    return items;
  }

  function _processUnreadMessagesPoll(data, reason, opts) {
    if (!data || typeof data.unread_messages_count !== "number") return;
    if (opts && opts.skipMessagesUnread) return;

    const onMessagesPage = GC.detectPage() === "messages";
    const hudUnread = coercePollUnreadForHud(data, reason).unread_messages_count;
    const prevUnread = _lastMessagesUnreadPoll;
    const unreadIncreased = prevUnread !== null && hudUnread > prevUnread;
    const unreadDelta = unreadIncreased ? hudUnread - prevUnread : 0;
    const messageSoundKey = resolveMessageNotifySoundKey(data);
    const latestId = Math.floor(Number(data.latest_message_id) || 0);

    if (unreadIncreased || messageSoundKey) {
      console.debug("[GC] notify check", {
        kind: "message",
        unreadCount: hudUnread,
        previousUnread: prevUnread,
        unreadIncreased,
        unreadDelta,
        latestMessageId: data.latest_message_id,
        messageSoundKey,
        notifyMessageSound: GC.settings?.notify_message_sound,
        audioUnlocked: _notifyAudioUnlocked,
      });
    }

    _lastMessagesUnreadPoll = hudUnread;

    const toastItems = unreadIncreased
      ? _extractNotificationToastItems(data, unreadDelta)
      : [];

    // Sound once per batch via latest_message_id dedupe (not per unread step).
    if (toastItems.length || (unreadIncreased && latestId > _lastToastedMessageId)) {
      _maybePlayMessageNotifySound(data, { unreadIncreased: true });
    }

    if (toastItems.length && !onMessagesPage) {
      _queueMessageNotifyItems(toastItems);
    } else if (latestId > _lastToastedMessageId && !toastItems.length) {
      // Baseline advance when toast skipped (e.g. messages page / no delta items).
      _lastToastedMessageId = latestId;
    }

    if (
      unreadIncreased &&
      onMessagesPage
    ) {
      if (
        GC.messagesPageState &&
        GC.messagesPageState.listLoaded &&
        !GC.messagesPageState.loading &&
        typeof GC.messagesPageState.loadList === "function"
      ) {
        GC.messagesPageState.loadList();
      } else if (typeof GC.bootMessagesInbox === "function") {
        GC.bootMessagesInbox({ force: true, pjax: true });
      }
    }
  }

  function updateNavBadges(navBadges) {
    const badges = navBadges && typeof navBadges === "object" ? navBadges : {};
    document.querySelectorAll("[data-nav-badge]").forEach((el) => {
      const key = el.getAttribute("data-nav-badge");
      if (!key) return;
      const entry = badges[key];
      const link = el.closest(".gc-nav-sub-link, a[data-nav-module]");
      if (key === "world_boss" && link) {
        const live = !!(entry && entry.active);
        link.classList.toggle("gc-nav-sub-link--wb-live", live);
        el.classList.toggle("gc-nav-badge--wb-live", live);
      }
      if (!entry || !entry.active) {
        el.textContent = "";
        el.hidden = true;
        el.classList.add("hidden");
        el.setAttribute("aria-hidden", "true");
        el.removeAttribute("aria-label");
        return;
      }
      const count = Math.max(0, Number(entry.count) || 0);
      const label = entry.label != null && String(entry.label) !== ""
        ? String(entry.label)
        : (count > 0 ? String(count > 99 ? "99+" : count) : "!");
      el.textContent = label;
      el.hidden = false;
      el.classList.remove("hidden");
      el.setAttribute("aria-hidden", "false");
      const ariaKey = key === "vote_center"
        ? "nav_badge_vote_center_aria"
        : key === "government"
          ? "nav_badge_government_aria"
          : key === "referrals"
            ? "nav_badge_referrals_aria"
            : key === "imperial_directives"
              ? "nav_badge_imperial_directives_aria"
              : key === "world_boss"
                ? "nav_badge_world_boss_aria"
              : key === "alliance"
                ? "nav_badge_alliance_aria"
              : key === "community"
              ? "nav_badge_community_aria"
              : "";
      if (ariaKey) {
        el.setAttribute(
          "aria-label",
          t(ariaKey, key === "vote_center"
            ? "Vote verfügbar"
            : key === "referrals"
              ? "Referral-Belohnung verfügbar"
              : key === "imperial_directives"
                ? "Imperial Directive abholbereit"
                : key === "world_boss"
                  ? "World Boss aktiv"
                : key === "alliance"
                  ? "Allianz-Bewerbung ausstehend"
                : "Abstimmung offen")
        );
      }
    });
    // Ensure world_boss live class clears even if badge node missing.
    document.querySelectorAll('[data-nav-module="world_boss"]').forEach((link) => {
      const entry = badges.world_boss;
      const live = !!(entry && entry.active);
      link.classList.toggle("gc-nav-sub-link--wb-live", live);
    });
  }
  GC.updateNavBadges = updateNavBadges;

  let _lastHudOnline = null;
  let _globalFleetDrawerBound = false;
  const FLEET_DRAWER_LS_SHOW_ALL = "gc:fleetDrawer:showAll";

  function resolveFleetDrawerCountdownAt(mv) {
    if (!mv || typeof mv !== "object") return 0;
    const status = String(mv.status || mv.phase || mv.leg_phase || "").toLowerCase();
    const direct = Number(mv.countdown_at || 0);
    if (direct > 0) return direct;
    // Holding must use holding_until — never fall back to past arrival_at.
    if (status === "holding") {
      const hold = Number(mv.holding_until || 0);
      if (hold > 0) return hold;
    }
    if (status === "returning") {
      const ret = Number(mv.return_at || mv.home_at || 0);
      if (ret > 0) return ret;
    }
    const arrival = Number(mv.arrival_at || 0);
    if (arrival > 0) return arrival;
    return Number(mv.return_at || mv.home_at || mv.holding_until || 0) || 0;
  }

  function normalizeFleetDrawerItem(mv) {
    if (!mv || typeof mv !== "object") return mv;
    const mission = String(mv.mission || mv.mission_type || "transport").trim().toLowerCase();
    const movementId = Number(mv.movement_id || mv.id || 0);
    let shipsBreakdown = Array.isArray(mv.ships_breakdown) ? mv.ships_breakdown : null;
    if (!shipsBreakdown && mv.ships && typeof mv.ships === "object") {
      shipsBreakdown = Object.entries(mv.ships)
        .filter(([, qty]) => Number(qty) > 0)
        .map(([key, qty]) => ({
          key: String(key),
          label_key: `fleet_ship_${key}`,
          count: Number(qty),
        }));
    }
    const res = mv.loaded_resources || mv.resources || {};
    return {
      ...mv,
      movement_id: movementId || Number(mv.movement_id || 0),
      id: movementId || Number(mv.id || 0),
      mission,
      mission_type: mission,
      mission_label_key: mv.mission_label_key || `fleet_mission_${mission}`,
      ships_breakdown: shipsBreakdown || [],
      loaded_resources: {
        metal: Number(res.metal || 0),
        crystal: Number(res.crystal || 0),
        fuel_cells: Number(res.fuel_cells || 0),
      },
      remaining_seconds: Math.max(0, Number(mv.remaining_seconds || 0)),
      countdown_at: resolveFleetDrawerCountdownAt(mv),
    };
  }

  function isActiveFleetsPayloadMissing(raw) {
    if (raw === null || raw === undefined) return true;
    if (typeof raw !== "object") return true;
    if (Array.isArray(raw)) return false;
    return !Array.isArray(raw.items);
  }

  function isExplicitEmptyActiveFleets(raw) {
    return isFleetHudConfirmedEmpty(raw);
  }

  function isFleetHudConfirmedEmpty(raw) {
    if (isActiveFleetsPayloadMissing(raw)) return false;
    if (raw.fleets_confirmed_empty === true) return true;
    if (Object.prototype.hasOwnProperty.call(raw, "active_fleet_count")) {
      return Number(raw.active_fleet_count) === 0;
    }
    return false;
  }

  function bumpFleetHudActionVersion(state) {
    const version = extractStateVersion(state);
    const bump = version > 0 ? version : getTimerServerNow();
    _fleetHudActionVersion = Math.max(_fleetHudActionVersion, bump);
    _fleetHudLastAppliedVersion = Math.max(_fleetHudLastAppliedVersion, bump);
  }

  function canClearFleetHudToEmpty(raw, opts, stateVersion) {
    if (!isFleetHudConfirmedEmpty(raw)) return false;
    if (opts && opts.allowEmptyClear) return true;
    const version = Number(stateVersion || 0);
    if (version > 0 && version >= _fleetHudActionVersion - 0.001) return true;
    if (opts && opts.authoritativeFleetHud && isMutationStatePatchReason(String(opts.reason || ""))) {
      return true;
    }
    return false;
  }

  function mergeFleetMovementIntoHud(mv, opts) {
    const item = normalizeFleetDrawerItem(mv);
    const movementId = String(item.movement_id || item.id || "");
    if (!movementId) return;
    const base = _fleetHudStickyPayload || normalizeActiveFleetsPayload({ items: [], count: 0 });
    const items = [
      item,
      ...base.items.filter((row) => String(row.movement_id || row.id || "") !== movementId),
    ];
    const payload = {
      ...base,
      count: items.length,
      active_fleet_count: items.length,
      fleets_confirmed_empty: false,
      items,
    };
    _fleetHudStickyPayload = payload;
    bumpFleetHudActionVersion({ server_time: getTimerServerNow() });
    renderGlobalFleetHud(payload, {
      ...(opts || {}),
      sticky: true,
      authoritativeFleetHud: true,
      reason: (opts && opts.reason) || "fleet_send_merge",
    });
  }
  GC.mergeFleetMovementIntoHud = mergeFleetMovementIntoHud;

  function preserveFleetHudAcrossNavigation() {
    if (!_fleetHudStickyPayload || !_fleetHudStickyPayload.count) return;
    renderGlobalFleetHud(_fleetHudStickyPayload, {
      sticky: true,
      reason: "pjax_preserve",
      authoritativeFleetHud: false,
    });
  }
  GC.preserveFleetHudAcrossNavigation = preserveFleetHudAcrossNavigation;

  function patchFleetHudFromActionPayload(json, reason) {
    const reasonStr = String(reason || "");
    const state = json?.state || json?.data?.state || null;
    const liveFleet = json?.data?.fleet || json?.fleet || null;
    if (liveFleet) {
      mergeFleetMovementIntoHud(liveFleet, { reason: reasonStr, allowEmptyClear: false });
    }
    if (state && state.active_fleets !== undefined) {
      bumpFleetHudActionVersion(state);
      const incoming = normalizeActiveFleetsPayload(state.active_fleets);
      const stickyCount = Number(_fleetHudStickyPayload?.count || 0);
      const serverConfirmedEmpty = isFleetHudConfirmedEmpty(state.active_fleets);
      const stateVersion = extractStateVersion(state);
      const canClearEmpty = canClearFleetHudToEmpty(state.active_fleets, {
        reason: reasonStr,
        authoritativeFleetHud: true,
        allowEmptyClear: isMutationStatePatchReason(reasonStr) && serverConfirmedEmpty,
      }, stateVersion);
      if (stickyCount > 0 && incoming.count === 0 && !canClearEmpty) {
        renderGlobalFleetHud(_fleetHudStickyPayload, {
          reason: reasonStr,
          sticky: true,
          authoritativeFleetHud: false,
          allowEmptyClear: false,
        });
      } else {
        renderGlobalFleetHud(state.active_fleets, {
          reason: reasonStr,
          stateVersion,
          stateContext: state,
          authoritativeFleetHud: true,
          allowEmptyClear: canClearEmpty,
        });
      }
    } else if (isMutationStatePatchReason(reasonStr)) {
      bumpFleetHudActionVersion(state || { server_time: getTimerServerNow() });
    }
  }
  GC.patchFleetHudFromActionPayload = patchFleetHudFromActionPayload;

  function isAuthoritativeFleetHudReason(reason, opts) {
    const r = String(reason || "");
    if (opts && (opts.authoritativeFleetHud || opts.forceApply || opts.allowResourceRegression)) return true;
    if (isAuthoritativeGameStateReason(r, opts)) return true;
    return (
      r === "poll"
      || r === "page_init"
      || r === "tab_visible"
      || r === "pjax_nav"
      || r === "fleet_countdown_expired"
      || r === "fleet_drawer_boot"
      || r === "page_hydrate"
      || isMutationStatePatchReason(r)
    );
  }

  function resolveFleetHudPayload(raw, opts) {
    const reason = String((opts && opts.reason) || "");
    const stateVersion = Number(
      (opts && opts.stateVersion) || extractStateVersion(opts && opts.stateContext)
    );
    const authoritative = isAuthoritativeFleetHudReason(reason, opts);

    if (isActiveFleetsPayloadMissing(raw)) {
      return _fleetHudStickyPayload
        ? { payload: _fleetHudStickyPayload, explicitEmpty: false, authoritative: false, missing: true }
        : null;
    }

    const normalized = normalizeActiveFleetsPayload(raw);
    const hasFleets = normalized.count > 0 || normalized.items.length > 0;

    if (hasFleets) {
      _fleetHudStickyPayload = {
        ...normalized,
        active_fleet_count: normalized.count,
        fleets_confirmed_empty: false,
      };
      if (stateVersion > 0) {
        _fleetHudLastAppliedVersion = Math.max(_fleetHudLastAppliedVersion, stateVersion);
      }
      return { payload: _fleetHudStickyPayload, explicitEmpty: false, authoritative: true };
    }

    const confirmedEmpty = canClearFleetHudToEmpty(raw, opts, stateVersion);
    if (!confirmedEmpty) {
      return _fleetHudStickyPayload
        ? { payload: _fleetHudStickyPayload, explicitEmpty: false, authoritative: false }
        : { payload: normalized, explicitEmpty: false, authoritative: false };
    }

    if (
      stateVersion > 0
      && _fleetHudLastAppliedVersion > 0
      && stateVersion < _fleetHudLastAppliedVersion - 0.001
      && stateVersion < _fleetHudActionVersion - 0.001
    ) {
      return _fleetHudStickyPayload
        ? { payload: _fleetHudStickyPayload, explicitEmpty: false, authoritative: false }
        : { payload: normalized, explicitEmpty: false, authoritative: false };
    }

    _fleetHudStickyPayload = {
      ...normalized,
      active_fleet_count: 0,
      fleets_confirmed_empty: true,
    };
    if (stateVersion > 0) {
      _fleetHudLastAppliedVersion = Math.max(_fleetHudLastAppliedVersion, stateVersion);
    }
    return { payload: _fleetHudStickyPayload, explicitEmpty: true, authoritative: authoritative };
  }
  GC.resolveFleetHudPayload = resolveFleetHudPayload;

  const FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT = 1;

  function normalizeActiveFleetsPayload(raw) {
    if (!raw) {
      return { count: 0, visible_limit: FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT, next_remaining_seconds: 0, items: [] };
    }
    if (Array.isArray(raw)) {
      const items = raw.map(normalizeFleetDrawerItem);
      const primary = items.length ? pickPrimaryFleetMovement(items) : null;
      return {
        count: items.length,
        visible_limit: FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT,
        next_remaining_seconds: Number(primary?.remaining_seconds || 0),
        items,
      };
    }
    const items = (Array.isArray(raw.items) ? raw.items : []).map(normalizeFleetDrawerItem);
    return {
      count: Number(raw.count) || items.length,
      visible_limit: Number(raw.visible_limit) || FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT,
      next_remaining_seconds: Number(raw.next_remaining_seconds) || 0,
      items,
    };
  }
  GC.normalizeActiveFleetsPayload = normalizeActiveFleetsPayload;

  function activeFleetsItems(raw) {
    return normalizeActiveFleetsPayload(raw).items;
  }

  function isFleetDrawerShowAll() {
    return localStorage.getItem(FLEET_DRAWER_LS_SHOW_ALL) === "1";
  }

  function setFleetDrawerShowAll(showAll) {
    localStorage.setItem(FLEET_DRAWER_LS_SHOW_ALL, showAll ? "1" : "0");
  }

  function isMobileFleetSheetViewport() {
    return window.matchMedia("(max-width: 768px)").matches;
  }

  /** Mobile sheet is the fleet window — expand with ≥1 fleet; desktop only needs overflow. */
  function canExpandFleetDrawer(count, visibleLimit) {
    const n = Math.max(0, Number(count) || 0);
    if (n <= 0) return false;
    if (isMobileFleetSheetViewport()) return true;
    return n > Math.max(1, Number(visibleLimit) || FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT);
  }

  function getFleetSheetBackdrop() {
    let backdrop = document.getElementById("gc-fleet-sheet-backdrop");
    if (!backdrop) {
      backdrop = document.createElement("button");
      backdrop.type = "button";
      backdrop.id = "gc-fleet-sheet-backdrop";
      backdrop.className = "gc-fleet-sheet-backdrop";
      backdrop.hidden = true;
      backdrop.setAttribute("aria-label", t("close", "Schließen"));
      document.body.appendChild(backdrop);
      backdrop.addEventListener("click", () => {
        if (!isFleetDrawerShowAll()) return;
        setFleetDrawerShowAll(false);
        if (GC.lastState?.active_fleets) {
          renderGlobalFleetHud(GC.lastState.active_fleets);
        } else if (typeof GC.renderGlobalFleetHud === "function") {
          renderGlobalFleetHud(null);
        }
      });
    }
    return backdrop;
  }

  let _fleetSheetAnchor = null;

  function _ensureFleetSheetAnchor(root) {
    if (!root || _fleetSheetAnchor?.parentNode) return;
    const home = _fleetSheetHomeEl();
    if (!home) return;
    const parent = root.parentNode;
    // Never park the restore marker in the sheet portal or empty parents.
    if (!parent || parent === document.body) return;
    _fleetSheetAnchor = document.createComment("gc-fleet-sheet-anchor");
    if (parent === home) {
      home.insertBefore(_fleetSheetAnchor, root);
      return;
    }
    // Root already docked in header slot: mark sticky restore point.
    const bar = home.querySelector("#resource-bar, .resource-bar.resource-bar-cmd");
    if (bar) {
      home.insertBefore(_fleetSheetAnchor, bar.nextSibling);
    } else {
      home.appendChild(_fleetSheetAnchor);
    }
  }

  function _fleetSheetHomeEl() {
    // Must be .gc-resource-sticky — never .resource-bar (CSS grid squeezes drawer to 1 col).
    return document.querySelector(".gc-header-cmd .gc-resource-sticky")
      || document.querySelector(".gc-header-row-resources .gc-resource-sticky")
      || document.querySelector(".gc-resource-sticky");
  }

  function _restoreFleetSheetPortal(root) {
    if (!root) return;
    root.classList.remove("gc-fleet-sheet-portal");
    root.classList.remove("gc-fleet-hud--header-slot");
    const sticky = _fleetSheetHomeEl();
    if (!sticky) return;
    const parent = root.parentNode;
    const insideResourceBar = !!(parent && parent.classList && parent.classList.contains("resource-bar"));
    const needsMove = parent === document.body || insideResourceBar || parent !== sticky;
    if (!needsMove) return;
    if (_fleetSheetAnchor?.parentNode === sticky) {
      sticky.insertBefore(root, _fleetSheetAnchor.nextSibling);
      return;
    }
    const bar = sticky.querySelector("#resource-bar, .resource-bar.resource-bar-cmd");
    if (bar) {
      sticky.insertBefore(root, bar.nextSibling);
      return;
    }
    sticky.appendChild(root);
  }

  function isMobileHeaderFleetViewport() {
    return window.matchMedia("(max-width: 768px)").matches;
  }

  function syncHeaderFleetsToggle(expanded) {
    const btn = document.getElementById("gc-header-fleets-toggle");
    if (!btn) return;
    btn.setAttribute("aria-expanded", expanded ? "true" : "false");
    btn.classList.toggle("is-active", !!expanded);
  }

  function toggleHeaderFleetSheet() {
    const root = document.getElementById("global-fleet-drawer-root")
      || document.querySelector("[data-global-fleet-drawer]");
    if (!root) return;
    const willExpand = !isFleetDrawerShowAll();
    setFleetDrawerShowAll(willExpand);
    if (GC.lastState?.active_fleets) {
      renderGlobalFleetHud(GC.lastState.active_fleets);
    } else {
      syncMobileFleetSheetLayout(root);
      syncHeaderFleetsToggle(willExpand);
    }
  }

  function syncMobileHeaderFleetSlot(root) {
    // Phone: keep drawer in resource sticky (CSS-hidden when collapsed).
    // Header shows icon+badge only — never dock the full HUD into the meta row.
    if (!root) return;
    root.classList.remove("gc-fleet-hud--header-slot");
    syncHeaderFleetsToggle(
      !!(root.classList.contains("is-show-all") && isMobileFleetSheetViewport())
    );
  }

  function syncMobileFleetSheetTop() {
    if (!isMobileFleetSheetViewport()) return;
    const resourcesRow = document.querySelector(".gc-header-cmd .gc-header-row-resources");
    const sticky = document.querySelector(".gc-resource-sticky");
    const anchor = resourcesRow || sticky || document.querySelector(".gc-header-cmd .gc-header-inner");
    const bottom = anchor ? Math.ceil(anchor.getBoundingClientRect().bottom) : 96;
    document.documentElement.style.setProperty("--gc-fleet-sheet-top", `${Math.max(bottom + 4, 72)}px`);
  }

  function syncMobileFleetSheetLayout(root) {
    const expanded = !!(root && root.classList.contains("is-show-all") && isMobileFleetSheetViewport());
    const backdrop = getFleetSheetBackdrop();
    backdrop.hidden = !expanded;
    document.body.classList.toggle("gc-fleet-sheet-open", expanded);
    syncHeaderFleetsToggle(expanded);
    if (!root) return;
    if (expanded) {
      _ensureFleetSheetAnchor(root);
      if (root.parentNode !== document.body) {
        document.body.appendChild(root);
      }
      root.classList.add("gc-fleet-sheet-portal");
      root.classList.remove("gc-fleet-hud--header-slot");
      syncMobileFleetSheetTop();
      root.setAttribute("aria-expanded", "true");
    } else {
      closeAllFleetDrawerRowDetails(root);
      _restoreFleetSheetPortal(root);
      root.setAttribute("aria-expanded", "false");
      syncMobileHeaderFleetSlot(root);
    }
  }

  function formatFleetDrawerRoute(mv) {
    if (!mv || typeof mv !== "object") return "–";
    const originName = String(mv.origin_name || "").trim();
    const originCoords = String(mv.origin_coords || "").trim();
    const targetName = String(mv.target_name || formatGlobalFleetHudTarget(mv) || "").trim();
    const targetCoords = String(mv.target_coords || "").trim();
    const origin = originName && originCoords ? `${originName} ${originCoords}` : (originCoords || originName || "–");
    const target = targetName && targetCoords && targetName !== targetCoords
      ? `${targetName} ${targetCoords}`
      : (targetCoords || targetName || "–");
    return `${origin} → ${target}`;
  }

  const _fleetDrawerMovementById = new Map();
  let _fleetDrawerTooltipEl = null;
  let _fleetDrawerTooltipTrigger = null;

  function fleetDrawerCountdownAt(mv) {
    return resolveFleetDrawerCountdownAt(mv);
  }

  function fleetDrawerRemainingSeconds(mv, serverNow) {
    const countdownAt = fleetDrawerCountdownAt(mv);
    if (!countdownAt) return 0;
    const srvRem = Number(mv?.remaining_seconds);
    return movementRemainingSeconds(
      countdownAt,
      serverNow ?? getTimerServerNow(),
      Number.isFinite(srvRem) && srvRem >= 0 ? srvRem : NaN
    );
  }

  function formatFleetDrawerRemaining(seconds) {
    const s = Math.max(0, Math.floor(Number(seconds) || 0));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
  }

  function formatFleetDrawerArrivalCompact(seconds) {
    return formatCountdownRemain(seconds);
  }

  function fleetDrawerTotalShips(mv) {
    const ships = Array.isArray(mv?.ships_breakdown) ? mv.ships_breakdown : [];
    return ships.reduce((sum, s) => sum + Math.max(0, Number(s.count || 0)), 0);
  }

  function notifyFleetDrawerLayoutChange() {
    if (typeof GC.syncSidebarSticky === "function") {
      requestAnimationFrame(() => GC.syncSidebarSticky());
    }
  }

  function updateFleetDrawerRowTimers(serverNow) {
    const now = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();
    updateFleetAttackAlertCountdown(now);
    document.querySelectorAll("[data-fleet-drawer-row]").forEach((row) => {
      if (row.hasAttribute("data-fleet-alert")) return;
      const movementId = Number(row.dataset.movementId || 0);
      const mv = movementId ? _fleetDrawerMovementById.get(movementId) : null;
      const cdEl = row.querySelector("[data-fleet-drawer-countdown]");
      if (!cdEl) return;
      let target = parseTimerTarget(cdEl.dataset.timerTarget || cdEl.dataset.countdownAt || 0);
      if (!target && mv) {
        patchFleetDrawerRowCountdown(row, mv);
        target = parseTimerTarget(cdEl.dataset.timerTarget || cdEl.dataset.countdownAt || 0);
      }
      if (!target) return;
      // Prefer DOM countdown target — never mix with a different mv phase target
      // (that flipped timer ↔ "Ankunft" / mission-like labels every tick).
      const srvRem = cdEl.dataset.serverRemaining;
      let remaining = movementRemainingSeconds(
        target,
        now,
        srvRem === undefined || srvRem === "" ? NaN : Number(srvRem)
      );
      if (
        mv
        && Number.isFinite(Number(mv.remaining_seconds))
        && fleetDrawerCountdownAt(mv) === target
      ) {
        remaining = movementRemainingSeconds(target, now, Number(mv.remaining_seconds));
      }
      // If DOM target is stale (e.g. past arrival_at) but server still has remaining,
      // re-bind to the live countdown_at instead of locking at 0s.
      const srvLiveRem = mv ? Math.max(0, Number(mv.remaining_seconds || 0)) : 0;
      const liveTarget = mv ? fleetDrawerCountdownAt(mv) : 0;
      if (remaining <= 0 && srvLiveRem > 0 && liveTarget > target) {
        delete cdEl.dataset.fleetArrivedKey;
        patchFleetDrawerRowCountdown(row, mv);
        target = parseTimerTarget(cdEl.dataset.timerTarget || cdEl.dataset.countdownAt || 0) || liveTarget;
        remaining = movementRemainingSeconds(target, now, srvLiveRem);
      }
      if (remaining <= 0) {
        // Stable numeric zero — no status words in the time column.
        _setIfChanged(cdEl, "0s");
        row.classList.add("is-arrived");
        cdEl.classList.add("is-arrived");
        remaining = 0;
      } else {
        delete cdEl.dataset.fleetArrivedKey;
        _setIfChanged(cdEl, formatCountdownRemain(remaining));
        row.classList.remove("is-arrived");
        cdEl.classList.remove("is-arrived");
      }
      const urgent = remaining > 0 && remaining < 10;
      row.classList.toggle("is-urgent", urgent);
      cdEl.classList.toggle("is-urgent", urgent);
      if (mv) patchFleetHudFlightTrack(row, mv, remaining);
    });
    // Collapsed rows are not in the DOM — still expire from the remembered map.
    if (hasExpiredFleetDrawerMovement(now)) {
      requestMovementCountdownRefresh("fleet");
    }
  }

  function hasExpiredFleetDrawerMovement(serverNow) {
    const now = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();
    for (const mv of _fleetDrawerMovementById.values()) {
      const remaining = fleetDrawerRemainingSeconds(mv, now);
      if (remaining <= 0 && fleetDrawerCountdownAt(mv) > 0) return true;
    }
    return false;
  }

  function rememberFleetDrawerMovements(items) {
    _fleetDrawerMovementById.clear();
    (items || []).forEach((mv) => {
      const id = Number(mv.movement_id || mv.id || 0);
      if (id) _fleetDrawerMovementById.set(id, mv);
    });
  }

  function fleetDrawerHoverTooltipsEnabled() {
    return window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  }

  function buildFleetDrawerTooltipHtml(mv) {
    if (!mv || typeof mv !== "object") return "";
    const mission = String(mv.mission || mv.mission_type || "custom");
    const missionKey = mv.mission_label_key || `fleet_mission_${mission}`;
    const status = String(mv.status || mv.phase || "");
    const legKey = globalFleetLegKey(mv, status);
    const targetLabel = `${String(mv.target_name || "").trim()} ${String(mv.target_coords || "").trim()}`.trim()
      || formatGlobalFleetHudTarget(mv);
    const ships = Array.isArray(mv.ships_breakdown) ? mv.ships_breakdown : [];
    const shipLines = ships.length
      ? ships.map((s) => `${t(s.label_key || `fleet_ship_${s.key}`, shipDisplayName(s.key))} × ${fmtNumber(s.count)}`).join("<br>")
      : tf("fleet_drawer_tooltip_no_ships", {}, "Keine Schiffe");
    const res = mv.loaded_resources || mv.resources || {};
    const metal = Number(res.metal || 0);
    const crystal = Number(res.crystal || 0);
    const fuel = Number(res.fuel_cells || 0);
    const countdownAt = fleetDrawerCountdownAt(mv);
    const rem = countdownAt
      ? formatCountdownRemain(fleetDrawerRemainingSeconds(mv, getTimerServerNow()))
      : "–";
    const rows = [
      `<div class="gc-fleet-drawer-tooltip-title">${t(missionKey, mission)}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_drawer_tooltip_ships", "Schiffe")}</span>${shipLines}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_drawer_tooltip_cargo", "Fracht")}</span>`,
      `${t("resource_metal", "Ferronit")}: ${fmtNumber(metal)}<br>`,
      `${t("resource_crystal", "Crytite")}: ${fmtNumber(crystal)}<br>`,
      `${t("resource_fuel_cells", "Brennzellen")}: ${fmtNumber(fuel)}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_mission_label", "Mission")}</span>${t(missionKey, mission)}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_drawer_tooltip_status", "Status")}</span>${t(legKey, legKey)}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_drawer_tooltip_target", "Ziel")}</span>${targetLabel.replace(/</g, "&lt;")}</div>`,
      `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${t("fleet_drawer_arrival_in", "Ankunft in:")}</span>${rem}</div>`,
    ];
    return rows.join("");
  }

  function positionFleetDrawerTooltip(tooltip, trigger) {
    if (!tooltip || !trigger) return;
    const margin = 8;
    tooltip.hidden = false;
    tooltip.style.visibility = "hidden";
    tooltip.style.display = "block";
    const rect = trigger.getBoundingClientRect();
    const tipRect = tooltip.getBoundingClientRect();
    let left = rect.left;
    let top = rect.bottom + margin;
    if (left + tipRect.width > window.innerWidth - margin) {
      left = Math.max(margin, window.innerWidth - tipRect.width - margin);
    }
    if (top + tipRect.height > window.innerHeight - margin) {
      top = Math.max(margin, rect.top - tipRect.height - margin);
    }
    tooltip.style.left = `${left}px`;
    tooltip.style.top = `${top}px`;
    tooltip.style.visibility = "visible";
  }

  function hideFleetDrawerTooltip() {
    if (_fleetDrawerTooltipEl) {
      _fleetDrawerTooltipEl.hidden = true;
      _fleetDrawerTooltipEl.innerHTML = "";
    }
    if (_fleetDrawerTooltipTrigger) {
      _fleetDrawerTooltipTrigger.removeAttribute("aria-describedby");
      _fleetDrawerTooltipTrigger = null;
    }
  }

  function showFleetDrawerTooltip(trigger, mv) {
    if (!fleetDrawerHoverTooltipsEnabled() || !trigger || !mv) return;
    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    const tooltip = root?.querySelector("[data-fleet-drawer-tooltip]") || document.getElementById("gc-fleet-drawer-tooltip");
    if (!tooltip) return;
    _fleetDrawerTooltipEl = tooltip;
    _fleetDrawerTooltipTrigger = trigger;
    tooltip.innerHTML = buildFleetDrawerTooltipHtml(mv);
    tooltip.hidden = false;
    trigger.setAttribute("aria-describedby", "gc-fleet-drawer-tooltip");
    positionFleetDrawerTooltip(tooltip, trigger);
  }

  function closeFleetDrawerRowDetail(row) {
    if (!row) return;
    row.classList.remove("is-detail-open");
    row.setAttribute("aria-expanded", "false");
    const detail = row.querySelector("[data-fleet-drawer-detail]");
    if (detail) {
      detail.hidden = true;
      detail.innerHTML = "";
    }
  }

  function closeAllFleetDrawerRowDetails(scope) {
    const root = scope
      || document.getElementById("global-fleet-drawer-root")
      || document.querySelector("[data-global-fleet-drawer]")
      || document;
    root.querySelectorAll("[data-fleet-drawer-row].is-detail-open").forEach((row) => {
      closeFleetDrawerRowDetail(row);
    });
  }

  function ensureFleetDrawerRowDetailEl(row) {
    if (!row) return null;
    let detail = row.querySelector("[data-fleet-drawer-detail]");
    if (detail) return detail;
    detail = document.createElement("div");
    detail.className = "gc-fleet-drawer-row-detail";
    detail.dataset.fleetDrawerDetail = "1";
    detail.hidden = true;
    detail.setAttribute("role", "region");
    row.appendChild(detail);
    return detail;
  }

  function refreshFleetDrawerRowDetail(row, mv) {
    if (!row || !row.classList.contains("is-detail-open") || !mv) return;
    const detail = ensureFleetDrawerRowDetailEl(row);
    if (!detail) return;
    detail.innerHTML = buildFleetDrawerTooltipHtml(mv);
    detail.hidden = false;
  }

  function openFleetDrawerRowDetail(row, mv) {
    if (!row || !mv) return;
    const root = document.getElementById("global-fleet-drawer-root")
      || document.querySelector("[data-global-fleet-drawer]");
    if (root) closeAllFleetDrawerRowDetails(root);
    const detail = ensureFleetDrawerRowDetailEl(row);
    if (!detail) return;
    detail.innerHTML = buildFleetDrawerTooltipHtml(mv);
    detail.hidden = false;
    row.classList.add("is-detail-open");
    row.setAttribute("aria-expanded", "true");
  }

  function toggleFleetDrawerRowDetail(row, mv) {
    if (!row || !mv) return;
    if (row.classList.contains("is-detail-open")) {
      closeFleetDrawerRowDetail(row);
      return;
    }
    openFleetDrawerRowDetail(row, mv);
  }

  function fleetDrawerFlightProgress(mv) {
    const pct = Number(mv?.progress_pct);
    if (Number.isFinite(pct)) return Math.max(0, Math.min(100, pct));
    const total = Math.max(1, Number(mv?.total_seconds || mv?.duration_seconds || mv?.flight_seconds || 0));
    const rem = Math.max(0, Number(mv?.remaining_seconds || 0));
    return Math.max(0, Math.min(100, Math.round(((total - rem) / total) * 100)));
  }

  function fleetDrawerRowCanAct(mv) {
    const status = String(mv?.status || mv?.phase || mv?.leg_phase || "").toLowerCase();
    return status === "outbound" || status === "holding";
  }

  function fleetDrawerMovementIdFromMv(mv) {
    return String(mv?.movement_id || mv?.id || "").trim();
  }

  function fleetDrawerResolveMovementId(btn) {
    if (!btn) return 0;
    let id = parseInt(btn.dataset.movementId || "0", 10);
    if (id > 0) return id;
    const row = btn.closest("[data-fleet-drawer-row]");
    if (row) {
      id = parseInt(row.dataset.movementId || "0", 10);
      if (id > 0) return id;
    }
    return 0;
  }

  function upsertFleetDrawerActionBtn(wrap, movementId, mv, canAct) {
    if (!wrap) return;
    let btn = wrap.querySelector("[data-fleet-drawer-recall]");
    if (!canAct || !movementId) {
      if (btn) btn.remove();
      return;
    }
    const status = String(mv.status || mv.phase || mv.leg_phase || "").toLowerCase();
    const actionKey = status === "holding"
      ? (mv.action_label_key || "fleet_drawer_action_recall")
      : (mv.action_label_key || "fleet_drawer_action_cancel");
    if (!btn) {
      btn = document.createElement("button");
      btn.type = "button";
      btn.className = "gc-fleet-hud-action gc-fleet-drawer-row-action";
      btn.dataset.fleetDrawerRecall = "1";
      wrap.appendChild(btn);
    }
    btn.dataset.movementId = movementId;
    _setIfChanged(btn, t(actionKey, actionKey));
    if (mv.cancel_reason) {
      btn.title = t(mv.cancel_reason, mv.cancel_reason);
    } else {
      btn.removeAttribute("title");
    }
  }

  function syncFleetDrawerRowAction(row, mv) {
    if (!row || !mv) return;
    const movementId = fleetDrawerMovementIdFromMv(mv);
    const canAct = !!movementId && fleetDrawerRowCanAct(mv) && mv.can_recall !== false;
    upsertFleetDrawerActionBtn(
      row.querySelector(".gc-fleet-hud-action-wrap"),
      movementId,
      mv,
      canAct
    );
  }

  function patchFleetDrawerRow(row, mv) {
    if (!row || !mv) return;
    const rowId = fleetDrawerMovementIdFromMv(mv);
    if (rowId) row.dataset.movementId = rowId;
    const mission = String(mv.mission || mv.mission_type || "custom");
    const missionKey = mv.mission_label_key || `fleet_mission_${mission}`;
    const detailOpen = row.classList.contains("is-detail-open");
    row.className = `gc-fleet-hud-row gc-fleet-drawer-row gc-fleet-hud-row--${mission}`;
    if (detailOpen) row.classList.add("is-detail-open");
    const missionEl = row.querySelector("[data-fleet-drawer-mission]");
    if (missionEl) {
      missionEl.className = `gc-fleet-hud-mission gc-fleet-hud-mission--${mission}`;
      missionEl.dataset.movementId = String(mv.movement_id || mv.id || "");
      _setIfChanged(missionEl, t(missionKey, mission));
    }
    const routeEl = row.querySelector(".gc-fleet-hud-route");
    if (routeEl) _setIfChanged(routeEl, formatFleetDrawerRoute(mv));
    const legEl = row.querySelector("[data-fleet-drawer-leg]");
    if (legEl) _setIfChanged(legEl, fleetDrawerLegLabel(mv));
    const shipsEl = row.querySelector("[data-fleet-drawer-ships]");
    if (shipsEl) {
      const totalShips = fleetDrawerTotalShips(mv);
      _setIfChanged(shipsEl, totalShips > 0 ? fmtNumber(totalShips) : "");
      shipsEl.hidden = totalShips <= 0;
    }
    patchFleetDrawerRowCountdown(row, mv);
    patchFleetHudFlightTrack(row, mv);
    syncFleetDrawerRowAction(row, mv);
    refreshFleetDrawerRowDetail(row, mv);
  }

  function syncFleetDrawerList(listEl, visibleItems, opts) {
    if (!listEl) return;
    const items = Array.isArray(visibleItems) ? visibleItems : [];
    const wantedIds = new Set(items.map((mv) => String(mv.movement_id || mv.id || "")).filter(Boolean));
    const allowRemove = !opts || opts.authoritative !== false;

    if (allowRemove) {
      listEl.querySelectorAll("[data-fleet-drawer-row]").forEach((row) => {
        if (row.hasAttribute("data-fleet-alert")) return;
        const id = String(row.dataset.movementId || "");
        if (id && !wantedIds.has(id)) row.remove();
      });
    }

    const alertOffset = listEl.querySelector("[data-fleet-alert]") ? 1 : 0;
    items.forEach((mv, index) => {
      const id = String(mv.movement_id || mv.id || "");
      if (!id) return;
      let row = listEl.querySelector(`[data-fleet-drawer-row][data-movement-id="${id}"]`);
      if (row && (!row.querySelector(".gc-fleet-hud-main") || !row.querySelector("[data-fleet-hud-track]"))) {
        row.replaceWith(createFleetDrawerRow(mv));
        row = listEl.querySelector(`[data-fleet-drawer-row][data-movement-id="${id}"]`);
      } else if (!row) {
        row = createFleetDrawerRow(mv);
        listEl.appendChild(row);
      } else {
        patchFleetDrawerRow(row, mv);
        const targetBefore = listEl.children[index + alertOffset] || null;
        if (row !== targetBefore) {
          listEl.insertBefore(row, targetBefore);
        }
      }
    });

    updateFleetDrawerRowTimers(getTimerServerNow());
  }

  function patchFleetDrawerRowFlight(row, mv) {
    const flight = row.querySelector("[data-fleet-flight-route]");
    if (!flight || !mv) return;
    const status = String(mv.status || mv.phase || mv.leg_phase || "outbound").toLowerCase();
    flight.dataset.fleetFlightStatus = status;
    const progress = status === "holding" ? 50 : fleetDrawerFlightProgress(mv);
    const visual = status === "returning" ? (100 - progress) / 100 : progress / 100;
    flight.style.setProperty("--fleet-progress", String(Math.max(0, Math.min(1, visual))));
    const labelEl = flight.querySelector("[data-fleet-flight-label]");
    if (labelEl && row?.classList.contains("is-selected")) {
      _setIfChanged(labelEl, t("fleet_drawer_remaining", "Restflugzeit"));
    } else if (labelEl) {
      const legKey = globalFleetLegKey(mv, status);
      _setIfChanged(labelEl, t(legKey, legKey));
    }
  }

  function patchFleetDrawerRowCountdown(row, mv) {
    const cdChip = row.querySelector("[data-fleet-drawer-countdown]");
    if (!cdChip || !mv) return;
    const phase = mv.phase || mv.leg_phase || mv.status || "";
    const countdownAt = fleetDrawerCountdownAt(mv);
    if (!countdownAt) {
      cdChip.textContent = "–";
      cdChip.removeAttribute("data-timer-target");
      cdChip.removeAttribute("data-countdown-at");
      cdChip.removeAttribute("data-countdown-key");
      delete cdChip.dataset.serverRemaining;
      updateFleetDrawerRowTimers(getTimerServerNow());
      return;
    }
    const countdownKey = `${mv.movement_id || mv.id}:${phase}:${countdownAt}`;
    const srvRem = Number(mv.remaining_seconds);
    const prevKey = cdChip.dataset.countdownKey || "";
    const prevTarget = Number(cdChip.dataset.countdownAt || 0);
    if (prevKey !== countdownKey || prevTarget !== countdownAt) {
      delete cdChip.dataset.fleetArrivedKey;
      applyQueueJobTimerAttrs(
        cdChip,
        countdownAt,
        "fleet",
        "fleet",
        Number.isFinite(srvRem) && srvRem >= 0 ? Math.ceil(srvRem) : undefined
      );
      cdChip.dataset.countdownScope = "fleet";
      cdChip.dataset.countdownKey = countdownKey;
      cdChip.classList.add("fleet-active-countdown");
      patchFleetHudFlightTrack(row, mv, Number.isFinite(srvRem) && srvRem >= 0 ? srvRem : undefined);
    } else if (Number.isFinite(srvRem) && srvRem >= 0) {
      assignMonotonicServerRemaining(cdChip, Math.ceil(srvRem), countdownAt);
    }
    updateFleetDrawerRowTimers(getTimerServerNow());
  }

  function createFleetDrawerFlightRoute(mv) {
    const flight = document.createElement("div");
    flight.className = "gc-fleet-drawer-row-flight";
    flight.dataset.fleetFlightRoute = "1";

    const stage = document.createElement("div");
    stage.className = "gc-fleet-flight-stage";

    const originNode = document.createElement("span");
    originNode.className = "gc-fleet-flight-node gc-fleet-flight-node--origin";
    originNode.setAttribute("aria-hidden", "true");
    stage.appendChild(originNode);

    const trackWrap = document.createElement("div");
    trackWrap.className = "gc-fleet-flight-core";

    const track = document.createElement("span");
    track.className = "gc-fleet-flight-track";
    const line = document.createElement("span");
    line.className = "gc-fleet-flight-line";
    line.setAttribute("aria-hidden", "true");
    const dot = document.createElement("span");
    dot.className = "gc-fleet-flight-dot";
    dot.setAttribute("aria-hidden", "true");
    track.appendChild(line);
    track.appendChild(dot);
    trackWrap.appendChild(track);

    const meta = document.createElement("div");
    meta.className = "gc-fleet-flight-meta";

    const labelEl = document.createElement("span");
    labelEl.className = "gc-fleet-flight-label";
    labelEl.dataset.fleetFlightLabel = "1";
    meta.appendChild(labelEl);
    trackWrap.appendChild(meta);
    stage.appendChild(trackWrap);

    const targetNode = document.createElement("span");
    targetNode.className = "gc-fleet-flight-node gc-fleet-flight-node--target";
    targetNode.setAttribute("aria-hidden", "true");
    stage.appendChild(targetNode);

    flight.appendChild(stage);
    return flight;
  }

  function fleetHudFlightVisual(mv, remainingSeconds) {
    const status = String(mv?.status || mv?.phase || mv?.leg_phase || "outbound").toLowerCase();
    if (status === "holding") {
      return { status, visual: 1 };
    }
    let progressPct = Number(mv?.progress_pct);
    if (Number.isFinite(remainingSeconds)) {
      const total = Math.max(1, Number(mv?.total_seconds || mv?.duration_seconds || mv?.flight_seconds || 0));
      const rem = Math.max(0, Number(remainingSeconds));
      progressPct = Math.max(0, Math.min(100, ((total - rem) / total) * 100));
    } else if (!Number.isFinite(progressPct)) {
      progressPct = fleetDrawerFlightProgress(mv);
    } else {
      progressPct = Math.max(0, Math.min(100, progressPct));
    }
    let visual = progressPct / 100;
    if (status === "returning") {
      visual = (100 - progressPct) / 100;
    }
    return { status, visual: Math.max(0, Math.min(1, visual)) };
  }

  function patchFleetHudFlightTrack(row, mv, remainingSeconds) {
    const track = row.querySelector("[data-fleet-hud-track]");
    if (!track || !mv) return;
    const { status, visual } = fleetHudFlightVisual(mv, remainingSeconds);
    const prevStatus = track.dataset.fleetFlightStatus || "";
    track.dataset.fleetFlightStatus = status;
    row.dataset.fleetFlightStatus = status;
    track.style.setProperty("--fleet-progress", String(visual));
    if (prevStatus && prevStatus !== status) {
      track.classList.add("is-snap");
      requestAnimationFrame(() => track.classList.remove("is-snap"));
    }
  }

  function createFleetHudFlightTrack() {
    const track = document.createElement("span");
    track.className = "gc-fleet-hud-track";
    track.dataset.fleetHudTrack = "1";
    track.setAttribute("aria-hidden", "true");
    const line = document.createElement("span");
    line.className = "gc-fleet-hud-track-line";
    const dot = document.createElement("span");
    dot.className = "gc-fleet-hud-track-dot";
    track.append(line, dot);
    return track;
  }

  function fleetDrawerLegLabel(mv) {
    const status = String(mv?.status || mv?.phase || mv?.leg_phase || "outbound").toLowerCase();
    const legKey = globalFleetLegKey(mv, status);
    return t(legKey, legKey);
  }

  function createFleetDrawerRow(mv) {
    const row = document.createElement("article");
    const mission = String(mv.mission || mv.mission_type || "custom");
    const missionKey = mv.mission_label_key || `fleet_mission_${mission}`;
    const movementId = String(mv.movement_id || mv.id || "");

    row.className = `gc-fleet-hud-row gc-fleet-drawer-row gc-fleet-hud-row--${mission}`;
    row.dataset.fleetDrawerRow = "1";
    row.dataset.movementId = movementId;
    row.setAttribute("role", "listitem");
    row.setAttribute("aria-expanded", "false");

    const main = document.createElement("div");
    main.className = "gc-fleet-hud-main";

    const missionEl = document.createElement("span");
    missionEl.className = `gc-fleet-hud-mission gc-fleet-hud-mission--${mission}`;
    missionEl.dataset.fleetDrawerMission = "1";
    missionEl.dataset.movementId = movementId;
    missionEl.textContent = t(missionKey, mission);
    main.appendChild(missionEl);

    const routeEl = document.createElement("span");
    routeEl.className = "gc-fleet-hud-route gc-fleet-drawer-row-route";
    routeEl.textContent = formatFleetDrawerRoute(mv);
    main.appendChild(routeEl);

    const track = createFleetHudFlightTrack();

    const meta = document.createElement("div");
    meta.className = "gc-fleet-hud-meta";

    const legEl = document.createElement("span");
    legEl.className = "gc-fleet-hud-leg";
    legEl.dataset.fleetDrawerLeg = "1";
    legEl.textContent = fleetDrawerLegLabel(mv);
    meta.appendChild(legEl);

    const shipsEl = document.createElement("span");
    shipsEl.className = "gc-fleet-hud-ships gc-mono";
    shipsEl.dataset.fleetDrawerShips = "1";
    const totalShips = fleetDrawerTotalShips(mv);
    shipsEl.textContent = totalShips > 0 ? fmtNumber(totalShips) : "";
    shipsEl.hidden = totalShips <= 0;
    meta.appendChild(shipsEl);

    const timeEl = document.createElement("span");
    timeEl.className = "gc-fleet-hud-time gc-mono";
    timeEl.dataset.fleetDrawerCountdown = "1";
    timeEl.textContent = formatCountdownRemain(fleetDrawerRemainingSeconds(mv, getTimerServerNow()));
    meta.appendChild(timeEl);

    const actionWrap = document.createElement("span");
    actionWrap.className = "gc-fleet-hud-action-wrap";
    meta.appendChild(actionWrap);

    row.append(main, track, meta);

    patchFleetDrawerRow(row, mv);
    return row;
  }

  function _fleetIncomingAttackActive(alerts) {
    const data = alerts && typeof alerts === "object" ? alerts : (GC.lastState?.fleet_alerts || {});
    const count = Math.max(0, Math.floor(Number(data.incoming_attack_count) || 0));
    const attacks = Array.isArray(data.incoming_attacks) ? data.incoming_attacks : [];
    return data.has_incoming_attack === true || count > 0 || attacks.length > 0;
  }

  function resolveFleetHudShellVisibilityMeta() {
    const sticky = _fleetHudStickyPayload;
    const stickyCount = Number(sticky?.count || 0);
    if (stickyCount > 0) {
      return { fleetCount: stickyCount, explicitEmpty: false };
    }
    if (sticky && sticky.fleets_confirmed_empty === true && stickyCount === 0) {
      return { fleetCount: 0, explicitEmpty: true };
    }
    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    const domRows = root
      ? root.querySelectorAll("[data-fleet-drawer-row][data-movement-id]").length
      : 0;
    const fromState = GC.lastState?.active_fleets;
    const stateCount = normalizeActiveFleetsPayload(fromState).count;
    const fleetCount = Math.max(stateCount, domRows);
    const explicitEmpty = fleetCount === 0
      && domRows === 0
      && isExplicitEmptyActiveFleets(fromState);
    return { fleetCount, explicitEmpty };
  }
  GC.resolveFleetHudShellVisibilityMeta = resolveFleetHudShellVisibilityMeta;

  function _syncFleetHudShellVisibility(root, fleetCount, alerts, opts) {
    if (!root) return;
    const hasAlert = _fleetIncomingAttackActive(alerts);
    const listEl = root.querySelector("[data-fleet-drawer-list]");
    const hasExistingRows = listEl
      && !!listEl.querySelector("[data-fleet-drawer-row][data-movement-id]");
    const explicitEmpty = Boolean(opts && opts.explicitEmpty);
    let showHud = fleetCount > 0 || hasAlert;
    if (!showHud && hasExistingRows && !explicitEmpty) {
      showHud = true;
    }
    const emptyEl = root.querySelector("[data-fleet-drawer-empty]");
    const panel = root.querySelector("[data-fleet-drawer-panel]");
    if (emptyEl) emptyEl.hidden = showHud;
    if (panel) panel.hidden = !showHud;
    root.classList.toggle("is-empty", !showHud);
  }

  function createFleetAttackAlertRow() {
    const row = document.createElement("article");
    row.className = "gc-fleet-hud-row gc-fleet-drawer-row gc-fleet-hud-row--attack gc-fleet-hud-row--incoming-alert";
    row.setAttribute("data-fleet-alert", "");
    row.setAttribute("role", "status");
    row.setAttribute("aria-live", "polite");

    const main = document.createElement("div");
    main.className = "gc-fleet-hud-main";

    const missionEl = document.createElement("span");
    missionEl.className = "gc-fleet-hud-mission gc-fleet-hud-mission--attack";
    missionEl.textContent = t("fleet_mission_attack", "Angriff");

    const routeEl = document.createElement("span");
    routeEl.className = "gc-fleet-hud-route gc-fleet-drawer-row-route";
    routeEl.dataset.fleetAlertSummary = "1";

    main.append(missionEl, routeEl);

    const track = createFleetHudFlightTrack();
    track.dataset.fleetFlightStatus = "inbound";

    const meta = document.createElement("div");
    meta.className = "gc-fleet-hud-meta";

    const legEl = document.createElement("span");
    legEl.className = "gc-fleet-hud-leg";
    legEl.textContent = t("fleet_leg_inbound", "Eingehend");

    const shipsEl = document.createElement("span");
    shipsEl.className = "gc-fleet-hud-ships gc-mono";
    shipsEl.dataset.fleetAlertCount = "1";
    shipsEl.hidden = true;

    const timeEl = document.createElement("span");
    timeEl.className = "gc-fleet-hud-time gc-mono";
    timeEl.dataset.fleetDrawerCountdown = "1";

    const actionWrap = document.createElement("span");
    actionWrap.className = "gc-fleet-hud-action-wrap";
    actionWrap.hidden = true;

    meta.append(legEl, shipsEl, timeEl, actionWrap);
    row.append(main, track, meta);
    return row;
  }

  function _fleetAttackAlertLabel(alerts) {
    const count = Math.max(0, Math.floor(Number(alerts?.incoming_attack_count) || 0));
    if (count <= 0) return "";
    if (count === 1) {
      return t("fleet_alert_incoming_attack", "Angriff im Anflug");
    }
    return tf("fleet_alert_incoming_attacks", { count }, `${count} Angriffe im Anflug`);
  }

  function updateFleetAttackAlertCountdown(serverNow) {
    const row = document.querySelector("[data-fleet-alert].gc-fleet-drawer-row");
    if (!row || row.hidden) return;
    const summaryEl = row.querySelector("[data-fleet-alert-summary]");
    const cdEl = row.querySelector("[data-fleet-drawer-countdown]");
    if (!summaryEl || !cdEl) return;
    const arrivalAt = Math.floor(Number(row.dataset.arrivalAt || 0));
    const now = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();
    const remaining = arrivalAt > 0 ? Math.max(0, Math.floor(arrivalAt - now)) : 0;
    if (remaining > 0) {
      _setIfChanged(cdEl, formatCountdownRemain(remaining));
      row.classList.toggle("is-urgent", remaining < 10);
      cdEl.classList.toggle("is-urgent", remaining < 10);
    } else if (arrivalAt > 0) {
      _setIfChanged(cdEl, "0s");
      row.classList.remove("is-urgent");
      cdEl.classList.remove("is-urgent");
    }
  }

  function _maybePlayMessageNotifySound(data, opts) {
    const payload = data && typeof data === "object" ? data : {};
    const o = opts && typeof opts === "object" ? opts : {};
    let alertKey = resolveMessageNotifySoundKey(payload);
    if (!alertKey && o.unreadIncreased) {
      const unread = Math.max(0, Math.floor(Number(payload.unread_messages_count) || 0));
      if (unread > 0) alertKey = `u:${unread}`;
    }
    if (!alertKey) return;
    if (!shouldPlayNotifySoundForKey(_notifySoundStorageKey(GC_NOTIFY_SOUND_LS_MESSAGE), alertKey)) {
      return;
    }
    playNewMessageNotifySound();
  }

  function _maybePlayIncomingAttackNotify(alerts) {
    const data = alerts && typeof alerts === "object" ? alerts : {};
    const attackCount = Math.max(0, Math.floor(Number(data.incoming_attack_count) || 0));
    const active = _fleetIncomingAttackActive(data);
    const alertKey = resolveAttackAlertSoundKey(data);

    if (active && alertKey) {
      console.debug("[GC] notify check", {
        kind: "attack",
        attackCount,
        hasIncomingAttack: data.has_incoming_attack === true,
        nextAttackArrival: data.next_attack_arrival,
        alertKey,
        active,
        notifyAttackSound: GC.settings?.notify_attack_sound,
        audioUnlocked: _notifyAudioUnlocked,
      });
    }

    if (!active || !alertKey) return;
    if (!shouldPlayNotifySoundForKey(_notifySoundStorageKey(GC_NOTIFY_SOUND_LS_ATTACK), alertKey)) {
      return;
    }
    playIncomingAttackNotifySound();
  }

  function syncFleetAttackAlert(alerts) {
    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    const data = alerts && typeof alerts === "object" ? alerts : {};
    const active = _fleetIncomingAttackActive(data);
    if (!root) return;
    const listEl = root.querySelector("[data-fleet-drawer-list]");
    let alertRow = root.querySelector("[data-fleet-alert].gc-fleet-drawer-row");

    if (!active) {
      if (alertRow) {
        alertRow.remove();
      }
      const shellMeta = resolveFleetHudShellVisibilityMeta();
      _syncFleetHudShellVisibility(root, shellMeta.fleetCount, data, { explicitEmpty: shellMeta.explicitEmpty });
      return;
    }

    if (!alertRow) {
      alertRow = createFleetAttackAlertRow();
    }

    const count = Math.max(0, Math.floor(Number(data.incoming_attack_count) || 0));
    const summaryEl = alertRow.querySelector("[data-fleet-alert-summary]");
    const shipsEl = alertRow.querySelector("[data-fleet-alert-count]");
    if (summaryEl) {
      _setIfChanged(summaryEl, _fleetAttackAlertLabel(data));
    }
    if (shipsEl) {
      shipsEl.textContent = count > 1 ? fmtNumber(count) : "";
      shipsEl.hidden = count <= 1;
    }

    const arrivalAt = Math.floor(Number(data.next_attack_arrival) || 0);
    if (arrivalAt > 0) {
      alertRow.dataset.arrivalAt = String(arrivalAt);
      const cdEl = alertRow.querySelector("[data-fleet-drawer-countdown]");
      if (cdEl) cdEl.dataset.timerTarget = String(arrivalAt);
    } else {
      alertRow.removeAttribute("data-arrival-at");
      const cdEl = alertRow.querySelector("[data-fleet-drawer-countdown]");
      if (cdEl) {
        cdEl.removeAttribute("data-timer-target");
        cdEl.textContent = "";
      }
    }

    if (listEl) {
      listEl.prepend(alertRow);
    } else {
      root.prepend(alertRow);
    }

    const shellMeta = resolveFleetHudShellVisibilityMeta();
    _syncFleetHudShellVisibility(root, shellMeta.fleetCount, data, { explicitEmpty: shellMeta.explicitEmpty });
    updateFleetAttackAlertCountdown(getTimerServerNow());
    GC.startProgressTicker();
  }
  GC.syncFleetAttackAlert = syncFleetAttackAlert;

  function renderGlobalFleetHud(fleetsRaw, opts) {
    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    const resolved = resolveFleetHudPayload(fleetsRaw, {
      ...(opts || {}),
      stateContext: (opts && opts.stateContext) || fleetsRaw,
    });
    const payload = resolved && resolved.payload;
    if (!payload) {
      GC.startProgressTicker();
      return;
    }
    const list = payload.items;
    const count = payload.count;

    updateFleetNavBadge(count);

    if (!root) {
      GC.startProgressTicker();
      return;
    }

    root.hidden = false;

    const showAll = isFleetDrawerShowAll();
    const visibleLimit = Math.max(1, Number(payload.visible_limit) || FLEET_DRAWER_VISIBLE_LIMIT_DEFAULT);

    const hasIncomingAttack = _fleetIncomingAttackActive(GC.lastState?.fleet_alerts);
    _syncFleetHudShellVisibility(root, count, GC.lastState?.fleet_alerts, {
      explicitEmpty: Boolean(resolved.explicitEmpty),
    });

    const listEl = root.querySelector("[data-fleet-drawer-list]");
    const moreBtn = root.querySelector("[data-fleet-drawer-more]");
    rememberFleetDrawerMovements(list);
    const canExpand = canExpandFleetDrawer(count, visibleLimit);
    // Phone: header icon may open the sheet even with 0–1 fleets.
    const nowShowAll = showAll && (canExpand || isMobileFleetSheetViewport());
    if (listEl) {
      listEl.classList.toggle("is-show-all", nowShowAll);
      root.classList.toggle("is-show-all", nowShowAll);
      const visibleItems = nowShowAll ? list : list.slice(0, visibleLimit);
      const prevCount = Number(listEl.dataset.fleetDrawerCount || 0);
      const countChanged = prevCount !== count;
      if (countChanged) {
        _clearMovementCountdownExpiryState();
        listEl.dataset.fleetDrawerCount = String(count);
        if (count > 0) notifyFleetDrawerLayoutChange();
      }
      syncFleetDrawerList(listEl, visibleItems, {
        authoritative: resolved.authoritative !== false,
      });

      if (moreBtn) {
        if (canExpand) {
          moreBtn.hidden = false;
          if (showAll) {
            _setIfChanged(moreBtn, t("fleet_drawer_show_less", "Weniger anzeigen"));
          } else if (count > visibleLimit) {
            _setIfChanged(
              moreBtn,
              tf("fleet_drawer_show_more", { count: count - visibleLimit }, `Weitere anzeigen (${count - visibleLimit})`)
            );
          } else {
            _setIfChanged(moreBtn, t("fleet_drawer_expand", "Flotten öffnen"));
          }
        } else {
          moreBtn.hidden = true;
          moreBtn.textContent = "";
        }
      }
    }

    // Always resync portal/backdrop — stuck open backdrop blocks expand after fleet send.
    syncMobileFleetSheetLayout(root);
    root.dataset.fleetSheetSynced = "1";
    GC.startProgressTicker();
  }

  function syncFleetVacationNotice(accountSafety) {
    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    if (!root) return;
    const notice = root.querySelector("[data-fleet-vacation-notice]");
    const textEl = root.querySelector("[data-fleet-vacation-text]");
    const timerEl = root.querySelector("[data-fleet-vacation-timer]");
    if (!notice || !textEl) return;

    const safety = accountSafety && typeof accountSafety === "object" ? accountSafety : {};
    const active = !!safety.vacation_active;
    if (!active) {
      notice.hidden = true;
      if (timerEl) timerEl.hidden = true;
      return;
    }

    notice.hidden = false;
    textEl.textContent = t(
      "fleet_drawer_vacation_notice",
      "Urlaubsmodus aktiv — Flotten senden, Handel und Angriffe sind eingeschränkt."
    );

    if (!timerEl) return;
    const lockedUntil = Math.floor(Number(safety.vacation_locked_until || 0));
    const now = Math.floor(getTimerServerNow());
    if (lockedUntil > now) {
      timerEl.hidden = false;
      timerEl.setAttribute("data-until", String(lockedUntil));
      timerEl.textContent = tf(
        "options_vacation_timer",
        { time: formatCountdownRemain(lockedUntil - now) },
        `Deaktivierung in ${formatCountdownRemain(lockedUntil - now)}`
      );
      GC.startProgressTicker();
    } else {
      timerEl.hidden = true;
      timerEl.removeAttribute("data-until");
      timerEl.textContent = "";
    }
  }
  GC.renderGlobalFleetHud = renderGlobalFleetHud;
  GC.syncFleetVacationNotice = syncFleetVacationNotice;

  async function handleFleetDrawerRecall(btn) {
    const movementId = fleetDrawerResolveMovementId(btn);
    if (!movementId || btn.disabled) return;
    btn.disabled = true;
    btn.classList.add("is-loading");
    try {
      const res = await GC.fetchGameAction("/api/fleet/recall", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          movement_id: movementId,
          request_id: (typeof crypto !== "undefined" && crypto.randomUUID)
            ? crypto.randomUUID()
            : `fleet-recall-${Date.now()}`,
        }),
      });
      if (res && (res.state || res.data?.state)) {
        applyActionState(res, res.ok ? "fleet_recall" : "fleet_recall_error");
      } else if (typeof GC.refreshGameState === "function") {
        await GC.refreshGameState("fleet_recall");
      }
      if (res.ok) {
        showNotify(t("fleet_recall_success", "Flotte wurde zurückgerufen."), "success");
      } else {
        const errKey = res.message_key || res.error || "fleet_recall_failed";
        showNotify(t(errKey, res.message || errKey), "error");
      }
    } catch (err) {
      showNotify(t("fleet_recall_failed", "Rückruf fehlgeschlagen."), "error");
      console.warn("[GC] fleet recall failed", err);
    } finally {
      btn.disabled = false;
      btn.classList.remove("is-loading");
    }
  }

  function initGlobalFleetDrawer() {
    if (_globalFleetDrawerBound) return;
    _globalFleetDrawerBound = true;

    document.addEventListener("click", (e) => {
      const headerFleetBtn = e.target.closest("[data-gc-open-fleet-sheet]");
      if (headerFleetBtn) {
        e.preventDefault();
        e.stopPropagation();
        toggleHeaderFleetSheet();
        if (isFleetDrawerShowAll() && typeof GC.refreshGameState === "function") {
          void GC.refreshGameState("fleet_drawer_expand");
        }
        return;
      }

      const recallBtn = e.target.closest("[data-fleet-drawer-recall]");
      if (recallBtn) {
        const drawerRoot = document.getElementById("global-fleet-drawer-root")
          || document.querySelector("[data-global-fleet-drawer]");
        if (!drawerRoot || !drawerRoot.contains(recallBtn)) return;
        e.preventDefault();
        e.stopPropagation();
        handleFleetDrawerRecall(recallBtn);
        return;
      }

      // Touch / coarse pointer: tap row for ship/cargo detail (desktop keeps hover tooltip).
      if (!fleetDrawerHoverTooltipsEnabled()) {
        const detailRow = e.target.closest("[data-fleet-drawer-row]");
        if (detailRow && !detailRow.hasAttribute("data-fleet-alert")) {
          const drawerRoot = document.getElementById("global-fleet-drawer-root")
            || document.querySelector("[data-global-fleet-drawer]");
          if (drawerRoot && drawerRoot.contains(detailRow)) {
            if (e.target.closest("[data-fleet-drawer-detail]")) return;
            const movementId = parseInt(detailRow.dataset.movementId || "0", 10);
            const mv = movementId ? _fleetDrawerMovementById.get(movementId) : null;
            if (mv) {
              e.preventDefault();
              toggleFleetDrawerRowDetail(detailRow, mv);
              return;
            }
          }
        }
      }

      const moreBtn = e.target.closest("[data-fleet-drawer-more]");
      if (!moreBtn) return;
      const drawerRoot = document.getElementById("global-fleet-drawer-root")
        || document.querySelector("[data-global-fleet-drawer]");
      if (!drawerRoot || !drawerRoot.contains(moreBtn)) return;
      e.preventDefault();
      e.stopPropagation();
      const willExpand = !isFleetDrawerShowAll();
      setFleetDrawerShowAll(willExpand);
      if (GC.lastState?.active_fleets) {
        renderGlobalFleetHud(GC.lastState.active_fleets);
      }
      if (willExpand) {
        if (typeof GC.refreshGameState === "function") {
          void GC.refreshGameState("fleet_drawer_expand");
        }
        if (typeof GC.scheduleFleetStateRefresh === "function") {
          GC.scheduleFleetStateRefresh("fleet_drawer_expand", { immediate: true });
        }
      }
    });

    const root = document.getElementById("global-fleet-drawer-root") || document.querySelector("[data-global-fleet-drawer]");
    if (!root) return;

    if (fleetDrawerHoverTooltipsEnabled()) {
      root.addEventListener("mouseover", (e) => {
        if (e.target.closest("[data-fleet-drawer-recall]")) return;
        const row = e.target.closest("[data-fleet-drawer-row]");
        if (!row || !root.contains(row)) return;
        const movementId = parseInt(row.dataset.movementId || "0", 10);
        const mv = _fleetDrawerMovementById.get(movementId);
        if (mv) showFleetDrawerTooltip(row, mv);
      });
      root.addEventListener("mouseout", (e) => {
        const row = e.target.closest("[data-fleet-drawer-row]");
        if (!row) return;
        const related = e.relatedTarget;
        if (related && (row.contains(related) || _fleetDrawerTooltipEl?.contains(related))) return;
        hideFleetDrawerTooltip();
      });
    }

    document.addEventListener("scroll", hideFleetDrawerTooltip, true);
    window.addEventListener("resize", () => {
      hideFleetDrawerTooltip();
      syncMobileFleetSheetTop();
      const fleetRoot = document.getElementById("global-fleet-drawer-root")
        || document.querySelector("[data-global-fleet-drawer]");
      if (fleetRoot) syncMobileFleetSheetLayout(fleetRoot);
    });

    if (!document.documentElement.dataset.gcFleetSheetEscapeBound) {
      document.documentElement.dataset.gcFleetSheetEscapeBound = "1";
      document.addEventListener("keydown", (e) => {
        if (e.key !== "Escape" || !isMobileFleetSheetViewport() || !isFleetDrawerShowAll()) return;
        setFleetDrawerShowAll(false);
        if (GC.lastState?.active_fleets) {
          renderGlobalFleetHud(GC.lastState.active_fleets);
        }
      });
    }

    GC.registerCleanup?.(() => {
      setFleetDrawerShowAll(false);
      document.body.classList.remove("gc-fleet-sheet-open");
      const backdrop = document.getElementById("gc-fleet-sheet-backdrop");
      if (backdrop) backdrop.hidden = true;
      const fleetRoot = document.getElementById("global-fleet-drawer-root")
        || document.querySelector("[data-global-fleet-drawer]");
      if (fleetRoot) {
        closeAllFleetDrawerRowDetails(fleetRoot);
        fleetRoot.classList.remove("is-show-all");
        const listEl = fleetRoot.querySelector("[data-fleet-drawer-list]");
        if (listEl) listEl.classList.remove("is-show-all");
        _restoreFleetSheetPortal(fleetRoot);
        _fleetSheetAnchor = null;
        delete fleetRoot.dataset.fleetSheetSynced;
      }
    }, { persistent: true });

    if (GC.lastState?.active_fleets) {
      renderGlobalFleetHud(GC.lastState.active_fleets);
    } else if (
      typeof GC.refreshGameState === "function"
      && shouldRunGameLoop()
      && !pageHasSsrLiveBoot()
    ) {
      void GC.refreshGameState("fleet_drawer_boot");
    }
  }
  GC.initGlobalFleetDrawer = initGlobalFleetDrawer;

  function pickPrimaryFleetMovement(fleets) {
    const list = Array.isArray(fleets) ? fleets : [];
    if (!list.length) return null;
    return list.slice().sort((a, b) => {
      const ca = Number(a?.countdown_at || 0) || Number.POSITIVE_INFINITY;
      const cb = Number(b?.countdown_at || 0) || Number.POSITIVE_INFINITY;
      return ca - cb;
    })[0];
  }

  function formatGlobalFleetHudTarget(mv) {
    if (!mv || typeof mv !== "object") return "–";
    const wt = mv.world_target;
    if (wt?.target_name_key) return t(wt.target_name_key, wt.target_name_key);
    if (wt?.target_name) return String(wt.target_name);
    const origin = String(mv.origin_name || "").trim();
    const target = String(mv.target_coords || "").trim();
    if (origin && target) return `${origin} → ${target}`;
    return target || origin || "–";
  }

  function globalFleetLegKey(mv, phase) {
    return mv?.status_label || mv?.leg_label_key || (
      phase === "returning"
        ? "fleet_leg_returning"
        : phase === "holding"
          ? "fleet_leg_holding"
          : "fleet_leg_outbound"
    );
  }

  function updateFleetNavBadge(count) {
    const n = Math.max(0, Number(count) || 0);
    const label = n > 9 ? "9+" : String(n);
    document.querySelectorAll("[data-fleet-nav-badge]").forEach((el) => {
      const navItem = el.closest("[data-nav-module='fleet']");
      if (n > 0) {
        el.textContent = label;
        el.hidden = false;
        el.classList.remove("hidden");
        el.setAttribute("aria-hidden", "false");
        navItem?.classList.add("gc-bottom-nav-item--fleet-active");
      } else {
        el.textContent = "";
        el.hidden = true;
        el.classList.add("hidden");
        el.setAttribute("aria-hidden", "true");
        navItem?.classList.remove("gc-bottom-nav-item--fleet-active");
      }
    });
    document.querySelectorAll("[data-header-fleet-badge]").forEach((el) => {
      if (n > 0) {
        el.textContent = label;
        el.hidden = false;
        el.classList.remove("hidden");
        el.setAttribute("aria-hidden", "false");
      } else {
        el.textContent = "";
        el.hidden = true;
        el.classList.add("hidden");
        el.setAttribute("aria-hidden", "true");
      }
    });
    const fleetsToggle = document.getElementById("gc-header-fleets-toggle");
    if (fleetsToggle) {
      fleetsToggle.classList.toggle("has-fleets", n > 0);
    }
  }
  GC.updateFleetNavBadge = updateFleetNavBadge;

  /** Single write path for shell HUD (header score/rank/online/messages + resource bar). */
  function syncFleetSlotsBadgeFromState(slots) {
    if (!slots || typeof slots !== "object") return;
    const active = parseInt(slots.active, 10) || 0;
    const max = parseInt(slots.max, 10) || 0;
    const text = `${active} / ${max}`;
    document.querySelectorAll("[data-fleet-slots]").forEach((el) => {
      _setIfChanged(el, text);
    });
    document.querySelectorAll("[data-logistics-fleet-slots]").forEach((el) => {
      _setIfChanged(el, text);
    });
    const freeEl = document.querySelector(".logistics-slots-free");
    if (freeEl && slots.free !== undefined) {
      const freeLabel = tt("logistics_slots_free");
      _setIfChanged(freeEl, `${freeLabel}: ${fmtNumber(parseInt(slots.free, 10) || 0)}`);
    }
    const fleetPage = document.getElementById("fleet-page");
    if (fleetPage?._fleetRt?.data) {
      fleetPage._fleetRt.data.fleet_slots = slots;
    }
  }
  GC.syncFleetSlotsBadgeFromState = syncFleetSlotsBadgeFromState;

  const _boostHudState = {
    effects: [],
    syncedAt: 0,
  };

  const _BOOST_DOMAIN_RES_KEYS = {
    production: ["metal", "crystal", "fuel_cells"],
    energy: ["energy"],
  };

  function _boostHudRemainingSeconds(baseRemaining) {
    const base = Math.max(0, Math.floor(Number(baseRemaining) || 0));
    const elapsed = Math.max(0, getApproxServerNow() - (_boostHudState.syncedAt || 0));
    return Math.max(0, base - elapsed);
  }

  function _normalizeBoostEffects(rawEffects) {
    if (!Array.isArray(rawEffects)) return [];
    return rawEffects.map((e) => ({
      key: String(e.key || e.effect_key || ""),
      affected_domain: String(e.affected_domain || "general"),
      effect_summary: String(e.effect_summary || ""),
      remaining_seconds: Math.max(0, Math.floor(Number(e.remaining_seconds) || 0)),
      resource_impacts: (e.resource_impacts && typeof e.resource_impacts === "object")
        ? e.resource_impacts
        : {},
    }));
  }

  function _resolveBoostEffectsFromState(data) {
    const fromData = data?.active_boosters?.active_effects;
    if (Array.isArray(fromData) && fromData.length) {
      return _normalizeBoostEffects(fromData);
    }
    const fromLast = GC.lastState?.active_boosters?.active_effects;
    if (Array.isArray(fromLast) && fromLast.length) {
      return _normalizeBoostEffects(fromLast);
    }
    return _boostHudState.effects;
  }

  function _boostEffectForResKey(resKey, effects) {
    const key = String(resKey || "");
    for (const [domain, keys] of Object.entries(_BOOST_DOMAIN_RES_KEYS)) {
      if (!keys.includes(key)) continue;
      const matches = (effects || []).filter((e) => e && e.affected_domain === domain);
      if (!matches.length) continue;
      // Prefer server aggregate chip row (stacked production total).
      const chipOnly = matches.find((e) => e.hud_chip_only || e.stack_aggregate);
      if (chipOnly) return chipOnly;
      const listable = matches.filter((e) => !e.hud_list_only);
      const pool = listable.length ? listable : matches;
      pool.sort((a, b) => {
        const pa = Number(a.effect_summary_params?.pct || 0);
        const pb = Number(b.effect_summary_params?.pct || 0);
        if (a.tier_standby && !b.tier_standby) return 1;
        if (!a.tier_standby && b.tier_standby) return -1;
        return pb - pa;
      });
      return pool[0];
    }
    return null;
  }

  function _formatResBoostChip(effect, resKey) {
    if (!effect) return "";
    const rem = _boostHudRemainingSeconds(effect.remaining_seconds);
    if (rem <= 0) return "";
    const summary = String(effect.effect_summary || "").trim();
    const impact = effect.resource_impacts?.[resKey]?.impact_summary
      ? String(effect.resource_impacts[resKey].impact_summary).trim()
      : "";
    const head = [summary, impact].filter(Boolean).join(" ");
    return head ? `${head} · ${formatDuration(rem)}` : formatDuration(rem);
  }

  function patchShellHudBoosters(data, opts) {
    // Mutation payloads that omit active_boosters must not re-hydrate from stale cache.
    if (data && typeof data === "object" && !Object.prototype.hasOwnProperty.call(data, "active_boosters")) {
      const stillActive = _boostHudState.effects.filter(
        (item) => _boostHudRemainingSeconds(item.remaining_seconds) > 0
      );
      if (stillActive.length !== _boostHudState.effects.length) {
        _boostHudState.effects = stillActive;
      }
      const barOmit = document.getElementById("resource-bar");
      if (!barOmit) return;
      ["metal", "crystal", "fuel_cells", "energy"].forEach((resKey) => {
        const chip = barOmit.querySelector(`[data-res-boost="${resKey}"]`);
        if (!chip) return;
        const effect = _boostEffectForResKey(resKey, _boostHudState.effects);
        const text = _formatResBoostChip(effect, resKey);
        if (!text) {
          chip.hidden = true;
          chip.textContent = "";
          return;
        }
        chip.hidden = false;
        _setIfChanged(chip, text);
      });
      return;
    }

    const incoming = _resolveBoostEffectsFromState(data);
    const serverEffects = data?.active_boosters?.active_effects;
    const resyncClock = !(opts && opts.resync === false);

    if (Array.isArray(serverEffects) && serverEffects.length) {
      _boostHudState.effects = incoming;
      if (resyncClock) {
        _boostHudState.syncedAt = getApproxServerNow();
      }
    } else if (Array.isArray(serverEffects) && serverEffects.length === 0) {
      _boostHudState.effects = [];
    } else if (incoming.length) {
      _boostHudState.effects = incoming;
    }

    const stillActive = _boostHudState.effects.filter(
      (item) => _boostHudRemainingSeconds(item.remaining_seconds) > 0
    );
    if (stillActive.length !== _boostHudState.effects.length) {
      _boostHudState.effects = stillActive;
    }

    const bar = document.getElementById("resource-bar");
    if (!bar) return;
    ["metal", "crystal", "fuel_cells", "energy"].forEach((resKey) => {
      const chip = bar.querySelector(`[data-res-boost="${resKey}"]`);
      if (!chip) return;
      const effect = _boostEffectForResKey(resKey, _boostHudState.effects);
      const text = _formatResBoostChip(effect, resKey);
      if (!text) {
        chip.hidden = true;
        chip.textContent = "";
        return;
      }
      chip.hidden = false;
      _setIfChanged(chip, text);
    });
  }

  function bootstrapHeaderBoostersFromDom() {
    const el = document.getElementById("gc-header-boosters-state");
    if (!el) return;
    try {
      const parsed = JSON.parse(el.textContent || "null");
      if (parsed && Array.isArray(parsed.active_effects) && parsed.active_effects.length) {
        patchShellHudBoosters({ active_boosters: parsed });
      }
    } catch (_) {}
  }

  /** GC-INSTANT-UX-001A — hydrate fleet drawer + unread badges from SSR before first poll. */
  function bootstrapHudFromDom() {
    const el = document.getElementById("gc-hud-boot-state");
    if (!el) return false;
    let parsed = null;
    try {
      parsed = JSON.parse(el.textContent || "null");
    } catch (_) {
      return false;
    }
    if (!parsed || typeof parsed !== "object") return false;
    const boot = {
      ok: true,
      unread_messages_count: Math.max(0, Math.floor(Number(parsed.unread_messages_count) || 0)),
      latest_message_id:
        parsed.latest_message_id == null ? null : Math.floor(Number(parsed.latest_message_id) || 0),
      active_fleets: parsed.active_fleets,
      fleet_alerts: parsed.fleet_alerts,
      fleet_slots: parsed.fleet_slots,
    };
    if (typeof GC.mergeLastState === "function") {
      GC.mergeLastState(boot, "ssr_hud_boot");
    } else {
      GC.lastState = { ...(GC.lastState && typeof GC.lastState === "object" ? GC.lastState : {}), ...boot, ok: true };
    }
    if (typeof GC.patchShellHudFromState === "function") {
      GC.patchShellHudFromState(boot, { reason: "ssr_hud_boot" });
    } else {
      if (typeof boot.unread_messages_count === "number") {
        updateMessagesUnreadBadges(boot.unread_messages_count);
      }
      if (boot.active_fleets !== undefined && typeof renderGlobalFleetHud === "function") {
        renderGlobalFleetHud(boot.active_fleets, { reason: "ssr_hud_boot" });
      }
    }
    return true;
  }
  GC.bootstrapHudFromDom = bootstrapHudFromDom;

  function tickBoostHudCountdown() {
    if (!_boostHudState.effects.length) return;
    // Local countdown only — do not re-sync the clock from lastState every tick
    // (that made stacked remaining look like a reset to the last polled snapshot).
    patchShellHudBoosters(
      { active_boosters: { active_effects: _boostHudState.effects } },
      { resync: false }
    );
  }

  function patchShellHudTimekeeper(data) {
    const tk = data && data.timekeeper;
    if (!tk) return;
    const bal = parseInt(tk.balance_sec, 10) || 0;
    const label = String(tk.label || formatDuration(bal));
    document.querySelectorAll("[data-timekeeper-balance]").forEach((el) => {
      _setIfChanged(el, label);
    });
    patchHudCapacityBar("timekeeper", bal, 86400, { animate: false });
    document.querySelectorAll("[data-gc-timekeeper-apply]").forEach((btn) => {
      const rem = parseInt(btn.dataset.timekeeperRemaining, 10) || 0;
      const unavailable = bal <= 0 || rem <= 0;
      btn.hidden = unavailable;
      btn.disabled = unavailable || _timekeeperApplying;
    });
    _syncTimekeeperApplyBtnTooltips();
  }

  let _timekeeperApplying = false;

  function _normalizeTimekeeperDomain(domain) {
    const d = String(domain || "").trim().toLowerCase();
    const aliases = {
      building: "build",
      buildings: "build",
      planet_evolution: "planet_research",
      pe_research: "planet_research",
    };
    return aliases[d] || d;
  }

  function _timekeeperOpenContext(openBtn) {
    const host = openBtn.closest("[data-job-id], [data-gc-card-queue], [data-hero-queue], [data-mini-queue-card]");
    const jobId = Math.floor(
      Number(
        host?.dataset?.jobId
          || openBtn.getAttribute("data-timekeeper-job-id")
          || openBtn.dataset.timekeeperJobId
          || 0
      )
    );
    const planetId = Math.floor(
      Number(
        GC.lastState?.active_planet_id
          || GC.lastState?.build_queue?.planet_id
          || (typeof GC.getDomPlanetId === "function" ? GC.getDomPlanetId() : 0)
          || 0
      )
    );
    return {
      domain: _normalizeTimekeeperDomain(
        openBtn.getAttribute("data-timekeeper-domain")
          || openBtn.dataset.timekeeperDomain
          || openBtn.getAttribute("data-timer-domain")
          || openBtn.dataset.timerDomain
          || "build"
      ),
      remaining: parseInt(
        openBtn.getAttribute("data-timekeeper-remaining") || openBtn.dataset.timekeeperRemaining,
        10
      ) || 0,
      jobId,
      planetId,
    };
  }

  function _timekeeperApplyTooltip() {
    const tk = (GC.lastState && GC.lastState.timekeeper) || {};
    const label = String(tk.label || "").trim();
    if (label && label !== "0min" && (parseInt(tk.balance_sec, 10) || 0) > 0) {
      return tf("timekeeper_apply_tooltip_up_to", { label }, `Bis zu ${label} einsetzen`);
    }
    return t("timekeeper_apply_tooltip", "Verfügbare Zeit einsetzen");
  }

  function _syncTimekeeperApplyBtnTooltips() {
    const tip = _timekeeperApplyTooltip();
    document.querySelectorAll("[data-gc-timekeeper-apply]").forEach((btn) => {
      btn.title = tip;
      btn.setAttribute("aria-label", tip);
    });
  }

  async function submitTimekeeperApplyFromBtn(openBtn) {
    if (!openBtn || openBtn.disabled || _timekeeperApplying) return;
    const ctx = _timekeeperOpenContext(openBtn);
    if (!ctx.domain || ctx.remaining <= 0 || _timekeeperApplyBalance() <= 0) return;

    _timekeeperApplying = true;
    setProgressionActionBusy(openBtn, true);

    const body = {
      domain: ctx.domain,
      mode: "max",
      request_id: `tk-${ctx.domain}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    };
    if (ctx.jobId > 0) body.job_id = ctx.jobId;
    if (ctx.planetId > 0) body.planet_id = ctx.planetId;

    try {
      const res = await GC.fetchGameAction("/api/timekeeper/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(body),
      });
      // GC-PERF-TK-001: do not rewrite queues from a failed/no-op apply payload.
      if (!res || !res.ok) {
        showNotify(mapActionError(res?.reason, res?.payload), "error");
        if (res && res.timekeeper) {
          patchShellHudTimekeeper({ timekeeper: res.timekeeper });
        }
        return;
      }
      const applied = Number(res.seconds_applied) || 0;
      if (applied <= 0) {
        showNotify(
          mapActionError("no_effect", res?.payload) || t("msg_action_failed", "Aktion fehlgeschlagen. Bitte erneut versuchen."),
          "error"
        );
        if (res.timekeeper) {
          patchShellHudTimekeeper({ timekeeper: res.timekeeper });
        }
        return;
      }
      // GC-PERF-TK-002: apply ledger wins over rebuild; clear monotonic remaining
      // so a earlier finish_at is not held by stale dataset.serverRemaining.
      if (res.timekeeper && res.state && typeof res.state === "object") {
        res.state.timekeeper = res.timekeeper || res.state.timekeeper;
      }
      document.querySelectorAll(
        "[data-gc-card-queue], [data-hero-queue], [data-mini-queue-card], [data-server-remaining], [data-timer-target]"
      ).forEach((el) => {
        if (el && el.dataset) delete el.dataset.serverRemaining;
      });
      applyActionState(res, "timekeeper_apply");
    } catch (err) {
      console.error("[GC] timekeeper apply failed", err);
      showNotify(t("msg_action_failed", "Aktion fehlgeschlagen. Bitte erneut versuchen."), "error");
    } finally {
      _timekeeperApplying = false;
      setProgressionActionBusy(openBtn, false);
      if (GC.lastState && GC.lastState.ok !== false) {
        _finalizeTimekeeperQueueButtons(GC.lastState);
      } else {
        patchShellHudTimekeeper(GC.lastState || {});
      }
    }
  }

  function initTimekeeperOnce() {
    if (GC._timekeeperReady) return;
    GC._timekeeperReady = true;

    document.addEventListener("click", (ev) => {
      const openBtn = ev.target.closest("[data-gc-timekeeper-apply]");
      if (!openBtn || openBtn.disabled) return;
      ev.preventDefault();
      ev.stopPropagation();
      void submitTimekeeperApplyFromBtn(openBtn);
    });
  }

  function patchShellHudFromState(data, opts) {
    if (!data || data.ok === false) return;
    const forceResourceBar = Boolean(opts && opts.forceResourceBar);
    const allowResourceRegression = Boolean(opts && opts.allowResourceRegression);
    const resourceOverrides = opts && opts.resourceOverrides;

    const p = data.player || {};
    const energy = data.energy || {};
    const resources = data.resources || {};
    const storage = data.storage || {};
    const prod = data.production_per_hour || {};

    // Partial HUD merges (SSR fleet/unread boot) must not wipe SSR resource amounts to 0.
    const hasResourceSnapshot = Boolean(
      resourceOverrides ||
      (data.player &&
        (data.player.metal != null ||
          data.player.crystal != null ||
          data.player.fuel_cells != null)) ||
      (data.resources &&
        (data.resources.metal != null ||
          data.resources.crystal != null ||
          data.resources.fuel_cells != null))
    );

    const storageMetal = Math.floor(Number(storage.metal || 0));
    const storageCrystal = Math.floor(Number(storage.crystal || 0));
    const storageFuelCells = Math.floor(Number(storage.fuel_cells || 0));

    let metal = resourceOverrides && resourceOverrides.metal != null
      ? Math.floor(Number(resourceOverrides.metal))
      : Math.floor(Number(p.metal ?? resources.metal ?? 0));
    let crystal = resourceOverrides && resourceOverrides.crystal != null
      ? Math.floor(Number(resourceOverrides.crystal))
      : Math.floor(Number(p.crystal ?? resources.crystal ?? 0));
    let fuelCells = resourceOverrides && resourceOverrides.fuelCells != null
      ? Math.floor(Number(resourceOverrides.fuelCells))
      : Math.floor(Number(p.fuel_cells ?? resources.fuel_cells ?? 0));

    if (!forceResourceBar && !allowResourceRegression) {
      const projected = projectLiveResourceAmounts(getApproxServerNow());
      metal = Math.max(metal, _last.metal ?? 0, projected?.metal ?? 0);
      crystal = Math.max(crystal, _last.crystal ?? 0, projected?.crystal ?? 0);
      fuelCells = Math.max(fuelCells, _last.fuelCells ?? 0, projected?.fuelCells ?? 0);
    }
    const used = Math.floor(Number(p.energy_used ?? energy.used ?? resources.energy_used ?? 0));
    const total = Math.floor(Number(p.energy_total ?? energy.total ?? resources.energy_total ?? 0));

    const prodMetal = Math.floor(Number(prod.metal_mine ?? prod.metal ?? 0));
    const prodCrystal = Math.floor(Number(prod.crystal_mine ?? prod.crystal ?? 0));
    const prodFuelCells = Math.floor(Number(prod.fuel_cell_plant ?? prod.fuel_cells ?? 0));

    const bar = document.getElementById("resource-bar");
    if (bar && hasResourceSnapshot) {
      if (forceResourceBar || _last.metal !== metal) {
        bar.querySelectorAll(".res-value.metal").forEach((el) => { _setIfChanged(el, fmtNumber(metal)); });
        _last.metal = metal;
        _resourceDisplay.metal = metal;
      }
      if (forceResourceBar || _last.crystal !== crystal) {
        bar.querySelectorAll(".res-value.crystal").forEach((el) => { _setIfChanged(el, fmtNumber(crystal)); });
        _last.crystal = crystal;
        _resourceDisplay.crystal = crystal;
      }
      if (forceResourceBar || (_last.storageMetal !== storageMetal && storageMetal > 0)) {
        bar.querySelectorAll(".res-cap.metal").forEach((el) => { _setIfChanged(el, fmtNumber(storageMetal)); });
        _last.storageMetal = storageMetal;
      }
      if (forceResourceBar || (_last.storageCrystal !== storageCrystal && storageCrystal > 0)) {
        bar.querySelectorAll(".res-cap.crystal").forEach((el) => { _setIfChanged(el, fmtNumber(storageCrystal)); });
        _last.storageCrystal = storageCrystal;
      }
      if (forceResourceBar || _last.fuelCells !== fuelCells) {
        bar.querySelectorAll(".res-value.fuel_cells").forEach((el) => { _setIfChanged(el, fmtNumber(fuelCells)); });
        _last.fuelCells = fuelCells;
        _resourceDisplay.fuelCells = fuelCells;
      }
      if (forceResourceBar || (_last.storageFuelCells !== storageFuelCells && storageFuelCells > 0)) {
        bar.querySelectorAll(".res-cap.fuel_cells").forEach((el) => {
          _setIfChanged(el, fmtNumber(storageFuelCells));
        });
        _last.storageFuelCells = storageFuelCells;
      }

      const rateLabel = (key, perHour) => {
        const ph = Math.floor(Number(perHour) || 0);
        bar.querySelectorAll(`[data-res-rate="${key}"]`).forEach((el) => {
          if (ph > 0) {
            const sign = ph >= 0 ? "+" : "";
            _setIfChanged(el, `${sign}${fmtNumber(ph)}/h`);
            el.style.visibility = "visible";
            el.removeAttribute("hidden");
            el.removeAttribute("aria-hidden");
          } else {
            _setIfChanged(el, "");
            el.style.visibility = "hidden";
            el.setAttribute("aria-hidden", "true");
          }
        });
      };

      if (forceResourceBar || _last.prodMetal !== prodMetal) {
        rateLabel("metal", prodMetal);
        _last.prodMetal = prodMetal;
      }
      if (forceResourceBar || _last.prodCrystal !== prodCrystal) {
        rateLabel("crystal", prodCrystal);
        _last.prodCrystal = prodCrystal;
      }
      if (forceResourceBar || _last.prodFuelCells !== prodFuelCells) {
        rateLabel("fuel_cells", prodFuelCells);
        _last.prodFuelCells = prodFuelCells;
      }

      const energyCapText = total > 0 ? fmtNumber(total) : "—";
      const energyText = `${fmtNumber(used)}/${energyCapText}`;
      if (forceResourceBar || _last.energyUsed !== used || _last.energyTotal !== total) {
        bar.querySelectorAll(".res-value.energy[data-energy-used], [data-energy-used]").forEach((el) => {
          _setIfChanged(el, fmtNumber(used));
        });
        bar.querySelectorAll(".res-cap.energy[data-energy-total], [data-energy-total]").forEach((el) => {
          _setIfChanged(el, energyCapText);
        });
        const energyEl = bar.querySelector("#res-energy") || document.getElementById("res-energy");
        if (energyEl) _setIfChanged(energyEl, energyText);
        _last.energyUsed = used;
        _last.energyTotal = total;
      }
      patchResourceBarEnergyWarning(used, total);
      patchHudStorageWarnings(metal, crystal, fuelCells, storageMetal, storageCrystal, storageFuelCells);
      patchHudCapacityBars(metal, crystal, fuelCells, storageMetal, storageCrystal, storageFuelCells, used, total, {
        animate: forceResourceBar,
      });
    }

    patchShellHudBoosters(data);
    patchShellHudTimekeeper(data);

    patchHeaderPlanetLimitFromState(data, forceResourceBar);

    if (data.score) {
      const s = data.score;
      const serverTotal = Number(s.total || 0);
      const rank = typeof s.rank === "number" ? s.rank : Number(s.rank || 0);
      const totalPlayers = Number(s.total_players || 0);
      const scoreStale = _scoreState.lastServerTotal !== null
        && serverTotal < _scoreState.lastServerTotal
        && !forceResourceBar;

      if (!scoreStale) {
        let delta = 0;
        if (_scoreState.lastServerTotal !== null && serverTotal > _scoreState.lastServerTotal) {
          delta = serverTotal - _scoreState.lastServerTotal;
        }
        _scoreState.lastServerTotal = serverTotal;

        const hudScoreEl = document.getElementById("hud-score-total");
        const hudRankEl = document.getElementById("hud-score-rank");

        if (hudScoreEl && _scoreState.lastAnimatedTotal !== serverTotal) {
          setScoreDisplayInstant(hudScoreEl, serverTotal);
          if (delta !== 0) showScoreDelta(delta, serverTotal);
          _scoreState.lastAnimatedTotal = serverTotal;
        }

        const rankText = (rank >= 1 && totalPlayers > 0) ? `#${rank}/${totalPlayers}` : "#–";
        if (hudRankEl) _setIfChanged(hudRankEl, rankText);
      }
    }

    const stats = data.player_stats || {};
    const onlineNow = Number(stats.online_now);
    const onlineTotal = Number(stats.total_players);
    if (Number.isFinite(onlineNow) && Number.isFinite(onlineTotal)) {
      const onlineText = `${fmtNumber(onlineNow)}/${fmtNumber(onlineTotal)}`;
      if (_lastHudOnline !== onlineText) {
        document.querySelectorAll("[data-hud-online-value]").forEach((el) => {
          _setIfChanged(el, onlineText);
        });
        _lastHudOnline = onlineText;
      }
    }

    if (typeof data.unread_messages_count === "number" && !(opts && opts.skipMessagesUnread)) {
      updateMessagesUnreadBadges(data.unread_messages_count);
    }

    if (data.nav_badges) {
      updateNavBadges(data.nav_badges);
    }

    if (data.active_fleets !== undefined) {
      const fleetResolved = resolveFleetHudPayload(data.active_fleets, {
        reason: (opts && opts.reason) || "",
        stateVersion: extractStateVersion(data),
        stateContext: data,
        mergePartial: Boolean(opts && opts.mergePartial),
      });
      if (fleetResolved && fleetResolved.payload) {
        renderGlobalFleetHud(data.active_fleets, {
          reason: (opts && opts.reason) || "",
          stateVersion: extractStateVersion(data),
          stateContext: data,
        });
      }
      if (typeof GC.notifyActiveFleetsListeners === "function") {
        GC.notifyActiveFleetsListeners(data.active_fleets, {
          reason: (opts && opts.reason) || "",
        });
      }
    }

    if (data.fleet_alerts !== undefined) {
      const alertSig = fleetAlertsHudSignature(data.fleet_alerts);
      if (alertSig !== _lastFleetAlertsHudSig) {
        _lastFleetAlertsHudSig = alertSig;
        _maybePlayIncomingAttackNotify(data.fleet_alerts);
        syncFleetAttackAlert(data.fleet_alerts);
      }
    }

    if (data.account_safety !== undefined) {
      syncFleetVacationNotice(data.account_safety);
      syncHeaderVacationBanner(data.account_safety);
    }

    if (data.fleet_slots) {
      syncFleetSlotsBadgeFromState(data.fleet_slots);
    }

    if (data.global_queue_hud !== undefined || data.build_queue !== undefined) {
      renderGlobalQueueHud(data.global_queue_hud || data);
    }

    markNotificationFreshFromGameState(data);
  }

  GC.patchShellHudFromState = patchShellHudFromState;

  /** GC-DEBRIS-LIVE-01 — page listeners for active_fleets deltas (Galaxy recycle arrival sync). */
  GC._activeFleetsListeners = GC._activeFleetsListeners || [];
  GC.registerActiveFleetsListener = function registerActiveFleetsListener(fn) {
    if (typeof fn !== "function") return () => {};
    GC._activeFleetsListeners.push(fn);
    return () => {
      GC._activeFleetsListeners = (GC._activeFleetsListeners || []).filter((cb) => cb !== fn);
    };
  };
  GC.notifyActiveFleetsListeners = function notifyActiveFleetsListeners(fleetsRaw, meta) {
    const list = GC._activeFleetsListeners || [];
    if (!list.length) return;
    for (const fn of list) {
      try {
        fn(fleetsRaw, meta || {});
      } catch (e) {
        console.error("[GC] activeFleets listener error", e);
      }
    }
  };

  GC.mergeLastState = function mergeLastState(partial, reason) {
    if (!partial || typeof partial !== "object") return GC.lastState;
    const base = GC.lastState && GC.lastState.ok === true ? GC.lastState : { ok: true };
    GC.lastState = { ...base, ...partial };
    if (typeof partial.unread_messages_count === "number" && String(reason || "").includes("messages")) {
      _messagesUnreadLocalAt = Date.now();
    }
    patchShellHudFromState(GC.lastState, { forceResourceBar: true, reason: reason || "merge" });
    return GC.lastState;
  };

  function patchOverviewScoreFromState(data) {
    if (!data || !data.score) return;
    const s = data.score;
    const serverTotal = Number(s.total || 0);
    const rank = typeof s.rank === "number" ? s.rank : Number(s.rank || 0);
    const totalPlayers = Number(s.total_players || 0);
    const scoreBuildings = Number(s.buildings || 0);
    const scoreResearch = Number(s.research || 0);

    const scoreStale = _scoreState.lastServerTotal !== null && serverTotal < _scoreState.lastServerTotal;
    if (scoreStale) return;

    const ovScoreVal = document.getElementById("overview-score-value");
    const ovScoreRank = document.getElementById("overview-score-rank");
    const ovScoreBuild = document.getElementById("overview-score-buildings");
    const ovScoreRes = document.getElementById("overview-score-research");

    if (ovScoreVal) {
      setScoreDisplayInstant(ovScoreVal, serverTotal);
    }
    if (ovScoreRank) {
      ovScoreRank.textContent = (rank >= 1 && totalPlayers > 0) ? `#${rank}/${totalPlayers}` : "#–/–";
    }
    if (ovScoreBuild) animateNumber(ovScoreBuild, scoreBuildings, { duration: 650, fmt: formatScore });
    if (ovScoreRes) animateNumber(ovScoreRes, scoreResearch, { duration: 650, fmt: formatScore });
  }

  // =========================
  function patchResearchPanelFromState(data) {
    renderResearchQueue((data && data.research) || null);
  }

  function patchShipyardPanelFromState(data, activePlanetId) {
    const page = document.getElementById("shipyard-page");
    if (!page || page.dataset.ready !== "1") return;
    const statePid = Number(
      activePlanetId || data?.active_planet_id || GC.lastState?.active_planet_id || 0
    );
    const pagePid = Number(page.dataset.planetId || 0);
    if (statePid > 0 && pagePid > 0 && pagePid !== statePid) {
      _lastShipyardQueueSignature = "";
      SHIPYARDQ.active.finishTime = 0;
      SHIPYARDQ.active.totalSeconds = 0;
      refreshShipyardStateCoalesced(page);
      return;
    }
    const slice = data?.shipyard;
    if (slice && typeof slice === "object") {
      const inner = slice.ships && typeof slice.ships === "object" ? slice.ships : null;
      if (inner && inner.ready !== false) {
        applyShipyardState(page, {
          ...inner,
          shipyard_queue: slice.queue || inner.shipyard_queue,
        });
        return;
      }
    }
    if (data?.shipyard_queue) {
      renderShipyardQueue(page, data.shipyard_queue);
    }
  }

  function patchDefensePanelFromGameState(data, activePlanetId) {
    const page = document.getElementById("defense-page");
    if (!page || page.dataset.ready !== "1" || !data?.defense) return;
    const statePid = Number(
      activePlanetId || data?.active_planet_id || GC.lastState?.active_planet_id || 0
    );
    const pagePid = Number(page.dataset.planetId || 0);
    if (statePid > 0 && pagePid > 0 && pagePid !== statePid) return;
    const slice = data.defense;
    const inner = slice.defenses && typeof slice.defenses === "object" ? slice.defenses : null;
    if (inner && inner.ready !== false) {
      applyDefenseState(page, {
        ...inner,
        defense_queue: slice.queue || inner.defense_queue,
      });
      return;
    }
    // GC-PERF-TK-004: queue-only slim slice (no stock catalog)
    if (slice.queue) {
      renderDefenseQueue(page, slice.queue);
    }
  }

  function syncProductionPanelsAfterGameState(data, reason, activePlanetId) {
    patchDefensePanelFromGameState(data, activePlanetId);
    const reasonStr = String(reason || "");
    const onShipyard = document.getElementById("shipyard-page")?.dataset.ready === "1";
    const onDefense = document.getElementById("defense-page")?.dataset.ready === "1";
    const completionReason =
      reasonStr === "timer_done"
      || reasonStr === "queue_timer_zero"
      || reasonStr.endsWith("_finished")
      || reasonStr === "shipyard_build"
      || reasonStr === "shipyard_cancel"
      || reasonStr === "defense_build"
      || reasonStr === "defense_cancel"
      || reasonStr === "timekeeper_apply";
    if (onShipyard && completionReason && !data?.shipyard && !data?.shipyard_queue) {
      const syPage = document.getElementById("shipyard-page");
      if (syPage) refreshShipyardStateCoalesced(syPage);
    }
    if (onDefense && completionReason && !data?.defense) {
      const defPage = document.getElementById("defense-page");
      if (defPage) refreshDefenseStateCoalesced(defPage);
    }
  }

  const _HUD_LAST_STATE_KEYS = [
    "ok",
    "server_time",
    "server_now",
    "active_planet_id",
    "active_planet_name",
    "active_planet",
    "planets",
    "planet_limit",
    "player",
    "resources",
    "energy",
    "storage",
    "production_per_hour",
    "score",
    "unread_messages_count",
    "nav_badges",
    "build_queue",
    "research",
    "global_queue_hud",
    "active_fleets",
    "fleet_slots",
    "account_safety",
    "active_boosters",
    "player_id",
    "energy_efficiency_pct",
    "energy_ratio",
    "buildings",
    "timekeeper",
  ];

  function isHudOnlyGameStateReason(reason) {
    const r = String(reason || "");
    return (
      r === "poll"
      || r === "page_init"
      || r === "tab_visible"
      || r === "admin_hud"
      || r === "pjax_nav"
      || r === "fleet_countdown_expired"
      || r === "fleet_drawer_boot"
      || r === "resource_rates_missing"
    );
  }

  function isPageReloadGameStateReason(reason) {
    const r = String(reason || "");
    if (r === "planet_evolution_finished" || r === "fleet_countdown_expired") return false;
    return r === "timer_done" || r === "queue_timer_zero" || r.endsWith("_finished");
  }

  function patchHudLastState(data, reason) {
    if (!data || data.ok === false) return;
    const next = coercePollUnreadForHud(data, reason);
    if (!GC.lastState || GC.lastState.ok !== true) {
      GC.lastState = { ...next };
      return;
    }
    const merged = { ...GC.lastState };
    _HUD_LAST_STATE_KEYS.forEach((key) => {
      if (!(key in next) || next[key] === undefined) return;
      // Never poison switcher/cache with empty diet/error payloads.
      if (key === "planets" && Array.isArray(next[key]) && next[key].length === 0) return;
      if (key === "active_fleets") {
        const incoming = next.active_fleets;
        if (isActiveFleetsPayloadMissing(incoming)) return;
        if (isFleetHudConfirmedEmpty(incoming)) {
          const current = merged.active_fleets;
          if (current && normalizeActiveFleetsPayload(current).count > 0) {
            const incV = extractStateVersion(next);
            const curV = extractStateVersion(merged);
            if (incV > 0 && curV > 0 && incV < curV - 0.001) return;
            if (incV > 0 && incV < _fleetHudActionVersion - 0.001) return;
          }
        }
      }
      merged[key] = next[key];
    });
    if (next.research && typeof next.research === "object") {
      merged.research = { ...(merged.research || {}), ...next.research };
      if (!Array.isArray(next.research.techs)) delete merged.research.techs;
    }
    GC.lastState = merged;
  }

  function commitGameStateCache(data, reason, opts) {
    if (opts && opts.hudOnly) {
      patchHudLastState(data, reason);
      return;
    }
    if (isHudOnlyGameStateReason(reason)) {
      patchHudLastState(data, reason);
      return;
    }
    const reasonStr = String(reason || "");
    // GC-PERF-TK-004: slim TK apply must not wipe production queue caches.
    if (reasonStr === "timekeeper_apply" && GC.lastState && data && typeof data === "object") {
      const prev = GC.lastState;
      const merged = { ...data };
      if (merged.shipyard == null && prev.shipyard != null) merged.shipyard = prev.shipyard;
      if (merged.shipyard_queue == null && prev.shipyard_queue != null) {
        merged.shipyard_queue = prev.shipyard_queue;
      }
      if (merged.defense == null && prev.defense != null) merged.defense = prev.defense;
      GC.lastState = coercePollUnreadForHud(merged, reason);
      return;
    }
    GC.lastState = coercePollUnreadForHud(data, reason);
  }

  function syncHudQueueLiveStatesFromPoll(data) {
    const buildQueueRaw = data?.build_queue || null;
    let queueList = [];
    if (Array.isArray(buildQueueRaw)) queueList = buildQueueRaw;
    else if (buildQueueRaw && Array.isArray(buildQueueRaw.queue)) queueList = buildQueueRaw.queue;
    _syncBuildQueueLiveState(queueList);

    const research = data?.research || {};
    const activeResearch = research.active || null;
    const researchQueue = Array.isArray(research.queue)
      ? research.queue
      : (activeResearch ? [activeResearch] : []);
    _syncResearchQueueLiveState(researchQueue);

    const hudJobs = data?.global_queue_hud?.jobs;
    if (Array.isArray(hudJobs)) {
      hudJobs.forEach((job) => {
        const kind = String(job?.kind || job?.domain || "");
        if (kind === "shipyard" || kind === "shipyard_queue") {
          _syncShipyardQueueLiveState([job]);
        } else if (kind === "defense" || kind === "defense_queue") {
          _syncDefenseQueueLiveState([job]);
        }
      });
    }
    if (data?.defense) {
      const defSlice = data.defense.queue || data.defense.defense_queue;
      const defQ = defSlice?.queue ?? defSlice;
      if (Array.isArray(defQ)) _syncDefenseQueueLiveState(defQ);
    }

    const hasActiveBuild = queueList.length > 0;
    const bqLimitFinal = buildQueueRaw?.summary?.limit ?? 3;
    const bqCountFinal = buildQueueRaw?.summary?.count ?? queueList.length;
    lastBuildQueueCount = bqCountFinal;
    lastBuildQueueFull = bqCountFinal >= bqLimitFinal;
    lastHadActiveJob = hasActiveBuild;

    const hasActiveResearchNow = researchQueue.length > 0;
    const rqLimitFinal = research?.summary?.limit ?? 3;
    const rqCountFinal = research?.summary?.count ?? researchQueue.length;
    lastResearchQueueCount = rqCountFinal;
    lastResearchQueueFull = rqCountFinal >= rqLimitFinal;
    lastHadActiveResearch = hasActiveResearchNow;
    lastHadActiveShipyard = SHIPYARDQ.active.finishTime > getTimerServerNow();
    lastHadActiveDefense = DEFENSEQ.active.finishTime > getTimerServerNow();
    syncActiveFleetBusyFromState(data);

    return hasBusyLiveActivity();
  }

  function shouldSyncRoleSidebarFromHudData(data, reason) {
    const planetId = Number(data?.active_planet_id || data?.active_planet?.planet_id || 0);
    if (!planetId) return false;
    const r = String(reason || "");
    if (r === "admin_balance_save" || r === "admin_balance_preset") return false;
    return true;
  }

  function applyHudOnlyGameState(data, reason, opts) {
    if (shouldRejectStaleGameState(data, reason, opts)) return false;
    const fetchSeq = Number((opts && opts._fetchSeq) || 0);
    if (fetchSeq > 0 && fetchSeq < _gameStateFetchAppliedSeq) return false;
    markGameStateVersionApplied(data);

    const forceResourceBar = Boolean(opts && (opts.forceResourceBar || opts.planetSwitch));
    const skipMessagesUnread = Boolean(opts && opts.skipMessagesUnread);
    const activePlanetId = Number(data.active_planet_id || data.build_queue?.planet_id || 0);

    if (typeof GC.updatePlanetRegistryFromState === "function") {
      GC.updatePlanetRegistryFromState(data);
    }
    if (typeof GC.syncRoleBasedSidebar === "function" && shouldSyncRoleSidebarFromHudData(data, reason)) {
      GC.syncRoleBasedSidebar(data);
    }
    if (shouldRunGameLoop()) {
      applyPlanetLandscapeFromState(data);
    }

    const p = data.player || {};
    const energy = data.energy || {};
    const resources = data.resources || {};
    const prod = data.production_per_hour || {};
    const storage = data.storage || {};

    patchShellHudFromState(coercePollUnreadForHud(data, reason), {
      forceResourceBar,
      skipMessagesUnread,
      allowResourceRegression: Boolean(opts && opts.allowResourceRegression),
      reason,
    });
    _processUnreadMessagesPoll(data, reason, opts);

    syncResourceLiveBaseline({
      planetId: activePlanetId,
      metal: Math.floor(Number(p.metal ?? resources.metal ?? 0)),
      crystal: Math.floor(Number(p.crystal ?? resources.crystal ?? 0)),
      fuelCells: Math.floor(Number(p.fuel_cells ?? resources.fuel_cells ?? 0)),
      prodMetal: Math.floor(Number(prod.metal_mine ?? prod.metal ?? 0)),
      prodCrystal: Math.floor(Number(prod.crystal_mine ?? prod.crystal ?? 0)),
      prodFuelCells: Math.floor(Number(prod.fuel_cell_plant ?? prod.fuel_cells ?? 0)),
      storageMetal: Math.floor(Number(storage.metal || 0)),
      storageCrystal: Math.floor(Number(storage.crystal || 0)),
      storageFuelCells: Math.floor(Number(storage.fuel_cells || 0)),
      energyUsed: Math.floor(Number(p.energy_used ?? energy.used ?? resources.energy_used ?? 0)),
      energyTotal: Math.floor(Number(p.energy_total ?? energy.total ?? resources.energy_total ?? 0)),
    }, opts);

    let anyActive = false;
    if (shouldRunGameLoop()) {
      anyActive = syncHudQueueLiveStatesFromPoll(data);
      syncMountedQueuePagesFromState(data, reason);
      GC.startProgressTicker();
    }
    patchHudLastState(data, reason);
    markGameStateFetchApplied(opts);
    syncPerfBodyClasses();
    return anyActive;
  }

  // Status polling / GC.refreshGameState
  // =========================
  function applyGameStateData(data, _reason, opts) {
      if (!data || data.ok === false) return false;
      const reason = String(_reason || "");
      const fetchSeq = Number((opts && opts._fetchSeq) || 0);
      if (fetchSeq > 0 && fetchSeq < _gameStateFetchAppliedSeq) return false;
      resetClientStateForAccountChange(
        data.player_id || readDomPlayerId(),
        reason || "game_state"
      );
      const skipMessagesUnread = Boolean(opts && opts.skipMessagesUnread);
      const hudOnly = Boolean(opts && opts.hudOnly) || isHudOnlyGameStateReason(reason);
      if (hudOnly) {
        return applyHudOnlyGameState(data, reason, {
          ...opts,
          skipMessagesUnread,
          hudOnly: true,
        });
      }
      const forceResourceBar = Boolean(opts && (opts.forceResourceBar || opts.planetSwitch));
      const planetSwitch = Boolean(opts && opts.planetSwitch);
      const planetSwitchReload = Boolean(opts && opts.planetSwitchReload);
      const skipScopedPanels = Boolean(
        (opts && opts.skipScopedPanels) || (planetSwitch && !planetSwitchReload)
      );
      const forcePanel = Boolean(opts && opts.forcePanel) || isMutationStatePatchReason(reason);

      if (shouldRejectStaleGameState(data, reason, opts)) return false;
      markGameStateVersionApplied(data);

      syncServerClockFromState(data);

      const activePlanetId = Number(data.active_planet_id || data.build_queue?.planet_id || 0);
      if (!hudOnly) {
        if (
          _last.activePlanetId !== null &&
          activePlanetId > 0 &&
          _last.activePlanetId !== activePlanetId
        ) {
          // Build queue is per active colony — never reuse the previous planet's panel state.
          _lastQueueSignature = "";
          _lastResearchQueueSignature = "";
          _lastShipyardQueueSignature = "";
          _lastDefenseQueueSignature = "";
          _resetQueueLiveStates();
        }
        if (activePlanetId > 0) {
          _last.activePlanetId = activePlanetId;
          if (!skipScopedPanels) syncScopedPlanetIds(activePlanetId);
        }

        if (planetSwitch && activePlanetId > 0) {
          const fleetPage = document.getElementById("fleet-page");
          if (fleetPage) {
            fleetPage._fleetApplySeq = 0;
            fleetPage._fleetLiveServerTime = 0;
            delete fleetPage.dataset.fleetUrlMission;
            if (fleetPage._fleetRt) {
              fleetPage._fleetRt.lastPreview = null;
              if (fleetPage._fleetRt.previewTimer) {
                clearTimeout(fleetPage._fleetRt.previewTimer);
                fleetPage._fleetRt.previewTimer = null;
              }
            }
          }
        } else if (_reason !== "planet_switch") {
          reloadPageForActivePlanet(activePlanetId, _reason || "state");
        }

        if (typeof GC.updatePlanetRegistryFromState === "function") {
          GC.updatePlanetRegistryFromState(data);
        }

        if (typeof GC.syncRoleBasedSidebar === "function") {
          GC.syncRoleBasedSidebar(data);
        }

        applyPlanetLandscapeFromState(data);
      }

      const p = data.player || {};
      const energy = data.energy || {};
      const resources = data.resources || {};
      const buildings = data.buildings || {};
      const buildQueueRaw = data.build_queue || null;
      const prod = data.production_per_hour || {};
      const research = data.research || {};
      const activeResearch = research.active || null;
      const storage = data.storage || {};

      const storageMetal = Math.floor(Number(storage.metal || 0));
      const storageCrystal = Math.floor(Number(storage.crystal || 0));
      const storageFuelCells = Math.floor(Number(storage.fuel_cells || 0));

      const metal = Math.floor(Number(p.metal ?? resources.metal ?? 0));
      const crystal = Math.floor(Number(p.crystal ?? resources.crystal ?? 0));
      const fuelCells = Math.floor(Number(p.fuel_cells ?? resources.fuel_cells ?? 0));
      const used = Math.floor(Number(p.energy_used ?? energy.used ?? resources.energy_used ?? 0));
      const total = Math.floor(Number(p.energy_total ?? energy.total ?? resources.energy_total ?? 0));

      const prodMetal = Math.floor(Number(prod.metal_mine ?? prod.metal ?? 0));
      const prodCrystal = Math.floor(Number(prod.crystal_mine ?? prod.crystal ?? 0));
      const prodFuelCells = Math.floor(Number(prod.fuel_cell_plant ?? prod.fuel_cells ?? 0));

      patchShellHudFromState(coercePollUnreadForHud(data, reason), {
        forceResourceBar,
        skipMessagesUnread,
        allowResourceRegression: Boolean(opts && opts.allowResourceRegression),
        reason,
      });
      _processUnreadMessagesPoll(data, reason, { skipMessagesUnread });

      const livePlanetId = activePlanetId > 0
        ? activePlanetId
        : Number(data.active_planet_id || data.build_queue?.planet_id || 0);
      syncResourceLiveBaseline({
        planetId: livePlanetId,
        metal,
        crystal,
        fuelCells,
        prodMetal,
        prodCrystal,
        prodFuelCells,
        storageMetal,
        storageCrystal,
        storageFuelCells,
        energyUsed: used,
        energyTotal: total,
      }, opts);

      if (skipScopedPanels) {
        commitGameStateCache(data, reason, opts);
        markGameStateFetchApplied(opts);
        return false;
      }

      // --- Queue tracking (always — ticker intervals / polling cadence) ---
      let queueList = [];
      if (Array.isArray(buildQueueRaw)) queueList = buildQueueRaw;
      else if (buildQueueRaw && Array.isArray(buildQueueRaw.queue)) queueList = buildQueueRaw.queue;

      const activeJob = queueList.length > 0 ? queueList[0] : null;
      _syncBuildQueueLiveState(queueList);

      const researchQueue = Array.isArray(research.queue) ? research.queue : (activeResearch ? [activeResearch] : []);
      _syncResearchQueueLiveState(researchQueue);

      if (data.shipyard?.queue) {
        const syJobs = Array.isArray(data.shipyard.queue.queue) ? data.shipyard.queue.queue : [];
        _syncShipyardQueueLiveState(syJobs);
      } else if (data.shipyard_queue) {
        const syJobs = Array.isArray(data.shipyard_queue.queue) ? data.shipyard_queue.queue : [];
        _syncShipyardQueueLiveState(syJobs);
      }
      if (data.defense) {
        const defSlice = data.defense.queue || data.defense.defense_queue;
        const defQ = defSlice?.queue ?? defSlice;
        if (Array.isArray(defQ)) _syncDefenseQueueLiveState(defQ);
      }

      const hasActiveBuild = !!activeJob;
      const bqLimitFinal = buildQueueRaw?.summary?.limit ?? 3;
      const bqCountFinal = buildQueueRaw?.summary?.count ?? queueList.length;
      lastBuildQueueCount = bqCountFinal;
      lastBuildQueueFull = bqCountFinal >= bqLimitFinal;
      lastHadActiveJob = hasActiveBuild;

      const hasActiveResearchNow = researchQueue.length > 0;
      const rqLimitFinal = research?.summary?.limit ?? 3;
      const rqCountFinal = research?.summary?.count ?? researchQueue.length;
      lastResearchQueueCount = rqCountFinal;
      lastResearchQueueFull = rqCountFinal >= rqLimitFinal;
      lastHadActiveResearch = hasActiveResearchNow;
      lastHadActiveShipyard = SHIPYARDQ.active.finishTime > getTimerServerNow();
      lastHadActiveDefense = DEFENSEQ.active.finishTime > getTimerServerNow();
      syncActiveFleetBusyFromState(data);

      renderBuildQueue(buildQueueRaw);

      if (shouldPatchGameStateModule("overview", { forcePanel })) {
        patchOverviewScoreFromState(data);
        patchOverviewResearch(research);
        patchOverviewStatus(data.overview, data, buildings, prod);
        if (data.planet_teaser) patchPlanetTeaser(data.planet_teaser);
      }
      if (typeof GC.patchPlanetRelocationFromState === "function") {
        GC.patchPlanetRelocationFromState(data);
      }

      if (forcePanel || shouldPatchGameStateModule("buildings")) {
      Object.keys(BUILDINGS).forEach((key) => {
        const cfg = BUILDINGS[key];
        const lvl = buildings[key];

        if (typeof lvl !== "undefined" && cfg.levelId) setText(cfg.levelId, lvl);

        const prodCell = document.querySelector(`.bcell-prod[data-building="${key}"]`);
        if (prodCell) {
          if (key === "metal_storage" && storageMetal > 0) {
            _setIfChanged(prodCell, `${fmtNumber(metal)} / ${fmtNumber(storageMetal)}`);
          } else if (key === "crystal_storage" && storageCrystal > 0) {
            _setIfChanged(prodCell, `${fmtNumber(crystal)} / ${fmtNumber(storageCrystal)}`);
          } else if (key === "fuel_storage" && storageFuelCells > 0) {
            _setIfChanged(prodCell, `${fmtNumber(fuelCells)} / ${fmtNumber(storageFuelCells)}`);
          } else {
            const val = Math.floor(prod[key] || 0);
            _setIfChanged(prodCell, val > 0 ? `${fmtNumber(val)} / h` : "-");
          }
        }

        const queueActive = queueList.length > 0;
        const bqLimit = buildQueueRaw?.summary?.limit ?? 3;
        const bqCount = buildQueueRaw?.summary?.count ?? queueList.length;
        const bqFull = bqCount >= bqLimit;
        let statusText = t("status_ready", "Bereit");
        let btnLabel = queueActive ? t("action_queue_upgrade", "Upgrade (anreihen)") : t("action_upgrade", "Upgrade");

        if (queueActive && activeJob && activeJob.building_type === key) {
          const finishAt = resolveQueueJobFinishTime(activeJob);
          const rem = finishAt
            ? queueJobRemainingSeconds(finishAt, getTimerServerNow(), resolveQueueJobRemaining(activeJob))
            : Math.max(0, Math.floor(Number(activeJob.remaining || activeJob.remaining_seconds || 0)));
          statusText = `${t("status_building", "Im Bau")} (${formatEta(Math.ceil(rem))})`;
        }

        if (cfg.statusId) setText(cfg.statusId, statusText);

        const btn = document.getElementById(cfg.btnId);
        if (btn && btn.classList.contains("gc-bld-head-action-btn")) {
          if (btn.getAttribute("aria-label") !== btnLabel) {
            btn.setAttribute("aria-label", btnLabel);
            btn.title = btnLabel;
          }
        } else if (btn && btn.tagName === "A" && !bqFull && btn.textContent !== btnLabel) {
          btn.textContent = btnLabel;
        }
      });

      updateBuildQueueActions(buildQueueRaw);

      const buildingsPanelPatch = data.buildings_panel || data.buildings_panel_delta;
      if (buildingsPanelPatch) {
        patchBuildingPanel(buildingsPanelPatch, buildQueueRaw);
      } else if (forcePanel && buildQueueRaw != null) {
        patchCardQueuesFromOwnerMap(
          document,
          resolveCardJobsByOwner(buildQueueRaw),
          (root) => root.querySelectorAll("[data-building-row]"),
          (row) => row.getAttribute("data-building-row") || "",
          (root, key) => root.querySelector(`[data-building-row="${key}"]`)
        );
        updateBuildQueueActions(buildQueueRaw);
      }
      }

      if (forcePanel || shouldPatchGameStateModule("research")) {
        patchResearchPanelFromState(data);
        updateResearchQueueActions(research);

        if (activeResearch) {
          const totalSec = Math.max(
            1,
            parseInt(activeResearch.total_seconds, 10) ||
              parseInt(activeResearch.total, 10) ||
              (resolveQueueJobRemaining(activeResearch) || 0) + 1
          );
          const totalLabel = document.getElementById("research-total");
          if (totalLabel) _setIfChanged(totalLabel, `${totalSec}s`);
        }
      }

      if (shouldPatchGameStateModule("trader", { forcePanel })) {
        if (data.exchange) patchExchangePanel(data.exchange);
        if (data.scrapyard) patchScrapyardPanel(data.scrapyard);
        if (data.collector_exchange) patchCollectorExchangePanel(data.collector_exchange);
        if (data.auction_house) patchAuctionHousePanel(data.auction_house);
      }

      if (forcePanel || shouldPatchGameStateModule("shipyard")) {
        patchShipyardPanelFromState(data, activePlanetId);
      }

      if ((forcePanel || shouldPatchGameStateModule("research")) && research.techs) {
        patchResearchPanel(research.techs, research);
      } else if (forcePanel && document.querySelector(".research-prog-list")) {
        patchCardQueuesFromOwnerMap(
          document,
          resolveCardJobsByOwner(research),
          _listResearchCards,
          (row) => row.getAttribute("data-tech-key") || "",
          (root, key) => root.querySelector(`[data-research-card][data-tech-key="${key}"]`)
        );
      }

      const stApplied = Number(data.server_time || 0);
      if (stApplied) _lastAppliedServerTime = Math.max(_lastAppliedServerTime, stApplied);

      if (
        data.imperial_directives
        && document.getElementById("imperial-directives-page")
        && reason !== "page_hydrate"
      ) {
        _patchImperialDirectivesFromGameStateSummary(data.imperial_directives, reason);
      }

      if (typeof syncLiveOpsFromGameState === "function") {
        syncLiveOpsFromGameState(data, reason);
      }

      commitGameStateCache(data, reason, opts);
      GC.startProgressTicker();
      _maybeRefreshStaleMovementCountdowns();
      if (shouldPatchGameStateModule("shipyard") || shouldPatchGameStateModule("defense")) {
        syncProductionPanelsAfterGameState(data, reason, activePlanetId);
      }
      syncPerfBodyClasses();

      if (typeof GC.scheduleLogisticsRefreshFromState === "function") {
        GC.scheduleLogisticsRefreshFromState();
      }

      if (data.codex && typeof GC.applyCodexFromState === "function") {
        GC.applyCodexFromState(data.codex);
      }

      markGameStateFetchApplied(opts);
      return hasBusyLiveActivity();
    }

  async function forceCanonicalGameStateRefresh(reason, opts) {
    if (!shouldRunGameLoop() || _authLoopAborted) return null;
    const reasonStr = String(reason || "queue_timer_zero");
    const o = opts && typeof opts === "object" ? opts : {};
    if (_queuePanelRefreshInFlight) return _queuePanelRefreshInFlight;
    _queuePanelRefreshInFlight = (async () => {
      try {
        const data = await GC.fetchJSON("/api/game-state?include_panel=1", { cache: "no-store" });
        if (!data || data.ok === false) return null;
        const wantPlanet = Number(o.planetId || 0);
        if (wantPlanet > 0) {
          const gotPlanet = Number(data.active_planet_id || data.build_queue?.planet_id || 0);
          if (gotPlanet > 0 && gotPlanet !== wantPlanet) {
            console.debug("[GC] canonical state refresh stale planet", {
              reason: reasonStr,
              wantPlanet,
              gotPlanet,
            });
            return null;
          }
        }
        syncServerClockFromState(data);
        applyGameStateData(data, reasonStr, {
          forcePanel: true,
          forceResourceBar: Boolean(o.forceResourceBar !== false),
        });
        return data;
      } catch (err) {
        if (err?.name !== "AbortError") {
          console.error("[GC] canonical state refresh failed", reasonStr, err);
        }
        return null;
      } finally {
        _queuePanelRefreshInFlight = null;
      }
    })();
    return _queuePanelRefreshInFlight;
  }
  GC.forceCanonicalGameStateRefresh = forceCanonicalGameStateRefresh;

  function refreshPageAfterQueueEvent(reason) {
    if (!shouldRunGameLoop() || _authLoopAborted) return Promise.resolve(null);
    return forceCanonicalGameStateRefresh(reason || "queue_timer_zero");
  }

  /** Lightweight HUD refresh — works on /admin too (shell chrome stays mounted). */
  async function refreshHudFromGameState(reason) {
    const reasonStr = String(reason || "admin_hud");
    const allowOnAdmin =
      reasonStr === "admin_hud"
      || reasonStr.startsWith("admin_")
      || reasonStr === "leave_admin";
    if (_authLoopAborted) return null;
    if (!shouldPollGameState() && !allowOnAdmin) return null;
    if (!hasLiveStatusRoot()) return null;
    try {
      const res = await fetch("/api/game-state", {
        credentials: "same-origin",
        cache: "no-store",
        headers: { Accept: "application/json" },
      });
      if (!res.ok) {
        if (res.status === 401) handleAuthFailure("admin_hud");
        return null;
      }
      const ct = (res.headers.get("content-type") || "").toLowerCase();
      if (!ct.includes("application/json")) return null;
      const data = await res.json();
      if (!data || data.ok === false) {
        if (isAuthStatusFailure(null, data)) handleAuthFailure("admin_hud");
        return null;
      }
      clearAuthFailureStreak();
      _statusPollErrorLogged = false;
      clearStatusWidgetOffline();
      applyGameStateData(data, reasonStr, { hudOnly: true, forceResourceBar: true });
      return data;
    } catch (err) {
      if (isAuthStatusFailure(err)) {
        handleAuthFailure("admin_hud");
        return null;
      }
      console.warn("[GC] HUD refresh failed", reason, err);
      return null;
    }
  }

  async function refreshGameState(reason) {
    if (!shouldRunGameLoop() || _authLoopAborted) return null;
    if (!shouldPollGameState() && String(reason || "") !== "planet_switch") {
      return null;
    }

    const reasonStr = String(reason || "");
    if (isPageReloadGameStateReason(reasonStr)) {
      return refreshPageAfterQueueEvent(reasonStr);
    }

    const isFinishReason = reasonStr.endsWith("_finished");
    const isChainReason = isFinishReason || reasonStr === "timer_done";
    const hudOnly = isHudOnlyGameStateReason(reasonStr);

    if (GC.refreshInFlight) {
      if (isChainReason || reasonStr === "fleet_countdown_expired") {
        if (!_queuedChainRefreshReason) _queuedChainRefreshReason = reasonStr;
      }
      return GC.refreshInFlight;
    }

    const p = GC.polling;
    p.inFlight = true;
    if (p.abort && !isChainReason && reasonStr !== "poll" && reasonStr !== "pjax_nav") {
      try {
        p.abort.abort();
      } catch (_) {}
    }

    const ctrl = new AbortController();
    p.abort = ctrl;
    const stateGenAtStart = _clientStateGen;
    const fetchSeq = ++_gameStateFetchSeq;
    const fetchTimeoutId = setTimeout(() => {
      try { ctrl.abort(); } catch (_) {}
    }, GAME_STATE_FETCH_TIMEOUT_MS);

    let resolveFlight;
    const flight = new Promise((resolve) => {
      resolveFlight = resolve;
    });
    _activeRefreshFlightResolve = resolveFlight;
    GC.refreshInFlight = flight;

    (async () => {
      try {
        let gameStateUrl = "/api/game-state";
        // GC-PERF-LIVE-001: diet polls send ?since= for unchanged short-circuit.
        if (hudOnly && _lastPollVersion > 0) {
          gameStateUrl = `/api/game-state?since=${encodeURIComponent(String(_lastPollVersion))}`;
        }
        const data = await GC.fetchJSON(gameStateUrl, { cache: "no-store", signal: ctrl.signal });
        if (!data || data.ok === false) {
          if (isAuthStatusFailure(null, data)) handleAuthFailure("game-state-payload");
          resolveFlight(null);
          return null;
        }

        clearAuthFailureStreak();
        p.backoff = 0;
        _statusPollErrorLogged = false;
        clearStatusWidgetOffline();
        syncServerClockFromState(data);

        if (stateGenAtStart !== _clientStateGen) {
          resolveFlight(null);
          return null;
        }

        if (fetchSeq < _gameStateFetchAppliedSeq) {
          resolveFlight(null);
          return null;
        }

        if (data.unchanged === true) {
          rememberPollVersion(data);
          maybeRestoreResourceRatesAfterUnchangedPoll();
          const wantPolling = hasBusyLiveActivity();
          // Cadence is owned by gameStatePollTick (active/idle/hidden). Do not
          // stop+start here — when hidden, lastInterval is always > active and
          // that thrash restarted polls every tick (GC-PERF-POLL-THRASH-001).
          if (reason !== "poll" && shouldPollGameState() && (reason === "page_init" || reason === "tab_visible" || !GC.polling.running)) {
            GC.startPolling(wantPolling);
          }
          resolveFlight(data);
          return data;
        }

        rememberPollVersion(data);
        const anyActive = applyGameStateData(data, reason, { hudOnly, _fetchSeq: fetchSeq });
        const wantPolling = anyActive || hasBusyLiveActivity();
        if (reason !== "poll" && shouldPollGameState() && (reason === "page_init" || reason === "tab_visible" || !GC.polling.running)) {
          GC.startPolling(wantPolling);
        }
        resolveFlight(data);
        return data;
      } catch (err) {
        if (err?.name === "AbortError") {
          resolveFlight(null);
          return null;
        }

        if (isAuthStatusFailure(err)) {
          handleAuthFailure(reason);
          resolveFlight(null);
          return null;
        }

        if (!shouldRunGameLoop()) {
          GC.stopPolling();
          resolveFlight(null);
          return null;
        }

        logStatusPollErrorOnce(reason, err);
        markStatusWidgetOffline();
        p.backoff = Math.min(60000, (p.backoff || 2000) * 1.6);
        if (reason !== "poll" && shouldPollGameState() && !_authLoopAborted && !GC.polling.running) {
          GC.startPolling(hasBusyLiveActivity(), true);
        }
        resolveFlight(null);
        return null;
      } finally {
        clearTimeout(fetchTimeoutId);
        p.inFlight = false;
        p.abort = null;
        if (_activeRefreshFlightResolve === resolveFlight) {
          _activeRefreshFlightResolve = null;
        }
        if (GC.refreshInFlight === flight) {
          GC.refreshInFlight = null;
        }
        const queued = _queuedChainRefreshReason;
        if (queued) {
          _queuedChainRefreshReason = null;
          queueMicrotask(() => {
            if (shouldRunGameLoop() && !_authLoopAborted) refreshGameState(queued);
          });
        }
      }
    })();

    return flight;
  }

  GC.refreshGameState = refreshGameState;
  GC.refreshHudFromGameState = refreshHudFromGameState;
  GC.applyHudFromGameState = function applyHudFromGameState(data, reason) {
    if (!data || data.ok === false) return false;
    const planetId = Number(data.active_planet_id || data.active_planet?.planet_id || 0);
    if (!planetId) return false;
    applyGameStateData(data, reason || "admin_hud", { hudOnly: true, forceResourceBar: true });
    clearStatusWidgetOffline();
    return true;
  };

  // =========================
  // Building category panels (sidebar-driven – survives PJAX)
  // =========================

  function patchPlanetTeaser(teaser) {
    const root = document.getElementById("gc-planet-teaser");
    if (!root || !teaser || !teaser.visible) return;

    const levelEl = root.querySelector("[data-pe-teaser-level]");
    const scoreEl = root.querySelector("[data-pe-teaser-score]");
    const pctEl = root.querySelector("[data-pe-teaser-unlock-pct]");
    if (levelEl && teaser.planet_level != null) levelEl.textContent = String(teaser.planet_level);
    if (scoreEl && teaser.planet_score != null) scoreEl.textContent = String(teaser.planet_score);
    if (pctEl && teaser.progress_to_unlock_pct != null) {
      pctEl.style.width = `${teaser.progress_to_unlock_pct}%`;
    }
    root.className = `gc-planet-teaser gc-panel gc-planet-teaser-${teaser.status || "countdown"}`;
  }

  function patchPlanetRelocationFromState(data) {
    const block = (data && data.planet_relocation) || (data && data.overview && data.overview.status && data.overview.status.planet && data.overview.status.planet.relocation);
    if (!block || typeof block !== "object") return;

    const form = document.getElementById("overview-planet-relocation-form");
    const activeWrap = document.getElementById("overview-planet-relocation-active");
    const cooldownWrap = document.getElementById("overview-planet-relocation-cooldown");
    const currentEl = document.getElementById("overview-planet-relocation-current");
    const targetEl = document.getElementById("overview-planet-relocation-target");
    const timerEl = document.getElementById("overview-planet-relocation-timer");
    const cooldownTimerEl = document.getElementById("overview-planet-relocation-cooldown-timer");
    const startBtn = document.getElementById("overview-planet-relocation-btn");
    if (!form) return;

    const coordsDisplay =
      (data.active_planet && data.active_planet.coordinates_formatted) ||
      (data.overview && data.overview.status && data.overview.status.planet && data.overview.status.planet.coordinates && data.overview.status.planet.coordinates.display) ||
      "";
    if (currentEl) {
      if (coordsDisplay) {
        currentEl.textContent = tf("overview_planet_relocation_current", { coords: coordsDisplay }, "Aktuell: %(coords)s");
        currentEl.hidden = false;
      } else {
        currentEl.hidden = true;
      }
    }

    const coordsEl = document.getElementById("overview-planet-coords");
    if (coordsEl && coordsDisplay && !block.active) {
      _setIfChanged(coordsEl, coordsDisplay);
    }

    const isActive = Boolean(block.active);
    const onCooldown = !isActive && !block.can_start && Number(block.cooldown_remaining_seconds || 0) > 0;

    if (activeWrap) activeWrap.hidden = !isActive;
    if (cooldownWrap) cooldownWrap.hidden = !onCooldown;
    form.hidden = isActive || onCooldown || block.can_start === false;

    if (isActive) {
      if (targetEl) targetEl.textContent = String(block.target || "");
      if (timerEl) {
        const finishAt = Number(block.finish_at || 0);
        const rem = Math.max(0, Number(block.remaining_seconds || 0));
        timerEl.textContent = formatDuration(rem);
        if (finishAt > 0) {
          timerEl.dataset.timerTarget = String(finishAt);
          timerEl.dataset.countdownAt = String(finishAt);
          timerEl.dataset.refreshOnZero = "game-state";
        }
      }
    } else if (onCooldown && cooldownTimerEl) {
      cooldownTimerEl.textContent = formatDuration(Math.max(0, Number(block.cooldown_remaining_seconds || 0)));
    }

    if (startBtn) {
      startBtn.disabled = isActive || onCooldown || block.can_start === false;
    }
  }
  GC.patchPlanetRelocationFromState = patchPlanetRelocationFromState;

  function initOverview() {
    initOverviewCompanions();
    const trigger = document.getElementById("overview-planet-menu-trigger");
    const modal = document.getElementById("gc-planet-manage-root");
    const renameForm = document.getElementById("overview-planet-rename-form");
    const deleteBtn = document.getElementById("overview-planet-delete-btn");
    const deleteHint = document.getElementById("overview-planet-delete-hint");
    if (!trigger || !modal) return;

    const hintEl = modal.querySelector("[data-planet-form-msg]");
    const nameInput = document.getElementById("overview-planet-rename-input");

    function isPlanetManageModalOpen() {
      return modal && !modal.hidden;
    }

    function setPlanetNameDisplay(name) {
      const label = String(name || "").trim();
      const nameEl = document.getElementById("overview-planet-name");
      if (nameEl) nameEl.textContent = label;
      const inputActive =
        nameInput &&
        (isPlanetManageModalOpen() || document.activeElement === nameInput);
      if (nameInput && !inputActive) nameInput.value = label;
      ["research-planet-label"].forEach((id) => {
        const chip = document.getElementById(id);
        if (!chip) return;
        _setIfChanged(chip, label);
      });
    }

    function syncDeleteState() {
      const canDelete = trigger.getAttribute("data-can-delete") === "1";
      if (deleteBtn) {
        deleteBtn.disabled = !canDelete;
        deleteBtn.setAttribute("aria-disabled", canDelete ? "false" : "true");
      }
      if (deleteHint) deleteHint.hidden = canDelete;
    }

    function openPlanetManageModal() {
      const currentName = document.getElementById("overview-planet-name");
      if (nameInput && currentName) nameInput.value = (currentName.textContent || "").trim();
      syncDeleteState();
      if (typeof GC.patchPlanetRelocationFromState === "function" && GC.lastState) {
        GC.patchPlanetRelocationFromState(GC.lastState);
      }
      if (hintEl) {
        hintEl.textContent = "";
        hintEl.hidden = true;
      }
      modal.hidden = false;
      modal.setAttribute("aria-hidden", "false");
      trigger.setAttribute("aria-expanded", "true");
      document.body.classList.add("gc-planet-manage-open");
      const closeBtn = modal.querySelector("[data-planet-close].gc-player-card-close");
      if (nameInput) {
        setTimeout(() => nameInput.focus(), 0);
      } else if (closeBtn) {
        closeBtn.focus({ preventScroll: true });
      }
    }

    function closePlanetManageModal() {
      modal.hidden = true;
      modal.setAttribute("aria-hidden", "true");
      trigger.setAttribute("aria-expanded", "false");
      document.body.classList.remove("gc-planet-manage-open");
      trigger.focus({ preventScroll: true });
    }

    function setHint(text, isError) {
      if (!hintEl) return;
      hintEl.textContent = text || "";
      hintEl.hidden = !text;
      hintEl.classList.toggle("gc-options-hint-error", Boolean(isError));
      hintEl.classList.toggle("is-error", Boolean(isError));
      hintEl.classList.toggle("is-success", Boolean(text) && !isError);
    }

    if (!modal.dataset.bound) {
      modal.dataset.bound = "1";
      modal.querySelectorAll("[data-planet-close]").forEach((el) => {
        el.addEventListener("click", () => closePlanetManageModal());
      });
      document.addEventListener("keydown", (ev) => {
        if (ev.key === "Escape" && !modal.hidden) closePlanetManageModal();
      });
    }

    if (trigger.dataset.overviewPlanetBound) {
      GC.applyOverviewPlanetName = setPlanetNameDisplay;
      return;
    }
    trigger.dataset.overviewPlanetBound = "1";

    trigger.addEventListener("click", (ev) => {
      ev.preventDefault();
      if (modal.hidden) openPlanetManageModal();
      else closePlanetManageModal();
    });

    if (renameForm) {
      renameForm.addEventListener("submit", async (ev) => {
        ev.preventDefault();
        const planetName = String(nameInput && nameInput.value ? nameInput.value : "").trim();
        if (!planetName) return;
        setHint("", false);
        try {
          const data = await GC.fetchGameAction("/api/options/planet-name", {
            method: "POST",
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify({ planet_name: planetName }),
          });
          if (!data.ok) {
            setHint(t(data.error || "options_error_invalid_name", "Speichern fehlgeschlagen."), true);
            return;
          }
          const saved =
            data.data &&
            (data.data.active_planet_name || data.data.planet_name || data.data.homeworld_name);
          if (saved) setPlanetNameDisplay(saved);
          setHint(t("playercard_save_success", "Gespeichert."), false);
          if (typeof GC.refreshGameState === "function") GC.refreshGameState("planet_rename");
          setTimeout(() => closePlanetManageModal(), 450);
        } catch (err) {
          if (err && err.message === "auth") return;
          setHint(t("playercard_save_error", "Speichern fehlgeschlagen."), true);
        }
      });
    }

    if (deleteBtn) {
      deleteBtn.addEventListener("click", async () => {
        if (deleteBtn.disabled) return;
        const confirmMsg = t(
          "overview_planet_delete_confirm",
          "Diese Kolonie unwiderruflich löschen?"
        );
        if (!window.confirm(confirmMsg)) return;
        setHint("", false);
        deleteBtn.disabled = true;
        try {
          const data = await GC.fetchGameAction("/api/planet/delete", {
            method: "POST",
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify({}),
          });
          if (!data.ok) {
            setHint(t(data.error || "planet_error_delete_failed", "Löschen fehlgeschlagen."), true);
            syncDeleteState();
            return;
          }
          closePlanetManageModal();
          if (typeof GC.navigateTo === "function") {
            await GC.navigateTo("/overview", { push: true, force: true });
          } else if (typeof GC.reloadCurrentPage === "function") {
            await GC.reloadCurrentPage({ force: true });
          }
        } catch (err) {
          if (err && err.message === "auth") return;
          setHint(t("planet_error_delete_failed", "Löschen fehlgeschlagen."), true);
          syncDeleteState();
        }
      });
    }

    const relocationForm = document.getElementById("overview-planet-relocation-form");
    if (relocationForm && !relocationForm.dataset.bound) {
      relocationForm.dataset.bound = "1";
      relocationForm.addEventListener("submit", async (ev) => {
        ev.preventDefault();
        const gEl = document.getElementById("overview-planet-relocation-galaxy");
        const sEl = document.getElementById("overview-planet-relocation-system");
        const pEl = document.getElementById("overview-planet-relocation-position");
        const galaxy = parseInt(gEl && gEl.value, 10);
        const system = parseInt(sEl && sEl.value, 10);
        const position = parseInt(pEl && pEl.value, 10);
        if (!galaxy || !system || !position) return;
        setHint("", false);
        const startBtn = document.getElementById("overview-planet-relocation-btn");
        if (startBtn) startBtn.disabled = true;
        try {
          const res = await GC.fetchGameAction("/api/planet/relocation/start", {
            method: "POST",
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify({ galaxy, system, position }),
          });
          if (typeof applyActionState === "function") applyActionState(res, "planet_relocation_start");
          if (!res.ok) {
            setHint(t(res.reason || res.error || "planet_relocation_failed", "Verschieben fehlgeschlagen."), true);
            if (typeof GC.patchPlanetRelocationFromState === "function" && res.state) {
              GC.patchPlanetRelocationFromState(res.state);
            }
            return;
          }
          setHint(t("planet_relocation_started", "Evakuierung gestartet."), false);
          if (typeof GC.patchPlanetRelocationFromState === "function" && res.state) {
            GC.patchPlanetRelocationFromState(res.state);
          }
        } catch (err) {
          if (err && err.message === "auth") return;
          setHint(t("planet_relocation_failed", "Verschieben fehlgeschlagen."), true);
        } finally {
          if (typeof GC.patchPlanetRelocationFromState === "function" && GC.lastState) {
            GC.patchPlanetRelocationFromState(GC.lastState);
          }
        }
      });
    }

    GC.applyOverviewPlanetName = setPlanetNameDisplay;
  }

  function initOverviewCompanions() {
    const layer = document.getElementById("overview-companion-layer");
    const pop = document.getElementById("overview-companion-popover");
    if (!layer || !pop) return;
    if (layer.dataset.companionBound === "1") return;
    layer.dataset.companionBound = "1";

    const popHome = pop.parentElement;
    let activeHotspot = null;

    const clearHotspotActive = () => {
      layer.querySelectorAll(".overview-companion-hotspot.is-popover-open").forEach((el) => {
        el.classList.remove("is-popover-open");
        el.setAttribute("aria-expanded", "false");
      });
      activeHotspot = null;
    };

    const closeCompanionPopover = () => {
      pop.hidden = true;
      pop.innerHTML = "";
      pop.classList.remove("is-open", "gc-popover-layer");
      pop.removeAttribute("data-placement");
      pop.style.left = "";
      pop.style.top = "";
      pop.style.visibility = "";
      pop.style.setProperty("--companion-caret-x", "");
      if (popHome && pop.parentElement !== popHome) {
        popHome.appendChild(pop);
      }
      clearHotspotActive();
    };

    const positionCompanionPopover = (btn) => {
      if (!btn) return;
      pop.classList.add("gc-popover-layer", "is-open");
      if (pop.parentElement !== document.body) {
        document.body.appendChild(pop);
      }
      pop.hidden = false;
      pop.style.visibility = "hidden";
      // Park offscreen while measuring — never leave a 0×0 box at viewport origin.
      pop.style.left = "-9999px";
      pop.style.top = "0px";

      const margin = 10;
      const rect = btn.getBoundingClientRect();
      const popRect = pop.getBoundingClientRect();
      const popW = Math.max(popRect.width, 1);
      const popH = Math.max(popRect.height, 1);

      let left = rect.left + rect.width / 2 - popW / 2;
      left = Math.max(margin, Math.min(left, window.innerWidth - popW - margin));

      let top = rect.top - popH - margin;
      let placement = "above";
      if (top < margin) {
        top = rect.bottom + margin;
        placement = "below";
      }
      // Tall mission popovers: keep in viewport without snapping to 0,0.
      if (top + popH > window.innerHeight - margin) {
        top = Math.max(margin, window.innerHeight - popH - margin);
      }
      // If still covering the hotspot awkwardly and side space exists, nudge beside.
      if (placement === "below" && top < rect.top && popH > window.innerHeight * 0.55) {
        const sideLeft = rect.right + margin;
        const sideRight = rect.left - popW - margin;
        if (sideLeft + popW <= window.innerWidth - margin) {
          left = sideLeft;
          top = Math.max(margin, Math.min(rect.top, window.innerHeight - popH - margin));
          placement = "below";
        } else if (sideRight >= margin) {
          left = sideRight;
          top = Math.max(margin, Math.min(rect.top, window.innerHeight - popH - margin));
          placement = "below";
        }
      }

      const caretX = Math.max(16, Math.min(popW - 16, rect.left + rect.width / 2 - left));
      pop.dataset.placement = placement;
      pop.style.setProperty("--companion-caret-x", `${caretX}px`);
      pop.style.left = `${Math.round(left)}px`;
      pop.style.top = `${Math.round(top)}px`;
      pop.style.visibility = "visible";
    };

    const schedulePositionCompanionPopover = (btn) => {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          if (!btn || pop.hidden || activeHotspot !== btn) return;
          positionCompanionPopover(btn);
        });
      });
    };

    const badgeLabel = (status, owned) => {
      if (status === "away") return t("overview_companion_away", "Mission");
      if (status === "ready") return t("overview_companion_ready", "Bereit");
      if (owned) return t("overview_companion_idle", "Bereit");
      return t("overview_companion_locked", "???");
    };

    const formatMissionHours = (sec) => {
      const h = Math.max(1, Math.round(Number(sec || 0) / 3600));
      return `${h}h`;
    };

    const parseOffers = (btn) => {
      try {
        const raw = btn.getAttribute("data-companion-offers") || "[]";
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      } catch (_e) {
        return [];
      }
    };

    const renderPopover = (btn) => {
      const owned = btn.getAttribute("data-companion-owned") === "1";
      const bossKey = btn.getAttribute("data-companion-boss") || "";
      const name = btn.getAttribute("data-companion-name") || bossKey;
      const status = btn.getAttribute("data-companion-status") || "locked";
      const power = btn.getAttribute("data-companion-power") || "0";
      const endurance = btn.getAttribute("data-companion-endurance") || "0";
      const cunning = btn.getAttribute("data-companion-cunning") || "0";
      const reward = btn.getAttribute("data-companion-reward") || "0";
      const endsAt = Number(btn.getAttribute("data-companion-ends-at") || 0);
      const canStart = btn.getAttribute("data-companion-can-start") === "1";
      const canClaim = btn.getAttribute("data-companion-can-claim") === "1";
      const outcome = btn.getAttribute("data-companion-outcome") || "";
      const offers = parseOffers(btn);

      let actions = "";
      const activeEventId = Number(btn.getAttribute("data-companion-active-event") || 0);
      if (!owned) {
        if (activeEventId > 0) {
          actions = `<button type="button" class="gc-btn gc-btn-primary" data-companion-nav-wb data-companion-event-id="${activeEventId}">${t("overview_companion_goto_wb", "Zum World Boss")}</button>`;
        } else {
          actions = `<p class="hint">${t("overview_companion_locked_hint", "Noch nicht gezähmt — World Boss Phase 3.")}</p>`;
        }
      } else if (canClaim) {
        const fail = outcome === "fail";
        const claimLabel = fail
          ? t("overview_companion_claim_fail", "Mission gescheitert — abschließen")
          : t("overview_companion_claim", "Ark-Token abholen");
        const claimExtra = fail ? "" : ` (+${reward})`;
        actions = `<p class="hint">${fail ? t("overview_companion_fail_hint", "Der Titan kehrt leer zurück.") : t("overview_companion_success_hint", "Mission erfolgreich.")}</p>
          <button type="button" class="gc-btn gc-btn-primary" data-companion-action="claim" data-companion-boss="${bossKey}">${claimLabel}${claimExtra}</button>`;
      } else if (canStart && offers.length) {
        actions = `<p class="overview-companion-mission-lead">${t("overview_companion_pick_mission", "Wähle eine Ark-Mission")}</p>
          <div class="overview-companion-mission-grid">
            ${offers
              .map((offer) => {
                const vk = String(offer.variant_key || "");
                const title = t(offer.title_key || vk, vk);
                const hint = t(offer.hint_key || "", "");
                const risk = t(offer.risk_key || "", "");
                const dur = formatMissionHours(offer.duration_sec);
                const succ = Math.round(Number(offer.success_chance || 0) * 100);
                const tok = Number(offer.reward_tokens || 0);
                return `<button type="button" class="overview-companion-mission-card" data-companion-action="start" data-companion-boss="${bossKey}" data-companion-variant="${vk}">
                  <span class="overview-companion-mission-title">${title}</span>
                  <span class="overview-companion-mission-meta gc-mono">${dur} · ${succ}% · +${tok} Ark</span>
                  <span class="overview-companion-mission-risk">${risk}</span>
                  <span class="overview-companion-mission-hint hint">${hint}</span>
                </button>`;
              })
              .join("")}
          </div>`;
      } else if (canStart) {
        actions = `<button type="button" class="gc-btn gc-btn-primary" data-companion-action="start" data-companion-boss="${bossKey}" data-companion-variant="strike">${t("overview_companion_mission", "Auf Mission schicken")} (+${reward} Ark)</button>`;
      } else if (status === "away" && endsAt > 0) {
        actions = `<p class="hint">${t("overview_companion_mission_eta", "Zurück in")} <span class="gc-mono" data-countdown-at="${endsAt}" data-countdown-format="eta">—</span></p>`;
      }

      clearHotspotActive();
      btn.classList.add("is-popover-open");
      btn.setAttribute("aria-expanded", "true");
      activeHotspot = btn;

      pop.innerHTML = `
        <div class="overview-companion-popover-inner">
          <p class="overview-companion-popover-eyebrow">${t("overview_companion_link", "Titan-Link")}</p>
          <header class="overview-companion-popover-head">
            <h3 id="overview-companion-popover-title">${name}</h3>
            <button type="button" class="gc-btn gc-btn-ghost gc-btn-xs" data-companion-close aria-label="${t("close", "Schließen")}">×</button>
          </header>
          <dl class="overview-companion-stats">
            <div><dt>${t("overview_companion_stat_power", "Power")}</dt><dd class="gc-mono">${power}</dd></div>
            <div><dt>${t("overview_companion_stat_endurance", "Ausdauer")}</dt><dd class="gc-mono">${endurance}</dd></div>
            <div><dt>${t("overview_companion_stat_cunning", "List")}</dt><dd class="gc-mono">${cunning}</dd></div>
          </dl>
          <div class="overview-companion-actions">${actions}</div>
        </div>`;
      positionCompanionPopover(btn);
      schedulePositionCompanionPopover(btn);
      if (typeof GC.refreshCountdowns === "function") GC.refreshCountdowns(pop);
      else if (typeof GC.initCountdowns === "function") GC.initCountdowns(pop);
    };

    const applyCompanionState = (companions) => {
      if (!companions || !Array.isArray(companions.slots)) return;
      companions.slots.forEach((slot) => {
        const btn = layer.querySelector(`[data-companion-boss="${slot.boss_key}"]`);
        if (!btn) return;
        const owned = !!slot.owned;
        const status = slot.status || (owned ? "idle" : "locked");
        const mission = slot.mission || {};
        const keepOpen = btn === activeHotspot;
        btn.className = `overview-companion-hotspot overview-companion-hotspot--${status}${owned ? "" : " is-locked"}`;
        if (keepOpen) btn.classList.add("is-popover-open");
        btn.setAttribute("data-companion-owned", owned ? "1" : "0");
        btn.setAttribute("data-companion-status", status);
        btn.setAttribute("data-companion-power", String((slot.stats && slot.stats.power) || 0));
        btn.setAttribute("data-companion-endurance", String((slot.stats && slot.stats.endurance) || 0));
        btn.setAttribute("data-companion-cunning", String((slot.stats && slot.stats.cunning) || 0));
        btn.setAttribute("data-companion-reward", String(mission.reward_tokens || 0));
        btn.setAttribute("data-companion-ends-at", String(mission.ends_at || 0));
        btn.setAttribute("data-companion-can-start", mission.can_start ? "1" : "0");
        btn.setAttribute("data-companion-can-claim", mission.can_claim ? "1" : "0");
        btn.setAttribute("data-companion-active-event", String(slot.active_event_id || 0));
        btn.setAttribute("data-companion-outcome", String(mission.outcome || ""));
        try {
          btn.setAttribute("data-companion-offers", JSON.stringify(slot.mission_offers || []));
        } catch (_e) {
          btn.setAttribute("data-companion-offers", "[]");
        }
        const badge = btn.querySelector("[data-companion-badge]");
        if (badge) badge.textContent = badgeLabel(status, owned);
      });
    };

    GC.patchOverviewCompanions = applyCompanionState;

    layer.addEventListener("click", (ev) => {
      const btn = ev.target.closest("[data-companion-boss]");
      if (!btn || !layer.contains(btn)) return;
      ev.preventDefault();
      ev.stopPropagation();
      if (activeHotspot === btn && !pop.hidden) {
        closeCompanionPopover();
        return;
      }
      renderPopover(btn);
    });

    const onDocPointerDown = (ev) => {
      if (pop.hidden) return;
      const target = ev.target;
      if (pop.contains(target)) return;
      if (activeHotspot && activeHotspot.contains(target)) return;
      closeCompanionPopover();
    };

    const onReposition = () => {
      if (pop.hidden || !activeHotspot) return;
      schedulePositionCompanionPopover(activeHotspot);
    };

    const onKeyDown = (ev) => {
      if (ev.key === "Escape" && !pop.hidden) {
        closeCompanionPopover();
      }
    };

    document.addEventListener("pointerdown", onDocPointerDown, true);
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);
    document.addEventListener("keydown", onKeyDown);

    pop.addEventListener("click", async (ev) => {
      if (ev.target.closest("[data-companion-close]")) {
        closeCompanionPopover();
        return;
      }
      const navBtn = ev.target.closest("[data-companion-nav-wb]");
      if (navBtn) {
        const eid = Number(navBtn.getAttribute("data-companion-event-id") || 0);
        closeCompanionPopover();
        const path = eid > 0 ? `/world-boss?event_id=${eid}` : "/world-boss";
        if (typeof GC.navigateTo === "function") GC.navigateTo(path);
        return;
      }
      const actionBtn = ev.target.closest("[data-companion-action]");
      if (!actionBtn) return;
      const action = actionBtn.getAttribute("data-companion-action");
      const bossKey = actionBtn.getAttribute("data-companion-boss");
      const variantKey = actionBtn.getAttribute("data-companion-variant") || "strike";
      if (!action || !bossKey) return;
      actionBtn.disabled = true;
      const requestId =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `cmp-${Date.now()}`;
      try {
        const res = await GC.fetchGameAction("/api/world-boss/companion/mission", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            "X-Request-Id": requestId,
          },
          body: JSON.stringify({
            action,
            boss_key: bossKey,
            variant_key: variantKey,
            request_id: requestId,
          }),
        });
        if (res && res.state && typeof GC.applyActionState === "function") {
          GC.applyActionState(res, res.ok ? "companion_mission" : "companion_mission_error");
        }
        if (res && res.ok) {
          const companions = res.state?.overview?.status?.companions;
          if (companions) applyCompanionState(companions);
          if (action === "claim") {
            const failed = res.mission && res.mission.success === false;
            showNotify(
              failed
                ? t("overview_companion_claim_fail_toast", "Mission gescheitert — keine Ark-Token.")
                : t("overview_companion_claim_ok", "Ark-Token erhalten."),
              failed ? "warning" : "success"
            );
          } else {
            showNotify(
              t("overview_companion_mission_ok", "Companion auf Mission geschickt."),
              "success"
            );
          }
          closeCompanionPopover();
        } else {
          showNotify(
            t(String(res?.error || "companion_mission_failed"), "Mission fehlgeschlagen."),
            "error"
          );
          actionBtn.disabled = false;
        }
      } catch (_err) {
        showNotify(t("msg_action_failed", "Aktion fehlgeschlagen."), "error");
        actionBtn.disabled = false;
      }
    });

    if (typeof GC.registerCleanup === "function") {
      GC.registerCleanup(() => {
        document.removeEventListener("pointerdown", onDocPointerDown, true);
        window.removeEventListener("resize", onReposition);
        window.removeEventListener("scroll", onReposition, true);
        document.removeEventListener("keydown", onKeyDown);
        closeCompanionPopover();
        delete layer.dataset.companionBound;
      });
    }
  }

  function parseInventoryPageState() {
    const el = document.getElementById("inventory-page-state");
    if (el && el.textContent) {
      try {
        return JSON.parse(el.textContent);
      } catch (_) {}
    }
    return { ready: false, containers: [], other_items: [] };
  }

  function inventoryResourceLabel(key) {
    if (key === "metal") return t("resource_metal", "Ferronit");
    if (key === "crystal") return t("resource_crystal", "Crytite");
    if (key === "fuel_cells") return t("resource_fuel_cells", "Brennzellen");
    return key;
  }

  function inventoryEffectMessage(effect) {
    if (!effect) return "";
    const params = { ...(effect.message_params || {}) };

    if (effect.kind === "time_boost") {
      const sec = parseInt(
        effect.seconds_shifted ?? params.seconds ?? effect.seconds_reduced,
        10
      ) || 0;
      const minutes = Math.max(1, Math.round(sec / 60));
      const target = String(effect.target || "build");
      const key = effect.message_key || `inv_effect_${target}_boost`;
      const fallbacks = {
        inv_effect_build_boost: "Bauzeit um %(minutes)s Minuten reduziert",
        inv_effect_research_boost: "Forschungszeit um %(minutes)s Minuten reduziert",
        inv_effect_shipyard_boost: "Schiffsbauzeit um %(minutes)s Minuten reduziert",
      };
      return tf(key, { ...params, minutes, seconds: sec }, fallbacks[key] || key);
    }

    if (effect.kind === "resource") {
      const label = inventoryResourceLabel(effect.resource_key || "metal");
      return tf(
        "inv_effect_resource_fmt",
        {
          amount: formatNumber(params.amount || effect.amount || 0),
          resource: label,
        },
        "+%(amount)s %(resource)s erhalten"
      );
    }

    if (effect.kind === "planet_xp") {
      const key = effect.message_key || "inv_effect_planet_xp";
      return tf(
        key,
        { ...params, xp: params.xp ?? effect.xp_gained ?? 0 },
        "Planet erhielt +%(xp)s XP"
      );
    }

    if (effect.kind === "craft") {
      const outName = t(`inv_${params.output_key}`, params.output_key || "");
      const key = effect.message_key || "inv_effect_craft";
      return tf(
        key,
        { ...params, item: outName },
        "%(amount)s× %(item)s hergestellt"
      );
    }

    if (effect.kind === "exchange") {
      const inName = t(`inv_${params.input_key}`, params.input_key || "");
      const outName = t(`inv_${params.output_key}`, params.output_key || "");
      const key = effect.message_key || "inv_effect_exchange";
      return tf(
        key,
        {
          ...params,
          input_name: inName,
          output_name: outName,
        },
        "%(input_amount)s× %(input_name)s zu %(output_amount)s× %(output_name)s verbessert."
      );
    }

    if (effect.message_key) {
      return tf(effect.message_key, params, effect.message_key);
    }
    return "";
  }

  function isInventoryPayload(inv) {
    return Boolean(inv && typeof inv === "object" && Array.isArray(inv.other_items));
  }

  function syncInventoryPageStateScript(inv) {
    const el = document.getElementById("inventory-page-state");
    if (el && inv) {
      try {
        el.textContent = JSON.stringify(inv);
      } catch (_) {}
    }
  }

  function applyInventoryConsumption(base, itemKey, consumed) {
    const inv = {
      ...(base || {}),
      other_items: [...((base && base.other_items) || [])],
    };
    const key = String(itemKey || "");
    const useCount = Math.max(1, parseInt(consumed, 10) || 1);
    if (!key) return inv;
    inv.other_items = inv.other_items
      .map((it) => {
        if (String(it.item_key) !== key) return it;
        const next = (parseInt(it.amount, 10) || 0) - useCount;
        return next > 0 ? { ...it, amount: next } : null;
      })
      .filter(Boolean);
    return inv;
  }

  function resolveInventoryFromAction(res) {
    if (isInventoryPayload(res?.inventory)) return res.inventory;
    const base = _inventoryLastState || parseInventoryPageState();
    if (res?.ok && res.item_key) {
      return applyInventoryConsumption(base, res.item_key, res.consumed);
    }
    return base;
  }

  async function refreshInventoryFromServer() {
    try {
      const res = await GC.fetchGameAction("/api/inventory/state");
      if (res?.ok && isInventoryPayload(res.inventory)) {
        _inventoryLastState = res.inventory;
        syncInventoryPageStateScript(_inventoryLastState);
        patchInventoryDom(_inventoryLastState);
        return true;
      }
    } catch (_) {}
    return false;
  }

  function applyInventoryActionResult(res) {
    _inventoryLastState = resolveInventoryFromAction(res);
    syncInventoryPageStateScript(_inventoryLastState);
    patchInventoryDom(_inventoryLastState);
    if (res?.ok && res.item_key && !isInventoryPayload(res?.inventory)) {
      refreshInventoryFromServer();
    }
  }

  function inventoryUseReasonText(reason) {
    const map = {
      no_build_queue: t("inv_error_no_build_queue", "Keine Bauaufträge in der Warteschlange."),
      no_research_queue: t("inv_error_no_research_queue", "Keine Forschung in der Warteschlange."),
      no_shipyard_queue: t("inv_error_no_shipyard_queue", "Keine Schiffsbauaufträge in der Warteschlange."),
      no_effect_target: t("inv_error_no_effect_target", "Kein gültiges Ziel für dieses Item."),
      no_matching_research: t("inv_error_no_matching_research", "Keine passende aktive Forschung für diesen Datenkern."),
      insufficient_items: t("inv_error_insufficient_items", "Nicht genug Items im Inventar."),
      insufficient_materials: t("inv_error_insufficient_materials", "Nicht genug Material im Inventar."),
      invalid_recipe: t("inv_error_invalid_recipe", "Unbekanntes Rezept."),
      item_not_usable: t("inv_error_item_not_usable", "Dieses Item kann nicht benutzt werden."),
      item_locked_planned: t("inv_hint_locked_planned", "Bald verfügbar"),
      invalid_item: t("inv_error_invalid_item", "Unbekanntes Item."),
      missing_item: t("inv_error_invalid_item", "Unbekanntes Item."),
      inventory_unavailable: t("inv_unavailable", "Inventar ist derzeit nicht verfügbar."),
      inventory_action_failed: t("inv_error_action_failed", "Inventar-Aktion ist fehlgeschlagen."),
    };
    return map[reason] || t("msg_generic_error", "Aktion fehlgeschlagen.");
  }

  const INVENTORY_ACTION_TIMEOUT_MS = 15000;

  async function runInventoryAction(buttons, url, payload, onSuccess) {
    const btnList = (Array.isArray(buttons) ? buttons : [buttons]).filter(Boolean);
    if (!btnList.length) return;

    btnList.forEach((btn) => lockInventoryActionBtn(btn));

    let timeoutId = null;
    const timeoutPromise = new Promise((_, reject) => {
      timeoutId = setTimeout(() => {
        const err = new Error("inventory action timeout");
        err.name = "AbortError";
        reject(err);
      }, INVENTORY_ACTION_TIMEOUT_MS);
    });

    try {
      const json = await Promise.race([
        GC.fetchGameAction(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Requested-With": "XMLHttpRequest",
          },
          body: JSON.stringify(payload),
        }),
        timeoutPromise,
      ]);
      if (!json || json.ok !== true) {
        const reason = json?.reason || "generic";
        const msg =
          json?.message ||
          inventoryUseReasonText(reason);
        console.warn("[GC] inventory action failed:", reason, json);
        showNotify(msg, "error");
        scrollInventoryToFeedback();
        patchInventoryDom(_inventoryLastState || parseInventoryPageState());
        return;
      }
      if (typeof onSuccess === "function") {
        await onSuccess(json);
      }
    } catch (err) {
      if (err?.name === "AbortError") {
        showNotify(t("inv_error_action_timeout", "Inventar-Aktion hat zu lange gedauert."), "error");
      } else if (!err?.gcAuth) {
        console.warn("[GC] inventory action error", err);
        showNotify(t("inv_error_action_failed", "Inventar-Aktion ist fehlgeschlagen."), "error");
      }
      scrollInventoryToFeedback();
      patchInventoryDom(_inventoryLastState || parseInventoryPageState());
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
      btnList.forEach((btn) => releaseInventoryActionBtn(btn));
    }
  }

  function listDepositableLegacyTimeItems(domain) {
    const legacy = (_inventoryLastState || parseInventoryPageState())?.timekeeper?.legacy_time_items || [];
    const dom = String(domain || "");
    const allDomains = dom === "all";
    return legacy.filter((item) => {
      if (!item) return false;
      const itemDom = legacyBoosterDomain(item.item_key);
      if (allDomains) {
        if (itemDom !== "build" && itemDom !== "research" && itemDom !== "shipyard") return false;
      } else if (itemDom !== dom) {
        return false;
      }
      if (item.usable === false) return false;
      return (parseInt(item.amount, 10) || 0) > 0;
    });
  }

  function countDepositableLegacyTimeItems(domain) {
    return listDepositableLegacyTimeItems(domain).reduce(
      (sum, item) => sum + (parseInt(item.amount, 10) || 0),
      0
    );
  }

  async function depositTimekeeperChip(chipBtn, domain) {
    const page = document.getElementById("inventory-page");
    if (!page || page.dataset.ready !== "1") return;
    const dom = String(domain || "").trim();
    if (!dom) return;

    let items = listDepositableLegacyTimeItems(dom);
    if (!items.length) {
      await refreshInventoryFromServer();
      items = listDepositableLegacyTimeItems(dom);
    }
    if (!items.length) {
      showNotify(t("inv_error_item_not_usable", "Dieses Item kann nicht benutzt werden."), "error");
      return;
    }

    const applyDepositSuccess = (res) => {
      applyActionState(res, "inventory_use");
      renderInventoryEffect(res.effect || {}, { preserveScroll: true });
      applyInventoryActionResult(res);
      void refreshInventoryFromServer();
    };

    // Prefer atomic domain deposit (new server). Old processes ignore deposit_domain
    // and answer invalid_item for empty item_key — fall back to per-SKU use.
    lockInventoryActionBtn(chipBtn);
    let timeoutId = null;
    try {
      const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => {
          const err = new Error("inventory action timeout");
          err.name = "AbortError";
          reject(err);
        }, INVENTORY_ACTION_TIMEOUT_MS);
      });
      const atomic = await Promise.race([
        GC.fetchGameAction("/api/inventory/use", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Requested-With": "XMLHttpRequest",
          },
          body: JSON.stringify({
            deposit_domain: dom,
            request_id: `inv-tk-${dom}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          }),
        }),
        timeoutPromise,
      ]);
      if (atomic && atomic.ok === true) {
        applyDepositSuccess(atomic);
        return;
      }
      const reason = atomic?.reason || "generic";
      // Old servers reject unknown deposit_domain ("all") as invalid_domain, or
      // ignore deposit_domain and answer invalid_item / missing_item — fall back.
      if (reason !== "invalid_item" && reason !== "missing_item" && reason !== "invalid_domain") {
        showNotify(atomic?.message || inventoryUseReasonText(reason), "error");
        scrollInventoryToFeedback();
        patchInventoryDom(_inventoryLastState || parseInventoryPageState());
        return;
      }
    } catch (err) {
      if (err?.name === "AbortError") {
        showNotify(t("inv_error_action_timeout", "Inventar-Aktion hat zu lange gedauert."), "error");
        scrollInventoryToFeedback();
        patchInventoryDom(_inventoryLastState || parseInventoryPageState());
        return;
      }
      if (!err?.gcAuth) {
        console.warn("[GC] inventory tk atomic deposit error", err);
      }
      // Fall through to per-SKU deposit.
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
      releaseInventoryActionBtn(chipBtn);
    }

    for (const item of items) {
      let left = parseInt(item.amount, 10) || 0;
      const itemKey = String(item.item_key || "");
      if (!itemKey || left < 1) continue;
      while (left > 0) {
        const chunk = Math.min(100, left);
        let ok = false;
        await runInventoryAction(
          chipBtn,
          "/api/inventory/use",
          {
            item_key: itemKey,
            amount: chunk,
            request_id: `inv-tk-${dom}-${itemKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          },
          (res) => {
            ok = true;
            applyDepositSuccess(res);
          }
        );
        if (!ok) return;
        left -= chunk;
      }
    }
  }

  function scrollInventoryToFeedback(opts) {
    if (opts && opts.preserveScroll) return;
    const panel = document.getElementById("inventory-rewards-panel");
    const page = document.getElementById("inventory-page");
    const scrollTarget = panel && !panel.hidden ? panel : page;
    if (scrollTarget) {
      try {
        scrollTarget.scrollIntoView({ behavior: "smooth", block: "nearest" });
      } catch (_) {
        scrollTarget.scrollIntoView(true);
      }
    }
  }

  function renderInventoryEffect(effect, opts) {
    const preserveScroll = Boolean(opts && opts.preserveScroll);
    if (effect?.kind === "timekeeper_credit") {
      const text = inventoryEffectMessage(effect);
      if (text) showNotify(text, "success");
      return;
    }
    const panel = document.getElementById("inventory-rewards-panel");
    const msgEl = document.querySelector("[data-inventory-effect-message]");
    const list = document.querySelector("[data-inventory-rewards-list]");
    if (!panel) return;
    const text = inventoryEffectMessage(effect);
    const icons = {
      time_boost: effect?.target === "research" ? "📡" : effect?.target === "shipyard" ? "🛰️" : "🔧",
      resource: "📦",
      planet_xp: "🪐",
      craft: "🧬",
      exchange: "🧬",
      production_grant: "⚡",
      research_instant: "📜",
    };
    const icon = icons[effect?.kind] || "✨";
    if (msgEl) {
      if (text) {
        msgEl.className = "inventory-effect-message inventory-effect-message--success";
        msgEl.innerHTML = `<span class="inventory-effect-icon" aria-hidden="true">${icon}</span><span class="inventory-effect-text">${escapeHtml(text)}</span>`;
        msgEl.hidden = false;
      } else {
        msgEl.textContent = "";
        msgEl.hidden = true;
      }
    }
    if (list) list.innerHTML = "";
    if (text) {
      panel.hidden = false;
      scrollInventoryToFeedback({ preserveScroll });
    }
  }

  function releaseInventoryActionBtn(btn) {
    if (!btn) return;
    btn.disabled = false;
    btn.classList.remove("is-loading", "is-busy");
  }

  function lockInventoryActionBtn(btn) {
    if (!btn) return;
    btn.disabled = true;
    btn.classList.add("is-loading", "is-busy");
  }

  function buildInventoryItemRowHtml(item) {
    const rarity = item.rarity || "common";
    const name = t(item.name_key || `inv_item_${item.item_key}`, item.item_key);
    const amount = parseInt(item.amount, 10) || 0;
    const craftProgress = (item.craft_progress || [])
      .map(
        (cp) =>
          `<span class="inventory-craft-progress gc-mono">${formatNumber(amount)} / ${formatNumber(cp.required || 0)} ${escapeHtml(t(cp.name_key, cp.output_key))}</span>`
      )
      .join("");
    const exchangeProgress = (item.exchange_progress || [])
      .map((ep) => {
        const inputName = t(`inv_${ep.input_key}`, ep.input_key);
        const outputName = t(`inv_${ep.output_key}`, ep.output_key);
        return `<span class="inventory-exchange-progress gc-mono">${escapeHtml(
          tf(
            "inv_exchange_upgrade_hint",
            {
              input_amount: ep.required,
              output_amount: ep.output_amount || 1,
              input_name: inputName,
              output_name: outputName,
            },
            "Upgrade möglich: %(input_amount)s %(input_name)s → %(output_amount)s %(output_name)s"
          )
        )}</span>`;
      })
      .join("");
    let prestigeProgress = "";
    if (item.prestige_progress) {
      const pp = item.prestige_progress;
      const badgeName = t(pp.badge_name_key || `playercard_badge_${pp.badge_key}`, pp.badge_key || "");
      if (pp.unlocked) {
        prestigeProgress = `<span class="inventory-prestige-progress gc-mono">${escapeHtml(
          tf("inv_prestige_progress_done", { badge: badgeName }, "%(badge)s freigeschaltet")
        )}</span>`;
      } else {
        const rewardHint = pp.reward_key
          ? `<span class="inventory-prestige-reward-hint">${escapeHtml(
              tf(
                "inv_prestige_reward_hint",
                {
                  amount: pp.reward_amount || 0,
                  reward: t(`inv_${pp.reward_key}`, pp.reward_key),
                },
                "Belohnung: %(amount)s× %(reward)s"
              )
            )}</span>`
          : "";
        prestigeProgress = `<span class="inventory-prestige-progress gc-mono">${escapeHtml(
          tf(
            "inv_prestige_progress",
            {
              owned: formatNumber(pp.owned || 0),
              required: formatNumber(pp.required || 0),
              badge: badgeName,
            },
            "%(owned)s / %(required)s → %(badge)s"
          )
        )}${rewardHint}</span>`;
      }
    }
    const endgameHint = item.exchange_endgame
      ? `<span class="inventory-endgame-hint">${escapeHtml(t("inv_dna_core_epic_hint", "Endgame-Material — später nutzbar"))}</span>`
      : "";
    let roleHint = "";
    if (item.locked_planned) {
      roleHint = `<span class="inventory-locked-hint">${escapeHtml(t("inv_hint_locked_planned", "Bald verfügbar"))}</span>`;
    } else if (item.prestige_progress) {
      roleHint = "";
    } else if (item.use_hint_key && !item.usable) {
      roleHint = `<span class="inventory-use-hint">${escapeHtml(t(item.use_hint_key, item.use_hint_key))}</span>`;
    } else if (item.trade_material && !item.usable) {
      roleHint = `<span class="inventory-trade-hint">${escapeHtml(t("inv_hint_collector_trade", "Im Sammler-Markt tauschbar"))}</span>`;
    }
    const collectibleBadge = item.collectible
      ? `<span class="inventory-collectible-badge">${escapeHtml(t("inv_collectible_badge", "Sammlerstück"))}</span>`
      : "";
    const useBtn = item.usable
      ? `<button type="button" class="gc-btn gc-btn-primary gc-btn-xs inventory-use-btn" data-inventory-use="${escapeHtml(item.item_key)}">${escapeHtml(t("inv_use_btn", "Benutzen"))}</button>`
      : "";
    const craftBtns = (item.craft_progress || [])
      .filter((cp) => cp.can_craft)
      .map(
        (cp) =>
          `<button type="button" class="gc-btn gc-btn-secondary gc-btn-xs inventory-craft-btn" data-inventory-craft="${escapeHtml(cp.recipe_key)}">${escapeHtml(t("inv_craft_btn", "Craften"))}</button>`
      )
      .join("");
    const exchangeBtns = (item.exchange_progress || [])
      .filter((ep) => ep.can_exchange)
      .map(
        (ep) =>
          `<button type="button" class="gc-btn gc-btn-secondary gc-btn-xs inventory-exchange-btn" data-inventory-exchange="${escapeHtml(ep.recipe_key)}">${escapeHtml(t("inv_upgrade_btn", "Upgrade"))}</button>`
      )
      .join("");
    const iconHtml = item.image
      ? `<span class="inventory-item-icon" aria-hidden="true"><img class="inventory-item-img" src="/static/${escapeHtml(String(item.image).replace(/^\/+/, ""))}" alt="" width="28" height="28" loading="lazy"></span>`
      : `<span class="inventory-item-icon" aria-hidden="true">${item.icon || "📦"}</span>`;
    return `${iconHtml}<div class="inventory-item-body"><span class="inventory-item-name">${escapeHtml(name)}</span>${craftProgress}${exchangeProgress}${prestigeProgress}${endgameHint}${roleHint}</div><span class="inventory-rarity-badge inventory-rarity-badge--${escapeHtml(rarity)}">${escapeHtml(t(`inv_rarity_${rarity}`, rarity))}</span>${collectibleBadge}<span class="inventory-item-amount gc-mono" data-inventory-item-amount="${escapeHtml(item.item_key)}">×${formatNumber(amount)}</span>${useBtn}${craftBtns}${exchangeBtns}`;
  }

  function patchInventoryActiveBoosters(inventory) {
    const panel = document.querySelector("[data-inventory-active-boosters]");
    const list = document.querySelector("[data-inventory-active-boosters-list]");
    if (!panel || !list) return;
    const effects = (inventory && inventory.active_boosters && inventory.active_boosters.active_effects) || [];
    if (!effects.length) {
      panel.hidden = true;
      list.innerHTML = "";
      return;
    }
    panel.hidden = false;
    list.innerHTML = effects
      .filter((effect) => !effect.hud_chip_only && !effect.stack_aggregate)
      .map((effect) => {
        const rem = Math.max(0, Math.floor(Number(effect.remaining_seconds) || 0));
        const domainKey = `inv_boost_domain_${effect.affected_domain || "general"}`;
        const domain = t(domainKey, effect.affected_domain || "general");
        const note = effect.note
          ? `<span class="inventory-active-booster-note">${escapeHtml(effect.note)}</span>`
          : "";
        return `<li class="inventory-active-booster-row" data-boost-key="${escapeHtml(effect.key || "")}" data-remaining-seconds="${rem}"><span class="inventory-active-booster-label">${escapeHtml(effect.label || "")}</span><span class="inventory-active-booster-effect">${escapeHtml(effect.effect_summary || "")}</span><span class="inventory-active-booster-domain">${escapeHtml(domain)}</span><span class="inventory-active-booster-time gc-mono" data-boost-remaining>${escapeHtml(formatDuration(rem))}</span>${note}</li>`;
      })
      .join("");
    if (!list.innerHTML) {
      panel.hidden = true;
      return;
    }
  }

  let _lootModalState = null;

  const GC_NOTIFY_SOUNDS = {
    attack: "/static/sounds/notify/notify.mp3",
    message: "/static/sounds/notify/message.mp3",
  };

  let _notifyAudioUnlocked = false;
  let _notifyAudio = {};
  let _notifySoundInitDone = false;

  function initNotificationSounds() {
    if (_notifySoundInitDone) return;
    _notifySoundInitDone = true;

    Object.entries(GC_NOTIFY_SOUNDS).forEach(([key, src]) => {
      const audio = new Audio(src);
      audio.preload = "auto";
      audio.volume = GC_NOTIFY_SOUND_BASE_VOLUME;
      _notifyAudio[key] = audio;
    });

    const unlock = () => {
      if (_notifyAudioUnlocked) return;
      _notifyAudioUnlocked = true;

      Object.values(_notifyAudio).forEach((audio) => {
        try {
          audio.muted = true;
          const promise = audio.play();
          if (promise && typeof promise.then === "function") {
            promise
              .then(() => {
                audio.pause();
                audio.currentTime = 0;
                audio.muted = false;
              })
              .catch(() => {
                audio.muted = false;
              });
          } else {
            audio.pause();
            audio.currentTime = 0;
            audio.muted = false;
          }
        } catch (_) {
          audio.muted = false;
        }
      });
    };

    ["click", "keydown", "touchstart", "pointerdown"].forEach((eventName) => {
      document.addEventListener(eventName, unlock, { once: true, passive: true });
    });
  }
  GC.initNotificationSounds = initNotificationSounds;

  function playNotificationSound(kind) {
    const volume = notifySoundVolumeForKind(kind);
    if (volume <= 0) return;
    initNotificationSounds();

    const audio = _notifyAudio[kind];
    if (!audio) return;

    try {
      audio.pause();
      audio.currentTime = 0;
      audio.muted = false;
      audio.volume = volume;

      const promise = audio.play();
      if (promise && typeof promise.catch === "function") {
        promise.catch((err) => {
          console.debug("[GC] notification sound blocked", kind, err);
        });
      }
    } catch (err) {
      console.debug("[GC] notification sound failed", kind, err);
    }
  }
  GC.playNotificationSound = playNotificationSound;

  function playLootboxOpenSound() {
    try {
      const audio = new Audio("/static/sounds/lootboxes/lootbox_sound.mp3");
      audio.volume = 0.2;
      audio.play().catch(() => {});
    } catch (_) {}
  }

  function playIncomingAttackNotifySound() {
    playNotificationSound("attack");
  }

  function playNewMessageNotifySound() {
    playNotificationSound("message");
  }

  function lootTileAmountLabel(tile) {
    const amt = parseInt(tile.amount, 10) || 0;
    const type = String(tile.type || "");
    if (type === "resource") return `+${formatNumber(amt)}`;
    if (type === "booster" && String(tile.key || "").includes("booster")) {
      const sec = parseInt(tile.booster_seconds, 10) || 0;
      if (sec >= 3600) return `${Math.round(sec / 3600)} h`;
      if (sec >= 60) return `${Math.round(sec / 60)} Min`;
    }
    return `×${formatNumber(amt)}`;
  }

  function lootTileName(tile) {
    if (tile.name_key) return t(tile.name_key, tile.label || tile.key || "");
    if (tile.label) return tile.label;
    if (tile.type === "resource") return inventoryResourceLabel(tile.key?.split(":")[1] || tile.key);
    return tile.key || "";
  }

  function buildLootRollTileHtml(tile, index) {
    const rarity = tile.rarity || "common";
    const name = lootTileName(tile);
    const amount = lootTileAmountLabel(tile);
    const icon = tile.icon || "📦";
    const rarityLabel = t(`inv_rarity_${rarity}`, rarity);
    return `<div class="gc-loot-tile rarity-${escapeHtml(rarity)}" data-loot-tile-index="${index}" data-rarity="${escapeHtml(rarity)}">
      <span class="gc-loot-tile-icon" aria-hidden="true">${icon}</span>
      <span class="gc-loot-tile-name">${escapeHtml(name)}</span>
      <span class="gc-loot-tile-amount gc-mono">${escapeHtml(amount)}</span>
      <span class="gc-loot-tile-rarity">${escapeHtml(rarityLabel)}</span>
    </div>`;
  }

  function buildLootRollTiles(payload) {
    const tiles = payload.roll_preview || [];
    return tiles.map((tile, i) => buildLootRollTileHtml(tile, i)).join("");
  }

  function buildLootRewardResultHtml(reward, primary) {
    const amt = parseInt(reward.amount, 10) || 0;
    const rarity = reward.rarity || "common";
    const primaryClass = primary ? " gc-loot-result-row--primary" : "";
    if (reward.reward_type === "resource") {
      const label = inventoryResourceLabel(reward.reward_key);
      return `<div class="gc-loot-result-row rarity-${escapeHtml(rarity)}${primaryClass}">
        <span class="gc-loot-result-icon" aria-hidden="true">${reward.icon || "📦"}</span>
        <div class="gc-loot-result-body">
          <span class="gc-loot-result-name">${escapeHtml(label)}</span>
          <span class="gc-loot-result-amount gc-mono">+${formatNumber(amt)}</span>
        </div>
        <span class="gc-loot-result-rarity">${escapeHtml(t(`inv_rarity_${rarity}`, rarity))}</span>
      </div>`;
    }
    const name = t(reward.name_key || `inv_item_${reward.reward_key}`, reward.reward_key);
    const icon = reward.icon || (reward.reward_type === "ship" ? "🛰️" : reward.reward_type === "defense" ? "🛡️" : "📦");
    return `<div class="gc-loot-result-row rarity-${escapeHtml(rarity)}${primaryClass}">
      <span class="gc-loot-result-icon" aria-hidden="true">${icon}</span>
      <div class="gc-loot-result-body">
        <span class="gc-loot-result-name">${escapeHtml(name)}</span>
        <span class="gc-loot-result-amount gc-mono">×${formatNumber(amt)}</span>
      </div>
      <span class="gc-loot-result-rarity">${escapeHtml(t(`inv_rarity_${rarity}`, rarity))}</span>
    </div>`;
  }

  function lootPrimaryRewardKey(payload) {
    const wr = payload.winning_reward || {};
    if (wr.preview_key) return String(wr.preview_key);
    if (wr.key && wr.type) return `${wr.type}:${wr.key}`;
    if (wr.key) return String(wr.key);
    const rewards = payload.rewards || [];
    if (!rewards.length) return "";
    const r = rewards[0];
    return `${r.reward_type}:${r.reward_key}`;
  }

  function canOpenContainerAgain(payload) {
    const key = payload.container_key || payload.item_key;
    const inv = payload.inventory || payload._deferredInventory || {};
    const row = (inv.containers || []).find((c) => c.item_key === key);
    if (!row) return false;
    if (key === "container_basic") {
      return (parseInt(row.amount, 10) || 0) > 0 || Boolean(row.free_open_available);
    }
    return (parseInt(row.amount, 10) || 0) > 0;
  }

  function closeLootModal() {
    if (_lootModalState?.timerId) {
      clearTimeout(_lootModalState.timerId);
    }
    if (_lootModalState?.onKeydown) {
      document.removeEventListener("keydown", _lootModalState.onKeydown);
    }
    const modal = document.querySelector(".gc-loot-modal");
    if (modal) modal.remove();
    document.body.classList.remove("gc-loot-modal-open");
    _lootModalState = null;
  }

  function revealLootRewards(modal, payload) {
    if (!modal || !payload) return;
    if (_lootModalState?.revealed) return;
    if (_lootModalState) _lootModalState.revealed = true;
    if (_lootModalState?.timerId) {
      clearTimeout(_lootModalState.timerId);
      _lootModalState.timerId = null;
    }

    const strip = modal.querySelector(".gc-loot-strip");
    if (strip) strip.classList.add("gc-loot-strip--done");

    const status = modal.querySelector(".gc-loot-status");
    const results = modal.querySelector(".gc-loot-results");
    const skipBtn = modal.querySelector(".gc-loot-skip");
    const closeBtn = modal.querySelector(".gc-loot-close");
    if (status) status.hidden = true;
    if (skipBtn) skipBtn.hidden = true;
    if (closeBtn) closeBtn.disabled = false;

    if (results) {
      const rewards = payload.rewards || [];
      const primaryKey = lootPrimaryRewardKey(payload);
      const card = modal.querySelector(".gc-loot-card");
      if (card && payload.winning_reward?.rarity) {
        card.classList.add(`gc-loot-card--win-${payload.winning_reward.rarity}`);
      }
      results.innerHTML = `
        <div class="gc-loot-results-panel">
          <div class="gc-loot-results-title">${escapeHtml(t("inv_loot_modal_your_reward", "Deine Belohnung"))}</div>
          <div class="gc-loot-results-grid">${rewards
            .map((r) => {
              const rk = `${r.reward_type}:${r.reward_key}`;
              return buildLootRewardResultHtml(r, rk === primaryKey);
            })
            .join("")}</div>
          <div class="gc-loot-results-actions">
            <button type="button" class="gc-btn gc-btn-primary gc-loot-to-inventory">${escapeHtml(t("inv_loot_modal_to_inventory", "Zum Inventar"))}</button>
            ${canOpenContainerAgain(payload) ? `<button type="button" class="gc-btn gc-btn-secondary gc-loot-open-again">${escapeHtml(t("inv_loot_modal_open_again", "Noch einmal öffnen"))}</button>` : ""}
            <button type="button" class="gc-btn gc-btn-ghost gc-loot-close-action">${escapeHtml(t("inv_loot_modal_close", "Schließen"))}</button>
          </div>
        </div>`;
      results.hidden = false;
    }

    if (payload._deferredState) {
      applyActionState({ ok: true, state: payload._deferredState }, "inventory_open");
    }
    applyInventoryActionResult({
      ok: true,
      inventory: payload.inventory || payload._deferredInventory,
      item_key: payload.item_key || payload.container_key,
      consumed: payload.consumed || payload.opened || 1,
    });
    void refreshInventoryFromServer();

    const page = document.getElementById("inventory-page");
    if (page) {
      page.querySelectorAll("[data-inventory-open]").forEach((btn) => {
        btn.disabled = false;
      });
      patchInventoryDom(_inventoryLastState || parseInventoryPageState());
    }
  }

  function computeLootRollTarget(strip, roller, winningIndex) {
    const tiles = strip.querySelectorAll(".gc-loot-tile");
    const tile = tiles[winningIndex];
    if (!tile || !roller) return 0;
    const tileCenter = tile.offsetLeft + tile.offsetWidth / 2;
    const rollerCenter = roller.clientWidth / 2;
    return rollerCenter - tileCenter;
  }

  function animateLootRoll(modal, payload) {
    const strip = modal.querySelector(".gc-loot-strip");
    const roller = modal.querySelector(".gc-loot-roller");
    if (!strip || !roller) {
      revealLootRewards(modal, payload);
      return;
    }

    playLootboxOpenSound();

    const winningIndex = Math.max(
      0,
      Math.min(
        parseInt(payload.winning_index, 10) || 0,
        (payload.roll_preview || []).length - 1
      )
    );

    const runAnimation = () => {
      const targetX = computeLootRollTarget(strip, roller, winningIndex);

      const finish = () => {
        strip.style.transition = "none";
        strip.style.transform = `translate3d(${targetX}px, 0, 0)`;
        strip.querySelectorAll(".gc-loot-tile.is-winning").forEach((el) => el.classList.remove("is-winning"));
        strip.querySelector(`.gc-loot-tile[data-loot-tile-index="${winningIndex}"]`)?.classList.add("is-winning");
        revealLootRewards(modal, payload);
      };

      if (_prefersReducedMotion) {
        finish();
        return;
      }

      strip.style.transform = "translate3d(0, 0, 0)";
      strip.style.transition = "transform 2.4s cubic-bezier(0.12, 0.85, 0.18, 1)";
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          strip.style.transform = `translate3d(${targetX}px, 0, 0)`;
        });
      });

      if (_lootModalState) {
        _lootModalState.timerId = window.setTimeout(finish, 2400);
        _lootModalState.skip = finish;
      }
    };

    requestAnimationFrame(() => {
      requestAnimationFrame(runAnimation);
    });
  }

  function lootContainerImageUrl(payload) {
    const fallback = "/static/img/lootboxes/Generic_Supply_Container.webp";
    const raw = String(payload.container_image || "").trim();
    if (!raw) return fallback;
    if (raw.startsWith("http://") || raw.startsWith("https://") || raw.startsWith("/")) return raw;
    const rel = raw.replace(/^static\//, "");
    return `/static/${rel}`;
  }

  function showLootOpeningModal(payload) {
    closeLootModal();
    const containerKey = payload.container_key || payload.item_key || "container_basic";
    const containerName = t(
      payload.container_name_key || `inv_${containerKey}`,
      containerKey
    );
    const containerRarity = payload.container_rarity || "common";
    const crateImg = lootContainerImageUrl(payload);
    const root = document.getElementById("gc-loot-modal-root") || document.body;

    const modal = document.createElement("div");
    modal.className = "gc-loot-modal";
    modal.setAttribute("role", "dialog");
    modal.setAttribute("aria-modal", "true");
    modal.setAttribute("aria-label", t("inv_loot_modal_title", "Container geöffnet"));
    modal.innerHTML = `
      <div class="gc-loot-card gc-loot-card--hud rarity-${escapeHtml(containerRarity)}">
        <div class="gc-loot-card-corners" aria-hidden="true"></div>
        <div class="gc-loot-card-scanlines" aria-hidden="true"></div>
        <button type="button" class="gc-loot-close gc-btn gc-btn-ghost gc-btn-xs" aria-label="${escapeHtml(t("inv_loot_modal_close", "Schließen"))}" disabled>×</button>
        <div class="gc-loot-header">
          <div class="gc-loot-title gc-mono">${escapeHtml(t("inv_loot_modal_title", "Container geöffnet"))}</div>
          <div class="gc-loot-subtitle gc-mono rarity-${escapeHtml(containerRarity)}">${escapeHtml(containerName)}</div>
        </div>
        <div class="gc-loot-crate rarity-${escapeHtml(containerRarity)}">
          <div class="gc-loot-crate-glow inventory-loot-card-glow inventory-loot-card-glow--${escapeHtml(containerRarity)}" aria-hidden="true"></div>
          <img class="gc-loot-crate-img"
               src="${escapeHtml(crateImg)}"
               alt="${escapeHtml(containerName)}"
               decoding="async"
               onerror="this.onerror=null;this.src='/static/img/lootboxes/Generic_Supply_Container.webp';">
        </div>
        <div class="gc-loot-roller">
          <div class="gc-loot-roller-rail" aria-hidden="true"></div>
          <div class="gc-loot-marker" aria-hidden="true"></div>
          <div class="gc-loot-strip">${buildLootRollTiles(payload)}</div>
        </div>
        <div class="gc-loot-status gc-mono">${escapeHtml(t("inv_loot_modal_status", "Wird geöffnet…"))}</div>
        <div class="gc-loot-results" hidden></div>
        <button type="button" class="gc-btn gc-btn-secondary gc-loot-skip">${escapeHtml(t("inv_loot_modal_skip", "Überspringen"))}</button>
      </div>`;

    root.appendChild(modal);
    document.body.classList.add("gc-loot-modal-open");

    const onKeydown = (ev) => {
      if (ev.key !== "Escape") return;
      if (_lootModalState?.revealed) {
        closeLootModal();
      } else if (typeof _lootModalState?.skip === "function") {
        _lootModalState.skip();
      }
    };
    document.addEventListener("keydown", onKeydown);

    _lootModalState = {
      payload,
      revealed: false,
      timerId: null,
      skip: null,
      onKeydown,
    };

    modal.addEventListener("click", (ev) => {
      const skipBtn = ev.target.closest(".gc-loot-skip");
      if (skipBtn && !skipBtn.hidden && typeof _lootModalState?.skip === "function") {
        _lootModalState.skip();
        return;
      }
      const closeBtn = ev.target.closest(".gc-loot-close");
      if (closeBtn && !closeBtn.disabled) {
        closeLootModal();
        return;
      }
      const toInv = ev.target.closest(".gc-loot-to-inventory");
      if (toInv) {
        closeLootModal();
        return;
      }
      const closeAction = ev.target.closest(".gc-loot-close-action");
      if (closeAction) {
        closeLootModal();
        return;
      }
      const openAgain = ev.target.closest(".gc-loot-open-again");
      if (openAgain) {
        const openPayload = { ..._lootModalState.payload };
        const itemKey = openPayload.container_key || openPayload.item_key;
        closeLootModal();
        const btn = document.querySelector(`[data-inventory-open="${CSS.escape(itemKey)}"][data-open-amount="1"]`)
          || document.querySelector(`[data-inventory-open="${CSS.escape(itemKey)}"]`);
        if (btn && !btn.disabled) btn.click();
      }
    });

    requestAnimationFrame(() => animateLootRoll(modal, payload));
  }

  GC.showLootOpeningModal = showLootOpeningModal;
  GC.revealLootRewards = revealLootRewards;
  GC.closeLootModal = closeLootModal;
  GC.playLootboxOpenSound = playLootboxOpenSound;

  function renderInventoryRewards(rewards) {
    const panel = document.getElementById("inventory-rewards-panel");
    const list = document.querySelector("[data-inventory-rewards-list]");
    if (!panel || !list) return;
    const rows = (rewards || []).filter((r) => (parseInt(r.amount, 10) || 0) > 0);
    if (!rows.length) {
      panel.hidden = true;
      list.innerHTML = "";
      return;
    }
    list.innerHTML = rows
      .map((r) => {
        const amt = parseInt(r.amount, 10) || 0;
        if (r.reward_type === "resource") {
          const label = inventoryResourceLabel(r.reward_key);
          return `<li class="inventory-reward-row inventory-reward-row--resource"><span class="inventory-reward-label">${escapeHtml(label)}</span><span class="inventory-reward-amount gc-mono">+${formatNumber(amt)}</span></li>`;
        }
        if (r.reward_type === "ship" || r.reward_type === "defense") {
          const name = t(r.name_key || `${r.reward_type}_${r.reward_key}`, r.reward_key);
          const icon = r.reward_type === "ship" ? "🛰️" : "🛡️";
          return `<li class="inventory-reward-row inventory-reward-row--${escapeHtml(r.reward_type)}"><span class="inventory-reward-icon" aria-hidden="true">${icon}</span><span class="inventory-reward-label">${escapeHtml(name)}</span><span class="inventory-reward-amount gc-mono">+${formatNumber(amt)}</span></li>`;
        }
        const name = t(r.name_key || `inv_item_${r.reward_key}`, r.reward_key);
        const rarity = t(`inv_rarity_${r.rarity || "common"}`, r.rarity || "common");
        const icon = r.icon || "📦";
        return `<li class="inventory-reward-row inventory-reward-row--item" data-rarity="${escapeHtml(r.rarity || "common")}"><span class="inventory-reward-icon" aria-hidden="true">${icon}</span><span class="inventory-reward-label">${escapeHtml(name)}</span><span class="inventory-rarity-badge inventory-rarity-badge--${escapeHtml(r.rarity || "common")}">${escapeHtml(rarity)}</span><span class="inventory-reward-amount gc-mono">×${formatNumber(amt)}</span></li>`;
      })
      .join("");
    panel.hidden = false;
  }

  function legacyBoosterDomain(itemKey) {
    const key = String(itemKey || "");
    if (key.startsWith("booster_build")) return "build";
    if (key.startsWith("booster_research")) return "research";
    if (key.startsWith("booster_shipyard")) return "shipyard";
    return "other";
  }

  function patchInventoryTimekeeperChips(tk) {
    const chipHost = document.querySelector("[data-inventory-timekeeper-chips]");
    const legacyHost = document.querySelector("[data-inventory-timekeeper-legacy]");
    const legacy = (tk && tk.legacy_time_items) || [];
    const counts = { build: 0, research: 0, shipyard: 0 };
    legacy.forEach((item) => {
      const dom = legacyBoosterDomain(item.item_key);
      if (counts[dom] != null) counts[dom] += parseInt(item.amount, 10) || 0;
    });
    if (chipHost) {
      const total = (counts.build || 0) + (counts.research || 0) + (counts.shipyard || 0);
      const chips = [];
      if (total > 0) {
        chips.push(["all", "inv_tk_chip_all", "Alle", "inv_tk_chip_all_hint", "Alle Zeit-Booster einzahlen", total]);
      }
      [
        ["build", "inv_tk_chip_build", "Bau", "inv_tk_chip_build_hint", "Alle Bau-Booster einzahlen"],
        ["research", "inv_tk_chip_research", "Forschung", "inv_tk_chip_research_hint", "Alle Forschungs-Booster einzahlen"],
        ["shipyard", "inv_tk_chip_shipyard", "Werft", "inv_tk_chip_shipyard_hint", "Alle Werft-Booster einzahlen"],
      ].forEach(([dom, key, fallback, hintKey, hintFb]) => {
        if ((counts[dom] || 0) > 0) chips.push([dom, key, fallback, hintKey, hintFb, counts[dom]]);
      });
      chipHost.innerHTML = chips
        .map(
          ([dom, key, fallback, hintKey, hintFb, amt]) =>
            `<button type="button" class="inventory-tk-chip inventory-tk-chip--${dom} gc-mono" data-inventory-tk-chip-domain="${dom}" title="${escapeHtml(t(hintKey, hintFb))}">${escapeHtml(t(key, fallback))} +${formatNumber(amt)}</button>`
        )
        .join("");
    }
    if (legacyHost) {
      legacyHost.innerHTML = legacy
        .map((item) => {
          const dom = legacyBoosterDomain(item.item_key);
          const usable = Boolean(item.usable);
          const name = t(item.name_key || item.item_key, item.item_key);
          const icon = item.icon || "⚡";
          const amt = parseInt(item.amount, 10) || 0;
          return `<button type="button" class="inventory-tk-deposit-btn" data-inventory-use="${escapeHtml(item.item_key)}" data-inventory-tk-domain="${dom}"${usable ? "" : " disabled"} title="${escapeHtml(name)}"><span class="inventory-tk-deposit-btn__icon" aria-hidden="true">${icon}</span><span class="inventory-tk-deposit-btn__label">${escapeHtml(name)}</span><span class="inventory-tk-deposit-btn__amt gc-mono">×${formatNumber(amt)}</span></button>`;
        })
        .join("");
      legacyHost.hidden = legacy.length === 0;
    }
  }

  function patchInventoryDom(inventory) {
    const inv = inventory || {};
    const tk = inv.timekeeper || {};
    document.querySelectorAll("[data-inventory-timekeeper-balance]").forEach((el) => {
      _setIfChanged(el, String(tk.label || formatDuration(parseInt(tk.balance_sec, 10) || 0)));
    });
    patchInventoryTimekeeperChips(tk);
    const containers = inv.containers || [];
    const items = inv.other_items || [];

    document.querySelectorAll("[data-inventory-container]").forEach((card) => {
      const key = card.dataset.inventoryContainer;
      const row = containers.find((c) => c.item_key === key);
      const amount = row ? parseInt(row.amount, 10) || 0 : 0;
      const owned = amount > 0;
      const isBasic = key === "container_basic";
      const freeOpenReady = Boolean(isBasic && row && row.free_open_available);
      const amountEl = card.querySelector(`[data-inventory-amount="${key}"]`);
      if (amountEl) amountEl.textContent = String(amount);
      card.classList.toggle("inventory-loot-card--owned", owned);
      card.classList.toggle("inventory-loot-card--free-ready", freeOpenReady);
      card.classList.toggle("inventory-loot-card--empty", !owned && !freeOpenReady);
      card.hidden = false;
      const cooldownSeconds = row ? parseInt(row.cooldown_seconds, 10) || 0 : 0;
      const openBlocked = Boolean(row && row.open_blocked);
      const maxOpen = row ? parseInt(row.max_open_amount, 10) || 500 : 500;
      const hint = card.querySelector(".inventory-loot-card-status, .inventory-loot-card-hint");
      if (hint) {
        hint.dataset.cooldownSeconds = String(cooldownSeconds);
        if (owned) {
          hint.textContent = t("inv_card_owned_hint", "Bereit zum Öffnen");
        } else if (freeOpenReady) {
          hint.textContent = t("inv_basic_free_ready", "Gratis-Öffnung verfügbar");
        } else if (openBlocked && cooldownSeconds > 0) {
          hint.textContent = t("inv_basic_cooldown_active", "Cooldown aktiv — 1× alle 24 Stunden");
        } else {
          hint.textContent = t("inv_card_empty_hint", "Noch nicht im Besitz");
        }
      }
      const cooldownEl = card.querySelector("[data-inventory-cooldown]");
      if (cooldownEl) {
        cooldownEl.dataset.cooldownSeconds = String(cooldownSeconds);
        cooldownEl.hidden = false;
        cooldownEl.textContent = cooldownSeconds > 0
          ? `${t("inv_basic_cooldown_timer", "Gratis-Öffnung in")} ${formatCountdownRemain(cooldownSeconds)}`
          : t("inv_basic_cooldown_ready", "Jetzt verfügbar");
      }
      card.dataset.maxOpen = String(maxOpen);
      card.querySelectorAll("[data-inventory-open]").forEach((btn) => {
        const isMaxBtn = btn.dataset.openMax === "1";
        if (isMaxBtn) {
          const openable = Math.max(0, Math.min(amount, maxOpen));
          btn.dataset.openAmount = String(Math.max(openable, 2));
          btn.disabled = !owned || openBlocked || amount < 2 || maxOpen < 2;
          return;
        }
        const need = parseInt(btn.dataset.openAmount, 10) || 1;
        const overMax = need > maxOpen;
        if (isBasic && need === 1) {
          btn.disabled = (openBlocked && !owned) || overMax;
        } else {
          btn.disabled = !owned || openBlocked || amount < need || overMax;
        }
      });
    });

    const itemList = document.querySelector("[data-inventory-item-list]");
    if (!itemList) return;

    const emptyItems = itemList.querySelector("[data-inventory-empty-items]");
    if (emptyItems) emptyItems.hidden = items.length > 0;

    items.forEach((item) => {
      let row = itemList.querySelector(`[data-inventory-item="${item.item_key}"]`);
      if (!row) {
        row = document.createElement("li");
        row.className = "inventory-item-row";
        row.dataset.inventoryItem = item.item_key;
        row.dataset.rarity = item.rarity || "common";
        itemList.appendChild(row);
      }
      row.dataset.usable = item.usable ? "1" : "0";
      row.dataset.collectible = item.collectible ? "1" : "0";
      row.dataset.canCraft = item.can_craft ? "1" : "0";
      row.innerHTML = buildInventoryItemRowHtml(item);
      row.hidden = false;
    });

    itemList.querySelectorAll("[data-inventory-item]").forEach((row) => {
      const key = row.dataset.inventoryItem;
      if (!items.some((i) => i.item_key === key)) row.remove();
    });

    if (items.length === 0 && !itemList.querySelector("[data-inventory-empty-items]")) {
      const empty = document.createElement("li");
      empty.className = "inventory-empty";
      empty.dataset.inventoryEmptyItems = "";
      empty.textContent = t("inv_no_items", "Noch keine Items.");
      itemList.appendChild(empty);
    }

    patchInventoryActiveBoosters(inv);
  }

  let _inventoryLastState = null;

  function bindInventoryOnce() {
    if (GC._inventoryEventsBound) return;
    GC._inventoryEventsBound = true;

    document.addEventListener("click", async (ev) => {
      const tkChip = ev.target.closest("[data-inventory-tk-chip-domain]");
      if (tkChip) {
        ev.preventDefault();
        const page = document.getElementById("inventory-page");
        if (!page || page.dataset.ready !== "1") return;
        void depositTimekeeperChip(tkChip, tkChip.dataset.inventoryTkChipDomain);
        return;
      }

      const useBtn = ev.target.closest("[data-inventory-use]");
      if (useBtn && !useBtn.disabled) {
        const page = document.getElementById("inventory-page");
        if (!page || page.dataset.ready !== "1") return;
        const itemKey = useBtn.dataset.inventoryUse;
        if (!itemKey) return;
        void runInventoryAction(
          useBtn,
          "/api/inventory/use",
          {
            item_key: itemKey,
            amount: 1,
            request_id: `inv-use-${itemKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          },
          (res) => {
            applyActionState(res, "inventory_use");
            renderInventoryEffect(res.effect || {});
            applyInventoryActionResult(res);
            void refreshInventoryFromServer();
          }
        );
        return;
      }

      const craftBtn = ev.target.closest("[data-inventory-craft]");
      if (craftBtn && !craftBtn.disabled) {
        const page = document.getElementById("inventory-page");
        if (!page || page.dataset.ready !== "1") return;
        const recipeKey = craftBtn.dataset.inventoryCraft;
        if (!recipeKey) return;
        void runInventoryAction(
          craftBtn,
          "/api/inventory/craft",
          {
            recipe_key: recipeKey,
            amount: 1,
            request_id: `inv-craft-${recipeKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          },
          (res) => {
            applyActionState(res, "inventory_craft");
            renderInventoryEffect(res.effect || {});
            applyInventoryActionResult(res);
            void refreshInventoryFromServer();
          }
        );
        return;
      }

      const exchangeBtn = ev.target.closest("[data-inventory-exchange]");
      if (exchangeBtn && !exchangeBtn.disabled) {
        const page = document.getElementById("inventory-page");
        if (!page || page.dataset.ready !== "1") return;
        const recipeKey = exchangeBtn.dataset.inventoryExchange;
        if (!recipeKey) return;
        void runInventoryAction(
          exchangeBtn,
          "/api/inventory/exchange",
          {
            recipe_key: recipeKey,
            amount: 1,
            request_id: `inv-exchange-${recipeKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          },
          (res) => {
            applyActionState(res, "inventory_exchange");
            renderInventoryEffect(res.effect || {});
            applyInventoryActionResult(res);
            void refreshInventoryFromServer();
          }
        );
        return;
      }

      const openBtn = ev.target.closest("[data-inventory-open]");
      if (!openBtn || openBtn.disabled) return;
      const page = document.getElementById("inventory-page");
      if (!page || page.dataset.ready !== "1") return;

      const itemKey = openBtn.dataset.inventoryOpen;
      if (!itemKey) return;
      let amount = parseInt(openBtn.dataset.openAmount, 10) || 1;
      if (openBtn.dataset.openMax === "1") {
        const card = openBtn.closest("[data-inventory-container]");
        const stockEl = card && card.querySelector(`[data-inventory-amount="${itemKey}"]`);
        const owned = Math.max(0, parseInt(stockEl && stockEl.textContent, 10) || 0);
        const maxOpen = Math.max(
          1,
          parseInt(card && card.dataset.maxOpen, 10) ||
            parseInt(openBtn.dataset.openAmount, 10) ||
            500
        );
        amount = Math.min(owned, maxOpen);
        if (amount < 2) return;
        openBtn.dataset.openAmount = String(amount);
      }

      const openButtons = Array.from(page.querySelectorAll("[data-inventory-open]"));
      void runInventoryAction(
        openButtons,
        "/api/inventory/open-container",
        {
          item_key: itemKey,
          amount,
          request_id: `inv-open-${itemKey}-${amount}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        },
        (res) => {
          showLootOpeningModal({
            ...res,
            item_key: itemKey,
            consumed: res.opened || amount,
            _deferredState: res.state,
            _deferredInventory: res.inventory,
          });
        }
      );
    });

    document.addEventListener("click", (ev) => {
      const closeBtn = ev.target.closest("[data-inventory-rewards-close]");
      if (!closeBtn) return;
      const panel = document.getElementById("inventory-rewards-panel");
      if (panel) panel.hidden = true;
    });
  }

  function tickInventoryCooldowns() {
    document.querySelectorAll("[data-inventory-cooldown]").forEach((el) => {
      let sec = parseInt(el.dataset.cooldownSeconds, 10) || 0;
      const card = el.closest("[data-inventory-container]");
      if (sec <= 0) {
        el.textContent = t("inv_basic_cooldown_ready", "Jetzt verfügbar");
        if (card && card.dataset.inventoryContainer === "container_basic") {
          const amountEl = card.querySelector('[data-inventory-amount="container_basic"]');
          const amount = amountEl ? parseInt(amountEl.textContent, 10) || 0 : 0;
          const hint = card.querySelector(".inventory-loot-card-status, .inventory-loot-card-hint");
          const openBtn = card.querySelector('[data-inventory-open][data-open-amount="1"]');
          if (amount <= 0) {
            card.classList.add("inventory-loot-card--free-ready");
            card.classList.remove("inventory-loot-card--empty");
            if (hint) hint.textContent = t("inv_basic_free_ready", "Gratis-Öffnung verfügbar");
            if (openBtn) openBtn.disabled = false;
          }
        }
        return;
      }
      sec = Math.max(0, sec - 1);
      el.dataset.cooldownSeconds = String(sec);
      el.textContent = `${t("inv_basic_cooldown_timer", "Gratis-Öffnung in")} ${formatCountdownRemain(sec)}`;
    });
  }

  function initInventory() {
    bindInventoryOnce();
    syncTradingSubnav("inventory");
    const page = document.getElementById("inventory-page");
    if (!page || page.dataset.ready !== "1") return;
    _inventoryLastState = parseInventoryPageState();
    patchInventoryDom(_inventoryLastState);
    GC.setSafeInterval(tickInventoryCooldowns, 1000);
    GC.registerCleanup(() => {
      closeLootModal();
      const panel = document.getElementById("inventory-rewards-panel");
      if (panel) panel.hidden = true;
    });
  }

  function parseAuctionHousePageState() {
    const el = document.getElementById("auction-house-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function patchAuctionHouseStats(stats) {
    const page = document.getElementById("auction-house-page");
    if (!page || !stats) return;
    const map = {
      active: stats.active_auctions,
      my_bids: stats.my_bids,
      won: stats.won_auctions,
    };
    Object.entries(map).forEach(([key, val]) => {
      const el = page.querySelector(`[data-auction-stat="${key}"]`);
      if (el && val !== undefined) _setIfChanged(el, String(val));
    });
  }

  function renderAuctionRecentBids(listingId, bids) {
    const page = document.getElementById("auction-house-page");
    if (!page) return;
    const section = page.querySelector(`[data-auction-recent="${listingId}"]`);
    if (!section) return;
    const rows = Array.isArray(bids) ? bids : [];
    let list = section.querySelector(`[data-auction-recent-list="${listingId}"]`);
    let empty = section.querySelector(`[data-auction-recent-empty="${listingId}"]`);
    if (!rows.length) {
      if (list) list.remove();
      if (!empty) {
        empty = document.createElement("p");
        empty.className = "auction-house-recent-empty";
        empty.dataset.auctionRecentEmpty = String(listingId);
        section.appendChild(empty);
      }
      empty.textContent = t("auction_house_recent_empty", "Noch keine Gebotshistorie.");
      empty.hidden = false;
      return;
    }
    if (empty) empty.remove();
    if (!list) {
      list = document.createElement("ul");
      list.className = "auction-house-recent-list";
      list.dataset.auctionRecentList = String(listingId);
      section.appendChild(list);
    }
    list.innerHTML = rows.map((bid) => (
      `<li class="auction-house-recent-row">`
      + `<span class="auction-house-recent-name">${escapeHtml(String(bid.player_name || "—"))}</span>`
      + `<span class="auction-house-recent-amount gc-mono">${escapeHtml(fmtNumber(bid.amount || 0))}</span>`
      + `</li>`
    )).join("");
  }

  function toggleAuctionHouseExpand(listingId, forceOpen) {
    const page = document.getElementById("auction-house-page");
    if (!page || !listingId) return;
    const id = String(listingId);
    const currentlyOpen = page.dataset.expandedAuction === id;
    const open = forceOpen === true ? true : forceOpen === false ? false : !currentlyOpen;

    page.querySelectorAll("[data-auction-expand]").forEach((expand) => {
      expand.hidden = true;
    });
    page.querySelectorAll("[data-auction-row]").forEach((row) => {
      row.classList.remove("is-expanded", "is-selected");
      row.setAttribute("aria-expanded", "false");
    });

    if (!open) {
      delete page.dataset.expandedAuction;
      return;
    }

    const row = page.querySelector(`[data-auction-row="${id}"]`);
    const expand = page.querySelector(`[data-auction-expand="${id}"]`);
    if (row) {
      row.classList.add("is-expanded", "is-selected");
      row.setAttribute("aria-expanded", "true");
    }
    if (expand) expand.hidden = false;
    page.dataset.expandedAuction = id;
  }

  function patchAuctionHousePanel(ah) {
    const page = document.getElementById("auction-house-page");
    if (!page || !ah || typeof ah !== "object") return;
    const tt = (key, fallback) => t(key, fallback);
    if (ah.stats) patchAuctionHouseStats(ah.stats);
    const auctions = Array.isArray(ah.auctions) ? ah.auctions : [];
    auctions.forEach((a) => {
      const id = a.id;
      if (!id) return;
      const hasBids = Boolean(a.has_bids || (a.current_bid > 0 && a.current_bidder_id));
      const displayBid = hasBids ? (a.current_bid || 0) : (a.display_bid || a.start_price || 0);
      const bidTxt = fmtNumber(displayBid);
      const currencyTxt = a.currency ? tt(`resource_${a.currency}`, a.currency) : "";

      const bidLabelEl = page.querySelector(`[data-auction-bid-label="${id}"]`);
      if (bidLabelEl) {
        const label = hasBids
          ? tt("auction_house_current_bid_upper", "AKTUELLES GEBOT")
          : tt("auction_house_start_bid_upper", "STARTGEBOT");
        _setIfChanged(bidLabelEl, label);
      }

      const bidEl = page.querySelector(`[data-auction-current-bid="${id}"]`);
      if (bidEl) _setIfChanged(bidEl, bidTxt);

      const currencyWrap = page.querySelector(`[data-auction-currency-label="${id}"]`);
      if (currencyWrap && currencyTxt) {
        const labelSpan = currencyWrap.querySelector("span:not(.gc-res-icon):not([class*='gc-res-icon'])");
        if (labelSpan) _setIfChanged(labelSpan, currencyTxt);
      }

      const rowBidderEl = page.querySelector(`[data-auction-row-bidder="${id}"]`);
      if (rowBidderEl) {
        const rowTxt = hasBids
          ? (a.is_leading
            ? tt("auction_house_you_lead_short", "Du (Führst)")
            : String(a.current_bidder_name || "—"))
          : "—";
        _setIfChanged(rowBidderEl, rowTxt);
      }

      const leaderBadge = page.querySelector(`[data-auction-leader="${id}"]`);
      const noBidsEl = page.querySelector(`[data-auction-no-bids="${id}"]`);
      const bidderEl = page.querySelector(`[data-auction-bidder="${id}"]`);
      if (hasBids && leaderBadge) {
        leaderBadge.hidden = false;
        leaderBadge.classList.toggle("auction-house-leader-badge--you", Boolean(a.is_leading));
        leaderBadge.classList.remove("auction-house-leader-badge--empty");
        if (bidderEl) {
          const txt = a.is_leading
            ? tt("auction_house_you_lead", "Du führst aktuell")
            : String(a.current_bidder_name || "—");
          _setIfChanged(bidderEl, txt);
        }
        if (noBidsEl) noBidsEl.hidden = true;
      } else if (leaderBadge) {
        leaderBadge.hidden = true;
        if (noBidsEl) noBidsEl.hidden = false;
      }

      const minEl = page.querySelector(`[data-auction-min-label="${id}"]`);
      if (minEl && a.min_next_bid) {
        const label = `(${tt("auction_house_min_bid", "min.")} ${fmtNumber(a.min_next_bid)})`;
        _setIfChanged(minEl, label);
      }
      const input = page.querySelector(`[data-auction-bid-input="${id}"]`);
      if (input) {
        const minVal = String(a.min_next_bid || 1);
        input.min = minVal;
        input.placeholder = fmtNumber(a.min_next_bid || 1);
        if (!input.matches(":focus") && (!input.value || readNumberInput(input) < parseIntNumber(minVal))) {
          setNumberInputValue(input, minVal);
        }
      }
      const card = page.querySelector(`[data-auction-card="${id}"]`);
      if (card) {
        card.dataset.minBid = String(a.min_next_bid || 1);
        card.dataset.currentBid = String(a.current_bid || 0);
        card.dataset.endsAt = String(a.ends_at || 0);
        card.dataset.currency = String(a.currency || "");
        card.dataset.hasBids = hasBids ? "1" : "0";
        card.dataset.isLeading = a.is_leading ? "1" : "0";
        card.classList.toggle("auction-house-row--leading", Boolean(a.is_leading));
      }
      const submitBtn = page.querySelector(`[data-auction-bid-submit="${id}"]`);
      if (submitBtn) {
        const label = a.is_leading
          ? tt("auction_house_raise_bid", "Gebot erhöhen")
          : tt("auction_house_place_bid", "Gebot abgeben");
        _setIfChanged(submitBtn, label);
      }
      renderAuctionRecentBids(id, a.recent_bids || []);
    });
    const expanded = page.dataset.expandedAuction;
    if (expanded && page.querySelector(`[data-auction-expand="${expanded}"]`)) {
      toggleAuctionHouseExpand(expanded, true);
    }
    patchAuctionHouseRotation(ah);
  }

  function formatAuctionRotationRemain(seconds) {
    const s = Math.max(0, Math.floor(Number(seconds) || 0));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const secR = s % 60;
    if (h > 0) return `${h}h ${m}m ${secR}s`;
    if (m > 0) return `${m}m ${secR}s`;
    return `${secR}s`;
  }

  async function refreshAuctionHouseState() {
    if (GC._auctionHouseRefreshInFlight) return;
    GC._auctionHouseRefreshInFlight = true;
    try {
      const res = await GC.fetchJSON("/api/auction-house/state");
      const ah = res?.auction_house;
      if (ah) patchAuctionHousePanel(ah);
    } catch (err) {
      console.warn("[GC] auction house state refresh failed", err);
    } finally {
      GC._auctionHouseRefreshInFlight = false;
    }
  }

  function patchAuctionHouseRotation(ah) {
    const page = document.getElementById("auction-house-page");
    if (!page || !ah) return;
    const nextAt = parseInt(String(ah.next_rotation_at || page.dataset.nextRotationAt || "0"), 10);
    if (nextAt > 0) page.dataset.nextRotationAt = String(nextAt);
    const timer = page.querySelector("[data-auction-rotation-timer]");
    if (timer && nextAt > 0) timer.dataset.nextRotationAt = String(nextAt);
    patchAuctionHouseUpcoming(ah.upcoming || []);
  }

  function patchAuctionHouseUpcoming(upcoming) {
    const page = document.getElementById("auction-house-page");
    if (!page || !Array.isArray(upcoming)) return;
    upcoming.forEach((u) => {
      const id = u.preview_index ?? u.id;
      if (id === undefined || id === null) return;
      const wrap = page.querySelector(`[data-auction-upcoming-available="${id}"]`);
      if (!wrap) return;
      const availableAt = u.available_at ?? u.starts_at;
      if (availableAt) wrap.dataset.availableAt = String(availableAt);
    });
  }

  function tickAuctionHouseCountdowns() {
    const page = document.getElementById("auction-house-page");
    if (!page) return;
    const now = Math.floor(getTimerServerNow());
    page.querySelectorAll("[data-auction-remaining]").forEach((wrap) => {
      const endsAt = parseInt(
        wrap.dataset.endsAt || wrap.closest("[data-auction-card]")?.dataset.endsAt || "0",
        10
      );
      if (!endsAt) return;
      const rem = Math.max(0, endsAt - now);
      const valEl = wrap.querySelector(".auction-house-time-value");
      if (valEl) _setIfChanged(valEl, formatCountdownRemain(rem));
    });
    page.querySelectorAll("[data-auction-upcoming-available]").forEach((wrap) => {
      const availableAt = parseInt(wrap.dataset.availableAt || "0", 10);
      if (!availableAt) return;
      const rem = Math.max(0, availableAt - now);
      const valEl = wrap.querySelector(".auction-house-upcoming-available-value");
      if (valEl) _setIfChanged(valEl, formatCountdownRemain(rem));
    });
    const rotWrap = page.querySelector("[data-auction-rotation-timer]");
    if (rotWrap) {
      const nextAt = parseInt(rotWrap.dataset.nextRotationAt || page.dataset.nextRotationAt || "0", 10);
      if (nextAt > 0) {
        const rem = Math.max(0, nextAt - now);
        const valEl = rotWrap.querySelector(".auction-rotation-timer-value");
        if (valEl) _setIfChanged(valEl, formatAuctionRotationRemain(rem));
        if (rem <= 0 && !GC._auctionHouseRotationRefreshDone) {
          GC._auctionHouseRotationRefreshDone = true;
          refreshAuctionHouseState().finally(() => {
            GC._auctionHouseRotationRefreshDone = false;
          });
        }
      }
    }
  }

  function bindAuctionHouseOnce() {
    if (GC._auctionHouseEventsBound) return;
    GC._auctionHouseEventsBound = true;

    document.addEventListener("click", (ev) => {
      const row = ev.target?.closest?.("[data-auction-row]");
      if (row && !ev.target?.closest?.("[data-auction-expand], [data-auction-bid-form], button, a, input, label")) {
        toggleAuctionHouseExpand(row.dataset.auctionRow);
        return;
      }

      const btn = ev.target?.closest?.("[data-auction-loot-toggle]");
      if (!btn) return;
      const id = btn.getAttribute("data-auction-loot-toggle");
      const panel = document.getElementById(`auction-loot-panel-${id}`);
      if (!panel) return;
      const open = panel.hidden;
      document.querySelectorAll(".auction-house-loot-preview-panel").forEach((p) => { p.hidden = true; });
      document.querySelectorAll("[data-auction-loot-toggle]").forEach((b) => {
        b.setAttribute("aria-expanded", "false");
      });
      if (open) {
        panel.hidden = false;
        btn.setAttribute("aria-expanded", "true");
      }
    });

    document.addEventListener("keydown", (ev) => {
      const row = ev.target?.closest?.("[data-auction-row]");
      if (!row) return;
      if (ev.key === "Enter" || ev.key === " ") {
        ev.preventDefault();
        toggleAuctionHouseExpand(row.dataset.auctionRow);
      }
    });

  }

  function bindAuctionHouseBidForms(root) {
    const page = root || document.querySelector("[data-auction-house]");
    if (!page) return;

    const tt = (key, fallback) => t(key, fallback);
    const auctionBidSucceeded = (res) => {
      if (!res || typeof res !== "object") return false;
      if (res.ok === true || res.reason === "bid_placed") return true;
      if (res.bid && res.bid.listing_id) return true;
      return false;
    };
    const auctionReasonText = (res) => {
      const reason = String((res && res.reason) || "generic");
      if (reason === "bid_must_raise") {
        return tt("auction_error_bid_must_raise", "Your bid must be higher than your current high bid.");
      }
      if (reason === "bid_too_low") {
        const minBid = Number(res?.min_bid || 0);
        if (minBid > 0) {
          return tt(
            "auction_error_bid_too_low_min",
            tt("auction_error_bid_too_low", "Bid is too low.") + ` (${tt("auction_house_min_bid", "min.")} ${fmtNumber(minBid)})`
          ).replace("%(min)s", fmtNumber(minBid));
        }
      }
      return tt(`auction_error_${reason}`, tt("auction_error_generic", "Bid failed."));
    };
    const setAuctionFormError = (listingId, message) => {
      const el = page.querySelector(`[data-auction-form-error="${listingId}"]`);
      if (!el) return;
      const msg = String(message || "").trim();
      el.textContent = msg;
      el.hidden = !msg;
    };

    page.querySelectorAll("[data-auction-bid-form]").forEach((form) => {
      if (form.dataset.bound === "1") return;
      form.dataset.bound = "1";

      form.addEventListener("submit", async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        ev.stopImmediatePropagation();

        const listingId = parseInt(
          form.querySelector("[name='listing_id']")?.value
          || form.getAttribute("data-auction-bid-form")
          || "0",
          10
        );
        const card = page.querySelector(`[data-auction-card="${listingId}"]`);
        const currency = String(
          form.querySelector("[name='currency']")?.value
          || card?.dataset.currency
          || ""
        ).trim();
        const input = form.querySelector("[data-auction-bid-input], [name='amount']");
        const btn = form.querySelector("[data-auction-bid-submit], [type='submit']");
        const amount = readNumberInput(input);
        const minBid = parseInt(String(card?.dataset.minBid || input?.min || "0"), 10);

        setAuctionFormError(listingId, "");
        if (!listingId || !currency || !amount) {
          const msg = tt("auction_error_invalid_amount", "Enter a valid bid.");
          setAuctionFormError(listingId, msg);
          showNotify(msg, "error");
          return;
        }
        if (minBid > 0 && amount < minBid) {
          const msg = auctionReasonText({ reason: "bid_too_low", min_bid: minBid });
          setAuctionFormError(listingId, msg);
          showNotify(msg, "error");
          return;
        }
        const isLeading = card?.dataset.isLeading === "1";
        const currentBid = parseInt(String(card?.dataset.currentBid || "0"), 10);
        if (isLeading && currentBid > 0 && amount <= currentBid) {
          const msg = auctionReasonText({ reason: "bid_must_raise", min_bid: minBid });
          setAuctionFormError(listingId, msg);
          showNotify(msg, "error");
          return;
        }
        if (form.dataset.submitting === "1") return;
        form.dataset.submitting = "1";
        if (btn) {
          btn.disabled = true;
          btn.classList.add("is-loading");
        }

        const requestId = newRequestId();
        let res = null;
        try {
          res = await GC.fetchGameAction("/api/auction-house/bid", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "X-Request-Id": requestId,
            },
            body: JSON.stringify({
              listing_id: listingId,
              amount,
              currency,
              request_id: requestId,
            }),
          });
        } catch (err) {
          if (err?.name === "AbortError") return;
          const msg = tt("auction_error_generic", "Bid failed.");
          setAuctionFormError(listingId, msg);
          showNotify(msg, "error");
          console.warn("[GC] auction bid request failed", err);
        } finally {
          form.dataset.submitting = "0";
          if (btn) {
            btn.disabled = false;
            btn.classList.remove("is-loading");
          }
        }

        if (!res) return;

        const succeeded = auctionBidSucceeded(res);
        const ahPayload = res?.auction_house || res?.state?.auction_house;
        try {
          if (ahPayload) patchAuctionHousePanel(ahPayload);
        } catch (patchErr) {
          console.warn("[GC] auction panel patch failed", patchErr);
        }

        if (succeeded) {
          try {
            if (res?.state) applyActionState(res, "auction_bid");
          } catch (stateErr) {
            console.warn("[GC] auction bid state apply failed", stateErr);
          }
          setAuctionFormError(listingId, "");
          showNotify(tt("auction_bid_ok", "Bid placed."), "success");
          if (input && ahPayload?.auctions) {
            const row = ahPayload.auctions.find((a) => Number(a.id) === listingId);
            if (row?.min_next_bid) setNumberInputValue(input, row.min_next_bid);
            else input.value = "";
          } else if (input) {
            input.value = "";
          }
        } else {
          try {
            if (res?.state) applyActionState(res, "auction_bid_error");
          } catch (_) {}
          const msg = auctionReasonText(res || { reason: "generic" });
          setAuctionFormError(listingId, msg);
          showNotify(msg, "error");
        }
      }, true);
    });
  }

  function initAuctionHouse() {
    bindAuctionHouseOnce();
    syncTradingSubnav("auction_house");
    const page = document.getElementById("auction-house-page");
    bindAuctionHouseBidForms(page);
    if (!page || page.dataset.ready !== "1") return;
    const state = parseAuctionHousePageState();
    if (state) patchAuctionHousePanel(state);
    tickAuctionHouseCountdowns();
    GC.setSafeInterval(tickAuctionHouseCountdowns, 1000);
    GC.registerCleanup(() => {});
  }

  function parseVoteCenterPageState() {
    const el = document.getElementById("vote-center-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function _voteRewardTypeLabel(r) {
    const key = String(r?.reward_type_label_key || "");
    if (key) return t(key, String(r?.reward_type || "lootbox"));
    const map = {
      standard_box: t("vote_reward_type_standard_box", "Standard-Box"),
      lootbox: t("vote_reward_type_standard_box", "Standard-Box"),
      resources: t("vote_reward_type_standard_box", "Standard-Box"),
      ships: t("vote_reward_type_standard_box", "Standard-Box"),
      defense: t("vote_reward_type_standard_box", "Standard-Box"),
    };
    return map[String(r?.reward_type || "standard_box")] || map.standard_box;
  }

  const VOTE_REWARD_IMG_FALLBACK = "/static/img/lootboxes/Generic_Supply_Container.webp";

  function _voteRewardDisplayHtml(r) {
    const items = Array.isArray(r?.display_items) ? r.display_items : [];
    if (!items.length) return "";
    return `<div class="vote-center-reward-visual">${items.map((item) => {
      const kind = String(item?.kind || "");
      const resKey = String(item?.resource_key || "");
      const name = t(item?.name_key || "", item?.name_fallback || "");
      const img = escapeHtml(String(item?.image || VOTE_REWARD_IMG_FALLBACK));
      const amount = fmtNumber(Number(item?.amount) || 0);
      const mods = [
        "vote-center-reward-item",
        kind ? `vote-center-reward-item--${escapeHtml(kind)}` : "",
        resKey ? `vote-center-reward-item--${escapeHtml(resKey)}` : "",
      ].filter(Boolean).join(" ");
      return `<div class="${mods}">
        <img class="vote-center-reward-item-img"
             src="${img}"
             alt="${escapeHtml(name)}"
             loading="lazy"
             decoding="async"
             onerror="this.onerror=null;this.src='${VOTE_REWARD_IMG_FALLBACK}';">
        <div class="vote-center-reward-item-meta">
          <span class="vote-center-reward-item-name">${escapeHtml(name)}</span>
          <span class="vote-center-reward-item-amount gc-mono">× ${escapeHtml(amount)}</span>
        </div>
      </div>`;
    }).join("")}</div>`;
  }

  function voteProviderCooldownRemaining(p, nowSec) {
    const remSec = Number(p.cooldown_remaining_sec);
    if (Number.isFinite(remSec) && remSec > 0) return Math.floor(remSec);
    const nextAt = Number(p.next_vote_at);
    if (!Number.isFinite(nextAt) || nextAt <= 0) return 0;
    return Math.max(0, Math.floor(nextAt - nowSec));
  }

  function formatVoteProviderStatus(p, nowSec) {
    const canVote = p.can_vote_now === true || p.can_vote_hint === true;
    if (canVote) {
      return t("vote_center_ready_to_vote", "Bereit zum Voten");
    }
    const rem = voteProviderCooldownRemaining(p, nowSec);
    if (rem <= 0) {
      return t("vote_center_now", "Jetzt");
    }
    return formatCountdownRemain(rem);
  }

  function patchVoteCenterDom(vc) {
    if (!vc) return;
    const rewards = Array.isArray(vc.pending_rewards) ? vc.pending_rewards : [];
    const pendingCount = Number(vc.pending_count) || rewards.length;
    const now = Math.floor(getApproxServerNow());

    document.querySelectorAll("[data-vote-pending-count]").forEach((el) => {
      el.textContent = String(pendingCount);
    });
    document.querySelectorAll("[data-vote-pending-count-inline]").forEach((el) => {
      el.textContent = String(pendingCount);
    });
    const claimAllBtn = document.querySelector("[data-vote-claim-all]");
    if (claimAllBtn) claimAllBtn.disabled = pendingCount <= 0;

    const providers = Array.isArray(vc.providers) ? vc.providers : [];
    providers.forEach((p) => {
      const key = String(p.provider_key || "");
      if (!key) return;
      const lastEl = document.querySelector(`[data-vote-provider-last="${key}"]`);
      const nextEl = document.querySelector(`[data-vote-provider-next="${key}"]`);
      const subtitleEl = document.querySelector(`[data-vote-provider-subtitle="${key}"]`);
      const rewardStatusEl = document.querySelector(`[data-vote-provider-reward-status="${key}"]`);
      const hintEl = document.querySelector(`[data-vote-provider-hint="${key}"]`);
      const voteCountEl = document.querySelector(`[data-vote-provider-count="${key}"]`);
      const linkEl = document.querySelector(`[data-vote-provider-link="${key}"]`);
      if (subtitleEl && p.subtitle_key) {
        subtitleEl.textContent = t(p.subtitle_key, subtitleEl.textContent || "");
      }
      if (rewardStatusEl && p.reward_status_key) {
        rewardStatusEl.textContent = t(p.reward_status_key, rewardStatusEl.textContent || "");
      }
      if (lastEl) {
        lastEl.textContent = p.last_vote_at
          ? formatLocaleDateTime(p.last_vote_at)
          : t("vote_center_never", "Noch nie");
      }
      if (nextEl) {
        const rem = voteProviderCooldownRemaining(p, now);
        if (p.can_vote_hint) {
          nextEl.textContent = t("vote_center_now", "Jetzt");
        } else if (rem > 0) {
          nextEl.textContent = formatCountdownRemain(rem);
        } else {
          nextEl.textContent = t("vote_center_now", "Jetzt");
        }
      }
      if (hintEl) {
        const rem = voteProviderCooldownRemaining(p, now);
        const postbackEnabled = !!p.postback_enabled;
        if (!postbackEnabled) {
          hintEl.hidden = false;
          const noRewardKey = String(p.no_auto_reward_key || "").trim();
          hintEl.textContent = noRewardKey
            ? t(noRewardKey, hintEl.textContent || "")
            : t(
                "vote_provider_gametoor_no_auto_reward",
                "GameToor-Votes werden aktuell noch nicht automatisch belohnt."
              );
          hintEl.classList.add("vote-center-hint-wait");
          hintEl.classList.remove("vote-center-hint-ready");
        } else if (p.can_vote_hint) {
          hintEl.hidden = false;
          hintEl.textContent = t("vote_center_can_vote", "Du kannst jetzt voten.");
          hintEl.classList.add("vote-center-hint-ready");
          hintEl.classList.remove("vote-center-hint-wait");
        } else if (rem > 0) {
          hintEl.hidden = true;
        } else {
          hintEl.hidden = false;
          hintEl.textContent = t("vote_center_wait_vote", "Bitte warte, bis der Cooldown abgelaufen ist.");
          hintEl.classList.add("vote-center-hint-wait");
          hintEl.classList.remove("vote-center-hint-ready");
        }
      }
      if (voteCountEl) voteCountEl.textContent = fmtNumber(Number(p.vote_count) || 0);
      if (linkEl && p.vote_url) linkEl.href = p.vote_url;
    });

    const list = document.querySelector("[data-vote-rewards-list]");
    if (!list) return;
    if (!rewards.length) {
      list.innerHTML = `<p class="vote-center-empty" data-vote-rewards-empty>${escapeHtml(t("vote_center_no_rewards", "Keine offenen Belohnungen."))}</p>`;
      return;
    }
    list.innerHTML = rewards.map((r) => `
      <article class="vote-center-reward-card" data-vote-reward-id="${Number(r.id)}">
        ${_voteRewardDisplayHtml(r)}
        <div class="vote-center-reward-info">
          <span class="vote-center-reward-title">${escapeHtml(t("vote_reward_title", "Vote Belohnung"))}</span>
          <span class="vote-center-reward-provider">${escapeHtml(String(r.provider_name || r.provider || ""))}</span>
          <span class="vote-center-reward-type">${escapeHtml(_voteRewardTypeLabel(r))}</span>
        </div>
        <button type="button" class="gc-btn gc-btn-ghost gc-btn-sm vote-center-claim-btn" data-vote-claim="${Number(r.id)}">
          ${escapeHtml(t("vote_center_claim_btn", "Belohnung abholen"))}
        </button>
      </article>
    `).join("");
  }

  async function _submitVoteClaim(endpoint, body, successKey, failKey, reasonKey) {
    const res = await GC.fetchGameAction(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (res?.state) applyActionState(res, res.ok ? reasonKey : `${reasonKey}_error`);
    if (res?.vote_center) patchVoteCenterDom(res.vote_center);
    if (res?.ok) {
      showNotify(t(successKey, "Belohnung ins Inventar gutgeschrieben."), "success");
    } else {
      showNotify(t(failKey, "Belohnung konnte nicht abgeholt werden."), "error");
    }
    return res;
  }

  let _voteCenterBound = false;
  let _voteCenterPollTimer = null;

  function stopVoteCenterPoll() {
    if (_voteCenterPollTimer) {
      clearInterval(_voteCenterPollTimer);
      _voteCenterPollTimer = null;
    }
  }

  async function refreshVoteCenterState() {
    const page = document.getElementById("vote-center-page");
    if (!page || page.dataset.ready !== "1") return null;
    try {
      const res = await GC.fetchGameAction("/api/vote/center-state");
      if (res?.vote_center) patchVoteCenterDom(res.vote_center);
      return res;
    } catch (_) {
      return null;
    }
  }

  function startVoteCenterPoll(maxAttempts = 24, intervalMs = 5000) {
    stopVoteCenterPoll();
    let attempts = 0;
    _voteCenterPollTimer = GC.setSafeInterval(async () => {
      if (document.hidden || !shouldRunVisualLoops()) return;
      attempts += 1;
      const page = document.getElementById("vote-center-page");
      if (!page || page.dataset.ready !== "1" || attempts > maxAttempts) {
        stopVoteCenterPoll();
        return;
      }
      await refreshVoteCenterState();
    }, intervalMs);
  }

  function bindVoteCenterOnce() {
    if (_voteCenterBound) return;
    _voteCenterBound = true;
    document.addEventListener("click", async (ev) => {
      const page = document.getElementById("vote-center-page");
      if (!page || page.dataset.ready !== "1") return;

      const voteLink = ev.target.closest("[data-vote-provider-link]");
      if (voteLink && voteLink.href) {
        ev.preventDefault();
        const providerKey = String(voteLink.dataset.voteProviderLink || "").trim();
        const href = voteLink.href;
        if (providerKey) {
          try {
            const res = await GC.fetchGameAction("/api/vote/visit", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                provider_key: providerKey,
                request_id: newRequestId(),
              }),
            });
            if (res?.vote_center) patchVoteCenterDom(res.vote_center);
            if (res?.ok && res?.created) {
              showNotify(
                t("vote_center_visit_reward_pending", "Vote registriert — Belohnung wartet im Vote Center."),
                "success"
              );
              window.open(href, "_blank", "noopener,noreferrer");
              startVoteCenterPoll();
            } else if (res?.ok && res?.reason === "cooldown_active") {
              const rem = Math.max(0, Number(res.cooldown_remaining_sec) || 0);
              showNotify(
                `${t("vote_center_next_in", "Nächster Vote möglich in")} ${formatCountdownRemain(rem)}`,
                "info"
              );
            }
          } catch (_) {
            showNotify(t("vote_center_visit_fail", "Vote konnte nicht registriert werden."), "error");
          }
        } else {
          window.open(href, "_blank", "noopener,noreferrer");
        }
        return;
      }

      const claimAllBtn = ev.target.closest("[data-vote-claim-all]");
      if (claimAllBtn && !claimAllBtn.disabled) {
        ev.preventDefault();
        claimAllBtn.disabled = true;
        try {
          await _submitVoteClaim(
            "/api/vote/rewards/claim-all",
            { request_id: newRequestId() },
            "vote_center_claim_all_ok",
            "vote_center_claim_all_fail",
            "vote_reward_claim_all"
          );
        } catch (_) {
          showNotify(t("vote_center_claim_all_fail", "Belohnungen konnten nicht abgeholt werden."), "error");
        } finally {
          claimAllBtn.disabled = false;
        }
        return;
      }

      const btn = ev.target.closest("[data-vote-claim]");
      if (!btn || btn.disabled) return;
      ev.preventDefault();
      const rewardId = parseInt(btn.dataset.voteClaim, 10) || 0;
      if (!rewardId) return;
      btn.disabled = true;
      try {
        await _submitVoteClaim(
          "/api/vote/rewards/claim",
          { reward_id: rewardId, request_id: newRequestId() },
          "vote_center_claim_ok",
          "vote_center_claim_fail",
          "vote_reward_claim"
        );
      } catch (_) {
        showNotify(t("vote_center_claim_fail", "Belohnung konnte nicht abgeholt werden."), "error");
      } finally {
        btn.disabled = false;
      }
    }, true);
  }

  function initVoteCenter() {
    bindVoteCenterOnce();
    syncTradingSubnav("vote_center");
    const page = document.getElementById("vote-center-page");
    if (!page || page.dataset.ready !== "1") return;
    const state = parseVoteCenterPageState();
    if (state) patchVoteCenterDom(state);
    GC.registerCleanup(stopVoteCenterPoll);
    if (!page._voteFocusBound) {
      page._voteFocusBound = true;
      const onFocus = () => {
        if (document.visibilityState && document.visibilityState !== "visible") return;
        refreshVoteCenterState();
      };
      window.addEventListener("focus", onFocus);
      document.addEventListener("visibilitychange", onFocus);
      GC.registerCleanup(() => {
        window.removeEventListener("focus", onFocus);
        document.removeEventListener("visibilitychange", onFocus);
        page._voteFocusBound = false;
      });
    }
  }

  function parseReferralsPageState() {
    const el = document.getElementById("referrals-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function _referralTierCardHtml(tier, scope) {
    const display = tier.display || {};
    const img = escapeHtml(String(display.image || "/static/img/lootboxes/Generic_Supply_Container.webp"));
    const title = escapeHtml(t(tier.label_key, tier.reward_key || ""));
    const desc = tier.desc_key ? escapeHtml(t(tier.desc_key, "")) : "";
    const progress = escapeHtml(String(tier.progress_label || ""));
    const claimable = Boolean(tier.claimable);
    const claimed = Boolean(tier.claimed);
    const unlocked = tier.unlocked !== false;
    let stateClass = "";
    if (claimable) stateClass = "referral-tier-card--claimable";
    else if (claimed) stateClass = "referral-tier-card--claimed";
    else if (!unlocked) stateClass = "referral-tier-card--locked";
    const action = claimable
      ? `<button type="button" class="gc-btn gc-btn-ghost gc-btn-sm" data-referral-claim>${escapeHtml(t("referral_claim_btn", "Abholen"))}</button>`
      : claimed
        ? `<span class="referral-tier-claimed">${escapeHtml(t("referral_claimed_badge", "Abgeholt"))}</span>`
        : scope === "referrer"
          ? `<span class="referral-tier-locked gc-mono" aria-hidden="true"></span>`
          : "";
    const progressLine = scope === "referrer"
      ? `<p class="referral-tier-progress gc-mono">${progress} ${escapeHtml(t("referral_tier_progress_suffix", "erfolgreiche Empfehlungen"))}</p>`
      : "";
    return `
      <article class="referral-tier-card ${stateClass}"
               data-referral-tier
               data-reward-scope="${escapeHtml(scope)}"
               data-reward-key="${escapeHtml(String(tier.reward_key || ""))}"
               data-required="${Number(tier.required_count) || 0}">
        <div class="referral-tier-visual">
          <img src="${img}" alt="" width="64" height="64" loading="lazy">
        </div>
        <div class="referral-tier-info">
          <h3 class="referral-tier-title">${title}</h3>
          ${desc ? `<p class="referral-tier-desc">${desc}</p>` : ""}
          ${progressLine}
        </div>
        ${action}
      </article>
    `;
  }

  function patchReferralsDom(state) {
    if (!state || typeof state !== "object") return;
    const page = document.getElementById("referrals-page");
    if (!page) return;

    const codeEl = page.querySelector("[data-referral-code]");
    if (codeEl && state.code) codeEl.textContent = String(state.code);

    const urlInput = page.querySelector("[data-referral-url-input]");
    if (urlInput && state.referral_url) urlInput.value = String(state.referral_url);

    const progressEl = page.querySelector("[data-referral-progress]");
    if (progressEl) {
      const pending = Math.max(0, Number(state.pending_count) || 0);
      const successful = Math.max(0, Number(state.successful_count) || 0);
      let html = `${escapeHtml(t("referral_progress", "Erfolgreiche Empfehlungen"))}: <strong>${fmtNumber(successful)}</strong>`;
      if (pending > 0) {
        html += ` <span class="referral-progress-pending">(${pending} ${escapeHtml(t("referral_pending_short", "ausstehend"))})</span>`;
      }
      progressEl.innerHTML = html;
    }

    const tierList = page.querySelector("[data-referral-tier-list]");
    if (tierList && Array.isArray(state.referrer_tiers)) {
      tierList.innerHTML = state.referrer_tiers.map((tier) => _referralTierCardHtml(tier, "referrer")).join("");
    }

    const referredList = page.querySelector("[data-referral-referred-list]");
    if (referredList) {
      if (state.referred_reward) {
        referredList.innerHTML = _referralTierCardHtml(state.referred_reward, "referred");
      } else {
        referredList.innerHTML = "";
      }
    }
  }

  let _referralsBound = false;

  function bindReferralsOnce() {
    if (_referralsBound) return;
    _referralsBound = true;

    document.addEventListener("click", async (ev) => {
      const copyBtn = ev.target.closest("[data-referral-copy]");
      if (copyBtn) {
        const page = document.getElementById("referrals-page");
        if (!page) return;
        const mode = String(copyBtn.dataset.referralCopy || "");
        let text = "";
        if (mode === "code") {
          text = page.querySelector("[data-referral-code]")?.textContent?.trim() || "";
        } else if (mode === "link") {
          text = page.querySelector("[data-referral-url-input]")?.value?.trim() || "";
        }
        if (!text) return;
        try {
          await navigator.clipboard.writeText(text);
          showNotify(t("referral_copy_ok", "In Zwischenablage kopiert."), "success");
        } catch (_) {
          showNotify(t("referral_copy_fail", "Kopieren fehlgeschlagen."), "error");
        }
        return;
      }

      const claimBtn = ev.target.closest("[data-referral-claim]");
      if (claimBtn) {
        const card = claimBtn.closest("[data-referral-tier]");
        if (!card) return;
        const scope = String(card.dataset.rewardScope || "").trim();
        const rewardKey = String(card.dataset.rewardKey || "").trim();
        if (!scope || !rewardKey) return;
        const res = await GC.fetchGameAction("/api/referrals/claim", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            reward_scope: scope,
            reward_key: rewardKey,
            request_id: newRequestId(),
          }),
        });
        if (res?.state) applyActionState(res, "referral_claim");
        if (res?.referrals) patchReferralsDom(res.referrals);
        if (res?.ok) {
          showNotify(t("referral_claim_ok", "Belohnung ins Inventar gutgeschrieben."), "success");
        } else {
          showNotify(t("referral_claim_fail", "Belohnung konnte nicht abgeholt werden."), "error");
        }
      }
    });

    document.addEventListener("submit", async (ev) => {
      const form = ev.target.closest("[data-referral-apply-form]");
      if (!form) return;
      ev.preventDefault();
      const input = form.querySelector("[data-referral-apply-input]");
      const code = String(input?.value || "").trim();
      if (!code) {
        showNotify(t("referral_apply_missing", "Bitte einen Code eingeben."), "error");
        return;
      }
      const res = await GC.fetchGameAction("/api/referrals/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ referral_code: code, request_id: newRequestId() }),
      });
      if (res?.state) applyActionState(res, "referral_apply");
      if (res?.referrals) patchReferralsDom(res.referrals);
      if (res?.ok) {
        showNotify(t("referral_apply_ok", "Referral-Code verknüpft."), "success");
        const applyPanel = document.querySelector(".referral-apply-panel");
        if (applyPanel) applyPanel.remove();
      } else {
        const reason = String(res?.reason || "");
        const msg = reason === "referral_self_not_allowed"
          ? t("referral_err_self", "Du kannst deinen eigenen Code nicht verwenden.")
          : reason === "referral_already_linked"
            ? t("referral_err_already_linked", "Du hast bereits einen Referrer.")
            : reason === "referral_code_not_found"
              ? t("referral_err_not_found", "Code nicht gefunden.")
              : t("referral_apply_fail", "Code konnte nicht eingelöst werden.");
        showNotify(msg, "error");
      }
    });
  }

  function initReferrals() {
    bindReferralsOnce();
    const page = document.getElementById("referrals-page");
    if (!page || page.dataset.ready !== "1") return;
    const state = parseReferralsPageState();
    if (state) patchReferralsDom(state);
  }

  let _loginRewardsBound = false;
  function parseLoginRewardsPageState() {
    const el = document.getElementById("login-rewards-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  let _loginRewardsCooldownTimer = null;
  let _loginRewardsUnlockAt = 0;

  function _stopLoginRewardsCooldown() {
    if (_loginRewardsCooldownTimer) {
      clearInterval(_loginRewardsCooldownTimer);
      _loginRewardsCooldownTimer = null;
    }
  }

  function _tickLoginRewardsCooldown() {
    const page = document.getElementById("login-rewards-page");
    if (!page) {
      _stopLoginRewardsCooldown();
      return;
    }
    const cooldown = page.querySelector("[data-lr-cooldown]");
    const secEl = page.querySelector("[data-lr-cooldown-sec]");
    if (!cooldown || !secEl) return;
    const now =
      typeof serverNow === "function"
        ? Number(serverNow())
        : typeof GC.getServerNow === "function"
          ? Number(GC.getServerNow())
          : Date.now() / 1000;
    const rem = Math.max(0, Math.floor(_loginRewardsUnlockAt - now));
    secEl.textContent = formatDurationHuman(rem, 3);
    if (rem <= 0) {
      cooldown.hidden = true;
      _stopLoginRewardsCooldown();
    }
  }

  function patchLoginRewardsDom(state) {
    const page = document.getElementById("login-rewards-page");
    if (!page || !state) return;
    const cur = page.querySelector("[data-lr-current-day]");
    if (cur) cur.textContent = `${Number(state.current_day || 0)}/30`;
    const next = page.querySelector("[data-lr-next-day]");
    if (next) next.textContent = state.available ? String(state.next_day || "—") : "—";
    page.querySelectorAll("[data-lr-claim]").forEach((btn) => {
      const disabled = !state.available;
      btn.disabled = disabled;
      btn.setAttribute("aria-disabled", disabled ? "true" : "false");
    });
    const cooldown = page.querySelector("[data-lr-cooldown]");
    const unlockIn = Math.max(0, Math.floor(Number(state.next_unlock_in_sec) || 0));
    if (cooldown) {
      const showCd = !state.available && unlockIn > 0;
      cooldown.hidden = !showCd;
      if (showCd) {
        const now =
          typeof serverNow === "function"
            ? Number(serverNow())
            : typeof GC.getServerNow === "function"
              ? Number(GC.getServerNow())
              : Date.now() / 1000;
        _loginRewardsUnlockAt = now + unlockIn;
        _tickLoginRewardsCooldown();
        if (!_loginRewardsCooldownTimer) {
          _loginRewardsCooldownTimer = setInterval(_tickLoginRewardsCooldown, 1000);
        }
      } else {
        _stopLoginRewardsCooldown();
      }
    }
    const script = document.getElementById("login-rewards-page-state");
    if (script) script.textContent = JSON.stringify(state);
  }

  function syncLiveOpsFromGameState(data, reason) {
    if (!data) return;
    const reasonStr = String(reason || "");
    if (data.login_rewards && document.getElementById("login-rewards-page")) {
      patchLoginRewardsDom(data.login_rewards);
    }
    if (reasonStr === "page_hydrate") return;
    const opsPanel = document.querySelector("[data-bp-ops][data-bp-daily-period]");
    if (!opsPanel || !document.getElementById("premium-page")) return;
    const serverKey = String(data.battle_pass?.ops?.daily_period_key || "").trim();
    const domKey = String(opsPanel.getAttribute("data-bp-daily-period") || "").trim();
    if (serverKey && domKey && serverKey !== domKey) {
      if (typeof GC.reloadCurrentPage === "function") {
        GC.reloadCurrentPage({ skipPolling: true, reason: "bp_daily_period_rollover" });
      }
    }
  }

  function bindLoginRewardsOnce() {
    if (_loginRewardsBound) return;
    _loginRewardsBound = true;
    document.addEventListener("click", async (ev) => {
      const btn = ev.target.closest("[data-lr-claim]");
      if (!btn) return;
      const page = document.getElementById("login-rewards-page");
      if (!page) return;
      if (btn.disabled || btn.getAttribute("aria-disabled") === "true") return;
      const res = await GC.fetchGameAction("/api/login-rewards/claim", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ request_id: newRequestId() }),
      });
      if (res?.state) applyActionState(res, "login_reward_claim");
      if (res?.login_rewards) {
        if (res.login_rewards.days) {
          GC.reloadCurrentPage({ skipPolling: true });
          return;
        }
        patchLoginRewardsDom(res.login_rewards);
      }
      if (res?.ok) {
        showNotify(t("login_rewards_claim_ok", "Login-Belohnung gutgeschrieben."), "success");
      } else {
        showNotify(t("login_rewards_claim_fail", "Belohnung konnte nicht abgeholt werden."), "error");
      }
    });
  }

  function initLoginRewards() {
    bindLoginRewardsOnce();
    const page = document.getElementById("login-rewards-page");
    if (!page || page.dataset.ready !== "1") return;
    const state = parseLoginRewardsPageState();
    if (state) patchLoginRewardsDom(state);
    if (typeof GC.registerCleanup === "function") {
      GC.registerCleanup(_stopLoginRewardsCooldown);
    }
  }

  let _battlePassBound = false;
  function parseBattlePassPageState() {
    const el = document.getElementById("battle-pass-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  function bindBattlePassOnce() {
    if (_battlePassBound) return;
    _battlePassBound = true;
    document.addEventListener("click", async (ev) => {
      const opBtn = ev.target.closest("[data-bp-claim-op]");
      if (opBtn) {
        const page = document.getElementById("premium-page");
        if (!page) return;
        const opKey = String(opBtn.getAttribute("data-bp-claim-op") || "").trim();
        if (!opKey) return;
        // Server owns period_key (UTC day); do not send stale DOM period.
        const res = await GC.fetchGameAction("/api/battle-pass/claim-op", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            op_key: opKey,
            request_id: newRequestId(),
          }),
        });
        if (res?.state) applyActionState(res, "battle_pass_claim_op");
        if (res?.ok) {
          showNotify(t("bp_op_claim_ok", "Season-Op XP gutgeschrieben."), "success");
          GC.reloadCurrentPage({ skipPolling: true });
        } else {
          const reason = String(res?.reason || "");
          const msg =
            reason === "incomplete"
              ? t("bp_op_err_incomplete", "Op noch nicht erfüllt.")
              : reason === "already_claimed"
                ? t("bp_op_err_claimed", "Op bereits abgeholt.")
                : t("bp_op_claim_fail", "Op-XP konnte nicht abgeholt werden.");
          showNotify(msg, "error");
        }
        return;
      }

      const btn = ev.target.closest("[data-bp-claim]");
      if (!btn) return;
      const page = document.getElementById("premium-page");
      if (!page) return;
      const track = String(btn.getAttribute("data-bp-claim") || "").trim();
      const level = Number(btn.getAttribute("data-bp-level") || 0);
      if (!track || level <= 0) return;
      const res = await GC.fetchGameAction("/api/battle-pass/claim", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          track,
          level,
          request_id: newRequestId(),
        }),
      });
      if (res?.state) applyActionState(res, "battle_pass_claim");
      if (res?.ok) {
        showNotify(t("bp_claim_ok", "Pass-Belohnung gutgeschrieben."), "success");
        GC.reloadCurrentPage({ skipPolling: true });
      } else {
        const reason = String(res?.reason || "");
        const msg =
          reason === "premium_required"
            ? t("bp_err_premium", "Premium-Track ist noch nicht freigeschaltet.")
            : reason === "level_not_reached"
              ? t("bp_err_level", "Level noch nicht erreicht.")
              : t("bp_claim_fail", "Belohnung konnte nicht abgeholt werden.");
        showNotify(msg, "error");
      }
    });
  }

  function initBattlePassTrackboard(page) {
    const board = page.querySelector("[data-bp-trackboard]");
    if (!board) return;
    const tiers = Array.from(board.querySelectorAll("[data-bp-tier]"));
    if (!tiers.length) return;

    const pageSize = Math.max(1, Number(board.getAttribute("data-page-size") || 6) || 6);
    const playerLevel = Math.max(
      1,
      Number(board.getAttribute("data-player-level") || 1) || 1
    );
    const pageCount = Math.max(1, Math.ceil(tiers.length / pageSize));
    let pageIndex = 0;

    const prevBtn = board.querySelector("[data-bp-page-prev]");
    const nextBtn = board.querySelector("[data-bp-page-next]");
    const labelEl = page.querySelector("[data-bp-page-label]");
    const jumpBtn = page.querySelector("[data-bp-jump-current]");
    const previewEmpty = page.querySelector("[data-bp-preview-empty]");
    const previewBody = page.querySelector("[data-bp-preview-body]");

    function pageForLevel(level) {
      const idx = tiers.findIndex((el) => Number(el.getAttribute("data-bp-level") || 0) === level);
      if (idx < 0) return 0;
      return Math.floor(idx / pageSize);
    }

    function renderPage() {
      const start = pageIndex * pageSize;
      const end = start + pageSize;
      tiers.forEach((tier, i) => {
        const show = i >= start && i < end;
        if (show) tier.removeAttribute("hidden");
        else tier.setAttribute("hidden", "");
      });
      if (labelEl) {
        const tpl = t("bp_page_label", "PAGE {n} / {m}");
        labelEl.textContent = tpl
          .replace("{n}", String(pageIndex + 1))
          .replace("{m}", String(pageCount));
      }
      if (prevBtn) prevBtn.disabled = pageIndex <= 0;
      if (nextBtn) nextBtn.disabled = pageIndex >= pageCount - 1;
    }

    function clearSelection() {
      board.querySelectorAll("[data-bp-card].is-selected").forEach((card) => {
        card.classList.remove("is-selected");
        card.setAttribute("aria-pressed", "false");
      });
    }

    function selectCard(card, opts) {
      if (!card) return;
      const ensureVisible = !opts || opts.ensureVisible !== false;
      const level = Number(card.getAttribute("data-bp-level") || 0);
      if (ensureVisible && level > 0) {
        const targetPage = pageForLevel(level);
        if (targetPage !== pageIndex) {
          pageIndex = targetPage;
          renderPage();
        }
      }
      clearSelection();
      card.classList.add("is-selected");
      card.setAttribute("aria-pressed", "true");
      const detail = card.querySelector("[data-bp-card-detail]");
      if (previewBody && detail) {
        previewBody.innerHTML = detail.innerHTML;
        previewBody.hidden = false;
        if (previewEmpty) previewEmpty.hidden = true;
      }
    }

    function pickDefaultCard() {
      const claimable = board.querySelector("[data-bp-card].is-claimable");
      if (claimable) return claimable;
      const currentTier = tiers.find(
        (el) => Number(el.getAttribute("data-bp-level") || 0) === playerLevel
      );
      if (currentTier) {
        const free = currentTier.querySelector('[data-bp-card][data-bp-track="free"]');
        if (free) return free;
      }
      return board.querySelector("[data-bp-card]");
    }

    function goToCurrent() {
      pageIndex = pageForLevel(playerLevel);
      renderPage();
      const card = pickDefaultCard();
      if (card) selectCard(card, { ensureVisible: true });
    }

    const onBoardClick = (ev) => {
      if (ev.target.closest("[data-bp-claim]")) return;
      const card = ev.target.closest("[data-bp-card]");
      if (!card || !board.contains(card)) return;
      selectCard(card, { ensureVisible: false });
    };

    const onBoardKeydown = (ev) => {
      const card = ev.target.closest("[data-bp-card]");
      if (!card || !board.contains(card)) return;
      if (ev.key === "Enter" || ev.key === " ") {
        ev.preventDefault();
        selectCard(card, { ensureVisible: false });
      }
    };

    const onDocKeydown = (ev) => {
      if (!document.getElementById("premium-page")) return;
      if (ev.target && (ev.target.tagName === "INPUT" || ev.target.tagName === "TEXTAREA")) {
        return;
      }
      if (ev.key === "ArrowLeft") {
        if (pageIndex <= 0) return;
        ev.preventDefault();
        pageIndex -= 1;
        renderPage();
      } else if (ev.key === "ArrowRight") {
        if (pageIndex >= pageCount - 1) return;
        ev.preventDefault();
        pageIndex += 1;
        renderPage();
      }
    };

    board.addEventListener("click", onBoardClick);
    board.addEventListener("keydown", onBoardKeydown);
    document.addEventListener("keydown", onDocKeydown);

    if (prevBtn) {
      prevBtn.addEventListener("click", () => {
        if (pageIndex <= 0) return;
        pageIndex -= 1;
        renderPage();
      });
    }
    if (nextBtn) {
      nextBtn.addEventListener("click", () => {
        if (pageIndex >= pageCount - 1) return;
        pageIndex += 1;
        renderPage();
      });
    }
    if (jumpBtn) {
      jumpBtn.addEventListener("click", () => goToCurrent());
    }

    pageIndex = pageForLevel(playerLevel);
    renderPage();
    const initial = pickDefaultCard();
    if (initial) selectCard(initial, { ensureVisible: true });

    if (typeof GC.registerCleanup === "function") {
      GC.registerCleanup(() => {
        board.removeEventListener("click", onBoardClick);
        board.removeEventListener("keydown", onBoardKeydown);
        document.removeEventListener("keydown", onDocKeydown);
      });
    }
  }

  function initBattlePass() {
    bindBattlePassOnce();
    bindShopBuyOnce();
    const page = document.getElementById("premium-page");
    if (!page) return;
    initBattlePassTrackboard(page);

    const state = parseBattlePassPageState();
    const remEl = page.querySelector("[data-bp-remaining]");
    if (!remEl) return;
    const fromState = Number(state?.season?.seconds_remaining);
    const fromAttr = Number(remEl.getAttribute("data-remaining-seconds") || 0);
    const endsAt = Number(state?.season?.ends_at || 0);
    const tick = () => {
      let rem = 0;
      if (endsAt > 0) {
        const now =
          typeof serverNow === "function"
            ? serverNow()
            : typeof GC.getServerNow === "function"
              ? GC.getServerNow()
              : Date.now() / 1000;
        rem = Math.max(0, Math.floor(endsAt - Number(now)));
      } else if (Number.isFinite(fromState) && fromState > 0) {
        rem = Math.max(0, Math.floor(fromState));
      } else {
        rem = Math.max(0, Math.floor(fromAttr || 0));
      }
      remEl.setAttribute("data-remaining-seconds", String(rem));
      remEl.textContent = formatDurationHuman(rem, 3);
    };
    tick();
  }

  let _shopBuyBound = false;

  function _shopSelectTab(page, tabKey) {
    const key = tabKey === "free" ? "free" : "premium";
    page.querySelectorAll("[data-shop-tab]").forEach((btn) => {
      const on = btn.getAttribute("data-shop-tab") === key;
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    page.querySelectorAll("[data-shop-panel]").forEach((panel) => {
      const on = panel.getAttribute("data-shop-panel") === key;
      panel.classList.toggle("is-active", on);
      if (on) panel.removeAttribute("hidden");
      else panel.setAttribute("hidden", "");
    });
    try {
      if (key === "free" && window.location.hash !== "#free") {
        history.replaceState(null, "", `${window.location.pathname}${window.location.search}#free`);
      } else if (key !== "free" && window.location.hash === "#free") {
        history.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
      }
    } catch (_) { /* ignore */ }
  }

  function _freeShopKindLabel(kind) {
    if (kind === "timekeeper") return t("shop_kind_timekeeper", "TIMEKEEPER");
    if (kind === "entitlement") return t("shop_kind_pass", "PASS");
    return t("shop_kind_supply", "SUPPLY");
  }

  function _renderFreeShopState(page, freeShop) {
    if (!page || !freeShop) return;
    const label = freeShop.label || t("inv_ark_token", "Ark-Token");
    const bal = Number(freeShop.balance) || 0;
    const balEl = page.querySelector("[data-free-shop-balance]");
    if (balEl) {
      balEl.innerHTML = `${escapeHtml(t("free_shop_balance", "Bestand"))}: <strong>${fmtNumber(bal)}</strong> ${escapeHtml(label)}`;
    }
    const grid = page.querySelector("[data-free-shop-grid]");
    if (!grid || !Array.isArray(freeShop.offers)) return;
    const assetV = (typeof GC !== "undefined" && GC.assetVersion) ? String(GC.assetVersion) : "";
    grid.innerHTML = freeShop.offers.map((offer) => {
      const affordable = !!offer.affordable;
      const img = offer.image
        ? `<figure class="shop-card-art"><img src="/static/${escapeHtml(offer.image)}${assetV ? `?v=${escapeHtml(assetV)}` : ""}" alt="" width="640" height="400" loading="lazy" decoding="async"><span class="shop-card-kind">${escapeHtml(_freeShopKindLabel(offer.kind))}</span></figure>`
        : "";
      return (
        `<article class="shop-card free-shop-card${affordable ? "" : " is-locked"}" data-free-shop-offer="${escapeHtml(offer.offer_id || "")}" data-shop-kind="${escapeHtml(offer.kind || "")}">`
        + `<div class="shop-card-frame" aria-hidden="true"></div>${img}`
        + `<div class="shop-card-body"><div class="shop-card-main">`
        + `<h2 class="shop-card-title">${escapeHtml(offer.title || offer.offer_id || "")}</h2>`
        + `<p class="hint shop-card-hint">${escapeHtml(offer.hint || "")}</p></div>`
        + `<div class="shop-card-footer"><p class="shop-card-price gc-mono">${fmtNumber(offer.cost || 0)} ${escapeHtml(label)}</p>`
        + `<div class="shop-card-actions"><button type="button" class="gc-btn gc-btn-sm gc-btn-primary" data-free-shop-redeem data-offer-id="${escapeHtml(offer.offer_id || "")}" ${affordable ? "" : "disabled"}>`
        + `${escapeHtml(t("free_shop_redeem", "Einlösen"))}</button></div></div></div></article>`
      );
    }).join("");
  }

  function bindShopBuyOnce() {
    if (_shopBuyBound) return;
    _shopBuyBound = true;
    document.addEventListener("click", async (ev) => {
      const tabBtn = ev.target && ev.target.closest ? ev.target.closest("[data-shop-tab]") : null;
      if (tabBtn) {
        const page = document.getElementById("shop-page");
        if (!page) return;
        ev.preventDefault();
        _shopSelectTab(page, tabBtn.getAttribute("data-shop-tab") || "premium");
        return;
      }

      const redeemBtn = ev.target && ev.target.closest ? ev.target.closest("[data-free-shop-redeem]") : null;
      if (redeemBtn) {
        const page = document.getElementById("shop-page");
        if (!page) return;
        ev.preventDefault();
        if (redeemBtn.disabled) return;
        const offerId = redeemBtn.getAttribute("data-offer-id") || "";
        if (!offerId) return;
        redeemBtn.disabled = true;
        try {
          const res = await GC.fetchGameAction("/api/story/free-shop/redeem", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ offer_id: offerId }),
          });
          if (res && typeof GC.applyActionState === "function") {
            GC.applyActionState(res, "story_free_shop_redeem");
          }
          if (res && res.ok && res.free_shop) {
            _renderFreeShopState(page, res.free_shop);
            showNotify(t("free_shop_redeem_ok", "Eingelöst."), "success");
          } else {
            const err = (res && res.error) || "";
            showNotify(
              err === "insufficient_tokens"
                ? t("free_shop_need", "Nicht genug Ark-Tokens.")
                : t("free_shop_fail", "Einlösen fehlgeschlagen."),
              "error"
            );
          }
        } catch (_) {
          showNotify(t("free_shop_fail", "Einlösen fehlgeschlagen."), "error");
        } finally {
          redeemBtn.disabled = false;
        }
        return;
      }

      const btn = ev.target && ev.target.closest ? ev.target.closest("[data-shop-buy]") : null;
      if (!btn) return;
      if (!document.getElementById("shop-page") && !document.getElementById("premium-page")) {
        return;
      }
      ev.preventDefault();
      if (btn.disabled) return;
      const sku = String(btn.getAttribute("data-sku") || "").trim();
      const provider = String(btn.getAttribute("data-provider") || "").trim();
      if (!sku || !provider) return;
      btn.disabled = true;
      try {
        const res = await GC.fetchGameAction("/api/shop/checkout", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sku, provider }),
        });
        if (res?.state && typeof GC.applyActionState === "function") {
          GC.applyActionState(res, "shop_checkout");
        }
        if (res?.ok && res.fulfilled) {
          showNotify(t("shop_fulfill_ok", "Kauf gutgeschrieben."), "success");
          if (typeof GC.reloadCurrentPage === "function") {
            GC.reloadCurrentPage({ reason: "shop_fulfilled" });
          }
          return;
        }
        if (res?.ok && res.checkout_url) {
          // External provider checkout — allowed navigation exception.
          window.location.assign(String(res.checkout_url));
          return;
        }
        const reason = String(res?.reason || "");
        let msg = t("shop_checkout_fail", "Kauf konnte nicht gestartet werden.");
        if (reason === "shop_disabled") msg = t("shop_disabled", "Shop ist derzeit deaktiviert.");
        else if (reason === "already_owned") msg = t("shop_owned", "Bereits freigeschaltet");
        else if (reason === "provider_unconfigured") {
          msg = t("shop_no_providers", "Zahlungsanbieter sind noch nicht konfiguriert.");
        }
        showNotify(msg, "error");
      } catch (_) {
        showNotify(t("shop_checkout_fail", "Kauf konnte nicht gestartet werden."), "error");
      } finally {
        btn.disabled = false;
      }
    });
  }

  function initShop() {
    bindShopBuyOnce();
    const page = document.getElementById("shop-page");
    if (!page) return;
    const wantFree = (window.location.hash || "") === "#free";
    _shopSelectTab(page, wantFree ? "free" : "premium");
    try {
      const el = document.getElementById("free-shop-page-state");
      if (el) {
        const fs = JSON.parse(el.textContent || "{}");
        if (fs && typeof fs === "object") _renderFreeShopState(page, fs);
      }
    } catch (_) { /* ignore */ }
  }

  function parseAlliancePageState() {
    const el = document.getElementById("alliance-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  function allianceErrorMessage(res, fallback) {
    const key = String(res?.error || res?.reason || "").trim();
    if (key === "already_in_alliance") {
      return t("alliance_err_already_member", "Du bist bereits in einer Allianz.");
    }
    if (key === "alliance_full") return t("alliance_err_full", "Allianz ist voll.");
    if (key === "alliance_not_found") return t("alliance_err_not_found", "Allianz nicht gefunden.");
    if (key === "invalid_alliance") return t("alliance_err_invalid", "Tag oder Name ungültig.");
    if (key === "recruitment_application_only") {
      return t("alliance_err_application_only", "Diese Allianz nimmt nur Bewerbungen an.");
    }
    if (key === "recruitment_closed") {
      return t("alliance_err_recruitment_closed", "Diese Allianz ist geschlossen.");
    }
    if (key === "application_message_required") {
      return t("alliance_err_message_required", "Bitte eine Bewerbungsnachricht eingeben.");
    }
    if (key === "pending_application_exists") {
      return t("alliance_err_pending_exists", "Du hast bereits eine offene Bewerbung.");
    }
    if (key === "application_not_found") {
      return t("alliance_err_application_not_found", "Bewerbung nicht gefunden.");
    }
    if (key === "alliance_logo_missing") {
      return t("alliance_logo_missing", "Bitte eine Bilddatei waehlen.");
    }
    if (key === "alliance_logo_too_large") {
      return t("alliance_logo_too_large", "Datei ist zu gross (max. 2 MB).");
    }
    if (key === "alliance_logo_invalid_type") {
      return t("alliance_logo_invalid_type", "Ungueltiges Bildformat.");
    }
    if (key === "alliance_logo_rate_limited") {
      return t("alliance_logo_rate_limited", "Bitte kurz warten und erneut versuchen.");
    }
    if (key === "leader_must_transfer") {
      return t("alliance_err_leader_must_transfer", "Als Leader musst du zuerst die Führung übertragen.");
    }
    if (key === "forbidden") {
      return t("alliance_err_forbidden", "Keine Berechtigung.");
    }
    if (key === "member_not_found") {
      return t("alliance_err_member_not_found", "Mitglied nicht gefunden.");
    }
    if (key === "transfer_not_officer") {
      return t("alliance_err_transfer_not_officer", "Leadership kann nur an Offiziere übertragen werden.");
    }
    if (key === "duplicate_tag") {
      return t("alliance_err_duplicate_tag", "Tag ist bereits vergeben.");
    }
    if (key === "duplicate_name") {
      return t("alliance_err_duplicate_name", "Name ist bereits vergeben.");
    }
    if (key === "invalid_tag") {
      return t("alliance_err_invalid_tag", "Tag ungültig.");
    }
    if (key === "invalid_role") {
      return t("alliance_err_invalid_role", "Rolle ungültig.");
    }
    if (key === "duplicate_diplomacy_request") {
      return t("alliance_err_duplicate_diplomacy", "Anfrage bereits offen.");
    }
    if (key === "pool_cap_exceeded") {
      return t("alliance_err_pool_cap_exceeded", "Allianzkasse ist voll.");
    }
    if (key === "invalid_broadcast") {
      return t("alliance_err_invalid_broadcast", "Betreff und Nachricht sind erforderlich.");
    }
    if (key === "no_recipients") {
      return t("alliance_err_no_recipients", "Keine Empfänger in der Allianz.");
    }
    if (key === "insufficient_resources") {
      return t("alliance_err_insufficient_resources", "Nicht genug Ressourcen auf dem aktiven Planeten.");
    }
    if (key === "invalid_donation") {
      return t("alliance_err_invalid_donation", "Ungültige Spende.");
    }
    if (key === "project_active") {
      return t("alliance_err_project_active", "Es läuft bereits ein Allianz-Projekt.");
    }
    if (key === "insufficient_pool") {
      return t("alliance_err_insufficient_pool", "Allianzkasse reicht nicht aus.");
    }
    return key || fallback || t("alliance_action_failed", "Aktion fehlgeschlagen.");
  }

  function patchAllianceDom(state) {
    if (!state || !state.in_alliance) return;
    const page = document.getElementById("alliance-page");
    if (!page) return;
    const fmt = typeof GC.fmtIntFull === "function" ? GC.fmtIntFull : (n) => String(n ?? 0);
    ["metal", "crystal", "fuel_cells"].forEach((res) => {
      const val = Number(state.pool?.[res] ?? 0);
      const cap = Number(state.pool_cap?.[res] ?? 0);
      const maxVal = Number(state.donation_limits?.[res] ?? Math.max(0, cap - val));
      const needRem = Number(state.project_need_remaining?.[res] ?? 0);
      const tile = page.querySelector(`.alliance-hub-pool-tile[data-resource="${res}"]`);
      const valEl = page.querySelector(`[data-pool-val="${res}"]`);
      const capEl = page.querySelector(`[data-pool-cap="${res}"]`);
      const fillEl = page.querySelector(`[data-pool-fill="${res}"]`);
      const needEl = page.querySelector(`[data-pool-need="${res}"]`);
      const actions = page.querySelector(`[data-pool-actions="${res}"]`);
      if (tile) tile.classList.toggle("is-full", maxVal <= 0);
      if (valEl) valEl.textContent = fmt(val);
      if (capEl) capEl.textContent = fmt(cap);
      if (fillEl) {
        const pct = cap > 0 ? Math.min(100, (val / cap) * 100) : 0;
        fillEl.style.width = `${pct}%`;
      }
      if (needEl) {
        if (state.active_project) {
          needEl.textContent = t("alliance_donate_need_active", "Projekt aktiv");
        } else if (needRem > 0) {
          needEl.textContent = t("alliance_donate_need_remaining", "Projekt braucht noch %(amt)s").replace(
            "%(amt)s",
            fmt(needRem)
          );
        } else {
          needEl.textContent = t("alliance_donate_need_ready", "Projektbedarf gedeckt");
        }
      }
      if (actions) {
        if (maxVal <= 0) {
          actions.innerHTML = `<span class="alliance-hub-pool-full-badge" data-pool-full="${res}">${escapeHtml(
            t("alliance_donate_complete", "Vollständig")
          )}</span>`;
        } else {
          let input = actions.querySelector(`[data-donate-amount="${res}"]`);
          if (!input) {
            actions.innerHTML = `
              <input type="text" inputmode="numeric" autocomplete="off" maxlength="20"
                class="gc-input gc-num-input alliance-hub-donate-input"
                data-donate-amount="${res}" data-input-max="${maxVal}"
                placeholder="${escapeHtml(t("alliance_donate_max_hint", "Max. %(max)s").replace("%(max)s", fmt(maxVal)))}">
              <div class="alliance-hub-pool-action-btns">
                <button type="button" class="gc-btn gc-btn-xs gc-btn-ghost" data-donate-max="${res}">${escapeHtml(t("alliance_donate_max_btn", "Max"))}</button>
                <button type="button" class="gc-btn gc-btn-sm gc-btn-secondary" data-donate-btn="${res}">${escapeHtml(t("alliance_donate_btn", "Spenden"))}</button>
              </div>`;
            input = actions.querySelector(`[data-donate-amount="${res}"]`);
            if (typeof bindFormattedNumberInputs === "function") bindFormattedNumberInputs(actions);
          } else {
            input.dataset.inputMax = String(maxVal);
            input.disabled = false;
            input.placeholder = t("alliance_donate_max_hint", "Max. %(max)s").replace("%(max)s", fmt(maxVal));
            if (!input.matches(":focus") && readNumberInput(input) > maxVal) {
              setNumberInputValue(input, maxVal);
            }
            const btn = actions.querySelector(`[data-donate-btn="${res}"]`);
            const maxBtn = actions.querySelector(`[data-donate-max="${res}"]`);
            if (btn) btn.disabled = false;
            if (maxBtn) maxBtn.disabled = false;
          }
        }
      }
    });
    const summary = page.querySelector("[data-alliance-summary]");
    if (summary && state.alliance_level != null) {
      const lvl = summary.querySelector("[data-alliance-level], .alliance-level-badge");
      if (lvl) lvl.textContent = "L" + state.alliance_level;
    }
    const lastXp = page.querySelector("[data-alliance-last-donation-xp]");
    if (lastXp) {
      const xp = Number(state.last_donation_xp || 0);
      if (xp > 0) {
        lastXp.hidden = false;
        lastXp.textContent = t("alliance_xp_last_donation", "Letzte Spende: +%(xp)s XP").replace(
          "%(xp)s",
          fmt(xp)
        );
      }
    }
    const logWrap = page.querySelector("[data-alliance-donations-log]");
    const logList = page.querySelector("[data-alliance-donation-list]");
    if (logWrap && logList && Array.isArray(state.recent_donations)) {
      const rows = state.recent_donations.slice(0, 12);
      logWrap.hidden = rows.length === 0;
      const resLabel = (key) => {
        if (key === "metal") return t("resource_metal", "Ferronit");
        if (key === "crystal") return t("resource_crystal", "Crytite");
        if (key === "fuel_cells") return t("resource_fuel_cells", "Brennzellen");
        return key;
      };
      const resIcon = (key) => {
        if (key !== "metal" && key !== "crystal" && key !== "fuel_cells") return "";
        const mod = `gc-res-${key.replace(/_/g, "-")}`;
        return `<span class="gc-res-icon gc-res-icon--sm ${mod}" aria-hidden="true"></span>`;
      };
      logList.innerHTML = rows
        .map((d) => {
          const name = escapeHtml(String(d.player_name || ""));
          const amt = fmt(Number(d.amount || 0));
          const resKey = String(d.resource || "");
          const label = escapeHtml(resLabel(resKey));
          return `<li class="alliance-hub-donation-row"><span>${name}</span><span class="alliance-hub-donation-amount gc-mono">${amt}</span><span class="alliance-hub-donation-res">${resIcon(resKey)}<span class="alliance-hub-donation-res-name">${label}</span></span></li>`;
        })
        .join("");
    }
    if (Array.isArray(state.members)) {
      state.members.forEach((m) => {
        const row = page.querySelector(`[data-member-id="${m.player_id}"]`);
        if (!row) return;
        const cells = row.querySelectorAll("td.gc-mono");
        if (cells.length >= 2 && m.donation_points != null) {
          const compact =
            typeof GC.fmtIntCompact === "function"
              ? GC.fmtIntCompact(Number(m.donation_points || 0))
              : fmt(Number(m.donation_points || 0));
          cells[1].textContent = compact;
        }
      });
    }
    if (state.show_logo && state.logo_url_client && state.alliance_id != null) {
      const aid = String(state.alliance_id);
      const frame = page.querySelector(`[data-alliance-logo-frame="${aid}"]`);
      if (frame) {
        let img = frame.querySelector("[data-alliance-logo-img]");
        const ph = frame.querySelector("[data-alliance-logo-ph]");
        if (!img) {
          img = document.createElement("img");
          img.className = "alliance-hub-logo";
          img.dataset.allianceLogoImg = aid;
          img.loading = "lazy";
          frame.appendChild(img);
        }
        img.src = state.logo_url_client;
        img.alt = String(state.name || "");
        img.hidden = false;
        if (ph) ph.remove();
      }
    }
    if (state.active_project) {
      const panel = page.querySelector("[data-alliance-active-project]");
      if (panel) {
        panel.dataset.finishAt = String(state.active_project.finish_at || "");
        panel.dataset.startedAt = String(state.active_project.started_at || "");
        panel.dataset.durationSeconds = String(state.active_project.duration_seconds || "");
        panel.dataset.progressPct = String(state.active_project.progress_pct ?? "");
        updateAllianceProjectProgress(panel);
      }
    } else {
      const panel = page.querySelector("[data-alliance-active-project]");
      if (panel) panel.remove();
    }
  }

  function updateAllianceProjectProgress(panel) {
    if (!panel) return;
    const finishAt = Number(panel.dataset.finishAt || 0);
    const startedAt = Number(panel.dataset.startedAt || 0);
    const durationSec = Number(panel.dataset.durationSeconds || 0);
    const now = GC.getServerNow ? GC.getServerNow() : Date.now() / 1000;
    const fill = panel.querySelector("[data-project-fill]");
    const eta = panel.querySelector("[data-project-eta]");
    if (!finishAt || finishAt <= now) {
      if (fill) fill.style.width = "100%";
      if (eta) eta.textContent = "";
      return;
    }
    const serverPct = panel.dataset.progressPct;
    let pct = serverPct !== "" && serverPct != null ? Number(serverPct) : NaN;
    if (Number.isNaN(pct)) {
      const total = durationSec > 0 ? durationSec : Math.max(1, finishAt - startedAt);
      if (startedAt > 0 && total > 0) {
        pct = Math.min(100, Math.max(0, ((now - startedAt) / total) * 100));
      } else {
        pct = 0;
      }
    } else if (startedAt > 0 && durationSec > 0) {
      const elapsed = Math.max(0, now - startedAt);
      pct = Math.min(100, Math.max(Number(serverPct), (elapsed / durationSec) * 100));
    }
    if (fill) fill.style.width = pct.toFixed(1) + "%";
    if (eta) eta.textContent = formatCountdownRemain(Math.max(0, Math.ceil(finishAt - now)));
  }

  let _allianceActionInFlight = false;

  async function allianceReloadHub(reason) {
    const cleanUrl = "/alliance";
    if (typeof GC.navigateTo === "function") {
      await GC.navigateTo(cleanUrl, { push: false, force: true });
    } else if (typeof GC.reloadCurrentPage === "function") {
      await GC.reloadCurrentPage({ force: true });
    }
    if (window.history?.replaceState) {
      window.history.replaceState(null, "", cleanUrl);
    }
    void reason;
  }

  /** In-hub field updates: allianceAction already applied state + patchAllianceDom. */
  const ALLIANCE_PATCH_ONLY = new Set([
    "alliance_profile",
    "alliance_recruitment",
    "alliance_diplomacy",
    "alliance_donate",
  ]);

  async function allianceFinalizeSuccess(reason, out) {
    if (ALLIANCE_PATCH_ONLY.has(String(reason || "")) && out?.alliance) {
      return;
    }
    await allianceReloadHub(reason);
  }

  async function allianceAction(url, body, reason) {
    if (_allianceActionInFlight) return { ok: false, error: "in_flight" };
    _allianceActionInFlight = true;
    const page = document.getElementById("alliance-page");
    const busyBtns = page
      ? [...page.querySelectorAll("[data-alliance-submit], [data-donate-btn], [data-alliance-leave]")]
      : [];
    busyBtns.forEach((btn) => {
      btn.disabled = true;
    });
    try {
      const res = await GC.fetchGameAction(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body || {}),
      });
      if (res?.state) applyActionState(res, reason || "alliance");
      if (res?.alliance) {
        const stateEl = document.getElementById("alliance-page-state");
        if (stateEl) stateEl.textContent = JSON.stringify(res.alliance);
        patchAllianceDom(res.alliance);
      }
      return res;
    } finally {
      _allianceActionInFlight = false;
      busyBtns.forEach((btn) => {
        btn.disabled = false;
      });
      const stateEl = document.getElementById("alliance-page-state");
      if (stateEl) {
        try {
          patchAllianceDom(JSON.parse(stateEl.textContent || "{}"));
        } catch (_) {}
      }
    }
  }

  async function allianceHandleCreate(form) {
    const fd = new FormData(form);
    const out = await allianceAction(
      "/api/alliance/create",
      {
        tag: String(fd.get("tag") || "").trim(),
        name: String(fd.get("name") || "").trim(),
        description: String(fd.get("description") || "").trim(),
      },
      "alliance_create"
    );
    if (out?.ok && out?.alliance?.in_alliance) {
      await allianceFinalizeSuccess("alliance_create", out);
      showNotify(t("alliance_create_success", "Allianz gegründet."), "success");
      return;
    }
    showNotify(allianceErrorMessage(out, "Gründung fehlgeschlagen"), "error");
  }

  async function allianceHandleJoin(form) {
    const fd = new FormData(form);
    const out = await allianceAction(
      "/api/alliance/join",
      { tag: String(fd.get("tag") || "").trim() },
      "alliance_join"
    );
    if (out?.ok && out?.alliance?.in_alliance) {
      await allianceFinalizeSuccess("alliance_join", out);
      showNotify(t("alliance_join_success", "Allianz beigetreten."), "success");
      return;
    }
    showNotify(allianceErrorMessage(out, "Beitritt fehlgeschlagen"), "error");
  }

  function allianceIsAllianceForm(form) {
    if (!form || form.tagName !== "FORM") return false;
    return Boolean(
      form.matches(
        "[data-alliance-create-form], [data-alliance-join-form], [data-alliance-desc-form], [data-alliance-profile-form], [data-alliance-diplomacy-form]"
      )
    );
  }

  function allianceBlockNativeSubmit(ev) {
    const form = ev.target;
    if (!allianceIsAllianceForm(form)) return;
    const page = document.getElementById("alliance-page");
    if (!page || !page.contains(form)) return;
    ev.preventDefault();
    ev.stopPropagation();
  }

  let _allianceBound = false;
  function bindAllianceOnce() {
    if (_allianceBound) return;
    _allianceBound = true;

    document.addEventListener("submit", allianceBlockNativeSubmit, true);

    document.addEventListener("change", async (ev) => {
      const logoInput = ev.target.closest("[data-alliance-logo-upload]");
      if (!logoInput?.files?.[0]) return;
      const page = document.getElementById("alliance-page");
      if (!page || !page.contains(logoInput)) return;
      const file = logoInput.files[0];
      const fd = new FormData();
      fd.append("logo", file);
      if (_allianceActionInFlight) return;
      _allianceActionInFlight = true;
      try {
        const out = await GC.fetchGameAction("/api/alliance/logo", {
          method: "POST",
          credentials: "same-origin",
          headers: { "X-Requested-With": "XMLHttpRequest" },
          body: fd,
        });
        if (out?.state) applyActionState(out, "alliance_logo_upload");
        if (out?.alliance) {
          const stateEl = document.getElementById("alliance-page-state");
          if (stateEl) stateEl.textContent = JSON.stringify(out.alliance);
          patchAllianceDom(out.alliance);
        }
        if (!out?.ok) {
          showNotify(allianceErrorMessage(out, "Logo-Upload fehlgeschlagen"), "error");
        } else {
          showNotify(t("alliance_logo_upload_ok", "Logo gespeichert."), "success");
        }
      } catch (_) {
        showNotify(t("alliance_logo_upload_fail", "Logo-Upload fehlgeschlagen."), "error");
      } finally {
        _allianceActionInFlight = false;
        logoInput.value = "";
      }
    });

    document.addEventListener("click", async (ev) => {
      const page = document.getElementById("alliance-page");
      if (!page || !page.contains(ev.target)) return;

      const manageOpen = ev.target.closest("[data-alliance-manage-open]");
      if (manageOpen) {
        ev.preventDefault();
        const dlg = document.getElementById("alliance-manage-modal");
        if (dlg && typeof dlg.showModal === "function") dlg.showModal();
        return;
      }
      const manageClose = ev.target.closest("[data-alliance-manage-close]");
      if (manageClose) {
        ev.preventDefault();
        const dlg = document.getElementById("alliance-manage-modal");
        if (dlg && dlg.open) dlg.close();
        return;
      }

      const broadcastOpen = ev.target.closest("[data-alliance-broadcast-open]");
      if (broadcastOpen) {
        ev.preventDefault();
        const dlg = document.getElementById("alliance-broadcast-modal");
        if (dlg && typeof dlg.showModal === "function") dlg.showModal();
        return;
      }
      const broadcastClose = ev.target.closest("[data-alliance-broadcast-close]");
      if (broadcastClose) {
        ev.preventDefault();
        const dlg = document.getElementById("alliance-broadcast-modal");
        if (dlg && dlg.open) dlg.close();
        return;
      }
      const broadcastSubmit = ev.target.closest("[data-alliance-broadcast-submit]");
      if (broadcastSubmit) {
        ev.preventDefault();
        const form = broadcastSubmit.closest("form");
        if (!form) return;
        const fd = new FormData(form);
        const subject = String(fd.get("subject") || "").trim();
        const body = String(fd.get("body") || "").trim();
        if (!subject || !body) {
          showNotify(t("alliance_err_invalid_broadcast", "Betreff und Nachricht sind erforderlich."), "error");
          return;
        }
        const out = await allianceAction(
          "/api/alliance/broadcast",
          { subject, body },
          "alliance_broadcast"
        );
        if (out?.ok) {
          const count = Number(out.broadcast_count || 0);
          const tpl = t("alliance_broadcast_ok", "Rundmail an %(count)s Mitglieder gesendet.");
          showNotify(tpl.replace("%(count)s", String(count)), "success");
          form.reset();
          const dlg = document.getElementById("alliance-broadcast-modal");
          if (dlg?.open) dlg.close();
        } else {
          showNotify(allianceErrorMessage(out, "Rundmail fehlgeschlagen"), "error");
        }
        return;
      }

      const chatOpen = ev.target.closest("[data-alliance-chat-open]");
      if (chatOpen) {
        ev.preventDefault();
        if (typeof GC.openAllianceChat === "function") {
          void GC.openAllianceChat();
        } else if (typeof GC.openTChat === "function") {
          void GC.openTChat();
        }
        return;
      }

      const tabJump = ev.target.closest("[data-alliance-tab-jump]");
      if (tabJump) {
        ev.preventDefault();
        const key = String(tabJump.dataset.allianceTabJump || "projects");
        const highlight = String(tabJump.dataset.allianceHighlightProject || "");
        switchAllianceTab(page, key, highlight);
        return;
      }

      const applyFocus = ev.target.closest("[data-alliance-visitor-apply-focus]");
      if (applyFocus) {
        ev.preventDefault();
        const box = document.getElementById("alliance-visitor-apply");
        const ta = box?.querySelector("[data-alliance-detail-message]");
        box?.scrollIntoView({ behavior: "smooth", block: "nearest" });
        ta?.focus?.();
        return;
      }

      const submitBtn = ev.target.closest("[data-alliance-submit]");
      if (submitBtn) {
        ev.preventDefault();
        const form = submitBtn.closest("form");
        if (!form) return;
        const action = String(submitBtn.dataset.allianceSubmit || form.dataset.allianceAction || "");
        if (action === "create") {
          await allianceHandleCreate(form);
          return;
        }
        if (action === "join") {
          await allianceHandleJoin(form);
          return;
        }
        if (action === "description") {
          const fd = new FormData(form);
          const out = await allianceAction(
            "/api/alliance/description",
            { description: String(fd.get("description") || "") },
            "alliance_description"
          );
          if (out?.ok) showNotify(t("alliance_saved", "Gespeichert."), "success");
          else showNotify(allianceErrorMessage(out, "Speichern fehlgeschlagen"), "error");
          return;
        }
        if (action === "profile") {
          const fd = new FormData(form);
          const out = await allianceAction(
            "/api/alliance/profile",
            {
              tag: String(fd.get("tag") || "").trim(),
              name: String(fd.get("name") || "").trim(),
              description: String(fd.get("description") || ""),
            },
            "alliance_profile"
          );
          if (out?.ok) {
            showNotify(t("alliance_saved", "Gespeichert."), "success");
            await allianceFinalizeSuccess("alliance_profile", out);
          } else {
            showNotify(allianceErrorMessage(out, "Speichern fehlgeschlagen"), "error");
          }
          return;
        }
        if (action === "diplomacy") {
          const fd = new FormData(form);
          const out = await allianceAction(
            "/api/alliance/diplomacy/send",
            {
              tag: String(fd.get("tag") || "").trim(),
              request_type: String(fd.get("request_type") || ""),
            },
            "alliance_diplomacy"
          );
          if (out?.ok) await allianceFinalizeSuccess("alliance_diplomacy", out);
          else showNotify(allianceErrorMessage(out, "Diplomatie fehlgeschlagen"), "error");
          return;
        }
      }

      const donateMaxBtn = ev.target.closest("[data-donate-max]");
      if (donateMaxBtn) {
        ev.preventDefault();
        const res = donateMaxBtn.dataset.donateMax;
        const input = page.querySelector(`[data-donate-amount="${res}"]`);
        if (!input || input.disabled) return;
        const maxVal = Number(input.dataset.inputMax || 0);
        if (maxVal > 0) setNumberInputValue(input, maxVal);
        return;
      }

      const donateBtn = ev.target.closest("[data-donate-btn]");
      if (donateBtn) {
        ev.preventDefault();
        const res = donateBtn.dataset.donateBtn;
        const input = page.querySelector(`[data-donate-amount="${res}"]`);
        const amount = readNumberInput(input);
        if (!amount) return;
        const out = await allianceAction(
          "/api/alliance/donate",
          { resource: res, amount },
          "alliance_donate"
        );
        if (!out?.ok) showNotify(allianceErrorMessage(out, "Spende fehlgeschlagen"), "error");
        else {
          if (input) setNumberInputValue(input, 0);
          showNotify(t("alliance_donate_ok", "Spende eingegangen."), "success");
        }
        return;
      }

      const startBtn = ev.target.closest("[data-start-project]");
      if (startBtn) {
        ev.preventDefault();
        const parts = String(startBtn.dataset.startProject || "").split(":");
        if (parts.length !== 2) return;
        const out = await allianceAction(
          "/api/alliance/project/start",
          { kind: parts[0], key: parts[1] },
          "alliance_project_start"
        );
        if (out?.ok) await allianceFinalizeSuccess("alliance_project_start", out);
        else showNotify(allianceErrorMessage(out, "Projektstart fehlgeschlagen"), "error");
        return;
      }

      const leaveBtn = ev.target.closest("[data-alliance-leave]");
      if (leaveBtn) {
        ev.preventDefault();
        const out = await allianceAction("/api/alliance/leave", {}, "alliance_leave");
        if (out?.ok) await allianceFinalizeSuccess("alliance_leave", out);
        else showNotify(allianceErrorMessage(out, "Verlassen fehlgeschlagen"), "error");
        return;
      }

      const disbandBtn = ev.target.closest("[data-alliance-disband]");
      if (disbandBtn) {
        ev.preventDefault();
        const ok = window.confirm(
          t("alliance_disband_confirm", "Allianz wirklich auflösen? Dies kann nicht rückgängig gemacht werden.")
        );
        if (!ok) return;
        const out = await allianceAction("/api/alliance/disband", {}, "alliance_disband");
        if (out?.ok) await allianceFinalizeSuccess("alliance_disband", out);
        else showNotify(allianceErrorMessage(out, "Auflösen fehlgeschlagen"), "error");
        return;
      }

      const recruitBtn = ev.target.closest("[data-recruitment-mode]");
      if (recruitBtn) {
        ev.preventDefault();
        const mode = String(recruitBtn.dataset.recruitmentMode || "");
        const out = await allianceAction("/api/alliance/recruitment", { mode }, "alliance_recruitment");
        if (out?.ok) {
          showNotify(t("alliance_saved", "Gespeichert."), "success");
          await allianceFinalizeSuccess("alliance_recruitment", out);
        } else {
          showNotify(allianceErrorMessage(out, "Speichern fehlgeschlagen"), "error");
        }
        return;
      }

      const memberAction = (url, body, reason) => allianceAction(url, body, reason);

      const roleBtn = ev.target.closest("[data-member-role]");
      if (roleBtn) {
        ev.preventDefault();
        const parts = String(roleBtn.dataset.memberRole || "").split(":");
        if (parts.length !== 2) return;
        const pid = parseInt(parts[0], 10);
        const role = parts[1];
        if (!pid || !role) return;
        const out = await memberAction(
          "/api/alliance/member/role",
          { player_id: pid, role },
          "alliance_member_role"
        );
        if (out?.ok) await allianceFinalizeSuccess("alliance_member_role", out);
        else showNotify(allianceErrorMessage(out, "Aktion fehlgeschlagen"), "error");
        return;
      }

      const kickBtn = ev.target.closest("[data-member-kick]");
      if (kickBtn) {
        ev.preventDefault();
        const pid = parseInt(kickBtn.dataset.memberKick || "0", 10);
        if (!pid) return;
        const out = await memberAction(
          "/api/alliance/member/kick",
          { player_id: pid },
          "alliance_member_kick"
        );
        if (out?.ok) await allianceFinalizeSuccess("alliance_member_kick", out);
        else showNotify(allianceErrorMessage(out, "Aktion fehlgeschlagen"), "error");
        return;
      }

      const transferBtn = ev.target.closest("[data-member-transfer]");
      if (transferBtn) {
        ev.preventDefault();
        const pid = parseInt(transferBtn.dataset.memberTransfer || "0", 10);
        if (!pid) return;
        const ok = window.confirm(
          t("alliance_transfer_confirm", "Leadership wirklich übertragen?")
        );
        if (!ok) return;
        const out = await memberAction(
          "/api/alliance/leader/transfer",
          { player_id: pid },
          "alliance_leader_transfer"
        );
        if (out?.ok) await allianceFinalizeSuccess("alliance_leader_transfer", out);
        else showNotify(allianceErrorMessage(out, "Aktion fehlgeschlagen"), "error");
        return;
      }

      const browseOpen = ev.target.closest("[data-alliance-browse-open]");
      if (browseOpen) {
        const href = browseOpen.getAttribute("href");
        if (href && typeof GC.navigateTo === "function") {
          ev.preventDefault();
          await GC.navigateTo(href, { push: true });
        }
        return;
      }

      const detailApply = ev.target.closest("[data-alliance-detail-apply]");
      if (detailApply) {
        ev.preventDefault();
        const aid = parseInt(detailApply.dataset.allianceDetailApply || "0", 10);
        if (!aid) return;
        const ta = page.querySelector("[data-alliance-detail-message]");
        const message = String(ta?.value || "").trim();
        if (!message) {
          showNotify(t("alliance_err_message_required", "Bitte eine Bewerbungsnachricht eingeben."), "error");
          return;
        }
        const out = await allianceAction(
          "/api/alliance/apply",
          { alliance_id: aid, message },
          "alliance_apply"
        );
        if (!out?.ok) {
          showNotify(allianceErrorMessage(out, "Bewerbung fehlgeschlagen"), "error");
          return;
        }
        showNotify(t("alliance_apply_sent", "Bewerbung gesendet."), "success");
        await allianceFinalizeSuccess("alliance_apply", out);
        return;
      }

      const detailJoin = ev.target.closest("[data-alliance-detail-join]");
      if (detailJoin) {
        ev.preventDefault();
        const tag = String(detailJoin.dataset.allianceDetailJoin || "").trim();
        if (!tag) return;
        const out = await allianceAction("/api/alliance/join", { tag }, "alliance_join");
        if (out?.ok && out?.alliance?.in_alliance) {
          await allianceFinalizeSuccess("alliance_join", out);
          showNotify(t("alliance_join_success", "Allianz beigetreten."), "success");
        } else {
          showNotify(allianceErrorMessage(out, "Beitritt fehlgeschlagen"), "error");
        }
        return;
      }

      const withdrawBtn = ev.target.closest("[data-alliance-withdraw]");
      if (withdrawBtn) {
        ev.preventDefault();
        const out = await allianceAction(
          "/api/alliance/application/withdraw",
          {},
          "alliance_withdraw"
        );
        if (!out?.ok) {
          showNotify(allianceErrorMessage(out, "Zurückziehen fehlgeschlagen"), "error");
          return;
        }
        showNotify(t("alliance_withdraw_ok", "Bewerbung zurückgezogen."), "success");
        await allianceFinalizeSuccess("alliance_withdraw", out);
        return;
      }

      const applyBtn = ev.target.closest("[data-alliance-apply]");
      if (applyBtn) {
        ev.preventDefault();
        const aid = parseInt(applyBtn.dataset.allianceApply || "0", 10);
        if (!aid) return;
        const out = await allianceAction("/api/alliance/apply", { alliance_id: aid }, "alliance_apply");
        if (!out?.ok) showNotify(allianceErrorMessage(out, "Bewerbung fehlgeschlagen"), "error");
        else {
          showNotify(t("alliance_apply_sent", "Bewerbung gesendet."), "success");
          await allianceFinalizeSuccess("alliance_apply", out);
        }
        return;
      }

      const appAccept = ev.target.closest("[data-app-accept]");
      if (appAccept) {
        ev.preventDefault();
        const id = parseInt(appAccept.dataset.appAccept || "0", 10);
        const out = await allianceAction(
          "/api/alliance/application/respond",
          { application_id: id, accept: true },
          "alliance_application"
        );
        await allianceFinalizeSuccess("alliance_application", out);
        return;
      }
      const appDecline = ev.target.closest("[data-app-decline]");
      if (appDecline) {
        ev.preventDefault();
        const id = parseInt(appDecline.dataset.appDecline || "0", 10);
        const out = await allianceAction(
          "/api/alliance/application/respond",
          { application_id: id, accept: false },
          "alliance_application"
        );
        await allianceFinalizeSuccess("alliance_application", out);
        return;
      }

      const dipAccept = ev.target.closest("[data-dip-accept]");
      if (dipAccept) {
        ev.preventDefault();
        const id = parseInt(dipAccept.dataset.dipAccept || "0", 10);
        const out = await allianceAction(
          "/api/alliance/diplomacy/respond",
          { request_id: id, accept: true },
          "alliance_diplomacy_respond"
        );
        await allianceFinalizeSuccess("alliance_diplomacy_respond", out);
        return;
      }
      const dipDecline = ev.target.closest("[data-dip-decline]");
      if (dipDecline) {
        ev.preventDefault();
        const id = parseInt(dipDecline.dataset.dipDecline || "0", 10);
        const out = await allianceAction(
          "/api/alliance/diplomacy/respond",
          { request_id: id, accept: false },
          "alliance_diplomacy_respond"
        );
        await allianceFinalizeSuccess("alliance_diplomacy_respond", out);
        return;
      }

      const tab = ev.target.closest("[data-alliance-tab]");
      if (tab) {
        ev.preventDefault();
        switchAllianceTab(page, String(tab.dataset.allianceTab || ""));
        return;
      }
    });
  }

  function switchAllianceTab(page, key, highlightProjectKey) {
    if (!page || !key) return;
    const tabBtn = page.querySelector(`[data-alliance-tab="${key}"]`);
    page.querySelectorAll(".alliance-hub-tab, .alliance-tab").forEach((t) =>
      t.classList.toggle("is-active", t === tabBtn)
    );
    page.querySelectorAll("[data-alliance-panel]").forEach((p) => {
      const show = p.dataset.alliancePanel === key;
      p.hidden = !show;
      p.classList.toggle("is-active", show);
    });
    if (highlightProjectKey) {
      requestAnimationFrame(() => {
        const card = page.querySelector(`[data-project-key="${highlightProjectKey}"]`);
        if (!card) return;
        card.scrollIntoView({ behavior: "smooth", block: "nearest" });
        card.classList.add("alliance-hub-project-card--highlight");
        window.setTimeout(() => card.classList.remove("alliance-hub-project-card--highlight"), 2400);
      });
    }
  }

  function initAlliance() {
    bindAllianceOnce();
    const page = document.getElementById("alliance-page");
    if (!page || page.dataset.ready !== "1") return;
    bindFormattedNumberInputs(page);
    const path = (window.location.pathname || "").replace(/\/$/, "") || "/";
    const onVisitor = page.hasAttribute("data-alliance-visitor") || /^\/alliance\/\d+$/.test(path);
    if (!onVisitor && window.history?.replaceState && window.location.search) {
      window.history.replaceState(null, "", "/alliance");
    }
    const state = parseAlliancePageState();
    if (state) patchAllianceDom(state);
    GC.registerCleanup(() => {
      const manageDlg = document.getElementById("alliance-manage-modal");
      if (manageDlg?.open) manageDlg.close();
      const broadcastDlg = document.getElementById("alliance-broadcast-modal");
      if (broadcastDlg?.open) broadcastDlg.close();
    });
    const proj = page.querySelector("[data-alliance-active-project]");
    if (proj) {
      updateAllianceProjectProgress(proj);
      const tick = () => {
        if (!document.getElementById("alliance-page")) return;
        updateAllianceProjectProgress(proj);
      };
      const id = setInterval(tick, 1000);
      GC.registerCleanup(() => clearInterval(id));
    }
  }

  function debugDirectiveDomMutation(label) {
    if (!_imperialDirectivesDebugEnabled()) return;
    const page = document.getElementById("imperial-directives-page");
    if (!page) return;
    const cards = page.querySelectorAll("[data-directive-card]");
    console.debug("[GC] directive DOM", label, {
      cards: cards.length,
      titledCards: page.querySelectorAll("[data-directive-card] .inventory-loot-card-name").length,
      htmlLength: page.innerHTML.length,
      text: page.innerText.slice(0, 500),
    });
  }

  function watchImperialDirectiveMutations() {
    if (!_imperialDirectivesDebugEnabled()) return;
    const page = document.getElementById("imperial-directives-page");
    if (!page || page.__directiveMutationWatch) return;
    page.__directiveMutationWatch = true;
    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.type === "childList" && (m.removedNodes.length || m.addedNodes.length)) {
          console.warn("[GC] directive DOM mutated", {
            target: m.target,
            added: m.addedNodes.length,
            removed: m.removedNodes.length,
          });
          console.trace("[GC] directive mutation trace");
        }
      }
    });
    observer.observe(page, { childList: true, subtree: true });
    GC.registerCleanup(() => observer.disconnect());
  }

  function _imperialDirectivesDebugEnabled() {
    return Boolean(window.GC_PERF_DEBUG || window.GC_CLIENT_CONFIG?.directive_debug);
  }

  function _logImperialDirectivesRender(source, payload, opts) {
    if (!_imperialDirectivesDebugEnabled()) return;
    console.log("[GC] imperial directives render", source, {
      reason: opts && opts.reason,
      force: Boolean(opts && opts.force),
      ready: payload && payload.ready,
      directiveCount: Array.isArray(payload?.directives) ? payload.directives.length : null,
      hasSummaryOnly: Boolean(payload && !Array.isArray(payload.directives)),
      payload,
    });
    console.trace("[GC] imperial directives render stack");
  }

  function _imperialDirectiveCardReady(d) {
    if (!d || typeof d !== "object") return false;
    const labelKey = String(d.title_key || d.description_key || d.definition_key || "").trim();
    if (!labelKey) return false;
    if (!Number.isFinite(Number(d.target)) || Number(d.target) < 1) return false;
    if (!Array.isArray(d.rewards_preview) || !d.rewards_preview.length) return false;
    return true;
  }

  function _imperialDirectivesStateUsable(state) {
    if (!state || state.ready === false) return false;
    const directives = Array.isArray(state.directives) ? state.directives : [];
    if (!directives.length) return false;
    const daily = directives.filter((d) => String(d.cadence) === "daily");
    const weekly = directives.filter((d) => String(d.cadence) === "weekly");
    if (!daily.length && !weekly.length) return false;
    return directives.every(_imperialDirectiveCardReady);
  }

  function _imperialDirectivesHasSsrCards(page) {
    if (!page) return false;
    return page.querySelectorAll("[data-directive-card] .inventory-loot-card-name").length > 0;
  }

  function _patchImperialDirectivesFromGameStateSummary(summary, reason) {
    void reason;
    const page = document.getElementById("imperial-directives-page");
    if (!page || !summary || summary.ready === false) return;
    _logImperialDirectivesRender("game-state-summary", summary, { reason });
    if (Array.isArray(summary.directives)) {
      return;
    }
    _patchImperialDirectivesMeta(page, summary);
    _syncImperialDirectiveCountdowns(page);
  }

  async function refreshImperialDirectivesFullState(reason) {
    const page = document.getElementById("imperial-directives-page");
    if (!page || page.dataset.ready !== "1") return null;
    try {
      const data = await GC.fetchJSON("/api/imperial-directives/state", { cache: "no-store" });
      if (!data?.ok || !data.imperial_directives) return null;
      _logImperialDirectivesRender("full-state-endpoint", data.imperial_directives, { reason, force: true });
      if (_imperialDirectivesStateUsable(data.imperial_directives)) {
        patchImperialDirectivesDom(data.imperial_directives, { force: true, reason: "full_state_fetch" });
      }
      return data.imperial_directives;
    } catch (_) {
      return null;
    }
  }

  function _patchImperialDirectivesMeta(page, state) {
    if (!page || !state) return;
    const claimable = Math.max(0, Number(state.claimable_count) || 0);
    const claimableEl = page.querySelector("[data-id-claimable-count]");
    if (claimableEl) claimableEl.textContent = String(claimable);
    const claimAllBtn = page.querySelector("[data-directive-claim-all]");
    if (claimAllBtn) claimAllBtn.disabled = claimable <= 0;

    const dailyReset = page.querySelector("[data-id-daily-reset]");
    if (dailyReset && state.daily_reset_at) {
      dailyReset.dataset.ts = String(state.daily_reset_at);
    }
    const weeklyReset = page.querySelector("[data-id-weekly-reset]");
    if (weeklyReset && state.weekly_reset_at) {
      weeklyReset.dataset.ts = String(state.weekly_reset_at);
    }
  }

  function parseImperialDirectivesPageState() {
    const el = document.getElementById("imperial-directives-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function _idCategoryLabel(category) {
    const key = `imperial_directives_category_${String(category || "")}`;
    return t(key, String(category || "").replace(/_/g, " "));
  }

  function _idRarityLabel(rarity) {
    const r = String(rarity || "common");
    return t(`inv_rarity_${r}`, t(`imperial_directives_rarity_${r}`, r.charAt(0).toUpperCase() + r.slice(1)));
  }

  function _idPrimaryReward(rewards) {
    const list = Array.isArray(rewards) ? rewards : [];
    return list.find((r) => String(r.item_type || "") === "container") || list[0] || null;
  }

  function _idBoosterRewards(rewards) {
    const list = Array.isArray(rewards) ? rewards : [];
    const primary = _idPrimaryReward(list);
    if (!primary) return list.slice(1);
    return list.filter((r) => r !== primary);
  }

  function _idDirectiveCardHtml(d) {
    const id = Number(d.id || 0);
    const status = String(d.status || "active");
    const rarity = String(d.rarity || "common");
    const cadence = String(d.cadence || "daily");
    const progress = Math.max(0, Number(d.progress) || 0);
    const target = Math.max(1, Number(d.target) || 1);
    const pct = Math.min(100, Math.round((progress / target) * 100));
    const cardState = d.claimable || status === "completed" ? "completed" : status;
    const title = escapeHtml(t(d.title_key, d.definition_key || ""));
    const desc = escapeHtml(tf(d.description_key, { target: fmtNumber(target) }, d.definition_key || ""));
    const fallback = "/static/img/lootboxes/Generic_Supply_Container.webp";
    const hero = _idPrimaryReward(d.rewards_preview);
    const heroImg = hero?.image ? `/static/${String(hero.image).replace(/^\/+/, "")}` : fallback;
    const heroAlt = escapeHtml(t(hero?.name_key, hero?.item_key || ""));
    const boosters = _idBoosterRewards(d.rewards_preview);
    const boosterHtml = boosters.map((reward) => {
      const img = reward.image ? `/static/${String(reward.image).replace(/^\/+/, "")}` : fallback;
      const name = t(reward.name_key, reward.item_key || "");
      return `<div class="id-directive-loot-chip" title="${escapeHtml(name)}">
        <img class="id-directive-loot-chip__img" src="${escapeHtml(img)}" alt="" width="32" height="32" loading="lazy">
        <span class="id-directive-loot-chip__amt gc-mono">×${escapeHtml(fmtNumber(reward.amount || 1))}</span>
      </div>`;
    }).join("");
    const weeklyTag = cadence === "weekly"
      ? `<span class="id-directive-card__cadence-tag">${escapeHtml(t("imperial_directives_weekly_badge", "Weekly"))}</span>`
      : "";
    let actionHtml = "";
    if (d.claimable || status === "completed") {
      actionHtml = `<button type="button" class="gc-btn gc-btn-primary gc-btn-sm id-directive-card__claim-btn" data-directive-claim="${id}">${escapeHtml(t("imperial_directives_claim_btn", "Claim reward"))}</button>`;
    } else if (status === "claimed") {
      actionHtml = `<span class="id-directive-card__claimed-badge">${escapeHtml(t("imperial_directives_claimed_badge", "Claimed"))}</span>`;
    } else {
      actionHtml = `<span class="id-directive-card__active-hint">${escapeHtml(t("imperial_directives_active_hint", "Progress through normal gameplay"))}</span>`;
    }
    const expires = Number(d.expires_at || 0);
    return `<article class="id-directive-card inventory-loot-card id-directive-card--${escapeHtml(cardState)}"
         data-directive-card
         data-directive-id="${id}"
         data-directive-status="${escapeHtml(status)}"
         data-directive-expires-at="${expires}"
         data-rarity="${escapeHtml(rarity)}">
      <div class="id-directive-card__tag-row">
        <span class="id-directive-card__category-tag">${escapeHtml(_idCategoryLabel(d.category))}</span>
        ${weeklyTag}
      </div>
      <div class="inventory-loot-card-hero id-directive-card__hero">
        <div class="inventory-loot-card-glow inventory-loot-card-glow--${escapeHtml(rarity)}" aria-hidden="true"></div>
        <img src="${escapeHtml(heroImg)}" alt="${heroAlt}" class="inventory-loot-card-img" width="168" height="168" loading="lazy" onerror="this.onerror=null;this.src='${fallback}';">
        <span class="id-directive-card__pct gc-mono" data-directive-pct>${pct}%</span>
      </div>
      <div class="inventory-loot-card-body id-directive-card__body">
        <div class="inventory-loot-card-head">
          <h3 class="inventory-loot-card-name id-directive-card__title">${title}</h3>
          <span class="inventory-rarity-badge inventory-rarity-badge--${escapeHtml(rarity)}">${escapeHtml(_idRarityLabel(rarity))}</span>
        </div>
        <p class="inventory-loot-card-hint id-directive-card__desc">${desc}</p>
        <div class="id-directive-card__progress" role="progressbar" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${progress}">
          <div class="id-directive-card__progress-fill gc-progress-smooth" data-directive-progress-fill style="width:${pct}%;"></div>
        </div>
        <div class="id-directive-card__progress-meta">
          <span class="id-directive-card__progress-label gc-mono" data-directive-progress-label>${escapeHtml(fmtNumber(progress))} / ${escapeHtml(fmtNumber(target))}</span>
          <span class="id-directive-card__expires gc-mono" data-directive-expires-label>${expires > 0 ? `${escapeHtml(t("imperial_directives_expires_in", "Expires in"))} …` : ""}</span>
        </div>
        ${boosterHtml ? `<div class="id-directive-card__loot-row">${boosterHtml}</div>` : ""}
      </div>
      <div class="inventory-loot-card-actions id-directive-card__actions">
        ${actionHtml}
      </div>
    </article>`;
  }

  let _idCountdownTimer = null;

  function _syncImperialDirectiveCountdowns(page) {
    if (!page) return;
    debugDirectiveDomMutation("countdown:before");
    const now = getTimerServerNow();
    page.querySelectorAll("[data-directive-expires-label]").forEach((label) => {
      const card = label.closest("[data-directive-card]");
      const expires = Number(card?.getAttribute("data-directive-expires-at") || 0);
      if (!expires) {
        return;
      }
      if (expires <= now) {
        label.textContent = t("imperial_directives_reset_now", "Soon");
        return;
      }
      const rem = Math.max(0, Math.ceil(expires - now));
      label.textContent = `${t("imperial_directives_expires_in", "Expires in")} ${formatCountdownRemain(rem)}`;
    });
    page.querySelectorAll("[data-id-daily-reset]").forEach((el) => {
      const ts = Number(el.dataset.ts || el.getAttribute("data-ts") || 0);
      if (ts > now) el.textContent = formatCountdownRemain(Math.ceil(ts - now));
      else if (ts > 0) el.textContent = t("imperial_directives_reset_now", "Soon");
    });
    page.querySelectorAll("[data-id-weekly-reset]").forEach((el) => {
      const ts = Number(el.dataset.ts || el.getAttribute("data-ts") || 0);
      if (ts > now) el.textContent = formatCountdownRemain(Math.ceil(ts - now));
      else if (ts > 0) el.textContent = t("imperial_directives_reset_now", "Soon");
    });
    debugDirectiveDomMutation("countdown:after");
  }

  function patchImperialDirectivesDom(state, opts) {
    const page = document.getElementById("imperial-directives-page");
    if (!page || !state || state.ready === false) return;

    debugDirectiveDomMutation("patch-dom:before");
    const reason = opts && opts.reason ? String(opts.reason) : "unknown";
    const force = Boolean(opts && opts.force);
    _logImperialDirectivesRender("patch-dom", state, { reason, force });

    if (!_imperialDirectivesStateUsable(state)) {
      _patchImperialDirectivesMeta(page, state);
      _syncImperialDirectiveCountdowns(page);
      return;
    }

    const dailyList = page.querySelector('[data-id-directive-list="daily"]');
    const weeklyList = page.querySelector('[data-id-directive-list="weekly"]');
    const directives = Array.isArray(state.directives) ? state.directives : [];
    const daily = directives.filter((d) => String(d.cadence) === "daily");
    const weekly = directives.filter((d) => String(d.cadence) === "weekly");

    if (!daily.length && !weekly.length) {
      _patchImperialDirectivesMeta(page, state);
      _syncImperialDirectiveCountdowns(page);
      return;
    }

    if (!force && _imperialDirectivesHasSsrCards(page)) {
      _patchImperialDirectivesMeta(page, state);
      _syncImperialDirectiveCountdowns(page);
      const scriptEl = document.getElementById("imperial-directives-page-state");
      if (scriptEl) scriptEl.textContent = JSON.stringify(state);
      return;
    }

    if (dailyList && daily.length) dailyList.innerHTML = daily.map(_idDirectiveCardHtml).join("");
    if (weeklyList && weekly.length) weeklyList.innerHTML = weekly.map(_idDirectiveCardHtml).join("");

    _patchImperialDirectivesMeta(page, state);

    const scriptEl = document.getElementById("imperial-directives-page-state");
    if (scriptEl) scriptEl.textContent = JSON.stringify(state);
    _syncImperialDirectiveCountdowns(page);
    debugDirectiveDomMutation("patch-dom:after");
  }

  let _imperialDirectivesBound = false;

  function bindImperialDirectivesOnce() {
    if (_imperialDirectivesBound) return;
    _imperialDirectivesBound = true;

    document.addEventListener("click", async (ev) => {
      const claimBtn = ev.target.closest("[data-directive-claim]");
      if (claimBtn) {
        const directiveId = Number(claimBtn.getAttribute("data-directive-claim") || 0);
        if (!directiveId) return;
        const res = await GC.fetchGameAction("/api/imperial-directives/claim", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ directive_id: directiveId, request_id: newRequestId() }),
        });
        if (res?.state) applyActionState(res, "imperial_directive_claim");
        if (res?.imperial_directives) {
          patchImperialDirectivesDom(res.imperial_directives, { force: true, reason: "claim" });
        }
        if (res?.ok) {
          showNotify(t("imperial_directives_claim_ok", "Reward added to inventory."), "success");
        } else {
          showNotify(t("imperial_directives_claim_fail", "Could not claim reward."), "error");
        }
        return;
      }

      const claimAllBtn = ev.target.closest("[data-directive-claim-all]");
      if (claimAllBtn) {
        const res = await GC.fetchGameAction("/api/imperial-directives/claim-all", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ request_id: newRequestId() }),
        });
        if (res?.state) applyActionState(res, "imperial_directive_claim_all");
        if (res?.imperial_directives) {
          patchImperialDirectivesDom(res.imperial_directives, { force: true, reason: "claim" });
        }
        if (res?.ok) {
          const count = Number(res?.claim?.count || 0);
          showNotify(
            count > 0
              ? tf("imperial_directives_claim_all_ok", { count: fmtNumber(count) }, "Rewards claimed.")
              : t("imperial_directives_claim_all_ok", "Rewards claimed."),
            "success",
          );
        } else {
          showNotify(t("imperial_directives_claim_all_fail", "Could not claim rewards."), "error");
        }
      }
    });
  }

  function initImperialDirectives() {
    bindImperialDirectivesOnce();
    debugDirectiveDomMutation("init:start");
    watchImperialDirectiveMutations();
    const page = document.getElementById("imperial-directives-page");
    if (!page || page.dataset.ready !== "1") return;
    resyncServerTimeFromDom(true);
    const state = parseImperialDirectivesPageState();
    debugDirectiveDomMutation("init:after-ssr-state-parse");
    const hasSsrCards = _imperialDirectivesHasSsrCards(page);
    if (state) _patchImperialDirectivesMeta(page, state);
    _syncImperialDirectiveCountdowns(page);
    if (!hasSsrCards) {
      void refreshImperialDirectivesFullState("page_init");
    }
    debugDirectiveDomMutation("init:done");
    if (_idCountdownTimer) clearInterval(_idCountdownTimer);
    _idCountdownTimer = setInterval(() => {
      const live = document.getElementById("imperial-directives-page");
      if (live) _syncImperialDirectiveCountdowns(live);
    }, 1000);
    GC.registerCleanup(() => {
      if (_idCountdownTimer) {
        clearInterval(_idCountdownTimer);
        _idCountdownTimer = null;
      }
    });
  }

  function parseStoryOpsPageState() {
    const el = document.getElementById("story-ops-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function _storyContactLabel(key) {
    if (key === "androgyn") return t("story_contact_androgyn", "Androgyn Echo");
    return t("story_contact_ark", "Genesis Ark");
  }

  const STORY_TTS_LS_KEY = "gc_story_tts_v1";
  const STORY_FOCUS_KEY = "gc_story_focus_v1";
  const STORY_TTS_AUTO_DEBOUNCE_MS = 350;
  let _storyTtsUtterance = null;
  let _storyTtsLastFingerprint = "";
  let _storyAudio = null;
  let _storyAudioUrl = null;
  let _storyTtsSpeakTimer = null;
  let _storyTtsSession = 0;
  let _storyTtsAbort = null;
  let _storyFocus = { pack_id: "", arc_id: "" };

  function _storyFocusLoad() {
    try {
      const raw = localStorage.getItem(STORY_FOCUS_KEY);
      if (!raw) return { pack_id: "", arc_id: "" };
      const p = JSON.parse(raw);
      return { pack_id: String(p.pack_id || ""), arc_id: String(p.arc_id || "") };
    } catch (_) {
      return { pack_id: "", arc_id: "" };
    }
  }

  function _storyFocusSave(packId, arcId) {
    _storyFocus = { pack_id: String(packId || ""), arc_id: String(arcId || "") };
    try { localStorage.setItem(STORY_FOCUS_KEY, JSON.stringify(_storyFocus)); } catch (_) {}
  }

  function _storyTtsLoadPrefs() {
    try {
      const raw = localStorage.getItem(STORY_TTS_LS_KEY);
      if (!raw) return { volume: 0.85, auto: false };
      const parsed = JSON.parse(raw);
      return {
        volume: Math.max(0, Math.min(1, Number(parsed.volume) || 0.85)),
        auto: parsed.auto === true,
      };
    } catch (_) {
      return { volume: 0.85, auto: false };
    }
  }

  function _storyTtsSavePrefs(prefs) {
    try { localStorage.setItem(STORY_TTS_LS_KEY, JSON.stringify(prefs)); } catch (_) {}
  }

  function _storyNeuralEnabled(page) {
    const el = page || document.getElementById("story-ops-page");
    if (el && el.dataset.ttsNeural === "1") return true;
    try {
      const st = parseStoryOpsPageState();
      return !!(st && st.tts && st.tts.neural);
    } catch (_) {
      return false;
    }
  }

  function _storyOrbEl() {
    return document.querySelector("#story-ops-page [data-story-orb]");
  }

  function _storyOrbSetState(state) {
    const orb = _storyOrbEl();
    if (!orb) return;
    orb.classList.toggle("is-speaking", state === "speaking");
    orb.classList.toggle("is-paused", state === "paused");
  }

  function _storyTtsStop() {
    _storyTtsSession += 1;
    if (_storyTtsSpeakTimer) {
      clearTimeout(_storyTtsSpeakTimer);
      _storyTtsSpeakTimer = null;
    }
    if (_storyTtsAbort) {
      try { _storyTtsAbort.abort(); } catch (_) {}
      _storyTtsAbort = null;
    }
    if (_storyAudio) {
      try { _storyAudio.pause(); } catch (_) {}
      try { _storyAudio.src = ""; } catch (_) {}
      _storyAudio = null;
    }
    if (_storyAudioUrl) {
      try { URL.revokeObjectURL(_storyAudioUrl); } catch (_) {}
      _storyAudioUrl = null;
    }
    if (typeof window !== "undefined" && "speechSynthesis" in window) {
      try { window.speechSynthesis.cancel(); } catch (_) {}
    }
    _storyTtsUtterance = null;
    _storyOrbSetState("idle");
  }

  function _storyTtsPause() {
    if (_storyAudio) {
      try { _storyAudio.pause(); } catch (_) {}
      _storyOrbSetState("paused");
      return;
    }
    if ("speechSynthesis" in window) {
      try { if (window.speechSynthesis.speaking) window.speechSynthesis.pause(); } catch (_) {}
      _storyOrbSetState("paused");
    }
  }

  function _storyTtsResume() {
    if (_storyAudio) {
      try { _storyAudio.play(); } catch (_) {}
      _storyOrbSetState("speaking");
      return;
    }
    if ("speechSynthesis" in window) {
      try { if (window.speechSynthesis.paused) window.speechSynthesis.resume(); } catch (_) {}
      _storyOrbSetState("speaking");
    }
  }

  function _storyTtsIsAbortError(err) {
    if (!err) return false;
    if (err.name === "AbortError") return true;
    const msg = String(err.message || err || "");
    return msg === "AbortError" || /aborted/i.test(msg);
  }

  async function _storyTtsSpeakNeural(text, volume, session) {
    const controller = new AbortController();
    _storyTtsAbort = controller;
    const res = await fetch("/api/story/tts", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Accept": "audio/mpeg,application/json" },
      body: JSON.stringify({ text }),
      credentials: "same-origin",
      signal: controller.signal,
    });
    if (session !== _storyTtsSession) return;
    const ctype = String(res.headers.get("content-type") || "");
    if (!res.ok || !ctype.includes("audio")) {
      let err = "tts_failed";
      try {
        const j = await res.json();
        err = j.error || err;
      } catch (_) {}
      throw new Error(err);
    }
    const blob = await res.blob();
    if (session !== _storyTtsSession) return;
    if (_storyAudioUrl) {
      try { URL.revokeObjectURL(_storyAudioUrl); } catch (_) {}
    }
    _storyAudioUrl = URL.createObjectURL(blob);
    const audio = new Audio(_storyAudioUrl);
    audio.volume = Math.max(0, Math.min(1, Number(volume) || 0.85));
    audio.onended = () => {
      if (session === _storyTtsSession) _storyOrbSetState("idle");
    };
    audio.onpause = () => {
      if (session !== _storyTtsSession) return;
      if (_storyAudio && !_storyAudio.ended && _storyAudio.currentTime > 0) {
        _storyOrbSetState("paused");
      }
    };
    audio.onplay = () => {
      if (session === _storyTtsSession) _storyOrbSetState("speaking");
    };
    if (session !== _storyTtsSession) {
      try { URL.revokeObjectURL(_storyAudioUrl); } catch (_) {}
      _storyAudioUrl = null;
      return;
    }
    _storyAudio = audio;
    _storyOrbSetState("speaking");
    await audio.play();
  }

  function _storyTtsSpeakBrowser(text, volume, session) {
    if (!("speechSynthesis" in window) || typeof window.SpeechSynthesisUtterance !== "function") {
      throw new Error("unsupported");
    }
    if (session !== _storyTtsSession) return;
    try { window.speechSynthesis.cancel(); } catch (_) {}
    const u = new window.SpeechSynthesisUtterance(text);
    const lang = String(document.documentElement.lang || "de").toLowerCase();
    u.lang = lang.startsWith("de") ? "de-DE" : "en-US";
    u.rate = 0.96;
    u.pitch = 0.92;
    u.volume = Math.max(0, Math.min(1, Number(volume) || 0.85));
    u.onstart = () => {
      if (session === _storyTtsSession) _storyOrbSetState("speaking");
    };
    u.onend = () => {
      if (session === _storyTtsSession) _storyOrbSetState("idle");
    };
    u.onerror = () => {
      if (session === _storyTtsSession) _storyOrbSetState("idle");
    };
    if (session !== _storyTtsSession) return;
    _storyTtsUtterance = u;
    _storyOrbSetState("speaking");
    window.speechSynthesis.speak(u);
    try { window.speechSynthesis.resume(); } catch (_) {}
  }

  async function _storyTtsSpeakText(text) {
    const raw = String(text || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
    if (!raw) {
      showNotify(t("story_tts_empty", "Kein Übertragungstext zum Vorlesen."), "error");
      return;
    }
    const prefs = _storyTtsLoadPrefs();
    _storyTtsStop();
    const session = _storyTtsSession;
    try {
      if (_storyNeuralEnabled()) {
        // Keep paragraph breaks for server prosody — do not flatten to Otto-monotone.
        await _storyTtsSpeakNeural(raw, prefs.volume, session);
        return;
      }
    } catch (err) {
      if (_storyTtsIsAbortError(err) || session !== _storyTtsSession) return;
      const code = String((err && err.message) || "");
      if (code === "edge_tts_missing" || code === "tts_timeout" || code.indexOf("tts_failed") === 0) {
        // Soft fallback — no error toast unless browser also fails.
      } else {
        // keep going to browser fallback
      }
    }
    if (session !== _storyTtsSession) return;
    try {
      _storyTtsSpeakBrowser(raw.replace(/\s+/g, " ").trim(), prefs.volume, session);
    } catch (_) {
      if (session !== _storyTtsSession) return;
      showNotify(
        t("story_tts_unsupported", "Vorlesen fehlgeschlagen. Neural-TTS braucht Netzwerk; Browser-TTS ist optional."),
        "error"
      );
    }
  }

  function _storyTtsScheduleAutoSpeak(script) {
    if (_storyTtsSpeakTimer) {
      clearTimeout(_storyTtsSpeakTimer);
      _storyTtsSpeakTimer = null;
    }
    const payload = String(script || "");
    _storyTtsSpeakTimer = setTimeout(() => {
      _storyTtsSpeakTimer = null;
      void _storyTtsSpeakText(payload);
    }, STORY_TTS_AUTO_DEBOUNCE_MS);
  }

  function _storyTtsBuildScript(title, body) {
    const t0 = String(title || "").trim();
    const b0 = String(body || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
    if (t0 && b0) return `${t0}.\n\n${b0}`;
    return t0 || b0;
  }

  function _storyTtsCurrentScript() {
    const page = document.getElementById("story-ops-page");
    if (!page) return "";
    const st = parseStoryOpsPageState();
    const beat = st && st.focus && st.focus.beat;
    if (beat && (beat.title || beat.body)) {
      return _storyTtsBuildScript(beat.title, beat.body);
    }
    const title = (page.querySelector("[data-story-title]") || {}).textContent || "";
    const bodyEl = page.querySelector("[data-story-text]");
    const body = bodyEl ? (bodyEl.innerText || bodyEl.textContent || "") : "";
    return _storyTtsBuildScript(title, body);
  }

  function _storyTtsFingerprint(state) {
    const focus = state && state.focus;
    const beat = focus && focus.beat;
    if (!beat) return "idle";
    return `${focus.pack_id || ""}:${focus.arc_id || ""}:${beat.beat_id || ""}:${beat.type || ""}`;
  }

  function _storyTtsSyncControls(page) {
    if (!page) return;
    const prefs = _storyTtsLoadPrefs();
    const vol = page.querySelector("[data-story-tts-volume]");
    const volVal = page.querySelector("[data-story-tts-volume-val]");
    const auto = page.querySelector("[data-story-tts-auto]");
    if (vol) vol.value = String(Math.round(prefs.volume * 100));
    if (volVal) volVal.textContent = `${Math.round(prefs.volume * 100)}%`;
    if (auto) auto.checked = !!prefs.auto;
    const label = page.querySelector(".story-tts__label");
    if (label) label.textContent = t("story_tts_bender_label", "Neural Contact Voice");
    [
      ["[data-story-tts-play]", "story_tts_play", "Abspielen"],
      ["[data-story-tts-pause]", "story_tts_pause", "Pause"],
      ["[data-story-tts-resume]", "story_tts_resume", "Weiter"],
      ["[data-story-tts-stop]", "story_tts_stop", "Stop"],
    ].forEach(([sel, key, fb]) => {
      const btn = page.querySelector(sel);
      if (btn) btn.textContent = t(key, fb);
    });
    const volLabel = page.querySelector(".story-tts__vol-label");
    if (volLabel) volLabel.textContent = t("story_tts_volume", "Lautstärke");
    const autoSpan = page.querySelector(".story-tts__auto span");
    if (autoSpan) autoSpan.textContent = t("story_tts_auto", "Neue Übertragungen automatisch vorlesen");
    const hint = page.querySelector("[data-story-tts-hint]");
    if (hint) {
      hint.textContent = _storyNeuralEnabled(page)
        ? t("story_tts_hint_neural", "Neurale Kontaktstimme (Killian). Natürliches Tempo, Absätze mit Pause — Kontaktkanal, kein Otto.")
        : t("story_tts_hint_missing", "Neural-TTS nicht installiert (pip install edge-tts). Fallback: Browser-Stimme.");
    }
  }

  function _renderStoryOpsState(state, opts = {}) {
    const page = document.getElementById("story-ops-page");
    if (!page || !state) return;
    const scriptEl = document.getElementById("story-ops-page-state");
    if (scriptEl) {
      try { scriptEl.textContent = JSON.stringify(state); } catch (_) {}
    }
    page.dataset.ttsNeural = (state.tts && state.tts.neural) ? "1" : "0";

    let focus = state.focus || null;
    if (_storyFocus.pack_id && _storyFocus.arc_id && Array.isArray(state.arcs)) {
      const found = state.arcs.find((a) => (
        a.pack_id === _storyFocus.pack_id
        && a.arc_id === _storyFocus.arc_id
        && a.status === "active"
      ));
      if (found) focus = found;
    }
    if (focus && focus.pack_id && focus.arc_id) {
      _storyFocusSave(focus.pack_id, focus.arc_id);
    }

    const beat = focus && focus.beat ? focus.beat : null;
    const contact = (focus && focus.contact_key) || "ark";
    const tx = page.querySelector("[data-story-tx]");
    if (tx) tx.setAttribute("data-contact", contact);
    const portrait = page.querySelector("[data-story-orb]");
    if (portrait) {
      portrait.className = `story-orb story-orb--${contact}`;
      if (_storyAudio && !_storyAudio.paused && !_storyAudio.ended) {
        portrait.classList.add("is-speaking");
      }
    }
    const contactLabel = page.querySelector("[data-story-contact-label]");
    if (contactLabel) contactLabel.textContent = _storyContactLabel(contact);
    const chapterLabel = page.querySelector("[data-story-chapter-label]");
    if (chapterLabel) chapterLabel.textContent = (focus && focus.chapter_title) || "";

    const titleEl = page.querySelector("[data-story-title]");
    const textEl = page.querySelector("[data-story-text]");
    const idle = state.idle || null;
    if (titleEl) {
      titleEl.textContent = beat
        ? (beat.title || "")
        : ((idle && idle.title) || t("story_idle_title", "Kanal ruhig"));
    }
    if (textEl) {
      textEl.textContent = beat
        ? (beat.body || "")
        : ((idle && idle.body)
          || t("story_idle_body", "Keine aktive Übertragung. Side Ops öffnen sich, wenn dein Imperium wächst."));
    }

    const progWrap = page.querySelector("[data-story-progress-wrap]");
    const prog = page.querySelector("[data-story-progress-fill]");
    const progBar = page.querySelector("[data-story-progress]");
    const progLabel = page.querySelector("[data-story-progress-label]");
    if (beat && beat.type === "objective") {
      const target = Math.max(1, Number(beat.target) || 1);
      const progress = Math.max(0, Number(beat.progress) || 0);
      if (progWrap) progWrap.hidden = false;
      if (prog) prog.style.width = `${Math.min(100, Math.floor((progress / target) * 100))}%`;
      if (progBar) {
        progBar.setAttribute("aria-valuemax", String(target));
        progBar.setAttribute("aria-valuenow", String(progress));
      }
      if (progLabel) progLabel.textContent = `${fmtNumber(progress)} / ${fmtNumber(target)}`;
    } else if (progWrap) {
      progWrap.hidden = true;
    }

    const actions = page.querySelector("[data-story-actions]");
    if (actions) {
      actions.innerHTML = "";
      if (beat && beat.type === "transmission" && focus) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "gc-btn gc-btn-primary";
        btn.setAttribute("data-story-advance", "");
        btn.setAttribute("data-pack-id", focus.pack_id || "");
        btn.setAttribute("data-arc-id", focus.arc_id || "");
        btn.textContent = beat.cta || t("story_cta_continue", "Weiter");
        actions.appendChild(btn);
      } else if (beat && beat.type === "choice" && Array.isArray(beat.choices) && focus) {
        beat.choices.forEach((ch) => {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = "gc-btn gc-btn-secondary";
          btn.setAttribute("data-story-choice", "");
          btn.setAttribute("data-pack-id", focus.pack_id || "");
          btn.setAttribute("data-arc-id", focus.arc_id || "");
          btn.setAttribute("data-choice-id", ch.id || "");
          btn.textContent = ch.label || ch.id || "";
          actions.appendChild(btn);
        });
      } else if (beat && beat.type === "objective") {
        const p = document.createElement("p");
        p.className = "story-tx__waiting hint";
        p.textContent = beat.objective_hint
          || t("story_waiting_gameplay", "Erfülle das Ziel durch normales Spielen.");
        actions.appendChild(p);
      }
    }

    const list = page.querySelector("[data-story-arc-list]");
    if (list && Array.isArray(state.arcs)) {
      list.innerHTML = "";
      if (!state.arcs.length) {
        const li = document.createElement("li");
        li.className = "story-ops-arc story-ops-arc--empty";
        li.textContent = t("story_no_arcs", "Noch keine Arcs.");
        list.appendChild(li);
      } else {
        state.arcs.forEach((arc) => {
          const li = document.createElement("li");
          const isFocus = focus && focus.pack_id === arc.pack_id && focus.arc_id === arc.arc_id;
          li.className = `story-ops-arc story-ops-arc--${arc.status || ""}${isFocus ? " is-focus" : ""}`;
          li.setAttribute("data-story-focus-arc", "");
          li.setAttribute("data-pack-id", arc.pack_id || "");
          li.setAttribute("data-arc-id", arc.arc_id || "");
          let chaptersHtml = "";
          if (Array.isArray(arc.chapters) && arc.chapters.length) {
            chaptersHtml = `<ol class="story-ops-arc__chapters">${arc.chapters.map((ch) => (
              `<li class="story-ops-ch story-ops-ch--${escapeHtml(ch.status || "")}">`
              + `<span class="story-ops-ch__mark" aria-hidden="true"></span>`
              + `<span class="story-ops-ch__title">${escapeHtml(ch.title || "")}</span></li>`
            )).join("")}</ol>`;
          }
          const seasonCode = arc.season_code || "";
          const seasonLabel = arc.season_label || seasonCode;
          const seasonHtml = seasonCode || seasonLabel
            ? `<span class="story-ops-arc__season" title="${escapeHtml(seasonLabel)}">${escapeHtml(seasonCode || seasonLabel)}</span>`
            : "";
          li.innerHTML = (
            `<div class="story-ops-arc__head">`
            + `<span class="story-ops-arc__kind">${escapeHtml(arc.kind_label || arc.kind || "")}</span>`
            + seasonHtml
            + `<span class="story-ops-arc__status">${escapeHtml(arc.status_label || arc.status || "")}</span>`
            + `</div><strong class="story-ops-arc__title">${escapeHtml(arc.title || "")}</strong>${chaptersHtml}`
          );
          list.appendChild(li);
        });
      }
    }

    _storyTtsSyncControls(page);

    const freeShop = state.free_shop || null;
    const arkBal = page.querySelector("[data-story-ark-balance]");
    if (arkBal) {
      const label = (freeShop && freeShop.label) || t("inv_ark_token", "Ark-Token");
      const bal = freeShop ? Number(freeShop.balance) || 0 : 0;
      arkBal.innerHTML = `${escapeHtml(t("free_shop_balance", "Bestand"))}: <strong>${fmtNumber(bal)}</strong> ${escapeHtml(label)}`;
    }

    const fp = _storyTtsFingerprint({ focus });
    const prefs = _storyTtsLoadPrefs();
    const fpChanged = fp !== _storyTtsLastFingerprint;
    const shouldAuto = opts.forceSpeak
      || (!opts.skipAutoSpeak
        && prefs.auto
        && beat
        && (beat.type === "transmission" || beat.type === "choice")
        && fpChanged);
    // Focus/beat change: kill leftover audio immediately (tabbing must not stack voices).
    if (fpChanged) {
      _storyTtsStop();
    }
    _storyTtsLastFingerprint = fp;
    if (shouldAuto) {
      const script = _storyTtsBuildScript(beat.title, beat.body);
      if (opts.forceSpeak) {
        void _storyTtsSpeakText(script);
      } else {
        _storyTtsScheduleAutoSpeak(script);
      }
    }
  }

  let _storyOpsBound = false;
  function bindStoryOpsOnce() {
    if (_storyOpsBound) return;
    _storyOpsBound = true;
    document.addEventListener("click", async (ev) => {
      const page = document.getElementById("story-ops-page");
      if (!page) return;

      const focusArc = ev.target.closest("[data-story-focus-arc]");
      if (focusArc && !ev.target.closest("[data-story-advance],[data-story-choice]")) {
        const packId = focusArc.getAttribute("data-pack-id") || "";
        const arcId = focusArc.getAttribute("data-arc-id") || "";
        if (packId && arcId) {
          // Stop TTS immediately — never wait on /api/story/state or neural synth while tabbing.
          _storyTtsStop();
          _storyFocusSave(packId, arcId);
          const local = parseStoryOpsPageState();
          if (local && Array.isArray(local.arcs)) {
            const found = local.arcs.find((a) => (
              a && a.pack_id === packId && a.arc_id === arcId
            ));
            if (found) {
              const next = Object.assign({}, local, { focus: found });
              // skipAutoSpeak: tabbing must not queue edge-tts and freeze the server/UI.
              _renderStoryOpsState(next, { forceSpeak: false, skipAutoSpeak: true });
              return;
            }
          }
          try {
            const q = `pack_id=${encodeURIComponent(packId)}&arc_id=${encodeURIComponent(arcId)}`;
            const data = await GC.fetchJSON(`/api/story/state?${q}`, { cache: "no-store" });
            if (data && data.story) {
              _renderStoryOpsState(data.story, { forceSpeak: false, skipAutoSpeak: true });
            }
          } catch (_) {}
        }
        return;
      }

      if (ev.target.closest("[data-story-tts-play]")) {
        ev.preventDefault();
        void _storyTtsSpeakText(_storyTtsCurrentScript());
        return;
      }
      if (ev.target.closest("[data-story-tts-pause]")) { ev.preventDefault(); _storyTtsPause(); return; }
      if (ev.target.closest("[data-story-tts-resume]")) { ev.preventDefault(); _storyTtsResume(); return; }
      if (ev.target.closest("[data-story-tts-stop]")) { ev.preventDefault(); _storyTtsStop(); return; }

      const advanceBtn = ev.target.closest("[data-story-advance]");
      const choiceBtn = ev.target.closest("[data-story-choice]");
      if (!advanceBtn && !choiceBtn) return;
      ev.preventDefault();
      const btn = advanceBtn || choiceBtn;
      const packId = btn.getAttribute("data-pack-id") || "";
      const arcId = btn.getAttribute("data-arc-id") || "";
      _storyFocusSave(packId, arcId);
      btn.disabled = true;
      try {
        let res;
        if (advanceBtn) {
          res = await GC.fetchGameAction("/api/story/advance", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ pack_id: packId, arc_id: arcId }),
          });
        } else {
          res = await GC.fetchGameAction("/api/story/choice", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              pack_id: packId,
              arc_id: arcId,
              choice_id: btn.getAttribute("data-choice-id") || "",
            }),
          });
        }
        if (res && typeof GC.applyActionState === "function") {
          GC.applyActionState(res, advanceBtn ? "story_advance" : "story_choice");
        }
        if (res && res.ok) {
          const gained = Number(res.ark_tokens_gained) || 0;
          if (gained > 0) {
            const tmpl = t("story_ark_token_toast", "+%(amount)s Ark-Token");
            const msg = tmpl.includes("%(amount)s")
              ? tmpl.replace("%(amount)s", String(gained))
              : `+${gained} Ark-Token`;
            showNotify(msg, "success");
          }
        }
        if (res && res.story) {
          _renderStoryOpsState(res.story);
        } else if (res && res.ok) {
          const q = `pack_id=${encodeURIComponent(packId)}&arc_id=${encodeURIComponent(arcId)}`;
          const data = await GC.fetchJSON(`/api/story/state?${q}`, { cache: "no-store" });
          if (data && data.story) _renderStoryOpsState(data.story);
        } else {
          showNotify(t("story_action_fail", "Übertragung fehlgeschlagen."), "error");
        }
      } catch (_) {
        showNotify(t("story_action_fail", "Übertragung fehlgeschlagen."), "error");
      } finally {
        btn.disabled = false;
      }
    });

    document.addEventListener("input", (ev) => {
      const vol = ev.target.closest("[data-story-tts-volume]");
      if (!vol || !document.getElementById("story-ops-page")) return;
      const prefs = _storyTtsLoadPrefs();
      prefs.volume = Math.max(0, Math.min(1, (Number(vol.value) || 0) / 100));
      _storyTtsSavePrefs(prefs);
      const val = document.querySelector("[data-story-tts-volume-val]");
      if (val) val.textContent = `${Math.round(prefs.volume * 100)}%`;
      if (_storyAudio) _storyAudio.volume = prefs.volume;
      if (_storyTtsUtterance) _storyTtsUtterance.volume = prefs.volume;
    });

    document.addEventListener("change", (ev) => {
      const auto = ev.target.closest("[data-story-tts-auto]");
      if (!auto || !document.getElementById("story-ops-page")) return;
      const prefs = _storyTtsLoadPrefs();
      prefs.auto = !!auto.checked;
      _storyTtsSavePrefs(prefs);
    });
  }

  function initStoryOps() {
    bindStoryOpsOnce();
    const page = document.getElementById("story-ops-page");
    if (!page || page.dataset.ready !== "1") return;
    _storyFocus = _storyFocusLoad();
    _storyTtsSyncControls(page);
    const state = parseStoryOpsPageState();
    if (state) _renderStoryOpsState(state);
    GC.registerCleanup(() => {
      _storyTtsStop();
      _storyTtsLastFingerprint = "";
    });
  }

  function parseGalacticPoliticsPageState() {
    const el = document.getElementById("galactic-politics-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return null;
  }

  function _gdPhaseLabel(phase) {
    if (phase === "vote_open") return t("gd_politics_phase_vote", "Abstimmung");
    if (phase === "active") return t("gd_politics_phase_active", "Mandat aktiv");
    return t("gd_politics_phase_resolved", "Abgeschlossen");
  }

  function _gdCountdownPrefix(phase) {
    if (phase === "vote_open") return t("gd_politics_countdown_vote", "Abstimmung endet in");
    if (phase === "active") return t("gd_politics_countdown_active", "Mandat endet in");
    return t("gd_politics_countdown_resolved", "Zyklus beendet");
  }

  function _gdOptionCardHtml(entry, opt) {
    const key = escapeHtml(String(opt.key || ""));
    const title = escapeHtml(t(opt.label_key, key));
    const desc = escapeHtml(t(opt.description_key, ""));
    const votes = fmtNumber(Math.max(0, Number(opt.vote_count) || 0));
    const selected = Boolean(opt.selected);
    const onCooldown = Boolean(opt.on_cooldown);
    const canVote = Boolean(entry.can_vote);
    let stateClass = "";
    if (selected) stateClass = "galactic-politics-option--selected";
    if (onCooldown) stateClass += " galactic-politics-option--cooldown";
    let action = "";
    if (onCooldown) {
      action = `<p class="galactic-politics-cooldown-note">${escapeHtml(t("gd_politics_cooldown", "Gesperrt (2× Sieg in Folge)"))}</p>`;
    } else if (canVote) {
      const btnLabel = selected
        ? t("gd_politics_voted", "Deine Stimme")
        : t("gd_politics_vote_btn", "Abstimmen");
      action = `<button type="button"
        class="gc-btn gc-btn-secondary gc-btn-sm galactic-politics-vote-btn"
        data-gd-vote-btn
        data-galaxy="${Number(entry.galaxy) || 0}"
        data-directive-key="${key}"
        ${selected ? 'disabled aria-pressed="true"' : ""}>${escapeHtml(btnLabel)}</button>`;
    }
    return `
      <article class="galactic-politics-option ${stateClass.trim()}"
               data-gd-option
               data-directive-key="${key}"
               data-on-cooldown="${onCooldown ? "1" : "0"}">
        <div class="galactic-politics-option-head">
          <h3 class="galactic-politics-option-title">${title}</h3>
          <span class="galactic-politics-option-votes gc-mono" data-gd-option-votes>${votes}</span>
        </div>
        <p class="galactic-politics-option-desc hint">${desc}</p>
        ${action}
      </article>
    `;
  }

  function _gdGalaxyCardHtml(entry) {
    const galaxy = Number(entry.galaxy) || 0;
    const phase = String(entry.cycle?.phase || "resolved");
    const countdown = Math.max(0, Number(entry.cycle?.countdown_seconds) || 0);
    const primary = escapeHtml(t(entry.active?.primary_label_key, entry.active?.primary || "—"));
    const secondaryKey = entry.active?.secondary_label_key;
    const secondary = secondaryKey
      ? escapeHtml(t(secondaryKey, entry.active?.secondary || "—"))
      : "—";
    const options = Array.isArray(entry.options) ? entry.options : [];
    let note = "";
    if (entry.vote_reason === "no_colony") {
      note = `<p class="galactic-politics-note hint">${escapeHtml(t("gd_politics_no_vote_right", "Kein Stimmrecht in dieser Galaxie."))}</p>`;
    } else if (entry.vote_reason === "vote_closed") {
      note = `<p class="galactic-politics-note hint">${escapeHtml(t("gd_politics_vote_closed", "Die Abstimmung ist geschlossen."))}</p>`;
    }
    const countdownText = phase === "resolved"
      ? "—"
      : formatCountdownRemain(countdown);
    return `
      <section class="gc-panel galactic-politics-panel galactic-politics-galaxy-card"
               data-gd-galaxy-card
               data-galaxy="${galaxy}">
        <div class="gc-panel-header galactic-politics-galaxy-head">
          <span class="gc-panel-title">${escapeHtml(tf("gd_politics_galaxy_title", { galaxy }, "Galaxie %(galaxy)s"))}</span>
          <span class="galactic-politics-phase gc-mono" data-gd-phase-label data-phase="${escapeHtml(phase)}">${escapeHtml(_gdPhaseLabel(phase))}</span>
        </div>
        <div class="galactic-politics-active" data-gd-active-row>
          <div class="gc-gd-chip">
            <span class="gc-gd-chip-label">${escapeHtml(t("gd_banner_primary_label", "Primär"))}</span>
            <span class="gc-gd-chip-value" data-gd-active-primary>${primary}</span>
          </div>
          <div class="gc-gd-chip gc-gd-chip--secondary">
            <span class="gc-gd-chip-label">${escapeHtml(t("gd_banner_secondary_label", "Sekundär"))}</span>
            <span class="gc-gd-chip-value" data-gd-active-secondary>${secondary}</span>
          </div>
        </div>
        <p class="galactic-politics-countdown gc-mono" data-gd-countdown data-seconds="${countdown}">
          ${escapeHtml(_gdCountdownPrefix(phase))}:
          <strong data-gd-countdown-value>${escapeHtml(countdownText)}</strong>
        </p>
        ${note}
        <div class="galactic-politics-options" data-gd-options>
          ${options.map((opt) => _gdOptionCardHtml(entry, opt)).join("")}
        </div>
      </section>
    `;
  }

  function patchGalacticPoliticsDom(state) {
    if (!state || typeof state !== "object") return;
    const page = document.getElementById("galactic-politics-page");
    if (!page) return;
    const list = page.querySelector("[data-gd-galaxy-list]");
    if (!list || !Array.isArray(state.galaxies)) return;
    list.innerHTML = state.galaxies.map((entry) => _gdGalaxyCardHtml(entry)).join("");
  }

  let _galacticPoliticsBound = false;

  function bindGalacticPoliticsOnce() {
    if (_galacticPoliticsBound) return;
    _galacticPoliticsBound = true;

    document.addEventListener("click", async (ev) => {
      const btn = ev.target.closest("[data-gd-vote-btn]");
      if (!btn || btn.disabled) return;
      const page = document.getElementById("galactic-politics-page");
      if (!page) return;
      const galaxy = Number(btn.dataset.galaxy) || 0;
      const directiveKey = String(btn.dataset.directiveKey || "").trim();
      if (!galaxy || !directiveKey) return;
      const res = await GC.fetchGameAction("/api/galactic-politics/vote", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          galaxy,
          directive_key: directiveKey,
          request_id: newRequestId(),
        }),
      });
      if (res?.state) applyActionState(res, "galactic_politics_vote");
      if (res?.galactic_politics) patchGalacticPoliticsDom(res.galactic_politics);
      if (res?.ok) {
        showNotify(t("gd_politics_vote_ok", "Stimme registriert."), "success");
      } else {
        const reason = String(res?.reason || "");
        const msg = reason === "no_colony"
          ? t("gd_politics_err_no_colony", "Kein Stimmrecht in dieser Galaxie.")
          : reason === "vote_closed"
            ? t("gd_politics_err_vote_closed", "Abstimmung ist geschlossen.")
            : reason === "cooldown"
              ? t("gd_politics_err_cooldown", "Diese Direktive ist gesperrt.")
              : t("gd_politics_vote_fail", "Stimme konnte nicht gespeichert werden.");
        showNotify(msg, "error");
      }
    });
  }

  function initGalacticPolitics() {
    bindGalacticPoliticsOnce();
    const page = document.getElementById("galactic-politics-page");
    if (!page || page.dataset.ready !== "1") return;
    const state = parseGalacticPoliticsPageState();
    if (state) patchGalacticPoliticsDom(state);
    syncTradingSubnav("galactic_politics");
  }

  function initTraderHub() {
    initExchangePanel();
    initScrapyardPanel();
    initCollectorExchangePanel();
  }

  function parseFleetPageData(page) {
    const el = document.getElementById("fleet-page-state");
    if (el && el.textContent) {
      try { return JSON.parse(el.textContent); } catch (_) {}
    }
    return {};
  }

  function getFleetRuntime(page) {
    if (!page._fleetRt) {
      page._fleetRt = {
        data: parseFleetPageData(page),
        lastPreview: null,
        sending: false,
        previewTimer: null,
      };
    }
    return page._fleetRt;
  }

  /** GC-557 — fleet send/preview origin must match active/context planet. */
  function resolveFleetOriginPlanetId(page) {
    if (!page) return 0;
    const rt = getFleetRuntime(page);
    const fromDom = parseInt(page.dataset.planetId || "0", 10);
    const fromState = Number(GC.lastState?.active_planet_id || 0);
    const fromRt = parseInt(rt.data?.planet_id || "0", 10);
    const pid = fromDom || fromState || fromRt;
    if (pid > 0) {
      page.dataset.planetId = String(pid);
      if (rt.data) rt.data.planet_id = pid;
    }
    return pid > 0 ? pid : 0;
  }

  function fleetFuelLabel(tt, fuelResource) {
    if (fuelResource === "fuel_cells") return tt("resource_fuel_cells", "Fuel Cells");
    if (fuelResource === "metal") return tt("resource_metal", "Ferronit");
    return tt("resource_crystal", "Crytite");
  }

  function bindFleetOnce() {
    if (GC._fleetEventsBound) return;
    GC._fleetEventsBound = true;

    const tt = (key, fallback) => t(key, fallback);
    const fleetPayload = (res) => ((res && res.data && typeof res.data === "object") ? res.data : res) || {};
    const apiError = (res) => (res && (res.error || res.reason)) || "generic";
    const reasonText = (reason, preview) => {
      if (reason === "mission_locked") {
        const lock = preview?.mission_lock || {};
        const until = Number(lock.locked_until || lock.until || 0);
        if (until > 0) {
          const when = new Date(until * 1000).toLocaleString(undefined, { dateStyle: "short", timeStyle: "short" });
          const tpl = tt("fleet_mission_locked_until", "This mission is locked until {datetime}.");
          return tpl.replace("{datetime}", when);
        }
        return tt("fleet_mission_locked", "This mission is currently locked.");
      }
      if (reason === "attack_limit_reached") {
        return tt(
          "fleet_attack_limit_reached",
          "Attack limit reached: you can only attack the same planet 5 times within 24 hours."
        );
      }
      if (reason === "noob_protection_blocked") {
        const np = preview?.noob_protection || {};
        const tpl = tt(
          "fleet_noob_protection_blocked",
          "Attack blocked: player scores must be within {factor}× of each other (you: {attacker_score}, target: {defender_score})."
        );
        return tpl
          .replace("{factor}", String(np.factor || 5))
          .replace("{attacker_score}", fmtNumber(np.attacker_score || 0))
          .replace("{defender_score}", fmtNumber(np.defender_score || 0));
      }
      return tt(`fleet_error_${reason}`, tt("fleet_error_generic", "Fleet action failed."));
    };

    const getPage = () => {
      const page = document.getElementById("fleet-page");
      return page && page.dataset.ready === "1" ? page : null;
    };

    const getForm = (page) => page.querySelector("#fleet-send-form");

    const getShipsSelection = (page) => {
      const ships = {};
      page.querySelectorAll("[data-ship-input]").forEach((inp) => {
        const key = inp.getAttribute("data-ship-input");
        if (!key) return;
        let val = readNumberInput(inp);
        if (val <= 0) return;
        // Cap to hangar stock on the row — over-typed / misformatted amounts must not
        // block mass-expedition preview/send with not_enough_ships.
        const row = inp.closest("[data-ship-key]");
        const have = parseIntNumber(row?.getAttribute("data-ship-have") ?? "0");
        if (have >= 0 && val > have) {
          val = have;
          setNumberInputValue(inp, have);
        }
        if (val > 0) ships[key] = val;
      });
      return ships;
    };

    const isCoarsePointer = () => window.matchMedia("(hover: none), (pointer: coarse)").matches;

    let _fleetShipPickTooltipTrigger = null;

    const hideFleetShipPickTooltip = () => {
      const page = getPage();
      const tooltip = page?.querySelector("[data-fleet-ship-pick-tooltip]")
        || document.getElementById("gc-fleet-ship-pick-tooltip");
      if (tooltip) {
        tooltip.hidden = true;
        tooltip.innerHTML = "";
      }
      if (_fleetShipPickTooltipTrigger) {
        _fleetShipPickTooltipTrigger.removeAttribute("aria-describedby");
        _fleetShipPickTooltipTrigger = null;
      }
    };

    const buildFleetShipPickTooltipHtml = (card) => {
      const name = card.getAttribute("data-ship-tooltip-name") || "";
      const have = parseInt(card.getAttribute("data-ship-have") || "0", 10) || 0;
      const speed = card.getAttribute("data-ship-tooltip-speed") || "0";
      const cargo = card.getAttribute("data-ship-tooltip-cargo") || "0";
      const esc = (value) => String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      return [
        `<div class="gc-fleet-drawer-tooltip-title">${esc(name)}</div>`,
        `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${tt("fleet_ship_stock", "Bestand")}</span>× ${formatNumber(have)}</div>`,
        `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${tt("fleet_table_speed", "Speed")}</span>${esc(speed)}</div>`,
        `<div class="gc-fleet-drawer-tooltip-section"><span class="gc-fleet-drawer-tooltip-label">${tt("fleet_table_cargo", "Cargo")}</span>${esc(cargo)}</div>`,
      ].join("");
    };

    const showFleetShipPickTooltip = (trigger, card) => {
      const page = getPage();
      if (!page || !trigger || !card || !page.contains(card)) return;
      const tooltip = page.querySelector("[data-fleet-ship-pick-tooltip]")
        || document.getElementById("gc-fleet-ship-pick-tooltip");
      if (!tooltip) return;
      hideFleetShipPickTooltip();
      _fleetShipPickTooltipTrigger = trigger;
      tooltip.innerHTML = buildFleetShipPickTooltipHtml(card);
      tooltip.hidden = false;
      trigger.setAttribute("aria-describedby", "gc-fleet-ship-pick-tooltip");
      positionFleetDrawerTooltip(tooltip, trigger);
    };

    const syncFleetShipPickQtyMarks = (page) => {
      page.querySelectorAll(".fleet-ship-card--pick").forEach((card) => {
        const inp = card.querySelector("[data-ship-input]");
        const qty = inp ? readNumberInput(inp) : 0;
        card.classList.toggle("has-ship-qty", qty > 0);
      });
    };

    /** GC-981 — programmatic ship qty changes must mirror manual input (preview + mass expo). */
    const emitFleetShipInputChange = (page, inp) => {
      if (!page || !inp) return;
      syncFleetShipPickQtyMarks(page);
      scrollFleetShipInputEnd(inp);
      inp.dispatchEvent(new Event("input", { bubbles: true }));
      inp.dispatchEvent(new Event("change", { bubbles: true }));
    };

    const setFleetShipInputValue = (page, inp, n) => {
      if (!inp) return;
      setNumberInputValue(inp, n);
      emitFleetShipInputChange(page, inp);
    };

    const scrollFleetShipInputEnd = (inp) => {
      if (!inp) return;
      requestAnimationFrame(() => {
        inp.scrollLeft = inp.scrollWidth;
      });
    };

    const getResourcesSelection = (page) => ({
      metal: readNumberInput(page.querySelector("[data-fleet-res-metal]")),
      crystal: readNumberInput(page.querySelector("[data-fleet-res-crystal]")),
      fuel_cells: readNumberInput(page.querySelector("[data-fleet-res-fuel-cells]")),
    });

    const getExpeditionHoursSelection = (page) => {
      const form = getForm(page);
      const mission = form?.querySelector("[data-fleet-mission]")?.value || "transport";
      if (mission !== "expedition") return undefined;
      const raw = form?.querySelector("[data-fleet-expedition-hours]")?.value || "1";
      const hours = parseInt(raw, 10);
      return Number.isFinite(hours) && hours >= 1 && hours <= 4 ? hours : 1;
    };

    const getTargetCoords = (page) => {
      const form = getForm(page);
      return {
        target_galaxy: parseInt(form?.querySelector('[name="target_galaxy"]')?.value || "1", 10),
        target_system: parseInt(form?.querySelector('[name="target_system"]')?.value || "1", 10),
        target_position: parseInt(form?.querySelector('[name="target_position"]')?.value || "1", 10),
      };
    };

    const getFleetUrlParams = () => new URLSearchParams(window.location.search);

    const getFleetUrlMissionPrefill = () => {
      const mission = (getFleetUrlParams().get("mission") || "").trim().toLowerCase();
      return mission || "";
    };

    const hasFleetWorldKeyPrefill = () => !!(getFleetUrlParams().get("world_key") || "").trim();

    const refreshFleetUrlMissionLock = (page) => {
      if (!page) return "";
      const params = getFleetUrlParams();
      const missionRaw = (params.get("mission") || "").trim().toLowerCase();
      const worldKeyRaw = (params.get("world_key") || "").trim();
      if (missionRaw) {
        page.dataset.fleetUrlMission = missionRaw;
      } else if (worldKeyRaw) {
        page.dataset.fleetUrlMission = "colonize";
      }
      if (worldKeyRaw) {
        page.dataset.fleetWorldKey = worldKeyRaw;
      }
      return String(page.dataset.fleetUrlMission || "").trim().toLowerCase();
    };

    const isFleetUrlPrefillLocked = (page) => {
      const locked = String(page?.dataset?.fleetUrlMission || "").trim().toLowerCase();
      if (locked) return true;
      return hasFleetWorldKeyPrefill() || !!getFleetUrlMissionPrefill();
    };

    const enforceFleetUrlMissionLock = (page) => {
      const form = getForm(page);
      const ms = form?.querySelector("[data-fleet-mission]");
      if (!ms) return "";
      const locked = String(page.dataset.fleetUrlMission || refreshFleetUrlMissionLock(page) || "").trim().toLowerCase();
      if (!locked) return "";
      const known = Array.from(ms.options).some((opt) => opt.value === locked);
      if (!known) return locked;
      if (ms.value !== locked) {
        ms.value = locked;
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(ms);
        if (typeof GC.updateFleetFormMode === "function") GC.updateFleetFormMode(page);
      }
      syncFleetMissionLockUi(page);
      return locked;
    };

    const getFleetWorldKey = (page) => {
      const fromDataset = String(page?.dataset?.fleetWorldKey || "").trim();
      if (fromDataset) return fromDataset;
      return (getFleetUrlParams().get("world_key") || "").trim();
    };
    const getFleetTargetType = (page) => {
      const fromPreview = String(page?.dataset?.fleetNativeTargetType || "").trim().toLowerCase();
      if (fromPreview) return fromPreview;
      const fromUrl = String(getFleetUrlParams().get("target_type") || "").trim().toLowerCase();
      if (fromUrl) return fromUrl;
      return String(page?.dataset?.fleetTargetType || "").trim().toLowerCase();
    };

    const buildFleetTargetPayload = (page) => {
      const wk = getFleetWorldKey(page);
      if (!wk) return {};
      const payload = { world_key: wk };
      const targetType = getFleetTargetType(page);
      if (targetType) payload.target_type = targetType;
      return payload;
    };

    const syncFleetMissionLockUi = (page) => {
      const form = getForm(page);
      const ms = form?.querySelector("[data-fleet-mission]");
      const row = page?.querySelector(".fleet-mission-speed-row");
      const formatLockUntil = (ts) => {
        const n = Number(ts);
        if (!Number.isFinite(n) || n <= 0) return "";
        try {
          return new Date(n * 1000).toLocaleString(undefined, { dateStyle: "short", timeStyle: "short" });
        } catch (_) {
          return "";
        }
      };
      const getOpsMissionLocks = () => getFleetRuntime(page).data?.mission_locks || {};
      const missionLockStatusText = (lock) => {
        if (!lock?.locked) return "";
        const until = formatLockUntil(lock.locked_until);
        if (until) {
          return tt("fleet_mission_locked_until", "This mission is locked until {datetime}.").replace("{datetime}", until);
        }
        return tt("fleet_mission_locked", "This mission is currently locked.");
      };
      const renderFleetMissionLocksBanner = () => {
        const banner = page.querySelector("[data-fleet-mission-locks-banner]");
        if (!banner) return;
        const active = Object.entries(getOpsMissionLocks()).filter(([, lock]) => lock && lock.locked);
        if (!active.length) {
          banner.hidden = true;
          banner.innerHTML = "";
          return;
        }
        const items = active.map(([mission, lock]) => {
          const name = tt(`fleet_mission_${mission}`, mission);
          const status = missionLockStatusText(lock);
          return `<li class="fleet-mission-locks-banner-item"><strong>${_fleetEsc(name)}</strong><span>${_fleetEsc(status)}</span></li>`;
        }).join("");
        banner.innerHTML =
          `<div class="fleet-mission-locks-banner-inner">` +
          `<p class="fleet-mission-locks-banner-title">${_fleetEsc(tt("fleet_mission_locks_notice_title", "Locked missions"))}</p>` +
          `<ul class="fleet-mission-locks-banner-list">${items}</ul>` +
          `</div>`;
        banner.hidden = false;
      };
      const applyOpsMissionLocksToSelect = () => {
        if (!ms) return;
        const rt = getFleetRuntime(page);
        const locks = getOpsMissionLocks();
        const urlPrefillLocked = isFleetUrlPrefillLocked(page);
        if (!rt.missionOptionLabels) {
          rt.missionOptionLabels = {};
          Array.from(ms.options).forEach((opt) => {
            rt.missionOptionLabels[opt.value] = opt.textContent.trim();
          });
        }
        Array.from(ms.options).forEach((opt) => {
          const lock = locks[opt.value];
          const opsLocked = !!(lock && lock.locked);
          opt.disabled = opsLocked;
          const baseLabel = rt.missionOptionLabels[opt.value] || tt(`fleet_mission_${opt.value}`, opt.value);
          opt.textContent = opsLocked
            ? `${baseLabel} — ${tt("fleet_mission_locked_short", "locked")}`
            : baseLabel;
        });
        if (!urlPrefillLocked) {
          const currentLock = locks[ms.value];
          if (currentLock && currentLock.locked) {
            const firstOpen = Array.from(ms.options).find((opt) => !opt.disabled);
            if (firstOpen) {
              ms.value = firstOpen.value;
              if (typeof GC.updateFleetFormMode === "function") GC.updateFleetFormMode(page);
            }
          }
        }
        if (typeof GC.rebuildHudSelect === "function") GC.rebuildHudSelect(ms);
        else if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(ms);
      };
      renderFleetMissionLocksBanner();
      if (!ms || !row) return;
      const urlPrefillLocked = isFleetUrlPrefillLocked(page);
      applyOpsMissionLocksToSelect();
      ms.disabled = urlPrefillLocked;
      row.classList.toggle("is-mission-locked", urlPrefillLocked);
    };

    const resolveFleetWorldTargetPresentation = (target) => {
      if (!target || typeof target !== "object") return null;
      const sw = target.strategic_world;
      if (sw?.world_key) return { ...sw };
      const wt = target.world_target;
      const worldKey = String(wt?.target_world_key || target.world_key || "").trim();
      if (!worldKey) return null;
      return {
        world_key: worldKey,
        name_key: wt?.target_name_key || sw?.name_key || null,
        display_name: wt?.target_name || null,
        type_key: sw?.type_key || null,
        native_type: wt?.target_type || null,
        role_icon: sw?.role_icon || "✦",
        promise_key: sw?.promise_key || null,
        risk_key: sw?.risk_key || null,
        risk_level: sw?.risk_level || "low",
        reward_hint_key: sw?.reward_hint_key || null,
      };
    };

    const _fleetEsc = (text) => String(text || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");

    const formatFleetNamedTarget = (worldTarget, target, fallbackCoords) => {
      const wt = worldTarget || target?.world_target || null;
      const coords = String(fallbackCoords || target?.coords || "").trim();
      if (!wt) {
        const legacyType = String(target?.target_type || "").trim();
        let name = String(target?.target_owner_name || "").trim();
        if (!name && legacyType === "expedition_slot") {
          name = tt("fleet_target_expedition_label", "Deep space");
        }
        if (!name && legacyType === "empty_slot") {
          name = tt("fleet_target_empty_label", "—");
        }
        if (!name) name = coords || "–";
        return {
          name,
          typeLabel: legacyType ? tt(`fleet_target_${legacyType}`, legacyType) : "",
          coords,
        };
      }
      let name = wt.target_name_key
        ? tt(wt.target_name_key, wt.target_name_key)
        : String(wt.target_name || "").trim();
      if (!name && wt.target_type === "expedition_world") {
        name = tt("fleet_target_expedition_label", "Deep space");
      }
      if (!name) name = coords || "–";
      const typeLabel = wt.target_type
        ? tt(`fleet_target_${wt.target_type}`, wt.target_type)
        : "";
      const legacyCoords = wt.legacy_coords;
      const coordsText = legacyCoords
        ? `[${legacyCoords.galaxy}:${legacyCoords.system}:${legacyCoords.position}]`
        : coords;
      return { name, typeLabel, coords: coordsText };
    };

    const renderFleetActiveTargetBlock = (mv) => {
      const named = formatFleetNamedTarget(mv.world_target, null, mv.target_coords);
      const routeHtml = GC.coordRouteHtml(mv.origin_coords, mv.target_coords);
      if (!mv.world_target) {
        return `<div class="fleet-active-coords gc-mono">${routeHtml}</div>`;
      }
      const originName = String(mv.origin_name || "").trim();
      const originPrefix = originName
        ? `<span class="fleet-active-origin-name">${_fleetEsc(originName)}</span><span class="fleet-active-route-arrow" aria-hidden="true">→</span>`
        : "";
      return `<div class="fleet-active-target">
          <div class="fleet-active-target-primary">${originPrefix}<span class="fleet-active-target-name">${_fleetEsc(named.name)}</span></div>
          ${named.typeLabel ? `<span class="fleet-active-target-type">${_fleetEsc(named.typeLabel)}</span>` : ""}
          <div class="fleet-active-coords-secondary gc-mono hint">${routeHtml}</div>
        </div>`;
    };

    const applyFleetPreviewNamedTarget = (page, target, fallbackCoords) => {
      const named = formatFleetNamedTarget(target?.world_target, target, fallbackCoords);
      const previewTargetName = page.querySelector("[data-preview-target-name]");
      const previewTargetNativeType = page.querySelector("[data-preview-target-native-type]");
      const previewTargetCoords = page.querySelector("[data-preview-target-coords]");
      const previewTargetHero = page.querySelector("[data-preview-target-hero]");
      if (previewTargetName) previewTargetName.textContent = named.name || "–";
      if (previewTargetNativeType) previewTargetNativeType.textContent = named.typeLabel || "–";
      if (previewTargetCoords) {
        if (named.coords) {
          previewTargetCoords.textContent = named.coords;
          previewTargetCoords.hidden = false;
        } else {
          previewTargetCoords.textContent = "";
          previewTargetCoords.hidden = true;
        }
      }
      if (previewTargetHero) {
        previewTargetHero.classList.toggle("is-empty", !named.name || named.name === "–");
      }
      return named;
    };

    const clearFleetWorldKey = (page) => {
      if (!page) return;
      delete page.dataset.fleetWorldKey;
      delete page.dataset.fleetTargetType;
      delete page.dataset.fleetNativeTargetType;
      page.querySelector("[data-fleet-coords-row]")?.removeAttribute("hidden");
      page.querySelector("[data-fleet-target-block]")?.classList.remove("is-world-target");
      page.querySelector(".fleet-send-panel")?.classList.remove("is-world-target-mode");
      page.querySelector("[data-fleet-coords-strip]")?.classList.remove("is-world-target");
      const hint = page.querySelector("[data-fleet-coords-hint]");
      if (hint?.dataset.worldTargetHint === "1") {
        hint.textContent = "";
        hint.hidden = true;
        delete hint.dataset.worldTargetHint;
      }
      hideFleetWorldTargetPanel(page);
    };
    const syncFleetWorldTargetUi = (page) => {
      const wk = getFleetWorldKey(page);
      const targetBlock = page.querySelector("[data-fleet-target-block]");
      const coordsRow = page.querySelector("[data-fleet-coords-row]");
      const strip = page.querySelector("[data-fleet-coords-strip]");
      const sendPanel = page.querySelector(".fleet-send-panel");
      const hint = page.querySelector("[data-fleet-coords-hint]");
      if (targetBlock) targetBlock.classList.toggle("is-world-target", !!wk);
      if (coordsRow) coordsRow.hidden = !!wk;
      if (strip) strip.classList.toggle("is-world-target", !!wk);
      if (sendPanel) sendPanel.classList.toggle("is-world-target-mode", !!wk);
      if (!hint) return;
      if (wk) {
        hint.hidden = true;
        delete hint.dataset.worldTargetHint;
      } else if (hint.dataset.worldTargetHint === "1") {
        hint.textContent = "";
        hint.hidden = true;
        delete hint.dataset.worldTargetHint;
      }
    };
    const renderFleetWorldTargetPanel = (page, presentation, extras = {}) => {
      const panel = page.querySelector("[data-fleet-world-target]");
      if (!panel) return;
      const sw = presentation && typeof presentation === "object" ? presentation : null;
      if (!sw?.world_key) {
        panel.hidden = true;
        return;
      }
      panel.hidden = false;
      syncFleetWorldTargetUi(page);
      const iconEl = panel.querySelector("[data-fleet-world-target-icon]");
      const nameEl = panel.querySelector("[data-fleet-world-target-name]");
      const typeEl = panel.querySelector("[data-fleet-world-target-type]");
      const promiseEl = panel.querySelector("[data-fleet-world-target-promise]");
      const riskEl = panel.querySelector("[data-fleet-world-target-risk]");
      const rewardEl = panel.querySelector("[data-fleet-world-target-reward]");
      const missionEl = panel.querySelector("[data-fleet-world-target-mission]");
      const flightEl = panel.querySelector("[data-fleet-world-target-flight]");
      if (iconEl) iconEl.textContent = sw.role_icon || "✦";
      if (nameEl) {
        nameEl.textContent = sw.display_name
          || (sw.name_key ? tt(sw.name_key, sw.name_key) : "–");
      }
      if (typeEl) {
        typeEl.textContent = sw.type_key
          ? tt(sw.type_key, sw.type_key)
          : sw.native_type
            ? tt(`fleet_target_${sw.native_type}`, sw.native_type)
            : "–";
      }
      const setMetaRow = (el, text) => {
        const row = el?.closest("div");
        if (!el || !row) return;
        const label = String(text || "").trim();
        if (!label || label === "–") {
          row.hidden = true;
          el.textContent = "–";
          return;
        }
        row.hidden = false;
        el.textContent = label;
      };
      setMetaRow(promiseEl, sw.promise_key ? tt(sw.promise_key, "") : "");
      if (riskEl) {
        const riskText = sw.risk_key ? tt(sw.risk_key, "") : "";
        setMetaRow(riskEl, riskText);
        if (riskText) {
          riskEl.className = `fleet-world-target-risk fleet-world-target-risk--${sw.risk_level || "low"}`;
        }
      }
      setMetaRow(rewardEl, sw.reward_hint_key ? tt(sw.reward_hint_key, "") : "");
      if (missionEl) {
        const mission = String(extras.mission || "").trim().toLowerCase();
        missionEl.textContent = mission ? tt(`fleet_mission_${mission}`, mission) : "–";
      }
      if (flightEl) {
        flightEl.textContent = extras.flightLabel || "–";
      }
    };
    const hideFleetWorldTargetPanel = (page) => renderFleetWorldTargetPanel(page, null);
    const loadFleetWorldTargetPreview = async (page, worldKey) => {
      const wk = String(worldKey || "").trim();
      if (!wk) {
        hideFleetWorldTargetPanel(page);
        return;
      }
      const mission = getForm(page)?.querySelector("[data-fleet-mission]")?.value || "colonize";
      const previewPath = mission === "expedition"
        ? "/api/worlds/expedition-preview"
        : "/api/worlds/colonize-preview";
      try {
        let res = await GC.fetchJSON(
          `${previewPath}?world_key=${encodeURIComponent(wk)}`,
          { cache: "no-store" }
        );
        if (
          mission === "expedition"
          && (!res?.ok || !res.data?.can_expedition)
        ) {
          res = await GC.fetchJSON(
            `/api/worlds/salvage-preview?world_key=${encodeURIComponent(wk)}`,
            { cache: "no-store" }
          );
        }
        if (res?.ok && res.data?.presentation) {
          const mission = enforceFleetUrlMissionLock(page)
            || getForm(page)?.querySelector("[data-fleet-mission]")?.value
            || "";
          renderFleetWorldTargetPanel(page, res.data.presentation, { mission });
          syncFleetMissionLockUi(page);
        } else {
          hideFleetWorldTargetPanel(page);
        }
      } catch (_) {
        hideFleetWorldTargetPanel(page);
      }
    };

    const formatFleetDuration = (sec) => formatCountdownRemain(sec);

    const buildShipRoleMap = (page) => {
      const rt = getFleetRuntime(page);
      const map = {};
      (rt.data.ship_defs || []).forEach((spec) => {
        if (spec?.key) map[spec.key] = spec.role || "";
      });
      return map;
    };

    const countShipsByRole = (page, ships, role) => {
      const roleMap = buildShipRoleMap(page);
      return Object.entries(ships || {}).reduce((total, [key, qty]) => {
        if (roleMap[key] !== role) return total;
        return total + (parseInt(qty, 10) || 0);
      }, 0);
    };

    const applyExpeditionTarget = (page) => {
      const form = getForm(page);
      if (!form) return;
      const rt = getFleetRuntime(page);
      const expPos = parseInt(rt.data.expedition_position || "16", 10);
      const posInp = form.querySelector('[name="target_position"]');
      if (posInp) posInp.value = String(expPos);
    };

    const syncExpeditionMissionTarget = (page) => {
      const form = getForm(page);
      if (!form) return;
      const wk = getFleetWorldKey(page);
      const rt = getFleetRuntime(page);
      const expPos = parseInt(rt.data.expedition_position || "16", 10);
      const g = parseInt(form.querySelector('[name="target_galaxy"]')?.value || "0", 10);
      const s = parseInt(form.querySelector('[name="target_system"]')?.value || "0", 10);
      const pos = parseInt(form.querySelector('[name="target_position"]')?.value || "0", 10);
      const missionSel = form.querySelector("[data-fleet-mission]");
      const mission = missionSel?.value || "transport";
      const strip = page.querySelector("[data-fleet-coords-strip]");
      const hint = page.querySelector("[data-fleet-coords-hint]");
      const sendPanel = page.querySelector(".fleet-send-panel");
      const previewHud = page.querySelector("[data-fleet-preview]");
      const isExpoSlot = pos === expPos;

      if (wk) {
        if (strip) {
          strip.classList.remove("is-expedition");
          strip.classList.add("is-world-target");
        }
        if (sendPanel) sendPanel.classList.toggle("is-expedition-mode", mission === "expedition");
        if (previewHud) previewHud.classList.toggle("is-expedition", mission === "expedition");
        syncFleetWorldTargetUi(page);
        updateFleetFormMode(page);
        if (missionSel) GC.syncHudSelect(missionSel);
        return;
      }

      if (strip) strip.classList.toggle("is-expedition", isExpoSlot);
      if (sendPanel) sendPanel.classList.toggle("is-expedition-mode", mission === "expedition" || isExpoSlot);
      if (previewHud) previewHud.classList.toggle("is-expedition", mission === "expedition" && isExpoSlot);

      const expoBtn = page.querySelector("[data-fleet-expedition-shortcut]");
      if (expoBtn) {
        const eg = parseInt(expoBtn.getAttribute("data-galaxy") || "0", 10);
        const es = parseInt(expoBtn.getAttribute("data-system") || "0", 10);
        const ep = parseInt(expoBtn.getAttribute("data-position") || "0", 10);
        expoBtn.classList.toggle("is-selected", eg === g && es === s && ep === pos && mission === "expedition");
      }

      const quickSel = page.querySelector("[data-fleet-quick-target-select]");
      if (quickSel && !isFleetQuickTargetManual(page)) {
        let matched = "";
        Array.from(quickSel.options).forEach((opt) => {
          if (!opt.value) return;
          const og = parseInt(opt.getAttribute("data-galaxy") || "0", 10);
          const os = parseInt(opt.getAttribute("data-system") || "0", 10);
          const op = parseInt(opt.getAttribute("data-position") || "0", 10);
          const optMission = opt.getAttribute("data-mission") || "";
          const coordMatch = og === g && os === s && op === pos;
          const isMatch = optMission === "expedition"
            ? coordMatch && mission === "expedition"
            : coordMatch && !optMission;
          if (isMatch) matched = opt.value;
        });
        quickSel.value = matched;
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(quickSel);
      }

      if (hint) {
        if (missionSel?.value === "expedition" && !isExpoSlot) {
          hint.textContent = formatMissionHint("fleet_expedition_coords_hint_required", { position: expPos });
          hint.hidden = false;
        } else if (isExpoSlot && missionSel?.value !== "expedition") {
          hint.textContent = formatMissionHint("fleet_expedition_hint_select_mission");
          hint.hidden = false;
        } else {
          hint.textContent = "";
          hint.hidden = true;
        }
      }
      updateFleetFormMode(page);
      if (missionSel) GC.syncHudSelect(missionSel);
    };

    const setColonizeRowVisible = (page, mission) => {
      const colonizeRow = page.querySelector("[data-fleet-colonize-row]");
      if (colonizeRow) colonizeRow.hidden = mission !== "colonize";
    };

    const syncMissionAllowlistFromTarget = (page, target) => {
      const sel = page.querySelector("[data-fleet-mission]");
      if (!sel || !target) return;
      const rt = getFleetRuntime(page);
      const urlMission = String(page.dataset.fleetUrlMission || refreshFleetUrlMissionLock(page) || "").trim().toLowerCase();
      const locked = isFleetUrlPrefillLocked(page);
      const preserveMission = !locked;
      const prevValue = sel.value;
      const allowed = new Set(target.allowed_missions || []);
      if (!rt.missionOptionLabels) {
        rt.missionOptionLabels = {};
        Array.from(sel.options).forEach((opt) => {
          rt.missionOptionLabels[opt.value] = opt.textContent.trim();
        });
      }
      const allMissions = Array.isArray(rt.data.missions) && rt.data.missions.length
        ? rt.data.missions.slice()
        : Object.keys(rt.missionOptionLabels);
      sel.innerHTML = "";
      allMissions.forEach((missionKey) => {
        const show = preserveMission
          || allowed.size === 0
          || allowed.has(missionKey)
          || (urlMission && missionKey === urlMission);
        if (!show) return;
        const opt = document.createElement("option");
        opt.value = missionKey;
        opt.textContent = rt.missionOptionLabels[missionKey]
          || tt(`fleet_mission_${missionKey}`, missionKey);
        sel.appendChild(opt);
      });
      if (!sel.options.length && allMissions.length) {
        allMissions.forEach((missionKey) => {
          const opt = document.createElement("option");
          opt.value = missionKey;
          opt.textContent = rt.missionOptionLabels[missionKey]
            || tt(`fleet_mission_${missionKey}`, missionKey);
          sel.appendChild(opt);
        });
      }
      if (urlMission && Array.from(sel.options).some((opt) => opt.value === urlMission)) {
        sel.value = urlMission;
      } else if (!locked && !preserveMission && allowed.size > 0 && !allowed.has(prevValue)) {
        const first = Array.from(sel.options)[0];
        if (first) sel.value = first.value;
      } else if (prevValue && Array.from(sel.options).some((opt) => opt.value === prevValue)) {
        sel.value = prevValue;
      } else if (sel.options.length && !Array.from(sel.options).some((opt) => opt.value === sel.value)) {
        sel.value = sel.options[0].value;
      }
      if (typeof GC.rebuildHudSelect === "function") GC.rebuildHudSelect(sel);
      else if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(sel);
      if (typeof GC.syncFleetMissionLockUi === "function") GC.syncFleetMissionLockUi(page);
      if (locked) {
        enforceFleetUrlMissionLock(page);
        return;
      }
      if (sel.value !== prevValue && !urlMission) {
        updateFleetFormMode(page);
        setColonizeRowVisible(page, sel.value);
      }
    };

    const updateFleetTargetInlineError = (page, target) => {
      const el = page.querySelector("[data-fleet-target-inline-error]");
      if (!el) return;
      const reason = String(target?.reason_if_blocked || "").trim();
      if (reason) {
        el.textContent = reasonText(reason);
        el.hidden = false;
        el.classList.add("is-blocked");
        return;
      }
      el.textContent = "";
      el.hidden = true;
      el.classList.remove("is-blocked");
    };

    const runTargetResolve = async (page) => {
      const form = getForm(page);
      if (!form) return null;
      const wk = getFleetWorldKey(page);
      if (wk) {
        updateFleetTargetInlineError(page, null);
        return null;
      }
      syncExpeditionMissionTarget(page);
      const coords = getTargetCoords(page);
      const mission = form.querySelector("[data-fleet-mission]")?.value || "transport";
      try {
        const q = new URLSearchParams({
          target_galaxy: String(coords.target_galaxy),
          target_system: String(coords.target_system),
          target_position: String(coords.target_position),
          mission_type: mission,
        });
        const res = await GC.fetchJSON(`/api/fleet/resolve-target?${q.toString()}`, { cache: "no-store" });
        const target = fleetPayload(res).target || res.target;
        if (res?.ok && target) {
          syncMissionAllowlistFromTarget(page, target);
          updateFleetTargetInlineError(page, target);
          return target;
        }
        updateFleetTargetInlineError(page, { reason_if_blocked: apiError(res) });
      } catch (_) {
        updateFleetTargetInlineError(page, null);
      }
      return null;
    };

    const scheduleTargetResolve = (page) => {
      const rt = getFleetRuntime(page);
      if (rt.targetResolveTimer) clearTimeout(rt.targetResolveTimer);
      rt.targetResolveTimer = setTimeout(() => runTargetResolve(page), 250);
    };

    const formatDebrisPreview = (debris) => {
      const metal = Math.max(0, parseInt(debris?.metal || 0, 10));
      const crystal = Math.max(0, parseInt(debris?.crystal || 0, 10));
      if (!metal && !crystal) {
        return tt("fleet_preview_no_debris", "No debris at target");
      }
      return tt(
        "fleet_preview_debris_amounts",
        "Metal %(metal)s · Crystal %(crystal)s",
        { metal: fmtNumber(metal), crystal: fmtNumber(crystal) }
      );
    };

    const shouldShowExpeditionHours = (page, mission) => {
      return mission === "expedition";
    };

    const updateFleetFormMode = (page) => {
      const form = getForm(page);
      if (!form) return;
      const mission = form.querySelector("[data-fleet-mission]")?.value || "transport";
      const resFieldset = page.querySelector("[data-fleet-resources-fieldset]");
      const showResources = ["transport", "deploy", "colonize", "collect"].includes(mission);
      if (resFieldset) {
        resFieldset.classList.toggle("fleet-resources-fieldset--inactive", !showResources);
        resFieldset.setAttribute("aria-hidden", showResources ? "false" : "true");
      }
      const expoHoursRow = page.querySelector("[data-fleet-expedition-hours-row]");
      if (expoHoursRow) expoHoursRow.hidden = !shouldShowExpeditionHours(page, mission);
      setColonizeRowVisible(page, mission);
      syncExpeditionDailyEfficiencyUi(page);
      page.querySelectorAll(".fleet-ship-row[data-ship-role='recycle']").forEach((row) => {
        row.classList.toggle("fleet-ship-row--mission-focus", mission === "recycle");
      });
      const debrisRow = page.querySelector("[data-preview-debris-row]");
      if (debrisRow) debrisRow.hidden = mission !== "recycle";
    };

    const formatMissionHint = (key, vars = {}) => {
      let text = tt(key, key);
      Object.entries(vars).forEach(([name, value]) => {
        text = text.replace(new RegExp(`%\\(${name}\\)s`, "g"), String(value ?? ""));
      });
      return text;
    };

    const expeditionDailyEfficiencyTone = (pct) => {
      const value = Math.max(0, parseInt(pct, 10) || 0);
      if (value >= 95) return "good";
      if (value >= 85) return "warn";
      if (value >= 70) return "mid";
      return "low";
    };

    const formatExpeditionDailyReset = (resetAt, serverNow) => {
      const target = Number(resetAt || 0);
      const now = Number.isFinite(serverNow) ? serverNow : getTimerServerNow();
      if (!target) return "";
      const rem = Math.max(0, Math.ceil(target - now));
      const time = rem > 0 ? formatCountdownRemain(rem) : tt("fleet_expedition_daily_efficiency_reset_soon", "Soon");
      return formatMissionHint("fleet_expedition_daily_efficiency_reset", { time });
    };

    const applyExpeditionDailyEfficiencyBlock = (root, daily, opts = {}) => {
      if (!root || !daily || typeof daily !== "object") return;
      const pct = Math.max(0, parseInt(daily.daily_efficiency_pct, 10) || 0);
      const tone = expeditionDailyEfficiencyTone(pct);
      const pctEl = root.querySelector(opts.pctSelector || "[data-fleet-expedition-daily-pct]");
      const dotEl = root.querySelector(opts.dotSelector || "[data-fleet-expedition-daily-dot]");
      const resetEl = root.querySelector(opts.resetSelector || "[data-fleet-expedition-daily-reset]");
      if (pctEl) pctEl.textContent = `${pct}%`;
      if (dotEl) {
        dotEl.className = `fleet-expedition-daily-dot fleet-expedition-daily-dot--${tone}`;
      }
      if (resetEl) {
        resetEl.textContent = formatExpeditionDailyReset(daily.reset_at);
        resetEl.dataset.ts = String(daily.reset_at || "");
      }
      root.hidden = false;
      root.dataset.expeditionDailyPct = String(pct);
      root.dataset.expeditionDailyResetAt = String(daily.reset_at || "");
    };

    const hideExpeditionDailyEfficiencyBlock = (root) => {
      if (!root) return;
      root.hidden = true;
      delete root.dataset.expeditionDailyPct;
      delete root.dataset.expeditionDailyResetAt;
    };

    const syncExpeditionDailyEfficiencyUi = (page, daily) => {
      if (!page) return;
      const rt = getFleetRuntime(page);
      if (daily && typeof daily === "object") {
        rt.data.expedition_daily = daily;
      }
      const payload = rt.data?.expedition_daily;
      if (!payload) return;

      page.querySelectorAll("[data-fleet-expedition-daily]").forEach((block) => {
        applyExpeditionDailyEfficiencyBlock(block, payload, {
          pctSelector: "[data-fleet-expedition-daily-pct]",
          dotSelector: "[data-fleet-expedition-daily-dot]",
          resetSelector: "[data-fleet-expedition-daily-reset]",
        });
      });

      const form = getForm(page);
      const mission = form?.querySelector("[data-fleet-mission]")?.value || "transport";
      const previewRow = page.querySelector("[data-preview-expedition-daily-row]");
      if (previewRow) {
        if (mission === "expedition") {
          applyExpeditionDailyEfficiencyBlock(previewRow, payload, {
            pctSelector: "[data-preview-expedition-daily-pct]",
            dotSelector: "[data-preview-expedition-daily-dot]",
            resetSelector: "[data-preview-expedition-daily-reset]",
          });
        } else {
          hideExpeditionDailyEfficiencyBlock(previewRow);
        }
      }
    };

    const tickExpeditionDailyEfficiencyResets = (page) => {
      if (!page) return;
      const now = getTimerServerNow();
      page.querySelectorAll("[data-fleet-expedition-daily-reset], [data-preview-expedition-daily-reset]").forEach((el) => {
        const ts = Number(el.dataset.ts || 0);
        if (!ts) return;
        el.textContent = formatExpeditionDailyReset(ts, now);
      });
    };

    GC.syncExpeditionDailyEfficiencyUi = syncExpeditionDailyEfficiencyUi;
    GC.tickExpeditionDailyEfficiencyResets = tickExpeditionDailyEfficiencyResets;

    const resolveMissionFeedback = (page, missionType, preview, ships) => {
      const mission = String(missionType || "transport").toLowerCase();
      const target = preview?.target || {};
      const rt = getFleetRuntime(page);
      const expPos = parseInt(rt.data.expedition_position || "16", 10);
      const hints = [];

      if (target.target_type === "expedition_slot" && mission !== "expedition") {
        hints.push({ tone: "warn", text: formatMissionHint("fleet_expedition_hint_select_mission") });
        return hints;
      }

      if (mission === "expedition") {
        const expoShips = countShipsByRole(page, ships, "expedition");
        const combatShips = countShipsByRole(page, ships, "combat");
        const recycleShips = countShipsByRole(page, ships, "recycle");
        const cargoTotal = parseInt(preview?.cargo_total || "0", 10) || 0;
        const rating = preview?.expedition_rating && typeof preview.expedition_rating === "object"
          ? preview.expedition_rating
          : {};
        const escortRatioPct = Math.max(
          0,
          Math.round((Number(rating.escort_ratio) || 0) * 100)
        );
        const escortCoverPct = Math.max(
          0,
          Math.round((Number(rating.escort_effectiveness) || 0) * 100)
        );
        const validTarget = target.target_type === "expedition_slot"
          || target.target_type === "strategic_world";
        if (target.target_type && !validTarget) {
          hints.push({
            tone: "warn",
            text: formatMissionHint("fleet_expedition_hint_wrong_position", { position: expPos }),
          });
        } else if (expoShips <= 0 && cargoTotal <= 0) {
          hints.push({ tone: "warn", text: formatMissionHint("fleet_expedition_hint_no_hull") });
        } else {
          hints.push({
            tone: "ok",
            text: formatMissionHint("fleet_expedition_hint_ready", { ships: expoShips, cargo: cargoTotal }),
          });
        }
        if (Object.keys(ships || {}).length) {
          let escortHintKey = "fleet_expedition_hint_escort_none";
          let escortTone = "warn";
          if (combatShips > 0 && escortCoverPct >= 35) {
            escortHintKey = "fleet_expedition_hint_escort_high";
            escortTone = "ok";
          } else if (combatShips > 0 && escortCoverPct >= 15) {
            escortHintKey = "fleet_expedition_hint_escort_mid";
            escortTone = "info";
          } else if (combatShips > 0) {
            escortHintKey = "fleet_expedition_hint_escort_low";
            escortTone = "warn";
          }
          hints.push({
            tone: escortTone,
            text: formatMissionHint(escortHintKey, {
              ships: combatShips,
              ratio: escortRatioPct,
              cover: escortCoverPct,
            }),
          });
          if (recycleShips > 0) {
            hints.push({
              tone: "ok",
              text: formatMissionHint("fleet_expedition_hint_recycler_aboard", { ships: recycleShips }),
            });
          } else {
            hints.push({ tone: "info", text: formatMissionHint("fleet_expedition_hint_recycler_tip") });
          }
          if (rating.voidrunner_bonus_active) {
            hints.push({
              tone: "ok",
              text: formatMissionHint("fleet_expedition_hint_voidrunner", {
                pct: parseInt(rating.voidrunner_bonus_pct, 10) || 25,
              }),
            });
          }
        }
        hints.push({ tone: "info", text: formatMissionHint("fleet_expedition_hint_events") });
        hints.push({ tone: "info", text: formatMissionHint("fleet_expedition_hint_jackpot") });
        return hints;
      }

      if (mission === "spy") {
        const probes = countShipsByRole(page, ships, "spy");
        hints.push({
          tone: probes > 0 ? "info" : "warn",
          text: probes > 0
            ? formatMissionHint("fleet_mission_hint_spy", { count: probes })
            : formatMissionHint("fleet_mission_hint_spy_none"),
        });
        return hints;
      }

      if (mission === "recycle") {
        const reclaimers = countShipsByRole(page, ships, "recycle");
        const debris = target.debris || {};
        const dm = Math.max(0, parseInt(debris.metal || 0, 10));
        const dc = Math.max(0, parseInt(debris.crystal || 0, 10));
        if (dm + dc <= 0) {
          hints.push({ tone: "warn", text: formatMissionHint("fleet_mission_hint_recycle_no_debris") });
        } else if (reclaimers <= 0) {
          hints.push({ tone: "warn", text: formatMissionHint("fleet_mission_hint_recycle_no_ship") });
        } else {
          hints.push({
            tone: "ok",
            text: formatMissionHint("fleet_mission_hint_recycle_ready", {
              metal: fmtNumber(dm),
              crystal: fmtNumber(dc),
              ships: reclaimers,
            }),
          });
        }
        hints.push({ tone: "info", text: formatMissionHint("fleet_mission_hint_recycle") });
        return hints;
      }

      const genericHints = {
        transport: "fleet_mission_hint_transport",
        collect: "fleet_mission_hint_collect",
        deploy: "fleet_mission_hint_deploy",
        attack: "fleet_mission_hint_attack",
        hold: "fleet_mission_hint_hold",
        colonize: "fleet_mission_hint_colonize",
      };
      if (genericHints[mission]) {
        hints.push({ tone: "info", text: formatMissionHint(genericHints[mission]) });
      }
      return hints;
    };

    const updateMissionFeedback = (page, preview, missionType, ships) => {
      const panel = page.querySelector("[data-fleet-mission-feedback]");
      const textEl = page.querySelector("[data-fleet-mission-feedback-text]");
      if (!panel || !textEl) return;
      const hints = resolveMissionFeedback(page, missionType, preview, ships);
      if (!hints.length || !Object.keys(ships || {}).length) {
        panel.hidden = true;
        textEl.textContent = "";
        panel.className = "fleet-mission-feedback";
        return;
      }
      const primary = hints[0];
      const extra = hints.slice(1).map((h) => h.text).join(" ");
      textEl.textContent = extra ? `${primary.text} ${extra}` : primary.text;
      panel.className = `fleet-mission-feedback is-${primary.tone || "info"}`;
      panel.hidden = false;
    };

    const renderShipChips = (ships) => Object.entries(ships || {})
      .map(([key, qty]) => `<span class="fleet-ship-chip">${shipDisplayName(key)} × ${formatNumber(qty)}</span>`)
      .join("");

    const fleetLegKey = (mv, phase) => mv.status_label || mv.leg_label_key || (
      phase === "returning"
        ? "fleet_leg_returning"
        : phase === "holding"
          ? "fleet_leg_holding"
          : "fleet_leg_outbound"
    );

    const fleetCountdownHtml = (mv) => {
      const countdownAt = Number(mv.countdown_at || 0);
      const homeAt = Number(mv.home_at || 0);
      const phase = mv.phase || mv.leg_phase || mv.status || "";
      const legLabel = tt(fleetLegKey(mv, phase), fleetLegKey(mv, phase));
      const buildTime = (at, scope, keySuffix, srvRem) => {
        const srvAttr = Number.isFinite(srvRem) && srvRem >= 0 ? ` data-server-remaining="${Math.ceil(srvRem)}"` : "";
        return `<time class="fleet-active-countdown gc-mono" data-timer-target="${at}" data-timer-kind="fleet" data-refresh-on-zero="fleet" data-countdown-at="${at}" data-countdown-scope="${scope}" data-countdown-key="${mv.id}:${keySuffix}:${at}"${srvAttr}>–</time>`;
      };
      if (!countdownAt && !homeAt) return "";
      const parts = [];
      if (countdownAt) {
        const srvRem = Number(mv.remaining_seconds);
        parts.push(`<span class="fleet-active-leg">${legLabel}: ${buildTime(countdownAt, "fleet", phase, srvRem)}</span>`);
      }
      if (homeAt > 0 && homeAt !== countdownAt) {
        const homeSrvRem = Number(mv.home_remaining_seconds);
        parts.push(`<span class="fleet-active-home">${tt("fleet_return_at", "Rückkehr")}: ${buildTime(homeAt, "fleet-home", "home", homeSrvRem)}</span>`);
      }
      return parts.join("");
    };

    const patchActiveFleetCards = (page, list) => {
      list.forEach((mv) => {
        const card = page.querySelector(`[data-fleet-id="${mv.id}"]`);
        if (!card) return;
        const phase = mv.phase || mv.leg_phase || mv.status || "";
        const mission = String(mv.mission_type || "custom");
        card.dataset.status = String(mv.status || "");
        card.dataset.leg = phase;
        card.dataset.mission = mission;
        card.className = `fleet-active-card fleet-active-card--${mission}`;
        const statusEl = card.querySelector(".fleet-active-status");
        if (statusEl) _setIfChanged(statusEl, tt(`fleet_status_${mv.status}`, mv.status));
        const missionEl = card.querySelector(".fleet-active-mission");
        if (missionEl) {
          missionEl.className = `fleet-active-mission fleet-active-mission--${mission}`;
          _setIfChanged(missionEl, tt(`fleet_mission_${mv.mission_type}`, mv.mission_type));
        }
        const timesEl = card.querySelector(".fleet-active-times");
        if (!timesEl) return;
        const countdownAt = Number(mv.countdown_at || 0);
        const homeAt = Number(mv.home_at || 0);
        const cdEl = timesEl.querySelector("[data-countdown-scope='fleet']");
        const homeEl = timesEl.querySelector("[data-countdown-scope='fleet-home']");
        const legKey = fleetLegKey(mv, phase);
        const legChanged = !cdEl
          || card.dataset.leg !== phase
          || Number(cdEl.dataset.countdownAt || 0) !== countdownAt
          || String(cdEl.dataset.countdownKey || "") !== `${mv.id}:${phase}:${countdownAt}`
          || (homeAt > 0 && homeAt !== countdownAt && !homeEl)
          || (homeEl && Number(homeEl.dataset.countdownAt || 0) !== homeAt);
        if (legChanged) {
          timesEl.innerHTML = fleetCountdownHtml(mv);
        } else {
          if (cdEl) {
            const srvRem = Number(mv.remaining_seconds);
            if (Number.isFinite(srvRem) && srvRem >= 0) {
              assignMonotonicServerRemaining(cdEl, Math.ceil(srvRem), countdownAt);
            } else {
              delete cdEl.dataset.serverRemaining;
            }
            _setIfChanged(
              cdEl,
              formatCountdownRemain(movementRemainingSeconds(countdownAt, getTimerServerNow(), mv.remaining_seconds))
            );
          }
          if (homeEl) {
            const homeSrvRem = Number(mv.home_remaining_seconds);
            if (Number.isFinite(homeSrvRem) && homeSrvRem >= 0) {
              assignMonotonicServerRemaining(homeEl, Math.ceil(homeSrvRem), homeAt);
            } else {
              delete homeEl.dataset.serverRemaining;
            }
            _setIfChanged(
              homeEl,
              formatCountdownRemain(movementRemainingSeconds(homeAt, getTimerServerNow(), mv.home_remaining_seconds))
            );
          }
        }
      });
    };

    const renderActiveFleets = (page, fleets) => {
      const activeListEl = page.querySelector("[data-fleet-active-list]");
      if (!activeListEl) return;
      const list = Array.isArray(fleets) ? fleets : [];
      if (typeof GC._debugFleetBatch === "object") {
        GC._debugFleetBatch.fleetDomPatches = (GC._debugFleetBatch.fleetDomPatches || 0) + 1;
      }
      if (!list.length) {
        activeListEl.dataset.fleetSig = "";
        _clearMovementCountdownExpiryState();
        activeListEl.innerHTML = `<p class="fleet-empty" data-fleet-empty>${tt("fleet_no_active", "No active fleets.")}</p>`;
        return;
      }

      const signature = list.map((mv) => (
        `${mv.id}:${mv.status}:${mv.phase || mv.leg_phase || ""}:${mv.countdown_at || 0}:${mv.home_at || 0}`
      )).join("|");
      const sigChanged = activeListEl.dataset.fleetSig !== signature;
      if (sigChanged) {
        const scrollParent = activeListEl.closest(".gc-panel, .gc-main, #main-content") || activeListEl;
        const scrollTop = scrollParent.scrollTop || 0;
        const pageScrollY = window.scrollY || window.pageYOffset || 0;
        activeListEl.dataset.fleetSig = signature;
        _clearMovementCountdownExpiryState();
        activeListEl.innerHTML = list.map((mv) => {
        const countdownAt = Number(mv.countdown_at || 0);
        const phase = mv.phase || mv.leg_phase || mv.status || "";
        const mission = String(mv.mission_type || "custom");
        const countdown = fleetCountdownHtml(mv);
        const cargo = [];
        if (mv.resources?.metal) cargo.push(`${tt("resource_metal")}: ${formatNumber(mv.resources.metal)}`);
        if (mv.resources?.crystal) cargo.push(`${tt("resource_crystal")}: ${formatNumber(mv.resources.crystal)}`);
        if (mv.resources?.fuel_cells) cargo.push(`${tt("resource_fuel_cells")}: ${formatNumber(mv.resources.fuel_cells)}`);
        return `<article class="fleet-active-card fleet-active-card--${mission}" data-fleet-id="${mv.id}" data-status="${mv.status}" data-mission="${mission}" data-leg="${phase}">
          <div class="fleet-active-row">
            <span class="fleet-active-mission fleet-active-mission--${mission}">${tt(`fleet_mission_${mv.mission_type}`, mv.mission_type)}</span>
            <span class="fleet-active-status">${tt(`fleet_status_${mv.status}`, mv.status)}</span>
          </div>
          ${renderFleetActiveTargetBlock(mv)}
          <div class="fleet-active-ships">${renderShipChips(mv.ships)}</div>
          ${cargo.length ? `<div class="fleet-active-cargo">${cargo.map((c) => `<span>${c}</span>`).join(" ")}</div>` : ""}
          <div class="fleet-active-times gc-mono">${countdown}</div>
        </article>`;
        }).join("");
        if (scrollParent) scrollParent.scrollTop = scrollTop;
        if (Number.isFinite(pageScrollY)) window.scrollTo(0, pageScrollY);
      } else {
        patchActiveFleetCards(page, list);
      }
      updateMovementCountdowns(getApproxServerNow());
      GC.startProgressTicker();
    };
    GC.renderActiveFleets = renderActiveFleets;

    const renderPresetSelect = (page, presets) => {
      const optionHtml = `<option value="">${tt("fleet_preset_none", "— none —")}</option>` +
        (presets || []).map((p) =>
          `<option value="${p.id}">[${tt(`fleet_preset_type_${p.preset_type}`, p.preset_type)}] ${String(p.name || "").replace(/</g, "&lt;")}</option>`
        ).join("");
      [page.querySelector("[data-fleet-preset-select]"), page.querySelector("[data-fleet-mass-preset]")].forEach((sel) => {
        if (!sel) return;
        const current = sel.value;
        sel.innerHTML = optionHtml;
        if (current) sel.value = current;
        if (typeof GC.rebuildHudSelect === "function") GC.rebuildHudSelect(sel);
        else if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(sel);
      });
    };

    const renderPresetList = (page, presets) => {
      const presetListEl = page.querySelector("[data-fleet-preset-list]");
      if (!presetListEl) return;
      const list = Array.isArray(presets) ? presets : [];
      if (!list.length) {
        presetListEl.innerHTML = `<li class="fleet-preset-empty">${tt("fleet_no_presets", "No presets saved yet.")}</li>`;
        return;
      }
      presetListEl.innerHTML = list.map((p) =>
        `<li class="fleet-preset-item" data-preset-id="${p.id}">
          <span class="fleet-preset-type">${tt(`fleet_preset_type_${p.preset_type}`, p.preset_type)}</span>
          <span class="fleet-preset-name">${String(p.name || "").replace(/</g, "&lt;")}</span>
          <div class="fleet-preset-actions">
            <button type="button" class="gc-btn gc-btn-ghost" data-preset-load="${p.id}">${tt("fleet_preset_load_btn", "Load")}</button>
            <button type="button" class="gc-btn gc-btn-ghost gc-btn-danger" data-preset-delete="${p.id}">${tt("fleet_preset_delete", "Delete")}</button>
          </div>
        </li>`
      ).join("");
    };

    const syncColonyChipsFromCoords = (page) => {
      syncExpeditionMissionTarget(page);
    };

    const applyLiveState = (page, state, opts) => {
      const rt = getFleetRuntime(page);
      if (!state || typeof state !== "object") return;
      // GC-FLEET-PLANET-SWITCH-001: drop stale /api/fleet/state for a previous planet.
      const pagePid = Number(page.dataset.planetId || rt.data?.planet_id || 0);
      const statePid = Number(state.planet_id || 0);
      if (pagePid > 0 && statePid > 0 && pagePid !== statePid) {
        console.debug("[GC] fleet applyLiveState stale planet", { pagePid, statePid });
        return;
      }
      const seq = Number(opts?.seq || 0);
      if (seq > 0) {
        const last = Number(page._fleetApplySeq || 0);
        if (seq < last) return;
        page._fleetApplySeq = seq;
      }
      const st = Number(state.server_time || 0);
      if (st) {
        const lastSt = Number(page._fleetLiveServerTime || 0);
        if (lastSt && st < lastSt - 1) return;
        page._fleetLiveServerTime = Math.max(lastSt, st);
      }
      if (statePid > 0) {
        page.dataset.planetId = String(statePid);
        rt.data.planet_id = statePid;
      }
      if (state.server_time) setServerTime(state.server_time);
      if (state.resources) {
        rt.data.resources = state.resources;
        ["metal", "crystal", "fuel_cells"].forEach((res) => {
          page.querySelectorAll(`[data-res="${res}"]`).forEach((el) => {
            el.textContent = formatNumber(state.resources[res] || 0);
          });
        });
      }
      if (state.ships) {
        rt.data.ships = state.ships;
        const totalShips = Object.values(state.ships).reduce((a, b) => a + (Number(b) || 0), 0);
        rt.data.has_ships = totalShips > 0;
        const noShipsPanel = page.querySelector(".fleet-no-ships-panel");
        const sendForm = page.querySelector("#fleet-send-form");
        if (noShipsPanel) noShipsPanel.hidden = totalShips > 0;
        if (sendForm) sendForm.hidden = totalShips <= 0;
        page.querySelectorAll(".fleet-ship-row").forEach((row) => {
          const key = row.getAttribute("data-ship-key");
          if (!key) return;
          const have = state.ships[key] || 0;
          row.setAttribute("data-ship-have", String(have));
          row.classList.toggle("is-empty", have <= 0);
          row.classList.toggle("fleet-ship-row-empty", have <= 0);
          row.hidden = false;
          const stockEl = row.querySelector(".fleet-ship-card-stock, .fleet-ship-stock, .fleet-ship-tbl-stock");
          if (stockEl) _setIfChanged(stockEl, `×${formatNumber(have)}`);
          const inp = row.querySelector("[data-ship-input]");
          if (inp) {
            inp.max = String(have);
            if (have <= 0) {
              inp.value = "0";
              inp.disabled = true;
            } else {
              inp.disabled = false;
              if (readNumberInput(inp) > have) setNumberInputValue(inp, have);
            }
          }
          const maxBtn = row.querySelector("[data-ship-max]");
          if (maxBtn) maxBtn.disabled = have <= 0;
          const maxImage = row.querySelector("[data-ship-max-image]");
          if (maxImage) maxImage.disabled = have <= 0;
        });
        syncFleetShipPickQtyMarks(page);
      }
      const slotsEl = page.querySelector("[data-fleet-slots]");
      if (state.fleet_slots && slotsEl) {
        slotsEl.textContent = `${state.fleet_slots.active} / ${state.fleet_slots.max}`;
      }
      if (state.active_fleets !== undefined) {
        rt.data.active_fleets = activeFleetsItems(state.active_fleets);
        renderActiveFleets(page, rt.data.active_fleets);
        if (typeof GC.renderGlobalFleetHud === "function") {
          GC.renderGlobalFleetHud(state.active_fleets, {
            reason: "fleet_live_state",
            authoritativeFleetHud: true,
          });
        }
      }
      if (state.mission_locks) {
        rt.data.mission_locks = state.mission_locks;
        if (typeof GC.syncFleetMissionLockUi === "function") GC.syncFleetMissionLockUi(page);
      }
      if (state.presets) {
        rt.data.presets = state.presets;
        renderPresetList(page, state.presets);
        renderPresetSelect(page, state.presets);
      }
    };

    const refreshFleetState = async (page, opts) => {
      const refreshOpts = opts && typeof opts === "object" ? opts : {};
      const force = !!(refreshOpts.force || refreshOpts.reason === "planet_switch");
      const optPlanetId = Number(refreshOpts.planetId || 0);
      const targetPage = page || document.getElementById("fleet-page");
      if (targetPage && optPlanetId > 0) {
        targetPage.dataset.planetId = String(optPlanetId);
        if (targetPage._fleetRt?.data) {
          targetPage._fleetRt.data.planet_id = optPlanetId;
        }
      }
      if (_fleetStateRefreshPromise) {
        _fleetStateRefreshQueued = true;
        // Prefer the latest forced planet-switch target over a bare coalesce.
        if (force || optPlanetId > 0) {
          _fleetStateRefreshQueuedOpts = {
            ...(_fleetStateRefreshQueuedOpts || {}),
            ...refreshOpts,
            ...(optPlanetId > 0 ? { planetId: optPlanetId } : {}),
            ...(force ? { force: true, reason: refreshOpts.reason || "planet_switch" } : {}),
          };
        } else if (!_fleetStateRefreshQueuedOpts) {
          _fleetStateRefreshQueuedOpts = refreshOpts;
        }
        return _fleetStateRefreshPromise;
      }
      if (!targetPage || targetPage.dataset.ready !== "1") {
        return null;
      }
      const seq = ++_fleetRefreshSeq;
      targetPage.dataset.fleetRefreshBusy = "1";
      _fleetStateRefreshPromise = (async () => {
        try {
          const rt = getFleetRuntime(targetPage);
          let planetId = Number(optPlanetId || 0);
          if (!planetId) {
            planetId = parseInt(targetPage.dataset.planetId || rt.data?.planet_id || "0", 10);
          }
          if (!planetId) {
            planetId = Number(GC.lastState?.active_planet_id || 0);
          }
          const q = planetId ? `?planet_id=${planetId}` : "";
          const res = await GC.fetchJSON(`/api/fleet/state${q}`, { cache: "no-store" });
          if (res?.ok) applyLiveState(targetPage, fleetPayload(res), { seq });
          return res;
        } catch (_) {
          return null;
        } finally {
          delete targetPage.dataset.fleetRefreshBusy;
        }
      })().finally(() => {
        _fleetStateRefreshPromise = null;
        if (_fleetStateRefreshQueued) {
          _fleetStateRefreshQueued = false;
          const queuedOpts = _fleetStateRefreshQueuedOpts;
          _fleetStateRefreshQueuedOpts = null;
          const live = document.getElementById("fleet-page");
          if (live && live.dataset.ready === "1") {
            void refreshFleetState(live, queuedOpts || undefined);
          }
        }
      });
      return _fleetStateRefreshPromise;
    };
    GC.refreshFleetState = refreshFleetState;

    GC.scheduleFleetStateRefresh = function scheduleFleetStateRefresh(reason, opts) {
      const reasonStr = String(reason || "fleet_state");
      _fleetStateRefreshReasons.add(reasonStr);
      if (typeof GC._debugFleetBatch === "object") {
        GC._debugFleetBatch.scheduledReasons = Array.from(_fleetStateRefreshReasons);
      }
      const run = () => {
        _fleetStateRefreshTimer = null;
        const reasons = Array.from(_fleetStateRefreshReasons);
        _fleetStateRefreshReasons.clear();
        const fleetPage = document.getElementById("fleet-page");
        if (!fleetPage || fleetPage.dataset.ready !== "1") return Promise.resolve(null);
        if (typeof GC._debugFleetBatch === "object") {
          GC._debugFleetBatch.coalescedReasons = reasons;
        }
        return refreshFleetState(fleetPage);
      };
      if (opts && opts.immediate) {
        if (_fleetStateRefreshTimer) {
          clearTimeout(_fleetStateRefreshTimer);
          _fleetStateRefreshTimer = null;
        }
        return run();
      }
      if (_fleetStateRefreshTimer) return _fleetStateRefreshPromise || Promise.resolve(null);
      _fleetStateRefreshTimer = GC.setSafeTimeout(run, FLEET_STATE_REFRESH_COALESCE_MS);
      return _fleetStateRefreshPromise || Promise.resolve(null);
    };

    const runPreview = async (page) => {
      const rt = getFleetRuntime(page);
      const form = getForm(page);
      if (!form) return;
      const previewCargo = page.querySelector("[data-preview-cargo]");
      const previewCargoFree = page.querySelector("[data-preview-cargo-free]");
      const previewFuel = page.querySelector("[data-preview-fuel]");
      const previewFuelAvail = page.querySelector("[data-preview-fuel-available]");
      const previewFlight = page.querySelector("[data-preview-flight]");
      const previewTargetType = page.querySelector("[data-preview-target-type]");
      const previewTargetOwner = page.querySelector("[data-preview-target-owner]");
      const previewTargetName = page.querySelector("[data-preview-target-name]");
      const previewTargetNativeType = page.querySelector("[data-preview-target-native-type]");
      const previewTargetCoords = page.querySelector("[data-preview-target-coords]");
      const previewTargetHero = page.querySelector("[data-preview-target-hero]");
      const previewMissionStatus = page.querySelector("[data-preview-mission-status]");
      const previewMissionBadge = page.querySelector("[data-preview-mission-badge]");
      const previewArrival = page.querySelector("[data-preview-arrival]");
      const missionFeedback = page.querySelector("[data-fleet-mission-feedback]");
      const sendBtn = page.querySelector("[data-fleet-send-btn]");
      const ships = getShipsSelection(page);
      enforceFleetUrlMissionLock(page);
      const missionType = form.querySelector("[data-fleet-mission]")?.value || "transport";
      const resetPreview = () => {
        rt.lastPreview = null;
        if (previewTargetType) previewTargetType.textContent = "–";
        if (previewTargetOwner) previewTargetOwner.textContent = "–";
        if (previewTargetName) previewTargetName.textContent = "–";
        if (previewTargetNativeType) previewTargetNativeType.textContent = "–";
        if (previewTargetCoords) {
          previewTargetCoords.textContent = "–";
          previewTargetCoords.hidden = true;
        }
        if (previewTargetHero) previewTargetHero.classList.add("is-empty");
        if (previewMissionStatus) {
          previewMissionStatus.textContent = "–";
          previewMissionStatus.classList.remove("is-ok", "is-blocked");
        }
        if (previewMissionBadge) previewMissionBadge.textContent = "–";
        if (previewCargo) previewCargo.textContent = "–";
        if (previewCargoFree) previewCargoFree.textContent = "–";
        if (previewFuel) previewFuel.textContent = "–";
        if (previewFuelAvail) previewFuelAvail.textContent = "–";
        if (previewFlight) previewFlight.textContent = "–";
        if (previewArrival) {
          delete previewArrival.dataset.timerTarget;
          delete previewArrival.dataset.countdownAt;
          delete previewArrival.dataset.timerKind;
          previewArrival.textContent = "–";
        }
        if (missionFeedback) {
          missionFeedback.hidden = true;
          missionFeedback.className = "fleet-mission-feedback";
          const fbText = missionFeedback.querySelector("[data-fleet-mission-feedback-text]");
          if (fbText) fbText.textContent = "";
        }
        const previewDailyRow = page.querySelector("[data-preview-expedition-daily-row]");
        if (previewDailyRow) hideExpeditionDailyEfficiencyBlock(previewDailyRow);
        if (sendBtn) sendBtn.disabled = true;
      };
      if (!Object.keys(ships).length) {
        resetPreview();
        return;
      }
      try {
        const originId = resolveFleetOriginPlanetId(page);
        const domPlanetId = getDomPlanetId();
        const res = await GC.fetchJSON("/api/fleet/preview", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Requested-With": "XMLHttpRequest",
            ...(domPlanetId ? { "X-GC-Dom-Planet-Id": String(domPlanetId) } : {}),
          },
          body: JSON.stringify({
            origin_planet_id: originId,
            ships,
            resources: getResourcesSelection(page),
            speed_percent: parseInt(form.querySelector("[data-fleet-speed]")?.value || "100", 10),
            mission_type: missionType,
            expedition_hours: getExpeditionHoursSelection(page),
            ...getTargetCoords(page),
            ...buildFleetTargetPayload(page),
          }),
        });
        const p = fleetPayload(res).preview || res.preview;
        if (res?.ok && p) {
          rt.lastPreview = p;
          const target = p.target || {};
          const named = applyFleetPreviewNamedTarget(page, target, target.coords);
          if (previewTargetType) {
            previewTargetType.textContent = named.typeLabel
              || (target.target_type ? tt(`fleet_target_${target.target_type}`, target.target_type) : "–");
          }
          if (previewTargetOwner) {
            previewTargetOwner.textContent = named.name || "–";
          }
          const debrisRow = page.querySelector("[data-preview-debris-row]");
          const previewDebris = page.querySelector("[data-preview-debris]");
          if (debrisRow && previewDebris) {
            const showDebris = missionType === "recycle";
            debrisRow.hidden = !showDebris;
            if (showDebris) previewDebris.textContent = formatDebrisPreview(target.debris);
          }
          syncMissionAllowlistFromTarget(page, target);
          const lockedMission = enforceFleetUrlMissionLock(page) || missionType;
          const wk = getFleetWorldKey(page);
          if (wk) {
            if (target.world_target?.target_type) {
              page.dataset.fleetNativeTargetType = String(target.world_target.target_type);
            }
            const presentation = resolveFleetWorldTargetPresentation(target);
            if (presentation) {
              renderFleetWorldTargetPanel(page, presentation, {
                mission: lockedMission,
                flightLabel: formatFleetDuration(p.duration_seconds ?? p.flight_seconds ?? 0),
              });
            }
            syncFleetWorldTargetUi(page);
          } else if (target.strategic_world) {
            renderFleetWorldTargetPanel(page, target.strategic_world, { mission: lockedMission });
          } else {
            hideFleetWorldTargetPanel(page);
          }
          updateFleetFormMode(page);
          if (previewMissionBadge) {
            previewMissionBadge.textContent = tt(`fleet_mission_${lockedMission}`, lockedMission);
          }
          if (previewMissionStatus) {
            previewMissionStatus.classList.remove("is-ok", "is-blocked");
            if (p.can_send) {
              previewMissionStatus.textContent = tt("fleet_preview_mission_ok", "Mission allowed");
              previewMissionStatus.classList.add("is-ok");
            } else {
              const reason = p.block_reason || p.mission_block_reason || "generic";
              previewMissionStatus.textContent = reasonText(reason, p);
              previewMissionStatus.classList.add("is-blocked");
            }
          }
          const previewHud = page.querySelector("[data-fleet-preview]");
          if (previewHud) {
            previewHud.classList.toggle(
              "is-expedition",
              lockedMission === "expedition"
                && (target.target_type === "expedition_slot" || target.target_type === "strategic_world")
            );
            previewHud.classList.toggle("is-ready", !!p.can_send);
            previewHud.classList.toggle("is-blocked", !p.can_send);
          }
          updateMissionFeedback(page, p, lockedMission, ships);
          if (previewCargo) {
            previewCargo.textContent = `${formatNumber(p.cargo_used || 0)} / ${formatNumber(p.cargo_total || 0)}`;
          }
          if (previewCargoFree) previewCargoFree.textContent = formatNumber(p.cargo_free || 0);
          if (previewFuel) previewFuel.textContent = formatNumber(p.fuel_cost || 0);
          if (previewFuelAvail) {
            previewFuelAvail.textContent = formatNumber(p.fuel_available ?? rt.data.resources?.fuel_cells ?? 0);
          }
          if (previewFlight) {
            const legSec = p.duration_seconds ?? p.flight_seconds ?? 0;
            const totalSec = lockedMission === "expedition" && p.expedition_total_seconds
              ? p.expedition_total_seconds
              : legSec;
            previewFlight.textContent = formatCountdownRemain(totalSec);
          }
          if (previewArrival) {
            delete previewArrival.dataset.timerTarget;
            delete previewArrival.dataset.countdownAt;
            delete previewArrival.dataset.timerKind;
            const flightSec = p.duration_seconds ?? p.flight_seconds ?? 0;
            previewArrival.textContent = flightSec > 0 ? formatCountdownRemain(flightSec) : "–";
          }
          if (sendBtn) sendBtn.disabled = !p.can_send;
          updateFleetTargetInlineError(page, null);
          if (p.expedition_daily) syncExpeditionDailyEfficiencyUi(page, p.expedition_daily);
        } else {
          resetPreview();
        }
      } catch (_) {
        resetPreview();
      }
    };

    const schedulePreview = (page) => {
      enforceFleetUrlMissionLock(page);
      const rt = getFleetRuntime(page);
      if (rt.previewTimer) clearTimeout(rt.previewTimer);
      rt.previewTimer = setTimeout(() => runPreview(page), 300);
    };

    const loadPresetById = (page, presetId) => {
      const rt = getFleetRuntime(page);
      const form = getForm(page);
      const preset = (rt.data.presets || []).find((p) => String(p.id) === String(presetId));
      if (!preset || !form) return;
      page.querySelectorAll("[data-ship-input]").forEach((inp) => { inp.value = "0"; });
      Object.entries(preset.ships || {}).forEach(([key, qty]) => {
        const inp = form.querySelector(`[data-ship-input="${key}"]`);
        if (inp) inp.value = String(qty);
      });
      if (preset.speed_percent) {
        const sp = form.querySelector("[data-fleet-speed]");
        if (sp) {
          sp.value = String(preset.speed_percent);
          GC.syncHudSelect(sp);
        }
      }
      if (preset.mission_type) {
        const ms = form.querySelector("[data-fleet-mission]");
        if (ms) {
          ms.value = preset.mission_type;
          GC.syncHudSelect(ms);
        }
      }
      if (preset.target_galaxy != null) form.querySelector('[name="target_galaxy"]').value = String(preset.target_galaxy);
      if (preset.target_system != null) form.querySelector('[name="target_system"]').value = String(preset.target_system);
      if (preset.target_position != null) form.querySelector('[name="target_position"]').value = String(preset.target_position);
      syncExpeditionMissionTarget(page);
      scheduleTargetResolve(page);
      syncFleetShipPickQtyMarks(page);
      schedulePreview(page);
      scheduleMassExpoSplitPreview(page);
    };

    const pickDefaultFleetTargetIfNeeded = (page) => {
      const params = getFleetUrlParams();
      if (params.has("world_key") || params.get("mission")) {
        return;
      }
      if (
        params.has("target_galaxy")
        && params.has("target_system")
        && params.has("target_position")
      ) {
        return;
      }
      const rt = getFleetRuntime(page);
      const origin = rt.data?.coordinates || {};
      const target = getTargetCoords(page);
      const og = parseInt(origin.galaxy, 10);
      const os = parseInt(origin.system, 10);
      const op = parseInt(origin.position, 10);
      if (
        og !== target.target_galaxy
        || os !== target.target_system
        || op !== target.target_position
      ) {
        return;
      }
      const quickSel = page.querySelector("[data-fleet-quick-target-select]");
      const altOption = quickSel
        ? Array.from(quickSel.options).find((opt) => opt.value && !opt.getAttribute("data-active"))
        : null;
      if (altOption) {
        applyQuickTarget(page, altOption);
        return;
      }
      const expo = page.querySelector("[data-fleet-expedition-shortcut]");
      if (expo) applyQuickTarget(page, expo);
    };

    const isFleetQuickTargetManual = (page) => page?.dataset?.fleetQuickManual === "1";

    const clearQuickTargetToManual = (page) => {
      if (!page) return;
      page.dataset.fleetQuickManual = "1";
      const quickSel = page.querySelector("[data-fleet-quick-target-select]");
      if (quickSel) {
        quickSel.value = "";
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(quickSel);
      }
    };

    const applyQuickTarget = (page, target) => {
      const form = getForm(page);
      if (!form || !target) return;
      delete page.dataset.fleetQuickManual;
      const readAttr = (key) => target.getAttribute(key) || target.dataset?.[key] || "";
      const g = form.querySelector('[name="target_galaxy"]');
      const s = form.querySelector('[name="target_system"]');
      const p = form.querySelector('[name="target_position"]');
      if (g) g.value = readAttr("data-galaxy");
      if (s) s.value = readAttr("data-system");
      if (p) p.value = readAttr("data-position");
      const mission = readAttr("data-mission");
      const ms = form.querySelector("[data-fleet-mission]");
      if (mission && ms && !isFleetUrlPrefillLocked(page)) {
        ms.value = mission;
        GC.syncHudSelect(ms);
        setColonizeRowVisible(page, mission);
      } else if (ms && ms.value === "expedition" && !isFleetUrlPrefillLocked(page)) {
        ms.value = "transport";
        GC.syncHudSelect(ms);
        setColonizeRowVisible(page, "transport");
      }
      if (!isFleetUrlPrefillLocked(page)) {
        delete page.dataset.fleetUrlMission;
        clearFleetWorldKey(page);
      }
      const quickSel = page.querySelector("[data-fleet-quick-target-select]");
      if (quickSel && target.tagName === "OPTION") {
        quickSel.value = target.value || "";
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(quickSel);
      } else if (quickSel && !mission) {
        let matched = "";
        const cg = parseInt(readAttr("data-galaxy") || "0", 10);
        const cs = parseInt(readAttr("data-system") || "0", 10);
        const cp = parseInt(readAttr("data-position") || "0", 10);
        Array.from(quickSel.options).forEach((opt) => {
          if (!opt.value) return;
          const og = parseInt(opt.getAttribute("data-galaxy") || "0", 10);
          const os = parseInt(opt.getAttribute("data-system") || "0", 10);
          const op = parseInt(opt.getAttribute("data-position") || "0", 10);
          if (og === cg && os === cs && op === cp) matched = opt.value;
        });
        quickSel.value = matched;
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(quickSel);
      } else if (quickSel && mission) {
        quickSel.value = "";
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(quickSel);
      }
      syncExpeditionMissionTarget(page);
      scheduleTargetResolve(page);
      schedulePreview(page);
    };

    GC.scheduleFleetPreview = schedulePreview;
    GC.scheduleFleetTargetResolve = scheduleTargetResolve;
    GC.runFleetTargetResolve = runTargetResolve;
    GC.syncColonyChipsFromCoords = syncColonyChipsFromCoords;
    GC.syncExpeditionMissionTarget = syncExpeditionMissionTarget;
    GC.updateFleetFormMode = updateFleetFormMode;
    GC.refreshFleetState = refreshFleetState;
    GC.runFleetPreview = runPreview;
    GC.applyFleetUrlPrefill = applyFleetUrlPrefill;
    GC.setFleetShipInputValue = setFleetShipInputValue;
    GC.pickDefaultFleetTargetIfNeeded = pickDefaultFleetTargetIfNeeded;
    GC.getFleetWorldKey = getFleetWorldKey;
    GC.clearFleetWorldKey = clearFleetWorldKey;
    GC.syncFleetWorldTargetUi = syncFleetWorldTargetUi;
    GC.renderFleetWorldTargetPanel = renderFleetWorldTargetPanel;
    GC.loadFleetWorldTargetPreview = loadFleetWorldTargetPreview;
    GC.enforceFleetUrlMissionLock = enforceFleetUrlMissionLock;
    GC.buildFleetTargetPayload = buildFleetTargetPayload;
    GC.syncFleetMissionLockUi = syncFleetMissionLockUi;
    GC.resolveFleetWorldTargetPresentation = resolveFleetWorldTargetPresentation;

    const formatMassExpoShipLine = (ships) => {
      const parts = Object.entries(ships || {})
        .map(([key, qty]) => [key, parseInt(qty, 10) || 0])
        .filter(([, qty]) => qty > 0)
        .sort((a, b) => b[1] - a[1])
        .map(([key, qty]) => `${formatNumber(qty)} ${shipDisplayName(key)}`);
      return parts.length ? parts.join(" · ") : "—";
    };

    let massExpoSplitPreviewTimer = null;
    const scheduleMassExpoSplitPreview = (page) => {
      if (!page?.querySelector("[data-fleet-mass-expo-split]")) return;
      if (massExpoSplitPreviewTimer) clearTimeout(massExpoSplitPreviewTimer);
      massExpoSplitPreviewTimer = GC.setSafeTimeout(() => {
        massExpoSplitPreviewTimer = null;
        updateMassExpoSplitPreview(page);
      }, 250);
    };

    const updateMassExpoSplitPreview = async (page) => {
      const panel = page?.querySelector("[data-fleet-mass-expo-split]");
      if (!panel) return;
      const freeEl = panel.querySelector("[data-fleet-mass-expo-free-slots]");
      const usableEl = panel.querySelector("[data-fleet-mass-expo-usable-slots]");
      const reservedEl = panel.querySelector("[data-fleet-mass-expo-reserved-slots]");
      const perFleetEl = panel.querySelector("[data-fleet-mass-expo-per-fleet]");
      const leftoverEl = panel.querySelector("[data-fleet-mass-expo-leftover]");
      const statusEl = panel.querySelector("[data-fleet-mass-expo-split-status]");
      const submitBtn = panel.querySelector("[data-fleet-mass-expo-split-submit]");
      const ships = getShipsSelection(page);

      const setStatus = (msg, { hidden = false } = {}) => {
        if (!statusEl) return;
        statusEl.textContent = msg || "";
        statusEl.hidden = hidden || !msg;
      };

      const clearSlotPreview = () => {
        if (freeEl) freeEl.textContent = "—";
        if (usableEl) usableEl.textContent = "—";
        if (reservedEl) reservedEl.textContent = "—";
        if (perFleetEl) perFleetEl.textContent = "—";
        if (leftoverEl) leftoverEl.textContent = "—";
      };

      if (!Object.keys(ships).length) {
        clearSlotPreview();
        setStatus("", { hidden: true });
        if (submitBtn) submitBtn.disabled = true;
        return;
      }

      try {
        const originId = resolveFleetOriginPlanetId(page);
        const res = await GC.fetchGameAction("/api/fleet/mass-expedition/preview", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ origin_planet_id: originId, ships }),
        });
        const data = fleetPayload(res);
        const preview = data && typeof data === "object" ? data : {};
        const freeSlots = parseInt(preview.free_slots, 10);
        const usableSlots = parseInt(preview.usable_slots, 10);
        const reservedSlots = parseInt(preview.reserved_slots, 10);
        if (freeEl) freeEl.textContent = Number.isFinite(freeSlots) ? String(freeSlots) : "0";
        if (usableEl) usableEl.textContent = Number.isFinite(usableSlots) ? String(usableSlots) : "0";
        if (reservedEl) {
          reservedEl.textContent = Number.isFinite(reservedSlots) ? String(reservedSlots) : "3";
        }
        if (perFleetEl) perFleetEl.textContent = formatMassExpoShipLine(preview.per_fleet_ships);
        if (leftoverEl) leftoverEl.textContent = formatMassExpoShipLine(preview.leftover_ships);

        if (res?.ok) {
          setStatus("", { hidden: true });
          if (submitBtn) submitBtn.disabled = false;
          if (preview.expedition_daily) syncExpeditionDailyEfficiencyUi(page, preview.expedition_daily);
          return;
        }

        const reason = res?.error || res?.reason || "generic";
        let msg = reasonText(reason);
        if (reason === "fleet_slots_full") {
          msg = tt("fleet_mass_expo_split_no_slots", "No free fleet slots available.");
        } else if (reason === "mass_expo_slots_reserved") {
          msg = tt(
            "fleet_mass_expo_split_slots_reserved",
            "Usable mass-expedition slots are 0 — %(reserved)s slots stay reserved."
          ).replace("%(reserved)s", Number.isFinite(reservedSlots) ? String(reservedSlots) : "3");
        } else if (reason === "mass_expo_split_too_small" || reason === "mass_expo_no_expedition_ships") {
          msg = tt(
            "fleet_mass_expo_split_too_small",
            "Select enough expedition ships for at least one expedition per slot."
          );
        }
        setStatus(msg);
        if (submitBtn) submitBtn.disabled = true;
      } catch (_) {
        setStatus(reasonText("generic"));
        if (submitBtn) submitBtn.disabled = true;
      }
    };

    GC.scheduleMassExpoSplitPreview = scheduleMassExpoSplitPreview;
    GC.updateMassExpoSplitPreview = updateMassExpoSplitPreview;

    const submitMassExpeditionSplit = async (page) => {
      const panel = page?.querySelector("[data-fleet-mass-expo-split]");
      const submitBtn = panel?.querySelector("[data-fleet-mass-expo-split-submit]");
      if (!panel || !submitBtn || panel.dataset.submitting === "1" || submitBtn.disabled) return;
      panel.dataset.submitting = "1";
      submitBtn.disabled = true;
      const ships = getShipsSelection(page);
      if (!Object.keys(ships).length) {
        showNotify(tt("fleet_no_ships_selected", "No ships selected."), "error");
        delete panel.dataset.submitting;
        submitBtn.disabled = false;
        return;
      }
      try {
        const originId = resolveFleetOriginPlanetId(page);
        const requestId =
          typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
            ? crypto.randomUUID()
            : `mass-expo-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
        const res = await GC.fetchGameAction("/api/fleet/mass-expedition", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            origin_planet_id: originId,
            ships,
            request_id: requestId,
          }),
        });
        if (res?.ok) {
          const data = fleetPayload(res);
          const started = parseInt(data.started_count, 10) || (data.started || []).length;
          // Soft-success with zero fleets is a failure (fuel/slots) — keep ship selection.
          if (!(started > 0)) {
            const skipped = Array.isArray(data.skipped) ? data.skipped : [];
            const skipReason = skipped[0]?.reason || res?.error || res?.reason || "send_failed";
            showNotify(reasonText(skipReason), "error");
            scheduleMassExpoSplitPreview(page);
            return;
          }
          showNotify(
            tt("fleet_mass_expo_split_success", "%(count)s expeditions launched.")
              .replace("%(count)s", String(started)),
            "success"
          );
          if (res.state) applyActionState(res, "fleet_mass_expo_success");
          await refreshFleetState(page);
          page.querySelectorAll("[data-ship-input]").forEach((inp) => { inp.value = "0"; });
          syncFleetShipPickQtyMarks(page);
          schedulePreview(page);
          scheduleMassExpoSplitPreview(page);
        } else {
          const reason = res?.error || res?.reason || "generic";
          let msg = reasonText(reason);
          if (reason === "fleet_slots_full") {
            msg = tt("fleet_mass_expo_split_no_slots", "No free fleet slots available.");
          } else if (reason === "mass_expo_slots_reserved") {
            msg = tt(
              "fleet_mass_expo_split_slots_reserved",
              "Usable mass-expedition slots are 0 — %(reserved)s slots stay reserved."
            ).replace("%(reserved)s", "3");
          } else if (reason === "mass_expo_split_too_small" || reason === "mass_expo_no_expedition_ships") {
            msg = tt(
              "fleet_mass_expo_split_too_small",
              "Select enough expedition ships for at least one expedition per slot."
            );
          }
          showNotify(msg, "error");
          scheduleMassExpoSplitPreview(page);
        }
      } catch (_) {
        showNotify(reasonText("generic"), "error");
      } finally {
        delete panel.dataset.submitting;
        scheduleMassExpoSplitPreview(page);
      }
    };

    const submitMassExpedition = async (page) => {
      const massForm = page?.querySelector("#fleet-mass-expo-form");
      if (!massForm || massForm.dataset.submitting === "1") return;
      massForm.dataset.submitting = "1";
      const massBtn = massForm.querySelector("[data-fleet-mass-expo-submit]");
      const massResult = page.querySelector("[data-fleet-mass-result]");
      if (massBtn) massBtn.disabled = true;
      if (massResult) { massResult.hidden = true; massResult.textContent = ""; }
      const presetId = page.querySelector("[data-fleet-mass-preset]")?.value;
      const waves = parseInt(page.querySelector("[data-fleet-mass-waves]")?.value || "1", 10);
      if (!presetId) {
        showNotify(tt("fleet_preset_none", "No preset selected."), "error");
        massForm.dataset.submitting = "0";
        if (massBtn) massBtn.disabled = false;
        return;
      }
      try {
        const originId = resolveFleetOriginPlanetId(page);
        const res = await GC.fetchGameAction("/api/fleet/mass-expedition", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            origin_planet_id: originId,
            preset_id: parseInt(presetId, 10),
            waves,
          }),
        });
        if (res?.ok) {
          const data = fleetPayload(res);
          const started = parseInt(data.started_count, 10) || (data.started || []).length;
          const skipped = (data.skipped || []).length;
          if (massResult) {
            massResult.textContent = tt("fleet_mass_expo_result", "Started %(started)s, skipped %(skipped)s.")
              .replace("%(started)s", String(started)).replace("%(skipped)s", String(skipped));
            massResult.hidden = false;
          }
          if (!(started > 0)) {
            const firstReason = String(data.skipped?.[0]?.reason || res?.error || res?.reason || "send_failed");
            showNotify(reasonText(firstReason), "error");
            return;
          }
          showNotify(tt("fleet_mass_expo_success", "Mass expedition launched."), "success");
          if (res.state) applyActionState(res, "fleet_mass_expo_success");
          await refreshFleetState(page);
          schedulePreview(page);
        } else {
          showNotify(reasonText(apiError(res)), "error");
        }
      } catch (_) {
        showNotify(reasonText("generic"), "error");
      } finally {
        massForm.dataset.submitting = "0";
        if (massBtn) massBtn.disabled = false;
      }
    };

    document.addEventListener("mouseover", (e) => {
      const page = getPage();
      if (!page || isCoarsePointer()) return;
      const trigger = e.target.closest("[data-fleet-ship-pick-trigger]");
      if (!trigger || !page.contains(trigger)) return;
      const card = trigger.closest(".fleet-ship-card--pick");
      if (!card) return;
      showFleetShipPickTooltip(trigger, card);
    });

    document.addEventListener("mouseout", (e) => {
      const trigger = e.target.closest("[data-fleet-ship-pick-trigger]");
      if (!trigger || _fleetShipPickTooltipTrigger !== trigger) return;
      const to = e.relatedTarget;
      if (to && trigger.contains(to)) return;
      hideFleetShipPickTooltip();
    });

    document.addEventListener("scroll", hideFleetShipPickTooltip, true);
    window.addEventListener("resize", hideFleetShipPickTooltip);
    if (typeof GC.registerCleanup === "function") {
      GC.registerCleanup(hideFleetShipPickTooltip);
    }

    document.addEventListener("click", async (e) => {
      const page = getPage();
      if (!page) return;
      const rt = getFleetRuntime(page);
      const form = getForm(page);
      const fuelResource = rt.data.fuel_resource || page.dataset.fuelResource || "fuel_cells";

      const pickTrigger = e.target.closest("[data-fleet-ship-pick-trigger]");
      if (pickTrigger && page.contains(pickTrigger) && isCoarsePointer()) {
        const card = pickTrigger.closest(".fleet-ship-card--pick");
        if (_fleetShipPickTooltipTrigger === pickTrigger) {
          hideFleetShipPickTooltip();
        } else if (card) {
          showFleetShipPickTooltip(pickTrigger, card);
        }
        e.preventDefault();
        return;
      }

      if (isCoarsePointer() && page.contains(e.target) && !e.target.closest("[data-fleet-ship-pick-trigger]")) {
        hideFleetShipPickTooltip();
      }

      const maxShip = e.target.closest("[data-ship-max]");
      if (maxShip && page.contains(maxShip)) {
        e.preventDefault();
        const key = maxShip.getAttribute("data-ship-max");
        const row = maxShip.closest("[data-ship-key]");
        const have = parseIntNumber(row?.getAttribute("data-ship-have") || "0");
        const inp = form?.querySelector(`[data-ship-input="${key}"]`);
        if (inp) setFleetShipInputValue(page, inp, have);
        return;
      }

      const maxShipImage = e.target.closest("[data-ship-max-image]");
      if (maxShipImage && page.contains(maxShipImage)) {
        e.preventDefault();
        const key = maxShipImage.getAttribute("data-ship-max-image");
        const row = maxShipImage.closest("[data-ship-key]");
        const have = parseIntNumber(row?.getAttribute("data-ship-have") || "0");
        const inp = form?.querySelector(`[data-ship-input="${key}"]`);
        if (inp && have > 0) setFleetShipInputValue(page, inp, have);
        return;
      }

      const resMax = e.target.closest("[data-fleet-res-max]");
      if (resMax && page.contains(resMax)) {
        e.preventDefault();
        const res = resMax.getAttribute("data-fleet-res-max");
        if (!rt.lastPreview) await runPreview(page);
        const cargoFree = parseInt(rt.lastPreview?.cargo_free ?? "0", 10) || 0;
        const bal = rt.data.resources?.[res] || 0;
        let val = Math.min(bal, cargoFree > 0 ? cargoFree : bal);
        // DOM attrs use hyphens (data-fleet-res-fuel-cells); API keys use underscores.
        const resAttr = String(res || "").replace(/_/g, "-");
        const inp = page.querySelector(`[data-fleet-res-${resAttr}]`);
        if (inp) setNumberInputValue(inp, Math.max(0, val));
        schedulePreview(page);
        return;
      }

      const expoShortcut = e.target.closest("[data-fleet-expedition-shortcut]");
      if (expoShortcut && page.contains(expoShortcut)) {
        e.preventDefault();
        applyQuickTarget(page, expoShortcut);
        return;
      }

      const loadBtn = e.target.closest("[data-preset-load]");
      if (loadBtn && page.contains(loadBtn)) {
        e.preventDefault();
        loadPresetById(page, loadBtn.getAttribute("data-preset-load"));
        return;
      }

      const delBtn = e.target.closest("[data-preset-delete]");
      if (delBtn && page.contains(delBtn)) {
        e.preventDefault();
        const id = delBtn.getAttribute("data-preset-delete");
        if (!id || !window.confirm(tt("fleet_preset_delete_confirm", "Delete this preset?"))) return;
        try {
          const res = await GC.fetchGameAction(`/api/fleet/presets/${id}`, { method: "DELETE" });
          if (res?.ok) {
            showNotify(tt("fleet_preset_deleted", "Preset deleted."), "success");
            rt.data.presets = (rt.data.presets || []).filter((p) => String(p.id) !== String(id));
            renderPresetList(page, rt.data.presets);
            renderPresetSelect(page, rt.data.presets);
          } else {
            showNotify(reasonText(apiError(res)), "error");
          }
        } catch (_) {
          showNotify(reasonText("generic"), "error");
        }
        return;
      }

      const savePreset = e.target.closest("[data-fleet-save-preset]");
      if (savePreset && page.contains(savePreset)) {
        e.preventDefault();
        const name = window.prompt(tt("fleet_preset_name_prompt", "Preset name:"));
        if (!name || !name.trim()) return;
        const type = window.prompt(tt("fleet_preset_type_prompt", "Type (raid/farm/spy/transport/deploy/expedition/custom):"), "custom") || "custom";
        try {
          const res = await GC.fetchGameAction("/api/fleet/presets", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              name: name.trim(),
              preset_type: type.trim().toLowerCase(),
              ships_json: getShipsSelection(page),
              resources_json: getResourcesSelection(page),
              speed_percent: parseInt(form.querySelector("[data-fleet-speed]")?.value || "100", 10),
              mission_type: form.querySelector("[data-fleet-mission]")?.value,
              ...getTargetCoords(page),
            }),
          });
          if (res?.ok) {
            showNotify(tt("fleet_preset_saved", "Preset saved."), "success");
            const preset = fleetPayload(res).preset;
            if (preset) {
              rt.data.presets = [preset, ...(rt.data.presets || []).filter((p) => p.id !== preset.id)];
              renderPresetList(page, rt.data.presets);
              renderPresetSelect(page, rt.data.presets);
            } else {
              await refreshFleetState(page);
            }
          } else {
            showNotify(reasonText(apiError(res)), "error");
          }
        } catch (_) {
          showNotify(reasonText("generic"), "error");
        }
        return;
      }

      const massExpoBtn = e.target.closest("[data-fleet-mass-expo-submit]");
      if (massExpoBtn && page.contains(massExpoBtn)) {
        e.preventDefault();
        submitMassExpedition(page);
        return;
      }

      const massExpoSplitBtn = e.target.closest("[data-fleet-mass-expo-split-submit]");
      if (massExpoSplitBtn && page.contains(massExpoSplitBtn)) {
        e.preventDefault();
        submitMassExpeditionSplit(page);
        return;
      }

    });

    document.addEventListener("change", (e) => {
      const page = getPage();
      if (!page) return;
      if (e.target.matches("[data-fleet-preset-select]")) {
        const id = e.target.value;
        if (id) loadPresetById(page, id);
        return;
      }
      if (e.target.matches("[data-fleet-mission]")) {
        delete page.dataset.fleetUrlMission;
        setColonizeRowVisible(page, e.target.value);
        if (e.target.value === "expedition" && !getFleetWorldKey(page)) applyExpeditionTarget(page);
        syncExpeditionMissionTarget(page);
        updateFleetFormMode(page);
        const wk = getFleetWorldKey(page);
        if (wk) loadFleetWorldTargetPreview(page, wk);
        scheduleTargetResolve(page);
        schedulePreview(page);
      }
      if (e.target.matches("[data-fleet-quick-target-select]")) {
        const opt = e.target.options[e.target.selectedIndex];
        if (opt && opt.value) applyQuickTarget(page, opt);
        else {
          clearQuickTargetToManual(page);
          syncExpeditionMissionTarget(page);
          scheduleTargetResolve(page);
          schedulePreview(page);
        }
        return;
      }
      if (e.target.matches('[name="target_galaxy"], [name="target_system"], [name="target_position"]')) {
        if (!isFleetUrlPrefillLocked(page)) {
          delete page.dataset.fleetUrlMission;
          clearFleetWorldKey(page);
        }
        clearQuickTargetToManual(page);
        syncExpeditionMissionTarget(page);
        scheduleTargetResolve(page);
      }
      if (e.target.closest("#fleet-send-form")) {
        if (e.target.matches("[data-ship-input]")) {
          syncFleetShipPickQtyMarks(page);
          scrollFleetShipInputEnd(e.target);
        }
        schedulePreview(page);
        scheduleMassExpoSplitPreview(page);
      }
    });

    document.addEventListener("focusin", (e) => {
      const page = getPage();
      if (!page || !page.contains(e.target)) return;
      if (e.target.matches(".fleet-ship-pick-value [data-ship-input]")) {
        hideFleetShipPickTooltip();
      }
      if (e.target.matches(".fleet-ship-card--pick [data-ship-input]")) {
        scrollFleetShipInputEnd(e.target);
      }
    });

    document.addEventListener("input", (e) => {
      const page = getPage();
      if (!page) return;
      if (e.target.matches('[name="target_galaxy"], [name="target_system"], [name="target_position"]')) {
        if (!isFleetUrlPrefillLocked(page)) {
          delete page.dataset.fleetUrlMission;
          clearFleetWorldKey(page);
        }
        clearQuickTargetToManual(page);
        syncExpeditionMissionTarget(page);
        scheduleTargetResolve(page);
      }
      if (e.target.closest("#fleet-send-form")) {
        if (e.target.matches("[data-ship-input]")) {
          syncFleetShipPickQtyMarks(page);
          scrollFleetShipInputEnd(e.target);
        }
        schedulePreview(page);
        scheduleMassExpoSplitPreview(page);
      }
    });

    document.addEventListener("submit", async (e) => {
      const page = getPage();
      if (e.target?.closest?.("#fleet-mass-expo-form")) {
        e.preventDefault();
        if (page) submitMassExpedition(page);
        return;
      }
      const sendForm = e.target.closest ? e.target.closest("#fleet-send-form") : null;
      if (sendForm && page && page.contains(sendForm)) {
        e.preventDefault();
        e.stopPropagation();
        const rt = getFleetRuntime(page);
        const form = sendForm;
        if (rt.sending) return;
        const errorEl = page.querySelector("[data-fleet-error]");
        if (errorEl) { errorEl.hidden = true; errorEl.textContent = ""; }
        const submitBtn = form.querySelector(".fleet-send-submit") || form.querySelector("[data-fleet-send-btn]");
        rt.sending = true;
        setProgressionActionBusy(submitBtn, true);
        if (!rt.lastPreview?.can_send) {
          await runPreview(page);
        }
        if (!rt.lastPreview?.can_send) {
          if (errorEl) {
            errorEl.textContent = reasonText(rt.lastPreview?.block_reason || "generic", rt.lastPreview);
            errorEl.hidden = false;
          }
          rt.sending = false;
          setProgressionActionBusy(submitBtn, false);
          if (submitBtn) submitBtn.disabled = !rt.lastPreview?.can_send;
          return;
        }
        try {
          enforceFleetUrlMissionLock(page);
          const originId = resolveFleetOriginPlanetId(page);
          const domPlanetId = getDomPlanetId();
          const res = await GC.fetchGameAction("/api/fleet/send", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              ...(domPlanetId ? { "X-GC-Dom-Planet-Id": String(domPlanetId) } : {}),
            },
            body: JSON.stringify({
              origin_planet_id: originId,
              ships: getShipsSelection(page),
              resources: getResourcesSelection(page),
              speed_percent: parseInt(form.querySelector("[data-fleet-speed]")?.value || "100", 10),
              mission_type: form.querySelector("[data-fleet-mission]")?.value,
              expedition_hours: getExpeditionHoursSelection(page),
              colony_name: form.querySelector("[data-fleet-colony-name]")?.value || undefined,
              ...getTargetCoords(page),
              ...buildFleetTargetPayload(page),
            }),
          });
          if (res?.ok) {
            showNotify(tt("fleet_send_success", "Fleet dispatched."), "success");
            const payload = fleetPayload(res);
            applyLiveState(page, {
              resources: payload.updated_resources,
              ships: payload.updated_ships,
              fleet_slots: payload.active_slots,
            });
            if (payload.fleet) {
              const prev = Array.isArray(rt.data.active_fleets) ? rt.data.active_fleets : [];
              const fleetId = payload.fleet.id;
              applyLiveState(page, {
                active_fleets: [payload.fleet, ...prev.filter((f) => f.id !== fleetId)],
              });
              mergeFleetMovementIntoHud(payload.fleet, { reason: "fleet_send_success" });
            }
            if (res.state) {
              applyActionState(res, "fleet_send_success");
            }
            // GC-PERF-FLEET-SEND: live payload + slim state are enough; deferred fleet-state via syncFleetUiAfterMutation
            page.querySelectorAll("[data-ship-input]").forEach((inp) => { inp.value = "0"; });
            const mInp = page.querySelector("[data-fleet-res-metal]");
            const cInp = page.querySelector("[data-fleet-res-crystal]");
            const fInp = page.querySelector("[data-fleet-res-fuel-cells]");
            if (mInp) mInp.value = "0";
            if (cInp) cInp.value = "0";
            if (fInp) fInp.value = "0";
            schedulePreview(page);
          } else {
            if (errorEl) {
              errorEl.textContent = reasonText(apiError(res));
              errorEl.hidden = false;
            }
            applyActionState(res, "fleet_send_error");
          }
        } catch (_) {
          if (errorEl) {
            errorEl.textContent = reasonText("generic");
            errorEl.hidden = false;
          }
        } finally {
          rt.sending = false;
          setProgressionActionBusy(submitBtn, false);
          if (submitBtn) submitBtn.disabled = !(rt.lastPreview && rt.lastPreview.can_send);
        }
        return;
      }

      if (!page) return;
    });
  }

  let _logisticsBound = false;
  const _logisticsPreviewTimers = new WeakMap();

  const tt = (key, fallback) => t(key, fallback);
  const apiError = (res) => (res && (res.error || res.reason)) || "generic";

  const logisticsPayload = (res) =>
    (res && res.data && typeof res.data === "object" ? res.data : res) || {};

  const logisticsReasonText = (reason) => {
    if (!reason) return tt("fleet_error_generic");
    const key = String(reason);
    const prefixed = tt(`fleet_error_${key}`, "");
    if (prefixed && prefixed !== `fleet_error_${key}`) return prefixed;
    const direct = tt(key, "");
    if (direct && direct !== key) return direct;
    return tt("fleet_error_generic");
  };

  function notifyLogisticsFailure(page, mode, message) {
    showLogisticsError(page, mode, message);
    showNotify(message, "error");
  }

  function logisticsSubmitEnabled(page, mode) {
    if (!logisticsFormReady(page, mode)) return false;
    const preview = page._logisticsLastPreview;
    if (!preview || preview.mode !== mode) return false;
    return !!preview.can_launch;
  }

  function syncLogisticsColonyLaunchHints(page, preview) {
    const launchIds = new Set(
      (preview?.legs || []).map((leg) => parseInt(leg.planet_id, 10)).filter(Boolean)
    );
    page.querySelectorAll(".logistics-colony-card").forEach((card) => {
      if (card.hidden) {
        card.classList.remove("is-slots-skipped");
        return;
      }
      const cb = card.querySelector("[data-logistics-colony-cb]");
      const pid = parseInt(card.getAttribute("data-colony-planet-id"), 10);
      const checked = !!(cb && cb.checked);
      card.classList.toggle("is-slots-skipped", checked && launchIds.size > 0 && !launchIds.has(pid));
    });
  }

  async function refreshLogisticsLiveState(page) {
    if (!page || page.dataset.ready !== "1") return;
    try {
      const originId = getLogisticsOriginId(page);
      const q = originId ? `?planet_id=${originId}` : "";
      const res = await GC.fetchJSON(`/api/fleet/state${q}`, { cache: "no-store" });
      if (!res?.ok) return;
      const payload = logisticsPayload(res);
      const slots = payload.active_slots || payload.fleet_slots;
      if (slots) updateLogisticsFleetSlotsBadge(page, slots);
      const data = parseLogisticsPageData(page);
      if (data && payload.planet_id && payload.ships) {
        const hubId = parseInt(payload.planet_id, 10);
        const hub = getLogisticsColonyById(data, hubId);
        if (hub) hub.ships = payload.ships;
        data.ships = payload.ships;
        const stateEl = page.querySelector("#logistics-page-state");
        if (stateEl) stateEl.textContent = JSON.stringify(data);
        updateLogisticsOriginShips(page, data);
      } else {
        scheduleLogisticsPreview(page);
      }
    } catch (_) {}
  }

  function scheduleLogisticsRefreshFromState() {
    const page = document.getElementById("logistics-page");
    if (!page || page.dataset.ready !== "1") return;
    if (page._logisticsLivePending) return;
    page._logisticsLivePending = true;
    queueMicrotask(async () => {
      page._logisticsLivePending = false;
      await refreshLogisticsLiveState(page);
    });
  }

  GC.scheduleLogisticsRefreshFromState = scheduleLogisticsRefreshFromState;

  function parseLogisticsPageData(page) {
    const el = page.querySelector("#logistics-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  function getLogisticsColonyById(data, planetId) {
    const id = parseInt(planetId, 10);
    if (!data?.colonies || !id) return null;
    return data.colonies.find((c) => parseInt(c.planet_id, 10) === id) || null;
  }

  function getLogisticsMode(page) {
    return String(page?.dataset?.logisticsMode || "collect").toLowerCase();
  }

  function setLogisticsMode(page, mode) {
    const m = mode === "distribute" ? "distribute" : "collect";
    page.dataset.logisticsMode = m;
    page.querySelectorAll("[data-logistics-tab]").forEach((btn) => {
      const active = btn.getAttribute("data-logistics-tab") === m;
      btn.classList.toggle("active", active);
      btn.setAttribute("aria-selected", active ? "true" : "false");
    });
    page.querySelectorAll("[data-logistics-panel]").forEach((panel) => {
      const show = panel.getAttribute("data-logistics-panel") === m;
      panel.hidden = !show;
    });
    syncLogisticsPreviewTargetsLabel(page, m);
    clearLogisticsError(page);
    scheduleLogisticsPreview(page);
  }

  function syncLogisticsPreviewTargetsLabel(page, mode) {
    const labelEl = page.querySelector("[data-logistics-preview-targets-label]");
    if (!labelEl) return;
    const m = mode || getLogisticsMode(page);
    labelEl.textContent =
      m === "distribute"
        ? tt("logistics_preview_targets", "Target colonies")
        : tt("logistics_preview_sources", "Sources");
  }

  function getLogisticsOriginId(page) {
    const sel = page.querySelector("[data-logistics-origin]");
    return sel ? parseInt(sel.value, 10) : 0;
  }

  function getLogisticsResourcesSelection(page) {
    const resources = { metal: 0, crystal: 0, fuel_cells: 0 };
    page.querySelectorAll("[data-logistics-resource]").forEach((inp) => {
      const key = inp.getAttribute("data-logistics-resource");
      if (!key) return;
      resources[key] = Math.max(0, readNumberInput(inp));
    });
    return resources;
  }

  function getLogisticsSelectedColonyIds(page, mode) {
    const ids = [];
    page.querySelectorAll(`[data-logistics-colony-cb="${mode}"]:checked`).forEach((cb) => {
      if (cb.disabled) return;
      const card = cb.closest("[data-colony-planet-id]");
      if (card && !card.hidden) ids.push(parseInt(cb.value, 10));
    });
    return ids;
  }

  function updateLogisticsOriginShips(page, data) {
    const originId = getLogisticsOriginId(page);
    syncLogisticsColonyVisibility(page, originId);
    syncLogisticsColonySelected(page);
    scheduleLogisticsPreview(page);
  }

  function syncLogisticsColonyVisibility(page, originId) {
    const hub = parseInt(originId, 10);
    page.querySelectorAll("[data-colony-planet-id]").forEach((li) => {
      const pid = parseInt(li.getAttribute("data-colony-planet-id"), 10);
      const isHub = pid === hub;
      // Hub is chosen in the toolbar — hide it from source/target lists.
      li.hidden = isHub;
      li.classList.toggle("is-hub", isHub);
      const cb = li.querySelector("[data-logistics-colony-cb]");
      if (cb) {
        cb.disabled = isHub;
        if (isHub) {
          cb.checked = false;
          li.classList.remove("is-selected");
        }
      }
    });
    updateLogisticsHubStock(page);
  }

  function updateLogisticsHubStock(page) {
    if (!page) return;
    const data = parseLogisticsPageData(page);
    const originId = getLogisticsOriginId(page);
    const hub = getLogisticsColonyById(data, originId);
    const res = (hub && hub.resources) || data?.hub_resources || {};
    ["metal", "crystal", "fuel_cells"].forEach((key) => {
      const amount = Math.max(0, Math.floor(Number(res[key]) || 0));
      page.querySelectorAll(`[data-logistics-hub-res="${key}"]`).forEach((el) => {
        _setIfChanged(el, fmtNumber(amount));
      });
    });
    if (data) {
      data.hub_resources = {
        metal: Math.max(0, Math.floor(Number(res.metal) || 0)),
        crystal: Math.max(0, Math.floor(Number(res.crystal) || 0)),
        fuel_cells: Math.max(0, Math.floor(Number(res.fuel_cells) || 0)),
      };
      const stateEl = page.querySelector("#logistics-page-state");
      if (stateEl) stateEl.textContent = JSON.stringify(data);
    }
  }

  function patchLogisticsColonyResources(page, colonyResources) {
    if (!page || !colonyResources || typeof colonyResources !== "object") return;
    const data = parseLogisticsPageData(page);
    Object.keys(colonyResources).forEach((pidRaw) => {
      const pid = parseInt(pidRaw, 10);
      const res = colonyResources[pidRaw] || colonyResources[pid] || {};
      const stock = {
        metal: Math.max(0, Math.floor(Number(res.metal) || 0)),
        crystal: Math.max(0, Math.floor(Number(res.crystal) || 0)),
        fuel_cells: Math.max(0, Math.floor(Number(res.fuel_cells) || 0)),
      };
      page.querySelectorAll(`[data-colony-planet-id="${pid}"]`).forEach((card) => {
        ["metal", "crystal", "fuel_cells"].forEach((key) => {
          card.querySelectorAll(`[data-logistics-colony-res="${key}"]`).forEach((el) => {
            _setIfChanged(el, fmtNumber(stock[key]));
          });
        });
      });
      if (data) {
        const col = getLogisticsColonyById(data, pid);
        if (col) col.resources = stock;
      }
    });
    if (data) {
      const stateEl = page.querySelector("#logistics-page-state");
      if (stateEl) stateEl.textContent = JSON.stringify(data);
    }
    updateLogisticsHubStock(page);
  }

  function syncLogisticsColonySelected(page) {
    page.querySelectorAll(".logistics-colony-card").forEach((card) => {
      const cb = card.querySelector("[data-logistics-colony-cb]");
      card.classList.toggle("is-selected", !!(cb && cb.checked && !card.hidden));
    });
  }

  function updateLogisticsFleetSlotsBadge(page, slots) {
    if (!slots) return;
    const el = page.querySelector("[data-logistics-fleet-slots]");
    if (el) {
      el.textContent = `${parseInt(slots.active, 10) || 0} / ${parseInt(slots.max, 10) || 0}`;
    }
    const freeEl = page.querySelector(".logistics-slots-free");
    if (freeEl && slots.free !== undefined) {
      const freeLabel = tt("logistics_slots_free");
      freeEl.textContent = `${freeLabel}: ${fmtNumber(parseInt(slots.free, 10) || 0)}`;
    }
    const data = parseLogisticsPageData(page);
    if (data) data.fleet_slots = slots;
  }

  function clearLogisticsError(page, mode) {
    const m = mode || getLogisticsMode(page);
    const errorEl = page.querySelector(`[data-logistics-error="${m}"]`);
    if (errorEl) {
      errorEl.hidden = true;
      errorEl.textContent = "";
    }
  }

  function showLogisticsError(page, mode, message) {
    const errorEl = page.querySelector(`[data-logistics-error="${mode}"]`);
    if (errorEl) {
      errorEl.textContent = message;
      errorEl.hidden = false;
    }
  }

  function logisticsFormReady(page, mode) {
    const m = mode || getLogisticsMode(page);
    const originId = getLogisticsOriginId(page);
    const colonyIds = getLogisticsSelectedColonyIds(page, m);
    if (!originId || !colonyIds.length) return false;
    if (m === "distribute") {
      const res = getLogisticsResourcesSelection(page);
      if ((res.metal || 0) + (res.crystal || 0) + (res.fuel_cells || 0) <= 0) return false;
    }
    return true;
  }

  function setLogisticsColonySelection(page, mode, checked) {
    page.querySelectorAll(`[data-logistics-colony-cb="${mode}"]`).forEach((cb) => {
      if (cb.disabled) {
        cb.checked = false;
        return;
      }
      const card = cb.closest("[data-colony-planet-id]");
      if (card && card.hidden) {
        cb.checked = false;
        return;
      }
      cb.checked = !!checked;
    });
    syncLogisticsColonySelected(page);
    updateLogisticsSubmitButtons(page);
    scheduleLogisticsPreview(page);
  }

  function updateLogisticsSubmitButtons(page) {
    const mode = getLogisticsMode(page);
    page.querySelectorAll("[data-logistics-submit]").forEach((btn) => {
      const btnMode = btn.getAttribute("data-logistics-submit");
      btn.disabled = btnMode !== mode || !logisticsSubmitEnabled(page, btnMode);
    });
  }

  function resetLogisticsPreview(page, hintKey) {
    page._logisticsLastPreview = null;
    const hud = page.querySelector("[data-logistics-preview]");
    if (hud) {
      hud.classList.remove("is-ready", "is-blocked");
    }
    const statusEl = page.querySelector("[data-logistics-preview-status]");
    if (statusEl) {
      statusEl.textContent = hintKey ? tt(hintKey) : "–";
      statusEl.classList.remove("is-ok", "is-blocked");
      if (hintKey) statusEl.classList.add("is-blocked");
    }
    ["flight", "cargo", "slots", "fuel"].forEach((key) => {
      const el = page.querySelector(`[data-logistics-preview-${key}]`);
      if (el) el.textContent = "–";
    });
    const targetsWrap = page.querySelector("[data-logistics-preview-targets]");
    const targetsList = page.querySelector("[data-logistics-preview-targets-list]");
    if (targetsWrap) targetsWrap.hidden = true;
    if (targetsList) targetsList.innerHTML = "";
    syncLogisticsColonyLaunchHints(page, null);
    updateLogisticsSubmitButtons(page);
  }

  function renderLogisticsPreview(page, preview) {
    const hud = page.querySelector("[data-logistics-preview]");
    const statusEl = page.querySelector("[data-logistics-preview-status]");
    const flightEl = page.querySelector("[data-logistics-preview-flight]");
    const cargoEl = page.querySelector("[data-logistics-preview-cargo]");
    const slotsEl = page.querySelector("[data-logistics-preview-slots]");
    const fuelEl = page.querySelector("[data-logistics-preview-fuel]");
    const targetsWrap = page.querySelector("[data-logistics-preview-targets]");
    const targetsList = page.querySelector("[data-logistics-preview-targets-list]");

    if (!preview || !Object.keys(preview).length) {
      resetLogisticsPreview(page);
      return;
    }

    page._logisticsLastPreview = { ...preview, mode: getLogisticsMode(page) };
    syncLogisticsPreviewTargetsLabel(page, getLogisticsMode(page));

    const canLaunch = !!preview.can_launch;
    const blockReason = preview.block_reason || "";
    clearLogisticsError(page, getLogisticsMode(page));
    if (hud) {
      hud.classList.toggle("is-ready", canLaunch);
      hud.classList.toggle("is-blocked", !canLaunch);
    }
    if (statusEl) {
      statusEl.classList.remove("is-ok", "is-blocked");
      const skipped = parseInt(preview.targets_skipped || "0", 10) || 0;
      if (canLaunch) {
        if (skipped > 0) {
          const launching = preview.targets_launching || (preview.legs || []).length;
          statusEl.textContent = tf(
            "logistics_preview_slots_capped",
            {
              launching,
              selected: preview.targets_selected || 0,
              skipped,
            },
            "Ready: %(launching)s of %(selected)s colonies — using all %(launching)s free slots (%(skipped)s waiting)."
          );
        } else {
          statusEl.textContent = tt("logistics_preview_ready");
        }
        statusEl.classList.add("is-ok");
      } else {
        statusEl.textContent = blockReason
          ? logisticsReasonText(blockReason)
          : tt("logistics_preview_incomplete");
        statusEl.classList.add("is-blocked");
      }
    }
    if (flightEl) {
      flightEl.textContent = formatCountdownRemain(preview.max_flight_seconds || 0);
    }
    if (cargoEl) {
      cargoEl.textContent = `${formatNumber(preview.cargo_used || 0)} / ${formatNumber(preview.cargo_total || 0)}`;
    }
    if (slotsEl) {
      const fs = preview.fleet_slots || {};
      const needed = formatNumber(preview.slots_needed || 0);
      const free = formatNumber(fs.free ?? 0);
      slotsEl.textContent = tt("logistics_preview_slots_line", "%(needed)s needed · %(free)s free")
        .replace("%(needed)s", needed)
        .replace("%(free)s", free);
    }
    if (fuelEl) {
      fuelEl.textContent = formatNumber(preview.total_fuel_cost || 0);
    }
    if (targetsWrap && targetsList) {
      const legs = preview.legs || [];
      if (legs.length) {
        targetsWrap.hidden = false;
        targetsList.innerHTML = legs
          .map((leg) => {
            const res = leg.resources;
            const cargoTxt = res
              ? ` — ${formatNumber(res.metal || 0)}/${formatNumber(res.crystal || 0)}/${formatNumber(res.fuel_cells || 0)}`
              : "";
            return `<li class="logistics-preview-target-item"><span class="logistics-preview-target-name">${escapeHtml(leg.name || "")}</span> <span class="gc-mono logistics-preview-target-coords">${escapeHtml(leg.coordinates || "")}</span><span class="logistics-preview-target-meta gc-mono">${formatCountdownRemain(leg.flight_seconds || 0)}${cargoTxt}</span></li>`;
          })
          .join("");
      } else {
        targetsWrap.hidden = true;
        targetsList.innerHTML = "";
      }
    }
    syncLogisticsColonyLaunchHints(page, preview);
    updateLogisticsSubmitButtons(page);
  }

  function escapeHtml(text) {
    return String(text || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function buildLogisticsPreviewBody(page) {
    const mode = getLogisticsMode(page);
    const originId = getLogisticsOriginId(page);
    const body = {
      mode,
      origin_planet_id: originId,
      target_planet_id: originId,
      ships: {},
      speed_percent: 100,
      ships_selection_mode: "auto_cargo",
    };
    if (mode === "collect") {
      body.source_planet_ids = getLogisticsSelectedColonyIds(page, "collect");
      body.resources_mode = "all";
    } else {
      body.target_planet_ids = getLogisticsSelectedColonyIds(page, "distribute");
      body.resources = getLogisticsResourcesSelection(page);
      body.resources_mode = "equal";
    }
    return body;
  }

  async function refreshLogisticsPreview(page) {
    const mode = getLogisticsMode(page);
    const originId = getLogisticsOriginId(page);
    const colonyIds = getLogisticsSelectedColonyIds(page, mode);

    if (!originId || !colonyIds.length) {
      if (!colonyIds.length && originId) {
        resetLogisticsPreview(page, "logistics_preview_select_colonies");
      } else {
        resetLogisticsPreview(page);
      }
      return;
    }
    if (mode === "distribute") {
      const res = getLogisticsResourcesSelection(page);
      if ((res.metal || 0) + (res.crystal || 0) + (res.fuel_cells || 0) <= 0) {
        resetLogisticsPreview(page, "logistics_distribute_no_resources");
        return;
      }
    }
    try {
      const res = await GC.fetchJSON("/api/fleet/logistics/preview", {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
        body: JSON.stringify(buildLogisticsPreviewBody(page)),
      });
      const preview = logisticsPayload(res).preview || res?.preview;
      if (res?.ok && preview) {
        renderLogisticsPreview(page, preview);
      } else {
        resetLogisticsPreview(page);
        if (!res?.ok) {
          notifyLogisticsFailure(page, mode, logisticsReasonText(apiError(res)));
        }
      }
    } catch (_) {
      resetLogisticsPreview(page);
      notifyLogisticsFailure(page, mode, logisticsReasonText("generic"));
    }
  }

  function scheduleLogisticsPreview(page) {
    if (!page) return;
    const prev = _logisticsPreviewTimers.get(page);
    if (prev) clearTimeout(prev);
    _logisticsPreviewTimers.set(
      page,
      setTimeout(() => {
        refreshLogisticsPreview(page);
      }, 320)
    );
  }

  function applyLogisticsActionState(page, res) {
    applyActionState(res, "logistics_action");
    const slots =
      res?.state?.fleet_slots ||
      res?.data?.active_slots ||
      logisticsPayload(res).active_slots;
    if (slots) updateLogisticsFleetSlotsBadge(page, slots);
    if (res?.state?.active_planet_id) {
      syncScopedPlanetIds(res.state.active_planet_id);
    }
    const colonyResources =
      res?.data?.colony_resources || logisticsPayload(res).colony_resources;
    if (colonyResources) {
      patchLogisticsColonyResources(page, colonyResources);
    }
  }

  function bindLogisticsOnce() {
    // Session-stable like bindFleetOnce — never reset on PJAX or document listeners multiply.
    if (GC._logisticsEventsBound || _logisticsBound) return;
    GC._logisticsEventsBound = true;
    _logisticsBound = true;

    document.addEventListener("click", (e) => {
      const tabBtn = e.target.closest("[data-logistics-tab]");
      if (tabBtn && !tabBtn.disabled) {
        const page = document.getElementById("logistics-page");
        if (page && page.contains(tabBtn)) {
          setLogisticsMode(page, tabBtn.getAttribute("data-logistics-tab"));
        }
        return;
      }

      const selectAllBtn = e.target.closest("[data-logistics-select-all]");
      if (selectAllBtn) {
        const page = document.getElementById("logistics-page");
        if (!page || !page.contains(selectAllBtn)) return;
        const mode = selectAllBtn.getAttribute("data-logistics-select-all") || getLogisticsMode(page);
        const action = selectAllBtn.getAttribute("data-logistics-select-all-action") || "all";
        setLogisticsColonySelection(page, mode, action !== "none");
        return;
      }

      const resMaxBtn = e.target.closest("[data-logistics-res-max]");
      if (resMaxBtn) {
        const page = document.getElementById("logistics-page");
        if (!page || !page.contains(resMaxBtn)) return;
        const key = resMaxBtn.getAttribute("data-logistics-res-max");
        const inp = page.querySelector(`[data-logistics-resource="${key}"]`);
        if (!inp || !key) return;
        const data = parseLogisticsPageData(page);
        const hub = getLogisticsColonyById(data, getLogisticsOriginId(page));
        const have = Math.max(0, parseInt(hub?.resources?.[key] ?? data?.resources?.[key] ?? "0", 10) || 0);
        setNumberInputValue(inp, have);
        updateLogisticsSubmitButtons(page);
        scheduleLogisticsPreview(page);
      }
    });

    document.addEventListener("change", (e) => {
      const page = document.getElementById("logistics-page");
      if (!page || page.dataset.ready !== "1") return;
      if (
        e.target.matches("[data-logistics-origin]") ||
        e.target.matches("[data-logistics-colony-cb]") ||
        e.target.matches("[data-logistics-resource]")
      ) {
        const data = parseLogisticsPageData(page);
        if (e.target.matches("[data-logistics-origin]")) {
          updateLogisticsOriginShips(page, data);
        } else {
          syncLogisticsColonySelected(page);
          updateLogisticsSubmitButtons(page);
          scheduleLogisticsPreview(page);
        }
      }
    });

    document.addEventListener("input", (e) => {
      const page = document.getElementById("logistics-page");
      if (!page || page.dataset.ready !== "1") return;
      if (e.target.matches("[data-logistics-resource]")) {
        updateLogisticsSubmitButtons(page);
        scheduleLogisticsPreview(page);
      }
    });

    document.addEventListener("submit", async (e) => {
      const collectForm = e.target.closest("#logistics-collect-form");
      const distributeForm = e.target.closest("#logistics-distribute-form");
      const form = collectForm || distributeForm;
      if (!form) return;
      const page = document.getElementById("logistics-page");
      if (!page || !page.contains(form)) return;
      e.preventDefault();
      if (form.dataset.submitting === "1") return;

      const mode = collectForm ? "collect" : "distribute";
      clearLogisticsError(page, mode);

      const originId = getLogisticsOriginId(page);
      const colonyIds = getLogisticsSelectedColonyIds(page, mode);

      if (!originId || !colonyIds.length) {
        notifyLogisticsFailure(
          page,
          mode,
          mode === "collect"
            ? tt("logistics_collect_incomplete")
            : tt("logistics_distribute_incomplete")
        );
        return;
      }

      const submitBtn = form.querySelector(`[data-logistics-submit="${mode}"]`);
      form.dataset.submitting = "1";
      if (submitBtn) submitBtn.disabled = true;
      try {
        await refreshLogisticsPreview(page);
        if (!logisticsSubmitEnabled(page, mode)) {
          const blockReason = page._logisticsLastPreview?.block_reason || "";
          notifyLogisticsFailure(
            page,
            mode,
            blockReason
              ? logisticsReasonText(blockReason)
              : mode === "collect"
                ? tt("logistics_collect_incomplete")
                : tt("logistics_distribute_incomplete")
          );
          return;
        }
        let res;
        try {
          if (mode === "collect") {
            res = await GC.fetchGameAction("/api/fleet/logistics/collect", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                target_planet_id: originId,
                source_planet_ids: colonyIds,
                ships: {},
                resources_mode: "all",
                ships_selection_mode: "auto_cargo",
              }),
            });
          } else {
            const resources = getLogisticsResourcesSelection(page);
            if ((resources.metal || 0) + (resources.crystal || 0) + (resources.fuel_cells || 0) <= 0) {
              notifyLogisticsFailure(page, mode, tt("logistics_distribute_no_resources"));
              return;
            }
            res = await GC.fetchGameAction("/api/fleet/logistics/distribute", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                origin_planet_id: originId,
                target_planet_ids: colonyIds,
                ships: {},
                resources,
                resources_mode: "equal",
                ships_selection_mode: "auto_cargo",
              }),
            });
          }
        } catch (_) {
          notifyLogisticsFailure(page, mode, logisticsReasonText("generic"));
          return;
        }
        if (res?.ok) {
          const okKey =
            mode === "collect" ? "logistics_collect_success" : "logistics_distribute_success";
          showNotify(
            tt(okKey),
            "success"
          );
          applyLogisticsActionState(page, res);
          try {
            // Collapse mobile fleet sheet so bottom nav stays usable (no full PJAX).
            if (typeof setFleetDrawerShowAll === "function") setFleetDrawerShowAll(false);
            document.body.classList.remove("gc-fleet-sheet-open");
            const backdrop = document.getElementById("gc-fleet-sheet-backdrop");
            if (backdrop) backdrop.hidden = true;
            const fleetRoot = document.getElementById("global-fleet-drawer-root")
              || document.querySelector("[data-global-fleet-drawer]");
            if (fleetRoot) {
              fleetRoot.classList.remove("is-show-all");
              const listEl = fleetRoot.querySelector("[data-fleet-drawer-list]");
              if (listEl) listEl.classList.remove("is-show-all");
              if (typeof syncMobileFleetSheetLayout === "function") {
                syncMobileFleetSheetLayout(fleetRoot);
              }
            }
            await refreshLogisticsLiveState(page);
          } catch (err) {
            console.warn("[GC] logistics post-success refresh failed", err);
          }
        } else {
          notifyLogisticsFailure(page, mode, logisticsReasonText(apiError(res)));
          applyLogisticsActionState(page, res);
        }
      } catch (_) {
        notifyLogisticsFailure(page, mode, logisticsReasonText("generic"));
      } finally {
        form.dataset.submitting = "0";
        updateLogisticsSubmitButtons(page);
        scheduleLogisticsPreview(page);
      }
    });
  }

  function initLogistics() {
    bindLogisticsOnce();
    const page = document.getElementById("logistics-page");
    if (!page || page.dataset.ready !== "1") return;

    const data = parseLogisticsPageData(page);
    if (data?.planet_id) {
      page.dataset.planetId = String(data.planet_id);
      syncScopedPlanetIds(data.planet_id);
    }
    if (typeof GC.initHudSelects === "function") GC.initHudSelects(page);
    setLogisticsMode(page, getLogisticsMode(page));
    updateLogisticsOriginShips(page, data);
    resetLogisticsPreview(page);
    refreshLogisticsLiveState(page);
    bindLogisticsHelp(page);
    GC.registerCleanup(() => {
      page._logisticsLivePending = false;
      const prev = _logisticsPreviewTimers.get(page);
      if (prev) clearTimeout(prev);
      _logisticsPreviewTimers.delete(page);
      closeLogisticsHelpModal(page);
    });
  }

  function closeLogisticsHelpModal(page) {
    const modal = document.getElementById("logistics-help-modal");
    if (!modal || modal.hidden) return;
    modal.hidden = true;
    modal.setAttribute("aria-hidden", "true");
    modal.classList.remove("is-open");
    document.body.classList.remove("gc-player-card-open");
    const openBtn = (page || document).querySelector("#logistics-help-open");
    if (openBtn) openBtn.setAttribute("aria-expanded", "false");
    if (page) page._logisticsHelpOpen = false;
  }

  function openLogisticsHelpModal(page, trigger) {
    const modal = document.getElementById("logistics-help-modal");
    if (!modal) return;
    page._logisticsHelpLastFocus = trigger || document.activeElement;
    modal.hidden = false;
    modal.setAttribute("aria-hidden", "false");
    modal.classList.add("is-open");
    document.body.classList.add("gc-player-card-open");
    const openBtn = page.querySelector("#logistics-help-open");
    if (openBtn) openBtn.setAttribute("aria-expanded", "true");
    page._logisticsHelpOpen = true;
    modal.querySelector("[data-logistics-help-close].gc-player-card-close")?.focus();
  }

  function bindLogisticsHelp(page) {
    if (!page || page.dataset.logisticsHelpBound === "1") return;
    page.dataset.logisticsHelpBound = "1";
    const helpOpen = page.querySelector("#logistics-help-open") || document.getElementById("logistics-help-open");
    if (helpOpen) {
      helpOpen.addEventListener("click", () => {
        if (page._logisticsHelpOpen) closeLogisticsHelpModal(page);
        else openLogisticsHelpModal(page, helpOpen);
      });
    }
    document.querySelectorAll("[data-logistics-help-close]").forEach((el) => {
      el.addEventListener("click", () => closeLogisticsHelpModal(page));
    });
    document.addEventListener("keydown", (ev) => {
      if (!page._logisticsHelpOpen) return;
      if (ev.key === "Escape") {
        ev.preventDefault();
        closeLogisticsHelpModal(page);
      }
    });
  }

  function getFleetPageMode(page) {
    const fromDataset = String(page?.dataset?.fleetPageMode || "").trim().toLowerCase();
    if (fromDataset === "collect" || fromDataset === "distribute") return fromDataset;
    const fromUrl = (new URLSearchParams(window.location.search).get("mode") || "send").trim().toLowerCase();
    if (fromUrl === "collect" || fromUrl === "distribute") return fromUrl;
    return "send";
  }

  function applyFleetPageMode(page) {
    if (!page) return "send";
    const mode = getFleetPageMode(page);
    page.dataset.fleetPageMode = mode;
    const isLogistics = mode === "collect" || mode === "distribute";
    page.querySelectorAll("[data-fleet-mode-tab]").forEach((tab) => {
      const tabMode = tab.getAttribute("data-fleet-mode-tab") || "";
      const active = isLogistics ? tabMode === mode : tabMode === "send";
      tab.classList.toggle("active", active);
      tab.setAttribute("aria-selected", active ? "true" : "false");
    });
    const sendPanel = page.querySelector('[data-fleet-mode-panel="send"]');
    const logPanel = page.querySelector('[data-fleet-mode-panel="logistics"]');
    if (sendPanel) sendPanel.hidden = isLogistics;
    if (logPanel) logPanel.hidden = !isLogistics;
    if (isLogistics) {
      const logPage = document.getElementById("logistics-page");
      if (logPage && logPage.dataset.ready === "1") {
        setLogisticsMode(logPage, mode);
        initLogistics();
      }
    }
    return mode;
  }

  function initFleet() {
    bindFleetOnce();
    const page = document.getElementById("fleet-page");
    if (!page || page.dataset.ready !== "1") return;

    page._fleetApplySeq = 0;
    page._fleetLiveServerTime = 0;
    const initParams = new URLSearchParams(window.location.search);
    const initMission = (initParams.get("mission") || "").trim();
    const initWorldKey = (initParams.get("world_key") || "").trim();
    if (!initMission && !initWorldKey) {
      delete page.dataset.fleetUrlMission;
    }
    if (!initWorldKey) {
      delete page.dataset.fleetWorldKey;
      delete page.dataset.fleetTargetType;
      delete page.dataset.fleetNativeTargetType;
    }

    const rt = getFleetRuntime(page);
    rt.data = parseFleetPageData(page);
    rt.lastPreview = null;
    resolveFleetOriginPlanetId(page);

    const fuelResource = rt.data.fuel_resource || page.dataset.fuelResource || "fuel_cells";
    const fuelLabelEl = page.querySelector("[data-fuel-resource-label]");
    if (fuelLabelEl) {
      fuelLabelEl.textContent = fleetFuelLabel((k, f) => t(k, f), fuelResource);
    }

    if (typeof GC.initHudSelects === "function") GC.initHudSelects(page);
    applyFleetUrlPrefill(page);
    if (typeof GC.pickDefaultFleetTargetIfNeeded === "function") {
      GC.pickDefaultFleetTargetIfNeeded(page);
    }

    const tickFleetCountdowns = () => {
      const p = document.getElementById("fleet-page");
      if (!p || p.dataset.ready !== "1") return;
      updateMovementCountdowns(getTimerServerNow());
    };
    tickFleetCountdowns();
    GC.startProgressTicker();
    // GC-INSTANT-UX-001C: SSR #fleet-page-state already has ready page context — skip redundant /api/fleet/state.
    const hasSsrFleetBoot = !!(rt.data && rt.data.ready === true);
    if (!hasSsrFleetBoot && typeof GC.refreshFleetState === "function") {
      GC.refreshFleetState(page);
    }
    if (typeof GC.syncFleetMissionLockUi === "function") GC.syncFleetMissionLockUi(page);
    applyFleetPageMode(page);
    if (typeof GC.syncFleetShipPickQtyMarks === "function") {
      GC.syncFleetShipPickQtyMarks(page);
    }
    if (typeof GC.scheduleMassExpoSplitPreview === "function") {
      GC.scheduleMassExpoSplitPreview(page);
    }
    if (typeof GC.syncExpeditionDailyEfficiencyUi === "function") {
      GC.syncExpeditionDailyEfficiencyUi(page);
    }
    const expeditionDailyTick = () => {
      const live = document.getElementById("fleet-page");
      if (!live || live.dataset.ready !== "1") return;
      if (typeof GC.tickExpeditionDailyEfficiencyResets === "function") {
        GC.tickExpeditionDailyEfficiencyResets(live);
      }
    };
    expeditionDailyTick();
    const expeditionDailyTimer = setInterval(expeditionDailyTick, 1000);
    GC.registerCleanup(() => clearInterval(expeditionDailyTimer));
  }

  function applyFleetUrlPrefill(page) {
    const params = new URLSearchParams(window.location.search);
    const form = page.querySelector("#fleet-send-form");
    if (!form) return;

    const readExpeditionPosition = () => {
      const fromPage = parseInt(page.dataset.expeditionPosition || "", 10);
      if (fromPage > 0) return fromPage;
      try {
        const st = JSON.parse(page.querySelector("#fleet-page-state")?.textContent || "{}");
        return parseInt(st.expedition_position || "16", 10) || 16;
      } catch (_) {
        return 16;
      }
    };

    const missionRaw = (params.get("mission") || "").trim().toLowerCase();
    const gRaw = params.get("target_galaxy");
    const sRaw = params.get("target_system");
    const pRaw = params.get("target_position");
    const hasCoords = gRaw != null && sRaw != null && pRaw != null;
    const gInp = form.querySelector('[name="target_galaxy"]');
    const sInp = form.querySelector('[name="target_system"]');
    const pInp = form.querySelector('[name="target_position"]');
    const ms = form.querySelector("[data-fleet-mission]");
    const missionKnown =
      missionRaw && ms && Array.from(ms.options).some((opt) => opt.value === missionRaw);

    if (hasCoords) {
      if (gInp) gInp.value = String(parseInt(gRaw, 10) || gRaw);
      if (sInp) sInp.value = String(parseInt(sRaw, 10) || sRaw);
      if (pInp) pInp.value = String(parseInt(pRaw, 10) || pRaw);
    }

    if (missionKnown) {
      if (missionRaw === "expedition") {
        const expPos = readExpeditionPosition();
        if (pInp) pInp.value = String(expPos);
      }
      page.dataset.fleetUrlMission = missionRaw;
      ms.value = missionRaw;
      if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(ms);
      if (typeof GC.updateFleetFormMode === "function") GC.updateFleetFormMode(page);
    } else {
      delete page.dataset.fleetUrlMission;
    }

    const worldKeyRaw = (params.get("world_key") || "").trim();
    const targetTypeRaw = (params.get("target_type") || "").trim().toLowerCase();
    if (worldKeyRaw) {
      page.dataset.fleetWorldKey = worldKeyRaw;
      if (targetTypeRaw) {
        page.dataset.fleetTargetType = targetTypeRaw;
      }
      if (!missionKnown && ms) {
        page.dataset.fleetUrlMission = "colonize";
        ms.value = "colonize";
        if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(ms);
        if (typeof GC.updateFleetFormMode === "function") GC.updateFleetFormMode(page);
      }
      if (typeof GC.syncFleetWorldTargetUi === "function") GC.syncFleetWorldTargetUi(page);
      if (typeof GC.loadFleetWorldTargetPreview === "function") {
        GC.loadFleetWorldTargetPreview(page, worldKeyRaw);
      }
    } else if (typeof GC.clearFleetWorldKey === "function") {
      GC.clearFleetWorldKey(page);
    }
    // GC-WB-FLEET-PREFILL-001: target_type from URL even without world_key (WB attack deep-link).
    if (targetTypeRaw) {
      page.dataset.fleetTargetType = targetTypeRaw;
    }

    const colonyName = params.get("colony_name");
    if (colonyName) {
      const inp = form.querySelector("[data-fleet-colony-name]");
      if (inp) inp.value = colonyName;
    }

    if (typeof GC.syncColonyChipsFromCoords === "function") {
      GC.syncColonyChipsFromCoords(page);
    }
    if (typeof GC.syncExpeditionMissionTarget === "function") {
      GC.syncExpeditionMissionTarget(page);
    }
    const urlMission = page.dataset.fleetUrlMission || "";
    if (urlMission && ms && ms.value !== urlMission) {
      ms.value = urlMission;
      if (typeof GC.syncHudSelect === "function") GC.syncHudSelect(ms);
      if (typeof GC.updateFleetFormMode === "function") GC.updateFleetFormMode(page);
    }
    if (typeof GC.syncFleetWorldTargetUi === "function") GC.syncFleetWorldTargetUi(page);
    if (typeof GC.enforceFleetUrlMissionLock === "function") GC.enforceFleetUrlMissionLock(page);
    if (typeof GC.syncFleetMissionLockUi === "function") GC.syncFleetMissionLockUi(page);

    // GC-WB-FLEET-PREFILL-001: max-select combat hulls (+ Eclipse Runner) for WB attack only.
    const prefillMission = (page.dataset.fleetUrlMission || missionRaw || "").trim().toLowerCase();
    const prefillTargetType = (page.dataset.fleetTargetType || targetTypeRaw || "").trim().toLowerCase();
        if (prefillMission === "attack" && prefillTargetType === "world_boss") {
      page.querySelectorAll("[data-ship-key][data-ship-have]").forEach((row) => {
        const role = (row.getAttribute("data-ship-role") || "").trim().toLowerCase();
        const key = (row.getAttribute("data-ship-key") || "").trim();
        if (role !== "combat" && key !== "eclipse_runner") return;
        const have = parseIntNumber(row.getAttribute("data-ship-have") || "0") || 0;
        if (have <= 0) return;
        const inp = form.querySelector(`[data-ship-input="${key}"]`);
        if (!inp) return;
        if (typeof GC.setFleetShipInputValue === "function") {
          GC.setFleetShipInputValue(page, inp, have);
        } else {
          setNumberInputValue(inp, have);
          inp.dispatchEvent(new Event("input", { bubbles: true }));
          inp.dispatchEvent(new Event("change", { bubbles: true }));
        }
      });
    }

    if (typeof GC.runFleetPreview === "function") {
      GC.runFleetPreview(page);
    }
    if (typeof GC.runFleetTargetResolve === "function") {
      GC.runFleetTargetResolve(page);
    }
  }

  let _shipyardRefreshTimer = null;
  let _shipyardUnitFinishKey = "";

  function scheduleShipyardRefreshFromState(immediate) {
    const page = document.getElementById("shipyard-page");
    if (!page || page.dataset.ready !== "1") return;
    if (_shipyardRefreshTimer != null) {
      clearTimeout(_shipyardRefreshTimer);
      _shipyardRefreshTimer = null;
    }
    const delay = immediate ? 0 : 150;
    _shipyardRefreshTimer = GC.setSafeTimeout(() => {
      _shipyardRefreshTimer = null;
      if (page.dataset.queueRefreshBusy === "1") return;
      page.dataset.queueRefreshBusy = "1";
      refreshShipyardStateCoalesced(page)
        .then((data) => {
          if (data?.current_ships) updateShipyardStockBadges(page, data.current_ships);
          _shipyardUnitFinishKey = "";
        })
        .finally(() => {
          delete page.dataset.queueRefreshBusy;
        });
    }, delay);
  }

  let _shipyardPollIntervalId = null;
  let _lastShipyardQueueSignature = "";

  function stopShipyardTimers() {
    if (_shipyardPollIntervalId != null) {
      clearInterval(_shipyardPollIntervalId);
      _shipyardPollIntervalId = null;
    }
  }

  function startShipyardTimers() {
    const page = document.getElementById("shipyard-page");
    if (!page || page.dataset.ready !== "1") return;
    GC.startProgressTicker();
  }

  function _shipyardQueueSignature(queueList, summary) {
    try {
      const count = summary?.count ?? (queueList?.length ?? 0);
      const items = (queueList || [])
        .map(
          (j, idx) =>
            `${j.id}:${j.queue_position ?? idx + 1}:${j.units_delivered ?? 0}:${j.amount_remaining ?? j.amount}:${j.next_finish_at || j.finish_at || 0}`
        )
        .join("|");
      return `${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function _syncShipyardQueueLiveState(queueList) {
    const first = queueList && queueList.length ? queueList[0] : null;
    if (first) {
      const finishTime = resolveQueueJobFinishTime(first);
      const isActiveHead = Boolean(first.is_active !== false);
      if (isActiveHead && finishTime) {
        const now = getTimerServerNow();
        const remaining = queueJobRemainingSeconds(finishTime, now, resolveQueueJobRemaining(first));
        const totalRaw = Number(first.order_total_seconds || first.total_seconds || 0);
        const total = totalRaw > 0 ? Math.floor(totalRaw) : Math.max(1, remaining + 1);
        SHIPYARDQ.active.finishTime = finishTime;
        SHIPYARDQ.active.totalSeconds = total;
      } else {
        SHIPYARDQ.active.finishTime = 0;
        SHIPYARDQ.active.totalSeconds = 0;
      }
    } else {
      SHIPYARDQ.active.finishTime = 0;
      SHIPYARDQ.active.totalSeconds = 0;
    }
  }

  function clearAllProductionCardQueues(page) {
    if (!page) return;
    page.querySelectorAll("[data-ship-card], [data-defense-card]").forEach((card) => {
      clearProductionCardQueueState(card);
    });
  }

  function clearProductionCardQueueState(card) {
    if (!card) return;
    delete card.dataset.queueHeadJobId;
    delete card.dataset.queuePending;
    GC.clearCardQueueBlock(card);
    card.classList.remove(
      "gc-ship-card--in-queue",
      "gc-ship-card--queue-active",
      "gc-ship-card--queue-pending"
    );
  }

  function patchShipyardCardQueues(page, _queueData) {
    // GC-UNIT-QUEUE-DEDUP-001: unit cards must not host queue UI.
    clearAllProductionCardQueues(page);
  }

  function shipyardIconUrl(shipKey) {
    const sk = String(shipKey || "").trim();
    return GC.preferWebpStaticUrl(`/static/img/ships/${sk}.png`);
  }
  GC.shipyardIconUrl = shipyardIconUrl;

  function renderShipyardQueue(page, queueData) {
    const host = document.getElementById("shipyard-mini-queue");
    if (!host) return;

    const qd = queueData || { queue: [], summary: { count: 0, limit: 3, refund_percent: 100, refund_percent_active: 50 } };
    const jobs = qd.queue || [];
    const summary = qd.summary || {};
    const first = jobs.length ? jobs[0] : null;

    _syncShipyardQueueLiveState(jobs);

    const sig = _shipyardQueueSignature(jobs, summary);

    if (!jobs.length) {
      _lastShipyardQueueSignature = sig;
      _productionZeroHandled.shipyard = "";
      _finishRefreshArmed.shipyard = false;
      _shipyardUnitFinishKey = "";
      SHIPYARDQ.active.finishTime = 0;
      SHIPYARDQ.active.totalSeconds = 0;
      _renderProductionMiniQueue("shipyard-mini-queue", qd, { domain: "shipyard" });
      clearAllProductionCardQueues(page);
      GC.startProgressTicker();
      return;
    }

    if (sig === _lastShipyardQueueSignature) {
      const finishTime = first ? resolveQueueJobFinishTime(first) : 0;
      const nextUnitFinish = first
        ? parseTimerTarget(first.next_countdown_at ?? first.next_finish_at ?? 0)
        : 0;
      const now = getTimerServerNow();
      const overdue =
        (finishTime > 0 && finishTime <= now) ||
        (nextUnitFinish > 0 && nextUnitFinish <= now);
      if (!overdue) {
        _renderProductionMiniQueue("shipyard-mini-queue", qd, { domain: "shipyard" });
        clearAllProductionCardQueues(page);
        GC.startProgressTicker();
        return;
      }
    }
    _lastShipyardQueueSignature = sig;
    _productionZeroHandled.shipyard = "";

    _renderProductionMiniQueue("shipyard-mini-queue", qd, { domain: "shipyard" });
    if (!jobs.length) _finishRefreshArmed.shipyard = false;
    else clearFinishRefreshArmed("shipyard", jobs);

    clearAllProductionCardQueues(page);
    GC.startProgressTicker();
  }

  function parseShipyardPageData(page) {
    const el = document.getElementById("shipyard-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  function updateShipyardStockBadges(page, ships) {
    if (!page) return;
    const stock = ships || {};
    page.querySelectorAll("[data-shipyard-stock]").forEach((el) => {
      const key = el.getAttribute("data-shipyard-stock");
      if (!key) return;
      const qty = Number(stock[key]) || 0;
      const text = fmtNumber(qty);
      if (el.textContent !== text) el.textContent = text;
    });
  }

  function renderShipyardInventory(page, ships) {
    updateShipyardStockBadges(page, ships);
  }

  function shipyardResourceIconHtml(resKey) {
    const icons = {
      metal: { file: "ferronit", mod: "gc-res-metal" },
      crystal: { file: "crytite", mod: "gc-res-crystal" },
      fuel_cells: { file: "fuel_cells", mod: "gc-res-fuel-cells" },
    };
    const cfg = icons[resKey];
    if (!cfg) return "";
    return (
      `<img src="/static/icons/${cfg.file}.png" alt="" ` +
      `class="gc-res-icon gc-res-icon--sm ${cfg.mod}" loading="lazy" aria-hidden="true">`
    );
  }

  function shipyardResourceLabel(resKey, tt) {
    const map = {
      metal: tt("resource_metal", "Metal"),
      crystal: tt("resource_crystal", "Crystal"),
      fuel_cells: tt("resource_fuel_cells", "Fuel cells"),
    };
    return map[resKey] || resKey;
  }

  function renderShipCostStackHtml(ship, resources) {
    return renderUnitCostStackHtml(ship, resources, 1);
  }

  function resolveUnitCardPreviewQty(qtyInp) {
    if (!qtyInp) return 1;
    const raw = String(qtyInp.value ?? "").trim();
    if (!raw) return 1;
    const n = readNumberInput(qtyInp);
    return n > 0 ? n : 1;
  }

  function storeUnitCardUnitCosts(costWrap, unitCosts) {
    if (!costWrap || !unitCosts) return;
    costWrap.dataset.unitCostMetal = String(Math.max(0, Math.floor(Number(unitCosts.cost_metal) || 0)));
    costWrap.dataset.unitCostCrystal = String(Math.max(0, Math.floor(Number(unitCosts.cost_crystal) || 0)));
    costWrap.dataset.unitCostFuel = String(Math.max(0, Math.floor(Number(unitCosts.cost_fuel_cells) || 0)));
  }

  function readUnitCardUnitCosts(costWrap) {
    if (!costWrap) {
      return { cost_metal: 0, cost_crystal: 0, cost_fuel_cells: 0 };
    }
    return {
      cost_metal: parseIntNumber(costWrap.dataset.unitCostMetal || "0"),
      cost_crystal: parseIntNumber(costWrap.dataset.unitCostCrystal || "0"),
      cost_fuel_cells: parseIntNumber(costWrap.dataset.unitCostFuel || "0"),
    };
  }

  function renderUnitCostStackHtml(unitCosts, resources, amount) {
    const qty = Math.max(1, Math.floor(Number(amount) || 0));
    const specs = [
      ["metal", "cost_metal"],
      ["crystal", "cost_crystal"],
      ["fuel_cells", "cost_fuel_cells"],
    ];
    return specs
      .map(([resKey, costKey]) => {
        const unit = Number(unitCosts[costKey]) || 0;
        const need = unit * qty;
        if (need <= 0) return "";
        const have = Number(resources[resKey]) || 0;
        return renderResourceCostChipHtml(resKey, need, have < need);
      })
      .filter(Boolean)
      .join("");
  }

  function militaryPageResources(_page) {
    return GC.lastState?.resources || {};
  }

  function syncUnitCardCostPreview(card, resources) {
    if (!card) return;
    const costWrap = card.querySelector("[data-shipyard-cost],[data-defense-cost]");
    const stack = costWrap?.querySelector(".gc-cost-stack");
    if (!costWrap || !stack) return;
    const unitCosts = readUnitCardUnitCosts(costWrap);
    const qtyInp = card.querySelector("[data-shipyard-qty],[data-defense-qty]");
    const amount = resolveUnitCardPreviewQty(qtyInp);
    const html = renderUnitCostStackHtml(unitCosts, resources || {}, amount);
    if (html && stack.innerHTML.trim() !== html.trim()) stack.innerHTML = html;
  }

  function initMilitaryUnitCostPreviewDelegation() {
    if (_militaryCostPreviewBound) return;
    _militaryCostPreviewBound = true;
    document.addEventListener("input", (e) => {
      const inp = e.target;
      if (!inp?.matches?.("[data-shipyard-qty],[data-defense-qty]")) return;
      const card = inp.closest("[data-ship-card],[data-defense-card]");
      if (!card) return;
      const page = card.closest("#shipyard-page,#defense-page");
      syncUnitCardCostPreview(card, militaryPageResources(page));
    });
  }

  function renderUnitBuildTimeFooterHtml(sec, tt) {
    const s = Math.max(0, Math.floor(Number(sec) || 0));
    if (s <= 0) return "";
    const label = tt("unit_technical_build_time", "Bauzeit");
    return (
      `<div class="gc-card-lr-row gc-card-footer-row gc-card-footer-row--time" data-unit-build-time>` +
      `<span class="gc-card-lr-label"><span aria-hidden="true">⏱</span> ${escapeHtml(label)}</span>` +
      `<span class="gc-card-lr-value gc-mono">${escapeHtml(formatDuration(s))}</span></div>`
    );
  }

  function shipyardReqItemVisible(item) {
    if (!item || item.met) return false;
    if (item.type === "building" && (item.key === "orbital_shipyard" || item.key === "shipyard")) {
      return false;
    }
    return true;
  }

  function renderShipyardReqBlocker(item, tt) {
    const label =
      item.type === "building"
        ? tt("building_" + item.key, item.key)
        : tt(item.key, item.key);
    const met = Boolean(item.met);
    const cls = met ? " is-met" : " is-unmet";
    const typeCls = item.type === "research" ? " shipyard-blocker-research" : " shipyard-blocker-building";
    const icon = met ? "✓" : "🔒";
    const cur = fmtNumber(Number(item.current) || 0);
    const req = fmtNumber(Number(item.required) || 0);
    return (
      `<span class="shipyard-blocker shipyard-blocker-req${typeCls}${cls}"` +
      ` title="${gcEscHtml(label)} L${req} (${cur}/${req})">` +
      `<span class="shipyard-blocker-icon" aria-hidden="true">${icon}</span>` +
      `<span class="shipyard-blocker-text">${gcEscHtml(label)}</span>` +
      `<span class="shipyard-blocker-progress gc-mono">L${cur}/${req}</span></span>`
    );
  }

  function renderShipyardLevelBlocker(required, current, tt) {
    const req = Number(required) || 0;
    const cur = Number(current) || 0;
    const met = cur >= req;
    const cls = met ? " is-met" : " is-unmet";
    const icon = met ? "✓" : "🔒";
    const label = tt("building_orbital_shipyard", "Orbital Shipyard");
    const title = tt("shipyard_locked_level", "Requires Orbital Shipyard level %(level)s")
      .replace("%(level)s", fmtNumber(req))
      .replace("{{level}}", fmtNumber(req));
    return (
      `<span class="shipyard-blocker shipyard-blocker-shipyard${cls}"` +
      ` title="${gcEscHtml(title)} (${fmtNumber(cur)}/${fmtNumber(req)})">` +
      `<span class="shipyard-blocker-icon" aria-hidden="true">${icon}</span>` +
      `<span class="shipyard-blocker-text">${gcEscHtml(label)}</span>` +
      `<span class="shipyard-blocker-progress gc-mono">L${fmtNumber(cur)}/${fmtNumber(req)}</span></span>`
    );
  }

  function renderShipyardResourceBlocker(resKey, need, have, tt) {
    const req = Number(need) || 0;
    const cur = Number(have) || 0;
    const met = cur >= req;
    const cls = met ? " is-met" : " is-unmet";
    const label = shipyardResourceLabel(resKey, tt);
    return (
      `<span class="shipyard-blocker shipyard-blocker-resource${cls}"` +
      ` title="${gcEscHtml(label)}: ${fmtNumber(cur)} / ${fmtNumber(req)}">` +
      `${shipyardResourceIconHtml(resKey)}` +
      `<span class="shipyard-blocker-text">${gcEscHtml(label)}</span>` +
      `<span class="shipyard-blocker-progress gc-mono">${fmtNumber(cur)}/${fmtNumber(req)}</span></span>`
    );
  }

  function renderShipyardBlockersHtml(ship, resources, syLevel, unlocked, tt) {
    const parts = [];
    if (!unlocked) {
      const reqSy = Number(ship.required_shipyard_level) || 0;
      const curSy = Number(syLevel) || 0;
      if (curSy < reqSy) {
        parts.push(renderShipyardLevelBlocker(reqSy, curSy, tt));
      }
      (ship.requirements?.items || [])
        .filter((item) => shipyardReqItemVisible(item))
        .forEach((item) => parts.push(renderShipyardReqBlocker(item, tt)));
      return parts.join("");
    }
    if (ship.can_build) return "";
    [
      ["metal", "cost_metal"],
      ["crystal", "cost_crystal"],
      ["fuel_cells", "cost_fuel_cells"],
    ].forEach(([resKey, costKey]) => {
      const need = Number(ship[costKey]) || 0;
      const have = Number(resources[resKey]) || 0;
      if (need > 0 && have < need) {
        parts.push(renderShipyardResourceBlocker(resKey, need, have, tt));
      }
    });
    return parts.join("");
  }

  function patchCompactUnitStatChips(card, attack, shield, hull, buildSeconds, tt) {
    const benefit = card?.querySelector("[data-unit-stats]");
    const mode = benefit?.dataset?.unitMode || "ship";
    const atk = Math.max(0, Math.floor(Number(attack) || 0));
    const shd = Math.max(0, Math.floor(Number(shield) || 0));
    const hul = Math.max(0, Math.floor(Number(hull) || 0));
    const hp = shd + hul > 0 ? shd + hul : hul;
    const sec = Math.max(0, Math.floor(Number(buildSeconds) || 0));
    let benefitHtml = "";
    if (mode === "defense" && hp > 0) {
      benefitHtml = renderCardLrRow(
        `🛡 ${tt("defense_stat_defense", "Verteidigung")}`,
        `<span class="gc-num-compact">${fmtIntParts(hp).display}</span>`
      );
    } else if (mode !== "defense" && atk > 0) {
      benefitHtml = renderCardLrRow(
        `⚔ ${tt("ship_stat_attack", "Angriff")}`,
        `<span class="gc-num-compact">${fmtIntParts(atk).display}</span>`
      );
    }
    if (benefit) {
      const wrapHtml = benefitHtml ? benefitHtml : "";
      if (benefit.innerHTML.trim() !== wrapHtml.trim()) benefit.innerHTML = wrapHtml;
    }
    let timeRow = card?.querySelector("[data-unit-build-time]");
    const timeHtml = sec > 0 ? renderUnitBuildTimeFooterHtml(sec, tt) : "";
    if (!timeHtml) {
      timeRow?.remove();
      return;
    }
    if (timeRow) {
      if (timeRow.outerHTML.trim() !== timeHtml.trim()) timeRow.outerHTML = timeHtml;
      return;
    }
    const costs = card?.querySelector(".gc-bld-card-meta");
    const twrap = document.createElement("div");
    twrap.innerHTML = timeHtml;
    timeRow = twrap.firstElementChild;
    if (!timeRow) return;
    if (costs) costs.insertAdjacentElement("afterend", timeRow);
    else card?.appendChild(timeRow);
  }

  function patchProductionStatChips(card, cycleSeconds, batchCapacity, tt) {
    patchCompactUnitStatChips(card, 0, 0, 0, cycleSeconds, tt);
  }

  function applyShipyardShipCard(card, ship, resources, syLevel, tt) {
    if (!card || !ship) return;
    const unlocked = card.dataset.unlocked === "1";
    card.classList.toggle("shipyard-ship-card--blocked", unlocked && !ship.can_build);
    card.classList.toggle("gc-prog-unaffordable", unlocked && !ship.can_build && ship.block_reason !== "queue_full");
    card.classList.toggle("gc-prog-affordable", unlocked && ship.can_build);

    const costWrap = card.querySelector("[data-shipyard-cost]");
    storeUnitCardUnitCosts(costWrap, ship);
    syncUnitCardCostPreview(card, resources);

    card.querySelector("[data-shipyard-blockers]")?.remove();

    if (ship.build_seconds != null) {
      patchCompactUnitStatChips(
        card,
        ship.attack,
        ship.shield,
        ship.hull,
        ship.build_seconds,
        tt
      );
    }

    if (!unlocked) return;
    const ownedCount = ship.owned_count ?? ship.owned ?? ship.stock;
    if (ownedCount != null) {
      const stockEl = card.querySelector(`[data-shipyard-stock="${ship.ship_key}"]`);
      if (stockEl) {
        const text = fmtNumber(Number(ownedCount) || 0);
        if (stockEl.textContent !== text) stockEl.textContent = text;
      }
    }
    const btn = card.querySelector("[data-shipyard-build]");
    const maxBtn = card.querySelector("[data-shipyard-max]");
    if (btn) {
      btn.disabled = !ship.can_build;
      btn.dataset.canBuild = ship.can_build ? "1" : "0";
      if (btn.dataset.building !== "1") btn.classList.remove("is-loading");
      const queueFull = ship.block_reason === "queue_full";
      const buildLabel = tt("shipyard_build_btn", "Bauen");
      const fullLabel = tt("shipyard_btn_queue_full", "Werftwarteschlange voll");
      if (queueFull) {
        btn.textContent = fullLabel;
        btn.title = fullLabel;
      } else {
        btn.textContent = buildLabel;
        btn.removeAttribute("title");
      }
    }
    if (maxBtn) maxBtn.dataset.maxQty = String(ship.max_build || 0);
    const qtyInp = card.querySelector(`[data-shipyard-qty="${ship.ship_key}"]`);
    if (qtyInp) {
      const cap = Number(ship.max_build) || 0;
      if (cap > 0) qtyInp.dataset.inputMax = String(cap);
      else qtyInp.removeAttribute("data-input-max");
    }
    const stockEl = card.querySelector("[data-shipyard-stock]");
    if (stockEl && ship.owned_count != null) {
      const text = fmtNumber(Number(ship.owned_count) || 0);
      if (stockEl.textContent !== text) stockEl.textContent = text;
    }
  }

  function applyShipyardState(page, data) {
    if (!page || !data) return;
    const statePlanet = Number(data.planet_id || 0);
    const activePlanet = Number(GC.lastState?.active_planet_id || page.dataset.planetId || 0);
    if (activePlanet > 0 && statePlanet > 0 && activePlanet !== statePlanet) {
      return;
    }
    const tt = (key, fb) => t(key, fb);
    const resources = data.resources || {};

    if (data.planet_id) page.dataset.planetId = String(data.planet_id);

    if (data.resources && typeof GC.mergeLastState === "function") {
      GC.mergeLastState({ resources: { ...resources } }, "shipyard_state");
      if (typeof GC.patchShellHudFromState === "function") {
        GC.patchShellHudFromState(
          { ...GC.lastState, resources: { ...resources } },
          { forceResourceBar: true, reason: "shipyard_state" }
        );
      }
    }

    if (data.orbital_shipyard_level != null) {
      page.dataset.shipyardLevel = String(data.orbital_shipyard_level);
      const lvlEl = page.querySelector("[data-shipyard-level-label]");
      if (lvlEl) {
        const lvlText = tt("shipyard_level_value", "Level %(level)s");
        lvlEl.textContent = lvlText.replace("%(level)s", fmtNumber(data.orbital_shipyard_level));
      }
    }
    if (data.production_batch_capacity != null) {
      page.dataset.shipyardBatchCapacity = String(data.production_batch_capacity);
      const capEl = page.querySelector("[data-shipyard-batch-capacity]");
      if (capEl) {
        capEl.textContent = tt(
          "shipyard_parallel_capacity",
          "Capacity per build cycle: %(capacity)s ships"
        ).replace("%(capacity)s", fmtNumber(data.production_batch_capacity));
      }
    }

    if (data.current_ships) updateShipyardStockBadges(page, data.current_ships);
    if (data.shipyard_queue) renderShipyardQueue(page, data.shipyard_queue);

    const syLevel = data.orbital_shipyard_level != null ? data.orbital_shipyard_level : page.dataset.shipyardLevel;

    (data.buildable_ships || []).forEach((ship) => {
      const card = page.querySelector(`[data-ship-key="${ship.ship_key}"][data-unlocked="1"]`);
      applyShipyardShipCard(card, ship, resources, syLevel, tt);
    });

    (data.locked_ships || []).forEach((ship) => {
      const card = page.querySelector(`[data-ship-key="${ship.ship_key}"][data-unlocked="0"]`);
      applyShipyardShipCard(card, ship, resources, syLevel, tt);
    });
  }

  async function refreshShipyardState(page) {
    let planetId = parseInt(page.dataset.planetId || "0", 10);
    const activePlanet = Number(GC.lastState?.active_planet_id || 0);
    if (activePlanet > 0) {
      if (planetId > 0 && planetId !== activePlanet) return null;
      planetId = activePlanet;
      page.dataset.planetId = String(activePlanet);
    }
    const q = planetId ? `?planet_id=${planetId}` : "";
    const res = await GC.fetchGameAction(`/api/shipyard${q}`, { method: "GET" });
    if (res?.ok && res.data) {
      applyShipyardState(page, res.data);
      return res.data;
    }
    return null;
  }

  function refreshShipyardStateCoalesced(page) {
    if (!page) return Promise.resolve(null);
    if (_shipyardApiInFlight) return _shipyardApiInFlight;
    _shipyardApiInFlight = Promise.resolve(refreshShipyardState(page)).finally(() => {
      _shipyardApiInFlight = null;
    });
    return _shipyardApiInFlight;
  }

  // GC-PERF-JS-002 — page binder lives in static/js/pages/shipyard.js (no duplicate body).
  GC.applyShipyardState = applyShipyardState;
  GC.parseShipyardPageData = parseShipyardPageData;
  GC.refreshShipyardState = refreshShipyardState;
  GC.startShipyardTimers = startShipyardTimers;
  GC.stopShipyardTimers = stopShipyardTimers;
  GC.shipyardActionReasonText = shipyardActionReasonText;
  GC.militaryPageResources = militaryPageResources;
  GC.syncUnitCardCostPreview = syncUnitCardCostPreview;
  GC.clearShipyardQueueSignature = function clearShipyardQueueSignature() {
    _lastShipyardQueueSignature = "";
  };

  /** Thin delegate — real bind/init in GC.pages.shipyard (shipyard.js). */
  function initShipyard() {
    if (GC.pages && typeof GC.pages.shipyard?.init === "function") {
      return GC.pages.shipyard.init();
    }
  }

  let _defenseRefreshTimer = null;
  let _defenseUnitFinishKey = "";
  let _defenseBound = false;
  let _defensePollIntervalId = null;
  let _lastDefenseQueueSignature = "";

  function defenseIconUrl(defenseKey) {
    return GC.preferWebpStaticUrl(
      `/static/img/defense/${String(defenseKey || "").trim()}.png`
    );
  }
  GC.defenseIconUrl = defenseIconUrl;

  function defenseLabel(defenseKey) {
    const k = String(defenseKey || "").trim();
    return defenseDisplayName(k);
  }

  function normalizeDefenseApiPayload(res) {
    if (!res) return null;
    if (res.data && typeof res.data === "object") return res.data;
    if (res.defenses && typeof res.defenses === "object") {
      return {
        ...res.defenses,
        defense_queue: res.queue || res.defenses.defense_queue,
      };
    }
    return null;
  }

  function updateDefenseStockBadges(page, stock) {
    if (!page) return;
    const inv = stock || {};
    page.querySelectorAll("[data-defense-stock]").forEach((el) => {
      const key = el.getAttribute("data-defense-stock");
      if (!key) return;
      const qty = Number(inv[key]) || 0;
      const text = fmtNumber(qty);
      if (el.textContent !== text) el.textContent = text;
    });
  }

  function renderDefenseInventory(page, stock) {
    updateDefenseStockBadges(page, stock);
  }

  function parseDefensePageData(page) {
    const el = document.getElementById("defense-page-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "{}");
    } catch (_) {
      return null;
    }
  }

  function _defenseQueueSignature(queueList, summary) {
    try {
      const count = summary?.count ?? (queueList?.length ?? 0);
      const items = (queueList || [])
        .map(
          (j, idx) =>
            `${j.id}:${j.queue_position ?? idx + 1}:${j.units_delivered ?? 0}:${j.amount_remaining ?? j.amount}:${j.next_finish_at || j.finish_at || 0}`
        )
        .join("|");
      return `${count}|${items}`;
    } catch (_) {
      return "";
    }
  }

  function patchDefenseCardQueues(page, _queueData) {
    // GC-UNIT-QUEUE-DEDUP-001: unit cards must not host queue UI.
    clearAllProductionCardQueues(page);
  }

  function _syncDefenseQueueLiveState(queueList) {
    const first = queueList && queueList.length ? queueList[0] : null;
    if (first) {
      const finishTime = resolveQueueJobFinishTime(first);
      const isActiveHead = Boolean(first.is_active !== false);
      if (isActiveHead && finishTime) {
        const now = getTimerServerNow();
        const remaining = queueJobRemainingSeconds(finishTime, now, resolveQueueJobRemaining(first));
        const totalRaw = Number(first.order_total_seconds || first.total_seconds || 0);
        const total = totalRaw > 0 ? Math.floor(totalRaw) : Math.max(1, remaining + 1);
        DEFENSEQ.active.finishTime = finishTime;
        DEFENSEQ.active.totalSeconds = total;
      } else {
        DEFENSEQ.active.finishTime = 0;
        DEFENSEQ.active.totalSeconds = 0;
      }
    } else {
      DEFENSEQ.active.finishTime = 0;
      DEFENSEQ.active.totalSeconds = 0;
    }
  }

  function renderDefenseQueue(page, queuePayload) {
    const host = document.getElementById("defense-mini-queue");
    if (!host) return;

    const qd = queuePayload || { queue: [], summary: { count: 0, limit: 3, refund_percent: 100, refund_percent_active: 50 } };
    const jobs = qd.queue || [];
    const summary = qd.summary || {};
    const first = jobs.length ? jobs[0] : null;

    _syncDefenseQueueLiveState(jobs);

    const sig = _defenseQueueSignature(jobs, summary);

    if (!jobs.length) {
      _lastDefenseQueueSignature = sig;
      _productionZeroHandled.defense = "";
      _finishRefreshArmed.defense = false;
      _defenseUnitFinishKey = "";
      DEFENSEQ.active.finishTime = 0;
      DEFENSEQ.active.totalSeconds = 0;
      _renderProductionMiniQueue("defense-mini-queue", qd, { domain: "defense" });
      clearAllProductionCardQueues(page);
      GC.startProgressTicker();
      return;
    }

    if (sig === _lastDefenseQueueSignature) {
      const finishTime = first ? resolveQueueJobFinishTime(first) : 0;
      const nextUnitFinish = first
        ? parseTimerTarget(first.next_countdown_at ?? first.next_finish_at ?? 0)
        : 0;
      const now = getTimerServerNow();
      const overdue =
        (finishTime > 0 && finishTime <= now) ||
        (nextUnitFinish > 0 && nextUnitFinish <= now);
      if (!overdue) {
        _renderProductionMiniQueue("defense-mini-queue", qd, { domain: "defense" });
        clearAllProductionCardQueues(page);
        GC.startProgressTicker();
        return;
      }
    }
    _lastDefenseQueueSignature = sig;
    _productionZeroHandled.defense = "";

    _renderProductionMiniQueue("defense-mini-queue", qd, { domain: "defense" });
    if (!jobs.length) _finishRefreshArmed.defense = false;
    else clearFinishRefreshArmed("defense", jobs);

    clearAllProductionCardQueues(page);
    GC.startProgressTicker();
  }

  function applyDefenseState(page, data) {
    if (!page || !data) return;
    const tt = (key, fallback) => t(key, fallback);
    if (data.planet_id != null) page.dataset.planetId = String(data.planet_id);
    if (data.defense_factory_level != null) {
      page.dataset.factoryLevel = String(data.defense_factory_level);
      const lvlEl = page.querySelector("[data-defense-factory-label]");
      if (lvlEl) {
        lvlEl.textContent = tt("defense_factory_level", "Level %(level)s").replace(
          "%(level)s",
          fmtNumber(data.defense_factory_level)
        );
      }
    }
    if (data.production_batch_capacity != null) {
      page.dataset.defenseBatchCapacity = String(data.production_batch_capacity);
      const capEl = page.querySelector("[data-defense-batch-capacity]");
      if (capEl) {
        capEl.textContent = tt(
          "defense_production_capacity",
          "Production via orbital shipyard capacity: %(capacity)s ships per cycle"
        ).replace("%(capacity)s", fmtNumber(data.production_batch_capacity));
      }
    }
    if (data.current_defense) updateDefenseStockBadges(page, data.current_defense);
    if (data.defense_queue) renderDefenseQueue(page, data.defense_queue);
    (data.buildable_defense || []).forEach((unit) => {
      applyDefenseUnitCard(page, unit, data.resources || {}, tt);
    });
    (data.locked_defense || []).forEach((unit) => {
      applyDefenseUnitCard(page, unit, data.resources || {}, tt, { locked: true });
    });
  }

  function applyDefenseUnitCard(page, unit, resources, tt, opts = {}) {
    const card = page.querySelector(`[data-defense-card="${unit.defense_key}"]`);
    if (!card) return;

    if (unit.stock != null) {
      const stockEl = card.querySelector(`[data-defense-stock="${unit.defense_key}"]`);
      if (stockEl) {
        const text = fmtNumber(Number(unit.stock) || 0);
        if (stockEl.textContent !== text) stockEl.textContent = text;
      }
    }

    if (opts.locked) return;

    card.classList.toggle("shipyard-ship-card--blocked", !unit.can_build);
    card.classList.toggle("gc-prog-unaffordable", !unit.can_build && unit.block_reason !== "queue_full");
    card.classList.toggle("gc-prog-affordable", !!unit.can_build);

    const costWrap = card.querySelector("[data-defense-cost]");
    storeUnitCardUnitCosts(costWrap, {
      cost_metal: unit.cost_metal,
      cost_crystal: unit.cost_crystal,
      cost_fuel_cells: unit.cost_fuel_cells,
    });
    syncUnitCardCostPreview(card, resources);

    card.querySelector("[data-defense-blockers]")?.remove();

    const maxBtn = card.querySelector(`[data-defense-max="${unit.defense_key}"]`);
    if (maxBtn) maxBtn.dataset.maxQty = String(unit.max_build || 0);
    const qtyInp = card.querySelector(`[data-defense-qty="${unit.defense_key}"]`);
    if (qtyInp) {
      const cap = Number(unit.max_build) || 0;
      if (cap > 0) qtyInp.dataset.inputMax = String(cap);
      else qtyInp.removeAttribute("data-input-max");
    }
    const btn = card.querySelector(`[data-defense-build="${unit.defense_key}"]`);
    if (btn) {
      btn.dataset.canBuild = unit.can_build ? "1" : "0";
      btn.disabled = !unit.can_build;
      const queueFull = unit.block_reason === "queue_full";
      const buildLabel = tt("defense_build_btn", "Bauen");
      const fullLabel = tt("defense_btn_queue_full", "Warteschlange voll");
      if (queueFull) {
        btn.textContent = fullLabel;
        btn.title = fullLabel;
      } else {
        btn.textContent = buildLabel;
        btn.removeAttribute("title");
      }
    }
    if (unit.build_seconds != null) {
      patchCompactUnitStatChips(
        card,
        unit.attack,
        unit.shield,
        unit.hull,
        unit.build_seconds,
        tt
      );
    }
  }

  async function refreshDefenseState(page) {
    const planetId = parseInt(page.dataset.planetId || "0", 10);
    const q = planetId ? `?planet_id=${planetId}` : "";
    const res = await GC.fetchGameAction(`/api/defense${q}`, { method: "GET" });
    const payload = normalizeDefenseApiPayload(res);
    if (res?.ok && payload) {
      applyDefenseState(page, payload);
      return payload;
    }
    return null;
  }

  function refreshDefenseStateCoalesced(page) {
    if (!page) return Promise.resolve(null);
    if (_defenseApiInFlight) return _defenseApiInFlight;
    _defenseApiInFlight = Promise.resolve(refreshDefenseState(page)).finally(() => {
      _defenseApiInFlight = null;
    });
    return _defenseApiInFlight;
  }

  function scheduleDefenseRefreshFromState(immediate) {
    const page = document.getElementById("defense-page");
    if (!page || page.dataset.ready !== "1") return;
    if (_defenseRefreshTimer != null) {
      clearTimeout(_defenseRefreshTimer);
      _defenseRefreshTimer = null;
    }
    const delay = immediate ? 0 : 150;
    _defenseRefreshTimer = GC.setSafeTimeout(() => {
      _defenseRefreshTimer = null;
      if (page.dataset.queueRefreshBusy === "1") return;
      page.dataset.queueRefreshBusy = "1";
      refreshDefenseStateCoalesced(page)
        .finally(() => {
          delete page.dataset.queueRefreshBusy;
          _defenseUnitFinishKey = "";
        });
    }, delay);
  }

  function stopDefenseTimers() {
    if (_defensePollIntervalId != null) {
      clearInterval(_defensePollIntervalId);
      _defensePollIntervalId = null;
    }
  }

  function startDefenseTimers() {
    stopDefenseTimers();
    const page = document.getElementById("defense-page");
    if (!page || page.dataset.ready !== "1") return;
    GC.startProgressTicker();
  }

  function bindDefenseOnce() {
    if (_defenseBound) return;
    _defenseBound = true;
    const tt = (key, fallback) => t(key, fallback);
    const apiError = (res) => (res && (res.error || res.reason)) || "generic";
    const reasonText = (reason) =>
      tt(`defense_error_${reason}`, tt(`fleet_error_${reason}`, reason || "Error"));

    document.addEventListener("click", async (e) => {
      const page = document.getElementById("defense-page");
      if (!page || page.dataset.ready !== "1") return;

      const maxBtn = e.target.closest("[data-defense-max]");
      if (maxBtn && page.contains(maxBtn)) {
        e.preventDefault();
        const dk = maxBtn.getAttribute("data-defense-max");
        const qtyInp = page.querySelector(`[data-defense-qty="${dk}"]`);
        const maxQty = parseIntNumber(
          maxBtn.dataset.maxQty || maxBtn.getAttribute("data-max-qty") || "0"
        );
        if (qtyInp && maxQty > 0) {
          qtyInp.dataset.inputMax = String(maxQty);
          setNumberInputValue(qtyInp, maxQty);
          const card = maxBtn.closest("[data-defense-card]");
          if (card) syncUnitCardCostPreview(card, militaryPageResources(page));
        }
        return;
      }

      const cancelBtn = e.target.closest("[data-defense-queue-cancel]");
      if (cancelBtn && page.contains(cancelBtn)) {
        e.preventDefault();
        const jobId = parseInt(cancelBtn.getAttribute("data-defense-queue-cancel") || "0", 10);
        const planetId = parseInt(page.dataset.planetId || "0", 10);
        if (!jobId) return;
        cancelBtn.disabled = true;
        try {
          const res = await GC.fetchGameAction("/api/defense/cancel", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ job_id: jobId, planet_id: planetId || undefined }),
          });
          if (res?.ok) {
            if (res.state) applyActionState(res, "defense_cancel");
            const payload = normalizeDefenseApiPayload(res);
            if (payload) applyDefenseState(page, payload);
            else await refreshDefenseState(page);
          } else {
            showNotify(reasonText(res?.error || apiError(res)), "error");
          }
        } catch (_) {
          showNotify(reasonText("generic"), "error");
        } finally {
          cancelBtn.disabled = false;
        }
        return;
      }

      const buildBtn = e.target.closest("[data-defense-build]");
      if (!buildBtn || !page.contains(buildBtn) || buildBtn.disabled) return;
      if (buildBtn.dataset.building === "1" || buildBtn.dataset.canBuild === "0") return;
      e.preventDefault();
      const defenseKey = buildBtn.getAttribute("data-defense-build");
      const qtyInp = page.querySelector(`[data-defense-qty="${defenseKey}"]`);
      const amount = readNumberInput(qtyInp) || 1;
      const planetId = parseInt(page.dataset.planetId || "0", 10);
      buildBtn.dataset.building = "1";
      buildBtn.disabled = true;
      buildBtn.classList.add("is-loading");
      try {
        const res = await GC.fetchGameAction("/api/defense/build", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ defense_key: defenseKey, amount, planet_id: planetId || undefined }),
        });
        if (res?.ok) {
          _lastDefenseQueueSignature = "";
          if (res.state) applyActionState(res, "defense_build");
          const payload = normalizeDefenseApiPayload(res);
          if (payload) applyDefenseState(page, payload);
          else if (!res.state) await refreshDefenseState(page);
        } else {
          showNotify(reasonText(res?.error || apiError(res)), "error");
        }
      } catch (_) {
        showNotify(reasonText("generic"), "error");
      } finally {
        delete buildBtn.dataset.building;
        buildBtn.classList.remove("is-loading");
        buildBtn.disabled = buildBtn.dataset.canBuild !== "1";
      }
    });
  }

  function initDefense() {
    bindDefenseOnce();
    const page = document.getElementById("defense-page");
    if (!page || page.dataset.ready !== "1") return;
    const data = parseDefensePageData(page);
    if (!data) return;
    applyDefenseState(page, data);
    startDefenseTimers();
    GC.registerCleanup(stopDefenseTimers);
    GC.startProgressTicker();
  }

  GC.refreshDefenseState = refreshDefenseState;

  function initExchangePanel() {
    const panel = document.getElementById("gc-exchange-panel");
    if (!panel || panel.dataset.disabled === "1") return;

    const page = document.getElementById("trader-hub-page");
    const form = panel.querySelector("#gc-exchange-form");
    const amountInput = panel.querySelector("#gc-exchange-amount");
    const routeSelect = panel.querySelector("[data-exchange-route]");
    const previewEl = panel.querySelector("[data-exchange-preview]");
    const receiveSummaryEl = panel.querySelector("[data-exchange-receive-summary]");
    const errorEl = panel.querySelector("[data-exchange-error]");
    const remainingEl = page?.querySelector("[data-exchange-daily-remaining]") || panel.querySelector("[data-exchange-daily-remaining]");
    const dailyUsedEl = page?.querySelector("[data-exchange-daily-used]");
    const dailyLimitEl = page?.querySelector("[data-exchange-daily-limit]");
    const dailyLimitDisplayEl = page?.querySelector("[data-exchange-daily-limit-display]");
    const empireDayEl = page?.querySelector("[data-exchange-empire-day]");
    const submitBtn = panel.querySelector(".gc-exchange-submit");
    const rateDisplayEl = panel.querySelector("[data-exchange-rate-display]");
    const giveTiles = panel.querySelectorAll("[data-exchange-give]");
    const receiveTiles = panel.querySelectorAll("[data-exchange-receive]");
    const maxBtn = panel.querySelector("[data-exchange-max]");
    if (!form || !amountInput || !previewEl) return;

    const tt = (key, fallback) => t(key, fallback);
    const iconBase = "/static/icons/";
    const resourceLabels = {
      metal: () => tt("resource_metal", "Ferronit"),
      crystal: () => tt("resource_crystal", "Crytite"),
      fuel_cells: () => tt("resource_fuel_cells", "Fuel cells"),
    };
    const ROUTES = {
      metal_to_crystal: { from: "metal", to: "crystal" },
      crystal_to_metal: { from: "crystal", to: "metal" },
      metal_to_fuel_cells: { from: "metal", to: "fuel_cells" },
      crystal_to_fuel_cells: { from: "crystal", to: "fuel_cells" },
      fuel_cells_to_metal: { from: "fuel_cells", to: "metal" },
      fuel_cells_to_crystal: { from: "fuel_cells", to: "crystal" },
    };
    const ROUTE_BY_PAIR = {
      "metal:crystal": "metal_to_crystal",
      "crystal:metal": "crystal_to_metal",
      "metal:fuel_cells": "metal_to_fuel_cells",
      "crystal:fuel_cells": "crystal_to_fuel_cells",
      "fuel_cells:metal": "fuel_cells_to_metal",
      "fuel_cells:crystal": "fuel_cells_to_crystal",
    };
    const RECEIVE_FOR_GIVE = {
      metal: ["crystal", "fuel_cells"],
      crystal: ["metal", "fuel_cells"],
      fuel_cells: ["metal", "crystal"],
    };

    const readRates = () => ({
      m2c: parseFloat(panel.dataset.rateM2c || "0.8"),
      c2m: parseFloat(panel.dataset.rateC2m || "0.8"),
      fuelMetalPer: parseFloat(panel.dataset.fuelMetalPer || "45"),
      fuelCrystalPer: parseFloat(panel.dataset.fuelCrystalPer || "28"),
      minAmount: parseInt(panel.dataset.min || "100", 10),
      fuelMin: parseInt(panel.dataset.fuelMin || "10", 10),
    });

    const reasonText = (reason) => tt(`exchange_error_${reason}`, tt("exchange_error_generic", "Exchange failed."));

    const selectedDirection = () => panel.dataset.dir || routeSelect?.value || "metal_to_crystal";

    const routeParts = (dir) => ROUTES[dir] || ROUTES.metal_to_crystal;

    const directionForPair = (give, receive) => ROUTE_BY_PAIR[`${give}:${receive}`] || null;

    const alternateReceive = (give, currentReceive) => {
      if (give === "metal") return currentReceive === "crystal" ? "fuel_cells" : "crystal";
      if (give === "crystal") return currentReceive === "metal" ? "fuel_cells" : "metal";
      if (give === "fuel_cells") return currentReceive === "metal" ? "crystal" : "metal";
      return "crystal";
    };

    const alternateGive = (receive, currentGive) => {
      if (receive === "metal") return currentGive === "crystal" ? "fuel_cells" : "crystal";
      if (receive === "crystal") return currentGive === "metal" ? "fuel_cells" : "metal";
      if (receive === "fuel_cells") return currentGive === "metal" ? "crystal" : "metal";
      return "metal";
    };

    const updateTileStates = (give, receive) => {
      giveTiles.forEach((btn) => {
        const res = btn.getAttribute("data-exchange-give") || "";
        const active = res === give;
        const canGive = (RECEIVE_FOR_GIVE[res] || []).length > 0;
        btn.classList.toggle("is-active", active);
        btn.classList.toggle("is-disabled", !canGive);
        btn.setAttribute("aria-pressed", active ? "true" : "false");
        btn.disabled = !canGive;
        btn.removeAttribute("title");
      });
      receiveTiles.forEach((btn) => {
        const res = btn.getAttribute("data-exchange-receive") || "";
        const active = res === receive;
        const enabled = (RECEIVE_FOR_GIVE[give] || []).includes(res);
        btn.classList.toggle("is-active", active);
        btn.classList.toggle("is-disabled", !enabled);
        btn.setAttribute("aria-pressed", active ? "true" : "false");
        btn.disabled = !enabled;
      });
    };

    const minForRoute = (dir) => {
      const cfg = readRates();
      const { from, to } = routeParts(dir);
      if (from === "fuel_cells") return cfg.fuelMin;
      if (to === "fuel_cells") {
        const per = from === "metal" ? cfg.fuelMetalPer : cfg.fuelCrystalPer;
        return Math.max(cfg.minAmount, Math.ceil(Math.max(0.001, per)));
      }
      return cfg.minAmount;
    };

    const computeReceive = (dir, amount) => {
      const cfg = readRates();
      const { from, to } = routeParts(dir);
      const raw = parseIntNumber(amount);
      if (!raw || raw <= 0) return 0;
      if (from === "metal" && to === "crystal") {
        return Math.floor(raw / Math.max(0.001, cfg.m2c));
      }
      if (from === "crystal" && to === "metal") return Math.floor(raw * Math.max(0, cfg.c2m));
      if (from === "metal" && to === "fuel_cells") return Math.floor(raw / Math.max(0.001, cfg.fuelMetalPer));
      if (from === "crystal" && to === "fuel_cells") return Math.floor(raw / Math.max(0.001, cfg.fuelCrystalPer));
      if (from === "fuel_cells" && to === "metal") return Math.floor(raw * Math.max(0.001, cfg.fuelMetalPer));
      if (from === "fuel_cells" && to === "crystal") return Math.floor(raw * Math.max(0.001, cfg.fuelCrystalPer));
      return 0;
    };

    const displayRate = (dir) => {
      const cfg = readRates();
      const { from, to } = routeParts(dir);
      if (from === "metal" && to === "crystal") {
        return tf(
          "exchange_rate_ferronite_per_crytite",
          { rate: formatRate(Math.max(0.001, cfg.m2c)) },
          `${formatRate(Math.max(0.001, cfg.m2c))} Ferronite per 1 Crytite`
        );
      }
      if (from === "crystal" && to === "metal") {
        return tf(
          "exchange_rate_ferronite_per_crytite",
          { rate: formatRate(Math.max(0, cfg.c2m)) },
          `${formatRate(Math.max(0, cfg.c2m))} Ferronite per 1 Crytite`
        );
      }
      if (from === "metal" && to === "fuel_cells") return formatRate(1 / Math.max(0.001, cfg.fuelMetalPer));
      if (from === "crystal" && to === "fuel_cells") return formatRate(1 / Math.max(0.001, cfg.fuelCrystalPer));
      if (from === "fuel_cells" && to === "metal") return formatRate(cfg.fuelMetalPer);
      if (from === "fuel_cells" && to === "crystal") return formatRate(cfg.fuelCrystalPer);
      return "0";
    };

    const formatRate = (rate) => (rate >= 1 ? String(Math.round(rate)) : rate.toFixed(3).replace(/\.?0+$/, ""));

    const readExchangeGiveBalance = (resource) => {
      const ex = GC.lastState?.exchange;
      if (ex?.balances && typeof ex.balances[resource] === "number") {
        return Math.max(0, Math.floor(ex.balances[resource]));
      }
      const dsMap = {
        metal: panel.dataset.balanceMetal,
        crystal: panel.dataset.balanceCrystal,
        fuel_cells: panel.dataset.balanceFuelCells,
      };
      const fromDs = parseIntNumber(dsMap[resource]);
      if (Number.isFinite(fromDs) && fromDs >= 0) return fromDs;
      const p = GC.lastState?.player || GC.lastState?.resources || {};
      const fromPlayer = parseIntNumber(p[resource]);
      if (Number.isFinite(fromPlayer) && fromPlayer >= 0) return fromPlayer;
      return 0;
    };

    const readExchangeDailyRemaining = () => {
      const ex = GC.lastState?.exchange;
      if (typeof ex?.daily_remaining === "number") {
        return Math.max(0, Math.floor(ex.daily_remaining));
      }
      const fromDs = parseIntNumber(panel.dataset.dailyRemaining);
      if (Number.isFinite(fromDs) && fromDs >= 0) return fromDs;
      const used = parseIntNumber(dailyUsedEl?.textContent);
      const limit = parseIntNumber(dailyLimitEl?.textContent);
      if (Number.isFinite(used) && Number.isFinite(limit) && limit >= 0) {
        return Math.max(0, limit - used);
      }
      return 0;
    };

    const computeExchangeMaxInput = () => {
      const dir = selectedDirection();
      if (!ROUTES[dir]) return 0;
      const { from } = routeParts(dir);
      if (!from) return 0;
      const balance = readExchangeGiveBalance(from);
      const remaining = readExchangeDailyRemaining();
      return Math.max(0, Math.min(balance, remaining));
    };

    const updateExchangeMaxBtn = () => {
      if (!maxBtn) return;
      const minNow = parseInt(panel.dataset.routeMin || String(minForRoute(selectedDirection())), 10);
      const maxVal = computeExchangeMaxInput();
      const enabled = maxVal > 0 && maxVal >= minNow && panel.dataset.disabled !== "1";
      maxBtn.disabled = !enabled;
      maxBtn.setAttribute("aria-disabled", enabled ? "false" : "true");
    };

    const applyExchangeMaxAmount = () => {
      const maxVal = computeExchangeMaxInput();
      if (maxVal <= 0) return;
      setNumberInputValue(amountInput, maxVal);
      amountInput.dispatchEvent(new Event("input", { bubbles: true }));
      scheduleUpdatePreview();
    };

    const setDirection = (dir) => {
      const next = ROUTES[dir] ? dir : "metal_to_crystal";
      panel.dataset.dir = next;
      if (routeSelect && routeSelect.value !== next) routeSelect.value = next;
      const { from, to } = routeParts(next);
      updateTileStates(from, to);
      if (rateDisplayEl) rateDisplayEl.textContent = displayRate(next);
      const minNow = minForRoute(next);
      panel.dataset.routeMin = String(minNow);
      amountInput.min = String(minNow);
      amountInput.dataset.exchangeMin = String(minNow);
      if (!amountInput.value || readNumberInput(amountInput) < minNow) {
        setNumberInputValue(amountInput, minNow);
      }
      updatePreview();
      updateExchangeMaxBtn();
    };

    const setResourcePair = (give, receive) => {
      let nextGive = give;
      let nextReceive = receive;
      if (nextGive === nextReceive) {
        nextReceive = alternateReceive(nextGive, nextReceive);
      }
      let dir = directionForPair(nextGive, nextReceive);
      if (!dir) {
        nextGive = alternateGive(nextReceive, nextGive);
        dir = directionForPair(nextGive, nextReceive) || "metal_to_crystal";
      }
      setDirection(dir);
    };

    let previewRaf = 0;
    const updatePreview = () => {
      const raw = readNumberInput(amountInput);
      const minNow = parseInt(panel.dataset.routeMin || String(minForRoute(selectedDirection())), 10);
      const dir = selectedDirection();
      const { to } = routeParts(dir);
      const valid = raw >= minNow;
      if (submitBtn) submitBtn.disabled = !valid;
      if (!valid) {
        previewEl.textContent = "–";
        if (receiveSummaryEl) receiveSummaryEl.textContent = "–";
        return;
      }
      const receive = computeReceive(dir, raw);
      const receiveLabel = resourceLabels[to]();
      previewEl.textContent = formatNumber(receive);
      if (receiveSummaryEl) {
        receiveSummaryEl.textContent = `${formatNumber(receive)} ${receiveLabel}`;
      }
      updateExchangeMaxBtn();
    };

    const scheduleUpdatePreview = () => {
      if (previewRaf) cancelAnimationFrame(previewRaf);
      previewRaf = requestAnimationFrame(() => {
        previewRaf = 0;
        updatePreview();
      });
    };

    const patchExchangeFromState = (exchange) => {
      if (!exchange) return;
      if (typeof exchange.daily_used === "number" && dailyUsedEl) {
        dailyUsedEl.textContent = fmtNumber(exchange.daily_used);
      }
      if (typeof exchange.daily_remaining === "number" && remainingEl) {
        remainingEl.textContent = fmtNumber(exchange.daily_remaining);
      }
      if (typeof exchange.daily_remaining === "number") {
        panel.dataset.dailyRemaining = String(Math.max(0, Math.floor(exchange.daily_remaining)));
      }
      if (exchange.balances && typeof exchange.balances === "object") {
        if (typeof exchange.balances.metal === "number") {
          panel.dataset.balanceMetal = String(Math.max(0, Math.floor(exchange.balances.metal)));
        }
        if (typeof exchange.balances.crystal === "number") {
          panel.dataset.balanceCrystal = String(Math.max(0, Math.floor(exchange.balances.crystal)));
        }
        if (typeof exchange.balances.fuel_cells === "number") {
          panel.dataset.balanceFuelCells = String(Math.max(0, Math.floor(exchange.balances.fuel_cells)));
        }
      }
      if (typeof exchange.daily_limit === "number" && dailyLimitEl) {
        dailyLimitEl.textContent = fmtNumber(exchange.daily_limit);
      }
      if (typeof exchange.daily_limit === "number" && dailyLimitDisplayEl) {
        dailyLimitDisplayEl.textContent = fmtNumber(exchange.daily_limit);
      }
      if (typeof exchange.empire_production_day_total === "number" && empireDayEl) {
        empireDayEl.textContent = tf(
          "trader_hub_empire_production_day",
          { total: fmtNumber(exchange.empire_production_day_total) },
          `Empire / Tag: ${fmtNumber(exchange.empire_production_day_total)}`
        );
      }
      if (typeof exchange.rate_metal_to_crystal === "number") {
        panel.dataset.rateM2c = String(exchange.rate_metal_to_crystal);
      }
      if (typeof exchange.rate_crystal_to_metal === "number") {
        panel.dataset.rateC2m = String(exchange.rate_crystal_to_metal);
      }
      if (typeof exchange.fuel_metal_per_unit === "number") {
        panel.dataset.fuelMetalPer = String(exchange.fuel_metal_per_unit);
      }
      if (typeof exchange.fuel_crystal_per_unit === "number") {
        panel.dataset.fuelCrystalPer = String(exchange.fuel_crystal_per_unit);
      }
      if (typeof exchange.fuel_min_units === "number") {
        panel.dataset.fuelMin = String(exchange.fuel_min_units);
      }
      if (typeof exchange.min_amount === "number") {
        panel.dataset.min = String(exchange.min_amount);
      }
      setDirection(selectedDirection());
      updateExchangeMaxBtn();
    };

    if (!panel.dataset.exchangeBound) {
      panel.dataset.exchangeBound = "1";

      giveTiles.forEach((btn) => {
        btn.addEventListener("click", () => {
          if (btn.disabled || btn.classList.contains("is-disabled")) return;
          const give = btn.getAttribute("data-exchange-give") || "metal";
          const { to } = routeParts(selectedDirection());
          setResourcePair(give, to);
        });
      });
      receiveTiles.forEach((btn) => {
        btn.addEventListener("click", () => {
          if (btn.disabled || btn.classList.contains("is-disabled")) return;
          const receive = btn.getAttribute("data-exchange-receive") || "crystal";
          const { from } = routeParts(selectedDirection());
          setResourcePair(from, receive);
        });
      });
      if (routeSelect) {
        routeSelect.addEventListener("change", () => {
          setDirection(routeSelect.value || "metal_to_crystal");
        });
      }
      amountInput.addEventListener("input", scheduleUpdatePreview);
      amountInput.addEventListener("change", scheduleUpdatePreview);
      amountInput.addEventListener("keyup", scheduleUpdatePreview);
      amountInput.addEventListener("paste", () => {
        scheduleUpdatePreview();
      });
      maxBtn?.addEventListener("click", (e) => {
        e.preventDefault();
        if (maxBtn.disabled) return;
        applyExchangeMaxAmount();
      });

      form.addEventListener("submit", async (e) => {
        e.preventDefault();
        if (errorEl) {
          errorEl.hidden = true;
          errorEl.textContent = "";
        }

        const amount = readNumberInput(amountInput);
        const dir = selectedDirection();
        const minNow = minForRoute(dir);
        if (!amount || amount < minNow) {
          if (errorEl) {
            errorEl.textContent = reasonText("below_minimum");
            errorEl.hidden = false;
          }
          return;
        }

        const { from, to } = routeParts(dir);
        const receive = computeReceive(dir, amount);
        const confirmMsg = tt(
          "exchange_confirm_prompt",
          "Exchange %(amount)s %(give)s for ~%(receive)s %(get)s?"
        )
          .replace("%(amount)s", formatNumber(amount))
          .replace("%(give)s", resourceLabels[from]())
          .replace("%(receive)s", formatNumber(receive))
          .replace("%(get)s", resourceLabels[to]());

        if (!window.confirm(confirmMsg)) return;

        if (submitBtn) submitBtn.disabled = true;
        try {
          const res = await GC.fetchGameAction("/api/exchange", {
            method: "POST",
            headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
            body: JSON.stringify({ direction: dir, from, to, amount }),
          });
          if (res?.ok) {
            setNumberInputValue(amountInput, minNow);
            scheduleUpdatePreview();
            applyActionState(res, "exchange_success");
            showNotify(tt("exchange_success", "Exchange completed."), "success");
          } else {
            applyActionState(res, "exchange_error");
            if (errorEl) {
              errorEl.textContent = reasonText(res?.reason);
              errorEl.hidden = false;
            }
          }
        } catch (_) {
          if (errorEl) {
            errorEl.textContent = reasonText("generic");
            errorEl.hidden = false;
          }
        } finally {
          updatePreview();
          updateExchangeMaxBtn();
        }
      });
    }

    panel._patchExchangeFromState = patchExchangeFromState;
    panel._computeExchangeMaxInput = computeExchangeMaxInput;
    if (!amountInput.value) amountInput.value = String(minForRoute(selectedDirection()));
    setDirection(selectedDirection());
  }

  function renderScrapyardRows(ships) {
    const tt = (key, fallback, vars) => t(key, fallback, vars);
    if (!Array.isArray(ships) || ships.length === 0) {
      return `<div class="trader-hub-scrap-empty" data-scrapyard-empty>
        <span class="trader-hub-scrap-empty-icon" aria-hidden="true">♻</span>
        <p class="trader-hub-scrap-empty-text hint">${tt("scrapyard_empty", "Keine recyclebaren Schiffe auf dieser Kolonie.")}</p>
      </div>`;
    }
    return ships.map((row) => {
      const key = String(row.ship_key || "");
      const amount = Number(row.amount || 0);
      const icon = String(row.icon || "");
      const shipName = shipDisplayName(key);
      const minM = Number(row.preview_refund_min?.metal || 0);
      const maxM = Number(row.preview_refund_max?.metal || 0);
      const minC = Number(row.preview_refund_min?.crystal || 0);
      const maxC = Number(row.preview_refund_max?.crystal || 0);
      const haveLabel = tt("scrapyard_have", "Available: %(count)s").replace("%(count)s", formatNumber(amount));
      const refundLabel = tt("scrapyard_refund_range", "Refund");
      const metalLabel = tt("resource_metal", "Ferronit");
      const crystalLabel = tt("resource_crystal", "Crytite");
      const recycleLabel = tt("scrapyard_recycle_btn", "Recycle");
      const amountLabel = tt("scrapyard_amount", "Amount");
      return `
        <article class="gc-scrapyard-row fleet-ship-row gc-trader-scrap-row" data-scrap-ship="${key}" data-scrap-max="${amount}">
          <div class="fleet-ship-row-main gc-trader-scrap-main">
            <div class="gc-trader-scrap-icon-wrap">
              <img src="${icon}" alt="" class="gc-scrapyard-ship-icon" width="40" height="40" loading="lazy">
            </div>
            <div class="gc-trader-scrap-body">
              <span class="gc-scrapyard-ship-name fleet-ship-name">${shipName}</span>
              <span class="gc-scrapyard-have fleet-ship-stock gc-mono">${haveLabel}</span>
              <span class="gc-trader-scrap-refund hint gc-mono">
                ${tt("scrapyard_refund_estimate", "Refund (approx.)")}:
                ${formatNumber(minM)}–${formatNumber(maxM)} ${metalLabel},
                ${formatNumber(minC)}–${formatNumber(maxC)} ${crystalLabel}
              </span>
            </div>
          </div>
          <div class="fleet-ship-row-controls gc-trader-scrap-actions">
            <input type="text" inputmode="numeric" class="gc-trader-input fleet-ship-input gc-scrapyard-qty gc-num-input" min="1" max="${amount}" value="1"
                   data-scrap-qty="${key}" aria-label="${amountLabel}">
            <button type="button" class="gc-btn gc-btn-secondary gc-trader-scrap-btn" data-scrap-recycle="${key}">
              ${recycleLabel.toUpperCase()}
            </button>
          </div>
        </article>`;
    }).join("");
  }

  function initScrapyardPanel() {
    const panel = document.getElementById("gc-scrapyard-panel");
    if (!panel || panel.dataset.disabled === "1") return;
    if (panel.dataset.scrapyardBound) return;
    panel.dataset.scrapyardBound = "1";
    bindFormattedNumberInputs(panel);

    const tt = (key, fallback) => t(key, fallback);
    const errorEl = panel.querySelector("[data-scrapyard-error]");
    const reasonText = (reason) => tt(`scrapyard_error_${reason}`, tt("scrapyard_error_generic", "Recycle failed."));

    panel.addEventListener("click", async (e) => {
      const btn = e.target.closest("[data-scrap-recycle]");
      if (!btn) return;
      const shipKey = btn.getAttribute("data-scrap-recycle");
      const row = btn.closest("[data-scrap-ship]");
      const qtyInp = row?.querySelector(`[data-scrap-qty="${shipKey}"]`);
      const amount = readNumberInput(qtyInp);
      const max = parseInt(row?.getAttribute("data-scrap-max") || "0", 10);
      if (!amount || amount > max) return;
      if (!window.confirm(tt("scrapyard_confirm", "Recycle ships for partial refund?"))) return;

      btn.disabled = true;
      if (errorEl) { errorEl.hidden = true; errorEl.textContent = ""; }
      try {
        const res = await GC.fetchGameAction("/api/trader/scrapyard", {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
          body: JSON.stringify({ ship_key: shipKey, amount }),
        });
        if (res?.ok) {
          applyActionState(res, "scrapyard_success");
          showNotify(tt("scrapyard_success", "Ships recycled."), "success");
        } else {
          applyActionState(res, "scrapyard_error");
          if (errorEl) {
            errorEl.textContent = reasonText(res?.reason);
            errorEl.hidden = false;
          }
        }
      } catch (_) {
        if (errorEl) {
          errorEl.textContent = reasonText("generic");
          errorEl.hidden = false;
        }
      } finally {
        btn.disabled = false;
      }
    });
  }

  function patchExchangePanel(exchange) {
    const panel = document.getElementById("gc-exchange-panel");
    if (panel && typeof panel._patchExchangeFromState === "function") {
      panel._patchExchangeFromState(exchange);
    }
  }

  function patchScrapyardPanel(scrapyard) {
    const panel = document.getElementById("gc-scrapyard-panel");
    if (!panel || !scrapyard || scrapyard.ready === false) return;
    const list = panel.querySelector("[data-scrapyard-list]");
    if (!list || !Array.isArray(scrapyard.ships)) return;
    list.innerHTML = renderScrapyardRows(scrapyard.ships);
    bindFormattedNumberInputs(list);
  }

  const COLLECTOR_SPEC_I18N = {
    xenobiologist: "collector_specialist_xenobiologist",
    scrapmaster: "collector_specialist_scrapmaster",
    energy_engineer: "collector_specialist_energy_engineer",
    hyper_technician: "collector_specialist_hypertech",
  };

  let collectorExchangeCache = null;
  let activeCollectorSpecialistKey = null;

  function readCollectorExchangeStateFromDom() {
    const el = document.getElementById("gc-collector-exchange-state");
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || "");
    } catch (_err) {
      return null;
    }
  }

  function writeCollectorExchangeStateToDom(collectorExchange) {
    const el = document.getElementById("gc-collector-exchange-state");
    if (el && collectorExchange) el.textContent = JSON.stringify(collectorExchange);
  }

  function collectorItemLabel(itemKey) {
    const key = String(itemKey || "");
    return t(`inventory_item_${key}_name`, t(`inv_${key}`, key));
  }

  function collectorOfferTitle(offer) {
    const offerKey = String(offer?.offer_key || "");
    return t(`collector_offer_${offerKey}_title`, t(String(offer?.name_key || ""), offerKey));
  }

  function collectorOfferDesc(offer) {
    const offerKey = String(offer?.offer_key || "");
    return t(`collector_offer_${offerKey}_desc`, "");
  }

  function collectorRewardPreviewLabel(rewardPreview) {
    const rows = Array.isArray(rewardPreview) ? rewardPreview : [];
    if (!rows.length) return "";
    return rows
      .map((rw) => {
        const amount = parseInt(rw.amount, 10) || 0;
        const rtype = String(rw.reward_type || "");
        const rkey = String(rw.reward_key || "");
        let label = "";
        if (rtype === "ship" || rtype === "ship_weighted") {
          label = shipDisplayName(rkey);
        } else {
          label = collectorItemLabel(rkey);
        }
        return amount > 1 ? `${label} ×${formatNumber(amount)}` : label;
      })
      .join(" · ");
  }

  function collectorOfferRewardLine(offer) {
    const offerKey = String(offer?.offer_key || "");
    const fallback = collectorRewardPreviewLabel(offer?.reward_preview);
    return t(`collector_offer_${offerKey}_reward`, fallback);
  }

  function sortCollectorOffers(offers) {
    return [...(offers || [])].sort((a, b) => {
      const aRedeem = !!a?.can_redeem;
      const bRedeem = !!b?.can_redeem;
      if (aRedeem !== bRedeem) return aRedeem ? -1 : 1;
      const aProgress = parseInt(a?.progress_pct, 10) || 0;
      const bProgress = parseInt(b?.progress_pct, 10) || 0;
      if (aProgress !== bProgress) return bProgress - aProgress;
      const aSort = parseInt(a?.sort, 10) || 0;
      const bSort = parseInt(b?.sort, 10) || 0;
      if (aSort !== bSort) return aSort - bSort;
      return String(a?.offer_key || "").localeCompare(String(b?.offer_key || ""));
    });
  }

  function renderCollectorOfferCard(offer) {
    const key = String(offer.offer_key || "");
    const owned = parseInt(offer.owned, 10) || 0;
    const required = parseInt(offer.input_amount, 10) || 0;
    const progress = parseInt(offer.progress_pct, 10) || 0;
    const canRedeem = !!offer.can_redeem;
    const rewardsReady = offer.rewards_ready !== false;
    const inputKey = String(offer.input_key || "");
    const title = collectorOfferTitle(offer);
    const rewardLine = collectorOfferRewardLine(offer);
    const desc = collectorOfferDesc(offer);
    const inputLabel = collectorItemLabel(inputKey);
    const cardClass = !rewardsReady
      ? " is-locked"
      : canRedeem
        ? " is-redeemable"
        : progress <= 0
          ? " is-dim"
          : "";
    const btnLabel = !rewardsReady
      ? t("collector_offer_locked_planned", "Coming soon")
      : canRedeem
        ? t("collector_redeem_button", "Redeem")
        : t("collector_missing_fragments", "Missing fragments");
    return `<article class="collector-offer-card${cardClass}" data-offer-key="${escapeHtml(key)}" data-collector-offer="${escapeHtml(key)}">
      <div class="collector-offer-main">
        <div class="collector-offer-headline">
          <h3 class="collector-offer-title">${escapeHtml(title)}</h3>
          <p class="collector-offer-reward-line hint">${escapeHtml(rewardLine)}</p>
        </div>
        <div class="collector-offer-metrics">
          <span class="collector-offer-owned gc-mono">
            <span data-collector-owned="${escapeHtml(key)}">${escapeHtml(formatNumber(owned))}</span>
            /
            <span data-collector-required="${escapeHtml(key)}">${escapeHtml(formatNumber(required))}</span>
          </span>
          <div class="gc-card-queue-bar collector-offer-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}" aria-label="${escapeHtml(title)}" data-collector-progress-bar="${escapeHtml(key)}">
            <div class="gc-card-queue-bar-fill gc-progress-smooth" style="width: ${progress}%;" data-collector-progress-fill="${escapeHtml(key)}"></div>
          </div>
          <button type="button" class="gc-btn gc-btn-primary gc-btn-sm collector-redeem-btn" data-collector-redeem="${escapeHtml(key)}"${canRedeem && rewardsReady ? "" : " disabled"}>${escapeHtml(btnLabel)}</button>
        </div>
      </div>
      <details class="collector-offer-details">
        <summary class="collector-offer-details-toggle">${escapeHtml(t("collector_offer_details", "Details"))}</summary>
        <p class="collector-offer-desc hint">${escapeHtml(desc)}</p>
        <p class="collector-offer-input hint">${escapeHtml(inputLabel)}</p>
      </details>
    </article>`;
  }

  function renderCollectorOffersGrid(collectorExchange, specialistKey) {
    const specialists = Array.isArray(collectorExchange?.specialists) ? collectorExchange.specialists : [];
    const spec = specialists.find((row) => String(row?.specialist_key || "") === String(specialistKey || ""));
    const offers = sortCollectorOffers(spec?.offers || []);
    return offers.map((offer) => renderCollectorOfferCard(offer)).join("");
  }

  function activateCollectorSpecialistTab(panel, specialistKey) {
    if (!panel || !specialistKey) return;
    activeCollectorSpecialistKey = specialistKey;
    panel.dataset.collectorActiveSpecialist = specialistKey;
    const tabs = panel.querySelectorAll("[data-collector-specialist-tab]");
    tabs.forEach((tab) => {
      const active = tab.getAttribute("data-collector-specialist-tab") === specialistKey;
      tab.classList.toggle("is-active", active);
      tab.setAttribute("aria-selected", active ? "true" : "false");
    });
    const grid = panel.querySelector("[data-collector-offers-grid]");
    if (grid && collectorExchangeCache) {
      grid.innerHTML = renderCollectorOffersGrid(collectorExchangeCache, specialistKey);
    }
  }

  function patchCollectorExchangePanel(collectorExchange) {
    const panel = document.getElementById("gc-collector-exchange-panel");
    if (!panel || !collectorExchange) return;
    panel.dataset.collectorReady = collectorExchange.ready ? "1" : "0";
    if (!collectorExchange.ready) return;

    collectorExchangeCache = collectorExchange;
    writeCollectorExchangeStateToDom(collectorExchange);

    const specialists = Array.isArray(collectorExchange.specialists) ? collectorExchange.specialists : [];
    const fallbackKey = specialists[0]?.specialist_key || "";
    const activeKey =
      activeCollectorSpecialistKey ||
      panel.dataset.collectorActiveSpecialist ||
      panel.querySelector("[data-collector-specialist-tab].is-active")?.getAttribute("data-collector-specialist-tab") ||
      fallbackKey;
    activateCollectorSpecialistTab(panel, activeKey || fallbackKey);
  }

  function initCollectorExchangePanel() {
    const panel = document.getElementById("gc-collector-exchange-panel");
    if (!panel || panel.dataset.collectorReady !== "1") return;
    if (panel.dataset.collectorBound === "1") return;
    panel.dataset.collectorBound = "1";

    collectorExchangeCache = readCollectorExchangeStateFromDom();
    activeCollectorSpecialistKey =
      panel.dataset.collectorActiveSpecialist ||
      panel.querySelector("[data-collector-specialist-tab].is-active")?.getAttribute("data-collector-specialist-tab") ||
      collectorExchangeCache?.specialists?.[0]?.specialist_key ||
      null;

    const tt = (key, fallback) => t(key, fallback);
    const errorEl = panel.querySelector("[data-collector-error]");
    const reasonText = (reason) =>
      tt(`collector_error_${reason}`, tt("collector_error_generic", "Exchange failed."));

    panel.addEventListener("click", (e) => {
      const tab = e.target.closest("[data-collector-specialist-tab]");
      if (tab) {
        activateCollectorSpecialistTab(panel, tab.getAttribute("data-collector-specialist-tab") || "");
        return;
      }
      const redeemBtn = e.target.closest("[data-collector-redeem]");
      if (!redeemBtn || redeemBtn.disabled) return;
      e.preventDefault();
      const offerKey = redeemBtn.getAttribute("data-collector-redeem") || "";
      if (!offerKey) return;

      redeemBtn.disabled = true;
      if (errorEl) {
        errorEl.hidden = true;
        errorEl.textContent = "";
      }

      GC.fetchGameAction("/api/collector-exchange/redeem", {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
        body: JSON.stringify({
          offer_key: offerKey,
          request_id: `collector-${offerKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        }),
      })
        .then((res) => {
          if (res?.ok) {
            applyActionState(res, "collector_redeem");
            showNotify(tt("collector_redeem_success", "Collectibles exchanged."), "success");
          } else {
            applyActionState(res, "collector_redeem_error");
            if (errorEl) {
              errorEl.textContent = reasonText(res?.reason);
              errorEl.hidden = false;
            }
          }
        })
        .catch(() => {
          if (errorEl) {
            errorEl.textContent = reasonText("generic");
            errorEl.hidden = false;
          }
        })
        .finally(() => {
          redeemBtn.disabled = false;
        });
    });

    GC.registerCleanup(() => {
      delete panel.dataset.collectorBound;
      collectorExchangeCache = null;
      activeCollectorSpecialistKey = null;
    });
  }

  GC.renderCollectorExchangePanel = patchCollectorExchangePanel;

  function initResearch() {
    initBuildingTechnicalData();
    GC.startProgressTicker();
  }

  function syncPlanetEvolutionResearchTicker() {
    const page = document.querySelector(".planet-evolution-page");
    if (!page) return;
    const hasCardQueues = page.querySelector(".gc-card-queue-block[data-gc-card-queue='1']");
    if (!hasCardQueues) return;
    GC.startProgressTicker();
  }

  function planetSwitchReasonText(reason) {
    if (!reason) return t("pe_error_generic", "Aktion fehlgeschlagen.");
    const pe = t(`pe_reason_${reason}`, "");
    if (pe && pe !== `pe_reason_${reason}`) return pe;
    return String(reason);
  }

  function syncHudSelectOpenState() {
    const anyOpen = !!document.querySelector(".gc-hud-select.is-open");
    document.body.classList.toggle("gc-has-open-popover", anyOpen);
  }

  function ensureHudSelectWrapId(wrap) {
    if (!wrap.dataset.gcHudSelectId) {
      wrap.dataset.gcHudSelectId = `gc-hud-select-${Math.random().toString(36).slice(2, 9)}`;
    }
    return wrap.dataset.gcHudSelectId;
  }

  function positionHudSelectMenu(wrap, menu) {
    if (!wrap || !menu) return;
    const trigger = wrap.querySelector(".gc-hud-select-trigger");
    if (!trigger) return;

    const margin = 4;
    const viewportPad = 8;
    const rect = trigger.getBoundingClientRect();
    const width = Math.max(rect.width, 120);
    const maxLeft = Math.max(viewportPad, window.innerWidth - viewportPad - width);

    menu.style.width = `${width}px`;
    menu.style.left = `${Math.min(Math.max(viewportPad, rect.left), maxLeft)}px`;
    menu.style.right = "auto";
    menu.style.maxHeight = `${Math.min(240, window.innerHeight - viewportPad * 2)}px`;

    const wasHidden = menu.hidden;
    menu.hidden = false;
    const menuHeight = menu.getBoundingClientRect().height;
    let top = rect.bottom + margin;
    if (top + menuHeight > window.innerHeight - viewportPad) {
      top = Math.max(viewportPad, rect.top - menuHeight - margin);
    }
    menu.style.top = `${top}px`;
    menu.hidden = wasHidden;
  }

  function floatHudSelectMenu(wrap, menu) {
    if (!wrap || !menu) return;
    ensureHudSelectWrapId(wrap);
    menu.classList.add("gc-popover-layer");
    menu.dataset.gcHudSelectWrapId = wrap.dataset.gcHudSelectId;
    if (menu.parentNode !== document.body) {
      document.body.appendChild(menu);
    }
  }

  function hudSelectParts(wrap) {
    if (!wrap) return null;
    const cached = wrap._gcHudSelect;
    if (cached && cached.menu) return cached;
    const select = wrap.querySelector("select.gc-hud-select-native");
    if (!select || !select._gcHudSelect) return null;
    wrap._gcHudSelect = select._gcHudSelect;
    return select._gcHudSelect;
  }

  function reparentHudSelectMenu(wrap, menu) {
    if (!wrap || !menu) return;
    if (menu.parentNode !== wrap) wrap.appendChild(menu);
    menu.classList.remove("gc-popover-layer");
    menu.style.pointerEvents = "";
    delete menu.dataset.gcHudSelectWrapId;
  }

  function closeHudSelectWrap(wrap) {
    if (!wrap) return;
    const hud = hudSelectParts(wrap) || {};
    const menu = hud.menu;
    const trigger = hud.trigger;
    if (menu) {
      menu.hidden = true;
      menu.style.pointerEvents = "none";
      reparentHudSelectMenu(wrap, menu);
    }
    wrap.classList.remove("is-open");
    if (trigger) trigger.setAttribute("aria-expanded", "false");
  }

  function openHudSelectWrap(wrap) {
    if (!wrap) return;
    const hud = hudSelectParts(wrap);
    if (!hud) return;
    const menu = hud.menu;
    const trigger = hud.trigger;
    if (!menu || !trigger || selectDisabled(wrap)) return;

    floatHudSelectMenu(wrap, menu);
    positionHudSelectMenu(wrap, menu);
    menu.hidden = false;
    menu.style.pointerEvents = "auto";
    wrap.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    syncHudSelectOpenState();
  }

  function selectDisabled(wrap) {
    const select = wrap && wrap.querySelector("select.gc-hud-select-native");
    const trigger = wrap && wrap.querySelector(".gc-hud-select-trigger");
    return !!(select && select.disabled) || !!(trigger && trigger.disabled);
  }

  function repositionOpenHudSelects() {
    document.querySelectorAll(".gc-hud-select.is-open").forEach((wrap) => {
      const hud = hudSelectParts(wrap);
      const menu = hud && hud.menu;
      if (menu && !menu.hidden) positionHudSelectMenu(wrap, menu);
    });
  }

  function closeAllHudSelects(except) {
    document.querySelectorAll(".gc-hud-select.is-open").forEach((wrap) => {
      if (except && wrap === except) return;
      closeHudSelectWrap(wrap);
    });
    syncHudSelectOpenState();
  }

  function teardownHudSelectPortals() {
    closeAllHudSelects();
    document.querySelectorAll(".gc-hud-select").forEach((wrap) => {
      const hud = hudSelectParts(wrap);
      const menu = hud && hud.menu;
      if (!menu) return;
      menu.hidden = true;
      menu.style.pointerEvents = "none";
      reparentHudSelectMenu(wrap, menu);
      wrap.classList.remove("is-open");
      const trigger = wrap.querySelector(".gc-hud-select-trigger");
      if (trigger) trigger.setAttribute("aria-expanded", "false");
    });
    document.querySelectorAll("body > .gc-hud-select-menu.gc-popover-layer").forEach((menu) => {
      menu.hidden = true;
      menu.style.pointerEvents = "none";
      const wrapId = menu.dataset.gcHudSelectWrapId;
      let reparented = false;
      if (wrapId) {
        const wrap = document.querySelector(`[data-gc-hud-select-id="${wrapId}"]`);
        if (wrap) {
          reparentHudSelectMenu(wrap, menu);
          reparented = true;
        }
      }
      if (!reparented) menu.remove();
    });
    document.body.classList.remove("gc-has-open-popover");
  }

  function releaseShellNavigationBlockers(reason) {
    closeAllHudSelects();
    teardownHudSelectPortals();
    document.querySelectorAll("body > .gc-hud-select-menu.gc-popover-layer").forEach((menu) => {
      menu.hidden = true;
      menu.style.pointerEvents = "none";
      menu.remove();
    });
    document.querySelectorAll(".gc-hud-select.is-open").forEach((wrap) => {
      wrap.classList.remove("is-open");
      const trigger = wrap.querySelector(".gc-hud-select-trigger");
      if (trigger) trigger.setAttribute("aria-expanded", "false");
    });
    document.body.classList.remove("gc-has-open-popover");
    document.querySelectorAll("a[href][data-pjax-busy='1']").forEach((link) => {
      link.dataset.pjaxBusy = "0";
    });
    document.querySelectorAll(".gc-nav-section.gc-nav-section--animating").forEach((section) => {
      section.classList.remove("gc-nav-section--animating");
      if (section._gcNavAnimTimer) {
        clearTimeout(section._gcNavAnimTimer);
        section._gcNavAnimTimer = null;
      }
    });
    document.querySelectorAll("[data-gc-planet-registry]").forEach((root) => {
      root.classList.remove("is-busy");
      root.querySelectorAll(".gc-planet-registry-card").forEach((btn) => {
        btn.disabled = false;
      });
    });
    if (reason) console.debug("[GC] releaseShellNavigationBlockers", reason);
  }

  function syncHudSelectLabelsInRoot(root) {
    const scope = root && root.querySelectorAll ? root : document;
    scope.querySelectorAll("select[data-gc-hud-select]").forEach((sel) => {
      if (sel.dataset.gcHudSelectEnhanced === "1" && typeof syncHudSelect === "function") {
        syncHudSelect(sel);
      }
    });
  }

  function syncHudSelect(select) {
    if (!select || !select._gcHudSelect) return;
    const { menu, valueEl, trigger } = select._gcHudSelect;
    const opt = select.options[select.selectedIndex];
    if (valueEl) valueEl.textContent = opt ? opt.textContent.trim() : "";
    if (trigger) trigger.disabled = !!select.disabled;
    if (menu) {
      menu.querySelectorAll(".gc-hud-select-item").forEach((item) => {
        const active = item.dataset.value === select.value;
        item.classList.toggle("is-active", active);
        item.setAttribute("aria-selected", active ? "true" : "false");
      });
    }
  }

  function rebuildHudSelect(select) {
    if (!select || !select._gcHudSelect) return;
    const { menu } = select._gcHudSelect;
    if (!menu) return;
    menu.innerHTML = "";
    Array.from(select.options).forEach((opt) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "gc-hud-select-item";
      btn.dataset.value = opt.value;
      btn.setAttribute("role", "option");
      btn.textContent = opt.textContent.trim();
      if (opt.disabled) btn.disabled = true;
      menu.appendChild(btn);
    });
    syncHudSelect(select);
  }

  function enhanceHudSelect(select) {
    if (!select || select.dataset.gcHudSelectEnhanced === "1") return;
    select.dataset.gcHudSelectEnhanced = "1";
    select.classList.add("gc-hud-select-native");

    const wrap = document.createElement("div");
    wrap.className = "gc-hud-select";
    select.parentNode.insertBefore(wrap, select);
    wrap.appendChild(select);

    const trigger = document.createElement("button");
    trigger.type = "button";
    trigger.className = "gc-hud-panel gc-hud-select-trigger";
    trigger.setAttribute("aria-haspopup", "listbox");
    trigger.setAttribute("aria-expanded", "false");
    if (select.id) trigger.setAttribute("aria-controls", `${select.id}-hud-menu`);

    const valueEl = document.createElement("span");
    valueEl.className = "gc-hud-select-value";

    const chevron = document.createElement("span");
    chevron.className = "gc-hud-select-chevron";
    chevron.setAttribute("aria-hidden", "true");
    chevron.textContent = "▾";

    trigger.appendChild(valueEl);
    trigger.appendChild(chevron);

    const menu = document.createElement("div");
    menu.className = "gc-hud-select-menu";
    menu.hidden = true;
    menu.setAttribute("role", "listbox");
    if (select.id) menu.id = `${select.id}-hud-menu`;

    wrap.insertBefore(trigger, select);
    wrap.appendChild(menu);

    select._gcHudSelect = { wrap, trigger, menu, valueEl };
    wrap._gcHudSelect = select._gcHudSelect;

    rebuildHudSelect(select);

    trigger.addEventListener("click", (e) => {
      e.stopPropagation();
      if (select.disabled || trigger.disabled) return;
      const isOpen = wrap.classList.contains("is-open");
      closeAllHudSelects();
      if (!isOpen) openHudSelectWrap(wrap);
    });

    menu.addEventListener("click", (e) => {
      const item = e.target.closest(".gc-hud-select-item");
      if (!item || item.disabled) return;
      const next = item.dataset.value ?? "";
      if (select.value !== next) {
        select.value = next;
        select.dispatchEvent(new Event("change", { bubbles: true }));
      } else {
        syncHudSelect(select);
      }
      closeHudSelectWrap(wrap);
      syncHudSelectOpenState();
    });

    select.addEventListener("change", () => syncHudSelect(select));
  }

  function initHudSelects(root) {
    if (!GC._hudSelectBound) {
      GC._hudSelectBound = true;
      document.addEventListener("click", (e) => {
        if (e.target.closest(".gc-hud-select")) return;
        if (e.target.closest(".gc-hud-select-menu")) return;
        closeAllHudSelects();
      });
      document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeAllHudSelects();
      });
      window.addEventListener("resize", repositionOpenHudSelects);
      window.addEventListener("scroll", repositionOpenHudSelects, true);
      GC.registerCleanup(() => closeAllHudSelects());
    }
    const scope = root && root.querySelectorAll ? root : document;
    scope.querySelectorAll("select[data-gc-hud-select]").forEach(enhanceHudSelect);
  }

  GC.initHudSelects = initHudSelects;
  GC.syncHudSelect = syncHudSelect;
  GC.rebuildHudSelect = rebuildHudSelect;
  GC.closeAllHudSelects = closeAllHudSelects;
  GC.teardownHudSelectPortals = teardownHudSelectPortals;
  GC.releaseShellNavigationBlockers = releaseShellNavigationBlockers;
  GC.syncHudSelectLabelsInRoot = syncHudSelectLabelsInRoot;

  function empireIdentityLabelKey(planet) {
    if (!planet) return "";
    return (
      planet.identity_title_key ||
      planet.empire_subtitle_key ||
      planet.empire_role_label_key ||
      planet.empire_identity_key ||
      ""
    );
  }

  function planetRegistryRoots() {
    return Array.from(document.querySelectorAll("[data-gc-planet-registry]"));
  }

  function rebuildPlanetRegistry(planets) {
    const roots = planetRegistryRoots();
    if (!roots.length || !Array.isArray(planets) || !planets.length) return;

    const active = planets.find((p) => p.is_active) || planets[0];
    const activeId = String(active.planet_id || "");

    roots.forEach((root) => {
      root.dataset.activePlanetId = activeId;
      const list = root.querySelector("[data-gc-planet-registry-list]");
      if (!list) return;
      list.replaceChildren();

      planets.forEach((p) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "gc-planet-registry-card" + (p.is_active ? " is-active" : "");
        btn.setAttribute("role", "listitem");
        btn.setAttribute("aria-current", p.is_active ? "true" : "false");
        btn.dataset.planetId = String(p.planet_id || "");
        btn.dataset.planetName = p.name || "";
        btn.dataset.planetCoord = p.coordinates_formatted || "";
        btn.dataset.planetClassKey = p.planet_class_label_key || "";
        btn.dataset.planetClass = p.planet_class || "";
        btn.dataset.planetHomeworld = p.is_homeworld ? "1" : "0";
        btn.dataset.planetRoleKey = p.empire_role_key || "";
        btn.dataset.planetRoleLabelKey = p.empire_role_label_key || "";
        btn.dataset.planetRoleIcon = p.empire_role_icon || "";
        btn.dataset.planetIdentityKey = empireIdentityLabelKey(p);
        const herocardUrl = String(p.herocard_url || "").trim();
        const herocardWebp = String(p.herocard_webp_url || "").trim();
        btn.dataset.planetHerocard = herocardUrl;
        btn.dataset.planetHerocardWebp = herocardWebp;

        const main = document.createElement("span");
        main.className = "gc-planet-registry-card-main";
        if (herocardUrl) {
          const thumb = document.createElement("span");
          thumb.className = "gc-planet-registry-card-thumb has-planet-image";
          thumb.setAttribute("aria-hidden", "true");
          thumb.style.setProperty("--gr-planet-image", `url('${herocardUrl}')`);
          if (herocardWebp) {
            thumb.style.setProperty("--gr-planet-image-webp", `url('${herocardWebp}')`);
          }
          main.appendChild(thumb);
        }
        const copy = document.createElement("span");
        copy.className = "gc-planet-registry-card-copy";
        const nameSpan = document.createElement("span");
        nameSpan.className = "gc-planet-registry-card-name";
        nameSpan.textContent = p.name || "";
        copy.appendChild(nameSpan);

        const identityKey = empireIdentityLabelKey(p);
        if (identityKey) {
          const roleSpan = document.createElement("span");
          roleSpan.className = "gc-planet-registry-card-role";
          roleSpan.textContent = t(identityKey, identityKey);
          copy.appendChild(roleSpan);
        }
        const coord = p.coordinates_formatted || "";
        const indicators = Array.isArray(p.status_indicators) ? p.status_indicators : [];
        if (coord || indicators.length) {
          const meta = document.createElement("span");
          meta.className = "gc-planet-registry-card-meta";
          if (coord) {
            const coordSpan = document.createElement("span");
            coordSpan.className = "gc-planet-registry-card-coord gc-mono";
            coordSpan.innerHTML = GC.coordLinkHtml(coord, { label: coord });
            meta.appendChild(coordSpan);
          }
          const statusSpan = document.createElement("span");
          statusSpan.className = "gc-planet-registry-card-status";
          indicators.forEach((ind) => {
            if (!ind || !ind.key) return;
            const icon = document.createElement("span");
            icon.className = "gc-planet-registry-status-icon";
            icon.dataset.statusKey = String(ind.key || "");
            const labelKey = String(ind.label_key || "");
            const label = labelKey ? t(labelKey, labelKey) : "";
            if (label) {
              icon.setAttribute("title", label);
              icon.setAttribute("aria-label", label);
            }
            icon.textContent = String(ind.icon || "");
            statusSpan.appendChild(icon);
          });
          meta.appendChild(statusSpan);
          copy.appendChild(meta);
        }
        main.appendChild(copy);
        btn.appendChild(main);

        list.appendChild(btn);
      });
    });
  }

  function updatePlanetRegistryFromPlanets(planets) {
    rebuildPlanetRegistry(planets);
  }

  function buildSidebarNavFromRole(empireRoleKey, isHomeworld) {
    const cfg = window.GC_SIDEBAR_NAV_CONFIG || {};
    const allModules = Array.isArray(cfg.all_modules) ? cfg.all_modules : [];
    const homeworldRoles = new Set(Array.isArray(cfg.homeworld_roles) ? cfg.homeworld_roles : ["homeworld"]);
    const role = String(empireRoleKey || "general").trim().toLowerCase();
    if (isHomeworld || homeworldRoles.has(role)) {
      const modules = {};
      allModules.forEach((key) => { modules[key] = "prominent"; });
      return {
        empire_role_key: "homeworld",
        is_homeworld: true,
        full_nav: true,
        show_more_section: false,
        modules,
      };
    }
    const prominent = cfg.prominent_by_role && cfg.prominent_by_role[role];
    if (!Array.isArray(prominent) || !prominent.length) {
      const modules = {};
      allModules.forEach((key) => { modules[key] = "prominent"; });
      return {
        empire_role_key: role,
        is_homeworld: false,
        full_nav: true,
        show_more_section: false,
        modules,
      };
    }
    const prominentSet = new Set(prominent);
    const alwaysProminent = new Set(
      Array.isArray(cfg.always_prominent_modules)
        ? cfg.always_prominent_modules
        : ["trading", "empire", "ranking", "records", "referrals"]
    );
    const modules = {};
    allModules.forEach((key) => {
      modules[key] = alwaysProminent.has(key) || prominentSet.has(key) ? "prominent" : "secondary";
    });
    return {
      empire_role_key: role,
      is_homeworld: false,
      full_nav: false,
      show_more_section: true,
      modules,
    };
  }

  function resolveSidebarNavFromState(data) {
    if (!data || typeof data !== "object") return null;
    if (data.active_planet && data.active_planet.sidebar_nav) {
      return data.active_planet.sidebar_nav;
    }
    const activeId = Number(data.active_planet_id || data.active_planet?.planet_id || 0);
    if (!activeId) return null;
    let roleKey = "general";
    let isHomeworld = false;
    const ap = data.active_planet;
    if (ap && Number(ap.planet_id) === activeId) {
      roleKey = ap.empire_role_key || roleKey;
      isHomeworld = !!ap.is_homeworld;
    } else if (Array.isArray(data.planets)) {
      const row = data.planets.find((p) => Number(p.planet_id) === activeId);
      if (row) {
        roleKey = row.empire_role_key || roleKey;
        isHomeworld = !!row.is_homeworld;
      }
    }
    return buildSidebarNavFromRole(roleKey, isHomeworld);
  }

  const MOBILE_BOTTOM_PRIORITY = (() => {
    const cfg = window.GC_SIDEBAR_NAV_CONFIG || {};
    return Array.isArray(cfg.mobile_bottom_priority) && cfg.mobile_bottom_priority.length
      ? cfg.mobile_bottom_priority
      : [
        "overview",
        "buildings",
        "research",
        "defense",
        "logistics",
        "fleet",
        "galaxy",
        "planet_evolution",
        "trading",
        "ranking",
      ];
  })();
  const MOBILE_BOTTOM_MAX = Number((window.GC_SIDEBAR_NAV_CONFIG || {}).mobile_bottom_max) || 4;

  function navTierForModule(nav, module) {
    const fullNav = !!nav.full_nav;
    const modules = nav.modules && typeof nav.modules === "object" ? nav.modules : {};
    return fullNav ? "prominent" : (modules[module] || "prominent");
  }

  function applyRoleNavTiers(root, nav) {
    if (!root || !nav) return;
    const fullNav = !!nav.full_nav;
    const modules = nav.modules && typeof nav.modules === "object" ? nav.modules : {};
    root.dataset.navRole = String(nav.empire_role_key || "general");
    root.dataset.navFull = fullNav ? "1" : "0";

    root.querySelectorAll("[data-nav-module]").forEach((el) => {
      const key = String(el.dataset.navModule || "");
      const tier = fullNav ? "prominent" : (modules[key] || "prominent");
      el.dataset.navTier = tier;
      el.classList.remove("gc-nav-module--prominent", "gc-nav-module--secondary");
      el.classList.add(`gc-nav-module--${tier}`);
    });

    root.querySelectorAll("[data-nav-group]").forEach((group) => {
      const keys = String(group.dataset.navGroupModules || "")
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean);
      const tiers = keys.map((key) => (fullNav ? "prominent" : (modules[key] || "prominent")));
      const anyProminent = tiers.some((tier) => tier === "prominent");
      const allSecondary = tiers.length > 0 && tiers.every((tier) => tier === "secondary");
      group.classList.toggle("gc-nav-group--prominent", anyProminent);
      group.classList.toggle("gc-nav-group--secondary", allSecondary);
    });
  }

  function moduleDisplaySection(nav, module) {
    const cfg = window.GC_SIDEBAR_NAV_CONFIG || {};
    const standalone = new Set(
      Array.isArray(cfg.standalone_modules) ? cfg.standalone_modules : ["messages"]
    );
    if (standalone.has(module)) return module;
    const primaryMap = cfg.module_primary_section || {};
    if (module === "support" || module === "options") return null;
    const utility = new Set(
      Array.isArray(cfg.utility_modules)
        ? cfg.utility_modules
        : (cfg.administration_modules || [])
    );
    if (utility.has(module)) return "administration";
    return primaryMap[module] || null;
  }

  function shouldShowSidebarNavLink(nav, el) {
    const module = String(el.dataset.navModule || "");
    if (!module) return true;
    const sectionKey = String(el.closest("[data-nav-section]")?.dataset.navSection || "");
    if (sectionKey === "messages") return module === "messages";
    if (sectionKey === "community") {
      if (module === "vote_center") return true;
      const display = moduleDisplaySection(nav, module);
      return display === "administration" && COMMUNITY_ADMIN_MODULES.has(module);
    }
    const display = moduleDisplaySection(nav, module);
    if (!display) return false;
    return display === sectionKey;
  }

  function navLinkShows(nav, module, placement) {
    const display = moduleDisplaySection(nav, module);
    if (!display) return false;
    if (placement === "administration") return display === "administration";
    return display === (window.GC_SIDEBAR_NAV_CONFIG?.module_primary_section || {})[module];
  }

  const NAV_SECTION_STORAGE_KEY = "gc_sidebar_state";
  const NAV_SECTION_STORAGE_KEY_RIGHT = "gc_sidebar_right_state";
  const LEFT_NAV_SECTIONS = new Set(["command", "infrastructure", "military"]);
  const RIGHT_NAV_SECTIONS = new Set(["messages", "economy", "community"]);
  let _leftmenuRouteCtxCache = null;
  const INFRA_NAV_SECTION_ANIM_MS = 220;
  const COMMUNITY_ADMIN_MODULES = new Set([
    "ranking", "hall_of_fame", "vote_center", "referrals", "alliance", "records", "world_boss",
  ]);

  function navStorageKeyForSidebar(sidebar) {
    if (!sidebar) return NAV_SECTION_STORAGE_KEY;
    const placement = sidebar.dataset.navPlacement || "";
    if (
      sidebar.id === "gc-sidebar-nav-right"
      || sidebar.id === "gc-mnav-sidebar-nav-right"
      || placement === "right"
      || placement === "mobile-drawer-right"
    ) {
      return NAV_SECTION_STORAGE_KEY_RIGHT;
    }
    return NAV_SECTION_STORAGE_KEY;
  }

  function readNavSectionState(storageKey) {
    const key = storageKey || NAV_SECTION_STORAGE_KEY;
    try {
      return JSON.parse(localStorage.getItem(key) || "{}");
    } catch (_) {
      return {};
    }
  }

  function writeNavSectionState(state, storageKey) {
    const key = storageKey || NAV_SECTION_STORAGE_KEY;
    try {
      localStorage.setItem(key, JSON.stringify(state));
    } catch (_) {}
  }

  function sidebarAllowsSection(sidebar, sectionKey) {
    if (!sidebar) return true;
    const placement = sidebar.dataset.navPlacement || "";
    if (
      sidebar.id === "gc-sidebar-nav-right"
      || sidebar.id === "gc-mnav-sidebar-nav-right"
      || placement === "right"
      || placement === "mobile-drawer-right"
    ) {
      return RIGHT_NAV_SECTIONS.has(sectionKey);
    }
    return LEFT_NAV_SECTIONS.has(sectionKey);
  }

  function pathFromMenuUrl(url) {
    try {
      const u = new URL(url, window.location.origin);
      return {
        path: u.pathname.replace(/\/$/, "") || "/",
        search: u.searchParams,
      };
    } catch (_) {
      return { path: "/", search: new URLSearchParams() };
    }
  }

  function linkPathMatchesRoute(link, path) {
    const href = link.getAttribute("href");
    if (!href || href.startsWith("#")) return false;
    try {
      const linkPath = new URL(href, window.location.origin).pathname.replace(/\/$/, "") || "/";
      return linkPath === path;
    } catch (_) {
      return false;
    }
  }

  function applyLeftmenuPathRouteHints(path, sections, groups) {
    if (path.endsWith("/messages")) sections.add("messages");
    if (
      path.endsWith("/overview")
      || path.endsWith("/galaxy")
      || path.endsWith("/planet-evolution")
    ) {
      sections.add("command");
    }
    if (path.endsWith("/research")) {
      sections.add("infrastructure");
    }
    if (
      path.endsWith("/shipyard")
      || path.endsWith("/defense")
      || path.endsWith("/fleet")
      || path.endsWith("/logistics")
    ) {
      sections.add("military");
    }
    if (
      path.endsWith("/trader-hub")
      || path.endsWith("/inventory")
      || path.endsWith("/auction-house")
      || path.endsWith("/galactic-politics")
      || path.endsWith("/skilltree")
    ) {
      sections.add("economy");
    }
    if (path.endsWith("/login-rewards") || path.endsWith("/premium") || path.endsWith("/shop") || path.endsWith("/shop/return")) {
      sections.add("command");
    }
    if (path.endsWith("/empire") || path.endsWith("/techtree")) sections.add("economy");
    if (path.endsWith("/vote-center")) {
      sections.add("community");
    }
    if (
      path === "/alliance"
      || /^\/alliance\/\d+$/.test(path)
      || path.endsWith("/ranking")
      || path.endsWith("/hall-of-fame")
      || path.endsWith("/world-boss")
      || path.endsWith("/chronicles")
      || path.endsWith("/records")
      || path.endsWith("/referrals")
      || path.endsWith("/imperial-directives")
      || path.endsWith("/story")
    ) {
      sections.add("community");
    }
  }

  function resolveLeftmenuRouteContext(url) {
    const targetUrl = String(url || window.location.href);
    if (_leftmenuRouteCtxCache && _leftmenuRouteCtxCache.url === targetUrl) {
      return _leftmenuRouteCtxCache.ctx;
    }
    const { path, search } = pathFromMenuUrl(targetUrl);
    const sections = new Set();
    const groups = new Set();
    let buildingTab = null;

    if (path.endsWith("/buildings")) {
      sections.add("infrastructure");
      groups.add("buildings");
      buildingTab = search.get("tab") || "resources";
      const ctx = { path, sections, groups, buildingTab };
      _leftmenuRouteCtxCache = { url: targetUrl, ctx };
      return ctx;
    }

    applyLeftmenuPathRouteHints(path, sections, groups);

    const sidebars = [
      document.getElementById("gc-sidebar-nav"),
      document.getElementById("gc-sidebar-nav-right"),
    ].filter(Boolean);

    sidebars.forEach((sidebar) => {
      sidebar.querySelectorAll("[data-nav-section]").forEach((section) => {
        if (section.hidden) return;
        const sectionKey = String(section.dataset.navSection || "");
        if (!sectionKey || !sidebarAllowsSection(sidebar, sectionKey)) return;

        section.querySelectorAll("a.gc-nav-sub-link[href], a.gc-nav-link[href]").forEach((link) => {
          if (link.id === "gc-nav-trading-parent") return;
          if (!linkPathMatchesRoute(link, path)) return;
          sections.add(sectionKey);
          const group = link.closest("[data-nav-group-key]");
          if (group) groups.add(String(group.dataset.navGroupKey || ""));
        });

        section.querySelectorAll("[data-trading-nav][href]").forEach((link) => {
          if (!linkPathMatchesRoute(link, path)) return;
          sections.add(sectionKey);
        });
      });
    });

    applyLeftmenuPathRouteHints(path, sections, groups);
    const ctx = { path, sections, groups, buildingTab };
    _leftmenuRouteCtxCache = { url: targetUrl, ctx };
    return ctx;
  }

  function invalidateLeftmenuRouteContextCache() {
    _leftmenuRouteCtxCache = null;
  }

  function resolveNavSectionExpanded(section, state, routeCtx) {
    const key = String(section.dataset.navSection || "");
    if (key && routeCtx?.sections?.has(key)) return true;
    if (key && Object.prototype.hasOwnProperty.call(state, key)) {
      return !!state[key];
    }
    return section.classList.contains("is-expanded");
  }

  function resolveNavGroupExpanded(group, state, routeCtx) {
    const key = String(group.dataset.navGroupKey || "");
    if (key && routeCtx?.groups?.has(key)) return true;
    if (key && Object.prototype.hasOwnProperty.call(state, key)) {
      return !!state[key];
    }
    if (key === "buildings") {
      return typeof GC.detectPage === "function" && GC.detectPage() === "buildings";
    }
    return group.classList.contains("is-expanded");
  }

  function navGroupExpandedUiMatches(group, expanded, key) {
    if (group.classList.contains("is-expanded") !== expanded) return false;
    if (key === "trading") {
      const sub = document.getElementById("gc-nav-trading-sub");
      if (!sub) return true;
      const subExpanded = !sub.hidden && !sub.classList.contains("gc-nav-sub--collapsed");
      return subExpanded === expanded;
    }
    return true;
  }

  function setNavSectionExpanded(section, expanded, persist) {
    if (!section) return;
    const toggle = section.querySelector(".gc-nav-section-toggle");
    const body = section.querySelector(".gc-nav-section-body");
    if (!toggle || !body) return;
    if (section.classList.contains("is-expanded") === expanded) return;
    const sidebar = section.closest(".gc-sidebar");
    const storageKey = navStorageKeyForSidebar(sidebar);
    const sectionKey = String(section.dataset.navSection || "");
    const isInfrastructure = sectionKey === "infrastructure";
    if (isInfrastructure) {
      section.classList.add("gc-nav-section--animating");
      if (section._gcNavAnimTimer) clearTimeout(section._gcNavAnimTimer);
      section._gcNavAnimTimer = setTimeout(() => {
        section.classList.remove("gc-nav-section--animating");
        section._gcNavAnimTimer = null;
      }, INFRA_NAV_SECTION_ANIM_MS);
    }
    section.classList.toggle("is-expanded", expanded);
    toggle.setAttribute("aria-expanded", expanded ? "true" : "false");
    if (persist) {
      const key = String(section.dataset.navSection || "");
      if (!key) return;
      const state = readNavSectionState(storageKey);
      state[key] = expanded;
      writeNavSectionState(state, storageKey);
    }
  }

  function setNavGroupExpanded(group, expanded, persist) {
    if (!group) return;
    const sidebar = group.closest(".gc-sidebar");
    const storageKey = navStorageKeyForSidebar(sidebar);
    const toggle = group.querySelector(".gc-nav-group-toggle, a.gc-nav-link--has-sub[data-nav-module]");
    const body = group.querySelector(".gc-nav-group-body");
    const key = String(group.dataset.navGroupKey || "");
    if (navGroupExpandedUiMatches(group, expanded, key)) return;
    group.classList.toggle("is-expanded", expanded);
    if (toggle) toggle.setAttribute("aria-expanded", expanded ? "true" : "false");
    if (key === "trading") {
      const sub = document.getElementById("gc-nav-trading-sub");
      if (sub) {
        sub.hidden = !expanded;
        sub.classList.toggle("gc-nav-sub--collapsed", !expanded);
        sub.setAttribute("aria-hidden", expanded ? "false" : "true");
      }
    } else if (body) {
      body.hidden = false;
      body.classList.remove("gc-nav-sub--collapsed");
      body.setAttribute("aria-hidden", "false");
    }
    if (persist && key) {
      const state = readNavSectionState(storageKey);
      state[key] = expanded;
      writeNavSectionState(state, storageKey);
    }
  }

  function syncNavGroupAccordionState(sidebar, state, routeCtx, storageKey) {
    if (!sidebar) return;
    const stored = state || readNavSectionState(storageKey || navStorageKeyForSidebar(sidebar));
    sidebar.querySelectorAll("[data-nav-group-key]").forEach((group) => {
      if (group.hidden) return;
      setNavGroupExpanded(group, resolveNavGroupExpanded(group, stored, routeCtx), false);
    });
  }

  function syncNavSectionAccordionState(sidebar, routeCtx) {
    if (!sidebar) return;
    const storageKey = navStorageKeyForSidebar(sidebar);
    const state = readNavSectionState(storageKey);
    sidebar.querySelectorAll("[data-nav-section]").forEach((section) => {
      if (section.hidden) return;
      const sectionKey = String(section.dataset.navSection || "");
      if (!sidebarAllowsSection(sidebar, sectionKey)) return;
      setNavSectionExpanded(section, resolveNavSectionExpanded(section, state, routeCtx), false);
    });
    syncNavGroupAccordionState(sidebar, state, routeCtx, storageKey);
  }

  function applyDesktopSidebarNav(sidebar, nav) {
    if (!sidebar || !nav) return;
    applyRoleNavTiers(sidebar, nav);
    const fullNav = !!nav.full_nav;
    sidebar.classList.toggle("gc-sidebar--full-nav", fullNav);
    sidebar.classList.toggle("gc-sidebar--role-nav", !fullNav);

    sidebar.querySelectorAll("[data-nav-module]").forEach((el) => {
      const sectionKey = String(el.closest("[data-nav-section]")?.dataset.navSection || "");
      const shouldShow =
        shouldShowSidebarNavLink(nav, el)
        && (!sectionKey || sidebarAllowsSection(sidebar, sectionKey));
      el.hidden = !shouldShow;
    });

    sidebar.querySelectorAll("[data-nav-section]").forEach((section) => {
      const sectionKey = String(section.dataset.navSection || "");
      if (!sidebarAllowsSection(sidebar, sectionKey)) {
        section.hidden = true;
        return;
      }
      if (sectionKey === "community") {
        const links = section.querySelectorAll("[data-nav-module], a.gc-nav-sub-link[href]");
        let anyVisible = false;
        links.forEach((el) => {
          if (!el.hidden) anyVisible = true;
        });
        section.hidden = !anyVisible;
        return;
      }
      const anyVisible = !!section.querySelector("[data-nav-module]:not([hidden]), a.gc-nav-sub-link[href]:not([hidden])");
      section.hidden = !anyVisible;
    });
  }

  function markLeftmenuActiveLinks(url, routeCtx) {
    const ctx = routeCtx || resolveLeftmenuRouteContext(url);
    const path = ctx.path;
    const onBuildings = path.endsWith("/buildings");
    const tradingPage = _tradingPageFromPath(path);

    _clearSidebarNavActive();

    if (onBuildings) {
      const tab = ctx.buildingTab || "resources";
      syncBuildingSidebarTab(tab);
    } else {
      syncBuildingSidebarTab(null);
    }

    if (tradingPage) {
      document.querySelectorAll("[data-trading-nav]").forEach((el) => {
        el.classList.toggle("active", el.dataset.tradingNav === tradingPage);
      });
    }

    if (!onBuildings && !tradingPage) {
      const activeLink = _pickSidebarHrefActive(path);
      if (activeLink) activeLink.classList.add("active");
    } else if (tradingPage) {
      const activeLink = _pickSidebarHrefActive(path);
      if (activeLink) activeLink.classList.add("active");
    }

    document.querySelectorAll(
      ".gc-bottom-nav-item, .gc-nav-drawer-link, a.gc-hud-panel-messages"
    ).forEach((link) => {
      const href = link.getAttribute("href");
      if (!href) return;
      let linkPath;
      try {
        linkPath = new URL(href, window.location.origin).pathname.replace(/\/$/, "") || "/";
      } catch (_) {
        return;
      }
      link.classList.toggle("active", linkPath === path);
    });
  }

  function restoreSidebarMenuState(sidebar, url, routeCtx) {
    if (!sidebar) return;
    const storageKey = navStorageKeyForSidebar(sidebar);
    const state = readNavSectionState(storageKey);
    let mutated = false;

    routeCtx.sections.forEach((key) => {
      if (!sidebarAllowsSection(sidebar, key)) return;
      if (!state[key]) {
        state[key] = true;
        mutated = true;
      }
    });
    routeCtx.groups.forEach((key) => {
      if (!state[key]) {
        state[key] = true;
        mutated = true;
      }
    });
    if (mutated) writeNavSectionState(state, storageKey);

    syncNavSectionAccordionState(sidebar, routeCtx);
  }

  GC.restoreLeftmenuState = function restoreLeftmenuState(url) {
    const targetUrl = url || window.location.href;
    const routeCtx = resolveLeftmenuRouteContext(targetUrl);

    restoreSidebarMenuState(document.getElementById("gc-sidebar-nav"), targetUrl, routeCtx);
    restoreSidebarMenuState(document.getElementById("gc-sidebar-nav-right"), targetUrl, routeCtx);
    restoreSidebarMenuState(document.getElementById("gc-mnav-sidebar-nav"), targetUrl, routeCtx);
    restoreSidebarMenuState(document.getElementById("gc-mnav-sidebar-nav-right"), targetUrl, routeCtx);
    markLeftmenuActiveLinks(targetUrl, routeCtx);
  };

  function applyMobileBottomNav(bottomNav, nav) {
    if (!bottomNav || !nav) return new Set(["overview", "buildings", "research", "messages"]);
    applyRoleNavTiers(bottomNav, nav);
    const fullNav = !!nav.full_nav;
    bottomNav.classList.toggle("gc-bottom-nav--full-nav", fullNav);
    bottomNav.classList.toggle("gc-bottom-nav--role-nav", !fullNav);

    const cfg = window.GC_SIDEBAR_NAV_CONFIG || {};
    const alwaysBottom = Array.isArray(cfg.mobile_always_bottom) ? cfg.mobile_always_bottom : [];
    const slotMax = Math.max(0, MOBILE_BOTTOM_MAX - alwaysBottom.length);
    const prominent = MOBILE_BOTTOM_PRIORITY.filter(
      (key) => !alwaysBottom.includes(key) && navTierForModule(nav, key) === "prominent"
    );
    const visible = fullNav
      ? ["overview", "buildings", "research", "fleet"].slice(0, slotMax)
      : prominent.slice(0, slotMax);
    const visibleSet = new Set([...visible, ...alwaysBottom]);

    bottomNav.querySelectorAll(".gc-bottom-nav-item[data-nav-module]").forEach((el) => {
      const key = String(el.dataset.navModule || "");
      const show = visibleSet.has(key);
      el.hidden = !show;
      el.classList.toggle("gc-nav-bottom-slot", show);
    });

    return visibleSet;
  }

  function syncMobileDrawerSidebars(nav) {
    const drawer = document.getElementById("gc-nav-drawer");
    const drawerLeft = document.getElementById("gc-mnav-sidebar-nav");
    const drawerRight = document.getElementById("gc-mnav-sidebar-nav-right");
    if (drawer && nav) {
      const fullNav = !!nav.full_nav;
      drawer.classList.toggle("gc-nav-drawer--full-nav", fullNav);
      drawer.classList.toggle("gc-nav-drawer--role-nav", !fullNav);
      applyRoleNavTiers(drawer, nav);
    }
    if (drawerLeft) applyDesktopSidebarNav(drawerLeft, nav);
    if (drawerRight) applyDesktopSidebarNav(drawerRight, nav);
  }

  GC.syncRoleBasedSidebar = function syncRoleBasedSidebar(data) {
    const nav = resolveSidebarNavFromState(data);
    if (!nav) return;

    const navSig = JSON.stringify(nav);
    const navChanged = navSig !== GC._lastSidebarNavSig;
    if (navChanged) GC._lastSidebarNavSig = navSig;

    if (!navChanged) {
      markLeftmenuActiveLinks(window.location.href, resolveLeftmenuRouteContext(window.location.href));
      return;
    }

    const sidebar = document.getElementById("gc-sidebar-nav");
    const sidebarRight = document.getElementById("gc-sidebar-nav-right");
    if (sidebar) applyDesktopSidebarNav(sidebar, nav);
    if (sidebarRight) applyDesktopSidebarNav(sidebarRight, nav);

    const bottomNav = document.getElementById("gc-bottom-nav");
    const drawer = document.getElementById("gc-nav-drawer");
    if (bottomNav || drawer) {
      const bottomModules = bottomNav
        ? applyMobileBottomNav(bottomNav, nav)
        : new Set();
      if (drawer) syncMobileDrawerSidebars(nav);
    }

    GC.restoreLeftmenuState(window.location.href);
  };

  function initRoleBasedSidebar() {
    if (GC._roleBasedSidebarBound) return;
    GC._roleBasedSidebarBound = true;

    initSidebarSectionAccordion();
    initBottomUtilityBar();

    if (GC.lastState && GC.lastState.ok !== false) {
      GC.syncRoleBasedSidebar(GC.lastState);
    } else {
      GC.restoreLeftmenuState(window.location.href);
    }
  }

  function initSidebarSectionAccordion() {
    if (GC._sidebarSectionAccordionBound) return;
    GC._sidebarSectionAccordionBound = true;

    document.addEventListener("click", (e) => {
      const groupToggle = e.target.closest(".gc-nav-group-toggle, #gc-nav-trading-parent");
      let sidebar = groupToggle?.closest(".gc-sidebar-desktop, .gc-sidebar-mobile-drawer");
      if (groupToggle && sidebar) {
        e.preventDefault();
        const group = groupToggle.closest("[data-nav-group-key]");
        if (!group || group.hidden) return;
        setNavGroupExpanded(group, !group.classList.contains("is-expanded"), true);
        return;
      }

      const toggle = e.target.closest(".gc-nav-section-toggle");
      sidebar = toggle?.closest(".gc-sidebar-desktop, .gc-sidebar-mobile-drawer");
      if (!toggle || !sidebar) {
        return;
      }
      e.preventDefault();
      const section = toggle.closest("[data-nav-section]");
      if (!section || section.hidden) return;
      setNavSectionExpanded(section, !section.classList.contains("is-expanded"), true);
    });

    GC.restoreLeftmenuState(window.location.href);
  }

  function initSidebarRightDrawer() {
    const toggle = document.getElementById("gc-sidebar-right-toggle");
    const sidebar = document.getElementById("gc-sidebar-right-stack")
      || document.getElementById("gc-sidebar-nav-right");
    if (!toggle || !sidebar || GC._sidebarRightDrawerBound) return;
    GC._sidebarRightDrawerBound = true;

    toggle.addEventListener("click", () => {
      const open = sidebar.classList.toggle("is-drawer-open");
      toggle.setAttribute("aria-expanded", open ? "true" : "false");
    });

    document.addEventListener("click", (e) => {
      if (!sidebar.classList.contains("is-drawer-open")) return;
      if (sidebar.contains(e.target) || toggle.contains(e.target)) return;
      sidebar.classList.remove("is-drawer-open");
      toggle.setAttribute("aria-expanded", "false");
    });

    GC.registerCleanup(() => {
      sidebar.classList.remove("is-drawer-open");
      toggle.setAttribute("aria-expanded", "false");
    });
  }

  function initBottomUtilityBar() {
    if (GC._bottomUtilityBarBound) return;
    GC._bottomUtilityBarBound = true;

    document.addEventListener("click", (e) => {
      const btn = e.target.closest(".gc-bottom-utility-bar [data-special-open-window]");
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      const target = btn.dataset.specialOpenWindow || "";
      if (!target) return;
      if (typeof GC.openSpecialWindow === "function") {
        GC.openSpecialWindow(target);
      }
    }, true);

    initSidebarRightDrawer();

    const bar = document.querySelector(".gc-bottom-utility-bar");
    if (bar && typeof ResizeObserver !== "undefined") {
      const syncBottomUtilHeight = () => {
        const h = Math.ceil(bar.getBoundingClientRect().height);
        document.documentElement.style.setProperty("--gc-bottom-util-h", `${h}px`);
        if (typeof GC.syncSidebarSticky === "function") GC.syncSidebarSticky();
      };
      syncBottomUtilHeight();
      const ro = new ResizeObserver(syncBottomUtilHeight);
      ro.observe(bar);
      GC.registerCleanup(() => ro.disconnect());
    }
  }

  GC.updatePlanetRegistryFromState = function updatePlanetRegistryFromState(data) {
    if (!data) return;

    const activeId = Number(
      data.active_planet_id || data.active_planet?.planet_id || 0
    );

    let planets = Array.isArray(data.planets) && data.planets.length ? data.planets : null;
    if (
      !planets
      && GC.lastState
      && Array.isArray(GC.lastState.planets)
      && GC.lastState.planets.length
    ) {
      planets = GC.lastState.planets;
    }

    if (planets && planets.length) {
      if (activeId > 0) {
        planets = planets.map((p) => ({
          ...p,
          is_active: Number(p.planet_id) === activeId,
        }));
      }
      rebuildPlanetRegistry(planets);
      return;
    }

    if (!activeId) return;
    planetRegistryRoots().forEach((root) => {
      root.dataset.activePlanetId = String(activeId);
      root.querySelectorAll(".gc-planet-registry-card").forEach((btn) => {
        const pid = Number(btn.dataset.planetId || 0);
        const on = pid === activeId;
        btn.classList.toggle("is-active", on);
        btn.setAttribute("aria-current", on ? "true" : "false");
      });
    });
  };

  function rebuildLanguageSelectMenu(select) {
    if (!select || !select._gcHudSelect) return;
    const { menu } = select._gcHudSelect;
    if (!menu) return;
    menu.innerHTML = "";
    Array.from(select.options).forEach((opt) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "gc-hud-select-item gc-lang-select-item";
      btn.dataset.value = opt.value;
      btn.setAttribute("role", "option");
      const label = opt.dataset.langLabel || opt.textContent.trim();
      const flag = opt.dataset.langFlag || opt.textContent.trim();
      btn.setAttribute("aria-label", label);
      btn.title = label;
      btn.textContent = flag;
      if (opt.disabled) btn.disabled = true;
      menu.appendChild(btn);
    });
    syncHudSelect(select);
  }

  function initLanguageSwitcher() {
    const root = document.getElementById("gc-language-switcher");
    const select = document.getElementById("gc-language-select");
    if (!root || !select || root.dataset.gcBound === "1") return;
    root.dataset.gcBound = "1";

    if (select.dataset.gcHudSelectEnhanced !== "1") {
      enhanceHudSelect(select);
    }
    rebuildLanguageSelectMenu(select);

    const apiUrl = root.dataset.api || "/api/locale";
    let busy = false;

    select.addEventListener("change", async () => {
      const prev = String(root.dataset.locale || "de").trim().toLowerCase();
      const loc = String(select.value || "").trim().toLowerCase();
      if (!loc || loc === prev || busy) {
        select.value = prev;
        syncHudSelect(select);
        return;
      }

      busy = true;
      root.classList.add("is-busy");
      select.disabled = true;
      const trigger = select._gcHudSelect && select._gcHudSelect.trigger;
      const wrap = select._gcHudSelect && select._gcHudSelect.wrap;
      if (trigger) trigger.disabled = true;
      try {
        const data = await GC.fetchGameAction(apiUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ locale: loc }),
        });
        if (!data || data.ok !== true) {
          console.warn("[GC] locale switch rejected", data && data.error);
          select.value = prev;
          syncHudSelect(select);
          return;
        }
        if (typeof GC.reloadCurrentPage === "function") {
          await GC.reloadCurrentPage({ force: true, fullDocument: true });
        } else {
          window.location.reload();
        }
        return;
      } catch (err) {
        console.error("[GC] locale switch failed", err);
        select.value = prev;
        syncHudSelect(select);
      } finally {
        busy = false;
        root.classList.remove("is-busy");
        select.disabled = false;
        if (trigger) trigger.disabled = false;
        if (wrap) closeHudSelectWrap(wrap);
      }
    });
  }

  function initPlanetRegistry() {
    if (GC._planetRegistryBound) return;
    GC._planetRegistryBound = true;

    // GC-PERF-PLANET-SWITCH: PJAX reload replaces registry roots (dropping is-busy).
    // Localhost switches finish so fast that a double/triple-click (or delayed
    // ghost click after DOM replace) starts another full switch+reload cycle.
    // Keep a short post-unlock cooldown so one intentional click = one switch.
    const PLANET_SWITCH_COOLDOWN_MS = 700;

    document.addEventListener("click", async (e) => {
      if (e.target.closest("a.gc-galaxy-coord-link")) return;
      const item = e.target.closest(".gc-planet-registry-card");
      if (!item) return;
      const root = item.closest("[data-gc-planet-registry]");
      if (!root) return;
      if (item.classList.contains("is-active")) return;

      const planetId = parseInt(item.dataset.planetId || "0", 10);
      if (!planetId) return;

      const now = Date.now();
      if (
        GC._planetSwitchInFlight
        || root.classList.contains("is-busy")
        || now < Number(GC._planetSwitchCooldownUntil || 0)
      ) {
        console.debug("[GC] planet_switch ignored", {
          planetId,
          inFlight: !!GC._planetSwitchInFlight,
          busy: root.classList.contains("is-busy"),
          cooldownMs: Math.max(0, Number(GC._planetSwitchCooldownUntil || 0) - now),
        });
        return;
      }

      e.preventDefault();
      GC._planetSwitchInFlight = true;
      console.debug("[GC] planet_switch start", planetId);
      if (typeof GC.closePlanetRegistrySheet === "function") {
        GC.closePlanetRegistrySheet();
      }
      planetRegistryRoots().forEach((r) => r.classList.add("is-busy"));
      item.disabled = true;
      let shellUnlocked = false;
      const releaseBusy = () => {
        planetRegistryRoots().forEach((r) => {
          r.classList.remove("is-busy");
          r.querySelectorAll(".gc-planet-registry-card").forEach((btn) => {
            btn.disabled = false;
          });
        });
      };
      // GC-PERF-PLANET-SWITCH-002: unlock Imperium/shell before long SSR reload.
      // Holding inFlight across reloadCurrentPage (up to PJAX 25s) made the rail
      // and follow-up nav feel dead after Admin→game under SQLite pressure.
      const unlockShellEarly = (reason) => {
        if (shellUnlocked) return;
        shellUnlocked = true;
        if (typeof GC.setSafeTimeout === "function") {
          const idx = GC.pageLifecycle.timeouts.indexOf(busyGuard);
          if (idx >= 0) GC.pageLifecycle.timeouts.splice(idx, 1);
        }
        clearTimeout(busyGuard);
        releaseBusy();
        GC._planetSwitchCooldownUntil = Date.now() + PLANET_SWITCH_COOLDOWN_MS;
        GC._planetSwitchInFlight = false;
        if (typeof GC.releaseShellNavigationBlockers === "function") {
          GC.releaseShellNavigationBlockers(reason || "planet_switch");
        }
      };
      const busyGuard = typeof GC.setSafeTimeout === "function"
        ? GC.setSafeTimeout(() => unlockShellEarly("planet_switch_watchdog"), 12000)
        : setTimeout(() => unlockShellEarly("planet_switch_watchdog"), 12000);

      try {
        const res = await GC.fetchGameAction("/api/planets/active", {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
          body: JSON.stringify({ planet_id: planetId }),
        });
        if (res?.ok) {
          const anyActive = applyActionState(res, "planet_switch");
          const name = item.dataset.planetName || "";
          ["research-planet-label"].forEach((id) => {
            const el = document.getElementById(id);
            if (!el || !name) return;
            el.textContent = name;
          });
          // Align page scope before SSR reload so soft-nav/polls see the new planet.
          syncScopedPlanetIds(planetId);
          const pageName =
            typeof GC.detectPage === "function" ? GC.detectPage() : "";
          const onAdmin = pageName === "admin";
          // GC-PERF-PLANET-SWITCH-004: progression pages soft-patch (no PJAX HTML tear-down).
          // Full SSR after Bauleiste enqueue made switches look stuck/stuttery.
          const PLANET_SWITCH_SKIP_SSR = new Set([
            "admin",
            "fleet",
            "messages",
            "alliance",
            "ranking",
            "options",
            "buildings",
            "research",
            "shipyard",
            "defense",
            "overview",
            "planet_evolution",
            "trader_hub",
            "logistics",
          ]);
          const PLANET_SWITCH_SOFT_PANEL = new Set([
            "buildings",
            "research",
            "shipyard",
            "defense",
            "overview",
            "planet_evolution",
            "trader_hub",
            "logistics",
          ]);
          const skipSsr = PLANET_SWITCH_SKIP_SSR.has(pageName);
          // Unlock before SSR/soft refresh so Imperium + sidebar stay clickable.
          unlockShellEarly("planet_switch_pre_reload");
          // Skip mid-flight registry rebuild when SSR reload replaces the rail anyway
          // (avoids pointer target shifting under a still-settling click).
          if (onAdmin || skipSsr) {
            if (Array.isArray(res.planets)) {
              updatePlanetRegistryFromPlanets(res.planets);
            } else if (res.state) {
              GC.updatePlanetRegistryFromState(res.state);
            }
          } else {
            await GC.reloadCurrentPage({
              force: true,
              skipHydrate: true,
              skipGameState: true,
              skipPolling: true,
            });
          }
          ensurePlanetLandscapeAfterSoftNav();
          syncScopedPlanetIds(planetId);
          bootstrapResourceLiveFromDom();
          bootstrapHeaderBoostersFromDom();
          _bootstrapPageQueueCompactLiveFromDom();
          if (typeof GC.releaseShellNavigationBlockers === "function") {
            GC.releaseShellNavigationBlockers("planet_switch");
          }
          // Soft panel reconcile for buildings/research/… (planet-gated include_panel).
          if (
            !onAdmin
            && PLANET_SWITCH_SOFT_PANEL.has(pageName)
            && typeof GC.forceCanonicalGameStateRefresh === "function"
          ) {
            _lastQueueSignature = "";
            _lastResearchQueueSignature = "";
            _lastShipyardQueueSignature = "";
            _lastDefenseQueueSignature = "";
            await GC.forceCanonicalGameStateRefresh("planet_switch_panel", {
              planetId,
              forceResourceBar: true,
            });
          }
          // GC-FLEET-PLANET-SWITCH-001: soft fleet refresh with explicit planet gate
          // (fleet stays in PLANET_SWITCH_SKIP_SSR to keep mission/coords draft).
          const fleetPage = document.getElementById("fleet-page");
          if (
            !onAdmin
            && pageName === "fleet"
            && fleetPage
            && fleetPage.dataset.ready === "1"
            && typeof GC.refreshFleetState === "function"
          ) {
            await GC.refreshFleetState(fleetPage, {
              planetId,
              reason: "planet_switch",
              force: true,
            });
          }
          if (!onAdmin) {
            GC.startPolling(anyActive || hasBusyLiveActivity());
            GC.startProgressTicker();
          }
        } else {
          showNotify(planetSwitchReasonText(res?.reason), "error");
        }
      } catch (err) {
        if (!err?.authRedirect) {
          showNotify(t("pe_error_generic", "Aktion fehlgeschlagen."), "error");
        }
      } finally {
        unlockShellEarly("planet_switch_finally");
      }
    });
  }

  function bindPlanetEvolutionOnce() {
    if (GC._peActionsBound) return;
    GC._peActionsBound = true;

    const tt = (key, fallback) => t(key, fallback);
    const PE_REASON_ALIASES = {
      requirements: "research_locked",
    };
    const reasonText = (reason) => {
      if (!reason) return tt("pe_error_generic", "Aktion fehlgeschlagen.");
      const key = PE_REASON_ALIASES[reason] || reason;
      const pe = tt(`pe_reason_${key}`, "");
      if (pe && pe !== `pe_reason_${key}`) return pe;
      const alt = tt(`reason_${key}`, "");
      if (alt && alt !== `reason_${key}`) return alt;
      return reason;
    };

    const postAction = async (url, body) => {
      if (typeof GC.fetchGameAction === "function") {
        return GC.fetchGameAction(url, {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
          body: JSON.stringify(body || {}),
        });
      }
      return GC.fetchJSON(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest" },
        body: JSON.stringify(body || {}),
      });
    };

    /** GC-CLEAN-002 — always patch state first; soft content only for structural PE SSR. */
    const finalizePeMutationSuccess = async (res, reason, { softContent = false } = {}) => {
      if (res?.state && typeof applyActionState === "function") {
        applyActionState(res, reason);
      } else if (typeof GC.refreshGameState === "function") {
        await GC.refreshGameState(reason);
      }
      if (softContent) await _softReloadPlanetEvolutionContent();
    };

    const peMutationFailed = (btn, res) => {
      if (btn) btn.disabled = false;
      showNotify(reasonText(res?.reason), "error");
    };

    const scrollTargets = {
      events: "pe-section-events",
      research: "pe-section-research",
      specialization: "pe-section-specialization",
      economy: "pe-section-economy",
      progression: "pe-section-progression",
      traits: "pe-section-traits",
      policies: "pe-section-policies",
      action: "pe-section-action",
    };

    const tabPanels = { events: "events", research: "research", policies: "policies", history: "history" };

    const peHighlightEl = (el) => {
      if (!el) return;
      el.classList.remove("pe-highlight-pulse");
      void el.offsetWidth;
      el.classList.add("pe-highlight-pulse");
      window.setTimeout(() => el.classList.remove("pe-highlight-pulse"), 2600);
    };

    const openPeExpansionDrawer = (open) => {
      const drawer = document.getElementById("pe-expansion-drawer");
      if (!drawer) return false;
      const isOpen = Boolean(open);
      drawer.hidden = !isOpen;
      drawer.classList.toggle("is-open", isOpen);
      document.querySelectorAll(".pe-expansion-drawer-toggle").forEach((el) => {
        el.setAttribute("aria-expanded", isOpen ? "true" : "false");
        el.classList.toggle("is-open", isOpen);
      });
      return true;
    };

    const togglePeExpansionDrawer = () => {
      const drawer = document.getElementById("pe-expansion-drawer");
      if (!drawer) return;
      openPeExpansionDrawer(drawer.hidden);
    };

    let peChronicleModalOpen = false;
    let peChronicleLastFocus = null;

    const formatPeChronicleTs = (ts) => {
      const n = Number(ts || 0);
      if (!n) return "—";
      try {
        return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(n * 1000));
      } catch (_) {
        return "—";
      }
    };

    const hydratePeChronicleDates = (rootEl) => {
      rootEl?.querySelectorAll(".pe-chronicle-timeline-date[data-ts]").forEach((el) => {
        el.textContent = formatPeChronicleTs(el.dataset.ts);
      });
    };

    const closePeChronicleModal = () => {
      const modal = document.getElementById("pe-chronicle-modal");
      if (!modal || modal.hidden) return;
      modal.hidden = true;
      modal.setAttribute("aria-hidden", "true");
      modal.classList.remove("is-open");
      document.body.classList.remove("gc-player-card-open");
      document.querySelectorAll(".pe-hero-chronicle-btn").forEach((btn) => {
        btn.setAttribute("aria-expanded", "false");
      });
      peChronicleModalOpen = false;
      if (peChronicleLastFocus && typeof peChronicleLastFocus.focus === "function") {
        peChronicleLastFocus.focus();
      }
      peChronicleLastFocus = null;
    };

    const openPeChronicleModal = (trigger) => {
      const modal = document.getElementById("pe-chronicle-modal");
      if (!modal) return;
      peChronicleLastFocus = trigger || document.activeElement;
      hydratePeChronicleDates(modal);
      modal.hidden = false;
      modal.setAttribute("aria-hidden", "false");
      modal.classList.add("is-open");
      document.body.classList.add("gc-player-card-open");
      document.querySelectorAll(".pe-hero-chronicle-btn").forEach((btn) => {
        btn.setAttribute("aria-expanded", "true");
      });
      peChronicleModalOpen = true;
      modal.querySelector("[data-pe-chronicle-close].gc-player-card-close")?.focus();
    };

    GC.closePeChronicleModal = closePeChronicleModal;

    let peInfoPopover = null;
    let peInfoActiveTrigger = null;
    let peInfoBackdrop = null;

    const peInfoIsMobile = () => window.matchMedia("(max-width: 640px)").matches;

    const setPeInfoExpanded = (expanded) => {
      if (peInfoActiveTrigger) {
        peInfoActiveTrigger.setAttribute("aria-expanded", expanded ? "true" : "false");
      }
    };

    const bindPeInfoPopoverSurface = (pop) => {
      const stopInside = (e) => e.stopPropagation();
      pop.addEventListener("click", stopInside);
      pop.addEventListener("mousedown", stopInside);
      pop.addEventListener("wheel", stopInside, { passive: true });
      pop.addEventListener("touchstart", stopInside, { passive: true });
    };

    const closePeInfoPopover = () => {
      if (peInfoBackdrop) {
        peInfoBackdrop.remove();
        peInfoBackdrop = null;
      }
      if (peInfoPopover) {
        peInfoPopover.remove();
        peInfoPopover = null;
      }
      setPeInfoExpanded(false);
      peInfoActiveTrigger = null;
    };

    const positionPeInfoPopover = (pop, trigger) => {
      const margin = 8;
      pop.style.visibility = "hidden";
      pop.style.display = "block";
      const rect = trigger.getBoundingClientRect();
      const popRect = pop.getBoundingClientRect();
      let left = rect.left + rect.width / 2 - popRect.width / 2;
      left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
      let top = rect.bottom + margin;
      if (top + popRect.height > window.innerHeight - margin) {
        top = Math.max(margin, rect.top - popRect.height - margin);
      }
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
      pop.style.right = "";
      pop.style.bottom = "";
      pop.style.visibility = "visible";
    };

    const openPeInfoPopover = (trigger) => {
      const page = document.querySelector(".planet-evolution-page");
      if (!page || !trigger || !page.contains(trigger)) return;
      const sourceId = trigger.getAttribute("aria-controls");
      const source = sourceId ? document.getElementById(sourceId) : null;
      if (!source) return;
      if (peInfoActiveTrigger === trigger && peInfoPopover) {
        closePeInfoPopover();
        return;
      }
      closePeInfoPopover();
      const mobile = peInfoIsMobile();
      if (mobile) {
        peInfoBackdrop = document.createElement("div");
        peInfoBackdrop.className = "pe-info-popover-backdrop";
        peInfoBackdrop.addEventListener("click", (e) => {
          e.stopPropagation();
          closePeInfoPopover();
        });
        document.body.appendChild(peInfoBackdrop);
      }
      const pop = document.createElement("div");
      pop.className = "pe-info-popover gc-popover-layer";
      if (mobile) pop.classList.add("pe-info-popover--sheet");
      pop.setAttribute("role", "dialog");
      pop.setAttribute("aria-modal", mobile ? "true" : "false");
      pop.setAttribute("tabindex", "-1");
      pop.innerHTML = source.innerHTML;
      bindPeInfoPopoverSurface(pop);
      document.body.appendChild(pop);
      if (!mobile) positionPeInfoPopover(pop, trigger);
      peInfoPopover = pop;
      peInfoActiveTrigger = trigger;
      trigger.setAttribute("aria-expanded", "true");
      pop.focus({ preventScroll: true });
    };

    const onPeInfoOutsideScroll = (e) => {
      if (!peInfoPopover) return;
      const target = e.target;
      if (target instanceof Node && peInfoPopover.contains(target)) return;
      if (peInfoActiveTrigger instanceof Node && peInfoActiveTrigger.contains(target)) return;
      closePeInfoPopover();
    };

    const onPeInfoResize = () => {
      if (!peInfoPopover || !peInfoActiveTrigger) return;
      const mobile = peInfoIsMobile();
      if (mobile) {
        if (!peInfoBackdrop) {
          peInfoBackdrop = document.createElement("div");
          peInfoBackdrop.className = "pe-info-popover-backdrop";
          peInfoBackdrop.addEventListener("click", (ev) => {
            ev.stopPropagation();
            closePeInfoPopover();
          });
          document.body.appendChild(peInfoBackdrop);
        }
        peInfoPopover.classList.add("pe-info-popover--sheet");
        peInfoPopover.setAttribute("aria-modal", "true");
        peInfoPopover.style.left = "";
        peInfoPopover.style.top = "";
      } else {
        if (peInfoBackdrop) {
          peInfoBackdrop.remove();
          peInfoBackdrop = null;
        }
        peInfoPopover.classList.remove("pe-info-popover--sheet");
        peInfoPopover.setAttribute("aria-modal", "false");
        positionPeInfoPopover(peInfoPopover, peInfoActiveTrigger);
      }
    };

    GC.closePeInfoPopover = closePeInfoPopover;

    let peHelpModalOpen = false;
    let peHelpLastFocus = null;

    const closePeHelpModal = () => {
      const modal = document.getElementById("pe-help-modal");
      if (!modal || modal.hidden) return;
      modal.hidden = true;
      modal.setAttribute("aria-hidden", "true");
      modal.classList.remove("is-open");
      document.body.classList.remove("gc-player-card-open");
      document.querySelectorAll(".pe-hero-help-btn").forEach((btn) => {
        btn.setAttribute("aria-expanded", "false");
      });
      peHelpModalOpen = false;
      if (peHelpLastFocus && typeof peHelpLastFocus.focus === "function") peHelpLastFocus.focus();
      peHelpLastFocus = null;
    };

    const openPeHelpModal = (trigger) => {
      const modal = document.getElementById("pe-help-modal");
      if (!modal) return;
      closePeInfoPopover();
      peHelpLastFocus = trigger || document.activeElement;
      modal.hidden = false;
      modal.setAttribute("aria-hidden", "false");
      modal.classList.add("is-open");
      document.body.classList.add("gc-player-card-open");
      document.querySelectorAll(".pe-hero-help-btn").forEach((btn) => {
        btn.setAttribute("aria-expanded", "true");
      });
      peHelpModalOpen = true;
      modal.querySelector("[data-pe-help-close].gc-player-card-close")?.focus();
    };

    GC.closePeHelpModal = closePeHelpModal;

    let pePendingChoiceBtn = null;

    const closePeChoiceConfirmModal = () => {
      const modal = document.getElementById("pe-choice-confirm-modal");
      if (!modal || modal.hidden) return;
      modal.hidden = true;
      modal.setAttribute("aria-hidden", "true");
      modal.classList.remove("is-open");
      document.body.classList.remove("gc-player-card-open");
      pePendingChoiceBtn = null;
    };

    const openPeChoiceConfirmModal = (choiceBtn) => {
      const modal = document.getElementById("pe-choice-confirm-modal");
      if (!modal || !choiceBtn) return;
      closePeInfoPopover();
      pePendingChoiceBtn = choiceBtn;
      const labelEl = modal.querySelector("#pe-choice-confirm-label");
      const effectEl = modal.querySelector("#pe-choice-confirm-effect");
      if (labelEl) labelEl.textContent = String(choiceBtn.dataset.choiceLabel || "").trim();
      if (effectEl) effectEl.textContent = String(choiceBtn.dataset.choiceEffect || "").trim();
      modal.hidden = false;
      modal.setAttribute("aria-hidden", "false");
      modal.classList.add("is-open");
      document.body.classList.add("gc-player-card-open");
      modal.querySelector("#pe-choice-confirm-submit")?.focus();
    };

    GC.closePeChoiceConfirmModal = closePeChoiceConfirmModal;

    const submitPeChoiceConfirm = async () => {
      const choiceBtn = pePendingChoiceBtn;
      if (!choiceBtn) return;
      const submitBtn = document.getElementById("pe-choice-confirm-submit");
      if (submitBtn) submitBtn.disabled = true;
      choiceBtn.disabled = true;
      const planetId = parseInt(choiceBtn.dataset.planetId || "0", 10);
      let res;
      try {
        res = await postAction(`/api/planets/${planetId}/research/choose`, {
          choice_group: choiceBtn.dataset.choiceGroup,
          choice_key: choiceBtn.dataset.choiceKey,
        });
        if (res?.ok) {
          closePeChoiceConfirmModal();
          await finalizePeMutationSuccess(res, "pe_research_choose", { softContent: true });
        } else {
          peMutationFailed(choiceBtn, res);
        }
      } finally {
        if (submitBtn) submitBtn.disabled = false;
        if (!res?.ok) closePeChoiceConfirmModal();
      }
    };

    const openPeSection = (sectionId) => {
      if (sectionId === "pe-section-history") {
        openPeChronicleModal(document.getElementById("pe-section-history"));
        return;
      }
      const section = document.getElementById(sectionId);
      if (section && section.tagName === "DETAILS") section.open = true;
      if (sectionId === "pe-section-expansion-gate" || sectionId === "pe-section-establishment") {
        openPeExpansionDrawer(true);
      }
    };

    const focusPeTarget = (root, { action, target, highlight, techKey, href }) => {
      const actionType = action || "focus_section";
      const navHref = String(href || "").trim();
      if (actionType === "navigate") {
        if (navHref && typeof GC.navigateTo === "function") {
          GC.navigateTo(navHref, { push: true });
          return;
        }
        const routes = {
          research: "/research",
          fleet: "/fleet",
          galaxy: "/galaxy?view=system",
          command_map: "/galaxy?view=command_map&dev=1",
        };
        const routeHref = routes[String(target || "").trim()];
        if (routeHref && typeof GC.navigateTo === "function") {
          GC.navigateTo(routeHref, { push: true });
          return;
        }
      }
      const sectionId = scrollTargets[target] || `pe-section-${target}`;
      const needsTab = actionType === "focus_tab" || Boolean(tabPanels[target]);
      if (needsTab && tabPanels[target]) {
        const tab = root.querySelector(`.pe-sec-tab[data-panel="${tabPanels[target]}"]`);
        if (tab) tab.click();
        else openPeSection(sectionId);
      } else if (sectionId) {
        openPeSection(sectionId);
      }

      let el = null;
      const highlightId = highlight || sectionId;
      if (highlightId) el = document.getElementById(highlightId);
      if (!el && techKey) {
        el = root.querySelector(`#pe-research-card-${techKey}, [data-tech-key="${techKey}"]`);
      }
      if (!el) el = document.getElementById(scrollTargets[target] || `pe-section-${target}`);

      if (el) {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        peHighlightEl(el);
      }
    };

    document.addEventListener("click", async (e) => {
      const root = document.querySelector(".planet-evolution-page");
      if (!root) return;

      const actionBtn = e.target.closest(".pe-action-btn");
      if (actionBtn && root.contains(actionBtn)) {
        focusPeTarget(root, {
          action: actionBtn.dataset.ctaAction,
          target: actionBtn.dataset.ctaTarget,
          highlight: actionBtn.dataset.ctaHighlight,
          techKey: actionBtn.dataset.techKey,
          href: actionBtn.dataset.ctaHref,
        });
        return;
      }

      const colonizeWorldBtn = e.target.closest(".pe-colonize-world-btn");
      if (colonizeWorldBtn && root.contains(colonizeWorldBtn)) {
        const colonizeHref = String(colonizeWorldBtn.dataset.ctaHref || "").trim()
          || "/galaxy?view=system";
        if (typeof GC.navigateTo === "function") {
          GC.navigateTo(colonizeHref, { push: true });
        }
        return;
      }

      const expansionToggle = e.target.closest(".pe-expansion-drawer-toggle");
      if (expansionToggle && root.contains(expansionToggle)) {
        e.preventDefault();
        togglePeExpansionDrawer();
        return;
      }

      const chronicleBtn = e.target.closest(".pe-hero-chronicle-btn");
      if (chronicleBtn && root.contains(chronicleBtn)) {
        e.preventDefault();
        openPeChronicleModal(chronicleBtn);
        return;
      }

      const helpBtn = e.target.closest(".pe-hero-help-btn");
      if (helpBtn && root.contains(helpBtn)) {
        e.preventDefault();
        openPeHelpModal(helpBtn);
        return;
      }

      const helpClose = e.target.closest("[data-pe-help-close]");
      if (helpClose && document.getElementById("pe-help-modal")?.contains(helpClose)) {
        e.preventDefault();
        closePeHelpModal();
        return;
      }

      const infoTrigger = e.target.closest(".pe-info-trigger");
      if (infoTrigger && root.contains(infoTrigger)) {
        e.preventDefault();
        e.stopPropagation();
        openPeInfoPopover(infoTrigger);
        return;
      }

      if (peInfoPopover
        && !e.target.closest(".pe-info-popover")
        && !e.target.closest(".pe-info-trigger")
        && !e.target.closest(".pe-info-popover-backdrop")) {
        closePeInfoPopover();
      }

      const choiceConfirmSubmit = e.target.closest("#pe-choice-confirm-submit");
      if (choiceConfirmSubmit) {
        e.preventDefault();
        await submitPeChoiceConfirm();
        return;
      }

      const choiceConfirmCancel = e.target.closest("[data-pe-choice-confirm-cancel]");
      if (choiceConfirmCancel) {
        e.preventDefault();
        closePeChoiceConfirmModal();
        return;
      }

      const chronicleClose = e.target.closest("[data-pe-chronicle-close]");
      if (chronicleClose && document.getElementById("pe-chronicle-modal")?.contains(chronicleClose)) {
        e.preventDefault();
        closePeChronicleModal();
        return;
      }

      const scrollBtn = e.target.closest(".pe-scroll-btn");
      if (scrollBtn && root.contains(scrollBtn)) {
        focusPeTarget(root, { target: scrollBtn.dataset.scroll });
        return;
      }

      const tab = e.target.closest(".pe-sec-tab");
      if (tab && root.contains(tab)) {
        const name = tab.dataset.panel;
        root.querySelectorAll(".pe-sec-tab").forEach((tEl) => tEl.classList.toggle("is-active", tEl === tab));
        root.querySelectorAll(".pe-sec-panel").forEach((panel) => {
          const active = panel.dataset.panel === name;
          panel.classList.toggle("is-active", active);
          panel.hidden = !active;
        });
        return;
      }

      const researchBtn = e.target.closest(".pe-research-btn");
      if (researchBtn && root.contains(researchBtn)) {
        if (researchBtn.disabled || researchBtn.getAttribute("aria-disabled") === "true") return;
        researchBtn.disabled = true;
        const planetId = parseInt(researchBtn.dataset.planetId || "0", 10);
        const techKey = researchBtn.dataset.techKey || "";
        const requestId = (typeof crypto !== "undefined" && crypto.randomUUID) ? crypto.randomUUID() : String(Date.now());
        let res;
        try {
          res = await postAction(`/api/planets/${planetId}/research/start`, { tech_key: techKey, request_id: requestId });
          if (res?.ok) await finalizePeMutationSuccess(res, "planet_research_start", { softContent: false });
          else peMutationFailed(researchBtn, res);
        } finally {
          if (!res?.ok) researchBtn.disabled = false;
        }
        return;
      }

      const choiceBtn = e.target.closest(".pe-choice-btn");
      if (choiceBtn && root.contains(choiceBtn)) {
        e.preventDefault();
        openPeChoiceConfirmModal(choiceBtn);
        return;
      }

      const specBtn = e.target.closest(".pe-spec-btn");
      if (specBtn && root.contains(specBtn)) {
        if (!confirm(tt("pe_confirm_spec", "Die Spezialisierung ist permanent."))) return;
        const picker = root.querySelector("#pe-spec-picker");
        if (!picker) return;
        specBtn.disabled = true;
        const planetId = parseInt(picker.dataset.planetId || "0", 10);
        const res = await postAction(`/api/planets/${planetId}/specialization/pick`, { spec_key: specBtn.dataset.specKey });
        if (res?.ok) await finalizePeMutationSuccess(res, "pe_spec_pick", { softContent: true });
        else peMutationFailed(specBtn, res);
        return;
      }

      const specUpgradeBtn = e.target.closest(".pe-spec-upgrade-btn");
      if (specUpgradeBtn && root.contains(specUpgradeBtn)) {
        specUpgradeBtn.disabled = true;
        const planetId = parseInt(specUpgradeBtn.dataset.planetId || "0", 10);
        const res = await postAction(`/api/planets/${planetId}/specialization/upgrade`, {});
        if (res?.ok) await finalizePeMutationSuccess(res, "pe_spec_upgrade", { softContent: true });
        else peMutationFailed(specUpgradeBtn, res);
        return;
      }

      const policyBtn = e.target.closest(".pe-policy-btn");
      if (policyBtn && root.contains(policyBtn)) {
        if (!confirm(tt("pe_confirm_policy", "Politik in diesem Slot aktivieren?"))) return;
        policyBtn.disabled = true;
        const planetId = parseInt(policyBtn.dataset.planetId || "0", 10);
        const slot = parseInt(policyBtn.dataset.slot || "0", 10);
        const res = await postAction(`/api/planets/${planetId}/policies/activate`, {
          slot,
          policy_key: policyBtn.dataset.policyKey,
        });
        if (res?.ok) await finalizePeMutationSuccess(res, "pe_policy_activate", { softContent: true });
        else peMutationFailed(policyBtn, res);
        return;
      }

      const eventChoiceBtn = e.target.closest(".pe-event-choice-btn");
      const eventRoot = root.querySelector("#pe-event-choices");
      if (eventChoiceBtn && eventRoot && root.contains(eventChoiceBtn)) {
        eventChoiceBtn.disabled = true;
        const planetId = parseInt(eventRoot.dataset.planetId || "0", 10);
        const eventId = parseInt(eventRoot.dataset.eventId || "0", 10);
        const res = await postAction(`/api/planets/${planetId}/events/resolve`, {
          event_id: eventId,
          choice_key: eventChoiceBtn.dataset.choiceKey,
        });
        if (res?.ok) await finalizePeMutationSuccess(res, "pe_event_resolve", { softContent: true });
        else peMutationFailed(eventChoiceBtn, res);
        return;
      }

    });

    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape") return;
      if (peChronicleModalOpen) closePeChronicleModal();
      else if (peHelpModalOpen) closePeHelpModal();
      else if (document.getElementById("pe-choice-confirm-modal") && !document.getElementById("pe-choice-confirm-modal").hidden) {
        closePeChoiceConfirmModal();
      } else if (peInfoPopover) closePeInfoPopover();
    });
    window.addEventListener("resize", onPeInfoResize);
    window.addEventListener("scroll", onPeInfoOutsideScroll, true);
  }

  function normalizePopoverTriggers(root = document) {
    const scope = root && root.querySelectorAll ? root : document;
    scope.querySelectorAll(".gc-popover-trigger[title]").forEach((el) => {
      el.removeAttribute("title");
    });
  }

  function initGcPopoversOnce() {
    if (GC._popoverBound) return;
    GC._popoverBound = true;

    let activePopover = null;
    let activeTrigger = null;

    const closePopover = () => {
      if (activePopover) {
        activePopover.remove();
        activePopover = null;
      }
      if (activeTrigger) {
        activeTrigger.setAttribute("aria-expanded", "false");
        activeTrigger = null;
      }
    };

    const positionPopover = (pop, trigger) => {
      const rect = trigger.getBoundingClientRect();
      const margin = 8;
      pop.style.visibility = "hidden";
      pop.style.display = "block";
      const popRect = pop.getBoundingClientRect();
      let left = rect.left + rect.width / 2 - popRect.width / 2;
      left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
      let top = rect.bottom + margin;
      if (top + popRect.height > window.innerHeight - margin) {
        top = Math.max(margin, rect.top - popRect.height - margin);
      }
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
      pop.style.visibility = "visible";
    };

    const openPopover = (trigger) => {
      const text = (trigger.dataset.popover || "").trim();
      if (!text) return;
      closePopover();

      const pop = document.createElement("div");
      pop.className = "gc-popover";
      pop.setAttribute("role", "tooltip");
      pop.textContent = text;
      document.body.appendChild(pop);
      positionPopover(pop, trigger);

      activePopover = pop;
      activeTrigger = trigger;
      trigger.setAttribute("aria-expanded", "true");
    };

    document.addEventListener("click", (e) => {
      const trigger = e.target.closest(".gc-popover-trigger");
      if (trigger) {
        e.preventDefault();
        e.stopPropagation();
        if (activeTrigger === trigger) closePopover();
        else openPopover(trigger);
        return;
      }
      if (!e.target.closest(".gc-popover")) closePopover();
    });

    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        closePopover();
        return;
      }
      if (e.key !== "Enter" && e.key !== " ") return;
      const trigger = e.target.closest(".gc-popover-trigger");
      if (!trigger) return;
      e.preventDefault();
      if (activeTrigger === trigger) closePopover();
      else openPopover(trigger);
    });

    window.addEventListener("resize", closePopover);
    window.addEventListener("scroll", closePopover, true);

    normalizePopoverTriggers();
  }

  function initCardRequirementsHoverOnce() {
    if (GC._reqHoverBound) return;
    GC._reqHoverBound = true;

    let activeTrigger = null;

    const hideReqTooltip = () => {
      const tip = document.getElementById("gc-req-hover-tooltip");
      if (tip) {
        tip.hidden = true;
        tip.style.display = "none";
        tip.style.visibility = "hidden";
        tip.innerHTML = "";
      }
      if (activeTrigger) {
        activeTrigger.removeAttribute("aria-describedby");
        activeTrigger = null;
      }
    };

    const ensureReqTooltipEl = () => {
      let tip = document.getElementById("gc-req-hover-tooltip");
      if (!tip) {
        tip = document.createElement("div");
        tip.id = "gc-req-hover-tooltip";
        tip.className = "gc-req-hover-tooltip";
        tip.hidden = true;
        tip.setAttribute("role", "tooltip");
        document.body.appendChild(tip);
      }
      return tip;
    };

    const positionReqTooltip = (tip, trigger) => {
      const rect = trigger.getBoundingClientRect();
      const margin = 8;
      tip.style.visibility = "hidden";
      tip.hidden = false;
      tip.style.display = "block";
      const popRect = tip.getBoundingClientRect();
      let left = rect.left + rect.width / 2 - popRect.width / 2;
      left = Math.max(margin, Math.min(left, window.innerWidth - popRect.width - margin));
      let top = rect.bottom + margin;
      if (top + popRect.height > window.innerHeight - margin) {
        top = Math.max(margin, rect.top - popRect.height - margin);
      }
      tip.style.left = `${left}px`;
      tip.style.top = `${top}px`;
      tip.style.visibility = "visible";
    };

    const showReqTooltip = (trigger) => {
      if (!trigger || !trigger.isConnected) return;
      const raw = trigger.getAttribute("data-req-items");
      if (!raw) return;
      let items;
      try {
        items = JSON.parse(raw);
      } catch (_err) {
        return;
      }
      const html = buildCardReqTooltipHtml(items);
      if (!html) return;
      if (activeTrigger && activeTrigger !== trigger) {
        activeTrigger.removeAttribute("aria-describedby");
      }
      const tip = ensureReqTooltipEl();
      tip.innerHTML = html;
      positionReqTooltip(tip, trigger);
      activeTrigger = trigger;
      trigger.setAttribute("aria-describedby", "gc-req-hover-tooltip");
    };

    const syncReqTooltipHover = (e) => {
      const trigger = e.target.closest(".gc-req-hover-trigger");
      if (trigger) {
        if (trigger !== activeTrigger) showReqTooltip(trigger);
        return;
      }
      if (activeTrigger) hideReqTooltip();
    };

    document.addEventListener("mouseover", syncReqTooltipHover, true);
    document.addEventListener("focusin", (e) => {
      const trigger = e.target.closest(".gc-req-hover-trigger");
      if (trigger) showReqTooltip(trigger);
    });
    document.addEventListener("focusout", (e) => {
      const trigger = e.target.closest(".gc-req-hover-trigger");
      if (trigger && !trigger.contains(e.relatedTarget)) hideReqTooltip();
    });
    document.addEventListener("pointerdown", hideReqTooltip, true);

    window.addEventListener("resize", hideReqTooltip);
    window.addEventListener("scroll", hideReqTooltip, true);
    window.addEventListener("blur", hideReqTooltip);

    GC.hideCardReqTooltip = hideReqTooltip;
    GC.registerCleanup(hideReqTooltip);
  }

